class ControlError(RuntimeError):
    """The schema-5 control plane cannot safely perform the requested transition."""


class ImmutablePinError(ControlError):
    """An immutable release, run, environment, model, or fleet pin drifted."""


class ReadinessError(ControlError):
    """Production cannot resume because at least one readiness gate is not valid."""


class SchedulerAmbiguity(ControlError):
    """Scheduler truth cannot be mapped to one unique durable intent."""


class SchedulerVisibilityPending(ControlError):
    """A recently submitted exact intent is still inside scheduler visibility grace."""


class FinalizerRetryableError(ControlError):
    """A typed infrastructure failure eligible for a bounded finalizer retry."""


class FinalizerSchedulerReadError(FinalizerRetryableError):
    """Scheduler truth could not be read completely and unambiguously."""


class FinalizerSubmissionError(FinalizerRetryableError):
    """One exact finalizer sbatch submission failed."""


class FinalizerNodeError(FinalizerRetryableError):
    """The finalizer's execution node failed transiently."""


class FinalizerConnectionError(FinalizerRetryableError):
    """A required infrastructure connection failed transiently."""


class FinalizerTimeoutError(FinalizerRetryableError):
    """A bounded finalizer operation exceeded its deadline."""


class FinalizerInterruptedError(FinalizerRetryableError):
    """USR1 or TERM requested a resumable finalizer drain."""


class FinalizerDeterministicError(ControlError):
    """A final artifact, provenance, or invariant failure requires intervention."""


class FinalizerSemanticError(FinalizerDeterministicError):
    """Final semantic acceptance or provenance is invalid."""


class FinalizerCacheError(FinalizerDeterministicError):
    """The primary final analysis cache is incomplete or drifted."""


class FinalizerSnapshotError(FinalizerDeterministicError):
    """The marker-last final snapshot is incomplete or drifted."""


class FinalizerProvenanceError(FinalizerDeterministicError):
    """Finalization provenance differs from frozen authority."""


class FinalizerInvariantError(FinalizerDeterministicError):
    """A durable finalization invariant is violated."""


class FinalizerRetryLimitError(FinalizerInvariantError):
    """The durable finalizer retry budget is exhausted."""


class ControllerFenced(ControlError):
    """A controller job does not own the exact durable role generation."""


@dataclass(frozen=True)
class _SnapshotLeaseRefreshTask:
    """One local asynchronous renewal; the cross-node lock remains authoritative."""

    future: Future[dict[str, Any]]
    thread: threading.Thread


@dataclass(frozen=True)
class _RuntimeLeaseRefreshTask:
    """One local asynchronous renewal; the cross-node lock remains authoritative."""

    future: Future[dict[str, Any]]
    thread: threading.Thread


@dataclass(frozen=True)
class SchedulerJob:
    job_id: str
    job_name: str
    state: str
    comment: str = ""
    command: str = ""
    source: str = "squeue"
    dependency: str = ""
    partition: str = ""
    qos: str = ""

    @property
    def active(self) -> bool:
        return normalize_scheduler_state(self.state) in ACTIVE_SCHEDULER_STATES

    @property
    def token(self) -> str | None:
        return self.comment if self.comment.startswith(TOKEN_PREFIX + ";") else None


@dataclass(frozen=True)
class SchedulerSnapshot:
    jobs: tuple[SchedulerJob, ...]
    captured_at: float
    squeue_ok: bool = True
    sacct_ok: bool = True
    errors: tuple[str, ...] = ()
    # Exact lower bound represented by this successful sacct query.  ``None``
    # means absence cannot prove that an earlier submission was never accepted.
    accounting_start_timestamp: float | None = None

    @property
    def active_job_ids(self) -> set[str]:
        return {job.job_id for job in self.jobs if job.active}


def canonical_json(value: Any) -> bytes:
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False
    ).encode("utf-8")


def sha256_value(value: Any) -> str:
    return hashlib.sha256(canonical_json(value)).hexdigest()


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()


def sha256_tree(root: Path) -> str:
    """Hash an immutable release tree, excluding only VCS and runtime cache metadata."""
    root = root.expanduser().resolve()
    if not root.is_dir():
        raise ImmutablePinError(f"cannot hash missing release tree: {root}")
    ignored_names = {".git", ".pytest_cache", "__pycache__"}
    paths = sorted(
        (
            path
            for path in root.rglob("*")
            if not any(part in ignored_names for part in path.relative_to(root).parts)
            and path.suffix != ".pyc"
            and (path.is_file() or path.is_symlink())
        ),
        key=lambda path: path.relative_to(root).as_posix(),
    )
    digest = hashlib.sha256()
    for path in paths:
        relative = path.relative_to(root).as_posix().encode("utf-8")
        digest.update(len(relative).to_bytes(8, "big"))
        digest.update(relative)
        if path.is_symlink():
            payload = ("SYMLINK\0" + os.readlink(path)).encode("utf-8")
        else:
            payload = path.read_bytes()
        digest.update(len(payload).to_bytes(8, "big"))
        digest.update(payload)
    return digest.hexdigest()


def utc_timestamp(now: float | None = None) -> str:
    value = time.time() if now is None else float(now)
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(value))


def normalize_scheduler_state(value: str) -> str:
    # sacct may report values such as CANCELLED+ or FAILED by 0:0.
    return value.strip().upper().split()[0].rstrip("+")


def job_token(role: str, generation: int, intent_token: str) -> str:
    _validate_role(role)
    if generation < 1:
        raise ValueError("controller generation must be positive")
    if not intent_token or any(char in intent_token for char in ";|\n\r"):
        raise ValueError("intent token must be non-empty and scheduler-safe")
    return f"{TOKEN_PREFIX};role={role};generation={generation};intent={intent_token}"


def drill_job_token(
    drill_id: str, role: str, generation: int, intent_token: str
) -> str:
    """Return a scheduler-searchable token outside the production token namespace."""

    _validate_role(role)
    if generation < 1:
        raise ValueError("drill generation must be positive")
    for label, value in (("drill_id", drill_id), ("intent_token", intent_token)):
        if not value or any(char in value for char in ";|\n\r"):
            raise ValueError(f"{label} must be non-empty and scheduler-safe")
    return (
        f"{DRILL_TOKEN_PREFIX};drill={drill_id};role={role};"
        f"generation={generation};intent={intent_token}"
    )


def parse_drill_job_token(value: str) -> dict[str, str] | None:
    if not value.startswith(DRILL_TOKEN_PREFIX + ";"):
        return None
    fields: dict[str, str] = {}
    for item in value.split(";")[1:]:
        if "=" not in item:
            return None
        key, field_value = item.split("=", 1)
        if not key or not field_value or key in fields:
            return None
        fields[key] = field_value
    if set(fields) != {"drill", "role", "generation", "intent"}:
        return None
    if fields["role"] not in ROLE_NAMES:
        return None
    try:
        if int(fields["generation"]) < 1:
            return None
    except ValueError:
        return None
    return fields


def parse_job_token(value: str) -> dict[str, str] | None:
    if not value.startswith(TOKEN_PREFIX + ";"):
        return None
    fields: dict[str, str] = {}
    for item in value.split(";")[1:]:
        if "=" not in item:
            return None
        key, field_value = item.split("=", 1)
        if not key or not field_value or key in fields:
            return None
        fields[key] = field_value
    if set(fields) != {"role", "generation", "intent"}:
        return None
    if fields["role"] not in ROLE_NAMES:
        return None
    try:
        if int(fields["generation"]) < 1:
            return None
    except ValueError:
        return None
    return fields


def _controller_job_name(name: str) -> bool:
    """Return whether ``name`` occupies the schema-5 controller namespace."""

    return name in LEGACY_CONTROLLER_JOB_NAMES or name.startswith(
        CONTROLLER_JOB_NAME_PREFIXES
    )


def _rendered_controller_job_name(
    role: str, generation: int, intent_token: str
) -> str:
    """Return the one production job name bound by a durable controller record."""

    _validate_role(role)
    if (
        not isinstance(generation, int)
        or isinstance(generation, bool)
        or generation < 1
    ):
        raise SchedulerAmbiguity(
            f"controller {role} record has an invalid generation"
        )
    if (
        not isinstance(intent_token, str)
        or not intent_token
        or any(char in intent_token for char in ";|\n\r")
    ):
        raise SchedulerAmbiguity(
            f"controller {role} record has an invalid intent token"
        )
    return (
        f"asys-s5-{ROLE_SHORT[role]}-g{generation:06d}-"
        f"{intent_token[:8]}"
    )


def _validate_role(role: str) -> None:
    if role not in ROLE_NAMES:
        raise ControlError(f"unknown controller role {role!r}; expected {ROLE_NAMES}")


def shared_controller_primitive_contract() -> dict[str, str]:
    """Return the exact production primitives exercised by isolated drill jobs."""

    return {
        "fencing": SHARED_CONTROLLER_FENCING_PRIMITIVE,
        "submission": SHARED_CONTROLLER_SUBMISSION_PRIMITIVE,
        "singleton": SHARED_CONTROLLER_SINGLETON_PRIMITIVE,
    }


def _state_path(state_dir: Path) -> Path:
    return state_dir / CONTROL_FILENAME


def _atomic_write_json(path: Path, value: Mapping[str, Any]) -> None:
    io.atomic_write_text(
        path,
        json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n",
    )


def _atomic_publish_readonly_bytes(path: Path, payload: bytes) -> None:
    """Publish immutable bytes without ever replacing an existing winner.

    Publication is a small marker-last transaction:

    * a uniquely named, payload-bound inode is created and directory-fsynced;
    * its complete bytes and final read-only mode are fsynced;
    * ``link(2)`` installs the destination with no-clobber semantics; and
    * the owned temporary link is removed and the directory is fsynced again.

    A directory advisory lock serializes publishers on the shared filesystem.  On
    replay, this function adopts a complete owned inode, removes only incomplete
    inodes in the exact payload namespace, and rejects malformed or conflicting
    namespace entries.  Consequently a process death at any write/link/fsync
    boundary cannot overwrite an immutable winner or leave an unrecoverable
    read-only partial file.
    """

    path = Path(os.path.abspath(os.fspath(path.expanduser())))
    path.parent.mkdir(parents=True, exist_ok=True)
    payload_sha256 = hashlib.sha256(payload).hexdigest()
    namespace_prefix = f".{path.name}.publish."
    owned_pattern = re.compile(
        rf"^{re.escape(namespace_prefix)}"
        rf"(?P<sha256>[0-9a-f]{{64}})\.(?P<owner>[0-9a-f]{{32}})\.tmp$"
    )
    directory_flags = (
        os.O_RDONLY
        | getattr(os, "O_DIRECTORY", 0)
        | getattr(os, "O_CLOEXEC", 0)
    )
    directory_descriptor = os.open(path.parent, directory_flags)

    def _read_regular_nofollow(
        candidate: Path, *, allowed_links: set[int]
    ) -> tuple[bytes, os.stat_result]:
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(candidate, flags)
        try:
            before = os.fstat(descriptor)
            blocks: list[bytes] = []
            while block := os.read(descriptor, 1024 * 1024):
                blocks.append(block)
            after = os.fstat(descriptor)
        finally:
            os.close(descriptor)
        identity = lambda item: (  # noqa: E731
            item.st_dev,
            item.st_ino,
            item.st_mode,
            item.st_nlink,
            item.st_size,
            item.st_mtime_ns,
            item.st_ctime_ns,
        )
        current = candidate.stat(follow_symlinks=False)
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_nlink not in allowed_links
            or stat.S_IMODE(before.st_mode) & 0o222
            or identity(before) != identity(after)
            or identity(current) != identity(after)
        ):
            raise ImmutablePinError(
                f"immutable publication inode is unsafe or changed: {candidate}"
            )
        return b"".join(blocks), current

    def _validate_destination(*, allowed_links: set[int]) -> os.stat_result:
        if path.is_symlink() or not path.is_file():
            raise ImmutablePinError(
                f"immutable publication destination is unsafe: {path}"
            )
        observed, metadata = _read_regular_nofollow(
            path, allowed_links=allowed_links
        )
        if observed != payload:
            raise ImmutablePinError(
                f"immutable publication destination already has different bytes: {path}"
            )
        return metadata

    try:
        fcntl.flock(directory_descriptor, fcntl.LOCK_EX)
        entries: list[tuple[Path, re.Match[str]]] = []
        for candidate in path.parent.iterdir():
            if not candidate.name.startswith(namespace_prefix):
                continue
            match = owned_pattern.fullmatch(candidate.name)
            if match is None:
                raise ImmutablePinError(
                    "foreign immutable-publication namespace entry exists: "
                    f"{candidate}"
                )
            if match.group("sha256") != payload_sha256:
                if candidate.is_symlink():
                    raise ImmutablePinError(
                        "conflicting immutable-publication entry is a symlink: "
                        f"{candidate}"
                    )
                metadata = candidate.stat(follow_symlinks=False)
                if (
                    stat.S_ISREG(metadata.st_mode)
                    and metadata.st_nlink == 1
                    and stat.S_IMODE(metadata.st_mode) & 0o222
                ):
                    # A writable inode cannot be a completed publication.  With the
                    # directory lock held it is an abandoned preimage from a process
                    # that died before sealing; remove it even if replay now computes
                    # a different marker payload from successor-stable state.
                    candidate.unlink()
                    os.fsync(directory_descriptor)
                    continue
                raise ImmutablePinError(
                    "conflicting immutable-publication payload exists: "
                    f"{candidate}"
                )
            if candidate.is_symlink():
                raise ImmutablePinError(
                    f"owned immutable-publication entry is a symlink: {candidate}"
                )
            entries.append((candidate, match))

        destination_exists = path.exists() or path.is_symlink()
        if destination_exists:
            destination_metadata = _validate_destination(
                allowed_links={1, 2}
            )
            for candidate, _match in entries:
                try:
                    candidate_metadata = candidate.stat(follow_symlinks=False)
                except FileNotFoundError:
                    continue
                if (
                    stat.S_ISREG(candidate_metadata.st_mode)
                    and candidate_metadata.st_dev == destination_metadata.st_dev
                    and candidate_metadata.st_ino == destination_metadata.st_ino
                ):
                    candidate.unlink()
                    os.fsync(directory_descriptor)
                    continue
                # With the directory lock held, every other same-payload inode is a
                # stale pre-link attempt.  Remove it only after proving its exact
                # owned name and regular one-link identity.
                if (
                    not stat.S_ISREG(candidate_metadata.st_mode)
                    or candidate_metadata.st_nlink != 1
                ):
                    raise ImmutablePinError(
                        "owned immutable-publication entry has unsafe identity: "
                        f"{candidate}"
                    )
                if not stat.S_IMODE(candidate_metadata.st_mode) & 0o222:
                    observed, _metadata = _read_regular_nofollow(
                        candidate, allowed_links={1}
                    )
                    if observed != payload:
                        raise ImmutablePinError(
                            "sealed immutable-publication preimage is corrupt: "
                            f"{candidate}"
                        )
                candidate.unlink()
                os.fsync(directory_descriptor)
            _validate_destination(allowed_links={1})
            return

        # Recover a complete, sealed pre-link inode if one survived a process death.
        recovered = False
        for candidate, _match in entries:
            metadata = candidate.stat(follow_symlinks=False)
            if (
                not stat.S_ISREG(metadata.st_mode)
                or metadata.st_nlink != 1
            ):
                raise ImmutablePinError(
                    f"owned immutable-publication entry has unsafe identity: {candidate}"
                )
            if stat.S_IMODE(metadata.st_mode) & 0o222:
                candidate.unlink()
                os.fsync(directory_descriptor)
                continue
            observed, _metadata = _read_regular_nofollow(
                candidate, allowed_links={1}
            )
            if observed != payload:
                # A sealed inode in the correct hash namespace with different
                # bytes is evidence of corruption, never an incomplete write.
                raise ImmutablePinError(
                    f"sealed immutable-publication preimage is corrupt: {candidate}"
                )
            if recovered:
                candidate.unlink()
                os.fsync(directory_descriptor)
                continue
            try:
                os.link(candidate, path, follow_symlinks=False)
            except FileExistsError:
                _validate_destination(allowed_links={1, 2})
            os.fsync(directory_descriptor)
            candidate.unlink()
            os.fsync(directory_descriptor)
            recovered = True

        if recovered:
            _validate_destination(allowed_links={1})
            return

        temporary = path.parent / (
            f"{namespace_prefix}{payload_sha256}.{uuid.uuid4().hex}.tmp"
        )
        flags = (
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0)
        )
        if hasattr(os, "O_NOFOLLOW"):
            flags |= os.O_NOFOLLOW
        descriptor = os.open(temporary, flags, 0o600)
        try:
            created = os.fstat(descriptor)
            if not stat.S_ISREG(created.st_mode) or created.st_nlink != 1:
                raise ImmutablePinError(
                    f"new immutable-publication inode is unsafe: {temporary}"
                )
            os.fsync(directory_descriptor)
            remaining = memoryview(payload)
            while remaining:
                written = os.write(descriptor, remaining)
                if written <= 0:
                    raise OSError(
                        "short write while publishing immutable artifact"
                    )
                remaining = remaining[written:]
            os.fsync(descriptor)
            os.fchmod(descriptor, 0o444)
            os.fsync(descriptor)
        finally:
            os.close(descriptor)

        try:
            os.link(temporary, path, follow_symlinks=False)
            os.fsync(directory_descriptor)
        finally:
            # Ordinary Python exceptions (including a lost filesystem reply after
            # the link committed) can close the two-link window immediately.  A
            # real SIGKILL skips this block; the owned-name replay above then removes
            # the surviving link before any caller accepts the destination.
            try:
                temporary.unlink()
            except FileNotFoundError:
                pass
            os.fsync(directory_descriptor)
        _validate_destination(allowed_links={1})
    finally:
        try:
            fcntl.flock(directory_descriptor, fcntl.LOCK_UN)
        finally:
            os.close(directory_descriptor)


def _atomic_publish_readonly_text(path: Path, payload: str) -> None:
    _atomic_publish_readonly_bytes(path, payload.encode("utf-8"))


def _atomic_publish_readonly_json(
    path: Path, value: Mapping[str, Any]
) -> None:
    _atomic_publish_readonly_text(
        path,
        json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n",
    )


@contextmanager
def _file_lock(path: Path, *, nonblocking: bool = False) -> Iterator[None]:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o644)
    try:
        flags = fcntl.LOCK_EX | (fcntl.LOCK_NB if nonblocking else 0)
        try:
            fcntl.flock(fd, flags)
        except BlockingIOError as exc:
            raise ControlError(
                f"cross-node singleton lock is already held: {path}"
            ) from exc
        os.ftruncate(fd, 0)
        os.write(
            fd,
            (
                f"host={socket.gethostname()} pid={os.getpid()} "
                f"started_at={time.time():.6f}\n"
            ).encode("utf-8"),
        )
        os.fsync(fd)
        yield
    finally:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        finally:
            os.close(fd)


@contextmanager
def control_lock(state_dir: Path) -> Iterator[None]:
    with _file_lock(state_dir / "locks" / "control.lock"):
        yield


@contextmanager
def role_singleton_lock(state_dir: Path, role: str) -> Iterator[None]:
    _validate_role(role)
    with _file_lock(state_dir / "locks" / f"{role}.lock", nonblocking=True):
        yield


@contextmanager
def admission_boundary_lock(state_dir: Path) -> Iterator[None]:
    """Serialize the final cell ``sbatch`` boundary with ``pause --drain``.

    The dispatcher performs a fresh desired-state check while owning this lock.  Pause
    owns the same lock before its fresh squeue snapshot, so no array can be admitted in
    the otherwise-unobservable interval between snapshot and drain intent publication.
    """

    with _file_lock(state_dir / "locks" / "admission-boundary.lock"):
        yield


@contextmanager
def capacity_transition_lock(state_dir: Path) -> Iterator[None]:
    """Serialize the multi-stage capacity-generation transaction."""

    with _file_lock(
        state_dir / "locks" / "capacity-transition.lock", nonblocking=True
    ):
        yield


@contextmanager
def finalizer_lock(state_dir: Path) -> Iterator[None]:
    """Prevent concurrent final snapshots or completion publications."""

    with _file_lock(state_dir / "locks" / "finalizer.lock", nonblocking=True):
        yield


def _append_jsonl(path: Path, record: Mapping[str, Any]) -> None:
    io.append_jsonl(path, dict(record))


def _read_jsonl_locked(path: Path, *, missing_ok: bool = False) -> list[dict[str, Any]]:
    try:
        fd = os.open(path, os.O_RDONLY)
    except FileNotFoundError:
        if missing_ok:
            return []
        raise
    try:
        fcntl.flock(fd, fcntl.LOCK_SH)
        with os.fdopen(os.dup(fd), "r", encoding="utf-8") as handle:
            records = [json.loads(line) for line in handle if line.strip()]
    finally:
        try:
            fcntl.flock(fd, fcntl.LOCK_UN)
        finally:
            os.close(fd)
    if not all(isinstance(record, dict) for record in records):
        raise ControlError(f"JSONL journal contains a non-object record: {path}")
    return records


def _history_record(
    control: Mapping[str, Any],
    *,
    event: str,
    details: Mapping[str, Any] | None,
    now: float,
) -> dict[str, Any]:
    history = list(control.get("transition_history", []))
    previous_hash = history[-1]["hash"] if history else None
    payload: dict[str, Any] = {
        "sequence": len(history) + 1,
        "at": utc_timestamp(now),
        "timestamp": now,
        "event": event,
        "details": copy.deepcopy(dict(details or {})),
        "previous_hash": previous_hash,
    }
    payload["hash"] = sha256_value(payload)
    return payload


def append_transition(
    state_dir: Path,
    control: MutableMapping[str, Any],
    *,
    event: str,
    details: Mapping[str, Any] | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    timestamp = time.time() if now is None else float(now)
    durable_history = _read_jsonl_locked(
        state_dir / TRANSITION_JOURNAL, missing_ok=True
    )
    in_memory_history = list(control.get("transition_history", []))
    if durable_history[: len(in_memory_history)] != in_memory_history:
        raise ControlError("transition journal diverged from in-memory control history")
    if len(durable_history) > len(in_memory_history):
        # A process can die after the journal append but before control.json replacement.
        # Preserve that sealed event and continue its hash chain.  The state mutation is
        # still applied idempotently by the retrying operator command.
        control["transition_history"] = copy.deepcopy(durable_history)
        validate_transition_history(control)
    record = _history_record(control, event=event, details=details, now=timestamp)
    control.setdefault("transition_history", []).append(record)
    # The separately fsynced journal makes the append-only audit trail recoverable even
    # if a future operator accidentally replaces control.json with an older copy.
    _append_jsonl(state_dir / TRANSITION_JOURNAL, record)
    return record


def validate_transition_history(control: Mapping[str, Any]) -> None:
    previous_hash: str | None = None
    history = control.get("transition_history")
    if not isinstance(history, list) or not history:
        raise ControlError("control transition history is absent")
    for expected_sequence, record in enumerate(history, start=1):
        if not isinstance(record, dict):
            raise ControlError("control transition history contains a non-object")
        candidate = dict(record)
        claimed_hash = candidate.pop("hash", None)
        if candidate.get("sequence") != expected_sequence:
            raise ControlError("control transition history sequence is not contiguous")
        if candidate.get("previous_hash") != previous_hash:
            raise ControlError("control transition history hash chain is broken")
        if claimed_hash != sha256_value(candidate):
            raise ControlError("control transition history record hash is invalid")
        previous_hash = claimed_hash


def _validate_admission(admission: Mapping[str, Any]) -> None:
    fixed = {
        "qos_limit": 448,
        "reserve": 64,
        "maximum_cell_tasks": PRODUCTION_DESIGN_CELL_CAP,
        "max_batch": 24,
        "cell_cpus": 1,
        "cell_memory": "4G",
        "effective_cell_time": "12:00:00",
        "signal": "B:USR1@1200",
        "no_requeue": True,
    }
    for key, expected in fixed.items():
        if admission.get(key) != expected:
            raise ImmutablePinError(
                f"unsafe schema-5 admission setting {key}: "
                f"expected {expected!r}, found {admission.get(key)!r}"
            )
    ceiling = admission.get("current_ceiling")
    if not isinstance(ceiling, int) or ceiling not in ADMISSION_RAMP_STAGES:
        raise ImmutablePinError(
            "current admission ceiling must be one of the closed staged values "
            f"{ADMISSION_RAMP_STAGES}; stages above "
            f"{PRODUCTION_NONPREEMPTIBLE_CELL_CAP} additionally require a sealed "
            "client-capacity generation"
        )


def _new_admission_safety_hold(*, configured_ceiling: int) -> dict[str, Any]:
    return {
        "schema_version": ADMISSION_SAFETY_HOLD_SCHEMA_VERSION,
        "protocol": ADMISSION_SAFETY_HOLD_PROTOCOL,
        "active": False,
        "mode": None,
        "reasons": [],
        "configured_ceiling": int(configured_ceiling),
        "consecutive_clean_polls": 0,
        "semantic_clean_after_activation": False,
        "activation_id": None,
        "activated_at": None,
        "activated_timestamp": None,
        "updated_at": None,
        "updated_timestamp": None,
        "acknowledged_at": None,
        "acknowledged_timestamp": None,
        "history": [],
    }


def _validate_admission_safety_hold(
    control: Mapping[str, Any], hold: Any
) -> None:
    if not isinstance(hold, dict):
        raise ControlError("schema-5 admission safety hold is missing")
    required = {
        "schema_version",
        "protocol",
        "active",
        "mode",
        "reasons",
        "configured_ceiling",
        "consecutive_clean_polls",
        "semantic_clean_after_activation",
        "activation_id",
        "activated_at",
        "activated_timestamp",
        "updated_at",
        "updated_timestamp",
        "acknowledged_at",
        "acknowledged_timestamp",
        "history",
    }
    if set(hold) != required:
        raise ControlError("schema-5 admission safety hold fields are invalid")
    if (
        hold.get("schema_version") != ADMISSION_SAFETY_HOLD_SCHEMA_VERSION
        or hold.get("protocol") != ADMISSION_SAFETY_HOLD_PROTOCOL
        or not isinstance(hold.get("active"), bool)
        or hold.get("configured_ceiling") not in ADMISSION_RAMP_STAGES
        or hold.get("configured_ceiling")
        != control.get("admission", {}).get("current_ceiling")
        or not isinstance(hold.get("reasons"), list)
        or not all(
            isinstance(item, str) and item for item in hold.get("reasons", [])
        )
        or len(set(hold.get("reasons", []))) != len(hold.get("reasons", []))
        or not isinstance(hold.get("consecutive_clean_polls"), int)
        or isinstance(hold.get("consecutive_clean_polls"), bool)
        or hold.get("consecutive_clean_polls", -1) < 0
        or not isinstance(hold.get("semantic_clean_after_activation"), bool)
        or not isinstance(hold.get("history"), list)
    ):
        raise ControlError("schema-5 admission safety hold is malformed")
    for field in (
        "activated_timestamp",
        "updated_timestamp",
        "acknowledged_timestamp",
    ):
        value = hold.get(field)
        if value is not None and (
            not isinstance(value, (int, float)) or isinstance(value, bool)
        ):
            raise ControlError(f"admission safety hold {field} is invalid")
    if hold["active"]:
        if (
            hold.get("mode") not in {"transient", "integrity", "operator"}
            or not hold["reasons"]
            or hold.get("activated_timestamp") is None
            or re.fullmatch(
                r"[0-9a-f]{32}", str(hold.get("activation_id", ""))
            )
            is None
        ):
            raise ControlError("active admission safety hold lacks its durable cause")
    elif (
        hold.get("mode") is not None
        or hold["reasons"]
        or hold.get("activation_id") is not None
    ):
        raise ControlError("inactive admission safety hold retains active causes")
    for record in hold["history"]:
        if (
            not isinstance(record, dict)
            or record.get("event") not in {"activated", "updated", "cleared"}
            or not isinstance(record.get("timestamp"), (int, float))
            or not isinstance(record.get("reasons"), list)
        ):
            raise ControlError("admission safety hold history is invalid")


def _validate_safety_hold_drain_intent(value: Any) -> None:
    """Validate the latest crash-recoverable critical-hold cell-drain intent."""

    if value is None:
        return
    required = {
        "protocol",
        "drain_id",
        "rollout_generation",
        "hold_activation_id",
        "hold_activated_timestamp",
        "hold_reasons",
        "state",
        "created_at",
        "created_timestamp",
        "updated_at",
        "updated_timestamp",
        "attempt_count",
        "snapshot_captured_timestamp",
        "snapshot_sha256",
        "targets",
        "results",
        "last_error",
        "completed_at",
        "completed_timestamp",
    }
    if not isinstance(value, dict) or set(value) != required:
        raise ControlError("schema-5 safety-hold drain intent fields are invalid")
    if (
        value.get("protocol") != SAFETY_HOLD_DRAIN_PROTOCOL
        or not isinstance(value.get("drain_id"), str)
        or not value["drain_id"]
        or not isinstance(value.get("rollout_generation"), int)
        or isinstance(value.get("rollout_generation"), bool)
        or value["rollout_generation"] < 0
        or re.fullmatch(
            r"[0-9a-f]{32}", str(value.get("hold_activation_id", ""))
        )
        is None
        or not isinstance(value.get("hold_activated_timestamp"), (int, float))
        or isinstance(value.get("hold_activated_timestamp"), bool)
        or not isinstance(value.get("hold_reasons"), list)
        or not value["hold_reasons"]
        or not all(isinstance(item, str) and item for item in value["hold_reasons"])
        or len(set(value["hold_reasons"])) != len(value["hold_reasons"])
        or value.get("state")
        not in {"reconciling", "signaling", "failed", "complete"}
        or not isinstance(value.get("attempt_count"), int)
        or isinstance(value.get("attempt_count"), bool)
        or value["attempt_count"] < 1
        or not isinstance(value.get("targets"), dict)
        or not isinstance(value.get("results"), dict)
    ):
        raise ControlError("schema-5 safety-hold drain intent is malformed")
    for field in (
        "created_timestamp",
        "updated_timestamp",
        "snapshot_captured_timestamp",
        "completed_timestamp",
    ):
        item = value.get(field)
        if item is not None and (
            not isinstance(item, (int, float)) or isinstance(item, bool)
        ):
            raise ControlError(f"safety-hold drain {field} is invalid")
    snapshot_sha = value.get("snapshot_sha256")
    if snapshot_sha is not None and _SHA256_RE.fullmatch(str(snapshot_sha)) is None:
        raise ControlError("safety-hold drain snapshot digest is invalid")
    for action_key, target in value["targets"].items():
        if (
            not isinstance(action_key, str)
            or not isinstance(target, dict)
            or set(target) != {"category", "job_id", "command"}
            or target.get("category")
            not in {"cell_usr1", "pending_cell_cancel"}
            or _EXACT_CELL_TASK_ID.fullmatch(str(target.get("job_id", ""))) is None
            or action_key
            != f"{target['category']}:{target['job_id']}"
            or not isinstance(target.get("command"), list)
            or not all(isinstance(part, str) and part for part in target["command"])
        ):
            raise ControlError("safety-hold drain target is invalid")
    if not set(value["results"]).issubset(value["targets"]):
        raise ControlError("safety-hold drain result has no durable target")
    for action_key, result in value["results"].items():
        target = value["targets"][action_key]
        if (
            not isinstance(result, dict)
            or set(result)
            != {
                "category",
                "job_id",
                "command",
                "returncode",
                "accepted",
                "evidence",
                "stderr",
                "completed_at",
                "completed_timestamp",
            }
            or result.get("category") != target["category"]
            or result.get("job_id") != target["job_id"]
            or result.get("command") != target["command"]
            or not isinstance(result.get("accepted"), bool)
            or result.get("evidence")
            not in {
                "scheduler_command_returncode_zero",
                "scheduler_target_no_longer_live",
                "scheduler_target_state_transitioned",
                "scheduler_command_failed",
            }
            or not isinstance(result.get("stderr"), str)
            or not isinstance(result.get("completed_timestamp"), (int, float))
            or isinstance(result.get("completed_timestamp"), bool)
        ):
            raise ControlError("safety-hold drain result is invalid")
        returncode = result.get("returncode")
        if returncode is not None and (
            not isinstance(returncode, int) or isinstance(returncode, bool)
        ):
            raise ControlError("safety-hold drain return code is invalid")
        if result["accepted"] is not (
            result["evidence"]
            in {
                "scheduler_command_returncode_zero",
                "scheduler_target_no_longer_live",
                "scheduler_target_state_transitioned",
            }
        ):
            raise ControlError("safety-hold drain acceptance evidence is inconsistent")
    if value["state"] == "complete":
        if (
            set(value["results"]) != set(value["targets"])
            or not all(row["accepted"] for row in value["results"].values())
            or value.get("completed_timestamp") is None
            or value.get("last_error") is not None
        ):
            raise ControlError("completed safety-hold drain lacks accepted evidence")
    elif value.get("completed_timestamp") is not None:
        raise ControlError("unfinished safety-hold drain claims completion")


def _new_capacity_state() -> dict[str, Any]:
    return {
        "schema_version": CAPACITY_STATE_SCHEMA_VERSION,
        "protocol": CAPACITY_STATE_PROTOCOL,
        "current_generation": 1,
        # ``None`` means the release-bundle fleet pin is effective.  A controlled
        # capacity transition publishes a sealed operational overlay here; the
        # scientific/release/model/run pins in ``immutable`` never change.
        "current_contract": None,
        "active_transition": None,
        "history": [],
    }


def _validate_capacity_contract_record(
    record: Any, *, expected_generation: int
) -> None:
    required = {
        "capacity_generation",
        "path",
        "sha256",
        "marker_path",
        "marker_sha256",
        "protected_capacity_marker_path",
        "protected_capacity_marker_sha256",
        "protected_capacity_marker_id",
        "static_feasibility_certificate_path",
        "static_feasibility_certificate_sha256",
        "static_feasibility_certificate_id",
        "base_fleet_contract_sha256",
        "additive_overlay_contract_path",
        "additive_overlay_contract_sha256",
        "fleet_id",
        "logical_replicas",
        "allocated_gpus",
        "profile_replicas",
        "activated_at",
        "activated_timestamp",
    }
    if (
        not isinstance(record, dict)
        or set(record) != required
        or record.get("capacity_generation") != expected_generation
        or not isinstance(record.get("path"), str)
        or not Path(record["path"]).is_absolute()
        or _SHA256_RE.fullmatch(str(record.get("sha256", ""))) is None
        or not isinstance(record.get("marker_path"), str)
        or not Path(record["marker_path"]).is_absolute()
        or _SHA256_RE.fullmatch(str(record.get("marker_sha256", ""))) is None
        or not isinstance(record.get("protected_capacity_marker_path"), str)
        or not Path(record["protected_capacity_marker_path"]).is_absolute()
        or _SHA256_RE.fullmatch(
            str(record.get("protected_capacity_marker_sha256", ""))
        )
        is None
        or _SHA256_RE.fullmatch(
            str(record.get("protected_capacity_marker_id", ""))
        )
        is None
        or not isinstance(
            record.get("static_feasibility_certificate_path"), str
        )
        or not Path(
            record["static_feasibility_certificate_path"]
        ).is_absolute()
        or _SHA256_RE.fullmatch(
            str(record.get("static_feasibility_certificate_sha256", ""))
        )
        is None
        or _SHA256_RE.fullmatch(
            str(record.get("static_feasibility_certificate_id", ""))
        )
        is None
        or _SHA256_RE.fullmatch(
            str(record.get("base_fleet_contract_sha256", ""))
        )
        is None
        or not isinstance(record.get("additive_overlay_contract_path"), str)
        or not Path(record["additive_overlay_contract_path"]).is_absolute()
        or _SHA256_RE.fullmatch(
            str(record.get("additive_overlay_contract_sha256", ""))
        )
        is None
        or record.get("fleet_id") != "schema5-v1"
        or not isinstance(record.get("logical_replicas"), int)
        or isinstance(record.get("logical_replicas"), bool)
        or record["logical_replicas"] < 22
        or not isinstance(record.get("allocated_gpus"), int)
        or isinstance(record.get("allocated_gpus"), bool)
        or record["allocated_gpus"] < 24
        or not isinstance(record.get("profile_replicas"), dict)
        or set(record["profile_replicas"]) != set(EXPECTED_FLEET_PROFILES)
        or any(
            not isinstance(count, int)
            or isinstance(count, bool)
            or count < EXPECTED_FLEET_PROFILES[profile]
            for profile, count in record["profile_replicas"].items()
        )
        or not isinstance(record.get("activated_timestamp"), (int, float))
        or isinstance(record.get("activated_timestamp"), bool)
    ):
        raise ControlError("schema-5 capacity contract record is invalid")


def _validate_capacity_state(value: Any) -> None:
    if not isinstance(value, dict) or set(value) not in (
        {
            "schema_version",
            "protocol",
            "current_generation",
            "active_transition",
            "history",
        },
        {
            "schema_version",
            "protocol",
            "current_generation",
            "current_contract",
            "active_transition",
            "history",
        },
    ):
        raise ControlError("schema-5 capacity state is missing or malformed")
    generation = value.get("current_generation")
    if (
        value.get("schema_version") != CAPACITY_STATE_SCHEMA_VERSION
        or value.get("protocol") != CAPACITY_STATE_PROTOCOL
        or not isinstance(generation, int)
        or isinstance(generation, bool)
        or generation < 1
        or not isinstance(value.get("history"), list)
    ):
        raise ControlError("schema-5 capacity generation is invalid")
    current_contract = value.get("current_contract")
    if current_contract is not None:
        _validate_capacity_contract_record(
            current_contract, expected_generation=generation
        )
    active = value.get("active_transition")
    if active is not None:
        required = {
            "transition_id",
            "phase",
            "from_generation",
            "to_generation",
            "created_at",
            "created_timestamp",
            "old_fleet_job_ids",
            "archive_path",
            "archive_sha256",
            "retirement_attempts",
            "last_retirement_error",
            "invalidated_readiness",
            "new_contract",
            "retirement_intent_path",
            "retirement_intent_sha256",
            "fleet_launch_attempts",
            "last_fleet_launch_error",
            "consumed_capacity_incidents",
        }
        if (
            not isinstance(active, dict)
            or not required.issubset(active)
            or active.get("phase") not in CAPACITY_TRANSITION_PHASES
            or (
                active.get("phase") == "retirement_requested"
                and (
                    active.get("from_generation") != generation
                    or active.get("to_generation") != generation + 1
                )
            )
            or (
                active.get("phase") in {"fleet_launch_pending", "readiness_pending"}
                and (
                    active.get("to_generation") != generation
                    or active.get("from_generation") != generation - 1
                )
            )
            or not isinstance(active.get("transition_id"), str)
            or not active["transition_id"]
            or not isinstance(active.get("old_fleet_job_ids"), list)
            or not all(str(job_id).isdigit() for job_id in active["old_fleet_job_ids"])
            or len(set(active["old_fleet_job_ids"]))
            != len(active["old_fleet_job_ids"])
            or _SHA256_RE.fullmatch(str(active.get("archive_sha256", ""))) is None
            or not isinstance(active.get("retirement_attempts"), int)
            or active["retirement_attempts"] < 0
            or not isinstance(active.get("fleet_launch_attempts"), int)
            or active["fleet_launch_attempts"] < 0
            or not isinstance(active.get("retirement_intent_path"), str)
            or not Path(active["retirement_intent_path"]).is_absolute()
            or _SHA256_RE.fullmatch(
                str(active.get("retirement_intent_sha256", ""))
            )
            is None
            or not isinstance(active.get("consumed_capacity_incidents"), list)
            or not all(
                isinstance(key, str) and key in CAPACITY_REMEDIATION_ALERT_KEYS
                for key in active["consumed_capacity_incidents"]
            )
            or len(active["consumed_capacity_incidents"])
            != len(set(active["consumed_capacity_incidents"]))
            or active["consumed_capacity_incidents"]
            != sorted(active["consumed_capacity_incidents"])
        ):
            raise ControlError("active schema-5 capacity transition is invalid")
        _validate_capacity_contract_record(
            active.get("new_contract"),
            expected_generation=int(active["to_generation"]),
        )
        if (
            active.get("phase") in {"fleet_launch_pending", "readiness_pending"}
            and current_contract != active["new_contract"]
        ):
            raise ControlError(
                "published capacity transition differs from current contract"
            )
    for record in value["history"]:
        if (
            not isinstance(record, dict)
            or record.get("phase") != "completed"
            or not isinstance(record.get("from_generation"), int)
            or record.get("to_generation") != record["from_generation"] + 1
            or not isinstance(record.get("completed_timestamp"), (int, float))
        ):
            raise ControlError("schema-5 capacity history is invalid")


def _new_admission_ramp_state(
    *, rollout_generation: int, current_ceiling: int, reason: str, now: float
) -> dict[str, Any]:
    return {
        "schema_version": ADMISSION_RAMP_SCHEMA_VERSION,
        "protocol": ADMISSION_RAMP_PROTOCOL,
        "rollout_generation": int(rollout_generation),
        "current_ceiling": int(current_ceiling),
        "window": None,
        "last_observation": None,
        "last_action": {
            "action": "initialized",
            "reason": reason,
            "at": utc_timestamp(now),
            "timestamp": float(now),
        },
        "promotions": [],
        "resets": [],
        # Authorizations are immutable evidence references retained as history.
        # ``capacity_gate`` is the one durable request that tells the operator (and
        # monitor) that a controlled placement/capacity transition is required.
        "client_capacity_authorizations": [],
        "capacity_gate": None,
    }


def _validate_client_capacity_authorization_record(value: Any) -> None:
    required = {
        "capacity_generation",
        "authorized_cell_ceiling",
        "path",
        "sha256",
        "control_immutable_sha256",
        "capacity_contract_sha256",
        "partition",
        "preempt_mode",
        "nonpreemptible_client_slots",
        "cpu_limit",
        "memory_limit_mib",
        "max_submit_jobs",
        "scheduler_evidence_sha256",
        "canary_evidence_sha256",
        "accepted_submission_evidence_sha256",
        "readiness_evidence_sha256",
        "captured_timestamp",
        "attested_at",
        "attested_timestamp",
    }
    if (
        not isinstance(value, dict)
        or set(value) != required
        or not isinstance(value.get("capacity_generation"), int)
        or isinstance(value.get("capacity_generation"), bool)
        or value["capacity_generation"] < 2
        or value.get("authorized_cell_ceiling") not in {192, 384}
        or not isinstance(value.get("path"), str)
        or not Path(value["path"]).is_absolute()
        or any(
            _SHA256_RE.fullmatch(str(value.get(field, ""))) is None
            for field in (
                "sha256",
                "control_immutable_sha256",
                "capacity_contract_sha256",
                "scheduler_evidence_sha256",
                "canary_evidence_sha256",
                "accepted_submission_evidence_sha256",
                "readiness_evidence_sha256",
            )
        )
        or not isinstance(value.get("partition"), str)
        or not value["partition"]
        or value.get("preempt_mode") != "OFF"
        or any(
            not isinstance(value.get(field), int)
            or isinstance(value.get(field), bool)
            or value[field] < 1
            for field in (
                "nonpreemptible_client_slots",
                "cpu_limit",
                "memory_limit_mib",
                "max_submit_jobs",
            )
        )
        or value["nonpreemptible_client_slots"] < value["authorized_cell_ceiling"]
        or value["cpu_limit"] < value["authorized_cell_ceiling"]
        or value["memory_limit_mib"] < value["authorized_cell_ceiling"] * 4096
        or value["max_submit_jobs"]
        < value["authorized_cell_ceiling"] + int(DEFAULT_ADMISSION["reserve"])
        or not isinstance(value.get("captured_timestamp"), (int, float))
        or isinstance(value.get("captured_timestamp"), bool)
        or not isinstance(value.get("attested_timestamp"), (int, float))
        or isinstance(value.get("attested_timestamp"), bool)
        or float(value["attested_timestamp"]) < float(value["captured_timestamp"])
        or not isinstance(value.get("attested_at"), str)
        or not value["attested_at"]
    ):
        raise ControlError("schema-5 client-capacity authorization record is invalid")


def _validate_client_capacity_gate(value: Any) -> None:
    if value is None:
        return
    required = {
        "state",
        "from_ceiling",
        "target_ceiling",
        "capacity_generation",
        "control_immutable_sha256",
        "requested_at",
        "requested_timestamp",
        "reason",
    }
    if (
        not isinstance(value, dict)
        or set(value) != required
        or value.get("state") != "capacity_transition_required"
        or value.get("from_ceiling") not in {96, 192}
        or value.get("target_ceiling")
        != ADMISSION_RAMP_REQUIREMENTS[value["from_ceiling"]]["next_ceiling"]
        or not isinstance(value.get("capacity_generation"), int)
        or isinstance(value.get("capacity_generation"), bool)
        or value["capacity_generation"] < 1
        or _SHA256_RE.fullmatch(
            str(value.get("control_immutable_sha256", ""))
        )
        is None
        or not isinstance(value.get("requested_at"), str)
        or not value["requested_at"]
        or not isinstance(value.get("requested_timestamp"), (int, float))
        or isinstance(value.get("requested_timestamp"), bool)
        or value.get("reason") != "sealed_client_capacity_authorization_missing"
    ):
        raise ControlError("schema-5 client-capacity gate request is invalid")


def _valid_run_qid_map(value: Any) -> bool:
    return bool(
        isinstance(value, dict)
        and set(value) == set(REQUIRED_RUNS)
        and all(
            isinstance(value[run_id], int)
            and not isinstance(value[run_id], bool)
            and 0 <= value[run_id] <= REQUIRED_RUN_QIDS[run_id]
            for run_id in REQUIRED_RUNS
        )
    )


def _validate_ramp_observation_record(value: Any) -> None:
    if not isinstance(value, dict):
        raise ControlError("admission ramp observation record is invalid")
    if (
        not isinstance(value.get("path"), str)
        or not value["path"]
        or _SHA256_RE.fullmatch(str(value.get("sha256", ""))) is None
        or not isinstance(value.get("timestamp"), (int, float))
        or isinstance(value.get("timestamp"), bool)
        or not isinstance(value.get("captured_timestamp"), (int, float))
        or isinstance(value.get("captured_timestamp"), bool)
        or float(value["captured_timestamp"]) > float(value["timestamp"])
        or value.get("cadence") not in MONITOR_CADENCE_SECONDS
        or not isinstance(value.get("clean"), bool)
    ):
        raise ControlError("admission ramp observation record fields are invalid")
    validated_qids = value.get("run_validated_qids")
    useful_qids = value.get("run_useful_qids")
    if value["cadence"] == "health":
        if validated_qids is not None or useful_qids is not None:
            raise ControlError("health ramp observation contains semantic progress")
    elif (
        not _valid_run_qid_map(validated_qids)
        or not _valid_run_qid_map(useful_qids)
        or any(
            useful_qids[run_id] > validated_qids[run_id]
            for run_id in REQUIRED_RUNS
        )
    ):
        raise ControlError(
            "semantic ramp observation lacks exact trusted/useful run progress"
        )


def _validate_admission_ramp(
    control: Mapping[str, Any], ramp: Any
) -> None:
    """Validate the durable, generation-scoped rollout evidence accumulator."""

    if not isinstance(ramp, dict):
        raise ControlError("schema-5 admission ramp state is missing")
    if (
        ramp.get("schema_version") != ADMISSION_RAMP_SCHEMA_VERSION
        or ramp.get("protocol") != ADMISSION_RAMP_PROTOCOL
    ):
        raise ControlError("schema-5 admission ramp protocol is invalid")
    generation = ramp.get("rollout_generation")
    if (
        not isinstance(generation, int)
        or isinstance(generation, bool)
        or generation != control.get("rollout_generation")
    ):
        raise ControlError("admission ramp rollout generation is not current")
    ceiling = ramp.get("current_ceiling")
    if ceiling != control.get("admission", {}).get("current_ceiling"):
        raise ControlError("admission ramp ceiling differs from dispatcher admission")
    if not isinstance(ramp.get("promotions"), list) or not isinstance(
        ramp.get("resets"), list
    ):
        raise ControlError("admission ramp promotion/reset history is invalid")
    authorizations = ramp.get("client_capacity_authorizations")
    if (
        not isinstance(authorizations, list)
        or len(
            {
                (item.get("capacity_generation"), item.get("sha256"))
                for item in authorizations
                if isinstance(item, dict)
            }
        )
        != len(authorizations)
    ):
        raise ControlError("admission ramp client-capacity history is invalid")
    for authorization in authorizations:
        _validate_client_capacity_authorization_record(authorization)
        if authorization["control_immutable_sha256"] != control.get(
            "immutable_sha256"
        ):
            raise ControlError(
                "client-capacity authorization binds another immutable control"
            )
    _validate_client_capacity_gate(ramp.get("capacity_gate"))
    capacity_gate = ramp.get("capacity_gate")
    if isinstance(capacity_gate, dict):
        if (
            ceiling > capacity_gate["from_ceiling"]
            or capacity_gate["capacity_generation"]
            > control.get("capacity", {}).get("current_generation", 0)
            or capacity_gate["control_immutable_sha256"]
            != control.get("immutable_sha256")
        ):
            raise ControlError("client-capacity gate is stale or misbound")
    last_observation = ramp.get("last_observation")
    if last_observation is not None:
        _validate_ramp_observation_record(last_observation)
    if not isinstance(ramp.get("last_action"), dict):
        raise ControlError("admission ramp last action is invalid")
    promotion_transitions = [
        row
        for row in control.get("transition_history", [])
        if isinstance(row, dict) and row.get("event") == "admission_ceiling_promoted"
    ]
    transition_index = 0
    for promotion in ramp["promotions"]:
        if not isinstance(promotion, dict):
            raise ControlError("admission ramp promotion record is invalid")
        source = promotion.get("from_ceiling")
        requirement = ADMISSION_RAMP_REQUIREMENTS.get(source)
        observations = promotion.get("observations")
        if (
            requirement is None
            or promotion.get("to_ceiling") != requirement["next_ceiling"]
            or not isinstance(observations, list)
            or not observations
            or promotion.get("evidence_sha256") != sha256_value(observations)
            or not _valid_run_qid_map(
                promotion.get("baseline_run_validated_qids")
            )
            or not _valid_run_qid_map(promotion.get("final_run_validated_qids"))
            or not _valid_run_qid_map(
                promotion.get("baseline_run_useful_qids")
            )
            or not _valid_run_qid_map(promotion.get("final_run_useful_qids"))
            or float(promotion.get("clean_seconds", -1.0))
            < float(requirement["clean_seconds"])
        ):
            raise ControlError("admission ramp promotion proof is invalid")
        capacity_authorization_sha256 = promotion.get(
            "client_capacity_authorization_sha256"
        )
        if promotion["to_ceiling"] > PRODUCTION_NONPREEMPTIBLE_CELL_CAP:
            matching_authorizations = [
                authorization
                for authorization in authorizations
                if authorization["sha256"] == capacity_authorization_sha256
                and authorization["capacity_generation"]
                == promotion.get("capacity_generation")
                and authorization["authorized_cell_ceiling"]
                >= promotion["to_ceiling"]
            ]
            if len(matching_authorizations) != 1:
                raise ControlError(
                    "higher-stage promotion lacks one matching client-capacity "
                    "generation authorization"
                )
            elif (
                capacity_authorization_sha256
                != control["immutable"][
                    "protected_capacity_marker_sha256"
                ]
            ):
                raise ControlError(
                    "protected-capacity promotion does not bind the immutable "
                    "full-design marker"
                )
        for observation in observations:
            _validate_ramp_observation_record(observation)
            if observation["clean"] is not True:
                raise ControlError("admission ramp promotion includes unclean evidence")
        baseline_qids = promotion["baseline_run_validated_qids"]
        final_qids = promotion["final_run_validated_qids"]
        if any(final_qids[run_id] < baseline_qids[run_id] for run_id in REQUIRED_RUNS):
            raise ControlError("admission ramp promotion contains regressed run progress")
        baseline_useful = promotion["baseline_run_useful_qids"]
        final_useful = promotion["final_run_useful_qids"]
        if any(
            final_useful[run_id] < baseline_useful[run_id]
            or baseline_useful[run_id] > baseline_qids[run_id]
            or final_useful[run_id] > final_qids[run_id]
            for run_id in REQUIRED_RUNS
        ):
            raise ControlError(
                "admission ramp promotion contains invalid useful-QID progress"
            )
        if source == 24 and not all(
            final_useful[run_id] > baseline_useful[run_id]
            for run_id in REQUIRED_RUNS
        ):
            raise ControlError(
                "initial admission promotion lacks all-run useful-QID progress"
            )
        matched = False
        while transition_index < len(promotion_transitions):
            details = promotion_transitions[transition_index].get("details", {})
            transition_index += 1
            matched = bool(
                details.get("previous") == source
                and details.get("current") == promotion["to_ceiling"]
                and details.get("rollout_generation")
                == promotion.get("rollout_generation")
                and details.get("fleet_generation")
                == promotion.get("fleet_generation")
                and details.get("throughput_epoch")
                == promotion.get("throughput_epoch")
                and details.get("evidence_sha256")
                == promotion.get("evidence_sha256")
                and details.get("capacity_generation")
                == promotion.get("capacity_generation")
                and details.get("client_capacity_authorization_sha256")
                == promotion.get("client_capacity_authorization_sha256")
            )
            if matched:
                break
        if not matched:
            raise ControlError("admission ramp promotion is not journal-bound")
    window = ramp.get("window")
    if window is None:
        return
    if not isinstance(window, dict):
        raise ControlError("admission ramp window is invalid")
    if (
        window.get("rollout_generation") != generation
        or window.get("ceiling") != ceiling
        or ceiling == ADMISSION_RAMP_STAGES[-1]
    ):
        raise ControlError("admission ramp window does not bind the current stage")
    if not isinstance(window.get("fleet_generation"), str) or not window.get(
        "fleet_generation"
    ):
        raise ControlError("admission ramp window lacks a fleet generation")
    if (
        not isinstance(window.get("throughput_epoch"), int)
        or isinstance(window.get("throughput_epoch"), bool)
        or window["throughput_epoch"] < 1
    ):
        raise ControlError("admission ramp window lacks a throughput epoch")
    if not isinstance(window.get("started_timestamp"), (int, float)) or isinstance(
        window.get("started_timestamp"), bool
    ):
        raise ControlError("admission ramp window start is invalid")
    if not _valid_run_qid_map(window.get("baseline_run_validated_qids")) or not (
        _valid_run_qid_map(window.get("latest_run_validated_qids"))
    ):
        raise ControlError("admission ramp run progress evidence is invalid")
    if not _valid_run_qid_map(window.get("baseline_run_useful_qids")) or not (
        _valid_run_qid_map(window.get("latest_run_useful_qids"))
    ):
        raise ControlError("admission ramp useful run progress evidence is invalid")
    if any(
        window["baseline_run_useful_qids"][run_id]
        > window["baseline_run_validated_qids"][run_id]
        or window["latest_run_useful_qids"][run_id]
        > window["latest_run_validated_qids"][run_id]
        for run_id in REQUIRED_RUNS
    ):
        raise ControlError("admission ramp useful progress exceeds trusted cardinality")
    if not isinstance(window.get("observations"), list) or not window["observations"]:
        raise ControlError("admission ramp window has no clean observations")
    previous_timestamp: float | None = None
    for observation in window["observations"]:
        _validate_ramp_observation_record(observation)
        timestamp = float(observation["timestamp"])
        if observation["clean"] is not True or (
            previous_timestamp is not None and timestamp < previous_timestamp
        ):
            raise ControlError("admission ramp window evidence is unclean or reordered")
        previous_timestamp = timestamp


def _validate_monitoring_state(monitoring: Any) -> None:
    """Validate mutable cadence state without allowing cadence or ownership drift."""

    if not isinstance(monitoring, dict):
        raise ControlError("schema-5 monitoring state must be an object")
    if monitoring.get("owner_role") != MONITOR_OWNER_ROLE:
        raise ControlError(
            f"schema-5 monitoring must be owned by {MONITOR_OWNER_ROLE!r}"
        )
    cadences = monitoring.get("cadences")
    if not isinstance(cadences, dict) or set(cadences) != set(MONITOR_CADENCE_SECONDS):
        raise ControlError(
            "schema-5 monitoring must contain exactly health, semantic, and daily cadences"
        )
    for cadence, expected_interval in MONITOR_CADENCE_SECONDS.items():
        row = cadences[cadence]
        if not isinstance(row, dict):
            raise ControlError(f"monitor cadence {cadence!r} must be an object")
        if row.get("interval_seconds") != expected_interval:
            raise ControlError(
                f"monitor cadence {cadence!r} interval drifted: expected "
                f"{expected_interval}, found {row.get('interval_seconds')!r}"
            )
        next_due = row.get("next_due_timestamp")
        if not isinstance(next_due, (int, float)) or isinstance(next_due, bool):
            raise ControlError(
                f"monitor cadence {cadence!r} next_due_timestamp is invalid"
            )
        failures = row.get("consecutive_failures")
        if not isinstance(failures, int) or isinstance(failures, bool) or failures < 0:
            raise ControlError(
                f"monitor cadence {cadence!r} consecutive_failures is invalid"
            )
        for timestamp_field in (
            "last_attempt_timestamp",
            "last_success_timestamp",
            "last_failure_timestamp",
        ):
            timestamp = row.get(timestamp_field)
            if timestamp is not None and (
                not isinstance(timestamp, (int, float)) or isinstance(timestamp, bool)
            ):
                raise ControlError(
                    f"monitor cadence {cadence!r} {timestamp_field} is invalid"
                )
        active = row.get("active_attempt")
        if active is not None:
            if not isinstance(active, dict):
                raise ControlError(
                    f"monitor cadence {cadence!r} active_attempt is invalid"
                )
            required = {
                "attempt_id",
                "started_timestamp",
                "scheduled_for_timestamp",
                "controller_generation",
                "controller_intent_token",
                "controller_job_id",
                "log_path",
                "timeout_seconds",
                "deadline_timestamp",
            }
            if not required.issubset(active):
                raise ControlError(
                    f"monitor cadence {cadence!r} active_attempt is incomplete"
                )
            if not isinstance(active["attempt_id"], str) or not active["attempt_id"]:
                raise ControlError(f"monitor cadence {cadence!r} attempt ID is invalid")
            if not isinstance(active["started_timestamp"], (int, float)):
                raise ControlError(
                    f"monitor cadence {cadence!r} attempt timestamp is invalid"
                )
            if (
                active.get("timeout_seconds") != MONITOR_DEADLINE_SECONDS[cadence]
                or not isinstance(active.get("deadline_timestamp"), (int, float))
                or active["deadline_timestamp"]
                != active["started_timestamp"] + active["timeout_seconds"]
            ):
                raise ControlError(
                    f"monitor cadence {cadence!r} execution deadline is invalid"
                )


def _new_finalization_state(
    pins: Mapping[str, Any], *, now: float
) -> dict[str, Any]:
    results_root = Path(str(pins["results_root"])).expanduser().resolve()
    return {
        "schema_version": FINALIZATION_SCHEMA_VERSION,
        "protocol": FINALIZATION_PROTOCOL,
        "state": "idle",
        "intent_id": None,
        "requested_at": None,
        "requested_timestamp": None,
        "semantic_evidence": None,
        "request_intent": None,
        "consumed_capacity_incidents": [],
        "output_root": str(
            results_root / "recovery" / "schema5-v1.2-r13" / "final"
        ),
        "attempts": 0,
        "worker_attempts": [],
        "next_attempt": 1,
        "phase_evidence": {
            "validating": None,
            "retiring_fleet": None,
            "snapshotting": None,
        },
        "active_job": None,
        "successor_job": None,
        "successor_retirement": None,
        "last_error": None,
        "completion_marker": None,
        "history": [],
    }


def _validate_finalizer_job_record(value: Any, *, context: str) -> None:
    if value is None:
        return
    expected = {
        "attempt",
        "intent_token",
        "job_token",
        "sbatch_path",
        "sbatch_sha256",
        "submission_transport",
        "submission_argv",
        "submission_argv_sha256",
        "persistent_hold",
        "spooled_receipt_path",
        "spooled_receipt_sha256",
        "released_at",
        "released_timestamp",
        "dependency_job_id",
        "job_id",
        "state",
        "created_at",
        "created_timestamp",
        "submitted_at",
        "submitted_timestamp",
    }
    if not isinstance(value, dict) or set(value) != expected:
        raise ControlError(f"{context} finalizer job record fields are invalid")
    attempt = value.get("attempt")
    created = value.get("created_timestamp")
    submitted = value.get("submitted_timestamp")
    dependency = value.get("dependency_job_id")
    job_id = value.get("job_id")
    released = value.get("released_timestamp")
    submission_argv = value.get("submission_argv")
    receipt_path = value.get("spooled_receipt_path")
    receipt_sha256 = value.get("spooled_receipt_sha256")
    sbatch = Path(str(value.get("sbatch_path", ""))).expanduser()
    try:
        exact_submission_argv = _exact_sbatch_submission_argv(
            token=str(value.get("job_token", "")),
            dependency_job_id=dependency if isinstance(dependency, str) else None,
        )
    except ControlError:
        exact_submission_argv = None
    if (
        not isinstance(attempt, int)
        or isinstance(attempt, bool)
        or attempt < 1
        or re.fullmatch(r"[0-9a-f]{32}", str(value.get("intent_token", "")))
        is None
        or not str(value.get("job_token", "")).startswith(
            FINALIZER_JOB_TOKEN_PREFIX + ";"
        )
        or not sbatch.is_absolute()
        or _SHA256_RE.fullmatch(str(value.get("sbatch_sha256", ""))) is None
        or value.get("submission_transport")
        != EXACT_SBATCH_SUBMISSION_TRANSPORT
        or not isinstance(submission_argv, list)
        or not all(isinstance(item, str) for item in submission_argv)
        or submission_argv != exact_submission_argv
        or value.get("submission_argv_sha256")
        != _submission_argv_sha256(submission_argv)
        or not isinstance(value.get("persistent_hold"), bool)
        or value.get("state")
        not in {"submitting", "submitted", "started", "terminal", "cancelled"}
        or not isinstance(created, (int, float))
        or isinstance(created, bool)
        or value.get("created_at") != utc_timestamp(float(created))
        or (
            submitted is not None
            and (
                not isinstance(submitted, (int, float))
                or isinstance(submitted, bool)
                or value.get("submitted_at") != utc_timestamp(float(submitted))
            )
        )
        or (submitted is None and value.get("submitted_at") is not None)
        or (
            dependency is not None
            and (not isinstance(dependency, str) or not dependency.isdigit())
        )
        or (
            job_id is not None
            and (not isinstance(job_id, str) or not job_id.isdigit())
        )
        or (
            value.get("state") in {"submitted", "started", "terminal", "cancelled"}
            and job_id is None
        )
        or (
            job_id is None
            and (
                receipt_path is not None
                or receipt_sha256 is not None
                or released is not None
                or value.get("released_at") is not None
            )
        )
        or (
            job_id is not None
            and (
                not isinstance(receipt_path, str)
                or not Path(receipt_path).is_absolute()
                or _SHA256_RE.fullmatch(str(receipt_sha256 or "")) is None
                or not isinstance(released, (int, float))
                or isinstance(released, bool)
                or value.get("released_at") != utc_timestamp(float(released))
            )
        )
    ):
        raise ControlError(f"{context} finalizer job record is invalid")


def _validate_successor_retirement_binding(value: Any) -> None:
    if value is None:
        return
    expected = {
        "schema_version",
        "protocol",
        "transaction_id",
        "publisher_identity_id",
        "successor_identity_id",
        "intent_path",
        "intent_sha256",
        "receipt_path",
        "receipt_sha256",
        "receipt_id",
    }
    if not isinstance(value, dict) or set(value) != expected:
        raise ControlError("finalizer successor-retirement binding fields are invalid")
    intent_path = Path(str(value.get("intent_path", ""))).expanduser()
    receipt_path_value = value.get("receipt_path")
    receipt_sha256 = value.get("receipt_sha256")
    receipt_id = value.get("receipt_id")
    if (
        value.get("schema_version")
        != FINALIZER_SUCCESSOR_RETIREMENT_SCHEMA_VERSION
        or value.get("protocol") != FINALIZER_SUCCESSOR_RETIREMENT_PROTOCOL
        or _SHA256_RE.fullmatch(str(value.get("transaction_id", ""))) is None
        or _SHA256_RE.fullmatch(str(value.get("publisher_identity_id", "")))
        is None
        or _SHA256_RE.fullmatch(str(value.get("successor_identity_id", "")))
        is None
        or not intent_path.is_absolute()
        or _SHA256_RE.fullmatch(str(value.get("intent_sha256", ""))) is None
    ):
        raise ControlError("finalizer successor-retirement binding is invalid")
    if receipt_path_value is None:
        if receipt_sha256 is not None or receipt_id is not None:
            raise ControlError(
                "incomplete successor-retirement binding claims a receipt"
            )
    else:
        receipt_path = Path(str(receipt_path_value)).expanduser()
        if (
            not receipt_path.is_absolute()
            or _SHA256_RE.fullmatch(str(receipt_sha256 or "")) is None
            or _SHA256_RE.fullmatch(str(receipt_id or "")) is None
        ):
            raise ControlError(
                "completed successor-retirement receipt binding is invalid"
            )


def _validate_finalizer_worker_attempts(
    finalization: Mapping[str, Any],
) -> None:
    attempts = finalization.get("worker_attempts")
    if (
        not isinstance(attempts, list)
        or len(attempts) != finalization.get("attempts")
        or len(attempts) > FINALIZER_MAX_TRANSIENT_ATTEMPTS
    ):
        raise ControlError("finalizer worker attempt accounting is invalid")
    identities: set[tuple[int, str]] = set()
    expected = {
        "attempt",
        "job_id",
        "status",
        "started_at",
        "started_timestamp",
        "finished_at",
        "finished_timestamp",
    }
    for row in attempts:
        if not isinstance(row, Mapping) or set(row) != expected:
            raise ControlError("finalizer worker attempt record is invalid")
        attempt = row.get("attempt")
        job_id = row.get("job_id")
        started = row.get("started_timestamp")
        finished = row.get("finished_timestamp")
        identity = (attempt, job_id)
        if (
            not isinstance(attempt, int)
            or isinstance(attempt, bool)
            or attempt < 1
            or not isinstance(job_id, str)
            or not job_id.isdigit()
            or identity in identities
            or row.get("status") not in FINALIZER_WORKER_ATTEMPT_STATES
            or not isinstance(started, (int, float))
            or isinstance(started, bool)
            or row.get("started_at") != utc_timestamp(float(started))
            or (
                row.get("status") == "started"
                and (
                    finished is not None
                    or row.get("finished_at") is not None
                )
            )
            or (
                row.get("status") != "started"
                and (
                    not isinstance(finished, (int, float))
                    or isinstance(finished, bool)
                    or row.get("finished_at")
                    != utc_timestamp(float(finished))
                )
            )
        ):
            raise ControlError("finalizer worker attempt record is invalid")
        identities.add(identity)


def _validate_finalizer_phase_evidence(
    finalization: Mapping[str, Any],
) -> None:
    evidence = finalization.get("phase_evidence")
    if not isinstance(evidence, Mapping) or set(evidence) != {
        "validating",
        "retiring_fleet",
        "snapshotting",
    }:
        raise ControlError("finalizer phase evidence fields are invalid")
    fields = {
        "validating": {
            "entered_at",
            "entered_timestamp",
            "semantic_report_path",
            "semantic_intent_path",
            "semantic_preflight_path",
            "semantic_report_sha256",
            "semantic_intent_sha256",
            "semantic_intent_id",
            "semantic_preflight_sha256",
            "semantic_preflight_id",
        },
        "retiring_fleet": {
            "entered_at",
            "entered_timestamp",
            "semantic_report_sha256",
            "semantic_preflight_sha256",
            "semantic_preflight_id",
            "retirement_root",
            "retirement_intent_path",
            "retirement_intent_sha256",
            "retirement_id",
            "retirement_marker_path",
            "retirement_marker_sha256",
            "retirement_completion_id",
        },
        "snapshotting": {
            "entered_at",
            "entered_timestamp",
            "retirement_root",
            "retirement_marker_path",
            "retirement_marker_sha256",
            "retirement_completion_id",
            "cache_root",
            "cache_marker_path",
            "cache_marker_sha256",
            "cache_generation_id",
            "cache_tree_sha256",
            "snapshot_root",
            "snapshot_marker_path",
            "snapshot_marker_sha256",
            "snapshot_id",
        },
    }
    path_fields = {
        "semantic_report_path",
        "semantic_intent_path",
        "semantic_preflight_path",
        "retirement_root",
        "retirement_intent_path",
        "retirement_marker_path",
        "cache_root",
        "cache_marker_path",
        "snapshot_root",
        "snapshot_marker_path",
    }
    sha_fields = {
        "semantic_report_sha256",
        "semantic_intent_sha256",
        "semantic_intent_id",
        "semantic_preflight_sha256",
        "semantic_preflight_id",
        "retirement_intent_sha256",
        "retirement_id",
        "retirement_marker_sha256",
        "retirement_completion_id",
        "cache_marker_sha256",
        "cache_generation_id",
        "cache_tree_sha256",
        "snapshot_marker_sha256",
    }
    present: list[str] = []
    for phase in ("validating", "retiring_fleet", "snapshotting"):
        row = evidence.get(phase)
        if row is None:
            continue
        present.append(phase)
        entered = row.get("entered_timestamp") if isinstance(row, Mapping) else None
        if (
            not isinstance(row, Mapping)
            or set(row) != fields[phase]
            or not isinstance(entered, (int, float))
            or isinstance(entered, bool)
            or row.get("entered_at") != utc_timestamp(float(entered))
        ):
            raise ControlError(f"finalizer {phase} phase evidence is invalid")
        for field in path_fields & set(row):
            value = row[field]
            if not isinstance(value, str) or not Path(value).is_absolute():
                raise ControlError(
                    f"finalizer {phase} phase path {field} is invalid"
                )
        for field in sha_fields & set(row):
            value = row[field]
            if value is not None and _SHA256_RE.fullmatch(str(value)) is None:
                raise ControlError(
                    f"finalizer {phase} phase identity {field} is invalid"
                )
        snapshot_id = row.get("snapshot_id")
        if snapshot_id is not None and (
            not isinstance(snapshot_id, str) or not snapshot_id
        ):
            raise ControlError("finalizer snapshot phase identity is invalid")
    expected_prefix = [
        phase
        for phase in ("validating", "retiring_fleet", "snapshotting")
        if evidence.get(phase) is not None
    ]
    if present != expected_prefix or present not in (
        [],
        ["validating"],
        ["validating", "retiring_fleet"],
        ["validating", "retiring_fleet", "snapshotting"],
    ):
        raise ControlError("finalizer phase evidence is not monotonic")
    state = finalization.get("state")
    if state != "blocked":
        required_count = min(FINALIZER_PHASE_ORDER.get(str(state), 0), 3)
        if len(present) != required_count:
            raise ControlError(
                "finalizer durable state differs from its phase evidence"
            )
    validating = evidence.get("validating")
    retiring = evidence.get("retiring_fleet")
    snapshotting = evidence.get("snapshotting")
    if retiring is not None and any(
        validating.get(field) is None
        for field in (
            "semantic_report_sha256",
            "semantic_intent_sha256",
            "semantic_intent_id",
            "semantic_preflight_sha256",
            "semantic_preflight_id",
        )
    ):
        raise ControlError(
            "fleet-retirement phase lacks completed semantic bindings"
        )
    if snapshotting is not None and any(
        retiring.get(field) is None
        for field in (
            "retirement_intent_sha256",
            "retirement_id",
            "retirement_marker_sha256",
            "retirement_completion_id",
        )
    ):
        raise ControlError(
            "snapshot phase lacks completed fleet-retirement bindings"
        )
    if state == "complete" and any(
        snapshotting.get(field) is None
        for field in (
            "cache_marker_sha256",
            "cache_generation_id",
            "cache_tree_sha256",
            "snapshot_marker_sha256",
            "snapshot_id",
        )
    ):
        raise ControlError(
            "completed finalization lacks cache/snapshot phase bindings"
        )


def _validate_finalization_state(
    control: Mapping[str, Any], finalization: Any
) -> None:
    expected = {
        "schema_version",
        "protocol",
        "state",
        "intent_id",
        "requested_at",
        "requested_timestamp",
        "semantic_evidence",
        "request_intent",
        "consumed_capacity_incidents",
        "output_root",
        "attempts",
        "worker_attempts",
        "next_attempt",
        "phase_evidence",
        "active_job",
        "successor_job",
        "successor_retirement",
        "last_error",
        "completion_marker",
        "history",
    }
    if not isinstance(finalization, dict) or set(finalization) != expected:
        raise ControlError("schema-5 finalization state fields are invalid")
    results_root = Path(
        str(control["immutable"]["results_root"])
    ).expanduser().resolve()
    expected_output = (
        results_root / "recovery" / "schema5-v1.2-r13" / "final"
    )
    state = finalization.get("state")
    requested = finalization.get("requested_timestamp")
    if (
        finalization.get("schema_version") != FINALIZATION_SCHEMA_VERSION
        or finalization.get("protocol") != FINALIZATION_PROTOCOL
        or state not in FINALIZATION_STATES
        or Path(str(finalization.get("output_root", ""))).expanduser().resolve()
        != expected_output
        or not isinstance(finalization.get("attempts"), int)
        or isinstance(finalization.get("attempts"), bool)
        or int(finalization["attempts"]) < 0
        or not isinstance(finalization.get("next_attempt"), int)
        or isinstance(finalization.get("next_attempt"), bool)
        or int(finalization["next_attempt"]) < 1
    ):
        raise ControlError("schema-5 finalization state is invalid")
    if state == "idle":
        if any(
            finalization.get(field) is not None
            for field in (
                "intent_id",
                "requested_at",
                "requested_timestamp",
                "semantic_evidence",
                "request_intent",
                "active_job",
                "successor_job",
                "successor_retirement",
                "last_error",
                "completion_marker",
            )
        ):
            raise ControlError("idle finalization contains active transaction state")
    else:
        if (
            re.fullmatch(r"[0-9a-f]{64}", str(finalization.get("intent_id", "")))
            is None
            or not isinstance(requested, (int, float))
            or isinstance(requested, bool)
            or finalization.get("requested_at")
            != utc_timestamp(float(requested))
        ):
            raise ControlError("active finalization intent identity is invalid")
        evidence = finalization.get("semantic_evidence")
        request_intent = finalization.get("request_intent")
        if (
            not isinstance(evidence, dict)
            or set(evidence) != {"path", "sha256", "captured_timestamp"}
            or not Path(str(evidence.get("path", ""))).is_absolute()
            or _SHA256_RE.fullmatch(str(evidence.get("sha256", ""))) is None
            or not isinstance(evidence.get("captured_timestamp"), (int, float))
            or isinstance(evidence.get("captured_timestamp"), bool)
        ):
            raise ControlError("active finalization semantic evidence is invalid")
        if (
            not isinstance(request_intent, dict)
            or set(request_intent) != {"path", "sha256", "intent_id"}
            or not Path(str(request_intent.get("path", ""))).is_absolute()
            or _SHA256_RE.fullmatch(str(request_intent.get("sha256", ""))) is None
            or request_intent.get("intent_id") != finalization.get("intent_id")
        ):
            raise ControlError("active finalization request intent is invalid")
    _validate_finalizer_worker_attempts(finalization)
    _validate_finalizer_phase_evidence(finalization)
    if state == "idle" and (
        finalization["worker_attempts"]
        or any(finalization["phase_evidence"].values())
    ):
        raise ControlError("idle finalization contains durable phase progress")
    consumed = finalization.get("consumed_capacity_incidents")
    if (
        not isinstance(consumed, list)
        or consumed != sorted(set(consumed))
        or any(
            not isinstance(key, str)
            or key not in CAPACITY_REMEDIATION_ALERT_KEYS
            for key in consumed
        )
        or (state == "idle" and consumed)
    ):
        raise ControlError(
            "finalization consumed-capacity incident binding is invalid"
        )
    _validate_finalizer_job_record(
        finalization.get("active_job"), context="active"
    )
    _validate_finalizer_job_record(
        finalization.get("successor_job"), context="successor"
    )
    _validate_successor_retirement_binding(
        finalization.get("successor_retirement")
    )
    last_error = finalization.get("last_error")
    if last_error is not None and (
        not isinstance(last_error, dict)
        or set(last_error)
        != {"kind", "message", "transient", "at", "timestamp"}
        or not isinstance(last_error.get("kind"), str)
        or not isinstance(last_error.get("message"), str)
        or not isinstance(last_error.get("transient"), bool)
        or not isinstance(last_error.get("timestamp"), (int, float))
        or isinstance(last_error.get("timestamp"), bool)
        or last_error.get("at")
        != utc_timestamp(float(last_error.get("timestamp", -1)))
    ):
        raise ControlError("finalization last_error is invalid")
    completion = finalization.get("completion_marker")
    if state == "complete":
        expected_marker_path = expected_output / FINAL_COMPLETE_FILENAME
        if (
            not isinstance(completion, dict)
            or set(completion) != {"path", "sha256", "final_id"}
            or Path(str(completion.get("path", ""))).expanduser()
            != expected_marker_path
            or _SHA256_RE.fullmatch(str(completion.get("sha256", ""))) is None
            or _SHA256_RE.fullmatch(str(completion.get("final_id", ""))) is None
        ):
            raise ControlError("completed finalization marker binding is invalid")
        retirement = finalization.get("successor_retirement")
        if (
            not isinstance(retirement, dict)
            or retirement.get("receipt_path") is None
            or not isinstance(finalization.get("active_job"), dict)
            or not isinstance(finalization.get("successor_job"), dict)
            or finalization["successor_job"].get("state")
            not in {"terminal", "cancelled"}
        ):
            raise ControlError(
                "completed finalization lacks proven successor retirement"
            )
    elif completion is not None:
        raise ControlError("non-complete finalization claims a completion marker")
    history = finalization.get("history")
    if not isinstance(history, list):
        raise ControlError("finalization history must be a list")
    previous: str | None = None
    for sequence, row in enumerate(history, start=1):
        if not isinstance(row, dict):
            raise ControlError("finalization history record is invalid")
        payload = dict(row)
        digest = payload.pop("hash", None)
        if (
            payload.get("sequence") != sequence
            or payload.get("previous_hash") != previous
            or not isinstance(payload.get("event"), str)
            or not isinstance(payload.get("timestamp"), (int, float))
            or payload.get("at")
            != utc_timestamp(float(payload.get("timestamp", -1)))
            or digest != sha256_value(payload)
        ):
            raise ControlError("finalization history hash chain is invalid")
        previous = str(digest)


def _append_finalization_history(
    finalization: MutableMapping[str, Any],
    *,
    event: str,
    details: Mapping[str, Any] | None,
    now: float,
) -> None:
    history = finalization["history"]
    payload: dict[str, Any] = {
        "sequence": len(history) + 1,
        "event": event,
        "details": copy.deepcopy(dict(details or {})),
        "at": utc_timestamp(now),
        "timestamp": now,
        "previous_hash": history[-1]["hash"] if history else None,
    }
    payload["hash"] = sha256_value(payload)
    history.append(payload)


def _finalization_request_intent_path(control: Mapping[str, Any]) -> Path:
    results_root = Path(
        str(control["immutable"]["results_root"])
    ).expanduser().resolve()
    return (
        results_root
        / CONTROL_STATE_DIRNAME
        / FINALIZER_STATE_DIRNAME
        / FINALIZER_REQUEST_INTENT_FILENAME
    )


def _cleanup_finalization_request_intent_orphans(root: Path) -> list[str]:
    """Remove only mkstemp names owned by the request-intent publisher.

    The caller owns ``control_lock``.  A process death releases that lock, so an exact
    hidden eight-character ``tempfile`` name cannot belong to a concurrent publisher.
    Anything with a different name, inode shape, owner, or mode is left untouched and
    fails closed when it collides with this private namespace.
    """

    pattern = re.compile(
        rf"^\.{re.escape(FINALIZER_REQUEST_INTENT_FILENAME)}\."
        r"[a-z0-9_]{8}\.tmp$"
    )
    removed: list[str] = []
    for candidate in sorted(root.iterdir(), key=lambda item: item.name):
        if pattern.fullmatch(candidate.name) is None:
            continue
        try:
            candidate_stat = candidate.lstat()
        except OSError as exc:
            raise ControlError(
                "cannot inspect orphaned finalization request-intent temporary"
            ) from exc
        mode = stat.S_IMODE(candidate_stat.st_mode)
        if (
            not stat.S_ISREG(candidate_stat.st_mode)
            or candidate_stat.st_nlink != 1
            or candidate_stat.st_uid != os.geteuid()
            or mode not in {0o600, 0o444}
        ):
            raise ControlError(
                "request-intent temporary namespace contains an unknown entry"
            )
        candidate.unlink()
        removed.append(candidate.name)
    if removed:
        io._fsync_directory(root)
    return removed


def _finalization_capacity_alert_resolution_plan(
    control: Mapping[str, Any],
    incident_keys: Sequence[str],
) -> list[dict[str, Any]]:
    """Bind every control-resident alert that the request is allowed to resolve."""

    consumed = sorted(set(incident_keys))
    if consumed != list(incident_keys):
        raise ControlError(
            "finalization capacity incidents must be sorted and unique"
        )
    return [
        {
            "dedupe_key": dedupe_key,
            "alert_ids": sorted(
                str(alert["alert_id"])
                for alert in control.get("alerts", [])
                if isinstance(alert, Mapping)
                and alert.get("dedupe_key") == dedupe_key
                and alert.get("resolved_at") is None
            ),
        }
        for dedupe_key in consumed
    ]


def _validate_finalization_capacity_alert_resolution_plan(
    value: Any,
    *,
    consumed_capacity_incidents: Sequence[str],
) -> list[dict[str, Any]]:
    consumed = list(consumed_capacity_incidents)
    if not isinstance(value, list) or len(value) != len(consumed):
        raise ControlError(
            "autonomous finalization alert-resolution plan is invalid"
        )
    observed_keys: list[str] = []
    observed_ids: list[str] = []
    for row in value:
        if not isinstance(row, dict) or set(row) != {
            "dedupe_key",
            "alert_ids",
        }:
            raise ControlError(
                "autonomous finalization alert-resolution plan is invalid"
            )
        dedupe_key = row.get("dedupe_key")
        alert_ids = row.get("alert_ids")
        if (
            not isinstance(dedupe_key, str)
            or dedupe_key not in CAPACITY_REMEDIATION_ALERT_KEYS
            or not isinstance(alert_ids, list)
            or alert_ids != sorted(set(alert_ids))
            or any(
                not isinstance(alert_id, str)
                or re.fullmatch(r"[0-9a-f]{32}", alert_id) is None
                for alert_id in alert_ids
            )
        ):
            raise ControlError(
                "autonomous finalization alert-resolution plan is invalid"
            )
        observed_keys.append(dedupe_key)
        observed_ids.extend(alert_ids)
    if observed_keys != consumed or len(observed_ids) != len(set(observed_ids)):
        raise ControlError(
            "autonomous finalization alert-resolution plan is invalid"
        )
    return copy.deepcopy(value)


def _finalization_request_intent_identity(
    control: Mapping[str, Any],
    *,
    semantic_evidence: Mapping[str, Any],
    consumed_capacity_incidents: Sequence[str],
    capacity_alert_resolution_plan: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    return {
        "schema_version": FINALIZER_REQUEST_INTENT_SCHEMA_VERSION,
        "protocol": FINALIZER_REQUEST_INTENT_PROTOCOL,
        "kind": "schema5_autonomous_finalization_request_intent",
        "release_id": control["immutable"]["release_id"],
        "immutable_sha256": control["immutable_sha256"],
        "semantic_evidence": copy.deepcopy(dict(semantic_evidence)),
        "consumed_capacity_incidents": list(consumed_capacity_incidents),
        "capacity_alert_resolution_plan": copy.deepcopy(
            list(capacity_alert_resolution_plan)
        ),
    }


def _validate_finalization_request_intent_payload(
    control: Mapping[str, Any],
    value: Any,
    *,
    semantic_evidence: Mapping[str, Any] | None = None,
    consumed_capacity_incidents: Sequence[str] | None = None,
    capacity_alert_resolution_plan: Sequence[Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    required = {
        "schema_version",
        "protocol",
        "kind",
        "release_id",
        "immutable_sha256",
        "semantic_evidence",
        "consumed_capacity_incidents",
        "capacity_alert_resolution_plan",
        "requested_at",
        "requested_timestamp",
        "intent_id",
    }
    if not isinstance(value, dict) or set(value) != required:
        raise ControlError("autonomous finalization request intent fields are invalid")
    evidence = value.get("semantic_evidence")
    consumed = value.get("consumed_capacity_incidents")
    resolution_plan = value.get("capacity_alert_resolution_plan")
    requested = value.get("requested_timestamp")
    identity = {
        key: copy.deepcopy(item)
        for key, item in value.items()
        if key not in {"requested_at", "requested_timestamp", "intent_id"}
    }
    if (
        value.get("schema_version") != FINALIZER_REQUEST_INTENT_SCHEMA_VERSION
        or value.get("protocol") != FINALIZER_REQUEST_INTENT_PROTOCOL
        or value.get("kind")
        != "schema5_autonomous_finalization_request_intent"
        or value.get("release_id") != control["immutable"]["release_id"]
        or value.get("immutable_sha256") != control["immutable_sha256"]
        or not isinstance(evidence, dict)
        or set(evidence) != {"path", "sha256", "captured_timestamp"}
        or not Path(str(evidence.get("path", ""))).is_absolute()
        or _SHA256_RE.fullmatch(str(evidence.get("sha256", ""))) is None
        or not isinstance(evidence.get("captured_timestamp"), (int, float))
        or isinstance(evidence.get("captured_timestamp"), bool)
        or not isinstance(consumed, list)
        or consumed != sorted(set(consumed))
        or any(
            not isinstance(key, str)
            or key not in CAPACITY_REMEDIATION_ALERT_KEYS
            for key in consumed
        )
        or not isinstance(requested, (int, float))
        or isinstance(requested, bool)
        or not math.isfinite(float(requested))
        or float(requested) < 0
        or value.get("requested_at") != utc_timestamp(float(requested))
        or value.get("intent_id") != sha256_value(identity)
    ):
        raise ControlError("autonomous finalization request intent is invalid")
    _validate_finalization_capacity_alert_resolution_plan(
        resolution_plan,
        consumed_capacity_incidents=consumed,
    )
    if semantic_evidence is not None and evidence != dict(semantic_evidence):
        raise ControlError(
            "autonomous finalization request intent semantic evidence drifted"
        )
    if (
        consumed_capacity_incidents is not None
        and consumed != list(consumed_capacity_incidents)
    ):
        raise ControlError(
            "autonomous finalization request intent capacity incidents drifted"
        )
    if (
        capacity_alert_resolution_plan is not None
        and resolution_plan != list(capacity_alert_resolution_plan)
    ):
        raise ControlError(
            "autonomous finalization request intent alert-resolution plan drifted"
        )
    return value


def _verify_finalization_request_intent(
    control: Mapping[str, Any],
) -> dict[str, Any]:
    finalization = control["finalization"]
    binding = finalization.get("request_intent")
    if not isinstance(binding, Mapping):
        raise ControlError("active finalization lacks its request-intent binding")
    path = Path(str(binding.get("path", ""))).expanduser()
    expected_path = _finalization_request_intent_path(control)
    if (
        not path.is_absolute()
        or path != expected_path
        or path.is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
        or sha256_file(path) != binding.get("sha256")
    ):
        raise ControlError(
            "autonomous finalization request intent is missing, mutable, or drifted"
        )
    value = _load_json_object(
        path, description="autonomous finalization request intent"
    )
    _validate_finalization_request_intent_payload(
        control,
        value,
        semantic_evidence=finalization["semantic_evidence"],
        consumed_capacity_incidents=finalization[
            "consumed_capacity_incidents"
        ],
    )
    if value["intent_id"] != binding.get("intent_id"):
        raise ControlError(
            "autonomous finalization request-intent identity drifted"
        )
    evidence_path = Path(value["semantic_evidence"]["path"])
    report = _load_json_object(
        evidence_path,
        description="request-intent semantic finalization evidence",
    )
    if (
        _finalization_semantic_evidence(
            expected_path.parent.parent,
            evidence_path,
            report,
        )
        != value["semantic_evidence"]
    ):
        raise ControlError(
            "autonomous finalization request semantic evidence drifted"
        )
    return value


def _publish_finalization_request_intent(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    semantic_evidence: Mapping[str, Any],
    consumed_capacity_incidents: Sequence[str],
    capacity_alert_resolution_plan: Sequence[Mapping[str, Any]],
    now: float,
) -> tuple[dict[str, Any], dict[str, Any]]:
    path = _finalization_request_intent_path(control)
    expected_state_dir = path.parent.parent
    if state_dir.expanduser().resolve() != expected_state_dir:
        raise ControlError(
            "autonomous finalization state root differs from immutable results root"
        )
    root = path.parent
    if root.is_symlink() or (root.exists() and not root.is_dir()):
        raise ControlError("autonomous finalizer state directory is unsafe")
    root.mkdir(parents=True, exist_ok=True)
    _cleanup_finalization_request_intent_orphans(root)
    identity = _finalization_request_intent_identity(
        control,
        semantic_evidence=semantic_evidence,
        consumed_capacity_incidents=consumed_capacity_incidents,
        capacity_alert_resolution_plan=capacity_alert_resolution_plan,
    )
    intent_id = sha256_value(identity)
    if path.exists() or path.is_symlink():
        if (
            path.is_symlink()
            or not path.is_file()
            or path.stat().st_nlink != 1
            or path.stat().st_mode & 0o222
        ):
            raise ControlError(
                "autonomous finalization request intent path is unsafe"
            )
        value = _load_json_object(
            path, description="existing autonomous finalization request intent"
        )
        _validate_finalization_request_intent_payload(control, value)
        frozen_consumed = list(value["consumed_capacity_incidents"])
        current_consumed = list(consumed_capacity_incidents)
        if not set(current_consumed).issubset(frozen_consumed):
            raise ControlError(
                "existing autonomous finalization request intent does not bind "
                "a newly active capacity cause"
            )
        frozen_resolution_plan = value["capacity_alert_resolution_plan"]
        frozen_alert_ids_by_key = {
            str(row["dedupe_key"]): {
                str(alert_id) for alert_id in row["alert_ids"]
            }
            for row in frozen_resolution_plan
        }
        current_alert_ids_by_key = {
            str(row["dedupe_key"]): {
                str(alert_id) for alert_id in row["alert_ids"]
            }
            for row in capacity_alert_resolution_plan
        }
        for dedupe_key, current_alert_ids in current_alert_ids_by_key.items():
            if not current_alert_ids.issubset(
                frozen_alert_ids_by_key.get(dedupe_key, set())
            ):
                raise ControlError(
                    "existing autonomous finalization request intent does not bind "
                    "a newly active capacity alert"
                )
        existing_evidence = value["semantic_evidence"]
        evidence_path = Path(existing_evidence["path"])
        evidence_report = _load_json_object(
            evidence_path,
            description="existing request-intent semantic evidence",
        )
        if (
            _finalization_semantic_evidence(
                state_dir,
                evidence_path,
                evidence_report,
            )
            != existing_evidence
        ):
            raise ControlError(
                "existing autonomous finalization semantic evidence drifted"
            )
        expected_existing_id = sha256_value(
            _finalization_request_intent_identity(
                control,
                semantic_evidence=existing_evidence,
                consumed_capacity_incidents=frozen_consumed,
                capacity_alert_resolution_plan=frozen_resolution_plan,
            )
        )
        if value["intent_id"] != expected_existing_id:
            raise ControlError(
                "existing autonomous finalization request intent conflicts"
            )
    else:
        value = {
            **identity,
            "requested_at": utc_timestamp(now),
            "requested_timestamp": now,
            "intent_id": intent_id,
        }
        _atomic_publish_readonly_json(path, value)
    intent_id = str(value["intent_id"])
    if (
        path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
        or path.is_symlink()
    ):
        raise ControlError(
            "autonomous finalization request intent was not sealed safely"
        )
    binding = {
        "path": str(path),
        "sha256": sha256_file(path),
        "intent_id": intent_id,
    }
    return value, binding


def _required_pin(mapping: Mapping[str, Any], field: str, *, context: str) -> Any:
    value = mapping.get(field)
    if value is None or value == "" or value == []:
        raise ImmutablePinError(
            f"{context} is missing required immutable field {field!r}"
        )
    return value


