def _validate_checksum_sidecar(
    path: Path, expected_name: str, expected_hash: str
) -> None:
    if path.is_symlink() or not path.is_file():
        raise ImmutablePinError(f"pinned checksum sidecar is missing: {path}")
    fields = path.read_text(encoding="utf-8").strip().split()
    if fields != [expected_hash, expected_name]:
        raise ImmutablePinError(
            f"checksum sidecar does not bind {expected_name}: {path}"
        )


def _benchmark_derived_qids(run: Mapping[str, Any]) -> int:
    manifest_path = Path(str(run["manifest_path"])).resolve()
    contracts_path = Path(str(run["benchmark_contract_path"])).resolve()
    try:
        rows = json.loads(manifest_path.read_text(encoding="utf-8"))
        contracts_payload = json.loads(contracts_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ImmutablePinError(
            f"cannot derive benchmark QID cardinality: {exc}"
        ) from exc
    if not isinstance(rows, list) or len(rows) != run["cell_count"]:
        raise ImmutablePinError(f"manifest cardinality drifted: {manifest_path}")
    if not isinstance(contracts_payload, dict):
        raise ImmutablePinError(
            f"benchmark contracts must be an object: {contracts_path}"
        )
    if (
        contracts_payload.get("manifest_filename") != "cells.json"
        or contracts_payload.get("manifest_sha256") != run["manifest_sha256"]
        or contracts_payload.get("manifest_cell_count") != run["cell_count"]
    ):
        raise ImmutablePinError(
            "benchmark contracts do not bind the exact run manifest"
        )
    contracts = contracts_payload.get("contracts")
    if not isinstance(contracts, list) or not contracts:
        raise ImmutablePinError("benchmark contracts contain no typed contract rows")
    counts: dict[tuple[str, int | None, int], int] = {}
    for contract in contracts:
        if not isinstance(contract, dict) or not isinstance(contract.get("key"), dict):
            raise ImmutablePinError("benchmark contract row is malformed")
        key_payload = contract["key"]
        if set(key_payload) != {"benchmark", "n_questions", "seed"}:
            raise ImmutablePinError("benchmark contract key has unexpected fields")
        key = (
            str(key_payload["benchmark"]),
            key_payload["n_questions"],
            key_payload["seed"],
        )
        count = contract.get("question_count")
        qids = contract.get("ordered_qids")
        if (
            not isinstance(count, int)
            or isinstance(count, bool)
            or count < 1
            or not isinstance(qids, list)
            or len(qids) != count
            or len(qids) != len(set(qids))
            or key in counts
        ):
            raise ImmutablePinError("benchmark contract QID cardinality is malformed")
        counts[key] = count
    total = 0
    for row in rows:
        if not isinstance(row, dict):
            raise ImmutablePinError("manifest contains a non-object cell")
        key = (str(row.get("benchmark")), row.get("n_questions"), row.get("seed"))
        if key not in counts:
            raise ImmutablePinError(f"manifest cell lacks benchmark contract: {key!r}")
        total += counts[key]
    return total


def _assert_root_read_only(path: Path, *, description: str) -> None:
    if path.stat().st_mode & 0o222:
        raise ImmutablePinError(f"{description} is not sealed read-only: {path}")


def _validate_schema4_environment_manifest_static(
    manifest: Mapping[str, Any], *, role: str
) -> None:
    """Validate schema-4 provenance without consulting retired build inputs.

    The live-prefix byte scan is owned by the generation-scoped runtime-integrity
    attestation. This release-bundle verifier authenticates the complete manifest
    contract and its content address using only sealed release artifacts.
    """

    if (
        manifest.get("schema_version") != ENVIRONMENT_MANIFEST_SCHEMA_VERSION
        or manifest.get("release_id") != PRODUCTION_RELEASE_ID
        or manifest.get("role") != role
        or manifest.get("sealed_read_only") is not True
        or not isinstance(manifest.get("directory_inventory"), dict)
    ):
        raise ImmutablePinError(
            f"{role} environment manifest is not sealed schema 4"
        )
    try:
        expected_content = runtime_integrity._validate_schema4_environment_manifest(
            manifest,
            role=role,
            inventory=manifest["directory_inventory"],
        )
    except runtime_integrity.RuntimeIntegrityError as exc:
        raise ImmutablePinError(
            f"{role} environment manifest provenance is invalid: {exc}"
        ) from exc
    if manifest.get("environment_content_sha256") != expected_content:
        raise ImmutablePinError(
            f"{role} environment manifest content identity is invalid"
        )


def _validate_package_cache_seed_input_binding(value: Any) -> dict[str, Any]:
    required = {
        "source_package_cache",
        "inventory_sha256",
        "inventory_entry_count",
        "inventory_file_count",
        "inventory_total_file_bytes",
        "requirements_sha256",
        "required_package_count",
        "archive_count",
        "selected_top_level_entries",
        "input_id",
    }
    if not isinstance(value, dict) or set(value) != required:
        raise ImmutablePinError(
            "selected Conda package-cache input binding has the wrong fields"
        )
    candidate = dict(value)
    input_id = candidate.pop("input_id", None)
    selected = value.get("selected_top_level_entries")
    counts = (
        "inventory_entry_count",
        "inventory_file_count",
        "inventory_total_file_bytes",
        "required_package_count",
        "archive_count",
    )
    expected_id = hashlib.sha256(
        (
            json.dumps(
                candidate,
                indent=2,
                sort_keys=True,
                ensure_ascii=True,
                allow_nan=False,
            )
            + "\n"
        ).encode("utf-8")
    ).hexdigest()
    if (
        not isinstance(value.get("source_package_cache"), str)
        or not Path(value["source_package_cache"]).is_absolute()
        or any(
            _SHA256_RE.fullmatch(str(value.get(field, ""))) is None
            for field in ("inventory_sha256", "requirements_sha256")
        )
        or any(
            not isinstance(value.get(field), int)
            or isinstance(value.get(field), bool)
            or value[field] < 0
            for field in counts
        )
        or value["inventory_entry_count"] < 1
        or value["inventory_file_count"] < 1
        or value["required_package_count"] < 1
        or not isinstance(selected, list)
        or not selected
        or any(
            not isinstance(item, str)
            or not item
            or Path(item).name != item
            for item in selected
        )
        or sorted(set(selected)) != selected
        or input_id != expected_id
    ):
        raise ImmutablePinError(
            "selected Conda package-cache input binding is invalid"
        )
    return dict(value)


def _validate_conda_toolchain_binding_static(value: Any) -> dict[str, Any]:
    required = {
        "schema_version",
        "protocol",
        "release_tag",
        "chain_namespace",
        "toolchain_root",
        "base_prefix",
        "completion_marker",
        "marker_id",
        "installer_contract",
        "intent_id",
        "conda_executable",
        "runtime_identity_sha256",
        "complete_prefix_inventory_sha256",
        "read_only_probes",
        "binding_id",
    }
    if not isinstance(value, dict) or set(value) != required:
        raise ImmutablePinError(
            "sealed Conda toolchain binding has the wrong fields"
        )
    root = Path(str(value.get("toolchain_root", "")))
    marker = value.get("completion_marker")
    executable = value.get("conda_executable")
    contract = value.get("installer_contract")
    candidate = dict(value)
    binding_id = candidate.pop("binding_id", None)
    expected_id = hashlib.sha256(
        (
            json.dumps(
                candidate,
                indent=2,
                sort_keys=True,
                ensure_ascii=True,
                allow_nan=False,
            )
            + "\n"
        ).encode("utf-8")
    ).hexdigest()
    if (
        value.get("schema_version") != conda_toolchain.SCHEMA_VERSION
        or value.get("protocol") != conda_toolchain.PROTOCOL
        or value.get("release_tag") != PRODUCTION_OPERATIONAL_TAG
        or value.get("chain_namespace") != "schema5-v1.2-r13"
        or not root.is_absolute()
        or value.get("base_prefix") != str(root / "base")
        or not isinstance(marker, dict)
        or set(marker) != {"path", "sha256", "size"}
        or marker.get("path")
        != str(root / conda_toolchain.MARKER_NAME)
        or not isinstance(executable, dict)
        or set(executable)
        != {"path", "sha256", "size", "mode", "link_count"}
        or executable.get("path") != str(root / "base/bin/conda")
        or not isinstance(contract, dict)
        or contract
        != conda_toolchain.PINNED_INSTALLER_CONTRACT.as_dict()
        or not isinstance(value.get("read_only_probes"), dict)
        or any(
            _SHA256_RE.fullmatch(str(item)) is None
            for item in (
                marker.get("sha256"),
                value.get("marker_id"),
                value.get("intent_id"),
                executable.get("sha256"),
                value.get("runtime_identity_sha256"),
                value.get("complete_prefix_inventory_sha256"),
                binding_id,
            )
        )
        or not isinstance(marker.get("size"), int)
        or isinstance(marker.get("size"), bool)
        or marker["size"] < 1
        or not isinstance(executable.get("size"), int)
        or isinstance(executable.get("size"), bool)
        or executable["size"] < 1
        or not isinstance(executable.get("mode"), int)
        or isinstance(executable.get("mode"), bool)
        or executable["mode"] & 0o222
        or not isinstance(executable.get("link_count"), int)
        or isinstance(executable.get("link_count"), bool)
        or executable["link_count"] < 1
        or binding_id != expected_id
    ):
        raise ImmutablePinError(
            "sealed Conda toolchain binding is invalid"
        )
    return dict(value)


def _validate_release_bundle(pins: Mapping[str, Any]) -> None:
    """Verify the freezer's marker-last bundle and its exact control fragment.

    The freezer performs expensive package/runtime and recursive environment checks at
    publication.  The control plane re-verifies every marker-addressed byte, the bundle
    ID, live root seals, and the identity's exact pin fragment on every file-verified
    load.  A hand-written pins file therefore cannot bypass an unsealed release.
    """

    supplied_root = Path(str(pins["release_bundle_root"])).expanduser()
    if supplied_root.is_symlink() or not supplied_root.is_dir():
        raise ImmutablePinError(
            f"release bundle root is missing or unsafe: {supplied_root}"
        )
    root = supplied_root.resolve()
    _assert_root_read_only(root, description="release bundle root")
    try:
        transport_binding = (
            scheduler_safety.validate_transport_uncertainty_binding(
                pins["transport_uncertainty_binding"]
            )
        )
        transport_binding_sha256 = (
            scheduler_safety.transport_uncertainty_binding_sha256(
                transport_binding
            )
        )
    except (KeyError, scheduler_safety.SchedulerSafetyError) as exc:
        raise ImmutablePinError(
            "release transport/checkpoint/self-consistency pins are invalid"
        ) from exc
    if (
        pins.get("transport_uncertainty_binding_sha256")
        != transport_binding_sha256
    ):
        raise ImmutablePinError(
            "release transport-uncertainty binding digest drifted"
        )
    marker_path = root / RELEASE_COMPLETE_FILENAME
    try:
        marker = json.loads(marker_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ImmutablePinError(
            f"cannot read release completion marker: {exc}"
        ) from exc
    marker_fields = {
        "schema_version",
        "release_id",
        "complete",
        "publication_protocol",
        "artifacts",
        "git_commit",
        "source_tree_sha256",
        "transport_uncertainty_binding",
        "transport_uncertainty_binding_sha256",
        "release_bundle_id",
    }
    if not isinstance(marker, dict) or set(marker) != marker_fields:
        raise ImmutablePinError("release completion marker has the wrong fields")
    candidate = dict(marker)
    bundle_id = candidate.pop("release_bundle_id", None)
    if (
        marker.get("schema_version") != RELEASE_BUNDLE_SCHEMA_VERSION
        or marker.get("release_id") != pins["release_id"]
        or marker.get("complete") is not True
        or marker.get("publication_protocol") != "fsync_verify_marker_last"
        or marker.get("git_commit") != pins["git_commit"]
        or marker.get("source_tree_sha256") != pins["source_tree_sha256"]
        or marker.get("transport_uncertainty_binding")
        != pins["transport_uncertainty_binding"]
        or marker.get("transport_uncertainty_binding_sha256")
        != pins["transport_uncertainty_binding_sha256"]
        or bundle_id != sha256_value(candidate)
        or bundle_id != pins["release_bundle_id"]
    ):
        raise ImmutablePinError("release completion marker identity is invalid")
    expected_artifacts = {
        HARNESS_ENVIRONMENT_FILENAME,
        SERVING_ENVIRONMENT_FILENAME,
        RELEASE_IDENTITY_FILENAME,
        HARNESS_ENVIRONMENT_FILENAME + ".sha256",
        SERVING_ENVIRONMENT_FILENAME + ".sha256",
        RELEASE_IDENTITY_FILENAME + ".sha256",
    }
    artifacts = marker.get("artifacts")
    if not isinstance(artifacts, dict) or set(artifacts) != expected_artifacts:
        raise ImmutablePinError("release marker has the wrong artifact inventory")
    for filename, record in artifacts.items():
        path = root / filename
        if (
            not isinstance(record, dict)
            or set(record) != {"sha256", "size"}
            or path.is_symlink()
            or not path.is_file()
            or path.stat().st_size != record.get("size")
            or sha256_file(path) != record.get("sha256")
        ):
            raise ImmutablePinError(f"release marker artifact drifted: {path}")
        _assert_root_read_only(path, description="release bundle artifact")
    for filename in (
        HARNESS_ENVIRONMENT_FILENAME,
        SERVING_ENVIRONMENT_FILENAME,
        RELEASE_IDENTITY_FILENAME,
    ):
        artifact = root / filename
        expected_checksum = f"{sha256_file(artifact)}  {filename}\n"
        if (root / (filename + ".sha256")).read_text(
            encoding="utf-8"
        ) != expected_checksum:
            raise ImmutablePinError(f"release checksum sidecar is invalid: {filename}")
    try:
        identity = json.loads(
            (root / RELEASE_IDENTITY_FILENAME).read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ImmutablePinError(f"cannot parse release identity: {exc}") from exc
    identity_fields = {
        "schema_version",
        "release_id",
        "git",
        "release_worktree",
        "worktree_sealed_read_only",
        "materialization",
        "offline_environment",
        "transport_uncertainty",
        "model_contract",
        "fleet_contract",
        "environments",
        "publication",
        "control_pin_fragment",
    }
    if not isinstance(identity, dict) or set(identity) != identity_fields:
        raise ImmutablePinError("release identity has the wrong fields")
    expected_fragment = {field: pins[field] for field in _RELEASE_FRAGMENT_FIELDS}
    if (
        identity.get("schema_version") != RELEASE_BUNDLE_SCHEMA_VERSION
        or identity.get("release_id") != pins["release_id"]
        or identity.get("release_worktree") != pins["release_worktree"]
        or identity.get("worktree_sealed_read_only") is not True
        or identity.get("offline_environment") != REQUIRED_OFFLINE_ENVIRONMENT
        or identity.get("publication")
        != {
            "protocol": "fsync_verify_marker_last",
            "complete_marker": RELEASE_COMPLETE_FILENAME,
        }
        or identity.get("control_pin_fragment") != expected_fragment
    ):
        raise ImmutablePinError(
            "release identity does not bind the exact sealed control pins"
        )
    transport_record = identity.get("transport_uncertainty")
    if (
        not isinstance(transport_record, dict)
        or set(transport_record)
        != {"binding", "binding_sha256", "source_tree_sha256"}
        or transport_record.get("binding")
        != pins["transport_uncertainty_binding"]
        or transport_record.get("binding_sha256")
        != pins["transport_uncertainty_binding_sha256"]
        or transport_record.get("source_tree_sha256")
        != pins["source_tree_sha256"]
    ):
        raise ImmutablePinError(
            "release transport/checkpoint/self-consistency identity drifted"
        )
    materialization = identity.get("materialization")
    materialization_fields = {
        "schema_version",
        "release_id",
        "root",
        "marker_path",
        "marker_sha256",
        "materialization_id",
        "tag_commit",
        "source_tree_sha256",
        "paths",
        "stage_records",
        "environment_capture",
        "conda_toolchain",
        "conda_creation_tool",
        "package_cache_seed_input",
        "conda_package_cache_sha256",
        "conda_package_cache_seed_sha256",
    }
    expected_materialization_root = root.parent
    expected_materialization_marker = (
        expected_materialization_root / MATERIALIZATION_COMPLETE_FILENAME
    )
    if (
        not isinstance(materialization, dict)
        or set(materialization) != materialization_fields
    ):
        raise ImmutablePinError("release materialization binding has the wrong fields")
    paths = materialization.get("paths")
    recorded_toolchain = materialization.get("conda_toolchain")
    package_cache_seed_input = materialization.get(
        "package_cache_seed_input"
    )
    if (
        materialization.get("schema_version") != MATERIALIZATION_SCHEMA_VERSION
        or materialization.get("release_id") != pins["release_id"]
        or materialization.get("root") != str(expected_materialization_root)
        or materialization.get("marker_path") != str(expected_materialization_marker)
        or materialization.get("tag_commit") != pins["git_commit"]
        or materialization.get("source_tree_sha256") != pins["source_tree_sha256"]
        or not isinstance(paths, dict)
        or set(paths)
        != {
            "source_repository",
            "environment_capture_root",
            "release_worktree",
            "source_harness_prefix",
            "source_serving_prefix",
            "source_package_cache",
            "harness_prefix",
            "serving_prefix",
        }
        or paths.get("release_worktree") != pins["release_worktree"]
        or paths.get("harness_prefix") != pins["harness_environment_prefix"]
        or paths.get("serving_prefix") != pins["serving_environment_prefix"]
        or not isinstance(materialization.get("stage_records"), dict)
        or not isinstance(materialization.get("environment_capture"), dict)
        or not isinstance(recorded_toolchain, dict)
        or recorded_toolchain != pins.get("conda_toolchain")
        or not isinstance(materialization.get("conda_creation_tool"), dict)
        or set(materialization.get("conda_creation_tool", {}))
        != {"path", "sha256"}
        or not Path(
            str(materialization.get("conda_creation_tool", {}).get("path", ""))
        ).is_absolute()
        or _SHA256_RE.fullmatch(
            str(
                materialization.get("conda_creation_tool", {}).get(
                    "sha256", ""
                )
            )
        )
        is None
        or _SHA256_RE.fullmatch(
            str(materialization.get("conda_package_cache_sha256", ""))
        )
        is None
        or _SHA256_RE.fullmatch(
            str(materialization.get("conda_package_cache_seed_sha256", ""))
        )
        is None
        or package_cache_seed_input != pins.get("package_cache_seed_input")
        or expected_materialization_marker.is_symlink()
        or not expected_materialization_marker.is_file()
        or sha256_file(expected_materialization_marker)
        != materialization.get("marker_sha256")
    ):
        raise ImmutablePinError("release materialization binding is invalid")
    _validate_package_cache_seed_input_binding(package_cache_seed_input)
    _validate_conda_toolchain_binding_static(recorded_toolchain)
    if (
        not isinstance(recorded_toolchain.get("toolchain_root"), str)
        or not Path(recorded_toolchain["toolchain_root"]).is_absolute()
    ):
        raise ImmutablePinError(
            "release Conda toolchain binding is invalid"
        )
    try:
        live_toolchain = (
            conda_toolchain.verified_conda_toolchain_binding(
                recorded_toolchain["toolchain_root"],
                exercise=True,
            )
        )
    except (
        OSError,
        conda_toolchain.CondaToolchainProvisionError,
    ) as exc:
        raise ImmutablePinError(
            f"release Conda toolchain verification failed: {exc}"
        ) from exc
    if live_toolchain != recorded_toolchain:
        raise ImmutablePinError(
            "release Conda toolchain binding drifted"
        )
    _assert_root_read_only(
        expected_materialization_marker,
        description="materialization completion marker",
    )
    try:
        materialization_marker = json.loads(
            expected_materialization_marker.read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ImmutablePinError(f"cannot parse materialization marker: {exc}") from exc
    if not isinstance(materialization_marker, dict):
        raise ImmutablePinError("materialization marker must be an object")
    candidate_materialization = dict(materialization_marker)
    materialization_id = candidate_materialization.pop("materialization_id", None)
    expected_materialization_id = hashlib.sha256(
        (
            json.dumps(
                candidate_materialization,
                indent=2,
                sort_keys=True,
                ensure_ascii=True,
                allow_nan=False,
            )
            + "\n"
        ).encode("utf-8")
    ).hexdigest()
    if (
        materialization_marker.get("schema_version")
        != MATERIALIZATION_SCHEMA_VERSION
        or materialization_marker.get("release_id") != pins["release_id"]
        or materialization_marker.get("git_tag") != PRODUCTION_OPERATIONAL_TAG
        or materialization_marker.get("complete") is not True
        or materialization_marker.get("publication_protocol")
        != "stage_records_fsync_marker_last"
        or materialization_marker.get("paths") != paths
        or materialization_marker.get("tag_commit") != pins["git_commit"]
        or materialization_marker.get("source_tree_sha256")
        != pins["source_tree_sha256"]
        or materialization_marker.get("environment_capture")
        != materialization.get("environment_capture")
        or materialization_marker.get("conda_toolchain")
        != recorded_toolchain
        or materialization_marker.get("conda_creation_tool")
        != materialization.get("conda_creation_tool")
        or materialization_marker.get("package_cache_seed_input")
        != package_cache_seed_input
        or materialization_marker.get("stage_records")
        != materialization.get("stage_records")
        or materialization_id != materialization.get("materialization_id")
        or materialization_id != expected_materialization_id
    ):
        raise ImmutablePinError("materialization marker identity is invalid")
    stage_records = materialization.get("stage_records")
    if set(stage_records) != set(MATERIALIZATION_STAGE_FILENAMES):
        raise ImmutablePinError("materialization stage inventory is incomplete")
    verified_stage_payloads: dict[str, dict[str, Any]] = {}
    for stage, filename in MATERIALIZATION_STAGE_FILENAMES.items():
        record = stage_records[stage]
        stage_path = expected_materialization_root / filename
        if (
            not isinstance(record, dict)
            or set(record) != {"filename", "sha256", "record_sha256"}
            or record.get("filename") != filename
            or stage_path.is_symlink()
            or not stage_path.is_file()
            or sha256_file(stage_path) != record.get("sha256")
        ):
            raise ImmutablePinError(f"materialization stage artifact drifted: {stage}")
        _assert_root_read_only(stage_path, description=f"{stage} materialization stage")
        try:
            stage_payload = json.loads(stage_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ImmutablePinError(
                f"cannot parse {stage} materialization stage: {exc}"
            ) from exc
        if not isinstance(stage_payload, dict):
            raise ImmutablePinError(f"{stage} materialization stage must be an object")
        candidate_stage = dict(stage_payload)
        record_sha256 = candidate_stage.pop("record_sha256", None)
        expected_record_sha256 = hashlib.sha256(
            (
                json.dumps(
                    candidate_stage,
                    indent=2,
                    sort_keys=True,
                    ensure_ascii=True,
                    allow_nan=False,
                )
                + "\n"
            ).encode("utf-8")
        ).hexdigest()
        if (
            stage_payload.get("schema_version") != MATERIALIZATION_SCHEMA_VERSION
            or stage_payload.get("release_id") != pins["release_id"]
            or stage_payload.get("stage") != stage
            or record_sha256 != record.get("record_sha256")
            or record_sha256 != expected_record_sha256
        ):
            raise ImmutablePinError(
                f"materialization stage record identity drifted: {stage}"
            )
        verified_stage_payloads[stage] = stage_payload
    package_cache_identity = verified_stage_payloads["package_cache"].get(
        "content_inventory"
    )
    package_cache_seed_identity = verified_stage_payloads["package_cache"].get(
        "package_cache_seed"
    )
    if (
        not isinstance(package_cache_identity, dict)
        or package_cache_identity.get("content_inventory_sha256")
        != materialization.get("conda_package_cache_sha256")
        or not isinstance(package_cache_seed_identity, dict)
        or package_cache_seed_identity.get(
            "seed_content_inventory_sha256"
        )
        != materialization.get("conda_package_cache_seed_sha256")
    ):
        raise ImmutablePinError(
            "materialization package-cache/seed content identity drifted"
        )
    git_identity = identity.get("git")
    if (
        not isinstance(git_identity, dict)
        or set(git_identity)
        != {
            "git_commit",
            "git_tag",
            "git_tag_object",
            "source_tree_sha256",
        }
        or git_identity.get("git_tag") != PRODUCTION_OPERATIONAL_TAG
        or git_identity.get("git_commit") != pins["git_commit"]
        or git_identity.get("git_tag_object")
        != pins["release_tag_object"]
        or git_identity.get("source_tree_sha256") != pins["source_tree_sha256"]
    ):
        raise ImmutablePinError("release identity Git/source pin drifted")
    environment_records = identity.get("environments")
    expected_environment_paths = {
        "harness": root / HARNESS_ENVIRONMENT_FILENAME,
        "serving": root / SERVING_ENVIRONMENT_FILENAME,
    }
    if not isinstance(environment_records, dict) or set(environment_records) != {
        "harness",
        "serving",
    }:
        raise ImmutablePinError("release identity environment records are incomplete")
    for role, manifest_path in expected_environment_paths.items():
        record = environment_records.get(role)
        prefix_field = f"{role}_environment_prefix"
        sha_field = f"{role}_environment_sha256"
        manifest_field = f"{role}_environment_manifest_path"
        if (
            not isinstance(record, dict)
            or set(record)
            != {
                "prefix",
                "manifest_path",
                "manifest_sha256",
                "directory_inventory_sha256",
            }
            or record.get("prefix") != pins[prefix_field]
            or record.get("manifest_path") != str(manifest_path)
            or record.get("manifest_sha256") != pins[sha_field]
            or pins[manifest_field] != str(manifest_path)
        ):
            raise ImmutablePinError(f"release identity {role} environment drifted")
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ImmutablePinError(
                f"cannot parse {role} environment manifest: {exc}"
            ) from exc
        if (
            not isinstance(manifest, dict)
            or manifest.get("prefix") != pins[prefix_field]
            or manifest.get("conda_toolchain") != recorded_toolchain
            or record.get("directory_inventory_sha256")
            != (
                manifest.get("directory_inventory", {}).get("inventory_sha256")
                if isinstance(manifest.get("directory_inventory"), dict)
                else None
            )
        ):
            raise ImmutablePinError(f"{role} environment manifest is not sealed")
        _validate_schema4_environment_manifest_static(manifest, role=role)
        _assert_root_read_only(
            Path(str(pins[prefix_field])).resolve(), description=f"{role} environment"
        )
    _assert_root_read_only(
        Path(str(pins["release_worktree"])).resolve(), description="release worktree"
    )


def _protected_capacity_source_expectations(
    immutable: Mapping[str, Any],
) -> dict[str, str]:
    """Derive the exact frozen source pins required by every capacity load."""

    release = Path(str(immutable["release_worktree"])).expanduser().resolve()
    dispatcher = (release / "slurm" / "dispatch_sweeps.py").resolve()
    qualification_runner = (
        release / "scripts" / "run_schema5_throughput_qualification.py"
    ).resolve()
    source_tree_sha256 = str(immutable["source_tree_sha256"])
    if (
        _SHA256_RE.fullmatch(source_tree_sha256) is None
        or dispatcher.is_symlink()
        or not dispatcher.is_file()
        or qualification_runner.is_symlink()
        or not qualification_runner.is_file()
    ):
        raise ImmutablePinError(
            "protected-capacity frozen source authority is incomplete"
        )
    return {
        "expected_source_tree_sha256": source_tree_sha256,
        "expected_dispatcher_source_sha256": sha256_file(dispatcher),
        "expected_qualification_runner_source_sha256": sha256_file(
            qualification_runner
        ),
    }


def _load_immutable_protected_capacity_contract(
    immutable: Mapping[str, Any],
) -> protected_capacity.ProtectedCapacityContract:
    """Load generation one, whose sealed bytes pin the annotated tag object."""

    contract = protected_capacity.load_contract(
        immutable["protected_capacity_marker_path"],
        expected_release_git_commit=str(immutable["git_commit"]),
        expected_release_tag_object=str(
            immutable["release_tag_object"]
        ),
        expected_marker_id=str(
            immutable["protected_capacity_marker_id"]
        ),
        expected_sha256=str(
            immutable["protected_capacity_marker_sha256"]
        ),
        **_protected_capacity_source_expectations(immutable),
    )
    expected_accounting = {
        "cell_job_elements": 384,
        "active_server_job_elements": 22,
        "warm_turnover_job_elements": 3,
        "controller_monitor_other_held_job_elements": 39,
        "total_non_cell_reserve_job_elements": 64,
        "total_canary_job_elements": 448,
    }
    if (
        contract.capacity_generation != 1
        or contract.base_active_logical_replicas != 22
        or contract.base_active_gpus != 24
        or contract.additive_reserved_logical_replicas != 0
        or contract.additive_reserved_gpus != 0
        or contract.effective_active_logical_replicas != 22
        or contract.effective_active_gpus != 24
        or contract.retained_warm_turnover_job_elements != 3
        or contract.retained_warm_turnover_gpus != 4
        or contract.attested_total_gpus != 28
        or dict(contract.job_element_accounting) != expected_accounting
        or contract.effective_fleet_contract_sha256
        != contract.base_fleet_contract_sha256
        or contract.additive_overlay_contract_path
        != contract.effective_fleet_contract_path
        or contract.additive_overlay_contract_sha256
        != contract.base_fleet_contract_sha256
    ):
        raise ImmutablePinError(
            "generation-one protected capacity is not the exact "
            "22-replica/24-active-GPU + 3-warm-job/4-warm-GPU baseline "
            "with 39 held non-cell slots"
        )
    return contract


def _load_protected_capacity_contract(
    control: Mapping[str, Any],
    *,
    path: str | Path,
    expected_marker_id: str,
    expected_sha256: str,
) -> protected_capacity.ProtectedCapacityContract:
    """Strictly load any generation under the immutable tag/source lineage."""

    immutable = control["immutable"]
    initial = _load_immutable_protected_capacity_contract(immutable)
    resolved = Path(path).expanduser().resolve()
    if (
        resolved == initial.path
        and expected_marker_id == initial.marker_id
        and expected_sha256 == initial.sha256
    ):
        return initial
    return protected_capacity.load_contract(
        resolved,
        expected_release_git_commit=str(immutable["git_commit"]),
        expected_release_tag_object=str(
            immutable["release_tag_object"]
        ),
        expected_marker_id=expected_marker_id,
        expected_sha256=expected_sha256,
        **_protected_capacity_source_expectations(immutable),
    )


def validate_immutable_pins(pins: Mapping[str, Any], *, verify_files: bool) -> None:
    """Validate the frozen schema-5 production identity and (optionally) its files."""
    if not isinstance(pins, dict):
        raise ImmutablePinError("immutable pins must be an object")
    if set(pins) != _IMMUTABLE_PIN_FIELDS:
        raise ImmutablePinError(
            "immutable pin fields differ from the closed schema: "
            f"missing={sorted(_IMMUTABLE_PIN_FIELDS - set(pins))}, "
            f"unexpected={sorted(set(pins) - _IMMUTABLE_PIN_FIELDS)}"
        )
    for field in (
        "release_id",
        "release_bundle_root",
        "release_bundle_id",
        "release_worktree",
        "git_commit",
        "release_tag_object",
        "source_tree_sha256",
        "transport_uncertainty_binding",
        "transport_uncertainty_binding_sha256",
        "model_contract_path",
        "model_contract_sha256",
        "fleet_contract_path",
        "fleet_contract_sha256",
        "protected_capacity_marker_path",
        "protected_capacity_marker_sha256",
        "protected_capacity_marker_id",
        "protected_client_partition",
        "protected_client_qos",
        "protected_client_slots",
        "protected_client_cpus",
        "protected_client_memory_mib",
        "protected_client_reserve_jobs",
        "protected_client_submit_headroom",
        "harness_environment_prefix",
        "harness_environment_manifest_path",
        "harness_environment_sha256",
        "serving_environment_prefix",
        "serving_environment_manifest_path",
        "serving_environment_sha256",
        "conda_toolchain",
        "package_cache_seed_input",
        "conda_package_cache_seed_sha256",
        "hf_home",
        "results_root",
        "server_pool_root",
        "dispatcher_command",
        "fleet_supervisor_command",
        "runs",
    ):
        _required_pin(pins, field, context="immutable pins")
    if pins["release_id"] != PRODUCTION_RELEASE_ID:
        raise ImmutablePinError(
            f"release_id must be {PRODUCTION_RELEASE_ID!r}; schema-5 v1.1 "
            "and other downgrade identities are not production-authorized"
        )
    if re.fullmatch(r"[0-9a-f]{40}", str(pins["release_tag_object"])) is None:
        raise ImmutablePinError(
            "release_tag_object must pin the exact annotated Git tag object"
        )
    try:
        expected_transport_binding = (
            scheduler_safety.validate_transport_uncertainty_binding(
                pins["transport_uncertainty_binding"]
            )
        )
        expected_transport_sha256 = (
            scheduler_safety.transport_uncertainty_binding_sha256(
                expected_transport_binding
            )
        )
    except scheduler_safety.SchedulerSafetyError as exc:
        raise ImmutablePinError(
            "immutable transport/checkpoint/self-consistency binding is invalid: "
            f"{exc}"
        ) from exc
    if (
        pins["transport_uncertainty_binding_sha256"]
        != expected_transport_sha256
    ):
        raise ImmutablePinError(
            "immutable transport-uncertainty binding digest drifted"
        )
    _validate_conda_toolchain_binding_static(pins["conda_toolchain"])
    _validate_package_cache_seed_input_binding(
        pins["package_cache_seed_input"]
    )
    if (
        _SHA256_RE.fullmatch(
            str(pins["conda_package_cache_seed_sha256"])
        )
        is None
    ):
        raise ImmutablePinError(
            "immutable Conda package-cache seed digest is invalid"
        )
    if not isinstance(pins["dispatcher_command"], list) or not all(
        isinstance(item, str) and item for item in pins["dispatcher_command"]
    ):
        raise ImmutablePinError("dispatcher_command must be a non-empty argv array")
    if not isinstance(pins["fleet_supervisor_command"], list) or not all(
        isinstance(item, str) and item for item in pins["fleet_supervisor_command"]
    ):
        raise ImmutablePinError(
            "fleet_supervisor_command must be a non-empty argv array"
        )
    for command_field in ("dispatcher_command", "fleet_supervisor_command"):
        command = pins[command_field]
        executable = Path(pins[command_field][0]).expanduser()
        if not executable.is_absolute():
            raise ImmutablePinError(
                f"{command_field} must pin an absolute executable, found {executable}"
            )
        if verify_files and not executable.is_file():
            raise ImmutablePinError(
                f"{command_field} executable is missing: {executable}"
            )
        if any(
            item == "--successor-sbatch" or "loop_keepalive.sbatch" in item
            for item in command
        ):
            raise ImmutablePinError(
                f"{command_field} must not create a competing legacy successor chain"
            )
        release_root = Path(str(pins["release_worktree"])).expanduser().resolve()
        for item in command[1:]:
            if not item.endswith((".py", ".sh")):
                continue
            script = Path(item).expanduser()
            if not script.is_absolute():
                raise ImmutablePinError(
                    f"{command_field} script arguments must be absolute: {item}"
                )
            try:
                script.resolve().relative_to(release_root)
            except ValueError as exc:
                raise ImmutablePinError(
                    f"{command_field} executes outside frozen release: {script}"
                ) from exc
            if verify_files and not script.is_file():
                raise ImmutablePinError(
                    f"pinned controller script is missing: {script}"
                )

    by_id = _run_pins_by_id(pins)
    runs = pins["runs"]
    if set(by_id) != set(REQUIRED_RUNS):
        raise ImmutablePinError(
            f"schema-5 run pins must be exactly {sorted(REQUIRED_RUNS)}, found {sorted(by_id)}"
        )
    for run_id, expected_cells in REQUIRED_RUNS.items():
        run = by_id[run_id]
        for field in (
            "run_root",
            "manifest_path",
            "manifest_sha256",
            "lineage_path",
            "lineage_sha256",
            "policy_path",
            "policy_sha256",
            "benchmark_contract_path",
            "benchmark_contract_sha256",
        ):
            _required_pin(run, field, context=f"run pin {run_id}")
        if run.get("cell_count") != expected_cells:
            raise ImmutablePinError(
                f"run {run_id} must pin {expected_cells} cells, found {run.get('cell_count')!r}"
            )
        if run.get("expected_qids") != REQUIRED_RUN_QIDS[run_id]:
            raise ImmutablePinError(
                f"run {run_id} must pin {REQUIRED_RUN_QIDS[run_id]} benchmark QIDs"
            )
        if (
            type(run.get("weight")) not in {int, float}
            or float(run["weight"]) != RUN_WEIGHT
        ):
            raise ImmutablePinError(f"run {run_id} weight must be exactly {RUN_WEIGHT}")

    if sum(int(run["cell_count"]) for run in runs) != EXPECTED_TOTAL_CELLS:
        raise ImmutablePinError("immutable runs do not total exactly 22,680 cells")
    if sum(int(run["expected_qids"]) for run in runs) != EXPECTED_TOTAL_QIDS:
        raise ImmutablePinError("immutable runs do not total exactly 4,524,660 QIDs")
    results_root = Path(str(pins["results_root"])).expanduser().resolve()
    expected_pool = results_root / "server_pools" / "schema5-v1"
    if Path(str(pins["server_pool_root"])).expanduser().resolve() != expected_pool:
        raise ImmutablePinError(f"canonical server pool must be {expected_pool}")
    expected_capacity_marker = protected_capacity.canonical_marker_path(results_root)
    if (
        Path(str(pins["protected_capacity_marker_path"]))
        .expanduser()
        .resolve()
        != expected_capacity_marker
        or _SHA256_RE.fullmatch(
            str(pins["protected_capacity_marker_sha256"])
        )
        is None
        or _SHA256_RE.fullmatch(str(pins["protected_capacity_marker_id"])) is None
    ):
        raise ImmutablePinError(
            "protected-capacity pins do not bind the canonical sealed marker"
        )
    if (
        not isinstance(pins["protected_client_partition"], str)
        or not pins["protected_client_partition"]
        or not isinstance(pins["protected_client_qos"], str)
        or not pins["protected_client_qos"]
        or not isinstance(pins["protected_client_slots"], int)
        or isinstance(pins["protected_client_slots"], bool)
        or pins["protected_client_slots"] < PRODUCTION_DESIGN_CELL_CAP
        or not isinstance(pins["protected_client_cpus"], int)
        or isinstance(pins["protected_client_cpus"], bool)
        or pins["protected_client_cpus"] < PRODUCTION_DESIGN_CELL_CAP
        or not isinstance(pins["protected_client_memory_mib"], int)
        or isinstance(pins["protected_client_memory_mib"], bool)
        or pins["protected_client_memory_mib"]
        < PRODUCTION_DESIGN_CELL_CAP * 4096
        or not isinstance(pins["protected_client_reserve_jobs"], int)
        or isinstance(pins["protected_client_reserve_jobs"], bool)
        or pins["protected_client_reserve_jobs"] < 64
        or not isinstance(pins["protected_client_submit_headroom"], int)
        or isinstance(pins["protected_client_submit_headroom"], bool)
        or pins["protected_client_submit_headroom"]
        < PRODUCTION_DESIGN_CELL_CAP + 64
    ):
        raise ImmutablePinError(
            "protected client pins do not authorize the full 384-cell "
            "production design plus the 64-job reserve"
        )
    for run_id, run in by_id.items():
        run_root = Path(str(run["run_root"])).expanduser().resolve()
        if run_root != results_root / run_id:
            raise ImmutablePinError(
                f"run {run_id} must live directly below the pinned results root"
            )
        expected_paths = {
            "manifest_path": run_root / "cells.json",
            "lineage_path": run_root / "lineage.schema5-v1.json",
            "policy_path": run_root / "artifact_policy.schema5-v1.json",
            "benchmark_contract_path": run_root / "benchmark_contracts.v1.json",
        }
        for field, expected_path in expected_paths.items():
            if Path(str(run[field])).expanduser().resolve() != expected_path:
                raise ImmutablePinError(f"run {run_id} {field} must be {expected_path}")
    if pins["dispatcher_command"] != expected_dispatcher_command(pins):
        raise ImmutablePinError(
            "dispatcher_command differs from the exact schema-5 topology command"
        )
    if pins["fleet_supervisor_command"] != expected_fleet_supervisor_command(pins):
        raise ImmutablePinError(
            "fleet_supervisor_command differs from the exact schema-5 topology command"
        )

    if not verify_files:
        return
    _validate_release_bundle(pins)
    for directory_field in (
        "release_bundle_root",
        "release_worktree",
        "harness_environment_prefix",
        "serving_environment_prefix",
        "hf_home",
        "results_root",
        "server_pool_root",
    ):
        path = Path(str(pins[directory_field])).expanduser().resolve()
        if not path.is_dir():
            raise ImmutablePinError(
                f"pinned directory is missing: {directory_field}={path}"
            )
    release_tree = Path(str(pins["release_worktree"])).expanduser().resolve()
    observed_source_hash = sha256_tree(release_tree)
    if observed_source_hash != pins["source_tree_sha256"]:
        raise ImmutablePinError(
            "frozen release source tree drifted: "
            f"expected {pins['source_tree_sha256']}, got {observed_source_hash}"
        )
    harness_python = Path(str(pins["harness_environment_prefix"])) / "bin" / "python"
    if not harness_python.is_file():
        raise ImmutablePinError(f"pinned harness Python is missing: {harness_python}")
    for release_relative in (
        Path("slurm") / "dispatch_sweeps.py",
        Path("slurm") / "run_dispatch_batch.sbatch.tmpl",
    ):
        release_artifact = release_tree / release_relative
        if not release_artifact.is_file():
            raise ImmutablePinError(
                f"pinned release is missing production cell runtime artifact: "
                f"{release_artifact}"
            )
    # Creation-time freezing proves the exact clean tag and records its commit.  A
    # materialized worktree's ``.git`` file may point back to the mutable source clone,
    # which is intentionally disposable after publication.  Runtime authority is the
    # sealed tree bytes above plus the marker-bound stored commit, never that mutable
    # Git administrative target.  This also prevents source-repository deletion from
    # taking a valid production release offline.
    file_pairs = [
        (pins["model_contract_path"], pins["model_contract_sha256"]),
        (pins["fleet_contract_path"], pins["fleet_contract_sha256"]),
        (
            pins["protected_capacity_marker_path"],
            pins["protected_capacity_marker_sha256"],
        ),
        (
            pins["harness_environment_manifest_path"],
            pins["harness_environment_sha256"],
        ),
        (
            pins["serving_environment_manifest_path"],
            pins["serving_environment_sha256"],
        ),
    ]
    for run in runs:
        file_pairs.extend(
            (run[f"{kind}_path"], run[f"{kind}_sha256"])
            for kind in ("manifest", "lineage", "policy", "benchmark_contract")
        )
    for path_value, expected_hash in file_pairs:
        path = Path(str(path_value)).expanduser().resolve()
        if not path.is_file():
            raise ImmutablePinError(f"pinned artifact is missing: {path}")
        observed = sha256_file(path)
        if observed != expected_hash:
            raise ImmutablePinError(
                f"pinned artifact drifted: {path}; expected {expected_hash}, got {observed}"
            )
    try:
        capacity_contract = _load_immutable_protected_capacity_contract(
            pins
        )
        model_contracts = load_model_contracts(
            pins["model_contract_path"],
            expected_sha256=pins["model_contract_sha256"],
        )
        frozen_fleet = load_fleet_contract(
            capacity_contract.effective_fleet_contract_path,
            model_contracts=model_contracts,
            expected_sha256=(
                capacity_contract.effective_fleet_contract_sha256
            ),
            allow_capacity_layout=True,
        )
        protected_capacity.authorize_fleet(frozen_fleet, capacity_contract)
        protected_client = protected_capacity.authorize_client(
            capacity_contract,
            partition=str(pins["protected_client_partition"]),
            qos=str(pins["protected_client_qos"]),
            required_slots=PRODUCTION_DESIGN_CELL_CAP,
            required_reserve_jobs=64,
        )
        expected_client_capacity = {
            "slots": int(pins["protected_client_slots"]),
            "cpus": int(pins["protected_client_cpus"]),
            "memory_mib": int(pins["protected_client_memory_mib"]),
            "reserve_jobs": int(pins["protected_client_reserve_jobs"]),
            "submit_headroom": int(pins["protected_client_submit_headroom"]),
        }
        if dict(protected_client.capacity) != expected_client_capacity:
            raise protected_capacity.ProtectedCapacityError(
                "protected client placement capacity differs from immutable pins"
            )
    except (
        FleetContractError,
        ModelContractError,
        protected_capacity.ProtectedCapacityError,
    ) as exc:
        raise ImmutablePinError(
            f"scientific fleet is not covered by protected capacity: {exc}"
        ) from exc
    for run_id, run in by_id.items():
        run_root = Path(str(run["run_root"])).resolve()
        for artifact_field, checksum_name in (
            ("manifest_path", "cells.sha256"),
            ("lineage_path", "lineage.schema5-v1.sha256"),
            ("policy_path", "artifact_policy.schema5-v1.sha256"),
            ("benchmark_contract_path", "benchmark_contracts.v1.sha256"),
        ):
            artifact = Path(str(run[artifact_field])).resolve()
            _validate_checksum_sidecar(
                run_root / checksum_name,
                artifact.name,
                str(run[artifact_field.replace("_path", "_sha256")]),
            )
        derived_qids = _benchmark_derived_qids(run)
        if derived_qids != REQUIRED_RUN_QIDS[run_id]:
            raise ImmutablePinError(
                f"run {run_id} benchmark-derived QIDs are {derived_qids}, "
                f"expected {REQUIRED_RUN_QIDS[run_id]}"
            )
    try:
        fleet_payload = json.loads(
            Path(str(pins["fleet_contract_path"])).read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ImmutablePinError(f"cannot parse fleet contract: {exc}") from exc
    if not isinstance(fleet_payload, dict):
        raise ImmutablePinError("fleet contract must be an object")
    if (
        fleet_payload.get("fleet_id") != "schema5-v1"
        or fleet_payload.get("release_id") != pins["release_id"]
        or fleet_payload.get("logical_replica_count") != 22
        or fleet_payload.get("allocated_gpu_count") != 24
        or fleet_payload.get("model_contract_sha256") != pins["model_contract_sha256"]
        or fleet_payload.get("server_pool", {}).get("root_suffix")
        != "server_pools/schema5-v1"
        or fleet_payload.get("server_pool", {}).get("no_requeue") is not True
    ):
        raise ImmutablePinError(
            "fleet contract does not encode the canonical 22/24 topology"
        )


def load_control(state_dir: Path, *, verify_files: bool = False) -> dict[str, Any]:
    path = _state_path(state_dir)
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ControlError(f"schema-5 control is not initialized: {path}") from exc
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ControlError(f"cannot read schema-5 control {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise ControlError("schema-5 control must be a JSON object")
    if value.get("schema_version") != CONTROL_SCHEMA_VERSION:
        raise ControlError(
            f"unsupported control schema {value.get('schema_version')!r}; "
            f"expected {CONTROL_SCHEMA_VERSION}"
        )
    if value.get("protocol") != CONTROL_PROTOCOL:
        raise ControlError(f"unexpected control protocol {value.get('protocol')!r}")
    immutable = value.get("immutable")
    if not isinstance(immutable, dict):
        raise ImmutablePinError("control immutable pins are missing")
    if value.get("immutable_sha256") != sha256_value(immutable):
        raise ImmutablePinError("control immutable pin digest is invalid")
    pins_path = state_dir / IMMUTABLE_PINS_FILENAME
    try:
        if (
            pins_path.is_symlink()
            or not pins_path.is_file()
            or pins_path.stat().st_nlink != 1
            or pins_path.stat().st_mode & 0o222
        ):
            raise ImmutablePinError(
                f"frozen immutable pin copy is not a sealed single-link file: {pins_path}"
            )
        frozen_pins = json.loads(pins_path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ImmutablePinError(
            f"frozen immutable pin copy is missing: {pins_path}"
        ) from exc
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ImmutablePinError(
            f"cannot read frozen immutable pins {pins_path}: {exc}"
        ) from exc
    if (
        frozen_pins != immutable
        or sha256_value(frozen_pins) != value["immutable_sha256"]
    ):
        raise ImmutablePinError(
            "control immutable pins differ from the frozen pin copy"
        )
    validate_immutable_pins(immutable, verify_files=verify_files)
    _validate_admission(value.get("admission", {}))
    _validate_admission_safety_hold(value, value.get("admission_safety_hold"))
    _validate_safety_hold_drain_intent(
        value.get("safety_hold_drain_intent")
    )
    _validate_capacity_state(value.get("capacity"))
    _validate_monitoring_state(value.get("monitoring"))
    _validate_finalization_state(value, value.get("finalization"))
    if (
        verify_files
        and value["finalization"].get("request_intent") is not None
    ):
        _verify_finalization_request_intent(value)
    if (
        verify_files
        and isinstance(value["finalization"].get("successor_retirement"), dict)
    ):
        _verify_successor_retirement_artifacts(
            value,
            value["finalization"]["successor_retirement"],
        )
    if value["finalization"]["state"] == "complete":
        _verify_completed_finalization_control_binding(value)
    _validate_admission_ramp(value, value.get("admission_ramp"))
    validate_transition_history(value)
    journal_path = state_dir / TRANSITION_JOURNAL
    try:
        journal_records = _read_jsonl_locked(journal_path)
    except FileNotFoundError as exc:
        raise ControlError(
            f"append-only transition journal is missing: {journal_path}"
        ) from exc
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ControlError(
            f"cannot validate transition journal {journal_path}: {exc}"
        ) from exc
    history = value["transition_history"]
    if (
        len(journal_records) < len(history)
        or journal_records[: len(history)] != history
    ):
        raise ControlError(
            "control transition history is not a prefix of its durable journal"
        )
    if value.get("desired_state") not in {"paused", "resuming", "running"}:
        raise ControlError("desired_state must be paused, resuming, or running")
    if (
        not isinstance(value.get("rollout_generation"), int)
        or value["rollout_generation"] < 0
    ):
        raise ControlError("rollout_generation must be a non-negative integer")
    if value["rollout_generation"] >= 1:
        validate_runtime_integrity_attestation(value, verify_metadata=False)
        validate_snapshot_integrity_attestation(
            value, state_dir=state_dir, verify_lease=False
        )
    else:
        if value.get(RUNTIME_ATTESTATION_STATE_KEY) is not None:
            raise ImmutablePinError(
                "generation-zero control must not claim a runtime integrity attestation"
            )
        if value.get(SNAPSHOT_ATTESTATION_STATE_KEY) is not None:
            if value.get("desired_state") != "paused" or value.get("drain_requested"):
                raise ReadinessError(
                    "generation-zero snapshot preseal requires paused non-draining control"
                )
            validate_snapshot_integrity_attestation(
                value, state_dir=state_dir, verify_lease=False
            )
    for gate in (*REQUIRED_GATES, *PRODUCTION_AUTHORIZATION_GATES):
        if gate not in value.get("readiness", {}):
            raise ControlError(f"readiness gate {gate!r} is missing")
    _validate_production_authorization_state(
        value,
        state_dir=state_dir,
        require_passed=value.get("desired_state") in {"resuming", "running"},
        verify_files=verify_files,
    )
    for role in ROLE_NAMES:
        if role not in value.get("controllers", {}):
            raise ControlError(f"controller state for {role!r} is missing")
    resume_intent = value.get("resume_intent")
    if value.get("desired_state") == "resuming" and not isinstance(resume_intent, dict):
        raise ControlError("resuming desired state requires a durable resume_intent")
    if value.get("desired_state") in {"resuming", "running"}:
        _validate_resume_production_authorizations(value)
    if value.get("desired_state") == "running":
        if (
            not isinstance(resume_intent, dict)
            or resume_intent.get("state") != "complete"
        ):
            raise ControlError(
                "running desired state requires a complete resume transaction"
            )
        resume_ids = resume_intent.get("controller_job_ids")
        visible_ids = resume_intent.get("scheduler_visible_job_ids")
        if (
            not isinstance(resume_ids, dict)
            or set(resume_ids) != set(ROLE_NAMES)
            or not all(str(resume_ids[role]).isdigit() for role in ROLE_NAMES)
            or visible_ids != resume_ids
        ):
            raise ControlError(
                "running resume transaction does not bind both scheduler-visible controllers"
            )
    return value


def initialize_control(
    state_dir: Path,
    *,
    pins: Mapping[str, Any],
    alert_email: str = "mabdel03@mit.edu",
    now: float | None = None,
) -> dict[str, Any]:
    """Create the paused control atomically, or prove an existing init is identical."""
    state_dir = state_dir.expanduser().resolve()
    timestamp = time.time() if now is None else float(now)
    validate_immutable_pins(pins, verify_files=True)
    state_dir.mkdir(parents=True, exist_ok=True)
    (state_dir / "logs").mkdir(parents=True, exist_ok=True)
    (state_dir / "sbatch").mkdir(parents=True, exist_ok=True)
    (state_dir / "locks").mkdir(parents=True, exist_ok=True)
    with control_lock(state_dir):
        if _state_path(state_dir).exists():
            existing = load_control(state_dir, verify_files=True)
            if existing["immutable_sha256"] != sha256_value(pins):
                raise ImmutablePinError(
                    "init is idempotent only for exactly the existing immutable pins"
                )
            _ensure_bootstrap_dispatcher_ledger(
                state_dir,
                timestamp=float(existing["created_timestamp"]),
                require_empty=(
                    existing["desired_state"] == "paused"
                    and int(existing["rollout_generation"]) == 0
                ),
            )
            return existing
        durable_history = _read_jsonl_locked(
            state_dir / TRANSITION_JOURNAL, missing_ok=True
        )
        if durable_history:
            if (
                len(durable_history) != 1
                or not isinstance(durable_history[0].get("timestamp"), (int, float))
            ):
                raise ControlError(
                    "transition journal exists without control.json and is not an "
                    "exact recoverable init preimage"
                )
            timestamp = float(durable_history[0]["timestamp"])
        control: dict[str, Any] = {
            "schema_version": CONTROL_SCHEMA_VERSION,
            "protocol": CONTROL_PROTOCOL,
            "created_at": utc_timestamp(timestamp),
            "created_timestamp": timestamp,
            "updated_at": utc_timestamp(timestamp),
            "updated_timestamp": timestamp,
            "immutable": copy.deepcopy(dict(pins)),
            "immutable_sha256": sha256_value(pins),
            "admission": copy.deepcopy(DEFAULT_ADMISSION),
            "admission_safety_hold": _new_admission_safety_hold(
                configured_ceiling=int(DEFAULT_ADMISSION["current_ceiling"])
            ),
            "safety_hold_drain_intent": None,
            "capacity": _new_capacity_state(),
            "admission_ramp": _new_admission_ramp_state(
                rollout_generation=0,
                current_ceiling=int(DEFAULT_ADMISSION["current_ceiling"]),
                reason="initialized_paused",
                now=timestamp,
            ),
            "desired_state": "paused",
            "drain_requested": False,
            "drain_intent": None,
            "rollout_generation": 0,
            RUNTIME_ATTESTATION_STATE_KEY: None,
            SNAPSHOT_ATTESTATION_STATE_KEY: None,
            "resume_intent": None,
            "readiness": {
                gate: {"passed": False, "evidence": None, "attested_at": None}
                for gate in (*REQUIRED_GATES, *PRODUCTION_AUTHORIZATION_GATES)
            },
            "controllers": {
                role: {
                    "next_generation": 1,
                    "active": None,
                    "successor": None,
                    "submission_intent": None,
                    "last_exit": None,
                    "heartbeat": None,
                }
                for role in ROLE_NAMES
            },
            "transition_history": [],
            "throughput_epochs": [],
            "monitoring": {
                "owner_role": MONITOR_OWNER_ROLE,
                "cadences": {
                    cadence: {
                        "interval_seconds": interval,
                        # A newly resumed chain performs each monitor immediately.  A
                        # successful attempt advances this durable deadline; controller
                        # successors never reset it.
                        "next_due_at": utc_timestamp(timestamp),
                        "next_due_timestamp": timestamp,
                        "last_attempt_at": None,
                        "last_attempt_timestamp": None,
                        "last_success_at": None,
                        "last_success_timestamp": None,
                        "last_failure_at": None,
                        "last_failure_timestamp": None,
                        "last_returncode": None,
                        "last_error": None,
                        "consecutive_failures": 0,
                        "active_attempt": None,
                    }
                    for cadence, interval in MONITOR_CADENCE_SECONDS.items()
                },
            },
            "finalization": _new_finalization_state(pins, now=timestamp),
            "alerts": [],
            "alert_email": alert_email,
            "last_reconciliation": None,
        }
        init_details = {
            "immutable_sha256": control["immutable_sha256"],
            "alert_email": alert_email,
        }
        if durable_history:
            expected_record = _history_record(
                control,
                event="initialized_paused",
                details=init_details,
                now=timestamp,
            )
            if durable_history != [expected_record]:
                raise ControlError(
                    "transition journal exists without control.json and conflicts "
                    "with the requested immutable init"
                )
            control["transition_history"] = copy.deepcopy(durable_history)
            validate_transition_history(control)
        else:
            append_transition(
                state_dir,
                control,
                event="initialized_paused",
                details=init_details,
                now=timestamp,
            )
        _ensure_bootstrap_dispatcher_ledger(
            state_dir,
            timestamp=timestamp,
            require_empty=True,
        )
        pins_path = state_dir / IMMUTABLE_PINS_FILENAME
        if pins_path.exists() or pins_path.is_symlink():
            if (
                pins_path.is_symlink()
                or not pins_path.is_file()
                or pins_path.stat().st_nlink != 1
                or pins_path.stat().st_mode & 0o222
            ):
                raise ImmutablePinError(
                    "recoverable init immutable pins are not a sealed single-link file"
                )
            try:
                existing_pins = json.loads(pins_path.read_text(encoding="utf-8"))
            except (OSError, UnicodeError, json.JSONDecodeError) as exc:
                raise ImmutablePinError(
                    f"cannot validate recoverable init immutable pins: {exc}"
                ) from exc
            if existing_pins != dict(pins):
                raise ImmutablePinError(
                    "recoverable init immutable pins conflict with the requested pins"
                )
        else:
            _atomic_publish_readonly_json(pins_path, dict(pins))
        _atomic_write_json(_state_path(state_dir), control)
        return control


def _ensure_bootstrap_dispatcher_ledger(
    state_dir: Path,
    *,
    timestamp: float,
    require_empty: bool,
) -> None:
    """Create/recover the canonical empty ledger before any running generation."""

    from slurm.dispatch_sweeps import _empty_ledger, validate_ledger_structure

    ledger_path = state_dir / "ledger.json"
    expected = _empty_ledger(now=float(timestamp))
    if not os.path.lexists(ledger_path):
        if not require_empty:
            raise ControlError(
                "initialized control lacks its canonical dispatcher ledger"
            )
        _atomic_write_json(ledger_path, expected)
    try:
        _raw, observed = _stable_mutable_json_preimage(
            ledger_path,
            required_parent=state_dir,
            description="bootstrap dispatcher ledger",
        )
        observed = validate_ledger_structure(
            observed, source=str(ledger_path)
        )
    except Exception as exc:
        raise ControlError(
            f"bootstrap dispatcher ledger is unsafe: {exc}"
        ) from exc
    if require_empty and observed != expected:
        raise ControlError(
            "paused rollout-zero control has a nonempty or conflicting "
            "dispatcher ledger"
        )


def _save_control(
    state_dir: Path, control: MutableMapping[str, Any], *, now: float
) -> None:
    control["updated_at"] = utc_timestamp(now)
    control["updated_timestamp"] = now
    # Refuse to persist mutation of any immutable pin or mandatory admission invariant.
    if control.get("immutable_sha256") != sha256_value(control.get("immutable")):
        raise ImmutablePinError("refusing to save mutated immutable pins")
    _validate_admission(control.get("admission", {}))
    if isinstance(control.get("admission_safety_hold"), dict):
        # ``configured_ceiling`` is a denormalized mirror of the staged ramp ceiling.
        # Keep private/test recovery mutations atomic with that source of truth.
        control["admission_safety_hold"]["configured_ceiling"] = int(
            control["admission"]["current_ceiling"]
        )
    _validate_admission_safety_hold(
        control, control.get("admission_safety_hold")
    )
    _validate_safety_hold_drain_intent(
        control.get("safety_hold_drain_intent")
    )
    _validate_capacity_state(control.get("capacity"))
    _validate_monitoring_state(control.get("monitoring"))
    _validate_finalization_state(control, control.get("finalization"))
    _validate_admission_ramp(control, control.get("admission_ramp"))
    validate_transition_history(control)
    _validate_production_authorization_state(
        control,
        state_dir=state_dir,
        require_passed=control.get("desired_state") in {"resuming", "running"},
        verify_files=False,
    )
    _atomic_write_json(_state_path(state_dir), control)


def _exact_keys(value: Mapping[str, Any], expected: set[str], *, context: str) -> None:
    observed = set(value)
    if observed != expected:
        raise ReadinessError(
            f"{context} fields differ: missing={sorted(expected - observed)}, "
            f"unexpected={sorted(observed - expected)}"
        )


def _exact_integer(value: Any, expected: int, *, context: str) -> None:
    if not isinstance(value, int) or isinstance(value, bool) or value != expected:
        raise ReadinessError(
            f"{context} must equal integer {expected}, found {value!r}"
        )


def _exact_boolean(value: Any, expected: bool, *, context: str) -> None:
    if not isinstance(value, bool) or value is not expected:
        raise ReadinessError(f"{context} must equal {expected!r}, found {value!r}")


def _validate_artifact_identity(
    control: Mapping[str, Any],
    payload: Mapping[str, Any] | None,
    *,
    name: str,
    exact_fields: set[str],
) -> Mapping[str, Any]:
    if not isinstance(payload, dict):
        raise ReadinessError(f"readiness artifact {name} must be a JSON object")
    _exact_keys(payload, exact_fields, context=f"readiness artifact {name}")
    if (
        payload.get("schema_version") != 1
        or payload.get("kind") != name
        or payload.get("passed") is not True
        or payload.get("immutable_sha256") != control["immutable_sha256"]
    ):
        raise ReadinessError(
            f"readiness artifact {name} has invalid schema, identity, pass state, or pins"
        )
    return payload


def _load_only_source_report(
    wrapper: Mapping[str, Any],
    *,
    expected_name: str,
    snapshot_context: _SnapshotValidationContext,
) -> Mapping[str, Any]:
    references = wrapper.get("referenced_artifacts")
    if not isinstance(references, list) or len(references) != 1:
        raise ReadinessError(
            f"{wrapper.get('kind')} must reference exactly one source report"
        )
    reference = references[0]
    if not isinstance(reference, dict) or reference.get("name") != expected_name:
        raise ReadinessError(
            f"{wrapper.get('kind')} must reference source {expected_name!r}"
        )
    _, payload = _validate_referenced_artifact(
        reference,
        context=f"{wrapper.get('kind')} source report",
        verified=set(),
        active=set(),
        snapshot_context=snapshot_context,
    )
    if not isinstance(payload, dict):
        raise ReadinessError(f"source report {expected_name!r} must be a JSON object")
    return payload


def _validate_migration_artifacts(
    control: Mapping[str, Any],
    metrics: Mapping[str, Any],
    artifacts: Mapping[str, tuple[Path, Mapping[str, Any] | None]],
    *,
    snapshot_context: _SnapshotValidationContext,
) -> None:
    contracts = {
        "response_incident_archive_report": (
            "consolidated_response_report",
            {
                "protocol_incidents_total": 22,
                "protocol_already_reset": 22,
                "sealed_incident_qids": 1_064,
            },
        ),
        "checkpoint_migration_report": (
            "consolidated_checkpoint_report",
            {
                "migrated_checkpoints": 47,
                "remaining_schema1_checkpoints": 0,
                "coordinates_preserved": True,
            },
        ),
        "permanent_ledger_archive_report": (
            "consolidated_permanent_report",
            {
                "permanent_ledgers_archived": 3,
                "unresolved_permanent_ledgers": 0,
            },
        ),
    }
    for name, (source_name, expected) in contracts.items():
        wrapper = _validate_artifact_identity(
            control,
            artifacts[name][1],
            name=name,
            exact_fields={
                "schema_version",
                "kind",
                "passed",
                "immutable_sha256",
                "metrics",
                "referenced_artifacts",
            },
        )
        if wrapper.get("metrics") != expected:
            raise ReadinessError(f"{name} metrics do not match the recovery contract")
        source = _load_only_source_report(
            wrapper,
            expected_name=source_name,
            snapshot_context=snapshot_context,
        )
        if source.get("schema_version") != 1 or source.get("passed") is not True:
            raise ReadinessError(
                f"{source_name} did not report a valid passing recovery"
            )
        for key, value in expected.items():
            if source.get(key) != value:
                raise ReadinessError(
                    f"{source_name} {key} does not match its typed wrapper"
                )
            if key in metrics and metrics.get(key) != value:
                raise ReadinessError(
                    f"outer migration metric {key} is not artifact-derived"
                )


def _validate_semantic_artifact(
    control: Mapping[str, Any],
    metrics: Mapping[str, Any],
    artifacts: Mapping[str, tuple[Path, Mapping[str, Any] | None]],
    *,
    snapshot_context: _SnapshotValidationContext,
) -> None:
    name = "legacy_semantic_audit_report"
    wrapper = _validate_artifact_identity(
        control,
        artifacts[name][1],
        name=name,
        exact_fields={
            "schema_version",
            "kind",
            "passed",
            "immutable_sha256",
            "metrics",
            "referenced_artifacts",
        },
    )
    if wrapper.get("metrics") != dict(metrics):
        raise ReadinessError(
            "semantic audit wrapper metrics differ from the outer envelope"
        )
    source = _load_only_source_report(
        wrapper,
        expected_name="consolidated_semantic_report",
        snapshot_context=snapshot_context,
    )
    if (
        source.get("schema_version") != 1
        or source.get("kind") != "legacy_semantic_audit"
        or source.get("passed") is not True
        or source.get("manifest_cells") != EXPECTED_TOTAL_CELLS
        or source.get("invalid_rows") != 0
        or source.get("metrics") != dict(metrics)
    ):
        raise ReadinessError(
            "consolidated semantic report does not prove the exact baseline"
        )


def _validate_fleet_artifact(
    control: Mapping[str, Any],
    metrics: Mapping[str, Any],
    artifacts: Mapping[str, tuple[Path, Mapping[str, Any] | None]],
    *,
    snapshot_context: _SnapshotValidationContext,
) -> None:
    fleet_binding = effective_fleet_contract_binding(control, verify_files=True)
    name = "fleet_health_report"
    report = _validate_artifact_identity(
        control,
        artifacts[name][1],
        name=name,
        exact_fields={
            "schema_version",
            "kind",
            "passed",
            "immutable_sha256",
            "server_pool_root",
            "metrics",
            "referenced_artifacts",
        },
    )
    if report.get("server_pool_root") != str(
        Path(control["immutable"]["server_pool_root"]).resolve()
    ) or report.get("metrics") != dict(metrics):
        raise ReadinessError(
            "fleet health artifact differs from the pinned pool or envelope"
        )
    raw = _load_only_source_report(
        report,
        expected_name="raw_fleet_health_probe",
        snapshot_context=snapshot_context,
    )
    _exact_keys(
        raw,
        {
            "schema_version",
            "kind",
            "passed",
            "immutable_sha256",
            "server_pool_root",
            "rollout_generation",
            "isolated_foreign_scheduler_job_ids",
            "sealed_successful_handoff_terminal_job_ids",
            "ignored_terminal_job_ids",
            "client_capacity_contract",
            "fleet_scheduler_safety_evidence",
            "fleet_scheduler_safety_policy",
            "captured_timestamp",
            "replicas",
            "referenced_artifacts",
        },
        context="raw fleet health probe",
    )
    pool_root = str(Path(control["immutable"]["server_pool_root"]).resolve())
    try:
        transaction_directory = fleet_transactions.state_directory(pool_root)
        current_fleet = fleet_transactions._read_current_index_raw(  # noqa: SLF001
            transaction_directory
        )
        current_ledger = (
            None
            if current_fleet is None
            else Path(str(current_fleet["ledger_path"]))
        )
        current_fleet_valid = (
            isinstance(current_fleet, dict)
            and current_fleet.get("pool_root") == pool_root
            and current_fleet.get("pool_id") == "schema5-v1"
            and current_fleet.get("fleet_sha256") == fleet_binding["sha256"]
            and current_ledger is not None
            and current_ledger.is_file()
            and not current_ledger.is_symlink()
            and sha256_file(current_ledger) == current_fleet["ledger_sha256"]
        )
    except (OSError, fleet_transactions.FleetTransactionError):
        current_fleet = None
        current_fleet_valid = False
    if (
        raw.get("schema_version") != 3
        or raw.get("kind") != "raw_fleet_health_probe"
        or raw.get("passed") is not True
        or raw.get("immutable_sha256") != control["immutable_sha256"]
        or raw.get("server_pool_root") != pool_root
        or not isinstance(raw.get("rollout_generation"), int)
        or isinstance(raw.get("rollout_generation"), bool)
        or raw["rollout_generation"] < 1
        or raw["rollout_generation"]
        > int(control.get("rollout_generation", 0)) + 1
        or not current_fleet_valid
        or current_fleet.get("current_generation")
        != raw["rollout_generation"]
        or raw.get("ignored_terminal_job_ids") != []
        or raw.get("captured_timestamp") != metrics.get("captured_timestamp")
    ):
        raise ReadinessError("raw fleet health probe identity differs from its wrapper")
    try:
        transport_binding = (
            scheduler_safety.validate_transport_uncertainty_binding(
                control["immutable"]["transport_uncertainty_binding"]
            )
        )
        transport_binding_sha256 = (
            scheduler_safety.transport_uncertainty_binding_sha256(
                transport_binding
            )
        )
        if (
            control["immutable"][
                "transport_uncertainty_binding_sha256"
            ]
            != transport_binding_sha256
        ):
            raise scheduler_safety.SchedulerSafetyError(
                "immutable transport binding digest drifted"
            )
        effective_fleet = load_effective_fleet_contract(
            control, verify_files=True
        )
        partition_time_requirements = (
            scheduler_safety.fleet_partition_time_requirements(
                effective_fleet.replicas
            )
        )
        scheduler_policy = (
            scheduler_safety.validate_scheduler_safety_evidence(
                raw.get("fleet_scheduler_safety_evidence", {}),
                expected_partitions=list(partition_time_requirements),
                required_time_limits_seconds=partition_time_requirements,
            )
        )
    except (ImmutablePinError, scheduler_safety.SchedulerSafetyError) as exc:
        raise ReadinessError(
            f"fleet scheduler-safety evidence failed closed: {exc}"
        ) from exc
    if (
        raw.get("fleet_scheduler_safety_policy") != scheduler_policy
        or metrics.get("transport_censor_protocol_version")
        != transport_binding["transport_censor_protocol_version"]
        or metrics.get("transport_censor_protocol_hash")
        != transport_binding["transport_censor_protocol_hash"]
        or metrics.get("transport_uncertainty_binding_sha256")
        != transport_binding_sha256
        or metrics.get("scheduler_safety_evidence_id")
        != scheduler_policy["scheduler_evidence_id"]
        or metrics.get("scheduler_safety_policy_id")
        != scheduler_policy["policy_id"]
        or metrics.get("scheduler_safety_policy_contract_id")
        != scheduler_policy["policy_contract_id"]
        or metrics.get("scheduler_preemptible_partitions")
        != scheduler_policy["preemptible_partitions"]
        or metrics.get(
            "scheduler_partition_time_requirements_seconds"
        )
        != partition_time_requirements
    ):
        raise ReadinessError(
            "fleet wrapper scheduler/transport metrics differ from raw evidence"
        )
    try:
        capacity_authority = effective_protected_capacity_binding(
            control, verify_files=True
        )
        capacity_contract = _load_protected_capacity_contract(
            control,
            path=capacity_authority["path"],
            expected_marker_id=str(capacity_authority["marker_id"]),
            expected_sha256=str(capacity_authority["sha256"]),
        )
        client_capacity_summary = (
            protected_capacity.validate_live_client_capacity_evidence(
                capacity_contract,
                raw.get("client_capacity_contract", {}),
                partition=str(
                    control["immutable"]["protected_client_partition"]
                ),
                qos=str(
                    control["immutable"]["protected_client_qos"]
                ),
                required_time_limit_seconds=(
                    scheduler_safety.CLIENT_JOB_TIME_LIMIT_SECONDS
                ),
            )
        )
    except (
        scheduler_safety.SchedulerSafetyError,
        protected_capacity.ProtectedCapacityError,
    ) as exc:
        raise ReadinessError(
            f"fleet client partition/QOS evidence failed closed: {exc}"
        ) from exc
    if (
        metrics.get("client_capacity_evidence_id")
        != client_capacity_summary["evidence_id"]
        or metrics.get("client_partition")
        != client_capacity_summary["partition"]
        or metrics.get("client_qos")
        != client_capacity_summary["qos"]
        or metrics.get("client_cpu_limit") != client_capacity_summary["cpu_limit"]
        or metrics.get("client_memory_limit_mib")
        != client_capacity_summary["memory_limit_mib"]
        or metrics.get("client_max_submit_jobs")
        != client_capacity_summary["max_submit_jobs"]
    ):
        raise ReadinessError(
            "fleet wrapper metrics differ from client partition/QOS evidence"
        )
    rows = raw.get("replicas")
    references = raw.get("referenced_artifacts")
    expected_count = int(fleet_binding["logical_replicas"])
    if not isinstance(rows, list) or len(rows) != expected_count:
        raise ReadinessError(
            "raw fleet health probe must contain the effective replica count"
        )
    if not isinstance(references, list) or len(references) != expected_count:
        raise ReadinessError(
            "raw fleet health probe must bind the effective registrations"
        )
    scheduler_history_sets: list[set[str]] = []
    for field in (
        "isolated_foreign_scheduler_job_ids",
        "sealed_successful_handoff_terminal_job_ids",
    ):
        values = raw.get(field)
        if (
            not isinstance(values, list)
            or any(not isinstance(value, str) or not value.isdigit() for value in values)
            or values != sorted(set(values), key=int)
        ):
            raise ReadinessError(
                f"raw fleet health probe has invalid {field}"
            )
        scheduler_history_sets.append(set(values))
    if scheduler_history_sets[0].intersection(scheduler_history_sets[1]):
        raise ReadinessError(
            "raw fleet health probe canary and handoff histories overlap"
        )
    reference_by_name = {
        reference.get("name"): reference
        for reference in references
        if isinstance(reference, dict)
    }
    if len(reference_by_name) != expected_count:
        raise ReadinessError("raw fleet registration references are not unique")

    try:
        fleet_contract = json.loads(
            Path(str(fleet_binding["path"])).read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReadinessError(f"cannot parse pinned fleet topology: {exc}") from exc
    expected_replicas: dict[str, dict[str, Any]] = {}
    for profile in (
        fleet_contract.get("profiles", []) if isinstance(fleet_contract, dict) else []
    ):
        if not isinstance(profile, dict) or not isinstance(
            profile.get("replicas"), list
        ):
            raise ReadinessError("pinned fleet topology contains a malformed profile")
        for replica in profile["replicas"]:
            if not isinstance(replica, dict) or not isinstance(
                replica.get("replica_id"), str
            ):
                raise ReadinessError(
                    "pinned fleet topology contains a malformed replica"
                )
            serving_profile = str(profile.get("serving_profile"))
            runtime_profile = get_serving_profile(serving_profile)
            expected_replicas[replica["replica_id"]] = {
                "serving_profile": serving_profile,
                "model_size": profile.get("model_size"),
                "hf_id": runtime_profile.hf_id,
                "served_model_name": runtime_profile.served_model_name,
                "max_model_len": runtime_profile.max_model_len,
                "tp_size": runtime_profile.tp_size,
                "partition": replica.get("partition"),
                "scheduler_job_name": replica.get("scheduler_job_name"),
                "replica_index": replica.get("replica_index"),
                "model_revision": profile.get("model_revision"),
                "tokenizer_id": profile.get("tokenizer_id"),
                "tokenizer_revision": profile.get("tokenizer_revision"),
            }
    if len(expected_replicas) != expected_count:
        raise ReadinessError(
            "effective fleet topology has the wrong replica cardinality"
        )

    observed_ids: set[str] = set()
    profile_counts: dict[str, int] = {}
    probe_ages: list[float] = []
    replica_fields = {
        "replica_id",
        "serving_profile",
        "ledger_generation",
        "intent_token",
        "attempt_state",
        "slurm_job_id",
        "comment",
        "job_name",
        "partition",
        "node",
        "host",
        "port",
        "spooled_provenance",
        "local_script_path",
        "local_script_sha256",
        "spooled_script_sha256",
        "spooled_script_proof",
        "scontrol",
        "http",
        "probe_transport_provenance",
        "registry_path",
        "registry_sha256",
    }
    provenance_fields = {
        "run_root",
        "server_pool_id",
        "replica_id",
        "replica_index",
        "release_id",
        "environment_hash",
        "model_revision",
        "tokenizer_id",
        "tokenizer_revision",
        "model_contract_sha256",
        "fleet_contract_sha256",
        "release_fleet_contract_sha256",
        "capacity_generation",
        "rollout_generation",
        "spooled_script_sha256",
    }
    http_fields = {
        "health_status",
        "models_status",
        "model_ids",
        "expected_model",
        "probe_started_timestamp",
        "probe_completed_timestamp",
        "healthy",
    }
    scontrol_fields = {
        "argv",
        "job_id",
        "job_state",
        "reason",
        "comment",
        "job_name",
        "node",
        "command",
        "effective_requeue",
        "raw_output",
        "raw_output_sha256",
    }
    spool_fields = {
        "argv",
        "local_path",
        "local_sha256",
        "observed_sha256",
        "observed_bytes",
        "exact_match",
    }
    captured = float(raw["captured_timestamp"])
    expected_probe_transport = {
        "transport_censor_protocol_version": transport_binding[
            "transport_censor_protocol_version"
        ],
        "transport_censor_protocol_hash": transport_binding[
            "transport_censor_protocol_hash"
        ],
        "transport_uncertainty_binding_sha256": (
            transport_binding_sha256
        ),
        "source_tree_sha256": control["immutable"][
            "source_tree_sha256"
        ],
    }
    active_scheduler_job_ids: set[str] = set()
    for row in rows:
        if not isinstance(row, dict):
            raise ReadinessError("raw fleet probe contains a non-object replica")
        _exact_keys(row, replica_fields, context="raw fleet replica")
        replica_id = row.get("replica_id")
        expected = expected_replicas.get(str(replica_id))
        if expected is None or replica_id in observed_ids:
            raise ReadinessError(
                f"raw fleet probe has unknown/duplicate replica {replica_id!r}"
            )
        observed_ids.add(str(replica_id))
        profile = row.get("serving_profile")
        if (
            profile != expected["serving_profile"]
            or row.get("partition") != expected["partition"]
            or row.get("job_name") != expected["scheduler_job_name"]
            or row.get("ledger_generation") != raw["rollout_generation"]
            or row.get("attempt_state") != "committed"
            or not str(row.get("slurm_job_id", "")).isdigit()
            or not isinstance(row.get("node"), str)
            or not row["node"]
            or row.get("host") != row.get("node")
            or not isinstance(row.get("port"), int)
            or isinstance(row.get("port"), bool)
            or not 1 <= row["port"] <= 65_535
        ):
            raise ReadinessError(
                f"raw fleet scheduler identity drifted for {replica_id}"
            )
        profile_counts[str(profile)] = profile_counts.get(str(profile), 0) + 1

        job_id = str(row["slurm_job_id"])
        active_scheduler_job_ids.add(job_id)
        local_path = Path(str(row.get("local_script_path", "")))
        local_sha256 = row.get("local_script_sha256")
        spooled_sha256 = row.get("spooled_script_sha256")
        try:
            local_valid = (
                local_path.is_absolute()
                and not local_path.is_symlink()
                and local_path.is_file()
                and not local_path.stat().st_mode & 0o222
                and sha256_file(local_path) == local_sha256
            )
        except OSError:
            local_valid = False
        parsed_comment = fleet_transactions.parse_intent_comment(
            str(row.get("comment", ""))
        )
        scontrol = row.get("scontrol")
        spool = row.get("spooled_script_proof")
        if (
            not local_valid
            or not isinstance(local_sha256, str)
            or _SHA256_RE.fullmatch(local_sha256) is None
            or spooled_sha256 != local_sha256
            or parsed_comment is None
            or parsed_comment.get("pool") != "schema5-v1"
            or parsed_comment.get("profile") != profile
            or parsed_comment.get("replica") != replica_id
            or parsed_comment.get("generation")
            != str(raw["rollout_generation"])
            or parsed_comment.get("intent") != row.get("intent_token")
            or parsed_comment.get("fleet") != fleet_binding["sha256"]
            or local_path.parent
            != (
                transaction_directory
                / "sbatch"
                / f"g{int(raw['rollout_generation']):06d}"
            ).resolve()
            or local_path.name
            != (
                re.sub(r"[^A-Za-z0-9_.-]+", "_", str(replica_id))
                + f".{row.get('intent_token')}.sbatch"
            )
            or not isinstance(scontrol, dict)
        ):
            raise ReadinessError(
                f"fleet effective scheduler/spool identity drifted for {replica_id}"
            )
        _exact_keys(
            scontrol, scontrol_fields, context="fleet effective Slurm state"
        )
        raw_output = scontrol.get("raw_output")
        raw_lines = (
            [line.strip() for line in raw_output.splitlines() if line.strip()]
            if isinstance(raw_output, str)
            else []
        )
        raw_fields: dict[str, str] = {}
        if len(raw_lines) == 1:
            try:
                raw_tokens = shlex.split(raw_lines[0], posix=True)
            except (TypeError, ValueError):
                raw_tokens = []
            for token in raw_tokens:
                if "=" not in token:
                    continue
                key, value = token.split("=", 1)
                if not key or key in raw_fields:
                    raw_fields = {}
                    break
                raw_fields[key] = value.strip('"')
        normalized_raw_output = (
            raw_lines[0] + "\n" if len(raw_lines) == 1 else None
        )
        if (
            scontrol.get("argv")
            != ["scontrol", "show", "job", "-o", job_id]
            or scontrol.get("job_id") != job_id
            or scontrol.get("job_state") != "RUNNING"
            or scontrol.get("reason") is not None
            or scontrol.get("comment") != row.get("comment")
            or scontrol.get("job_name") != row.get("job_name")
            or scontrol.get("node") != row.get("node")
            or scontrol.get("command") != str(local_path)
            or scontrol.get("effective_requeue") != 0
            or normalized_raw_output != raw_output
            or scontrol.get("raw_output_sha256")
            != hashlib.sha256(str(raw_output).encode("utf-8")).hexdigest()
            or raw_fields.get("JobId") != job_id
            or raw_fields.get("JobState") != "RUNNING"
            or raw_fields.get("Reason") not in {None, "None"}
            or raw_fields.get("Requeue") != "0"
            or raw_fields.get("Comment") != row.get("comment")
            or raw_fields.get("JobName") != row.get("job_name")
            or raw_fields.get("NodeList") != row.get("node")
            or not fleet_transactions.command_binds_sbatch(
                raw_fields.get("Command", ""), str(local_path)
            )
            or not isinstance(spool, dict)
        ):
            raise ReadinessError(
                f"fleet effective Requeue=0 proof drifted for {replica_id}"
            )
        _exact_keys(spool, spool_fields, context="fleet spooled script proof")
        if (
            spool.get("argv")
            != ["scontrol", "write", "batch_script", job_id, "-"]
            or spool.get("local_path") != str(local_path)
            or spool.get("local_sha256") != local_sha256
            or spool.get("observed_sha256") != spooled_sha256
            or not isinstance(spool.get("observed_bytes"), int)
            or isinstance(spool.get("observed_bytes"), bool)
            or spool["observed_bytes"] < 1
            or spool["observed_bytes"] != local_path.stat().st_size
            or spool.get("exact_match") is not True
        ):
            raise ReadinessError(
                f"fleet exact spooled-script proof drifted for {replica_id}"
            )

        reference_name = f"registry_{replica_id}"
        reference = reference_by_name.get(reference_name)
        expected_registry_path = str(
            (
                Path(pool_root)
                / "servers"
                / str(profile)
                / f"{row.get('host')}_{row.get('port')}.json"
            ).resolve()
        )
        if (
            not isinstance(reference, dict)
            or reference.get("path") != row.get("registry_path")
            or reference.get("path") != expected_registry_path
            or reference.get("sha256") != row.get("registry_sha256")
        ):
            raise ReadinessError(f"raw fleet registry binding drifted for {replica_id}")
        _, registry = _validate_referenced_artifact(
            reference,
            context=f"fleet registration {replica_id}",
            verified=set(),
            active=set(),
            snapshot_context=snapshot_context,
        )
        if (
            not isinstance(registry, dict)
            or str(registry.get("replica_id")) != replica_id
            or registry.get("replica_index") != expected["replica_index"]
            or registry.get("server_pool_id") != "schema5-v1"
            or registry.get("serving_profile") != profile
            or registry.get("model_size") != expected["model_size"]
            or registry.get("hf_id") != expected["hf_id"]
            or registry.get("served_model_name")
            != expected["served_model_name"]
            or registry.get("max_model_len") != expected["max_model_len"]
            or registry.get("tp_size") != expected["tp_size"]
            or str(registry.get("slurm_job_id")) != str(row["slurm_job_id"])
            or registry.get("host") != row["host"]
            or registry.get("port") != row["port"]
            or registry.get("release_id") != control["immutable"]["release_id"]
            or registry.get("environment_hash")
            != control["immutable"]["serving_environment_sha256"]
            or registry.get("model_contract_sha256")
            != control["immutable"]["model_contract_sha256"]
            or registry.get("fleet_contract_sha256")
            != fleet_binding["sha256"]
            or registry.get("release_fleet_contract_sha256")
            != control["immutable"]["fleet_contract_sha256"]
            or registry.get("capacity_generation")
            != fleet_binding["capacity_generation"]
            or registry.get("rollout_generation")
            != raw["rollout_generation"]
            or registry.get("model_revision") != expected["model_revision"]
            or registry.get("tokenizer_id") != expected["tokenizer_id"]
            or registry.get("tokenizer_revision")
            != expected["tokenizer_revision"]
        ):
            raise ReadinessError(
                f"fleet registration provenance drifted for {replica_id}"
            )

        provenance = row.get("spooled_provenance")
        if not isinstance(provenance, dict):
            raise ReadinessError(f"spooled provenance is missing for {replica_id}")
        _exact_keys(provenance, provenance_fields, context="spooled fleet provenance")
        if (
            provenance.get("run_root") != pool_root
            or provenance.get("server_pool_id") != "schema5-v1"
            or str(provenance.get("replica_id")) != replica_id
            or provenance.get("replica_index") != expected["replica_index"]
            or provenance.get("release_id") != control["immutable"]["release_id"]
            or provenance.get("environment_hash")
            != control["immutable"]["serving_environment_sha256"]
            or provenance.get("model_revision") != expected["model_revision"]
            or provenance.get("tokenizer_id") != expected["tokenizer_id"]
            or provenance.get("tokenizer_revision") != expected["tokenizer_revision"]
            or provenance.get("model_contract_sha256")
            != control["immutable"]["model_contract_sha256"]
            or provenance.get("fleet_contract_sha256")
            != fleet_binding["sha256"]
            or provenance.get("release_fleet_contract_sha256")
            != control["immutable"]["fleet_contract_sha256"]
            or provenance.get("capacity_generation")
            != fleet_binding["capacity_generation"]
            or provenance.get("rollout_generation")
            != raw["rollout_generation"]
            or provenance.get("spooled_script_sha256")
            != row.get("spooled_script_sha256")
        ):
            raise ReadinessError(f"spooled fleet provenance drifted for {replica_id}")

        http = row.get("http")
        if (
            row.get("probe_transport_provenance")
            != expected_probe_transport
        ):
            raise ReadinessError(
                f"fleet probe transport provenance drifted for {replica_id}"
            )
        if not isinstance(http, dict):
            raise ReadinessError(f"HTTP health evidence is missing for {replica_id}")
        _exact_keys(http, http_fields, context="fleet HTTP probe")
        completed = http.get("probe_completed_timestamp")
        started = http.get("probe_started_timestamp")
        if (
            http.get("healthy") is not True
            or http.get("health_status") != 200
            or http.get("models_status") != 200
            or not isinstance(http.get("model_ids"), list)
            or http.get("expected_model") != expected["served_model_name"]
            or http.get("expected_model") not in http["model_ids"]
            or not isinstance(started, (int, float))
            or isinstance(started, bool)
            or not isinstance(completed, (int, float))
            or isinstance(completed, bool)
            or not float(started) <= float(completed) <= captured
        ):
            raise ReadinessError(f"fleet HTTP probe failed for {replica_id}")
        probe_ages.append(captured - float(completed))
    if any(
        active_scheduler_job_ids.intersection(history)
        for history in scheduler_history_sets
    ):
        raise ReadinessError(
            "raw fleet health probe history overlaps active allocations"
        )
    if observed_ids != set(expected_replicas):
        raise ReadinessError("raw fleet probe does not cover the frozen replica set")
    if profile_counts != fleet_binding["profile_replicas"]:
        raise ReadinessError(
            "raw fleet probe profile counts differ from the effective topology"
        )
    if not probe_ages or max(probe_ages) != metrics.get("max_heartbeat_age_seconds"):
        raise ReadinessError(
            "fleet freshness metric is not derived from raw HTTP probes"
        )


