def _validate_context_artifacts(
    control: Mapping[str, Any],
    metrics: Mapping[str, Any],
    artifacts: Mapping[str, tuple[Path, Mapping[str, Any] | None]],
    *,
    snapshot_context: _SnapshotValidationContext,
) -> None:
    total_failures = 0
    total_truncations = 0
    margins: list[int] = []
    requests: dict[str, int] = {}
    seven_run = _run_pins_by_id(control["immutable"])[
        "full_sweep_agent_count_7_schema5_v1"
    ]
    for name, contract in _CONTEXT_ARTIFACT_CONTRACTS.items():
        wrapper = _validate_artifact_identity(
            control,
            artifacts[name][1],
            name=name,
            exact_fields={
                "schema_version",
                "kind",
                "passed",
                "immutable_sha256",
                "run_id",
                "filters",
                "all_routed_profiles",
                "metrics",
                "referenced_artifacts",
            },
        )
        expected_metrics = {
            "selected_cells": contract["selected_cells"],
            "audited_requests": contract["audited_requests"],
            "failed_requests": 0,
            "failed_cells": 0,
            "minimum_context_headroom_tokens": 1_287,
            "truncation_incidents": 0,
        }
        if (
            wrapper.get("run_id") != contract["run_id"]
            or wrapper.get("filters") != contract["filters"]
            or wrapper.get("all_routed_profiles") is not True
            or wrapper.get("metrics") != expected_metrics
        ):
            raise ReadinessError(
                f"{name} selection or metrics differ from the exact audit"
            )
        source = _load_only_source_report(
            wrapper,
            expected_name=str(contract["source_name"]),
            snapshot_context=snapshot_context,
        )
        summary = source.get("summary")
        manifest = source.get("manifest")
        if (
            source.get("schema_version") != 3
            or source.get("audit") != "all_routed_profiles_context_capacity"
            or source.get("run_id") != contract["run_id"]
            or source.get("filters") != contract["filters"]
            or source.get("all_routed_profiles") is not True
            or not isinstance(summary, dict)
            or summary.get("passed") is not True
            or not isinstance(manifest, dict)
            or manifest.get("path") != str(Path(seven_run["manifest_path"]).resolve())
            or manifest.get("sha256") != seven_run["manifest_sha256"]
            or manifest.get("cells") != seven_run["cell_count"]
            or source.get("failure_groups") != []
            or source.get("failure_examples") != []
        ):
            raise ReadinessError(f"raw context report for {name} has invalid identity")
        for field in (
            "selected_cells",
            "audited_requests",
            "failed_requests",
            "failed_cells",
            "minimum_context_headroom_tokens",
        ):
            if summary.get(field) != expected_metrics[field]:
                raise ReadinessError(
                    f"raw context report {name} {field} differs from its wrapper"
                )
        requests[name] = int(expected_metrics["audited_requests"])
        total_failures += int(expected_metrics["failed_requests"])
        total_truncations += int(expected_metrics["truncation_incidents"])
        margins.append(int(expected_metrics["minimum_context_headroom_tokens"]))
    derived = {
        "dense_peer_requests": requests["dense_peer_context_audit"],
        "seven_agent_requests": requests["seven_agent_context_audit"],
        "failed_preflights": total_failures,
        "truncation_incidents": total_truncations,
        "minimum_context_margin_tokens": min(margins),
    }
    if dict(metrics) != derived:
        raise ReadinessError(
            "outer context metrics are not derived from both raw audits"
        )


def _validate_smoke_catalog_binding(
    control: Mapping[str, Any],
    value: Any,
    *,
    expected_fleet_sha256: str,
    expected_capacity_generation: int,
    expected_rollout_generation: int,
) -> TrustedGenerationCatalog:
    """Independently load the exact sealed endpoint catalog named by smoke evidence."""

    if not isinstance(value, Mapping) or set(value) != SMOKE_TRUSTED_CATALOG_FIELDS:
        raise ReadinessError("smoke trusted-generation catalog binding is malformed")
    marker_path = Path(str(value.get("marker_path", "")))
    if (
        not marker_path.is_absolute()
        or _SHA256_RE.fullmatch(str(value.get("catalog_id", ""))) is None
        or any(
            _SHA256_RE.fullmatch(str(value.get(field, ""))) is None
            for field in (
                "marker_sha256",
                "inventory_sha256",
                "catalog_payload_sha256",
            )
        )
        or not isinstance(value.get("allowed_generation_tuple_count"), int)
        or isinstance(value.get("allowed_generation_tuple_count"), bool)
        or int(value["allowed_generation_tuple_count"]) < 1
    ):
        raise ReadinessError("smoke trusted-generation catalog binding is invalid")
    try:
        catalog = validate_trusted_generation_catalog(
            marker_path,
            server_pool_root=Path(
                str(control["immutable"]["server_pool_root"])
            ).resolve(),
        )
    except (OSError, ValueError, GenerationCatalogError) as exc:
        raise ReadinessError(
            f"smoke trusted-generation catalog failed validation: {exc}"
        ) from exc
    expected = {
        "catalog_id": catalog.catalog_id,
        "marker_path": str(catalog.marker_path),
        "marker_sha256": catalog.marker_sha256,
        "inventory_sha256": catalog.inventory_sha256,
        "catalog_payload_sha256": catalog.catalog_sha256,
        "allowed_generation_tuple_count": len(
            catalog.allowed_generation_tuples
        ),
    }
    if dict(value) != expected:
        raise ReadinessError(
            "smoke trusted-generation catalog binding differs from sealed bytes"
        )
    expected_prefix = (
        str(control["immutable"]["fleet_contract_sha256"]),
        expected_fleet_sha256,
        expected_capacity_generation,
        expected_rollout_generation,
    )
    if not any(
        identity[:4] == expected_prefix
        for identity in catalog.allowed_generation_tuples
    ):
        raise ReadinessError(
            "smoke trusted-generation catalog lacks the exact readiness generation"
        )
    return catalog


def _smoke_result_records(
    reference: Any,
    *,
    expected_path: Path,
    expected_rows: int,
) -> list[dict[str, Any]]:
    """Read one sealed canonical smoke JSONL and verify its evidence reference."""

    if (
        not isinstance(reference, Mapping)
        or set(reference) != {"path", "sha256", "row_count"}
        or reference.get("path") != str(expected_path)
        or _SHA256_RE.fullmatch(str(reference.get("sha256", ""))) is None
        or reference.get("row_count") != expected_rows
    ):
        raise ReadinessError("smoke cell result-artifact binding is malformed")
    path, raw = _read_stable_authorization_file(
        expected_path, description="sealed smoke result artifact"
    )
    if (
        path != expected_path
        or hashlib.sha256(raw).hexdigest() != reference["sha256"]
    ):
        raise ReadinessError("smoke cell result artifact drifted")
    lines = raw.splitlines()
    if len(lines) != expected_rows or any(not line for line in lines):
        raise ReadinessError(
            "smoke cell result artifact row count is not exact"
        )
    records: list[dict[str, Any]] = []
    for index, line in enumerate(lines):
        def reject_duplicates(
            pairs: Sequence[tuple[str, Any]],
        ) -> dict[str, Any]:
            value: dict[str, Any] = {}
            for key, nested in pairs:
                if key in value:
                    raise ReadinessError(
                        f"smoke cell result row {index} duplicates key {key!r}"
                    )
                value[key] = nested
            return value

        def reject_nonfinite(token: str) -> Any:
            raise ReadinessError(
                f"smoke cell result row {index} contains non-finite {token}"
            )

        try:
            record = json.loads(
                line.decode("utf-8"),
                object_pairs_hook=reject_duplicates,
                parse_constant=reject_nonfinite,
            )
        except ReadinessError:
            raise
        except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
            raise ReadinessError(
                f"smoke cell result row {index} is malformed"
            ) from exc
        if not isinstance(record, dict):
            raise ReadinessError(
                f"smoke cell result row {index} is not an object"
            )
        records.append(record)
    return records


def _validate_smoke_artifacts(
    control: Mapping[str, Any],
    metrics: Mapping[str, Any],
    artifacts: Mapping[str, tuple[Path, Mapping[str, Any] | None]],
) -> None:
    fleet_binding = effective_fleet_contract_binding(control, verify_files=True)
    suites = {
        "long_32b_smoke": ("schema5_smoke_32b_long_v1", 15),
        "selective_long_smoke": ("schema5_smoke_selective_long_v1", 20),
        "standard_canary_smoke": ("schema5_smoke_standard_canaries_v1", 6),
    }
    expected_profiles = {
        "long_32b_smoke": {"32B-long": 15},
        "selective_long_smoke": {
            "0.6B": 1,
            "0.6B-long": 3,
            "1.7B": 1,
            "1.7B-long": 3,
            "4B": 1,
            "4B-long": 3,
            "8B": 1,
            "8B-long": 3,
            "14B": 1,
            "14B-long": 3,
        },
        "standard_canary_smoke": {
            "0.6B": 1,
            "1.7B": 1,
            "4B": 1,
            "8B": 1,
            "14B": 1,
            "32B": 1,
        },
    }
    provenance_expected = {
        "release_id": control["immutable"]["release_id"],
        "git_commit": control["immutable"]["git_commit"],
        "source_tree_sha256": control["immutable"]["source_tree_sha256"],
        "harness_environment_sha256": control["immutable"][
            "harness_environment_sha256"
        ],
        "serving_environment_sha256": control["immutable"][
            "serving_environment_sha256"
        ],
        "model_contract_sha256": control["immutable"]["model_contract_sha256"],
        "fleet_contract_sha256": fleet_binding["sha256"],
        "release_fleet_contract_sha256": control["immutable"][
            "fleet_contract_sha256"
        ],
        "capacity_generation": fleet_binding["capacity_generation"],
        "server_pool_root": str(
            Path(control["immutable"]["server_pool_root"]).resolve()
        ),
        # Smokes are executed while paused for the generation that ``resume`` will
        # publish.  A capacity transition therefore cannot reuse generation-1 smoke
        # provenance from the initial launch.
        "rollout_generation": (
            int(control["rollout_generation"]) + 1
            if isinstance(
                control.get("capacity", {}).get("active_transition"), dict
            )
            else 1
        ),
    }
    expected_attempt_root: Path | None = None
    expected_attempt_binding: Mapping[str, Any] | None = None
    selected_catalog: TrustedGenerationCatalog | None = None
    selected_generation_tuples: frozenset[
        tuple[str, str, int, int, str]
    ] | None = None
    derived = {
        "long_32b_cells": 0,
        "selective_long_cells": 0,
        "standard_canary_cells": 0,
        "schema5_complete_cells": 0,
        "context_incidents": 0,
        "protocol_incidents": 0,
        "transport_incidents": 0,
        "truncation_incidents": 0,
        "provenance_failures": 0,
        "trusted_generation_failures": 0,
    }
    metric_names = {
        "long_32b_smoke": "long_32b_cells",
        "selective_long_smoke": "selective_long_cells",
        "standard_canary_smoke": "standard_canary_cells",
    }
    exact_fields = {
        "schema_version",
        "kind",
        "passed",
        "immutable_sha256",
        "run_id",
        "expected_cells",
        "schema5_complete_cells",
        "context_incidents",
        "protocol_incidents",
        "transport_incidents",
        "truncation_incidents",
        "provenance_failures",
        "trusted_generation_failures",
        "semantic_validation_failures",
        "top_level_length_censored_qids",
        "top_level_protocol_censored_qids",
        "top_level_transport_censored_qids",
        "transport_affected_qids",
        "transport_censored_coordinates",
        "auxiliary_length_censored_draws",
        "auxiliary_protocol_censored_draws",
        "auxiliary_transport_censored_draws",
        "transport_censor_protocol_version",
        "transport_censor_protocol_hash",
        "concurrency",
        "resumable",
        "execution_halted",
        "execution_halt_reason",
        "provenance",
        "suite_identity",
        "cells",
    }
    for name, (run_id, expected_cells) in suites.items():
        suite = _validate_artifact_identity(
            control,
            artifacts[name][1],
            name=name,
            exact_fields=exact_fields,
        )
        zero_fields = (
            "context_incidents",
            "protocol_incidents",
            "transport_incidents",
            "truncation_incidents",
            "provenance_failures",
            "trusted_generation_failures",
            "semantic_validation_failures",
            "top_level_length_censored_qids",
            "top_level_protocol_censored_qids",
            "top_level_transport_censored_qids",
            "transport_affected_qids",
            "transport_censored_coordinates",
            "auxiliary_length_censored_draws",
            "auxiliary_protocol_censored_draws",
            "auxiliary_transport_censored_draws",
        )
        cells = suite.get("cells")
        identity = suite.get("suite_identity")
        identity_fields = {
            "run_id",
            "cell_count",
            "manifest_sha256",
            "benchmark_contracts_sha256",
            "artifact_policy_sha256",
            "lineage_sha256",
            "serving_profile_counts",
            "estimand_excluded",
            "smoke_attempt",
        }
        artifact_path = artifacts[name][0]
        attempt_root = artifact_path.parent.parent
        attempt_binding = (
            identity.get("smoke_attempt")
            if isinstance(identity, Mapping)
            else None
        )
        attempt_ordinal = (
            attempt_binding.get("attempt_ordinal")
            if isinstance(attempt_binding, Mapping)
            else None
        )
        trusted_catalog_id = (
            attempt_binding.get("trusted_catalog_id")
            if isinstance(attempt_binding, Mapping)
            else None
        )
        if (
            not isinstance(attempt_binding, Mapping)
            or set(attempt_binding) != SMOKE_ATTEMPT_BINDING_FIELDS
            or attempt_binding.get("protocol")
            != SMOKE_ATTEMPT_BINDING_PROTOCOL
            or not isinstance(attempt_binding.get("attempt_id"), str)
            or not attempt_binding["attempt_id"]
            or not isinstance(attempt_ordinal, int)
            or isinstance(attempt_ordinal, bool)
            or int(attempt_ordinal) < 1
            or attempt_binding.get("immutable_sha256")
            != control["immutable_sha256"]
            or attempt_binding.get("capacity_generation")
            != provenance_expected["capacity_generation"]
            or attempt_binding.get("rollout_generation")
            != provenance_expected["rollout_generation"]
            or attempt_binding.get("fleet_contract_sha256")
            != provenance_expected["fleet_contract_sha256"]
            or attempt_binding.get("release_fleet_contract_sha256")
            != provenance_expected["release_fleet_contract_sha256"]
            or _SHA256_RE.fullmatch(str(trusted_catalog_id or "")) is None
            or attempt_binding["attempt_id"]
            != (
                f"a{int(attempt_ordinal):06d}-"
                f"g{int(provenance_expected['rollout_generation']):06d}-"
                f"c{int(provenance_expected['capacity_generation']):06d}-"
                f"{str(trusted_catalog_id)[:16]}"
            )
            or artifact_path.parent.name != "artifacts"
            or attempt_root.name != attempt_binding["attempt_id"]
            or attempt_root.parent.name != "attempts"
            or attempt_root.parent.parent.name != SMOKE_ATTEMPT_BASE_NAME
        ):
            raise ReadinessError(
                f"smoke suite {name} is outside its generation-scoped attempt"
            )
        if expected_attempt_root is None:
            expected_attempt_root = attempt_root
            expected_attempt_binding = dict(attempt_binding)
        elif (
            attempt_root != expected_attempt_root
            or dict(attempt_binding) != dict(expected_attempt_binding or {})
        ):
            raise ReadinessError(
                "smoke suite artifacts do not share one exact attempt"
            )
        provenance = suite.get("provenance")
        catalog_binding = (
            provenance.get("trusted_generation_catalog")
            if isinstance(provenance, Mapping)
            else None
        )
        if selected_catalog is None:
            selected_catalog = _validate_smoke_catalog_binding(
                control,
                catalog_binding,
                expected_fleet_sha256=str(fleet_binding["sha256"]),
                expected_capacity_generation=int(
                    fleet_binding["capacity_generation"]
                ),
                expected_rollout_generation=int(
                    provenance_expected["rollout_generation"]
                ),
            )
            if trusted_catalog_id != selected_catalog.catalog_id:
                raise ReadinessError(
                    "smoke attempt does not bind its exact trusted-generation "
                    "catalog"
                )
            selected_generation_tuples = frozenset(
                candidate
                for candidate in selected_catalog.allowed_generation_tuples
                if candidate[:4]
                == (
                    provenance_expected[
                        "release_fleet_contract_sha256"
                    ],
                    provenance_expected["fleet_contract_sha256"],
                    provenance_expected["capacity_generation"],
                    provenance_expected["rollout_generation"],
                )
            )
            if not selected_generation_tuples:
                raise ReadinessError(
                    "smoke catalog contains no endpoint for its selected "
                    "readiness generation"
                )
        else:
            expected_catalog_binding = {
                "catalog_id": selected_catalog.catalog_id,
                "marker_path": str(selected_catalog.marker_path),
                "marker_sha256": selected_catalog.marker_sha256,
                "inventory_sha256": selected_catalog.inventory_sha256,
                "catalog_payload_sha256": selected_catalog.catalog_sha256,
                "allowed_generation_tuple_count": len(
                    selected_catalog.allowed_generation_tuples
                ),
            }
            if dict(catalog_binding or {}) != expected_catalog_binding:
                raise ReadinessError(
                    "smoke suites bind different trusted-generation catalogs"
                )
            if trusted_catalog_id != selected_catalog.catalog_id:
                raise ReadinessError(
                    "smoke attempt does not bind its exact trusted-generation "
                    "catalog"
                )
        expected_provenance = {
            **provenance_expected,
            "trusted_generation_catalog": dict(catalog_binding),
        }
        valid_identity = (
            isinstance(identity, dict)
            and set(identity) == identity_fields
            and identity.get("run_id") == run_id
            and identity.get("cell_count") == expected_cells
            and identity.get("serving_profile_counts") == expected_profiles[name]
            and identity.get("estimand_excluded") is True
            and dict(identity.get("smoke_attempt") or {})
            == dict(expected_attempt_binding or {})
            and all(
                _SHA256_RE.fullmatch(str(identity.get(field, ""))) is not None
                for field in (
                    "manifest_sha256",
                    "benchmark_contracts_sha256",
                    "artifact_policy_sha256",
                    "lineage_sha256",
                )
            )
        )
        if (
            suite.get("run_id") != run_id
            or suite.get("expected_cells") != expected_cells
            or suite.get("schema5_complete_cells") != expected_cells
            or any(suite.get(field) != 0 for field in zero_fields)
            or suite.get("concurrency") != 1
            or suite.get("resumable") is not True
            or suite.get("execution_halted") is not False
            or suite.get("execution_halt_reason") is not None
            or suite.get("transport_censor_protocol_version")
            != TRANSPORT_CENSOR_PROTOCOL_VERSION
            or suite.get("transport_censor_protocol_hash")
            != TRANSPORT_CENSOR_PROTOCOL_HASH
            or suite.get("provenance") != expected_provenance
            or not valid_identity
            or not isinstance(cells, list)
            or len(cells) != expected_cells
        ):
            raise ReadinessError(
                f"smoke suite {name} does not satisfy its exact contract"
            )
        cell_fields = {
            "cell_id",
            "status",
            "valid_qids",
            "expected_qids",
            "top_level_length_censored_qids",
            "top_level_protocol_censored_qids",
            "top_level_transport_censored_qids",
            "transport_affected_qids",
            "transport_censored_coordinates",
            "auxiliary_length_censored_draws",
            "auxiliary_protocol_censored_draws",
            "auxiliary_transport_censored_draws",
            "context_incidents",
            "protocol_incidents",
            "transport_incidents",
            "truncation_incidents",
            "provenance_failures",
            "provenance_errors",
            "trusted_generation_errors",
            "results_artifact",
            "semantic_errors",
            "failure",
        }
        cell_ids: set[str] = set()
        for cell in cells:
            if (
                not isinstance(cell, dict)
                or set(cell) != cell_fields
                or not isinstance(cell.get("cell_id"), str)
                or not cell.get("cell_id")
            ):
                raise ReadinessError(
                    f"smoke suite {name} contains an invalid cell report"
                )
            cell_ids.add(cell["cell_id"])
            if (
                cell.get("status") != "complete"
                or not isinstance(cell.get("expected_qids"), int)
                or isinstance(cell.get("expected_qids"), bool)
                or cell.get("expected_qids", 0) <= 0
                or cell.get("valid_qids") != cell.get("expected_qids")
                or any(cell.get(field) != 0 for field in zero_fields if field in cell)
                or cell.get("provenance_errors") != []
                or cell.get("trusted_generation_errors") != []
                or cell.get("semantic_errors") != []
                or cell.get("failure") is not None
            ):
                raise ReadinessError(
                    f"smoke suite {name} has a non-canonical cell result"
                )
            assert selected_catalog is not None
            assert selected_generation_tuples is not None
            expected_result_path = (
                Path(str(control["immutable"]["results_root"])).resolve()
                / SMOKE_ATTEMPT_RUNS_NAME
                / str(attempt_binding["attempt_id"])
                / run_id
                / "cells"
                / str(cell["cell_id"])
                / "results.jsonl"
            )
            records = _smoke_result_records(
                cell.get("results_artifact"),
                expected_path=expected_result_path,
                expected_rows=int(cell["valid_qids"]),
            )
            observed_trusted_errors = trusted_generation_catalog_errors(
                records, selected_generation_tuples
            )
            if observed_trusted_errors:
                raise ReadinessError(
                    f"smoke suite {name} contains out-of-catalog endpoint "
                    f"provenance: {observed_trusted_errors[:3]}"
                )
        if len(cell_ids) != expected_cells:
            raise ReadinessError(f"smoke suite {name} repeats a cell ID")
        derived[metric_names[name]] = expected_cells
        derived["schema5_complete_cells"] += expected_cells
        for field in (
            "context_incidents",
            "protocol_incidents",
            "transport_incidents",
            "truncation_incidents",
            "provenance_failures",
            "trusted_generation_failures",
        ):
            derived[field] += int(suite[field])
    if dict(metrics) != derived:
        raise ReadinessError("outer smoke metrics are not derived from suite artifacts")


def _validate_email_artifact(
    control: Mapping[str, Any],
    metrics: Mapping[str, Any],
    artifacts: Mapping[str, tuple[Path, Mapping[str, Any] | None]],
    *,
    snapshot_context: _SnapshotValidationContext,
) -> None:
    name = "email_delivery_receipt"
    receipt = _validate_artifact_identity(
        control,
        artifacts[name][1],
        name=name,
        exact_fields={
            "schema_version",
            "kind",
            "passed",
            "immutable_sha256",
            "metrics",
            "referenced_artifacts",
        },
    )
    if receipt.get("metrics") != dict(metrics):
        raise ReadinessError("email receipt metrics differ from the outer envelope")
    references = receipt.get("referenced_artifacts")
    expected_names = (
        "active_email_challenge",
        "email_ack_request",
        "email_acknowledgement",
    )
    if (
        not isinstance(references, list)
        or len(references) != len(expected_names)
        or tuple(
            reference.get("name") if isinstance(reference, dict) else None
            for reference in references
        )
        != expected_names
    ):
        raise ReadinessError(
            "email delivery receipt must reference exactly its active challenge, "
            "request, and one-time acknowledgement"
        )
    verified: set[tuple[str, str]] = set()
    active: set[tuple[str, str]] = set()
    active_path, active_challenge = _validate_referenced_artifact(
        references[0],
        context="active email challenge",
        verified=verified,
        active=active,
        snapshot_context=snapshot_context,
    )
    request_path, request = _validate_referenced_artifact(
        references[1],
        context="email acknowledgement request",
        verified=verified,
        active=active,
        snapshot_context=snapshot_context,
    )
    acknowledgement_path, acknowledgement = _validate_referenced_artifact(
        references[2],
        context="email acknowledgement",
        verified=verified,
        active=active,
        snapshot_context=snapshot_context,
    )
    if (
        not isinstance(active_challenge, dict)
        or not isinstance(request, dict)
        or not isinstance(acknowledgement, dict)
    ):
        raise ReadinessError(
            "active email challenge, request, and acknowledgement must be objects"
        )
    if (
        request.get("immutable_sha256") != control["immutable_sha256"]
        or request.get("recipient") != control.get("alert_email")
        or request.get("release_tag") != PRODUCTION_OPERATIONAL_TAG
        or request.get("release_git_commit")
        != control["immutable"]["git_commit"]
    ):
        raise ReadinessError(
            "email challenge differs from immutable production control"
        )
    try:
        schema5_email_ack.validate_request_payload(request)
        schema5_email_ack.validate_active_challenge(
            active_challenge,
            active_path=active_path,
            request=request,
            request_path=request_path,
        )
        schema5_email_ack.validate_acknowledgement(
            acknowledgement,
            acknowledgement_path=acknowledgement_path,
            request=request,
            request_path=request_path,
        )
    except schema5_email_ack.AcknowledgementError as exc:
        raise ReadinessError(
            f"email challenge closed-schema validation failed: {exc}"
        ) from exc
    derived = {
        "recipient": request["recipient"],
        "delivery_succeeded": request["delivery_succeeded"],
        "returncode": request["returncode"],
        "acknowledged": True,
        "chain_id": request["chain_id"],
        "request_id": request["request_id"],
        "release_tag": request["release_tag"],
        "release_git_commit": request["release_git_commit"],
        "challenge_generation": request["challenge_generation"],
        "challenge_id": request["challenge_id"],
        "challenge_verifier": request["challenge_verifier"],
        "acknowledged_at": acknowledgement["acknowledged_at"],
    }
    if dict(metrics) != derived:
        raise ReadinessError(
            "outer email metrics are not derived from the request and acknowledgement"
        )


class _SnapshotValidationContext:
    """One readiness-validation pass over the two large sealed snapshots.

    ``full`` is used only while attesting generation zero or creating a new rollout
    seal. Normal dispatcher, controller, and status paths construct a compact context
    from the current generation seal and never hash snapshot payload bytes.
    """

    def __init__(
        self,
        *,
        full: bool,
        seal: Mapping[str, Any] | None = None,
        allow_inventory_lookup: bool = False,
        allowed_members: Sequence[Mapping[str, str]] = (),
    ) -> None:
        self.full = full
        self.seal = dict(seal) if seal is not None else None
        self.allow_inventory_lookup = allow_inventory_lookup
        self.proofs: dict[str, dict[str, Any]] = {}
        self.metadata: dict[str, dict[str, Any]] = {}
        self.members: dict[tuple[str, str], dict[str, str]] = {}
        self.inventories: dict[str, dict[str, str]] = {}
        self.allowed_members = {
            (str(row["snapshot_root"]), str(row["logical_path"])): dict(row)
            for row in allowed_members
        }

    def add_metadata(self, path: Path) -> None:
        try:
            row = snapshot_integrity.metadata_entry(path)
        except snapshot_integrity.SnapshotIntegrityError as exc:
            raise ReadinessError(str(exc)) from exc
        self.add_metadata_record(row)

    def add_metadata_record(self, row: Mapping[str, Any]) -> None:
        """Add metadata already proven from the descriptor used for byte hashing."""

        try:
            canonical = snapshot_integrity.canonical_metadata_entries([row])[0]
        except snapshot_integrity.SnapshotIntegrityError as exc:
            raise ReadinessError(str(exc)) from exc
        key = str(canonical["path"])
        previous = self.metadata.get(key)
        if previous is not None and previous != canonical:
            raise ReadinessError(
                f"sealed snapshot metadata changed during validation: {key}"
            )
        self.metadata[key] = canonical

    def sealed_snapshot(self, *, path: Path, digest: str) -> Mapping[str, Any] | None:
        if self.seal is None:
            return None
        matches = [
            row
            for row in self.seal.get("snapshots", [])
            if isinstance(row, dict)
            and row.get("attestation_path") == str(path.resolve())
            and row.get("attestation_sha256") == digest
        ]
        if len(matches) != 1:
            raise ReadinessError(
                f"snapshot attestation is not uniquely bound by generation seal: {path}"
            )
        return matches[0]

    def add_member(self, member: Mapping[str, str]) -> None:
        key = (str(member["snapshot_root"]), str(member["logical_path"]))
        previous = self.members.get(key)
        if previous is not None and previous != dict(member):
            raise ReadinessError(
                f"conflicting sealed snapshot membership proof: {key}"
            )
        self.members[key] = dict(member)


def _snapshot_regular_sha256(path: Path, *, context: str) -> str:
    try:
        return snapshot_integrity.sha256_file(path, description=context)
    except snapshot_integrity.SnapshotIntegrityError as exc:
        raise ReadinessError(str(exc)) from exc


def _snapshot_regular_sha256_with_metadata(
    path: Path, *, context: str
) -> tuple[str, dict[str, Any]]:
    try:
        return snapshot_integrity.sha256_file_with_metadata(
            path, description=context
        )
    except snapshot_integrity.SnapshotIntegrityError as exc:
        raise ReadinessError(str(exc)) from exc


def _validate_snapshot_external_attestation(
    path: Path,
    payload: Mapping[str, Any],
    *,
    snapshot_context: _SnapshotValidationContext,
) -> dict[str, Any]:
    """Verify the external envelope and every sealed snapshot control artifact."""
    cache_key = str(path.resolve())
    cached = snapshot_context.proofs.get(cache_key)
    if cached is not None:
        return cached
    _exact_keys(
        payload,
        {
            "schema_version",
            "kind",
            "passed",
            "snapshot_root",
            "snapshot_id",
            "file_count",
            "total_bytes",
            "control_artifacts",
            "attested_at",
        },
        context=f"snapshot external attestation {path}",
    )
    if payload.get("schema_version") != 1:
        raise ReadinessError(f"snapshot external attestation has wrong schema: {path}")
    if payload.get("kind") != "recovery_snapshot_external_attestation":
        raise ReadinessError(
            f"snapshot artifact is not an external attestation: {path}"
        )
    if payload.get("passed") is not True:
        raise ReadinessError(f"snapshot external attestation did not pass: {path}")
    root_value = payload.get("snapshot_root")
    if not isinstance(root_value, str) or not Path(root_value).is_absolute():
        raise ReadinessError(
            f"snapshot external attestation has non-absolute root: {path}"
        )
    supplied_root = Path(root_value)
    if supplied_root.is_symlink():
        raise ReadinessError(
            f"sealed snapshot root must not be a symlink: {supplied_root}"
        )
    root = supplied_root.resolve()
    if not root.is_dir():
        raise ReadinessError(f"sealed snapshot root is missing: {root}")
    if root.stat().st_mode & 0o222:
        raise ReadinessError(f"snapshot root is not read-only: {root}")
    controls = payload.get("control_artifacts")
    if not isinstance(controls, dict) or set(controls) != SNAPSHOT_CONTROL_FILENAMES:
        raise ReadinessError(
            f"snapshot external attestation must bind exactly "
            f"{sorted(SNAPSHOT_CONTROL_FILENAMES)}: {path}"
        )
    attestation_digest = sha256_file(path)
    sealed_row = snapshot_context.sealed_snapshot(
        path=path, digest=attestation_digest
    )
    # Running hot paths stop here.  The immutable seal was created from a full
    # payload/inventory validation and the short-lived metadata lease detects later
    # chmod/write/replace/hardlink/shape drift.  Reopening two ~201k-row inventories
    # (and their duplicate source copies) on every dispatcher/spec/successor check
    # would defeat the purpose of the compact lease.
    if not snapshot_context.full:
        if sealed_row is None:  # pragma: no cover - compact contexts always bind one
            raise ReadinessError("compact snapshot validation lacks a generation seal")
        for filename in sorted(SNAPSHOT_CONTROL_FILENAMES):
            record = controls[filename]
            if not isinstance(record, dict):
                raise ReadinessError(
                    f"invalid snapshot control record {filename}: {path}"
                )
            _exact_keys(
                record, {"sha256", "size"}, context=f"snapshot control {filename}"
            )
            if (
                _SHA256_RE.fullmatch(str(record.get("sha256", ""))) is None
                or not isinstance(record.get("size"), int)
                or isinstance(record.get("size"), bool)
                or record["size"] < 0
            ):
                raise ReadinessError(
                    f"invalid snapshot control identity for {filename}: {path}"
                )
        try:
            time.strptime(str(payload.get("attested_at")), "%Y-%m-%dT%H:%M:%SZ")
        except (TypeError, ValueError, OverflowError) as exc:
            raise ReadinessError(
                f"snapshot attestation timestamp is invalid: {path}"
            ) from exc
        proof = {
            "attestation_path": str(path.resolve()),
            "attestation_sha256": attestation_digest,
            "snapshot_root": str(root),
            "snapshot_id": str(payload["snapshot_id"]),
            "file_count": payload.get("file_count"),
            "total_bytes": payload.get("total_bytes"),
            "inventory_sha256": sealed_row.get("inventory_sha256"),
            "control_artifacts": {
                name: dict(controls[name]) for name in sorted(controls)
            },
        }
        if proof != dict(sealed_row):
            raise ReadinessError(
                f"snapshot external attestation differs from generation seal: {root}"
            )
        snapshot_context.proofs[cache_key] = proof
        return proof
    for filename in sorted(SNAPSHOT_CONTROL_FILENAMES):
        record = controls[filename]
        if not isinstance(record, dict):
            raise ReadinessError(f"invalid snapshot control record {filename}: {path}")
        _exact_keys(record, {"sha256", "size"}, context=f"snapshot control {filename}")
        artifact = root / filename
        if not artifact.is_file() or artifact.is_symlink():
            raise ReadinessError(
                f"snapshot control artifact is missing/unsafe: {artifact}"
            )
        digest = record.get("sha256")
        size = record.get("size")
        if not isinstance(digest, str) or len(digest) != 64:
            raise ReadinessError(f"invalid snapshot control hash for {artifact}")
        if not isinstance(size, int) or isinstance(size, bool) or size < 0:
            raise ReadinessError(f"invalid snapshot control size for {artifact}")
        observed_digest, metadata = _snapshot_regular_sha256_with_metadata(
            artifact, context="sealed snapshot control artifact"
        )
        if metadata["size"] != size or observed_digest != digest:
            raise ReadinessError(f"snapshot control artifact drifted: {artifact}")
        snapshot_context.add_metadata_record(metadata)

    try:
        marker = json.loads(
            (root / "SNAPSHOT_COMPLETE.json").read_text(encoding="utf-8")
        )
        catalog = json.loads(
            (root / "SNAPSHOT_CATALOG.json").read_text(encoding="utf-8")
        )
        source_inventory = (root / "SOURCE_INVENTORY.sha256").read_bytes()
        snapshot_inventory = (root / "SNAPSHOT_INVENTORY.sha256").read_bytes()
        directory_lines = (
            (root / "DIRECTORY_INVENTORY.txt").read_text(encoding="utf-8").splitlines()
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReadinessError(f"cannot parse sealed snapshot controls: {exc}") from exc
    if not isinstance(marker, dict) or not isinstance(catalog, dict):
        raise ReadinessError("sealed snapshot marker/catalog must be JSON objects")
    if source_inventory != snapshot_inventory:
        raise ReadinessError("sealed snapshot source and copy inventories differ")
    inventory_sha = hashlib.sha256(snapshot_inventory).hexdigest()
    if snapshot_context.full:
        seen_paths: set[str] = set()
        file_count = 0
        total_bytes = 0
        try:
            inventory_lines = snapshot_inventory.decode("utf-8").splitlines()
        except UnicodeDecodeError as exc:
            raise ReadinessError(
                f"sealed snapshot inventory is not UTF-8: {exc}"
            ) from exc
        for line_number, raw_line in enumerate(inventory_lines, start=1):
            digest, separator, logical = raw_line.partition("  ")
            relative = Path(logical)
            if (
                not separator
                or re.fullmatch(r"[0-9a-f]{64}", digest) is None
                or not logical
                or relative.is_absolute()
                or ".." in relative.parts
                or relative.as_posix() != logical
                or logical in SNAPSHOT_CONTROL_FILENAMES
                or logical in seen_paths
            ):
                raise ReadinessError(
                    f"invalid sealed snapshot inventory row {line_number}: {raw_line!r}"
                )
            candidate = root / relative
            if candidate.is_symlink() or not candidate.is_file():
                raise ReadinessError(
                    f"sealed snapshot payload is missing/unsafe: {candidate}"
                )
            observed_digest, metadata = _snapshot_regular_sha256_with_metadata(
                candidate, context="sealed snapshot payload"
            )
            if observed_digest != digest:
                raise ReadinessError(f"sealed snapshot payload drifted: {candidate}")
            snapshot_context.add_metadata_record(metadata)
            seen_paths.add(logical)
            file_count += 1
            total_bytes += int(metadata["size"])
        snapshot_context.inventories[str(root)] = {
            raw_line.partition("  ")[2]: raw_line.partition("  ")[0]
            for raw_line in inventory_lines
        }
        if directory_lines != sorted(set(directory_lines)):
            raise ReadinessError(
                "sealed snapshot directory inventory is not sorted and unique"
            )
        for logical in directory_lines:
            relative = Path(logical)
            candidate = root / relative
            if (
                not logical
                or relative.is_absolute()
                or ".." in relative.parts
                or relative.as_posix() != logical
                or candidate.is_symlink()
                or not candidate.is_dir()
                or candidate.stat().st_mode & 0o222
            ):
                raise ReadinessError(
                    f"sealed snapshot directory is invalid: {logical!r}"
                )
            snapshot_context.add_metadata(candidate)
        expected_files = seen_paths | set(SNAPSHOT_CONTROL_FILENAMES)
        expected_directories = set(directory_lines)
        observed_files: set[str] = set()
        observed_directories: set[str] = set()
        for directory, names, filenames in os.walk(
            root, topdown=True, followlinks=False
        ):
            names.sort()
            filenames.sort()
            directory_path = Path(directory)
            for name in names:
                candidate = directory_path / name
                if candidate.is_symlink():
                    raise ReadinessError(
                        f"symlink is forbidden in sealed snapshot: {candidate}"
                    )
                observed_directories.add(candidate.relative_to(root).as_posix())
            for name in filenames:
                candidate = directory_path / name
                if candidate.is_symlink() or not candidate.is_file():
                    raise ReadinessError(
                        f"unsafe regular entry in sealed snapshot: {candidate}"
                    )
                observed_files.add(candidate.relative_to(root).as_posix())
        if observed_files != expected_files or observed_directories != expected_directories:
            raise ReadinessError(
                "sealed snapshot topology differs from its file/directory inventories: "
                f"extra_files={sorted(observed_files - expected_files)[:5]}, "
                f"missing_files={sorted(expected_files - observed_files)[:5]}, "
                f"extra_directories={sorted(observed_directories - expected_directories)[:5]}, "
                f"missing_directories={sorted(expected_directories - observed_directories)[:5]}"
            )
        snapshot_context.add_metadata(root)
    if (
        marker.get("schema_version") != 1
        or marker.get("snapshot_id") != catalog.get("snapshot_id")
        or marker.get("snapshot_id") != payload.get("snapshot_id")
        or marker.get("file_count") != file_count
        or catalog.get("file_count") != file_count
        or payload.get("file_count") != file_count
        or marker.get("total_bytes") != total_bytes
        or catalog.get("total_bytes") != total_bytes
        or payload.get("total_bytes") != total_bytes
        or marker.get("snapshot_inventory_sha256") != inventory_sha
        or catalog.get("source_inventory_sha256") != inventory_sha
        or catalog.get("snapshot_inventory_sha256") != inventory_sha
        or marker.get("verified") is not True
        or marker.get("read_only") is not True
    ):
        raise ReadinessError("snapshot envelope claims differ from sealed inventories")
    completed_at = marker.get("completed_at")
    attested_at = payload.get("attested_at")
    try:
        completed_epoch = time.mktime(
            time.strptime(str(completed_at), "%Y-%m-%dT%H:%M:%SZ")
        )
        attested_epoch = time.mktime(
            time.strptime(str(attested_at), "%Y-%m-%dT%H:%M:%SZ")
        )
    except (TypeError, ValueError, OverflowError) as exc:
        raise ReadinessError(
            "snapshot completion/attestation timestamps are invalid"
        ) from exc
    if attested_epoch < completed_epoch:
        raise ReadinessError("snapshot attestation predates sealed snapshot completion")
    proof = {
        "attestation_path": str(path.resolve()),
        "attestation_sha256": attestation_digest,
        "snapshot_root": str(root),
        "snapshot_id": str(payload["snapshot_id"]),
        "file_count": file_count,
        "total_bytes": total_bytes,
        "inventory_sha256": inventory_sha,
        "control_artifacts": {
            name: dict(controls[name]) for name in sorted(controls)
        },
    }
    if sealed_row is not None and proof != dict(sealed_row):
        raise ReadinessError(
            f"snapshot controls differ from generation seal: {root}"
        )
    snapshot_context.proofs[cache_key] = proof
    return proof


def _validate_sealed_snapshot_member(
    artifact_path: Path,
    payload: Mapping[str, Any],
    *,
    snapshot_context: _SnapshotValidationContext,
) -> None:
    raw = payload.get("sealed_snapshot_member")
    if raw is None:
        return
    if not isinstance(raw, dict):
        raise ReadinessError(
            f"sealed_snapshot_member must be an object: {artifact_path}"
        )
    _exact_keys(
        raw,
        {"snapshot_id", "snapshot_root", "logical_path", "sha256"},
        context=f"sealed_snapshot_member {artifact_path}",
    )
    snapshot_id = raw.get("snapshot_id")
    root_value = raw.get("snapshot_root")
    logical = raw.get("logical_path")
    digest = raw.get("sha256")
    if (
        not isinstance(snapshot_id, str)
        or not snapshot_id
        or not isinstance(root_value, str)
        or not Path(root_value).is_absolute()
        or not isinstance(logical, str)
        or not logical
        or not isinstance(digest, str)
        or _SHA256_RE.fullmatch(digest) is None
    ):
        raise ReadinessError(
            f"sealed_snapshot_member identity is invalid: {artifact_path}"
        )
    supplied_root = Path(root_value)
    if supplied_root.is_symlink():
        raise ReadinessError(
            f"sealed_snapshot_member root is symlinked: {supplied_root}"
        )
    root = supplied_root.resolve()
    if str(root) != root_value:
        raise ReadinessError(
            f"sealed_snapshot_member root is not canonical: {root_value}"
        )
    relative = Path(logical)
    if (
        relative.is_absolute()
        or ".." in relative.parts
        or relative.as_posix() != logical
        or logical in SNAPSHOT_CONTROL_FILENAMES
    ):
        raise ReadinessError(
            f"sealed_snapshot_member logical path is unsafe: {logical!r}"
        )
    matching_proofs = [
        proof
        for proof in snapshot_context.proofs.values()
        if proof.get("snapshot_root") == str(root)
        and proof.get("snapshot_id") == snapshot_id
    ]
    if len(matching_proofs) != 1:
        raise ReadinessError(
            "sealed_snapshot_member does not address exactly one attested snapshot"
        )
    member = {
        "snapshot_id": snapshot_id,
        "snapshot_root": str(root),
        "logical_path": logical,
        "sha256": digest,
    }
    if not snapshot_context.full:
        assert snapshot_context.seal is not None
        seal_matches = [
            row
            for row in snapshot_context.seal.get("sealed_members", [])
            if isinstance(row, dict) and row == member
        ]
        allowed = snapshot_context.allowed_members.get(
            (str(root), logical)
        ) == member
        if len(seal_matches) == 1 or allowed:
            snapshot_context.add_member(member)
            return
        if not snapshot_context.allow_inventory_lookup:
            raise ReadinessError(
                "sealed_snapshot_member is not bound by the rollout seal/readiness proof"
            )
        inventory = snapshot_context.inventories.get(str(root))
        if inventory is None:
            inventory_path = root / "SNAPSHOT_INVENTORY.sha256"
            try:
                raw_inventory = snapshot_integrity.read_regular_bytes(
                    inventory_path,
                    description="sealed snapshot membership inventory",
                )
            except snapshot_integrity.SnapshotIntegrityError as exc:
                raise ReadinessError(str(exc)) from exc
            inventory_digest = hashlib.sha256(raw_inventory).hexdigest()
            expected_control_digest = matching_proofs[0]["control_artifacts"][
                "SNAPSHOT_INVENTORY.sha256"
            ]["sha256"]
            if (
                inventory_digest != matching_proofs[0]["inventory_sha256"]
                or inventory_digest != expected_control_digest
            ):
                raise ReadinessError(
                    "sealed_snapshot_member inventory differs from generation seal"
                )
            try:
                inventory_lines = raw_inventory.decode("utf-8").splitlines()
            except UnicodeDecodeError as exc:
                raise ReadinessError(
                    "sealed_snapshot_member inventory is not UTF-8"
                ) from exc
            inventory = {}
            for raw_line in inventory_lines:
                row_digest, separator, row_logical = raw_line.partition("  ")
                if (
                    not separator
                    or _SHA256_RE.fullmatch(row_digest) is None
                    or not row_logical
                    or row_logical in inventory
                ):
                    raise ReadinessError(
                        "sealed snapshot membership inventory is malformed"
                    )
                inventory[row_logical] = row_digest
            snapshot_context.inventories[str(root)] = inventory
        if inventory.get(logical) != digest:
            raise ReadinessError(
                "sealed_snapshot_member logical path/hash is absent from snapshot inventory"
            )
        snapshot_context.add_member(member)
        return
    candidate = root / relative
    if candidate.is_symlink() or not candidate.is_file():
        raise ReadinessError(
            f"sealed_snapshot_member payload is missing/unsafe: {candidate}"
        )
    observed_digest, metadata = _snapshot_regular_sha256_with_metadata(
        candidate, context="sealed snapshot selected member"
    )
    if observed_digest != digest:
        raise ReadinessError(
            f"sealed_snapshot_member payload hash drifted: {candidate}"
        )
    inventory = snapshot_context.inventories.get(str(root))
    if inventory is None or inventory.get(logical) != digest:
        raise ReadinessError(
            "sealed_snapshot_member logical path/hash is absent from snapshot inventory"
        )
    snapshot_context.add_metadata_record(metadata)
    snapshot_context.add_member(member)


def _validate_referenced_artifact(
    reference: Mapping[str, Any],
    *,
    context: str,
    verified: set[tuple[str, str]],
    active: set[tuple[str, str]],
    snapshot_context: _SnapshotValidationContext | None = None,
) -> tuple[Path, Mapping[str, Any] | None]:
    if snapshot_context is None:
        snapshot_context = _SnapshotValidationContext(full=True)
    _exact_keys(reference, {"name", "path", "sha256"}, context=context)
    name = reference.get("name")
    path_value = reference.get("path")
    expected_hash = reference.get("sha256")
    if not isinstance(name, str) or not name:
        raise ReadinessError(f"{context} has invalid artifact name")
    if not isinstance(path_value, str) or not Path(path_value).is_absolute():
        raise ReadinessError(f"{context} artifact path must be absolute")
    if not isinstance(expected_hash, str) or len(expected_hash) != 64:
        raise ReadinessError(f"{context} has invalid SHA-256")
    supplied_path = Path(path_value)
    if supplied_path.is_symlink() or not supplied_path.is_file():
        raise ReadinessError(
            f"{context} artifact is missing or a symlink: {supplied_path}"
        )
    path = supplied_path.resolve()
    observed = sha256_file(path)
    if observed != expected_hash:
        raise ReadinessError(
            f"{context} artifact drifted: {path}; expected {expected_hash}, got {observed}"
        )
    identity = (str(path), observed)
    if identity in active:
        raise ReadinessError(f"recursive artifact cycle detected at {path}")
    if identity in verified:
        return path, None
    active.add(identity)
    try:
        nested_payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError):
        active.remove(identity)
        verified.add(identity)
        return path, None
    if not isinstance(nested_payload, dict):
        active.remove(identity)
        verified.add(identity)
        return path, None
    if nested_payload.get("kind") == "recovery_snapshot_external_attestation":
        _validate_snapshot_external_attestation(
            path, nested_payload, snapshot_context=snapshot_context
        )
    nested = nested_payload.get("referenced_artifacts")
    if nested is not None:
        if not isinstance(nested, list):
            raise ReadinessError(
                f"nested referenced_artifacts must be an array: {path}"
            )
        nested_names = [
            item.get("name") if isinstance(item, dict) else None for item in nested
        ]
        if len(nested_names) != len(set(nested_names)):
            raise ReadinessError(f"nested artifact names must be unique: {path}")
        for index, item in enumerate(nested):
            if not isinstance(item, dict):
                raise ReadinessError(
                    f"nested artifact reference {index} is not an object: {path}"
                )
            _validate_referenced_artifact(
                item,
                context=f"nested artifact {path}[{index}]",
                verified=verified,
                active=active,
                snapshot_context=snapshot_context,
            )
    _validate_sealed_snapshot_member(
        path, nested_payload, snapshot_context=snapshot_context
    )
    active.remove(identity)
    verified.add(identity)
    return path, nested_payload


def _validate_gate_metrics(
    control: Mapping[str, Any],
    gate: str,
    metrics: Mapping[str, Any],
    artifacts: Mapping[str, tuple[Path, Mapping[str, Any] | None]],
    *,
    now: float | None,
    snapshot_context: _SnapshotValidationContext,
) -> None:
    if gate == "snapshot":
        expected = {
            "snapshot_count": 2,
            "pre_repair_verified": True,
            "legacy_consolidated_verified": True,
        }
        _exact_keys(metrics, set(expected), context="snapshot metrics")
        _exact_integer(metrics["snapshot_count"], 2, context="snapshot_count")
        _exact_boolean(
            metrics["pre_repair_verified"], True, context="pre_repair_verified"
        )
        _exact_boolean(
            metrics["legacy_consolidated_verified"],
            True,
            context="legacy_consolidated_verified",
        )
        snapshot_roots: set[str] = set()
        snapshot_ids: set[str] = set()
        for name in READINESS_ARTIFACT_NAMES[gate]:
            payload = artifacts[name][1]
            if not isinstance(payload, dict):
                raise ReadinessError(f"snapshot artifact {name} must be JSON")
            _validate_snapshot_external_attestation(
                artifacts[name][0],
                payload,
                snapshot_context=snapshot_context,
            )
            snapshot_roots.add(str(Path(str(payload["snapshot_root"])).resolve()))
            snapshot_ids.add(str(payload["snapshot_id"]))
        if len(snapshot_roots) != 2 or len(snapshot_ids) != 2:
            raise ReadinessError(
                "pre-repair and consolidated snapshots must have distinct roots and IDs"
            )
        return
    exact_metrics: dict[str, Any]
    if gate == "migrations":
        exact_metrics = {
            "protocol_incidents_total": 22,
            "protocol_already_reset": 22,
            "sealed_incident_qids": 1_064,
            "migrated_checkpoints": 47,
            "remaining_schema1_checkpoints": 0,
            "permanent_ledgers_archived": 3,
            "unresolved_permanent_ledgers": 0,
        }
    elif gate == "semantic_audit":
        exact_metrics = {
            "complete_cells": 740,
            "active_validated_qids": 888_068,
            "corrupt_cells": 0,
            "permanent_cells": 0,
            "malformed_lines": 0,
            "duplicate_qids": 0,
            "unexpected_qids": 0,
            "repair_count": 0,
        }
    elif gate == "static_feasibility_certificate":
        authority = effective_protected_capacity_binding(
            control, verify_files=True
        )
        certificate = protected_capacity.load_static_feasibility_certificate(
            authority["static_feasibility_certificate_path"],
            expected_sha256=authority[
                "static_feasibility_certificate_sha256"
            ],
            expected_certificate_id=authority[
                "static_feasibility_certificate_id"
            ],
            expected_capacity_generation=authority[
                "capacity_generation"
            ],
            expected_base_fleet_contract_sha256=authority[
                "base_fleet_contract_sha256"
            ],
            expected_effective_fleet_contract_sha256=authority[
                "effective_fleet_contract_sha256"
            ],
            expected_additive_overlay_contract_sha256=authority[
                "additive_overlay_contract_sha256"
            ],
            expected_release_git_commit=str(
                control["immutable"]["git_commit"]
            ),
        )
        exact_metrics = {
            "capacity_generation": certificate.capacity_generation,
            "certificate_id": certificate.certificate_id,
            "certificate_sha256": certificate.sha256,
            "base_fleet_contract_sha256": (
                certificate.base_fleet_contract_sha256
            ),
            "effective_fleet_contract_sha256": (
                certificate.effective_fleet_contract_sha256
            ),
            "additive_overlay_contract_sha256": (
                certificate.additive_overlay_contract_sha256
            ),
            "effective_logical_replicas": (
                certificate.effective_logical_replicas
            ),
            "effective_active_gpus": certificate.effective_active_gpus,
            "selected_cell_count": int(
                certificate.payload["selected_cell_count"]
            ),
        }
        artifact = artifacts["preflight_capacity_certificate"][0]
        if artifact != certificate.path or sha256_file(artifact) != certificate.sha256:
            raise ReadinessError(
                "static-feasibility gate does not reference the exact current "
                "certificate"
            )
    elif gate == "protected_capacity":
        authority = effective_protected_capacity_binding(
            control, verify_files=True
        )
        contract = _load_protected_capacity_contract(
            control,
            path=authority["path"],
            expected_marker_id=str(authority["marker_id"]),
            expected_sha256=str(authority["sha256"]),
        )
        exact_metrics = {
            "capacity_generation": contract.capacity_generation,
            "marker_id": contract.marker_id,
            "marker_sha256": contract.sha256,
            "certificate_id": (
                contract.static_feasibility_certificate_id
            ),
            "effective_fleet_contract_sha256": (
                contract.effective_fleet_contract_sha256
            ),
            "effective_logical_replicas": (
                contract.effective_active_logical_replicas
            ),
            "effective_active_gpus": contract.effective_active_gpus,
            "retained_warm_turnover_gpus": (
                contract.retained_warm_turnover_gpus
            ),
            "attested_total_gpus": contract.attested_total_gpus,
        }
        artifact = artifacts["protected_capacity_marker"][0]
        if artifact != contract.path or sha256_file(artifact) != contract.sha256:
            raise ReadinessError(
                "protected-capacity gate does not reference the exact current "
                "marker"
            )
    elif gate == "fleet":
        fleet_binding = effective_fleet_contract_binding(
            control, verify_files=True
        )
        expected_keys = {
            "logical_replicas",
            "allocated_gpus",
            "healthy_replicas",
            "unhealthy_replicas",
            "profile_replicas",
            "revision_mismatches",
            "missing_profiles",
            "stale_registrations",
            "max_heartbeat_age_seconds",
            "captured_timestamp",
            "model_contract_sha256",
            "fleet_contract_sha256",
            "client_capacity_evidence_id",
            "client_partition",
            "client_qos",
            "client_cpu_limit",
            "client_memory_limit_mib",
            "client_max_submit_jobs",
            "transport_censor_protocol_version",
            "transport_censor_protocol_hash",
            "transport_uncertainty_binding_sha256",
            "scheduler_safety_evidence_id",
            "scheduler_safety_policy_id",
            "scheduler_safety_policy_contract_id",
            "scheduler_preemptible_partitions",
            "scheduler_partition_time_requirements_seconds",
        }
        _exact_keys(metrics, expected_keys, context="fleet metrics")
        for key, expected in {
            "logical_replicas": fleet_binding["logical_replicas"],
            "allocated_gpus": fleet_binding["allocated_gpus"],
            "healthy_replicas": fleet_binding["logical_replicas"],
            "unhealthy_replicas": 0,
            "revision_mismatches": 0,
            "missing_profiles": 0,
            "stale_registrations": 0,
            "client_cpu_limit": control["immutable"][
                "protected_client_cpus"
            ],
            "client_memory_limit_mib": control["immutable"][
                "protected_client_memory_mib"
            ],
            "client_max_submit_jobs": control["immutable"][
                "protected_client_submit_headroom"
            ],
        }.items():
            _exact_integer(metrics[key], expected, context=f"fleet {key}")
        if metrics.get("profile_replicas") != fleet_binding["profile_replicas"]:
            raise ReadinessError(
                "fleet profile replica counts do not match the effective contract"
            )
        if (
            metrics.get("model_contract_sha256")
            != control["immutable"]["model_contract_sha256"]
        ):
            raise ReadinessError(
                "fleet model-contract revision/hash does not match immutable pins"
            )
        if (
            metrics.get("fleet_contract_sha256")
            != fleet_binding["sha256"]
        ):
            raise ReadinessError("fleet-contract hash does not match immutable pins")
        age = metrics.get("max_heartbeat_age_seconds")
        if (
            not isinstance(age, (int, float))
            or isinstance(age, bool)
            or not 0 <= age <= 600
        ):
            raise ReadinessError(
                "fleet max_heartbeat_age_seconds must be within [0, 600]"
            )
        if (
            metrics.get("client_partition")
            != control["immutable"]["protected_client_partition"]
            or metrics.get("client_qos")
            != control["immutable"]["protected_client_qos"]
            or not isinstance(metrics.get("client_capacity_evidence_id"), str)
            or _SHA256_RE.fullmatch(
                metrics["client_capacity_evidence_id"]
            )
            is None
        ):
            raise ReadinessError(
                "fleet metrics lack the exact protected client partition/QOS "
                "capacity evidence identity"
            )
        transport_binding = control["immutable"][
            "transport_uncertainty_binding"
        ]
        if (
            metrics.get("transport_censor_protocol_version")
            != transport_binding["transport_censor_protocol_version"]
            or metrics.get("transport_censor_protocol_hash")
            != transport_binding["transport_censor_protocol_hash"]
            or metrics.get("transport_uncertainty_binding_sha256")
            != control["immutable"][
                "transport_uncertainty_binding_sha256"
            ]
            or any(
                _SHA256_RE.fullmatch(str(metrics.get(field, ""))) is None
                for field in (
                    "scheduler_safety_evidence_id",
                    "scheduler_safety_policy_id",
                    "scheduler_safety_policy_contract_id",
                )
            )
            or not isinstance(
                metrics.get("scheduler_preemptible_partitions"), list
            )
            or not isinstance(
                metrics.get(
                    "scheduler_partition_time_requirements_seconds"
                ),
                dict,
            )
        ):
            raise ReadinessError(
                "fleet metrics lack exact scheduler/transport provenance"
            )
        captured = metrics.get("captured_timestamp")
        if (
            not isinstance(captured, (int, float))
            or isinstance(captured, bool)
            or captured < 0
        ):
            raise ReadinessError("fleet captured_timestamp is invalid")
        if now is not None and not 0 <= now - float(captured) <= 600:
            raise ReadinessError(
                "fleet readiness evidence is not recent (<=600 seconds)"
            )
        fleet_contract = artifacts["fleet_contract"][0]
        if (
            str(fleet_contract) != str(Path(fleet_binding["path"]).resolve())
            or sha256_file(fleet_contract)
            != fleet_binding["sha256"]
        ):
            raise ReadinessError(
                "fleet evidence does not reference the exact immutable contract"
            )
        _validate_fleet_artifact(
            control,
            metrics,
            artifacts,
            snapshot_context=snapshot_context,
        )
        return
    elif gate == "context_audit":
        exact_metrics = {
            "dense_peer_requests": 43_092,
            "seven_agent_requests": 57_456,
            "failed_preflights": 0,
            "truncation_incidents": 0,
        }
        expected_keys = set(exact_metrics) | {"minimum_context_margin_tokens"}
        _exact_keys(metrics, expected_keys, context="context-audit metrics")
        margin = metrics.get("minimum_context_margin_tokens")
        if not isinstance(margin, int) or isinstance(margin, bool) or margin < 1_287:
            raise ReadinessError(
                "minimum context margin must be at least the audited 1,287 tokens"
            )
        for key, expected in exact_metrics.items():
            _exact_integer(metrics.get(key), expected, context=f"context_audit {key}")
        _validate_context_artifacts(
            control,
            metrics,
            artifacts,
            snapshot_context=snapshot_context,
        )
        return
    elif gate == "smoke_runs":
        exact_metrics = {
            "long_32b_cells": 15,
            "selective_long_cells": 20,
            "standard_canary_cells": 6,
            "schema5_complete_cells": 41,
            "context_incidents": 0,
            "protocol_incidents": 0,
            "transport_incidents": 0,
            "truncation_incidents": 0,
            "provenance_failures": 0,
            "trusted_generation_failures": 0,
        }
    elif gate == "email_test":
        expected_keys = {
            "recipient",
            "delivery_succeeded",
            "returncode",
            "acknowledged",
            "chain_id",
            "request_id",
            "release_tag",
            "release_git_commit",
            "challenge_generation",
            "challenge_id",
            "challenge_verifier",
            "acknowledged_at",
        }
        _exact_keys(metrics, expected_keys, context="email-test metrics")
        if metrics.get("recipient") != control.get("alert_email"):
            raise ReadinessError(
                "email readiness recipient does not match control alert_email"
            )
        _exact_boolean(
            metrics.get("delivery_succeeded"), True, context="email delivery"
        )
        _exact_integer(metrics.get("returncode"), 0, context="email returncode")
        _exact_boolean(
            metrics.get("acknowledged"), True, context="email receipt acknowledgement"
        )
        for field in (
            "chain_id",
            "request_id",
            "challenge_id",
            "challenge_verifier",
        ):
            if _SHA256_RE.fullmatch(str(metrics.get(field, ""))) is None:
                raise ReadinessError(
                    f"email receipt {field} must be a lowercase SHA-256"
                )
        if metrics.get("release_tag") != PRODUCTION_OPERATIONAL_TAG:
            raise ReadinessError(
                "email receipt release tag differs from production"
            )
        if (
            metrics.get("release_git_commit")
            != control["immutable"]["git_commit"]
        ):
            raise ReadinessError(
                "email receipt release commit differs from immutable control"
            )
        challenge_generation = metrics.get("challenge_generation")
        if (
            not isinstance(challenge_generation, int)
            or isinstance(challenge_generation, bool)
            or challenge_generation < 0
        ):
            raise ReadinessError(
                "email receipt challenge generation is invalid"
            )
        try:
            time.strptime(
                str(metrics.get("acknowledged_at")), "%Y-%m-%dT%H:%M:%SZ"
            )
        except ValueError as exc:
            raise ReadinessError(
                "email receipt acknowledged_at must be a canonical UTC timestamp"
            ) from exc
        _validate_email_artifact(
            control,
            metrics,
            artifacts,
            snapshot_context=snapshot_context,
        )
        return
    else:
        raise ReadinessError(f"no typed readiness contract exists for gate {gate!r}")
    _exact_keys(metrics, set(exact_metrics), context=f"{gate} metrics")
    for key, expected in exact_metrics.items():
        if isinstance(expected, bool):
            _exact_boolean(metrics.get(key), expected, context=f"{gate} {key}")
        elif isinstance(expected, int):
            _exact_integer(metrics.get(key), expected, context=f"{gate} {key}")
        elif metrics.get(key) != expected:
            raise ReadinessError(f"{gate} {key} must equal {expected!r}")
    if gate == "migrations":
        _validate_migration_artifacts(
            control,
            metrics,
            artifacts,
            snapshot_context=snapshot_context,
        )
    elif gate == "semantic_audit":
        _validate_semantic_artifact(
            control,
            metrics,
            artifacts,
            snapshot_context=snapshot_context,
        )
    elif gate == "smoke_runs":
        _validate_smoke_artifacts(control, metrics, artifacts)


def _validate_scheduler_gate_payload(
    control: Mapping[str, Any], payload: Mapping[str, Any]
) -> None:
    _exact_keys(
        payload,
        {
            "schema_version",
            "gate",
            "immutable_sha256",
            "captured_at",
            "captured_timestamp",
            "all",
            "no_admit",
            "scheduler",
            "roles",
            "ambiguous_tokens",
            "unmappable_job_ids",
            "malformed_token_job_ids",
            "referenced_job_ids_absent_from_window",
            "errors",
            "passed",
        },
        context="scheduler reconciliation evidence",
    )
    if (
        payload.get("schema_version") != 1
        or payload.get("gate") != "scheduler_reconciliation"
    ):
        raise ReadinessError("scheduler reconciliation evidence has invalid identity")
    if payload.get("immutable_sha256") != control["immutable_sha256"]:
        raise ReadinessError("scheduler reconciliation was produced for different pins")
    if (
        payload.get("passed") is not True
        or payload.get("all") is not True
        or payload.get("no_admit") is not True
    ):
        raise ReadinessError("scheduler reconciliation must pass with --all --no-admit")
    scheduler = payload.get("scheduler")
    if not isinstance(scheduler, dict):
        raise ReadinessError("scheduler reconciliation lacks typed scheduler facts")
    _exact_keys(
        scheduler,
        {"squeue_ok", "sacct_ok", "job_count", "schema5_job_count"},
        context="scheduler reconciliation scheduler facts",
    )
    if scheduler.get("squeue_ok") is not True or scheduler.get("sacct_ok") is not True:
        raise ReadinessError(
            "scheduler reconciliation lacks complete squeue+sacct truth"
        )
    for field in ("job_count", "schema5_job_count"):
        value = scheduler.get(field)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ReadinessError(f"scheduler reconciliation {field} is invalid")
    if scheduler["schema5_job_count"] != 0:
        raise ReadinessError(
            "pre-resume scheduler reconciliation must contain no controller jobs"
        )
    for field in ("errors", "unmappable_job_ids", "malformed_token_job_ids"):
        if payload.get(field) != []:
            raise ReadinessError(f"scheduler reconciliation {field} must be empty")
    if payload.get("ambiguous_tokens") != {}:
        raise ReadinessError("scheduler reconciliation contains ambiguous intents")
    if payload.get("referenced_job_ids_absent_from_window") != []:
        raise ReadinessError(
            "scheduler reconciliation has controller IDs outside its window"
        )
    roles = payload.get("roles")
    if not isinstance(roles, dict) or set(roles) != set(ROLE_NAMES):
        raise ReadinessError("scheduler reconciliation role coverage is incomplete")
    for role, state in roles.items():
        if not isinstance(state, dict) or set(state) != {
            "active",
            "successor",
            "submission_intent",
        }:
            raise ReadinessError(f"scheduler reconciliation role {role} is malformed")
        if any(state[field] is not None for field in state):
            raise ReadinessError(
                f"pre-resume scheduler reconciliation unexpectedly references {role} jobs"
            )
    captured = payload.get("captured_timestamp")
    if (
        not isinstance(captured, (int, float))
        or isinstance(captured, bool)
        or captured < 0
    ):
        raise ReadinessError("scheduler reconciliation captured_timestamp is invalid")
    if payload.get("captured_at") != utc_timestamp(float(captured)):
        raise ReadinessError("scheduler reconciliation timestamps disagree")


def _validate_attestation(
    control: Mapping[str, Any],
    gate: str,
    evidence_path: Path,
    expected_sha256: str,
    *,
    now: float | None = None,
    snapshot_context: _SnapshotValidationContext | None = None,
) -> None:
    if snapshot_context is None:
        snapshot_context = _SnapshotValidationContext(full=True)
    if evidence_path.is_symlink() or not evidence_path.is_file():
        raise ReadinessError(
            f"readiness evidence is missing for {gate}: {evidence_path}"
        )
    observed = sha256_file(evidence_path)
    if observed != expected_sha256:
        raise ReadinessError(
            f"readiness evidence drifted for {gate}: expected {expected_sha256}, got {observed}"
        )
    try:
        payload = json.loads(evidence_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReadinessError(
            f"readiness evidence for {gate} is not valid JSON: {exc}"
        ) from exc
    if not isinstance(payload, dict) or payload.get("passed") is not True:
        raise ReadinessError(
            f"readiness evidence for {gate} does not attest passed=true"
        )
    if payload.get("gate") != gate:
        raise ReadinessError(
            f"readiness evidence gate mismatch: expected {gate!r}, got {payload.get('gate')!r}"
        )
    if payload.get("immutable_sha256") != control["immutable_sha256"]:
        raise ReadinessError(
            f"readiness evidence for {gate} was produced for different pins"
        )
    if gate == "scheduler_reconciliation":
        _validate_scheduler_gate_payload(control, payload)
        return
    _exact_keys(
        payload,
        {
            "schema_version",
            "gate",
            "passed",
            "immutable_sha256",
            "metrics",
            "artifacts",
        },
        context=f"readiness evidence for {gate}",
    )
    if payload.get("schema_version") != READINESS_EVIDENCE_SCHEMA_VERSION:
        raise ReadinessError(
            f"readiness evidence for {gate} must use schema "
            f"{READINESS_EVIDENCE_SCHEMA_VERSION}"
        )
    metrics = payload.get("metrics")
    artifact_rows = payload.get("artifacts")
    if not isinstance(metrics, dict):
        raise ReadinessError(f"readiness metrics for {gate} must be an object")
    if not isinstance(artifact_rows, list):
        raise ReadinessError(f"readiness artifacts for {gate} must be an array")
    expected_names = READINESS_ARTIFACT_NAMES[gate]
    observed_names = [
        row.get("name") if isinstance(row, dict) else None for row in artifact_rows
    ]
    if len(observed_names) != len(set(observed_names)) or set(observed_names) != set(
        expected_names
    ):
        raise ReadinessError(
            f"readiness artifacts for {gate} must be exactly {sorted(expected_names)}"
        )
    verified: dict[str, tuple[Path, Mapping[str, Any] | None]] = {}
    verified_identities: set[tuple[str, str]] = set()
    active_identities: set[tuple[str, str]] = set()
    for index, row in enumerate(artifact_rows):
        assert isinstance(row, dict)
        name = str(row["name"])
        verified[name] = _validate_referenced_artifact(
            row,
            context=f"readiness artifact {gate}[{index}]",
            verified=verified_identities,
            active=active_identities,
            snapshot_context=snapshot_context,
        )
    _validate_gate_metrics(
        control,
        gate,
        metrics,
        verified,
        now=now,
        snapshot_context=snapshot_context,
    )


def _read_stable_authorization_file(
    path: Path, *, description: str
) -> tuple[Path, bytes]:
    """Read one sealed single-link file without following any symlink component."""

    lexical = Path(os.path.abspath(os.fspath(path.expanduser())))
    if any(character in str(lexical) for character in ("\x00", "\n", "\r")):
        raise ReadinessError(f"{description} path is unsafe")
    try:
        resolved = lexical.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise ReadinessError(f"{description} is unavailable: {exc}") from exc
    if resolved != lexical:
        raise ReadinessError(f"{description} traverses a symlink")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(lexical, flags)
    except OSError as exc:
        raise ReadinessError(f"cannot open {description}: {exc}") from exc
    try:
        before = os.fstat(descriptor)
        chunks: list[bytes] = []
        while block := os.read(descriptor, 1024 * 1024):
            chunks.append(block)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    identity = lambda value: (
        value.st_dev,
        value.st_ino,
        value.st_mode,
        value.st_nlink,
        value.st_size,
        value.st_mtime_ns,
        value.st_ctime_ns,
    )
    try:
        current = lexical.stat(follow_symlinks=False)
    except OSError as exc:
        raise ReadinessError(f"cannot restat {description}: {exc}") from exc
    if (
        not stat.S_ISREG(before.st_mode)
        or identity(before) != identity(after)
        or (current.st_dev, current.st_ino) != (after.st_dev, after.st_ino)
        or stat.S_IMODE(before.st_mode) & 0o222
        or before.st_nlink != 1
    ):
        raise ReadinessError(
            f"{description} is mutable, linked, or changed while being read"
        )
    return lexical, b"".join(chunks)


def _parse_authorization_json(
    raw: bytes, *, description: str
) -> dict[str, Any]:
    def reject_duplicates(pairs: Sequence[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ReadinessError(
                    f"{description} duplicates JSON key {key!r}"
                )
            result[key] = value
        return result

    def reject_nonfinite(token: str) -> Any:
        raise ReadinessError(f"{description} contains non-finite {token}")

    try:
        value = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicates,
            parse_constant=reject_nonfinite,
        )
    except ReadinessError:
        raise
    except (UnicodeError, json.JSONDecodeError, ValueError) as exc:
        raise ReadinessError(f"{description} is invalid JSON: {exc}") from exc
    if not isinstance(value, dict):
        raise ReadinessError(f"{description} must contain one JSON object")
    return value


def _authorization_file_binding(
    path: Path,
    *,
    description: str,
    identity_field: str | None = None,
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    canonical, raw = _read_stable_authorization_file(
        path, description=description
    )
    binding: dict[str, Any] = {
        "path": str(canonical),
        "sha256": hashlib.sha256(raw).hexdigest(),
        "size": len(raw),
    }
    value: dict[str, Any] | None = None
    if identity_field is not None:
        value = _parse_authorization_json(raw, description=description)
        identity = value.get(identity_field)
        if not isinstance(identity, str) or not identity:
            raise ReadinessError(
                f"{description} lacks {identity_field!r} identity"
            )
        binding[identity_field] = identity
    return binding, value


def _authorization_lineage(
    control: Mapping[str, Any],
    manifest: Mapping[str, Any],
    *,
    chain_id: str,
) -> dict[str, str]:
    immutable = control["immutable"]
    capacity_authority = effective_protected_capacity_binding(
        control, verify_files=True
    )
    marker_path = Path(str(capacity_authority["path"]))
    marker_binding, marker = _authorization_file_binding(
        marker_path,
        description="protected-capacity release lineage",
        identity_field="marker_id",
    )
    assert marker is not None
    if (
        marker_binding["sha256"]
        != capacity_authority["sha256"]
        or marker_binding["marker_id"]
        != capacity_authority["marker_id"]
    ):
        raise ReadinessError(
            "production authorization protected-capacity lineage drifted"
        )
    lineage = {
        "release_id": str(manifest.get("release_id", "")),
        "release_tag": str(manifest.get("release_tag", "")),
        "release_git_commit": str(
            manifest.get("release_git_commit", "")
        ),
        "release_tag_object": str(
            manifest.get("release_tag_object", "")
        ),
        "immutable_sha256": str(control["immutable_sha256"]),
        "chain_id": chain_id,
    }
    if (
        lineage["release_id"] != immutable["release_id"]
        or lineage["release_id"] != PRODUCTION_RELEASE_ID
        or lineage["release_tag"] != PRODUCTION_OPERATIONAL_TAG
        or lineage["release_git_commit"] != immutable["git_commit"]
        or _SHA256_RE.fullmatch(lineage["chain_id"]) is None
        or re.fullmatch(r"[0-9a-f]{40}", lineage["release_tag_object"])
        is None
        or marker.get("release_id") != lineage["release_id"]
        or marker.get("release_tag") != lineage["release_tag"]
        or marker.get("release_git_commit")
        != lineage["release_git_commit"]
        or marker.get("release_tag_object")
        != lineage["release_tag_object"]
    ):
        raise ReadinessError(
            "production authorization chain has the wrong release lineage"
        )
    return lineage


def _sanitized_subprocess_environment() -> dict[str, str]:
    """Return the fixed Git/Slurm command environment for the control plane."""

    environment = dict(os.environ)
    for name in tuple(environment):
        if name in _BLOCKED_SUBPROCESS_ENVIRONMENT or name.startswith(
            _BLOCKED_SUBPROCESS_ENVIRONMENT_PREFIXES
        ):
            environment.pop(name, None)
    environment.update(
        {
            "PATH": TRUSTED_SYSTEM_PATH,
            "LANG": "C",
            "LC_ALL": "C",
            "GIT_ATTR_NOSYSTEM": "1",
            "GIT_CONFIG_GLOBAL": os.devnull,
            "GIT_CONFIG_NOSYSTEM": "1",
            "GIT_NO_REPLACE_OBJECTS": "1",
            "GIT_OPTIONAL_LOCKS": "0",
            "GIT_PAGER": "cat",
            "GIT_TERMINAL_PROMPT": "0",
            "PAGER": "cat",
        }
    )
    return environment


def _trusted_shell_prelude() -> str:
    """Return the fail-closed bootstrap shared by generated production jobs."""

    return f"""\
unset BASH_ENV CDPATH ENV LD_AUDIT LD_LIBRARY_PATH LD_PRELOAD
unset GIT_ALTERNATE_OBJECT_DIRECTORIES GIT_ATTR_NOSYSTEM GIT_CEILING_DIRECTORIES
unset GIT_COMMON_DIR GIT_CONFIG GIT_CONFIG_COUNT GIT_CONFIG_GLOBAL
unset GIT_CONFIG_NOSYSTEM GIT_CONFIG_PARAMETERS GIT_CONFIG_SYSTEM GIT_DIR
unset GIT_DISCOVERY_ACROSS_FILESYSTEM GIT_EXEC_PATH GIT_INDEX_FILE GIT_NAMESPACE
unset GIT_NO_REPLACE_OBJECTS GIT_OBJECT_DIRECTORY GIT_REPLACE_REF_BASE
unset GIT_SHALLOW_FILE GIT_SSH GIT_SSH_COMMAND GIT_TEMPLATE_DIR GIT_WORK_TREE
unset SLURM_CLUSTERS SLURM_CONF SLURM_EXIT_ERROR SLURM_TIME_FORMAT
while IFS= read -r ambient_name; do
  case "$ambient_name" in
    ASYS_*|BASH_FUNC_*|PIP_*|PYTHON*|CONDA_*|HF_*|TRANSFORMERS_*|VLLM_*|GIT_CONFIG_KEY_*|GIT_CONFIG_VALUE_*|GIT_TRACE*|SACCT_*|SBATCH_*|SCONTROL_*|SQUEUE_*)
      builtin unset -v "$ambient_name" 2>/dev/null || true
      ;;
  esac
done < <(compgen -e)
export PATH={TRUSTED_SYSTEM_PATH}
readonly PATH
while read -r _ _ ambient_function; do
  builtin unset -f "$ambient_function"
done < <(builtin declare -F)
export LANG=C LC_ALL=C
export GIT_ATTR_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
export GIT_NO_REPLACE_OBJECTS=1 GIT_OPTIONAL_LOCKS=0 GIT_TERMINAL_PROMPT=0
export GIT_PAGER=cat PAGER=cat
"""


def _validate_trusted_sbatch_bootstrap(payload: str, *, description: str) -> None:
    """Reject a job script that can inherit an ambient shell/toolchain authority."""

    lines = [line.strip() for line in payload.splitlines()]
    export_directives = [
        line for line in lines if line.startswith("#SBATCH --export=")
    ]
    if export_directives != ["#SBATCH --export=NONE"]:
        raise ControlError(
            f"{description} must contain exactly one #SBATCH --export=NONE directive"
        )
    required = {
        "set -euo pipefail",
        "umask 027",
        "unset BASH_ENV CDPATH ENV LD_AUDIT LD_LIBRARY_PATH LD_PRELOAD",
        f"export PATH={TRUSTED_SYSTEM_PATH}",
        "readonly PATH",
        "export LANG=C LC_ALL=C",
        (
            "export GIT_ATTR_NOSYSTEM=1 GIT_CONFIG_GLOBAL=/dev/null "
            "GIT_CONFIG_NOSYSTEM=1"
        ),
        (
            "export GIT_NO_REPLACE_OBJECTS=1 GIT_OPTIONAL_LOCKS=0 "
            "GIT_TERMINAL_PROMPT=0"
        ),
    }
    missing = sorted(required - set(lines))
    if missing:
        raise ControlError(
            f"{description} lacks trusted shell bootstrap lines: "
            + ", ".join(missing)
        )
    try:
        directive_index = lines.index("#SBATCH --export=NONE")
        strict_index = lines.index("set -euo pipefail")
        scrub_index = lines.index(
            "unset BASH_ENV CDPATH ENV LD_AUDIT LD_LIBRARY_PATH LD_PRELOAD"
        )
        path_index = lines.index(f"export PATH={TRUSTED_SYSTEM_PATH}")
        locale_index = lines.index("export LANG=C LC_ALL=C")
    except ValueError as exc:  # pragma: no cover - guarded by the required set
        raise ControlError(f"{description} has an incomplete shell bootstrap") from exc
    if not directive_index < strict_index < scrub_index < path_index < locale_index:
        raise ControlError(
            f"{description} initializes its trusted shell bootstrap out of order"
        )


def _trusted_system_argv(argv: Sequence[str]) -> list[str]:
    command = list(argv)
    if not command or not all(
        isinstance(value, str) and value for value in command
    ):
        raise ControlError("scheduler subprocess argv is empty or invalid")
    executable = _TRUSTED_SYSTEM_EXECUTABLES.get(command[0])
    if executable is not None:
        command[0] = executable
    return command


def _production_authorization_environment(
    control: Mapping[str, Any]
) -> dict[str, str]:
    """Build the isolated, offline verifier environment from immutable pins."""

    harness = Path(
        str(control["immutable"]["harness_environment_prefix"])
    ).expanduser().resolve()
    environment = _sanitized_subprocess_environment()
    for name in tuple(environment):
        if name.startswith(("PYTHON", "PIP_", "CONDA_")) or name == "VIRTUAL_ENV":
            environment.pop(name, None)
    environment.update(
        {
            "PYTHONDONTWRITEBYTECODE": "1",
            "PYTHONNOUSERSITE": "1",
            "PYTHONSAFEPATH": "1",
            "HF_HUB_OFFLINE": "1",
            "TRANSFORMERS_OFFLINE": "1",
            "HF_DATASETS_OFFLINE": "1",
            "PIP_CONFIG_FILE": os.devnull,
            "PIP_NO_INPUT": "1",
            "PIP_DISABLE_PIP_VERSION_CHECK": "1",
            "CONDARC": os.devnull,
            "CONDA_NO_PLUGINS": "true",
            "LD_LIBRARY_PATH": str(harness / "lib"),
        }
    )
    return environment


def _invoke_production_authorization_verifier(
    control: Mapping[str, Any],
    *,
    gate: str,
    chain_manifest: Path,
    verifier_runner: (
        Callable[
            [Sequence[str], Mapping[str, str], float],
            subprocess.CompletedProcess[str],
        ]
        | None
    ) = None,
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
]:
    immutable = control["immutable"]
    harness_prefix = (
        Path(str(immutable["harness_environment_prefix"]))
        .expanduser()
        .resolve()
    )
    try:
        # Conda normally publishes ``bin/python`` as a same-prefix symlink.  Invoke
        # and bind its sealed regular target so the verifier never trusts a symlink
        # inode while retaining the exact pinned environment.
        harness_python = (harness_prefix / "bin" / "python").resolve(
            strict=True
        )
        harness_python.relative_to(harness_prefix)
    except (OSError, RuntimeError, ValueError) as exc:
        raise ReadinessError(
            "pinned production-authorization Python escapes its harness prefix"
        ) from exc
    verifier = (
        Path(str(immutable["release_worktree"])).expanduser().resolve()
        / PRODUCTION_AUTHORIZATION_VERIFIER
    )
    python_binding, _ = _authorization_file_binding(
        harness_python,
        description="pinned production-authorization harness Python",
    )
    verifier_binding, _ = _authorization_file_binding(
        verifier,
        description="frozen production-authorization verifier",
    )
    manifest_binding, manifest = _authorization_file_binding(
        chain_manifest,
        description="production-authorization chain manifest",
        identity_field="chain_id",
    )
    assert manifest is not None
    subcommand = {
        "throughput_qualification": "verify-throughput-qualification",
        "external_watchdog": "verify-watchdog-readiness",
    }[gate]
    argv = [
        str(harness_python),
        "-I",
        str(verifier),
        subcommand,
        "--chain-manifest",
        str(Path(str(manifest_binding["path"]))),
    ]
    environment = _production_authorization_environment(control)
    try:
        if verifier_runner is None:
            completed = subprocess.run(
                argv,
                capture_output=True,
                text=True,
                check=False,
                env=environment,
                timeout=PRODUCTION_AUTHORIZATION_VERIFIER_TIMEOUT_SECONDS,
            )
        else:
            completed = verifier_runner(
                argv,
                environment,
                PRODUCTION_AUTHORIZATION_VERIFIER_TIMEOUT_SECONDS,
            )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise ReadinessError(
            f"{gate} frozen verifier could not run: {exc}"
        ) from exc
    if completed.returncode != 0:
        raise ReadinessError(
            f"{gate} frozen verifier failed ({completed.returncode}): "
            f"{completed.stderr.strip()[:1000]}"
        )
    report = _parse_authorization_json(
        completed.stdout.encode("utf-8"),
        description=f"{gate} frozen verifier output",
    )
    if (
        report.get("passed") is not True
        or report.get("chain_id") != manifest_binding["chain_id"]
        or report.get("manifest") != manifest_binding["path"]
    ):
        raise ReadinessError(
            f"{gate} frozen verifier did not bind the exact chain manifest"
        )
    return (
        report,
        manifest_binding,
        manifest,
        {
            "harness_python": python_binding,
            "verifier": verifier_binding,
        },
    )


def _binding_matches_file(
    binding: Mapping[str, Any],
    *,
    description: str,
    identity_field: str | None = None,
) -> dict[str, Any] | None:
    expected = {"path", "sha256", "size"}
    if identity_field is not None:
        expected.add(identity_field)
    if set(binding) != expected:
        raise ReadinessError(f"{description} binding fields drifted")
    path = Path(str(binding.get("path", "")))
    observed, value = _authorization_file_binding(
        path,
        description=description,
        identity_field=identity_field,
    )
    if observed != dict(binding):
        raise ReadinessError(f"{description} binding drifted")
    return value


def _build_throughput_authorization_artifacts(
    report: Mapping[str, Any],
    *,
    evidence_path: Path | None,
    expected_sha256: str | None,
    manifest_binding: Mapping[str, Any],
    lineage: Mapping[str, str],
) -> tuple[dict[str, Any], dict[str, Any]]:
    exact_report_fields = {
        "passed",
        "chain_id",
        "manifest",
        "qualification_marker",
        "attempt_marker",
        "attempt_id",
        "attempt_pointer",
        "qualification_id",
        "cells",
        "qids",
        "health_soak_384_seconds",
        "loaded_384_seconds",
        "loaded_384_useful_qids",
        "loaded_384_observation_count",
        "loaded_384_exact_saturation",
        "throughput_qids_per_day",
        "chain_verification",
    }
    if set(report) != exact_report_fields:
        raise ReadinessError(
            "throughput-qualification verifier output fields drifted"
        )
    if (
        report.get("cells") != 768
        or report.get("qids") != 15_360
        or not isinstance(report.get("health_soak_384_seconds"), (int, float))
        or isinstance(report.get("health_soak_384_seconds"), bool)
        or float(report["health_soak_384_seconds"]) < 7_200
        or not isinstance(report.get("loaded_384_seconds"), (int, float))
        or isinstance(report.get("loaded_384_seconds"), bool)
        or not 0 < float(report["loaded_384_seconds"]) <= float(
            report["health_soak_384_seconds"]
        )
        or not isinstance(report.get("loaded_384_useful_qids"), int)
        or isinstance(report.get("loaded_384_useful_qids"), bool)
        or not 0 < int(report["loaded_384_useful_qids"]) <= 15_360
        or not isinstance(report.get("loaded_384_observation_count"), int)
        or isinstance(report.get("loaded_384_observation_count"), bool)
        or int(report["loaded_384_observation_count"]) < 2
        or report.get("loaded_384_exact_saturation") is not True
        or not isinstance(report.get("chain_verification"), Mapping)
        or report["chain_verification"].get("chain_id")
        != report["chain_id"]
    ):
        raise ReadinessError(
            "throughput-qualification verifier output is incomplete"
        )
    fixed, fixed_value = _authorization_file_binding(
        Path(str(report["qualification_marker"])),
        description="fixed throughput-qualification marker",
        identity_field="qualification_id",
    )
    attempt, attempt_value = _authorization_file_binding(
        Path(str(report["attempt_marker"])),
        description="current throughput-qualification attempt marker",
        identity_field="qualification_id",
    )
    pointer, pointer_value = _authorization_file_binding(
        Path(str(report["attempt_pointer"])),
        description="current throughput-qualification attempt pointer",
        identity_field="pointer_id",
    )
    assert fixed_value is not None
    assert attempt_value is not None
    assert pointer_value is not None
    current_path = Path(str(fixed["path"])).parent / "CURRENT_ATTEMPT.json"
    current, current_value = _authorization_file_binding(
        current_path,
        description="current throughput-qualification attempt selector",
        identity_field="current_id",
    )
    assert current_value is not None
    if (
        fixed["qualification_id"] != report["qualification_id"]
        or attempt["qualification_id"] != report["qualification_id"]
        or fixed["sha256"] != attempt["sha256"]
        or fixed["size"] != attempt["size"]
        or pointer_value.get("attempt_id") != report["attempt_id"]
        or current_value.get("attempt_id") != report["attempt_id"]
        or current_value.get("pointer") != pointer["path"]
        or current_value.get("pointer_sha256") != pointer["sha256"]
        or current_value.get("pointer_id") != pointer["pointer_id"]
        or pointer_value.get("chain_id") != lineage["chain_id"]
        or fixed_value.get("chain_id") != lineage["chain_id"]
        or fixed_value.get("manifest") != manifest_binding["path"]
        or fixed_value.get("manifest_sha256")
        != manifest_binding["sha256"]
        or fixed_value.get("release_id") != lineage["release_id"]
        or fixed_value.get("release_tag") != lineage["release_tag"]
        or fixed_value.get("release_git_commit")
        != lineage["release_git_commit"]
        or fixed_value.get("release_tag_object")
        != lineage["release_tag_object"]
    ):
        raise ReadinessError(
            "throughput-qualification artifacts do not bind one exact attempt"
        )
    if evidence_path is not None and evidence_path.expanduser().resolve() != Path(
        str(fixed["path"])
    ):
        raise ReadinessError(
            "--evidence must be the verifier-selected qualification marker"
        )
    if expected_sha256 is not None and expected_sha256 != fixed["sha256"]:
        raise ReadinessError(
            "throughput-qualification evidence hash differs from the verifier"
        )
    readiness = pointer_value.get("readiness_generation")
    if not isinstance(readiness, Mapping):
        raise ReadinessError(
            "throughput-qualification pointer lacks readiness generation"
        )
    generation_fields = (
        "rollout_generation",
        "capacity_generation",
        "catalog_id",
        "fleet_contract_sha256",
        "release_fleet_contract_sha256",
    )
    if any(field not in readiness for field in generation_fields):
        raise ReadinessError(
            "throughput-qualification readiness generation is incomplete"
        )
    generation = {field: readiness[field] for field in generation_fields}
    for field in ("rollout_generation", "capacity_generation"):
        if (
            not isinstance(generation[field], int)
            or isinstance(generation[field], bool)
            or generation[field] < 1
        ):
            raise ReadinessError(
                "throughput-qualification generation is malformed"
            )
    for field in (
        "catalog_id",
        "fleet_contract_sha256",
        "release_fleet_contract_sha256",
    ):
        if _SHA256_RE.fullmatch(str(generation[field])) is None:
            raise ReadinessError(
                "throughput-qualification generation hash is malformed"
            )
    artifacts = {
        "qualification_marker": fixed,
        "attempt_marker": attempt,
        "attempt_pointer": {
            **pointer,
            "attempt_id": str(report["attempt_id"]),
        },
        "current_attempt": {
            **current,
            "attempt_id": str(report["attempt_id"]),
            "pointer_id": str(pointer["pointer_id"]),
        },
    }
    return artifacts, generation


def _build_watchdog_authorization_artifacts(
    report: Mapping[str, Any],
    *,
    control: Mapping[str, Any],
    evidence_path: Path | None,
    expected_sha256: str | None,
) -> dict[str, Any]:
    exact_report_fields = {
        "passed",
        "chain_id",
        "manifest",
        "control_sha256",
        "external_watchdog_drill",
        "watchdog_ready",
    }
    if set(report) != exact_report_fields:
        raise ReadinessError("external-watchdog verifier output fields drifted")
    if report.get("control_sha256") != control["immutable_sha256"]:
        raise ReadinessError(
            "external-watchdog verifier binds a different control"
        )
    artifacts: dict[str, Any] = {}
    for report_name, identity_field, stored_name in (
        ("external_watchdog_drill", "drill_id", "watchdog_drill"),
        ("watchdog_ready", "marker_id", "watchdog_ready"),
    ):
        source = report.get(report_name)
        expected_fields = {
            "marker",
            "marker_sha256",
            "marker_size",
            "protocol",
            identity_field,
        }
        if not isinstance(source, Mapping) or set(source) != expected_fields:
            raise ReadinessError(
                f"external-watchdog {report_name} binding fields drifted"
            )
        observed, value = _authorization_file_binding(
            Path(str(source["marker"])),
            description=f"external-watchdog {report_name} marker",
            identity_field=identity_field,
        )
        assert value is not None
        expected = {
            "path": source["marker"],
            "sha256": source["marker_sha256"],
            "size": source["marker_size"],
            identity_field: source[identity_field],
        }
        if (
            observed != expected
            or value.get(identity_field) != source[identity_field]
            or value.get("control_sha256") != control["immutable_sha256"]
        ):
            raise ReadinessError(
                f"external-watchdog {report_name} marker drifted"
            )
        artifacts[stored_name] = {
            **observed,
            "protocol": str(source["protocol"]),
        }
    ready = artifacts["watchdog_ready"]
    if evidence_path is not None and evidence_path.expanduser().resolve() != Path(
        str(ready["path"])
    ):
        raise ReadinessError(
            "--evidence must be the verifier-selected WATCHDOG_READY marker"
        )
    if expected_sha256 is not None and expected_sha256 != ready["sha256"]:
        raise ReadinessError(
            "external-watchdog evidence hash differs from the verifier"
        )
    return artifacts


def _authorization_record_identity(record: Mapping[str, Any]) -> str:
    identity = dict(record)
    identity.pop("authorization_id", None)
    return sha256_value(identity)


def _production_authorization_core(record: Mapping[str, Any]) -> dict[str, Any]:
    return {
        key: copy.deepcopy(value)
        for key, value in record.items()
        if key
        not in {
            "authorization_id",
            "attested_at",
            "attested_timestamp",
        }
    }


def _validate_production_authorization_record(
    control: Mapping[str, Any],
    *,
    gate: str,
    record: Mapping[str, Any],
    state_dir: Path,
    verify_files: bool,
) -> None:
    common_fields = {
        "schema_version",
        "protocol",
        "gate",
        "passed",
        "authorization_id",
        "chain_id",
        "chain_manifest",
        "harness_python",
        "verifier",
        "verifier_report_sha256",
        "release_lineage",
        "artifacts",
        "qualification_generation",
        "attested_at",
        "attested_timestamp",
    }
    if set(record) != common_fields:
        raise ReadinessError(
            f"{gate} production-authorization fields drifted"
        )
    authorization_id = str(record.get("authorization_id", ""))
    lineage = record.get("release_lineage")
    chain_manifest = record.get("chain_manifest")
    harness_python = record.get("harness_python")
    verifier = record.get("verifier")
    bindings_valid = bool(
        isinstance(chain_manifest, Mapping)
        and set(chain_manifest) == {"path", "sha256", "size", "chain_id"}
        and isinstance(harness_python, Mapping)
        and set(harness_python) == {"path", "sha256", "size"}
        and isinstance(verifier, Mapping)
        and set(verifier) == {"path", "sha256", "size"}
    )
    if (
        record.get("schema_version")
        != PRODUCTION_AUTHORIZATION_SCHEMA_VERSION
        or record.get("protocol") != PRODUCTION_AUTHORIZATION_PROTOCOL
        or record.get("gate") != gate
        or record.get("passed") is not True
        or _SHA256_RE.fullmatch(authorization_id) is None
        or authorization_id != _authorization_record_identity(record)
        or record.get("chain_id")
        != (lineage.get("chain_id") if isinstance(lineage, Mapping) else None)
        or not isinstance(record.get("attested_at"), str)
        or not isinstance(record.get("attested_timestamp"), (int, float))
        or isinstance(record.get("attested_timestamp"), bool)
        or not math.isfinite(float(record.get("attested_timestamp", 0)))
        or _SHA256_RE.fullmatch(
            str(record.get("verifier_report_sha256", ""))
        )
        is None
        or not bindings_valid
        or any(
            _SHA256_RE.fullmatch(str(binding.get("sha256", ""))) is None
            or not isinstance(binding.get("path"), str)
            or not binding.get("path")
            or not isinstance(binding.get("size"), int)
            or isinstance(binding.get("size"), bool)
            or int(binding.get("size", -1)) < 0
            for binding in (
                chain_manifest
                if isinstance(chain_manifest, Mapping)
                else {},
                harness_python
                if isinstance(harness_python, Mapping)
                else {},
                verifier if isinstance(verifier, Mapping) else {},
            )
        )
        or not isinstance(lineage, Mapping)
        or set(lineage)
        != {
            "release_id",
            "release_tag",
            "release_git_commit",
            "release_tag_object",
            "immutable_sha256",
            "chain_id",
        }
        or lineage.get("release_id") != control["immutable"]["release_id"]
        or lineage.get("release_tag") != PRODUCTION_OPERATIONAL_TAG
        or lineage.get("release_git_commit")
        != control["immutable"]["git_commit"]
        or lineage.get("immutable_sha256") != control["immutable_sha256"]
        or re.fullmatch(
            r"[0-9a-f]{40}", str(lineage.get("release_tag_object", ""))
        )
        is None
        or chain_manifest.get("chain_id") != record.get("chain_id")
        or chain_manifest.get("chain_id") != lineage.get("chain_id")
    ):
        raise ReadinessError(f"{gate} production authorization is invalid")
    artifacts = record.get("artifacts")
    qualification_generation = record.get("qualification_generation")
    if not isinstance(artifacts, Mapping):
        raise ReadinessError(f"{gate} authorization artifacts are invalid")
    if gate == "throughput_qualification":
        expected_artifacts = {
            "qualification_marker": {
                "path",
                "sha256",
                "size",
                "qualification_id",
            },
            "attempt_marker": {
                "path",
                "sha256",
                "size",
                "qualification_id",
            },
            "attempt_pointer": {
                "path",
                "sha256",
                "size",
                "pointer_id",
                "attempt_id",
            },
            "current_attempt": {
                "path",
                "sha256",
                "size",
                "current_id",
                "attempt_id",
                "pointer_id",
            },
        }
        if (
            set(artifacts) != set(expected_artifacts)
            or any(
                not isinstance(artifacts[name], Mapping)
                or set(artifacts[name]) != fields
                for name, fields in expected_artifacts.items()
            )
            or not isinstance(qualification_generation, Mapping)
            or set(qualification_generation)
            != {
                "rollout_generation",
                "capacity_generation",
                "catalog_id",
                "fleet_contract_sha256",
                "release_fleet_contract_sha256",
            }
        ):
            raise ReadinessError(
                "throughput-qualification authorization bindings are malformed"
            )
    else:
        expected_artifacts = {
            "watchdog_drill": {
                "path",
                "sha256",
                "size",
                "drill_id",
                "protocol",
            },
            "watchdog_ready": {
                "path",
                "sha256",
                "size",
                "marker_id",
                "protocol",
            },
        }
        if (
            set(artifacts) != set(expected_artifacts)
            or any(
                not isinstance(artifacts[name], Mapping)
                or set(artifacts[name]) != fields
                for name, fields in expected_artifacts.items()
            )
            or qualification_generation is not None
        ):
            raise ReadinessError(
                "external-watchdog authorization bindings are malformed"
            )
    matching_events = [
        row
        for row in control.get("transition_history", [])
        if row.get("event") == "production_authorization_attested"
        and row.get("details")
        == {
            "gate": gate,
            "authorization_id": authorization_id,
            "chain_id": record["chain_id"],
            "chain_manifest_sha256": chain_manifest["sha256"],
        }
    ]
    if len(matching_events) != 1:
        raise ReadinessError(
            f"{gate} production authorization is not uniquely journal-bound"
        )
    if not verify_files:
        return
    _binding_matches_file(
        record["chain_manifest"],
        description=f"{gate} chain manifest",
        identity_field="chain_id",
    )
    _binding_matches_file(
        record["harness_python"],
        description=f"{gate} pinned harness Python",
    )
    _binding_matches_file(
        record["verifier"],
        description=f"{gate} frozen verifier",
    )
    if gate == "throughput_qualification":
        qualification = _binding_matches_file(
            artifacts["qualification_marker"],
            description="authorized throughput-qualification marker",
            identity_field="qualification_id",
        )
        attempt = _binding_matches_file(
            artifacts["attempt_marker"],
            description="authorized throughput-qualification attempt marker",
            identity_field="qualification_id",
        )
        pointer_binding = dict(artifacts["attempt_pointer"])
        pointer_attempt_id = pointer_binding.pop("attempt_id", None)
        pointer = _binding_matches_file(
            pointer_binding,
            description="authorized throughput-qualification pointer",
            identity_field="pointer_id",
        )
        current_binding = dict(artifacts["current_attempt"])
        current_attempt_id = current_binding.pop("attempt_id", None)
        current_pointer_id = current_binding.pop("pointer_id", None)
        current = _binding_matches_file(
            current_binding,
            description="authorized current-attempt selector",
            identity_field="current_id",
        )
        if (
            qualification is None
            or attempt is None
            or pointer is None
            or current is None
            or artifacts["qualification_marker"]["sha256"]
            != artifacts["attempt_marker"]["sha256"]
            or qualification.get("qualification_id")
            != attempt.get("qualification_id")
            or pointer.get("attempt_id") != pointer_attempt_id
            or current.get("attempt_id") != current_attempt_id
            or current.get("pointer_id") != current_pointer_id
            or current.get("pointer") != artifacts["attempt_pointer"]["path"]
            or current.get("pointer_sha256")
            != artifacts["attempt_pointer"]["sha256"]
        ):
            raise ReadinessError(
                "throughput-qualification authorization selection drifted"
            )
        generation = record.get("qualification_generation")
        if (
            not isinstance(generation, Mapping)
            or pointer.get("readiness_generation") is None
            or any(
                pointer["readiness_generation"].get(key) != value
                for key, value in generation.items()
            )
        ):
            raise ReadinessError(
                "throughput-qualification generation binding drifted"
            )
    else:
        if set(artifacts) != {"watchdog_drill", "watchdog_ready"}:
            raise ReadinessError(
                "external-watchdog artifact bindings drifted"
            )
        for name, identity_field in (
            ("watchdog_drill", "drill_id"),
            ("watchdog_ready", "marker_id"),
        ):
            binding = dict(artifacts[name])
            binding.pop("protocol", None)
            value = _binding_matches_file(
                binding,
                description=f"authorized external-watchdog {name}",
                identity_field=identity_field,
            )
            if (
                value is None
                or value.get("control_sha256") != control["immutable_sha256"]
            ):
                raise ReadinessError(
                    f"external-watchdog {name} control binding drifted"
                )


def _validate_production_authorization_state(
    control: Mapping[str, Any],
    *,
    state_dir: Path,
    require_passed: bool,
    verify_files: bool,
) -> None:
    readiness = control.get("readiness")
    if not isinstance(readiness, Mapping):
        raise ControlError("schema-5 readiness state is missing")
    failures: list[str] = []
    for gate in PRODUCTION_AUTHORIZATION_GATES:
        record = readiness.get(gate)
        if not isinstance(record, Mapping):
            failures.append(f"{gate}: record missing")
            continue
        if record.get("passed") is not True:
            if dict(record) != {
                "passed": False,
                "evidence": None,
                "attested_at": None,
            }:
                failures.append(f"{gate}: unpassed record is malformed")
            elif require_passed:
                failures.append(f"{gate}: not passed")
            continue
        try:
            _validate_production_authorization_record(
                control,
                gate=gate,
                record=record,
                state_dir=state_dir,
                verify_files=verify_files,
            )
        except ReadinessError as exc:
            failures.append(str(exc))
    if failures:
        raise ReadinessError(
            "production authorization failed:\n- " + "\n- ".join(failures)
        )


def _production_authorization_resume_binding(
    control: Mapping[str, Any],
) -> dict[str, dict[str, str]]:
    binding: dict[str, dict[str, str]] = {}
    for gate in PRODUCTION_AUTHORIZATION_GATES:
        record = control.get("readiness", {}).get(gate)
        if not isinstance(record, Mapping) or record.get("passed") is not True:
            raise ReadinessError(
                f"production authorization {gate} is not passed"
            )
        binding[gate] = {
            "authorization_id": str(record.get("authorization_id", "")),
            "chain_id": str(record.get("chain_id", "")),
            "chain_manifest_sha256": str(
                record.get("chain_manifest", {}).get("sha256", "")
            ),
        }
        if any(
            _SHA256_RE.fullmatch(value) is None
            for value in binding[gate].values()
        ):
            raise ReadinessError(
                f"production authorization {gate} resume binding is invalid"
            )
    return binding


def _validate_resume_production_authorizations(
    control: Mapping[str, Any],
) -> None:
    intent = control.get("resume_intent")
    if not isinstance(intent, Mapping):
        raise ReadinessError(
            "resume transaction lacks production authorizations"
        )
    expected = _production_authorization_resume_binding(control)
    if intent.get("production_authorizations") != expected:
        raise ReadinessError(
            "resume transaction production authorizations drifted"
        )


def _validate_initial_qualification_generation(
    control: Mapping[str, Any],
    *,
    resume_catalog_pin: Mapping[str, Any],
    target_rollout_generation: int,
) -> None:
    """Bind the 0 -> 1 launch to the exact qualified serving generation.

    Later ordinary pause/resume cycles intentionally reuse their established
    qualification unless a capacity transition invalidates it.  The initial launch
    has no such historical generation, so accepting a qualification produced before
    a prelaunch fleet/catalog change would start an unmeasured system.
    """

    if int(target_rollout_generation) != 1:
        return
    record = control.get("readiness", {}).get("throughput_qualification")
    generation = (
        record.get("qualification_generation")
        if isinstance(record, Mapping)
        else None
    )
    fleet = effective_fleet_contract_binding(control, verify_files=True)
    expected = {
        "rollout_generation": 1,
        "capacity_generation": int(fleet["capacity_generation"]),
        "catalog_id": resume_catalog_pin.get("catalog_id"),
        "fleet_contract_sha256": str(fleet["sha256"]),
        "release_fleet_contract_sha256": str(
            control["immutable"]["fleet_contract_sha256"]
        ),
    }
    if (
        not isinstance(generation, Mapping)
        or dict(generation) != expected
        or resume_catalog_pin.get("rollout_generation") != 1
        or resume_catalog_pin.get("capacity_generation")
        != expected["capacity_generation"]
        or resume_catalog_pin.get("fleet_contract_sha256")
        != expected["fleet_contract_sha256"]
        or resume_catalog_pin.get("release_fleet_contract_sha256")
        != expected["release_fleet_contract_sha256"]
    ):
        raise ReadinessError(
            "initial production launch throughput qualification does not bind "
            "the exact rollout/capacity/fleet/catalog generation"
        )


def _prepare_production_authorization_record(
    control: Mapping[str, Any],
    *,
    gate: str,
    chain_manifest: Path,
    evidence_path: Path | None,
    expected_sha256: str | None,
    timestamp: float,
    verifier_runner: (
        Callable[
            [Sequence[str], Mapping[str, str], float],
            subprocess.CompletedProcess[str],
        ]
        | None
    ) = None,
) -> dict[str, Any]:
    report, manifest_binding, manifest, executable_bindings = (
        _invoke_production_authorization_verifier(
            control,
            gate=gate,
            chain_manifest=chain_manifest,
            verifier_runner=verifier_runner,
        )
    )
    chain_id = str(report["chain_id"])
    lineage = _authorization_lineage(control, manifest, chain_id=chain_id)
    if gate == "throughput_qualification":
        artifacts, qualification_generation = (
            _build_throughput_authorization_artifacts(
                report,
                evidence_path=evidence_path,
                expected_sha256=expected_sha256,
                manifest_binding=manifest_binding,
                lineage=lineage,
            )
        )
    else:
        artifacts = _build_watchdog_authorization_artifacts(
            report,
            control=control,
            evidence_path=evidence_path,
            expected_sha256=expected_sha256,
        )
        qualification_generation = None
    record: dict[str, Any] = {
        "schema_version": PRODUCTION_AUTHORIZATION_SCHEMA_VERSION,
        "protocol": PRODUCTION_AUTHORIZATION_PROTOCOL,
        "gate": gate,
        "passed": True,
        "chain_id": chain_id,
        "chain_manifest": manifest_binding,
        "harness_python": executable_bindings["harness_python"],
        "verifier": executable_bindings["verifier"],
        "verifier_report_sha256": sha256_value(report),
        "release_lineage": lineage,
        "artifacts": artifacts,
        "qualification_generation": qualification_generation,
        "attested_at": utc_timestamp(timestamp),
        "attested_timestamp": timestamp,
    }
    record["authorization_id"] = _authorization_record_identity(record)
    return record


def _require_pristine_authorization_control(
    control: Mapping[str, Any],
) -> None:
    if (
        control["desired_state"] != "paused"
        or control.get("drain_requested")
        or control["finalization"]["state"] != "idle"
        or control.get("resume_intent") is not None
    ):
        raise ReadinessError(
            "production authorization requires pristine paused control"
        )


def attest_production_authorization(
    state_dir: Path,
    *,
    gate: str,
    chain_manifest: Path,
    evidence_path: Path | None = None,
    expected_sha256: str | None = None,
    now: float | None = None,
    verifier_runner: (
        Callable[
            [Sequence[str], Mapping[str, str], float],
            subprocess.CompletedProcess[str],
        ]
        | None
    ) = None,
) -> dict[str, Any]:
    if gate not in PRODUCTION_AUTHORIZATION_GATES:
        raise ReadinessError("unknown production-authorization gate")
    timestamp = time.time() if now is None else float(now)
    chain_manifest = chain_manifest.expanduser()

    # The verifier can legitimately take hours.  Snapshot the complete paused control
    # under lock, release it while the bounded subprocess runs, and accept the result
    # only if the exact control bytes are still current.  This keeps status and repair
    # inspection responsive without creating a time-of-check/time-of-use launch gap.
    with control_lock(state_dir):
        snapshot = load_control(state_dir, verify_files=True)
        _require_pristine_authorization_control(snapshot)
        snapshot_sha256 = sha256_value(snapshot)
    record = _prepare_production_authorization_record(
        snapshot,
        gate=gate,
        chain_manifest=chain_manifest,
        evidence_path=evidence_path,
        expected_sha256=expected_sha256,
        timestamp=timestamp,
        verifier_runner=verifier_runner,
    )
    manifest_binding = record["chain_manifest"]
    chain_id = record["chain_id"]

    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        _require_pristine_authorization_control(control)
        if sha256_value(control) != snapshot_sha256:
            raise ReadinessError(
                "control changed while the production-authorization verifier ran; "
                "discarding the stale result"
            )
        current = control["readiness"][gate]
        if current.get("passed") is True:
            if _production_authorization_core(current) == (
                _production_authorization_core(record)
            ):
                return control
            if gate != "throughput_qualification":
                raise ReadinessError(
                    "external-watchdog authorization is immutable once published"
                )
            old_generation = current.get("qualification_generation")
            new_generation = record.get("qualification_generation")
            if (
                not isinstance(old_generation, Mapping)
                or not isinstance(new_generation, Mapping)
                or (
                    int(new_generation["rollout_generation"]),
                    int(new_generation["capacity_generation"]),
                )
                <= (
                    int(old_generation["rollout_generation"]),
                    int(old_generation["capacity_generation"]),
                )
                or current.get("chain_id") != record.get("chain_id")
                or current.get("release_lineage")
                != record.get("release_lineage")
            ):
                raise ReadinessError(
                    "throughput-qualification replacement is not a newer "
                    "same-chain additive attempt"
                )
        control["readiness"][gate] = record
        append_transition(
            state_dir,
            control,
            event="production_authorization_attested",
            details={
                "gate": gate,
                "authorization_id": record["authorization_id"],
                "chain_id": chain_id,
                "chain_manifest_sha256": manifest_binding["sha256"],
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        return control


def attest_gate(
    state_dir: Path,
    *,
    gate: str,
    evidence_path: Path | None = None,
    expected_sha256: str | None = None,
    chain_manifest: Path | None = None,
    now: float | None = None,
    verifier_runner: (
        Callable[
            [Sequence[str], Mapping[str, str], float],
            subprocess.CompletedProcess[str],
        ]
        | None
    ) = None,
) -> dict[str, Any]:
    if gate in PRODUCTION_AUTHORIZATION_GATES:
        if chain_manifest is None:
            raise ReadinessError(
                f"{gate} attestation requires --chain-manifest"
            )
        return attest_production_authorization(
            state_dir,
            gate=gate,
            chain_manifest=chain_manifest,
            evidence_path=evidence_path,
            expected_sha256=expected_sha256,
            now=now,
            verifier_runner=verifier_runner,
        )
    if gate not in REQUIRED_GATES or gate == "scheduler_reconciliation":
        raise ReadinessError(
            "gate must be a non-scheduler required gate; reconciliation owns its gate"
        )
    if evidence_path is None:
        raise ReadinessError(f"{gate} attestation requires --evidence")
    timestamp = time.time() if now is None else float(now)
    evidence_path = evidence_path.expanduser().resolve()
    evidence_hash = expected_sha256 or sha256_file(evidence_path)
    with control_lock(state_dir):
        control = load_control(state_dir)
        snapshot_record = control.get(SNAPSHOT_ATTESTATION_STATE_KEY)
        if isinstance(snapshot_record, dict):
            # Readiness publication is a trusted slow path: renew the metadata lease
            # when due, then use the preseal. New selected-member claims may consult
            # the already-sealed inventory once and are persisted below.
            refresh_snapshot_integrity_lease(state_dir, control)
            seal = validate_snapshot_integrity_attestation(
                control, state_dir=state_dir, verify_lease=True
            )
            allowed_members = [
                member
                for binding in snapshot_record.get("member_bindings", {}).values()
                if isinstance(binding, dict)
                for member in binding.get("members", [])
                if isinstance(member, dict)
            ]
            snapshot_context = _SnapshotValidationContext(
                full=False,
                seal=seal,
                allow_inventory_lookup=True,
                allowed_members=allowed_members,
            )
        else:
            snapshot_context = _SnapshotValidationContext(full=True)
        _validate_attestation(
            control,
            gate,
            evidence_path,
            evidence_hash,
            now=timestamp,
            snapshot_context=snapshot_context,
        )
        current = control["readiness"][gate]
        replacement = {
            "passed": True,
            "evidence": str(evidence_path),
            "sha256": evidence_hash,
            "attested_at": utc_timestamp(timestamp),
            "attested_timestamp": timestamp,
        }
        if gate == "fleet":
            payload = _load_json_object(
                evidence_path, description="fleet readiness evidence"
            )
            metrics = payload.get("metrics")
            if not isinstance(metrics, Mapping):
                raise ReadinessError(
                    "fleet readiness evidence lacks scheduler metrics"
                )
            replacement.update(
                {
                    "scheduler_safety_evidence_id": metrics[
                        "scheduler_safety_evidence_id"
                    ],
                    "scheduler_safety_policy_id": metrics[
                        "scheduler_safety_policy_id"
                    ],
                    "scheduler_safety_policy_contract_id": metrics[
                        "scheduler_safety_policy_contract_id"
                    ],
                    "transport_uncertainty_binding_sha256": metrics[
                        "transport_uncertainty_binding_sha256"
                    ],
                    "transport_censor_protocol_version": metrics[
                        "transport_censor_protocol_version"
                    ],
                    "transport_censor_protocol_hash": metrics[
                        "transport_censor_protocol_hash"
                    ],
                }
            )
        active_capacity = control["capacity"].get("active_transition")
        if (
            isinstance(active_capacity, dict)
            and active_capacity.get("phase") == "readiness_pending"
            and gate in active_capacity.get("invalidated_readiness", [])
        ):
            replacement["capacity_generation"] = int(
                active_capacity["to_generation"]
            )
        control["readiness"][gate] = replacement
        if gate == "snapshot" and not isinstance(snapshot_record, dict):
            target_generation = int(control["rollout_generation"]) + 1
            control[SNAPSHOT_ATTESTATION_STATE_KEY] = (
                ensure_snapshot_integrity_attestation(
                    state_dir,
                    control,
                    generation=target_generation,
                    validation_context=snapshot_context,
                )
            )
            snapshot_record = control[SNAPSHOT_ATTESTATION_STATE_KEY]
        binding_changed = False
        if snapshot_context.members:
            if not isinstance(snapshot_record, dict):
                raise ReadinessError(
                    "sealed snapshot members cannot be bound without a generation seal"
                )
            members = sorted(
                snapshot_context.members.values(),
                key=lambda row: (row["snapshot_root"], row["logical_path"]),
            )
            binding = {
                "evidence_sha256": evidence_hash,
                "members": members,
            }
            bindings = snapshot_record.setdefault("member_bindings", {})
            binding_changed = bindings.get(gate) != binding
            bindings[gate] = binding
        elif isinstance(snapshot_record, dict):
            bindings = snapshot_record.setdefault("member_bindings", {})
            if gate in bindings:
                bindings.pop(gate)
                binding_changed = True
        if current == replacement and not binding_changed:
            return control
        append_transition(
            state_dir,
            control,
            event="readiness_attested",
            details={
                "gate": gate,
                "evidence": str(evidence_path),
                "sha256": evidence_hash,
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        return control


def validate_readiness(
    control: Mapping[str, Any],
    *,
    state_dir: Path | None = None,
    verify_files: bool = True,
    now: float | None = None,
    snapshot_full: bool = False,
) -> _SnapshotValidationContext:
    validate_immutable_pins(control["immutable"], verify_files=verify_files)
    _validate_admission(control["admission"])
    if verify_files and not snapshot_full and isinstance(
        control.get(SNAPSHOT_ATTESTATION_STATE_KEY), dict
    ):
        if state_dir is None:
            raise ReadinessError(
                "compact readiness validation requires the exact control state directory"
            )
        seal = validate_snapshot_integrity_attestation(
            control, state_dir=state_dir, verify_lease=True
        )
        bindings = control[SNAPSHOT_ATTESTATION_STATE_KEY].get(
            "member_bindings", {}
        )
        allowed_members = [
            member
            for binding in bindings.values()
            if isinstance(binding, dict)
            for member in binding.get("members", [])
            if isinstance(member, dict)
        ]
        snapshot_context = _SnapshotValidationContext(
            full=False,
            seal=seal,
            allowed_members=allowed_members,
        )
    else:
        snapshot_context = _SnapshotValidationContext(full=True)
    failures: list[str] = []
    for gate in REQUIRED_GATES:
        record = control["readiness"].get(gate, {})
        if record.get("passed") is not True:
            failures.append(f"{gate}: not passed")
            continue
        if not verify_files:
            continue
        evidence = record.get("evidence")
        evidence_hash = record.get("sha256")
        if not evidence or not evidence_hash:
            failures.append(f"{gate}: missing checksummed evidence")
            continue
        try:
            _validate_attestation(
                control,
                gate,
                Path(evidence),
                str(evidence_hash),
                now=now,
                snapshot_context=snapshot_context,
            )
        except ReadinessError as exc:
            failures.append(str(exc))
    if failures:
        raise ReadinessError("resume gates failed:\n- " + "\n- ".join(failures))
    if state_dir is None:
        if control.get("desired_state") in {"resuming", "running"}:
            raise ReadinessError(
                "production authorization validation requires the control state directory"
            )
    else:
        _validate_production_authorization_state(
            control,
            state_dir=state_dir,
            require_passed=control.get("desired_state")
            in {"resuming", "running"},
            verify_files=verify_files,
        )
    return snapshot_context


def _close_open_epoch(
    control: MutableMapping[str, Any], *, reason: str, now: float
) -> bool:
    epochs = control.setdefault("throughput_epochs", [])
    if not epochs or epochs[-1].get("closed_at") is not None:
        return False
    epochs[-1]["closed_at"] = utc_timestamp(now)
    epochs[-1]["closed_timestamp"] = now
    epochs[-1]["close_reason"] = reason
    return True


def _reset_admission_ramp(
    state_dir: Path,
    control: MutableMapping[str, Any],
    *,
    reason: str,
    now: float,
    ceiling: int | None = None,
    rollout_generation: int | None = None,
    clear_last_observation: bool = False,
) -> bool:
    """Close any clean ramp window and rebind it to safe current control identity."""

    ramp = control["admission_ramp"]
    previous_ceiling = int(control["admission"]["current_ceiling"])
    target_ceiling = previous_ceiling if ceiling is None else int(ceiling)
    target_generation = (
        int(control["rollout_generation"])
        if rollout_generation is None
        else int(rollout_generation)
    )
    generation_changed = ramp.get("rollout_generation") != target_generation
    if target_ceiling not in ADMISSION_RAMP_STAGES:
        raise ControlError("cannot reset admission ramp to an unknown stage")
    window = ramp.get("window")
    identity_changed = bool(
        generation_changed
        or ramp.get("current_ceiling") != target_ceiling
        or previous_ceiling != target_ceiling
    )
    changed = window is not None or identity_changed
    if isinstance(window, dict):
        reset = {
            "reason": reason,
            "at": utc_timestamp(now),
            "timestamp": now,
            "rollout_generation": window["rollout_generation"],
            "fleet_generation": window["fleet_generation"],
            "throughput_epoch": window["throughput_epoch"],
            "ceiling": window["ceiling"],
            "started_at": window["started_at"],
            "started_timestamp": window["started_timestamp"],
            "clean_seconds": max(0.0, now - float(window["started_timestamp"])),
            "observation_count": len(window["observations"]),
            "evidence_sha256": sha256_value(window["observations"]),
        }
        ramp["resets"].append(reset)
    control["admission"]["current_ceiling"] = target_ceiling
    control["admission_safety_hold"]["configured_ceiling"] = target_ceiling
    ramp["rollout_generation"] = target_generation
    ramp["current_ceiling"] = target_ceiling
    ramp["window"] = None
    if clear_last_observation or generation_changed:
        ramp["last_observation"] = None
    ramp["last_action"] = {
        "action": "reset",
        "reason": reason,
        "at": utc_timestamp(now),
        "timestamp": now,
        "previous_ceiling": previous_ceiling,
        "current_ceiling": target_ceiling,
        "rollout_generation": target_generation,
    }
    if changed:
        append_transition(
            state_dir,
            control,
            event="admission_ramp_reset",
            details={
                "reason": reason,
                "previous_ceiling": previous_ceiling,
                "current_ceiling": target_ceiling,
                "rollout_generation": target_generation,
                "window_was_active": isinstance(window, dict),
            },
            now=now,
        )
    return changed


def _verify_resume_controller_visibility(
    control: Mapping[str, Any], snapshot: SchedulerSnapshot, *, now: float
) -> dict[str, SchedulerJob]:
    if not snapshot.squeue_ok or not snapshot.sacct_ok:
        raise SchedulerAmbiguity(
            "transactional resume requires complete squeue+sacct truth"
        )
    visible: dict[str, SchedulerJob] = {}
    for role in ROLE_NAMES:
        record = control["controllers"][role].get("active")
        if not isinstance(record, dict) or not record.get("job_id"):
            raise SchedulerVisibilityPending(
                f"resume has not committed the {role} job ID"
            )
        matches = [
            job
            for job in snapshot.jobs
            if job.active
            and job.job_id == str(record["job_id"])
            and job.token == record.get("job_token")
        ]
        if len(matches) > 1:
            raise SchedulerAmbiguity(
                f"resume controller {role} has duplicate exact jobs"
            )
        if not matches:
            submitted = float(
                record.get("submitted_timestamp", record.get("created_timestamp", now))
            )
            if now - submitted < SUBMISSION_VISIBILITY_GRACE_SECONDS:
                raise SchedulerVisibilityPending(
                    f"resume controller {role} is not yet scheduler-visible"
                )
            raise SchedulerAmbiguity(
                f"resume controller {role} job {record['job_id']} remained invisible beyond grace"
            )
        if _exact_live_controller_job(snapshot, record) is None:
            raise SchedulerAmbiguity(
                f"resume controller {role} lacks exact spool/transport proof"
            )
        visible[role] = matches[0]
    return visible


def _validate_resume_scheduler_namespace(
    control: Mapping[str, Any],
    snapshot: SchedulerSnapshot,
    *,
    allow_active_controllers: bool,
    allow_crash_window_intents: bool,
) -> None:
    """Fail closed on every live job that can affect a resume transaction.

    During a crash retry, an accepted active-controller intent may be visible before
    its scheduler ID was committed.  That one exact durable token is admissible.  At
    the final commit boundary, however, only the two exact ``active`` records are
    allowed; cell jobs, drill jobs, successors, malformed tokens, and all other
    production-controller rows must be absent.
    """

    if not snapshot.squeue_ok or not snapshot.sacct_ok:
        raise SchedulerAmbiguity(
            "transactional resume requires complete squeue+sacct truth"
        )
    report = build_reconciliation_report(
        control, snapshot, all_jobs=True, no_admit=True
    )
    errors = list(report["errors"])

    exact_active: set[tuple[str, str]] = set()
    crash_tokens: set[str] = set()
    for role in ROLE_NAMES:
        role_state = control["controllers"][role]
        active = role_state.get("active")
        if isinstance(active, dict) and active.get("job_id") and active.get(
            "job_token"
        ):
            exact_active.add((str(active["job_id"]), str(active["job_token"])))
        intent = role_state.get("submission_intent")
        if (
            allow_crash_window_intents
            and isinstance(intent, dict)
            and intent.get("target") == "active"
            and intent.get("job_token")
        ):
            crash_tokens.add(str(intent["job_token"]))

    unexpected_controllers: list[str] = []
    for job in snapshot.jobs:
        if not job.active or not job.comment.startswith(TOKEN_PREFIX):
            continue
        parsed = parse_job_token(job.comment)
        exact = allow_active_controllers and (job.job_id, job.comment) in exact_active
        crash_window = parsed is not None and job.comment in crash_tokens
        if parsed is None or not (exact or crash_window):
            unexpected_controllers.append(job.job_id)
    if unexpected_controllers:
        errors.append(
            "unexpected live production controller namespace jobs: "
            + ", ".join(sorted(unexpected_controllers))
        )

    live_drills = _all_live_drill_jobs(snapshot)
    if live_drills:
        errors.append(
            "live controller-drill jobs: "
            + ", ".join(sorted(job.job_id for job in live_drills))
        )
    live_cells = sorted(
        job.job_id
        for job in snapshot.jobs
        if job.active
        and (
            job.comment.startswith(CELL_INTENT_PREFIX)
            or _cell_job(job.job_name)
        )
    )
    if live_cells:
        errors.append(
            "live schema-5 cell jobs have not drained: " + ", ".join(live_cells)
        )
    if errors:
        raise SchedulerAmbiguity(
            "transactional resume found an unclean live production join: "
            + "; ".join(dict.fromkeys(errors))
        )


def _validate_resume_drill_proof(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    expected_marker_sha256: str,
) -> None:
    """Revalidate the complete static drill proof and its marker byte identity."""

    if _SHA256_RE.fullmatch(expected_marker_sha256) is None:
        raise ReadinessError("resume transaction lacks a controller kill drill proof")
    before = _controller_drill_marker_sha256(state_dir)
    if before != expected_marker_sha256:
        raise ReadinessError("controller kill drill marker drifted during resume")
    validate_controller_drill_marker(
        state_dir,
        control,
        require_current_baseline=False,
        allow_resuming=True,
    )
    after = _controller_drill_marker_sha256(state_dir)
    if after != expected_marker_sha256 or after != before:
        raise ReadinessError("controller kill drill marker changed during validation")


def _release_resume_role(
    state_dir: Path,
    *,
    role: str,
    scheduler_reader: Callable[[], SchedulerSnapshot],
    release_runner: Callable[[Sequence[str]], subprocess.CompletedProcess[str]],
    now: float,
) -> None:
    control = load_control(state_dir)
    record = control["controllers"][role].get("active")
    if not isinstance(record, dict) or not str(record.get("job_id", "")).isdigit():
        raise SchedulerAmbiguity(f"cannot release uncommitted resume controller {role}")
    snapshot = scheduler_reader()
    matches = [
        job
        for job in snapshot.jobs
        if job.active
        and job.job_id == str(record["job_id"])
        and job.token == record.get("job_token")
    ]
    if len(matches) > 1:
        raise SchedulerAmbiguity(
            f"refusing to release duplicate {role} controller jobs"
        )
    scheduler_job: SchedulerJob
    if not matches:
        # Once an exact held allocation is released it may start and finish before a
        # crash-retry observes it.  Complete accounting truth plus a unique terminal
        # token is sufficient to adopt that release; absence of all token history is not.
        token_matches = _find_intent_jobs(snapshot, str(record.get("job_token", "")))
        if len(token_matches) != 1 or token_matches[0].job_id != str(record["job_id"]):
            raise SchedulerVisibilityPending(
                f"exact resume controller {role} is not visible for release"
            )
        scheduler_job = token_matches[0]
    else:
        scheduler_job = matches[0]
    receipt_path = Path(str(record.get("spooled_receipt_path", ""))).resolve()
    receipt_sha256 = str(record.get("spooled_receipt_sha256", ""))
    if (
        not receipt_path.is_absolute()
        or _SHA256_RE.fullmatch(receipt_sha256) is None
    ):
        raise SchedulerAmbiguity(
            f"cannot release {role} controller without exact spool proof"
        )
    observation_runner = (
        _run_subprocess
        if release_runner is _run_subprocess
        else getattr(release_runner, "release_observation_runner", None)
    )
    proof = _ensure_exact_sbatch_released(
        state_dir,
        record=record,
        job_id=str(record["job_id"]),
        receipt_path=receipt_path,
        receipt_sha256=receipt_sha256,
        now=now,
        release_runner=release_runner,
        scheduler_job=scheduler_job,
        observation_runner=(
            observation_runner if callable(observation_runner) else None
        ),
    )
    result = {
        "job_id": str(record["job_id"]),
        "status": (
            "adopted_terminal_after_release"
            if not scheduler_job.active
            else "released"
        ),
        "returncode": 0,
        "stderr": "",
        "at": utc_timestamp(now),
    }
    with control_lock(state_dir):
        updated = load_control(state_dir)
        intent = updated.get("resume_intent")
        if not isinstance(intent, dict):
            raise SchedulerAmbiguity(
                "resume intent disappeared during controller release"
            )
        intent.setdefault("release_results", {})[role] = result
        controller_record = updated["controllers"][role].get("active")
        if isinstance(controller_record, dict):
            controller_record.update(proof)
            submission_intent = updated["controllers"][role].get(
                "submission_intent"
            )
            if (
                isinstance(submission_intent, dict)
                and submission_intent.get("intent_token")
                == controller_record.get("intent_token")
            ):
                submission_intent.update(proof)
        append_transition(
            state_dir,
            updated,
            event="resume_controller_release_result",
            details={"role": role, **result},
            now=now,
        )
        _save_control(state_dir, updated, now=now)


def resume_control(
    state_dir: Path,
    *,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    release_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Transactionally create both controller chains before enabling admission.

    Every scheduler boundary is restartable from ``resume_intent``.  Controllers are
    submitted normally (not held) so a starting supervisor can claim its exact intent
    and wait in ``resuming`` without introducing a second release side effect.  The
    durable desired state remains ``resuming`` until both exact job IDs are visible in
    complete squeue+sacct truth; only the final atomic control write publishes
    ``running``.  Thus neither a crash nor scheduler visibility lag can expose a
    one-controller production state to the dispatcher.
    """
    timestamp = time.time() if now is None else float(now)
    read_scheduler = scheduler_reader or (lambda: query_scheduler(now=time.time()))
    submit = submit_runner or _run_subprocess
    # Kept in the public signature for callers written against the initial held-job
    # prototype.  Release is intentionally no longer an external transaction boundary.
    del release_runner
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        if control["finalization"]["state"] != "idle":
            raise ReadinessError(
                "production resume requires finalization state exactly idle"
            )
        if control["capacity"]["active_transition"] is not None:
            raise ReadinessError(
                "capacity transition is incomplete; finish it before resume"
            )
        if control["admission_safety_hold"]["active"]:
            raise ReadinessError(
                "admission safety hold is active; clear it before resume"
            )
        if control["desired_state"] == "resuming":
            # A visibility retry may occur long after the controller jobs were accepted.
            # Expiry is not evidence of drift: first bind the immutable generation
            # records through load_control, then renew both metadata proofs and verify
            # the exact refreshed leases before trusting compact readiness.
            refresh_runtime_integrity_lease(state_dir, control, now=None)
            validate_runtime_integrity_attestation(control, verify_metadata=True)
            refresh_snapshot_integrity_lease(state_dir, control, now=None)
            validate_snapshot_integrity_attestation(
                control, state_dir=state_dir, verify_lease=True
            )
        # Fleet freshness authorizes the atomic paused -> resuming transition. Once
        # that transition is durably recorded, scheduler visibility retries must not
        # expire the already-proven launch gate; all artifact bytes and typed facts
        # are still revalidated. Running is likewise idempotent after the launch
        # evidence becomes historical.
        readiness_now = timestamp if control["desired_state"] == "paused" else None
        snapshot_validation = validate_readiness(
            control,
            state_dir=state_dir,
            verify_files=True,
            now=readiness_now,
            # Each paused -> new rollout transition gets a fresh full-byte proof.
            # Normally the marker-last snapshot gate already prepared the exact next
            # generation preseal. A manual legacy control without one falls back to a
            # full scan here; retries and running paths always use the compact seal.
            snapshot_full=(
                control["desired_state"] == "paused"
                and (
                    not isinstance(
                        control.get(SNAPSHOT_ATTESTATION_STATE_KEY), dict
                    )
                    or control[SNAPSHOT_ATTESTATION_STATE_KEY].get("generation")
                    != int(control["rollout_generation"]) + 1
                )
            ),
        )
        drill_marker_sha256: str | None = None
        if (
            control["desired_state"] == "paused"
            and int(control["rollout_generation"]) == 0
        ):
            before_marker_sha256 = _controller_drill_marker_sha256(state_dir)
            validate_controller_drill_marker(state_dir, control)
            drill_marker_sha256 = _controller_drill_marker_sha256(state_dir)
            if drill_marker_sha256 != before_marker_sha256:
                raise ReadinessError(
                    "controller kill drill marker changed during validation"
                )
        elif control["desired_state"] == "paused":
            prior_resume = control.get("resume_intent")
            prior_marker_sha256 = (
                prior_resume.get("controller_drill_marker_sha256")
                if isinstance(prior_resume, dict)
                and prior_resume.get("state") == "complete"
                else None
            )
            if (
                not isinstance(prior_marker_sha256, str)
                or _SHA256_RE.fullmatch(prior_marker_sha256) is None
            ):
                raise ReadinessError(
                    "paused production control lacks its completed controller-drill proof"
                )
            current_marker_sha256 = _controller_drill_marker_sha256(state_dir)
            if current_marker_sha256 != prior_marker_sha256:
                raise ReadinessError(
                    "historical controller kill drill marker is missing or drifted"
                )
            # The first drill baseline intentionally predates all production writes, but
            # its marker, state, journal, recovery events, and sealed reconciliation stay
            # immutable and auditable across every later pause/resume cycle.
            validate_controller_drill_marker(
                state_dir,
                control,
                require_current_baseline=False,
                allow_completed_drain=True,
            )
            drill_marker_sha256 = current_marker_sha256
        _validate_production_authorization_state(
            control,
            state_dir=state_dir,
            require_passed=True,
            verify_files=True,
        )
        production_authorizations = (
            _production_authorization_resume_binding(control)
        )
        if control["desired_state"] in {"resuming", "running"}:
            _validate_resume_production_authorizations(control)
        if control["desired_state"] == "paused":
            pre_resume_snapshot = read_scheduler()
            # The persisted readiness gate is not live scheduler truth.  Join the
            # current queue/accounting window before changing desired state, and require
            # the controller, drill, and cell namespaces to be completely drained.
            _validate_resume_scheduler_namespace(
                control,
                pre_resume_snapshot,
                allow_active_controllers=False,
                allow_crash_window_intents=False,
            )
        elif control["desired_state"] == "resuming":
            resume_intent = control.get("resume_intent")
            expected_marker = (
                resume_intent.get("controller_drill_marker_sha256")
                if isinstance(resume_intent, dict)
                else None
            )
            if not isinstance(expected_marker, str):
                raise ReadinessError(
                    "resume transaction lacks a controller kill drill proof"
                )
            _validate_resume_drill_proof(
                state_dir,
                control,
                expected_marker_sha256=expected_marker,
            )
            _validate_resume_scheduler_namespace(
                control,
                read_scheduler(),
                allow_active_controllers=True,
                allow_crash_window_intents=True,
            )
        require_fresh_external_watchdog_mirror(
            state_dir, control=control, now=timestamp
        )
        if control["desired_state"] == "running":
            intent = control.get("resume_intent")
            if not isinstance(intent, dict) or intent.get("state") != "complete":
                raise SchedulerAmbiguity(
                    "running control lacks a complete resume transaction"
                )
            if not control.get("drain_requested"):
                return control
        elif control["desired_state"] == "paused":
            generation = int(control["rollout_generation"]) + 1
            trusted_generation_catalog_pin = _load_resume_catalog_pin(
                state_dir,
                control,
                target_rollout_generation=generation,
            )
            _validate_initial_qualification_generation(
                control,
                resume_catalog_pin=trusted_generation_catalog_pin,
                target_rollout_generation=generation,
            )
            # Establish the expensive byte-level environment proof before publishing
            # or submitting anything for the new rollout generation.  The immutable
            # generation file is then metadata-validated by every process at startup.
            runtime_attestation = ensure_runtime_integrity_attestation(
                state_dir,
                control,
                generation=generation,
                force_full=True,
                now=timestamp,
            )
            existing_snapshot_attestation = control.get(
                SNAPSHOT_ATTESTATION_STATE_KEY
            )
            if (
                isinstance(existing_snapshot_attestation, dict)
                and existing_snapshot_attestation.get("generation") == generation
            ):
                refresh_snapshot_integrity_lease(state_dir, control)
                validate_snapshot_integrity_attestation(
                    control, state_dir=state_dir, verify_lease=True
                )
                snapshot_attestation = copy.deepcopy(
                    existing_snapshot_attestation
                )
            else:
                snapshot_attestation = ensure_snapshot_integrity_attestation(
                    state_dir,
                    control,
                    generation=generation,
                    validation_context=snapshot_validation,
                )
            control["desired_state"] = "resuming"
            control["drain_requested"] = False
            control["drain_intent"] = None
            control["rollout_generation"] = generation
            _reset_admission_ramp(
                state_dir,
                control,
                reason="rollout_generation_started",
                now=timestamp,
                ceiling=24,
                rollout_generation=generation,
                clear_last_observation=True,
            )
            control[RUNTIME_ATTESTATION_STATE_KEY] = runtime_attestation
            control[SNAPSHOT_ATTESTATION_STATE_KEY] = snapshot_attestation
            control["resume_intent"] = {
                "resume_id": uuid.uuid4().hex,
                "state": "submitting_controllers",
                "rollout_generation": generation,
                "created_at": utc_timestamp(timestamp),
                "created_timestamp": timestamp,
                "controller_job_ids": {},
                "controller_drill_marker_sha256": drill_marker_sha256,
                "production_authorizations": production_authorizations,
                "trusted_generation_catalog": (
                    trusted_generation_catalog_pin
                ),
            }
            append_transition(
                state_dir,
                control,
                event="resume_intent_created",
                details={
                    "resume_id": control["resume_intent"]["resume_id"],
                    "rollout_generation": generation,
                    "admission_ceiling": control["admission"]["current_ceiling"],
                },
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)

    control = load_control(state_dir)
    if not isinstance(control.get("resume_intent"), dict):
        raise SchedulerAmbiguity("resume transaction has no durable intent")

    if control["desired_state"] == "resuming":
        _validate_production_authorization_state(
            control,
            state_dir=state_dir,
            require_passed=True,
            verify_files=True,
        )
        _validate_resume_production_authorizations(control)
        _validate_pinned_resume_catalog(state_dir, control)
        expected_drill_marker = control["resume_intent"].get(
            "controller_drill_marker_sha256"
        )
        if not isinstance(expected_drill_marker, str):
            raise ReadinessError(
                "resume transaction lacks a controller kill drill proof"
            )
        _validate_resume_drill_proof(
            state_dir,
            control,
            expected_marker_sha256=expected_drill_marker,
        )
        for role in ROLE_NAMES:
            current = load_control(state_dir)["controllers"][role].get("active")
            snapshot = read_scheduler()
            if not snapshot.squeue_ok or not snapshot.sacct_ok:
                raise SchedulerAmbiguity(
                    "transactional resume requires complete squeue+sacct truth"
                )
            exact_live = bool(
                isinstance(current, dict)
                and any(
                    job.active
                    and job.job_id == str(current.get("job_id"))
                    and job.token == current.get("job_token")
                    for job in snapshot.jobs
                )
            )
            current_inside_visibility_grace = bool(
                isinstance(current, dict)
                and current.get("job_id")
                and not any(
                    job.job_id == str(current.get("job_id"))
                    and job.token == current.get("job_token")
                    for job in snapshot.jobs
                )
                and timestamp
                - float(
                    current.get(
                        "submitted_timestamp",
                        current.get("created_timestamp", timestamp),
                    )
                )
                < SUBMISSION_VISIBILITY_GRACE_SECONDS
            )
            if exact_live or current_inside_visibility_grace:
                record = current
            else:
                record = submit_controller_intent(
                    state_dir,
                    role=role,
                    target="active",
                    dependency_job_id=None,
                    scheduler=snapshot,
                    submit_runner=submit,
                    allow_resuming=True,
                    hold=False,
                    now=timestamp,
                )
            assert isinstance(record, dict)
            with control_lock(state_dir):
                updated = load_control(state_dir)
                resume_intent = updated.get("resume_intent")
                if not isinstance(resume_intent, dict):
                    raise SchedulerAmbiguity(
                        "resume intent disappeared during submission"
                    )
                resume_intent.setdefault("controller_job_ids", {})[role] = str(
                    record["job_id"]
                )
                _save_control(state_dir, updated, now=timestamp)
        with control_lock(state_dir):
            control = load_control(state_dir)
            # This scheduler read deliberately occurs while the final control lock is
            # held.  No concurrent controller-state mutation or proof replacement can
            # be interleaved between this join and the atomic running-state commit.
            snapshot = read_scheduler()
            _validate_resume_scheduler_namespace(
                control,
                snapshot,
                allow_active_controllers=True,
                allow_crash_window_intents=False,
            )
            visible = _verify_resume_controller_visibility(
                control, snapshot, now=timestamp
            )
            resume_intent = control["resume_intent"]
            expected_marker = resume_intent.get("controller_drill_marker_sha256")
            if not isinstance(expected_marker, str):
                raise ReadinessError(
                    "resume transaction lacks a controller kill drill proof"
                )
            _validate_resume_drill_proof(
                state_dir,
                control,
                expected_marker_sha256=expected_marker,
            )
            _validate_production_authorization_state(
                control,
                state_dir=state_dir,
                require_passed=True,
                verify_files=True,
            )
            _validate_resume_production_authorizations(control)
            _validate_pinned_resume_catalog(state_dir, control)
            expected_ids = {role: visible[role].job_id for role in ROLE_NAMES}
            if resume_intent.get("controller_job_ids") != expected_ids:
                raise SchedulerAmbiguity(
                    "resume intent job IDs changed before the running-state commit"
                )
            if _controller_drill_marker_sha256(state_dir) != expected_marker:
                raise ReadinessError(
                    "controller kill drill marker drifted at the running-state commit"
                )
            resume_intent["state"] = "complete"
            resume_intent["scheduler_visible_job_ids"] = {
                role: visible[role].job_id for role in ROLE_NAMES
            }
            resume_intent["completed_at"] = utc_timestamp(timestamp)
            resume_intent["completed_timestamp"] = timestamp
            control["desired_state"] = "running"
            append_transition(
                state_dir,
                control,
                event="resumed",
                details={
                    "resume_id": resume_intent["resume_id"],
                    "controller_job_ids": resume_intent["scheduler_visible_job_ids"],
                    "rollout_generation": control["rollout_generation"],
                },
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
    return load_control(state_dir)


def _cell_array_base_job_id(job_id: str) -> str | None:
    if _EXACT_CELL_TASK_ID.fullmatch(job_id) is None:
        return None
    return job_id.split("_", 1)[0]


def _assert_cell_submission_cut_visible(
    state_dir: Path,
    snapshot: SchedulerSnapshot,
    *,
    now: float,
    visibility_grace_seconds: float = 300.0,
    ledger_cut: tuple[bytes, Mapping[str, Any]] | None = None,
) -> tuple[bytes, dict[str, Any]]:
    """Prove every intent that crossed sbatch is represented at the drain cut.

    The dispatcher fsyncs ``submitting`` before invoking sbatch and keeps the shared
    admission lock until it fsyncs the outcome.  Slurm visibility can nevertheless lag
    an accepted reply.  A pause must therefore reject an apparently empty scheduler
    snapshot while such an intent remains inside its visibility grace; otherwise the
    accepted array could begin after pause falsely reported a complete drain.
    """

    if not snapshot.squeue_ok or not snapshot.sacct_ok:
        raise SchedulerAmbiguity(
            "exact cell drain requires complete squeue+sacct transaction truth"
        )
    if ledger_cut is None:
        ledger_raw, ledger = _production_dispatcher_ledger_preimage(
            state_dir,
            description="exact cell submission-cut dispatcher ledger",
        )
    else:
        ledger_raw, supplied = ledger_cut
        if not isinstance(ledger_raw, bytes) or not isinstance(supplied, Mapping):
            raise SchedulerAmbiguity(
                "exact cell submission cut received an invalid ledger preimage"
            )
        ledger = dict(supplied)
    intents = ledger["intents"]
    jobs = ledger["jobs"]

    for batch_id, intent in sorted(intents.items()):
        if not isinstance(batch_id, str) or not isinstance(intent, dict):
            raise SchedulerAmbiguity("dispatcher ledger contains an invalid cell intent")
        state = str(intent.get("state", ""))
        if state not in {"submitting", "submitted", "reconciled"}:
            # ``prepared`` is durable before the dispatcher changes to ``submitting``;
            # sbatch is never invoked from that state.  Reconciled/terminal states are
            # already represented in the durable jobs table.
            continue
        expected_comment = CELL_INTENT_PREFIX + batch_id
        expected_name = f"asys-dispatch-{batch_id[-10:]}"
        from slurm.dispatch_sweeps import (
            STDIN_EXACT_SUBMISSION_TRANSPORT,
            _command_binds_stdin_submission,
            _stdin_submission_argv_sha256,
        )

        if (
            intent.get("submission_transport")
            != STDIN_EXACT_SUBMISSION_TRANSPORT
            or intent.get("submission_argv_sha256")
            != _stdin_submission_argv_sha256(batch_id)
        ):
            raise SchedulerAmbiguity(
                f"cell intent {batch_id} lacks its exact stdin transport"
            )
        matching_bases: set[str] = set()
        provenance_errors: list[str] = []
        for job in snapshot.jobs:
            base_id = _cell_array_base_job_id(job.job_id)
            if base_id is None:
                continue
            namespace_match = (
                job.comment == expected_comment
                or job.job_name == expected_name
            )
            if not namespace_match:
                continue
            if (
                job.comment != expected_comment
                or job.job_name != expected_name
                or not _command_binds_stdin_submission(job.command, batch_id)
            ):
                provenance_errors.append(job.job_id)
                continue
            matching_bases.add(base_id)
        if provenance_errors:
            raise SchedulerAmbiguity(
                f"cell intent {batch_id} has scheduler provenance drift for jobs "
                f"{sorted(provenance_errors)}"
            )
        if len(matching_bases) > 1:
            raise SchedulerAmbiguity(
                f"cell intent {batch_id} maps to duplicate Slurm jobs "
                f"{sorted(matching_bases)}"
            )
        recorded_job_id = intent.get("job_id")
        recorded_job = (
            jobs.get(str(recorded_job_id)) if recorded_job_id is not None else None
        )
        if recorded_job_id is not None and (
            not str(recorded_job_id).isdigit()
            or matching_bases
            and matching_bases != {str(recorded_job_id)}
        ):
            raise SchedulerAmbiguity(
                f"cell intent {batch_id} conflicts with its accepted Slurm job ID"
            )
        if matching_bases:
            continue
        if isinstance(recorded_job, dict):
            recorded_state = recorded_job.get("state")
            if recorded_state == "terminal":
                # A complete joined scheduler observation previously proved this
                # exact accepted allocation terminal.
                continue
            if recorded_state == "inactive":
                inactive_since = recorded_job.get("inactive_since_at")
                if (
                    not isinstance(inactive_since, (int, float))
                    or isinstance(inactive_since, bool)
                    or not math.isfinite(float(inactive_since))
                ):
                    raise SchedulerAmbiguity(
                        f"inactive cell intent {batch_id} lacks its durable "
                        "absence timestamp"
                    )
                inactive_age = max(
                    0.0, float(now) - float(inactive_since)
                )
                if inactive_age < visibility_grace_seconds:
                    raise SchedulerVisibilityPending(
                        f"accepted cell intent {batch_id} was first observed "
                        f"inactive only {inactive_age:.1f}s ago; retry after "
                        "the visibility contract"
                    )
                continue
        submit_started_at = intent.get("submit_started_at")
        if (
            not isinstance(submit_started_at, (int, float))
            or isinstance(submit_started_at, bool)
            or not math.isfinite(float(submit_started_at))
        ):
            raise SchedulerAmbiguity(
                f"cell intent {batch_id} lacks a valid durable sbatch-boundary timestamp"
            )
        age = max(0.0, float(now) - float(submit_started_at))
        if age < visibility_grace_seconds:
            raise SchedulerVisibilityPending(
                f"cell intent {batch_id} crossed sbatch only {age:.1f}s ago but is not "
                "yet visible in complete squeue+sacct truth; retry pause after visibility"
            )
        if state in {"submitted", "reconciled"} or recorded_job_id is not None:
            raise SchedulerAmbiguity(
                f"accepted cell intent {batch_id} job {recorded_job_id} disappeared from "
                "complete scheduler history"
            )
        # An ID-less ambiguous submit that remains absent from both authoritative
        # sources beyond the visibility grace is proven not accepted for this cut.
    _assert_dispatcher_ledger_preimage_unchanged(
        state_dir,
        expected_raw=ledger_raw,
        description="exact cell submission-cut dispatcher ledger",
    )
    return ledger_raw, ledger


def _lexical_absolute_artifact_path(
    value: Any, *, description: str
) -> Path:
    if not isinstance(value, str) or not value:
        raise SchedulerAmbiguity(f"{description} path is missing")
    supplied = Path(value).expanduser()
    if not supplied.is_absolute():
        raise SchedulerAmbiguity(f"{description} path is not absolute")
    lexical = Path(os.path.abspath(os.fspath(supplied)))
    if str(supplied) != str(lexical):
        raise SchedulerAmbiguity(
            f"{description} path is not lexically canonical"
        )
    return lexical


def _strict_json_object_preimage(
    raw: bytes, *, description: str
) -> dict[str, Any]:
    def unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise SchedulerAmbiguity(
                    f"{description} repeats JSON field {key!r}"
                )
            result[key] = value
        return result

    def finite_float(token: str) -> float:
        value = float(token)
        if not math.isfinite(value):
            raise SchedulerAmbiguity(
                f"{description} contains non-finite number {token!r}"
            )
        return value

    try:
        value = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=unique_object,
            parse_float=finite_float,
            parse_constant=lambda token: (_ for _ in ()).throw(
                SchedulerAmbiguity(
                    f"{description} contains non-finite number {token!r}"
                )
            ),
        )
    except SchedulerAmbiguity:
        raise
    except (UnicodeError, json.JSONDecodeError, ValueError) as exc:
        raise SchedulerAmbiguity(
            f"{description} JSON is invalid: {exc}"
        ) from exc
    if not isinstance(value, dict):
        raise SchedulerAmbiguity(f"{description} is not a JSON object")
    return value


def _cell_worker_binding_from_sbatch(
    raw: bytes,
    *,
    batch_id: str,
    expected_job_name: str,
    batch_manifest_path: Path,
    batch_manifest_sha256: str,
    task_count: int,
) -> dict[str, str]:
    try:
        text = raw.decode("utf-8")
    except UnicodeError as exc:
        raise SchedulerAmbiguity(
            f"cell batch {batch_id} sbatch is not UTF-8"
        ) from exc
    collapsed = text.replace("\\\n", " ")
    worker_lines = [
        line.strip()
        for line in collapsed.splitlines()
        if line.lstrip().startswith("exec ")
    ]
    if len(worker_lines) != 1:
        raise SchedulerAmbiguity(
            f"cell batch {batch_id} sbatch must contain one worker exec"
        )
    try:
        tokens = shlex.split(worker_lines[0])
    except ValueError as exc:
        raise SchedulerAmbiguity(
            f"cell batch {batch_id} worker command is invalid: {exc}"
        ) from exc
    run_task_positions = [
        index for index, token in enumerate(tokens) if token == "run-task"
    ]
    if (
        not tokens
        or tokens[0] != "exec"
        or len(run_task_positions) != 1
        or run_task_positions[0] < 2
    ):
        raise SchedulerAmbiguity(
            f"cell batch {batch_id} sbatch lacks its exact run-task worker"
        )
    run_task_index = run_task_positions[0]
    worker_script = Path(tokens[run_task_index - 1]).expanduser()
    worker_lexical = (
        Path(os.path.abspath(os.fspath(worker_script)))
        if worker_script.is_absolute()
        else None
    )
    if (
        worker_lexical is None
        or str(worker_script) != str(worker_lexical)
        or worker_lexical.name != "dispatch_sweeps.py"
        or worker_lexical.parent.name != "slurm"
    ):
        raise SchedulerAmbiguity(
            f"cell batch {batch_id} sbatch worker path is not exact"
        )

    def exact_option(name: str) -> str:
        positions = [
            index for index, token in enumerate(tokens) if token == name
        ]
        if (
            len(positions) != 1
            or positions[0] + 1 >= len(tokens)
        ):
            raise SchedulerAmbiguity(
                f"cell batch {batch_id} sbatch option {name} is ambiguous"
            )
        return tokens[positions[0] + 1]

    if (
        exact_option("--batch-manifest") != str(batch_manifest_path)
        or exact_option("--batch-manifest-sha256")
        != batch_manifest_sha256
        or exact_option("--index") != "$SLURM_ARRAY_TASK_ID"
    ):
        raise SchedulerAmbiguity(
            f"cell batch {batch_id} sbatch worker arguments drifted"
        )
    directive_lines = [line.strip() for line in text.splitlines()]
    for directive in (
        f"#SBATCH --job-name={expected_job_name}",
        f"#SBATCH --comment={CELL_INTENT_PREFIX}{batch_id}",
        "#SBATCH --cpus-per-task=1",
        "#SBATCH --mem=4G",
        "#SBATCH --time=12:00:00",
        f"#SBATCH --array=0-{task_count - 1}%{task_count}",
        "#SBATCH --signal=B:USR1@1200",
        "#SBATCH --no-requeue",
        "#SBATCH --export=NONE",
    ):
        if directive_lines.count(directive) != 1:
            raise SchedulerAmbiguity(
                f"cell batch {batch_id} sbatch directive drifted: "
                f"{directive}"
            )
    return {
        "worker_script": str(worker_lexical),
        "worker_command_sha256": hashlib.sha256(
            worker_lines[0].encode("utf-8")
        ).hexdigest(),
    }


def _exact_live_cell_task_actions(
    state_dir: Path,
    snapshot: SchedulerSnapshot,
    *,
    ledger_preimage: Mapping[str, Any] | None = None,
    trusted_bindings: (
        MutableMapping[str, dict[str, Any]] | None
    ) = None,
) -> tuple[list[str], list[str]]:
    """Map every live schema-5 cell task to a durable drain action.

    A pause signal is a mutating scheduler operation, so job-name matching alone is
    insufficient.  The live squeue row must bind the exact array base ID, batch token,
    and immutable sbatch path recorded in the dispatcher ledger.  Any scoped row that
    cannot be proven is an ambiguity and prevents *all* signalling.  Running/batch
    workers receive USR1; pending/configuring/suspended elements are canceled exactly so
    they cannot begin stochastic work after the paused snapshot.
    """

    if not snapshot.squeue_ok:
        raise SchedulerAmbiguity(
            "exact cell drain requires authoritative live squeue truth"
        )
    live_rows = [
        job
        for job in snapshot.jobs
        if job.source == "squeue"
        and normalize_scheduler_state(job.state) in ACTIVE_SCHEDULER_STATES
        and _cell_job(job.job_name)
    ]
    ledger_raw: bytes | None = None
    if ledger_preimage is None:
        ledger_raw, ledger = _production_dispatcher_ledger_preimage(
            state_dir,
            description="exact cell drain dispatcher ledger",
        )
    else:
        try:
            from slurm.dispatch_sweeps import (
                validate_production_ledger_structure,
            )

            ledger = validate_production_ledger_structure(
                dict(ledger_preimage),
                source=str(state_dir / "ledger.json"),
            )
        except Exception as exc:
            raise SchedulerAmbiguity(
                f"exact cell drain received an invalid ledger preimage: {exc}"
            ) from exc
    if not isinstance(ledger, dict) or not isinstance(ledger.get("jobs"), dict):
        raise SchedulerAmbiguity("dispatcher ledger has no typed jobs mapping")
    intents = ledger.get("intents")
    if not isinstance(intents, dict):
        raise SchedulerAmbiguity("dispatcher ledger has no typed intents mapping")
    if not live_rows:
        if ledger_raw is not None:
            _assert_dispatcher_ledger_preimage_unchanged(
                state_dir,
                expected_raw=ledger_raw,
                description="exact cell drain dispatcher ledger",
            )
        return [], []

    signal_ids: list[str] = []
    cancel_ids: list[str] = []
    errors: list[str] = []
    artifact_bindings: dict[
        tuple[str, str], tuple[dict[str, Any], list[Any]]
    ] = {}
    for job in live_rows:
        base_id = _cell_array_base_job_id(job.job_id)
        if base_id is None:
            errors.append(f"unsafe cell task ID {job.job_id!r}")
            continue
        if not job.job_name.startswith("asys-dispatch-"):
            errors.append(f"unscoped legacy cell task {job.job_id} ({job.job_name})")
            continue
        if not job.comment.startswith(CELL_INTENT_PREFIX):
            errors.append(f"cell task {job.job_id} lacks a schema-5 batch token")
            continue
        batch_id = job.comment[len(CELL_INTENT_PREFIX) :]
        record = ledger["jobs"].get(base_id)
        intent = intents.get(batch_id)
        if not isinstance(intent, dict):
            errors.append(
                f"cell task {job.job_id} is absent from its durable intent ledger"
            )
            continue
        expected_name = f"asys-dispatch-{batch_id[-10:]}"
        from slurm.dispatch_sweeps import (
            STDIN_EXACT_SUBMISSION_TRANSPORT,
            _command_binds_stdin_submission,
            _stdin_submission_argv_sha256,
        )

        if job.job_name != expected_name:
            errors.append(
                f"cell task {job.job_id} has unexpected job name {job.job_name!r}"
            )
            continue
        if (
            intent.get("submission_transport")
            != STDIN_EXACT_SUBMISSION_TRANSPORT
            or intent.get("submission_argv_sha256")
            != _stdin_submission_argv_sha256(batch_id)
            or not _command_binds_stdin_submission(job.command, batch_id)
        ):
            errors.append(
                f"cell task {job.job_id} lacks its exact stdin submission "
                "transport"
            )
            continue
        intent_job_id = intent.get("job_id")
        if intent_job_id is not None and str(intent_job_id) != base_id:
            errors.append(
                f"cell task {job.job_id} conflicts with batch intent {batch_id}"
            )
            continue
        if isinstance(record, dict):
            if (
                str(record.get("job_id")) != base_id
                or str(record.get("batch_id")) != batch_id
                or str(record.get("sbatch_path"))
                != str(intent.get("sbatch_path"))
            ):
                errors.append(
                    f"cell task {job.job_id} conflicts with batch intent {batch_id}"
                )
                continue
        elif str(intent.get("state")) != "submitting":
            errors.append(
                f"cell task {job.job_id} has no accepted or ambiguous durable job record"
            )
            continue
        intent_tasks = intent.get("tasks")
        if not isinstance(intent_tasks, list):
            errors.append(
                f"cell task {job.job_id} intent has no typed task list"
            )
            continue
        if intent.get("state") not in {
            "submitting",
            "submitted",
            "reconciled",
        }:
            errors.append(
                f"cell task {job.job_id} has incompatible intent state "
                f"{intent.get('state')!r}"
            )
            continue
        if isinstance(record, dict) and (
            any(
                record.get(field) != intent.get(field)
                for field in (
                    "batch_manifest",
                    "batch_manifest_sha256",
                    "sbatch_path",
                    "sbatch_sha256",
                    "tasks",
                    "submission_transport",
                    "submission_argv_sha256",
                )
            )
            or record.get("spooled_sbatch_sha256")
            != intent.get("sbatch_sha256")
            or not isinstance(record.get("task_count"), int)
            or isinstance(record.get("task_count"), bool)
            or record.get("task_count") != len(intent_tasks)
            or record.get("state")
            not in {"submitted", "active", "visibility_grace"}
        ):
            errors.append(
                f"cell task {job.job_id} job record differs from intent "
                f"{batch_id} or has incompatible state"
            )
            continue
        task_suffix = job.job_id.partition("_")[2]
        if not task_suffix:
            errors.append(
                f"cell task {job.job_id} is an unexpanded array parent"
            )
            continue
        if int(task_suffix) >= len(intent_tasks):
            errors.append(
                f"cell task {job.job_id} index exceeds its durable task list"
            )
            continue
        try:
            sbatch_artifact = _lexical_absolute_artifact_path(
                intent.get("sbatch_path"),
                description=f"cell batch {batch_id} sbatch",
            )
            manifest_artifact = _lexical_absolute_artifact_path(
                intent.get("batch_manifest"),
                description=f"cell batch {batch_id} manifest",
            )
            sbatch_sha256 = str(intent.get("sbatch_sha256", ""))
            manifest_sha256 = str(
                intent.get("batch_manifest_sha256", "")
            )
            if (
                _SHA256_RE.fullmatch(sbatch_sha256) is None
                or _SHA256_RE.fullmatch(manifest_sha256) is None
            ):
                raise SchedulerAmbiguity(
                    f"cell batch {batch_id} artifact hashes are invalid"
                )
            cache_key = (base_id, batch_id)
            cached = artifact_bindings.get(cache_key)
            if cached is None:
                sbatch_raw = _stable_readonly_preimage(
                    sbatch_artifact,
                    description=f"cell batch {batch_id} sbatch",
                )
                manifest_raw = _stable_readonly_preimage(
                    manifest_artifact,
                    description=f"cell batch {batch_id} manifest",
                )
                if (
                    hashlib.sha256(sbatch_raw).hexdigest()
                    != sbatch_sha256
                    or hashlib.sha256(manifest_raw).hexdigest()
                    != manifest_sha256
                ):
                    raise SchedulerAmbiguity(
                        f"cell batch {batch_id} artifact hash drifted"
                    )
                if isinstance(record, dict):
                    from slurm.dispatch_sweeps import (
                        DispatcherError,
                        _spooled_script_receipt,
                    )

                    try:
                        (
                            observed_receipt_path,
                            observed_receipt_sha256,
                        ) = _spooled_script_receipt(
                            batch_id=batch_id,
                            job_id=base_id,
                            expected_name=expected_name,
                            expected_comment=job.comment,
                            sbatch_path=sbatch_artifact,
                            sbatch_sha256=sbatch_sha256,
                            spooled_script_reader=lambda _job_id: (
                                _ for _ in ()
                            ).throw(
                                DispatcherError(
                                    "sealed spooled-script receipt is missing"
                                )
                            ),
                            now=float(snapshot.captured_at),
                        )
                    except DispatcherError as exc:
                        raise SchedulerAmbiguity(str(exc)) from exc
                    if (
                        observed_receipt_path
                        != record.get("spooled_receipt_path")
                        or observed_receipt_sha256
                        != record.get("spooled_receipt_sha256")
                    ):
                        raise SchedulerAmbiguity(
                            f"cell batch {batch_id} spooled-script receipt "
                            "differs from its durable job record"
                        )
                else:
                    from slurm.dispatch_sweeps import (
                        _read_spooled_batch_script,
                    )

                    if (
                        hashlib.sha256(
                            _read_spooled_batch_script(base_id)
                        ).hexdigest()
                        != sbatch_sha256
                    ):
                        raise SchedulerAmbiguity(
                            f"cell batch {batch_id} Slurm-spooled script "
                            "differs from its durable intent"
                        )
                manifest = _strict_json_object_preimage(
                    manifest_raw,
                    description=f"cell batch {batch_id} manifest",
                )
                if (
                    manifest.get("schema_version") != 1
                    or manifest.get("batch_id") != batch_id
                    or manifest.get("tasks") != intent_tasks
                ):
                    raise SchedulerAmbiguity(
                        f"cell batch {batch_id} manifest differs from intent"
                    )
                worker_binding = _cell_worker_binding_from_sbatch(
                    sbatch_raw,
                    batch_id=batch_id,
                    expected_job_name=expected_name,
                    batch_manifest_path=manifest_artifact,
                    batch_manifest_sha256=manifest_sha256,
                    task_count=len(intent_tasks),
                )
                artifact_binding = {
                    "array_job_id": base_id,
                    "batch_id": batch_id,
                    "job_name": job.job_name,
                    "comment": job.comment,
                    "sbatch_path": str(sbatch_artifact),
                    "sbatch_sha256": sbatch_sha256,
                    "batch_manifest_path": str(manifest_artifact),
                    "batch_manifest_sha256": manifest_sha256,
                    **worker_binding,
                }
                artifact_bindings[cache_key] = (
                    artifact_binding,
                    intent_tasks,
                )
            else:
                artifact_binding, cached_tasks = cached
                if cached_tasks != intent_tasks:
                    raise SchedulerAmbiguity(
                        f"cell batch {batch_id} task mapping changed"
                    )
        except (
            OSError,
            ValueError,
            SchedulerAmbiguity,
        ) as exc:
            errors.append(
                f"cell task {job.job_id} artifact provenance failed: {exc}"
            )
            continue
        if trusted_bindings is not None:
            binding = {
                **artifact_binding,
                "scheduler_job_id": job.job_id,
                "state": normalize_scheduler_state(job.state),
            }
            prior = trusted_bindings.setdefault(job.job_id, binding)
            if prior != binding:
                errors.append(
                    f"cell task {job.job_id} has conflicting artifact bindings"
                )
                continue
        if normalize_scheduler_state(job.state) in {"RUNNING", "COMPLETING"}:
            signal_ids.append(job.job_id)
        else:
            cancel_ids.append(job.job_id)
    if errors:
        raise SchedulerAmbiguity(
            "exact cell drain mapping failed: " + "; ".join(errors)
        )
    all_ids = signal_ids + cancel_ids
    if len(all_ids) != len(set(all_ids)):
        raise SchedulerAmbiguity("exact cell drain contains duplicate task IDs")
    if ledger_raw is not None:
        _assert_dispatcher_ledger_preimage_unchanged(
            state_dir,
            expected_raw=ledger_raw,
            description="exact cell drain dispatcher ledger",
        )
    return sorted(signal_ids), sorted(cancel_ids)


def _exact_running_cell_task_ids(
    state_dir: Path, snapshot: SchedulerSnapshot
) -> list[str]:
    """Compatibility helper returning the signalable subset of an exact drain."""

    signal_ids, _cancel_ids = _exact_live_cell_task_actions(state_dir, snapshot)
    return signal_ids


_TRUSTED_SCIENTIFIC_LIVE_STATES = {
    "PENDING",
    "RUNNING",
    "CONFIGURING",
    "COMPLETING",
    "RESIZING",
    "SUSPENDED",
}
_TRUSTED_FLEET_BINDING_FIELDS = {
    "job_name",
    "comment",
    "sbatch_path",
    "sbatch_sha256",
    "intent_token",
    "replica_id",
    "serving_profile",
    "ledger_generation",
    "ledger_path",
    "ledger_sha256",
    "partition",
    "qos",
    "allocated_gpus",
    "gpu_type",
}

_SCIENTIFIC_SBATCH_RESOURCE_FLAGS = frozenset(
    {
        "--account",
        "--constraint",
        "--cpus-per-task",
        "--gres",
        "--gpus",
        "--gpus-per-node",
        "--gpus-per-socket",
        "--gpus-per-task",
        "--mem",
        "--mem-per-cpu",
        "--mem-per-gpu",
        "--nodes",
        "--ntasks",
        "--ntasks-per-node",
        "--partition",
        "--qos",
        "--reservation",
        "--tres-per-job",
        "--tres-per-node",
        "--tres-per-socket",
        "--tres-per-task",
    }
)
_SCIENTIFIC_SBATCH_SHORT_RESOURCE_FLAGS = frozenset(
    {"-A", "-C", "-N", "-c", "-n", "-p", "-q"}
)


def _command_has_scientific_resource_override(command: str) -> bool:
    """Reject CLI resource overrides that can supersede an immutable sbatch file."""

    try:
        tokens = shlex.split(command)
    except ValueError:
        return True
    for token in tokens:
        if token in _SCIENTIFIC_SBATCH_SHORT_RESOURCE_FLAGS:
            return True
        if re.fullmatch(r"-[ACNcnpq].+", token) is not None:
            return True
        if any(
            token == flag or token.startswith(flag + "=")
            for flag in _SCIENTIFIC_SBATCH_RESOURCE_FLAGS
        ):
            return True
    return False


def _stable_mutable_json_preimage(
    path: Path,
    *,
    required_parent: Path | None,
    description: str,
) -> tuple[bytes, dict[str, Any]]:
    """Read one atomic mutable ledger without following or racing replacement."""

    lexical = Path(os.path.abspath(os.fspath(path.expanduser())))
    if required_parent is not None:
        parent = Path(
            os.path.abspath(os.fspath(required_parent.expanduser()))
        ).resolve()
        if lexical.parent != parent:
            raise SchedulerAmbiguity(
                f"{description} is outside its exact state directory"
            )
    try:
        resolved = lexical.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise SchedulerAmbiguity(f"{description} is unavailable: {exc}") from exc
    if resolved != lexical or lexical.is_symlink():
        raise SchedulerAmbiguity(f"{description} traverses a symlink")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(lexical, flags)
    except OSError as exc:
        raise SchedulerAmbiguity(f"cannot open {description}: {exc}") from exc
    try:
        before = os.fstat(descriptor)
        blocks: list[bytes] = []
        while block := os.read(descriptor, 1024 * 1024):
            blocks.append(block)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    identity = lambda item: (  # noqa: E731
        item.st_dev,
        item.st_ino,
        item.st_mode,
        item.st_nlink,
        item.st_size,
        item.st_mtime_ns,
        item.st_ctime_ns,
    )
    try:
        current = lexical.stat(follow_symlinks=False)
    except OSError as exc:
        raise SchedulerAmbiguity(
            f"{description} disappeared after its stable read: {exc}"
        ) from exc
    if (
        not stat.S_ISREG(before.st_mode)
        or before.st_nlink != 1
        or identity(before) != identity(after)
        or identity(current) != identity(after)
    ):
        raise SchedulerAmbiguity(
            f"{description} changed or is not a one-link regular file"
        )
    raw = b"".join(blocks)
    value = _strict_json_object_preimage(
        raw, description=description
    )
    return raw, value


def _production_dispatcher_ledger_preimage(
    state_dir: Path, *, description: str
) -> tuple[bytes, dict[str, Any]]:
    """Load the mandatory, production-closed dispatcher transaction ledger."""

    ledger_path = state_dir / "ledger.json"
    try:
        raw, ledger = _stable_mutable_json_preimage(
            ledger_path,
            required_parent=state_dir,
            description=description,
        )
        from slurm.dispatch_sweeps import validate_production_ledger_structure

        ledger = validate_production_ledger_structure(
            ledger, source=str(ledger_path)
        )
    except Exception as exc:
        raise SchedulerAmbiguity(
            f"cannot prove the mandatory dispatcher ledger cut: {exc}"
        ) from exc
    return raw, ledger


def _assert_dispatcher_ledger_preimage_unchanged(
    state_dir: Path, *, expected_raw: bytes, description: str
) -> None:
    observed_raw, _ledger = _production_dispatcher_ledger_preimage(
        state_dir, description=description
    )
    if observed_raw != expected_raw:
        raise SchedulerAmbiguity(
            f"{description} changed before the drain transaction committed"
        )


def _stable_readonly_preimage(path: Path, *, description: str) -> bytes:
    lexical = Path(os.path.abspath(os.fspath(path.expanduser())))
    try:
        resolved = lexical.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise SchedulerAmbiguity(f"{description} is unavailable: {exc}") from exc
    if resolved != lexical or lexical.is_symlink():
        raise SchedulerAmbiguity(f"{description} traverses a symlink")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(lexical, flags)
    except OSError as exc:
        raise SchedulerAmbiguity(f"cannot open {description}: {exc}") from exc
    try:
        before = os.fstat(descriptor)
        blocks: list[bytes] = []
        while block := os.read(descriptor, 1024 * 1024):
            blocks.append(block)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    identity = lambda item: (  # noqa: E731
        item.st_dev,
        item.st_ino,
        item.st_mode,
        item.st_nlink,
        item.st_size,
        item.st_mtime_ns,
        item.st_ctime_ns,
    )
    try:
        current = lexical.stat(follow_symlinks=False)
    except OSError as exc:
        raise SchedulerAmbiguity(
            f"{description} disappeared after its stable read: {exc}"
        ) from exc
    if (
        not stat.S_ISREG(before.st_mode)
        or before.st_nlink != 1
        or stat.S_IMODE(before.st_mode) & 0o222
        or identity(before) != identity(after)
        or identity(current) != identity(after)
        or stat.S_IMODE(current.st_mode) & 0o222
    ):
        raise SchedulerAmbiguity(
            f"{description} changed or is not a one-link read-only regular file"
        )
    return b"".join(blocks)


def _trusted_scientific_live_scheduler_rows(
    snapshot: SchedulerSnapshot,
    *,
    now: float,
) -> dict[str, SchedulerJob]:
    if (
        snapshot.squeue_ok is not True
        or snapshot.sacct_ok is not True
        or snapshot.errors
        or not math.isfinite(float(snapshot.captured_at))
        or float(snapshot.captured_at) <= 0
        or float(snapshot.captured_at) > now + 1.0
        or now - float(snapshot.captured_at)
        > protected_capacity.MAX_TRUSTED_SCHEDULER_AGE_SECONDS
    ):
        raise SchedulerAmbiguity(
            "trusted scientific occupancy requires complete, current "
            "squeue+sacct truth"
        )
    live: dict[str, SchedulerJob] = {}
    for row in snapshot.jobs:
        if row.source != "squeue":
            continue
        state = normalize_scheduler_state(row.state)
        if state not in _TRUSTED_SCIENTIFIC_LIVE_STATES:
            continue
        if _EXACT_CELL_TASK_ID.fullmatch(row.job_id) is None or row.job_id in live:
            raise SchedulerAmbiguity(
                "trusted scientific scheduler truth contains a malformed or "
                f"duplicated live identity: {row.job_id!r}"
            )
        if (
            re.fullmatch(r"[A-Za-z0-9_.-]+", row.partition) is None
            or re.fullmatch(r"[A-Za-z0-9_.-]+", row.qos) is None
        ):
            raise SchedulerAmbiguity(
                "trusted scientific scheduler truth lacks exact partition/QOS "
                f"for live job {row.job_id}"
            )
        live[row.job_id] = row
    return live


def _trusted_dispatcher_bindings(
    state_dir: Path,
    snapshot: SchedulerSnapshot,
    *,
    live_rows: Mapping[str, SchedulerJob],
    now: float,
    allow_exact_quiescence: bool,
) -> tuple[dict[str, dict[str, Any]], float | None, bool, str]:
    scoped = {
        job_id: row
        for job_id, row in live_rows.items()
        if row.comment.startswith(CELL_INTENT_PREFIX) or _cell_job(row.job_name)
    }
    ledger_path = state_dir / "ledger.json"
    if not scoped and allow_exact_quiescence:
        raw, ledger = _production_dispatcher_ledger_preimage(
            state_dir,
            description="trusted quiescent dispatcher ledger",
        )
        updated = ledger.get("updated_at")
        ledger_updated = (
            float(updated)
            if isinstance(updated, (int, float))
            and not isinstance(updated, bool)
            and math.isfinite(float(updated))
            and float(updated) > 0
            and float(updated) <= now + 1.0
            else None
        )
        ledger_sha256 = hashlib.sha256(raw).hexdigest()
        provenance_id = sha256_value(
            {
                "exact_cell_quiescence": True,
                "ledger_sha256": ledger_sha256,
                "bindings": {},
            }
        )
        return {}, ledger_updated, True, provenance_id

    raw, ledger = _production_dispatcher_ledger_preimage(
        state_dir,
        description="trusted scientific dispatcher ledger",
    )
    updated = ledger.get("updated_at")
    if (
        not isinstance(updated, (int, float))
        or isinstance(updated, bool)
        or not math.isfinite(float(updated))
        or float(updated) <= 0
        or float(updated) > now + 1.0
        or now - float(updated)
        > protected_capacity.MAX_DISPATCHER_LEDGER_AGE_SECONDS
    ):
        raise SchedulerAmbiguity(
            "trusted scientific dispatcher ledger is missing, future, or "
            "older than 360 seconds"
        )
    # This existing exact drain join validates the immutable intent, numeric array
    # base/task, scheduler name/comment, and exact sbatch command for every scoped row.
    # The returned set must equal the namespace selected above.  In particular, a
    # foreign-named job carrying a forged schema-5 comment must be rejected rather
    # than silently skipped by the drain mapper and then discounted as trusted.
    bindings: dict[str, dict[str, Any]] = {}
    signal_ids, cancel_ids = _exact_live_cell_task_actions(
        state_dir,
        snapshot,
        ledger_preimage=ledger,
        trusted_bindings=bindings,
    )
    mapped_ids = set(signal_ids) | set(cancel_ids)
    if mapped_ids != set(scoped):
        raise SchedulerAmbiguity(
            "trusted scientific dispatcher mapping differs from its exact "
            "scheduler namespace: "
            f"missing={sorted(set(scoped) - mapped_ids)}, "
            f"unexpected={sorted(mapped_ids - set(scoped))}"
        )
    if set(bindings) != mapped_ids:
        raise SchedulerAmbiguity(
            "trusted scientific dispatcher artifact bindings differ from "
            "the exact mapped task set"
        )
    resource_overrides = sorted(
        job_id
        for job_id in mapped_ids
        if _command_has_scientific_resource_override(
            scoped[job_id].command
        )
    )
    if resource_overrides:
        raise SchedulerAmbiguity(
            "trusted scientific dispatcher jobs contain scheduler resource "
            "overrides outside their immutable sbatch files: "
            + ", ".join(resource_overrides)
        )
    bindings = {
        job_id: {
            **binding,
            "partition": scoped[job_id].partition,
            "qos": scoped[job_id].qos,
        }
        for job_id, binding in bindings.items()
    }
    post_raw, _post_ledger = _production_dispatcher_ledger_preimage(
        state_dir,
        description="trusted scientific dispatcher ledger",
    )
    if post_raw != raw:
        raise SchedulerAmbiguity(
            "trusted scientific dispatcher ledger changed while its cell "
            "artifacts were reconciled"
        )
    provenance_id = sha256_value(
        {
            "exact_cell_quiescence": False,
            "ledger_sha256": hashlib.sha256(raw).hexdigest(),
            "bindings": bindings,
        }
    )
    return bindings, float(updated), False, provenance_id


def reconcile_trusted_scientific_job_provenance(
    state_dir: Path,
    *,
    fleet_bindings: Mapping[str, Mapping[str, Any]],
    fleet_contract_sha256: str,
    fleet_generation: int,
    scheduler_snapshot: SchedulerSnapshot | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    now: float | None = None,
    allow_exact_cell_quiescence: bool = False,
) -> protected_capacity.TrustedScientificJobProvenance:
    """Join exact dispatcher/fleet ledgers to complete current scheduler truth.

    Callers may supply fleet IDs only after their fleet transaction, registry/history,
    and spooled-script validators have accepted the binding.  This shared boundary
    independently rejects name/comment-only matches, missing siblings, stale
    dispatcher state, and any scheduler-set ambiguity before residual capacity can
    discount an allocation.
    """

    timestamp = time.time() if now is None else float(now)
    snapshot = (
        scheduler_snapshot
        if scheduler_snapshot is not None
        else (scheduler_reader or (lambda: query_scheduler(now=timestamp)))()
    )
    live_rows = _trusted_scientific_live_scheduler_rows(
        snapshot,
        now=timestamp,
    )
    (
        cell_bindings,
        dispatcher_updated,
        exact_quiescence,
        dispatcher_provenance_id,
    ) = _trusted_dispatcher_bindings(
        Path(state_dir),
        snapshot,
        live_rows=live_rows,
        now=timestamp,
        allow_exact_quiescence=allow_exact_cell_quiescence,
    )
    if not isinstance(fleet_bindings, Mapping):
        raise SchedulerAmbiguity(
            "trusted scientific fleet bindings are not a mapping"
        )
    normalized_fleet: dict[str, dict[str, Any]] = {}
    expected_names: set[str] = set()
    for job_id, raw_binding in sorted(fleet_bindings.items()):
        if (
            not isinstance(job_id, str)
            or not job_id.isdigit()
            or not isinstance(raw_binding, Mapping)
            or set(raw_binding) != _TRUSTED_FLEET_BINDING_FIELDS
        ):
            raise SchedulerAmbiguity(
                "trusted scientific fleet binding fields are invalid"
            )
        binding = dict(raw_binding)
        row = live_rows.get(job_id)
        partition = binding.get("partition")
        qos = binding.get("qos")
        allocated_gpus = binding.get("allocated_gpus")
        gpu_type = binding.get("gpu_type")
        serving_profile = binding.get("serving_profile")
        if (
            not isinstance(partition, str)
            or re.fullmatch(r"[A-Za-z0-9_.-]+", partition) is None
            or not isinstance(qos, str)
            or re.fullmatch(r"[A-Za-z0-9_.-]+", qos) is None
            or not isinstance(allocated_gpus, int)
            or isinstance(allocated_gpus, bool)
            or allocated_gpus < 1
            or not isinstance(gpu_type, str)
            or re.fullmatch(r"[A-Za-z0-9_.-]+", gpu_type) is None
            or not isinstance(serving_profile, str)
            or re.fullmatch(r"[A-Za-z0-9_.-]+", serving_profile) is None
        ):
            raise SchedulerAmbiguity(
                f"trusted scientific fleet job {job_id} has invalid placement "
                "or GPU authority"
            )
        parsed = fleet_transactions.parse_intent_comment(
            str(binding.get("comment", ""))
        )
        sbatch_lexical = Path(
            os.path.abspath(
                os.fspath(
                    Path(str(binding.get("sbatch_path", ""))).expanduser()
                )
            )
        )
        sbatch_path = str(sbatch_lexical)
        ledger_generation = binding.get("ledger_generation")
        if (
            not isinstance(ledger_generation, int)
            or isinstance(ledger_generation, bool)
            or ledger_generation < 1
            or ledger_generation != fleet_generation
        ):
            raise SchedulerAmbiguity(
                f"trusted scientific fleet job {job_id} has an invalid "
                "or non-current ledger generation"
            )
        sbatch = sbatch_lexical
        try:
            transaction_directory = sbatch.parents[2]
        except IndexError as exc:
            raise SchedulerAmbiguity(
                f"trusted scientific fleet job {job_id} has an unsafe script path"
            ) from exc
        expected_ledger_path = Path(
            os.path.abspath(
                os.fspath(
                    fleet_transactions.ledger_path(
                        transaction_directory,
                        ledger_generation,
                    ).expanduser()
                )
            )
        )
        supplied_ledger_path = Path(
            os.path.abspath(
                os.fspath(
                    Path(
                        str(binding.get("ledger_path", ""))
                    ).expanduser()
                )
            )
        )
        if supplied_ledger_path != expected_ledger_path:
            raise SchedulerAmbiguity(
                f"trusted scientific fleet job {job_id} ledger path is not "
                "generation-addressed from its script"
            )
        sbatch_raw = _stable_readonly_preimage(
            sbatch,
            description=f"trusted fleet script for job {job_id}",
        )
        ledger_raw, fleet_ledger = _stable_mutable_json_preimage(
            supplied_ledger_path,
            required_parent=expected_ledger_path.parent,
            description=f"trusted fleet ledger for job {job_id}",
        )
        replicas = fleet_ledger.get("replicas")
        replica_record = (
            replicas.get(str(binding.get("replica_id")))
            if isinstance(replicas, Mapping)
            else None
        )
        attempts = (
            replica_record.get("attempts")
            if isinstance(replica_record, Mapping)
            else None
        )
        exact_attempts = [
            attempt
            for attempt in attempts
            if isinstance(attempt, Mapping)
            and attempt.get("intent_token") == binding.get("intent_token")
            and str(attempt.get("job_id")) == job_id
            and attempt.get("sbatch_path") == sbatch_path
            and attempt.get("sbatch_sha256")
            == binding.get("sbatch_sha256")
            and attempt.get("submission_transport")
            == fleet_transactions.STDIN_EXACT_SUBMISSION_TRANSPORT
            and attempt.get("submission_argv_sha256")
            == fleet_transactions.submission_argv_sha256(
                str(binding.get("comment", ""))
            )
            and attempt.get("allocated_gpus") == allocated_gpus
            and attempt.get("state") == "committed"
        ] if isinstance(attempts, list) else []
        try:
            sbatch_text = sbatch_raw.decode("utf-8")
        except UnicodeError as exc:
            raise SchedulerAmbiguity(
                f"trusted fleet script for job {job_id} is not UTF-8"
            ) from exc
        sbatch_lines = [line.strip() for line in sbatch_text.splitlines()]
        placement_directives_valid = all(
            sbatch_lines.count(directive) == 1
            for directive in (
                f"#SBATCH --partition={partition}",
                f"#SBATCH --qos={qos}",
                f"#SBATCH --gres=gpu:{gpu_type}:{allocated_gpus}",
            )
        )
        # Slurm's portable squeue/sacct formats expose requested placement but do not
        # expose a complete per-job GPU allocation in one authoritative field.  Bind
        # GPU authority to the immutable script and committed generation ledger, and
        # reject CLI resource overrides that could supersede either source.
        if (
            row is None
            or row.job_name != binding.get("job_name")
            or row.comment != binding.get("comment")
            or row.partition != partition
            or row.qos != qos
            or not fleet_transactions.command_binds_stdin_submission(
                row.command, str(binding.get("comment", ""))
            )
            or _command_has_scientific_resource_override(row.command)
            or _SHA256_RE.fullmatch(str(binding.get("sbatch_sha256", "")))
            is None
            or hashlib.sha256(sbatch_raw).hexdigest()
            != binding.get("sbatch_sha256")
            or _SHA256_RE.fullmatch(str(binding.get("ledger_sha256", "")))
            is None
            or hashlib.sha256(ledger_raw).hexdigest()
            != binding.get("ledger_sha256")
            or fleet_ledger.get("rollout_generation") != ledger_generation
            or len(exact_attempts) != 1
            or not placement_directives_valid
            or parsed is None
            or parsed.get("fleet") != fleet_contract_sha256
            or parsed.get("intent") != binding.get("intent_token")
            or parsed.get("replica") != binding.get("replica_id")
            or parsed.get("profile") != serving_profile
            or parsed.get("generation")
            != str(binding.get("ledger_generation"))
        ):
            raise SchedulerAmbiguity(
                f"trusted scientific fleet job {job_id} lacks its exact "
                "ledger/scheduler/script provenance"
            )
        expected_names.add(str(binding["job_name"]))
        normalized_fleet[job_id] = {
            **binding,
            "sbatch_path": sbatch_path,
            "state": normalize_scheduler_state(row.state),
        }
    unbound_fleet: list[str] = []
    for job_id, row in live_rows.items():
        parsed = fleet_transactions.parse_intent_comment(row.comment)
        in_namespace = (
            row.job_name.startswith("asys-s5-serve-")
            or row.job_name in expected_names
            or (
                parsed is not None
                and parsed.get("fleet") == fleet_contract_sha256
            )
        )
        if in_namespace and job_id not in normalized_fleet:
            unbound_fleet.append(job_id)
    if unbound_fleet:
        raise SchedulerAmbiguity(
            "trusted scientific fleet reconciliation has unbound live jobs: "
            + ", ".join(sorted(unbound_fleet))
        )
    scheduler_states = {
        job_id: normalize_scheduler_state(row.state)
        for job_id, row in sorted(live_rows.items())
    }
    scheduler_truth_id = sha256_value(
        {
            "captured_at": snapshot.captured_at,
            "squeue_ok": snapshot.squeue_ok,
            "sacct_ok": snapshot.sacct_ok,
            "errors": list(snapshot.errors),
            "jobs": [
                {
                    "job_id": row.job_id,
                    "job_name": row.job_name,
                    "state": row.state,
                    "comment": row.comment,
                    "command": row.command,
                    "source": row.source,
                    "partition": row.partition,
                    "qos": row.qos,
                }
                for row in snapshot.jobs
            ],
        }
    )
    fleet_provenance_id = sha256_value(
        {
            "fleet_contract_sha256": fleet_contract_sha256,
            "fleet_generation": fleet_generation,
            "bindings": normalized_fleet,
        }
    )
    try:
        return protected_capacity.build_trusted_scientific_job_provenance(
            scheduler_job_states=scheduler_states,
            scheduler_captured_timestamp=float(snapshot.captured_at),
            trusted_cell_job_ids=tuple(cell_bindings),
            trusted_fleet_job_ids=tuple(normalized_fleet),
            dispatcher_ledger_updated_timestamp=dispatcher_updated,
            exact_cell_quiescence=exact_quiescence,
            dispatcher_provenance_id=dispatcher_provenance_id,
            fleet_provenance_id=fleet_provenance_id,
            fleet_contract_sha256=fleet_contract_sha256,
            fleet_generation=fleet_generation,
            scheduler_truth_id=scheduler_truth_id,
            now=timestamp,
        )
    except protected_capacity.ProtectedCapacityError as exc:
        raise SchedulerAmbiguity(
            f"trusted scientific provenance failed closed: {exc}"
        ) from exc


def _safety_hold_scheduler_snapshot_sha256(
    snapshot: SchedulerSnapshot,
) -> str:
    return sha256_value(
        {
            "captured_at": snapshot.captured_at,
            "squeue_ok": snapshot.squeue_ok,
            "sacct_ok": snapshot.sacct_ok,
            "errors": list(snapshot.errors),
            "jobs": [
                {
                    "job_id": row.job_id,
                    "job_name": row.job_name,
                    "state": row.state,
                    "comment": row.comment,
                    "command": row.command,
                    "source": row.source,
                    "dependency": row.dependency,
                    "partition": row.partition,
                    "qos": row.qos,
                }
                for row in snapshot.jobs
            ],
        }
    )


def _append_safety_hold_drain_event(
    state_dir: Path,
    *,
    intent: Mapping[str, Any],
    event: str,
    details: Mapping[str, Any],
    now: float,
) -> None:
    _append_jsonl(
        state_dir / SAFETY_HOLD_DRAIN_JOURNAL,
        {
            "at": utc_timestamp(now),
            "timestamp": now,
            "event": event,
            "drain_id": intent["drain_id"],
            "rollout_generation": intent["rollout_generation"],
            "hold_activation_id": intent["hold_activation_id"],
            "hold_activated_timestamp": intent["hold_activated_timestamp"],
            "details": copy.deepcopy(dict(details)),
        },
    )


def _set_safety_hold_drain_failure(
    state_dir: Path,
    *,
    message: str,
    now: float,
) -> None:
    """Persist a failed drain attempt without releasing the admission fence."""

    with control_lock(state_dir):
        control = load_control(state_dir)
        intent = control.get("safety_hold_drain_intent")
        if not isinstance(intent, dict):
            raise SchedulerAmbiguity(
                "safety-hold drain intent disappeared during failure persistence"
            )
        intent["state"] = "failed"
        intent["last_error"] = message[:2000]
        intent["updated_at"] = utc_timestamp(now)
        intent["updated_timestamp"] = now
        intent["completed_at"] = None
        intent["completed_timestamp"] = None
        _append_safety_hold_drain_event(
            state_dir,
            intent=intent,
            event="failed",
            details={"error": message[:2000]},
            now=now,
        )
        append_transition(
            state_dir,
            control,
            event="admission_safety_hold_cell_drain_failed",
            details={
                "drain_id": intent["drain_id"],
                "error": message[:2000],
                "effective_ceiling": 0,
            },
            now=now,
        )
        _save_control(state_dir, control, now=now)


def _safety_hold_drain_complete_for_current_activation(
    control: Mapping[str, Any],
) -> bool:
    hold = control.get("admission_safety_hold")
    intent = control.get("safety_hold_drain_intent")
    if not isinstance(hold, Mapping) or hold.get("active") is not True:
        return False
    activation = hold.get("activated_timestamp")
    return bool(
        isinstance(activation, (int, float))
        and not isinstance(activation, bool)
        and isinstance(intent, Mapping)
        and intent.get("state") == "complete"
        and intent.get("rollout_generation")
        == control.get("rollout_generation")
        and intent.get("hold_activation_id") == hold.get("activation_id")
        and float(intent.get("hold_activated_timestamp", -1.0))
        == float(activation)
    )


def _persist_safety_hold_drain_result(
    state_dir: Path,
    *,
    action_key: str,
    returncode: int | None,
    accepted: bool,
    evidence: str,
    stderr: str,
    now: float,
) -> None:
    with control_lock(state_dir):
        control = load_control(state_dir)
        intent = control.get("safety_hold_drain_intent")
        if not isinstance(intent, dict) or intent.get("state") != "signaling":
            raise SchedulerAmbiguity(
                "safety-hold drain intent changed during scheduler mutation"
            )
        target = intent["targets"].get(action_key)
        if not isinstance(target, dict):
            raise SchedulerAmbiguity(
                f"safety-hold drain target {action_key!r} disappeared"
            )
        result = {
            "category": target["category"],
            "job_id": target["job_id"],
            "command": list(target["command"]),
            "returncode": returncode,
            "accepted": bool(accepted),
            "evidence": evidence,
            "stderr": stderr[:1000],
            "completed_at": utc_timestamp(now),
            "completed_timestamp": now,
        }
        intent["results"][action_key] = result
        intent["updated_at"] = utc_timestamp(now)
        intent["updated_timestamp"] = now
        _append_safety_hold_drain_event(
            state_dir,
            intent=intent,
            event="action_result",
            details={"action_key": action_key, "result": result},
            now=now,
        )
        _save_control(state_dir, control, now=now)


def _ensure_safety_hold_cell_drain_locked(
    state_dir: Path,
    *,
    scheduler: SchedulerSnapshot | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    signal_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Drain the exact cell cut for an active critical hold.

    The caller owns :func:`admission_boundary_lock`.  Therefore the durable ceiling-zero
    hold, the complete scheduler cut, and every external signal form one serialized
    admission transaction.  An intent precedes scheduler reads and exact targets
    precede ``scancel``; repeating the operation after any crash is safe.
    """

    if scheduler is not None and scheduler_reader is not None:
        raise ControlError(
            "safety-hold drain accepts scheduler or scheduler_reader, not both"
        )
    timestamp = time.time() if now is None else float(now)
    current = load_control(state_dir)
    hold = current["admission_safety_hold"]
    if not hold["active"] or current["desired_state"] != "running":
        # Paused/resuming control cannot admit cells.  Their quiescence/reconciliation
        # contracts remain authoritative, while production-running holds require the
        # explicit scheduler drain below.
        return current
    activation = float(hold["activated_timestamp"])
    activation_id = str(hold["activation_id"])
    existing = current.get("safety_hold_drain_intent")
    same_activation = bool(
        isinstance(existing, dict)
        and int(existing.get("rollout_generation", -1))
        == int(current["rollout_generation"])
        and existing.get("hold_activation_id") == activation_id
        and float(existing.get("hold_activated_timestamp", -1.0)) == activation
    )
    if same_activation and existing.get("state") == "complete":
        return current

    with control_lock(state_dir):
        control = load_control(state_dir)
        hold = control["admission_safety_hold"]
        if not hold["active"] or control["desired_state"] != "running":
            return control
        activation = float(hold["activated_timestamp"])
        activation_id = str(hold["activation_id"])
        previous = control.get("safety_hold_drain_intent")
        same_activation = bool(
            isinstance(previous, dict)
            and int(previous.get("rollout_generation", -1))
            == int(control["rollout_generation"])
            and previous.get("hold_activation_id") == activation_id
            and float(previous.get("hold_activated_timestamp", -1.0))
            == activation
        )
        if same_activation and previous.get("state") == "complete":
            return control
        if same_activation:
            intent = copy.deepcopy(previous)
            intent["state"] = "reconciling"
            intent["attempt_count"] = int(intent["attempt_count"]) + 1
            intent["hold_reasons"] = sorted(hold["reasons"])
            intent["last_error"] = None
            intent["completed_at"] = None
            intent["completed_timestamp"] = None
            event = "retry_started"
        else:
            intent = {
                "protocol": SAFETY_HOLD_DRAIN_PROTOCOL,
                "drain_id": uuid.uuid4().hex,
                "rollout_generation": int(control["rollout_generation"]),
                "hold_activation_id": activation_id,
                "hold_activated_timestamp": activation,
                "hold_reasons": sorted(hold["reasons"]),
                "state": "reconciling",
                "created_at": utc_timestamp(timestamp),
                "created_timestamp": timestamp,
                "updated_at": utc_timestamp(timestamp),
                "updated_timestamp": timestamp,
                "attempt_count": 1,
                "snapshot_captured_timestamp": None,
                "snapshot_sha256": None,
                "targets": {},
                "results": {},
                "last_error": None,
                "completed_at": None,
                "completed_timestamp": None,
            }
            event = "intent_created"
        intent["updated_at"] = utc_timestamp(timestamp)
        intent["updated_timestamp"] = timestamp
        control["safety_hold_drain_intent"] = intent
        _append_safety_hold_drain_event(
            state_dir,
            intent=intent,
            event=event,
            details={
                "attempt_count": intent["attempt_count"],
                "hold_reasons": intent["hold_reasons"],
            },
            now=timestamp,
        )
        append_transition(
            state_dir,
            control,
            event="admission_safety_hold_cell_drain_started",
            details={
                "drain_id": intent["drain_id"],
                "attempt_count": intent["attempt_count"],
                "effective_ceiling": 0,
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)

    try:
        snapshot = (
            scheduler
            if scheduler is not None
            else (
                scheduler_reader()
                if scheduler_reader is not None
                else query_scheduler(tolerate_errors=True)
            )
        )
        ledger_cut = _assert_cell_submission_cut_visible(
            state_dir,
            snapshot,
            now=timestamp,
        )
        running_ids, pending_ids = _exact_live_cell_task_actions(
            state_dir,
            snapshot,
            ledger_preimage=ledger_cut[1],
        )
    except Exception as exc:
        message = f"{type(exc).__name__}: {exc}"
        _set_safety_hold_drain_failure(
            state_dir, message=message, now=timestamp
        )
        raise

    current_categories = {
        **{job_id: "cell_usr1" for job_id in running_ids},
        **{job_id: "pending_cell_cancel" for job_id in pending_ids},
    }
    with control_lock(state_dir):
        _assert_dispatcher_ledger_preimage_unchanged(
            state_dir,
            expected_raw=ledger_cut[0],
            description="safety-hold exact-target dispatcher ledger",
        )
        control = load_control(state_dir)
        intent = control.get("safety_hold_drain_intent")
        if not isinstance(intent, dict) or intent.get("state") != "reconciling":
            raise SchedulerAmbiguity(
                "safety-hold drain intent changed before exact target commit"
            )
        expected_commands = {
            "cell_usr1": ["scancel", "--batch", "--signal=USR1"],
            "pending_cell_cancel": ["scancel"],
        }
        for job_id, category in sorted(current_categories.items()):
            action_key = f"{category}:{job_id}"
            intent["targets"].setdefault(
                action_key,
                {
                    "category": category,
                    "job_id": job_id,
                    "command": [*expected_commands[category], job_id],
                },
            )
        intent["state"] = "signaling"
        intent["snapshot_captured_timestamp"] = float(snapshot.captured_at)
        intent["snapshot_sha256"] = _safety_hold_scheduler_snapshot_sha256(
            snapshot
        )
        intent["updated_at"] = utc_timestamp(timestamp)
        intent["updated_timestamp"] = timestamp
        intent["last_error"] = None
        _append_safety_hold_drain_event(
            state_dir,
            intent=intent,
            event="targets_committed",
            details={
                "snapshot_captured_timestamp": snapshot.captured_at,
                "snapshot_sha256": intent["snapshot_sha256"],
                "targets": copy.deepcopy(intent["targets"]),
            },
            now=timestamp,
        )
        append_transition(
            state_dir,
            control,
            event="admission_safety_hold_cell_drain_targets_committed",
            details={
                "drain_id": intent["drain_id"],
                "running_cell_task_ids": running_ids,
                "pending_cell_task_ids": pending_ids,
                "snapshot_sha256": intent["snapshot_sha256"],
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)

    runner = signal_runner or _run_subprocess
    intent = load_control(state_dir)["safety_hold_drain_intent"]
    for action_key, target in sorted(intent["targets"].items()):
        latest = load_control(state_dir)["safety_hold_drain_intent"]
        prior = latest["results"].get(action_key)
        if isinstance(prior, dict) and prior.get("accepted") is True:
            continue
        job_id = str(target["job_id"])
        current_category = current_categories.get(job_id)
        if current_category is None:
            _persist_safety_hold_drain_result(
                state_dir,
                action_key=action_key,
                returncode=None,
                accepted=True,
                evidence="scheduler_target_no_longer_live",
                stderr="",
                now=timestamp,
            )
            continue
        if current_category != target["category"]:
            _persist_safety_hold_drain_result(
                state_dir,
                action_key=action_key,
                returncode=None,
                accepted=True,
                evidence="scheduler_target_state_transitioned",
                stderr="",
                now=timestamp,
            )
            continue
        command = list(target["command"])
        try:
            proc = runner(command)
            returncode: int | None = int(proc.returncode)
            stderr = proc.stderr.strip()[:1000]
        except Exception as exc:
            returncode = None
            stderr = f"{type(exc).__name__}: {exc}"[:1000]
        accepted = returncode == 0
        _persist_safety_hold_drain_result(
            state_dir,
            action_key=action_key,
            returncode=returncode,
            accepted=accepted,
            evidence=(
                "scheduler_command_returncode_zero"
                if accepted
                else "scheduler_command_failed"
            ),
            stderr=stderr,
            now=timestamp,
        )
        if not accepted:
            message = (
                f"failed safety-hold drain action {command!r}: "
                f"returncode={returncode!r} stderr={stderr}"
            )
            _set_safety_hold_drain_failure(
                state_dir, message=message, now=timestamp
            )
            raise ControlError(message)

    with control_lock(state_dir):
        control = load_control(state_dir)
        intent = control.get("safety_hold_drain_intent")
        if not isinstance(intent, dict) or intent.get("state") != "signaling":
            raise SchedulerAmbiguity(
                "safety-hold drain intent changed before completion"
            )
        if (
            set(intent["results"]) != set(intent["targets"])
            or not all(row.get("accepted") is True for row in intent["results"].values())
        ):
            raise SchedulerAmbiguity(
                "safety-hold drain cannot complete without every accepted exact action"
            )
        intent["state"] = "complete"
        intent["last_error"] = None
        intent["completed_at"] = utc_timestamp(timestamp)
        intent["completed_timestamp"] = timestamp
        intent["updated_at"] = utc_timestamp(timestamp)
        intent["updated_timestamp"] = timestamp
        _append_safety_hold_drain_event(
            state_dir,
            intent=intent,
            event="complete",
            details={
                "target_count": len(intent["targets"]),
                "result_count": len(intent["results"]),
            },
            now=timestamp,
        )
        append_transition(
            state_dir,
            control,
            event="admission_safety_hold_cell_drain_complete",
            details={
                "drain_id": intent["drain_id"],
                "target_count": len(intent["targets"]),
                "effective_ceiling": 0,
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        return copy.deepcopy(control)


def _persist_drain_result(
    state_dir: Path,
    *,
    category: str,
    job_id: str,
    command: Sequence[str],
    proc: subprocess.CompletedProcess[str],
    now: float,
) -> None:
    with control_lock(state_dir):
        control = load_control(state_dir)
        intent = control.get("drain_intent")
        if not isinstance(intent, dict) or intent.get("state") != "signaling":
            raise SchedulerAmbiguity(
                "pause drain intent changed during scheduler mutation"
            )
        key = f"{category}:{job_id}"
        intent.setdefault("results", {})[key] = {
            "category": category,
            "job_id": job_id,
            "command": list(command),
            "returncode": int(proc.returncode),
            "stderr": proc.stderr.strip()[:1000],
            "completed_at": utc_timestamp(now),
            "completed_timestamp": now,
        }
        _save_control(state_dir, control, now=now)


def _pause_control_locked(
    state_dir: Path,
    *,
    drain: bool,
    scheduler: SchedulerSnapshot | None = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    if not drain:
        raise ControlError("schema-5 production may only be paused with --drain")
    timestamp = time.time() if now is None else float(now)
    successor_jobs: list[tuple[str, str]] = []
    with control_lock(state_dir):
        control = load_control(state_dir)
        changed = control["desired_state"] != "paused" or not control.get(
            "drain_requested"
        )
        control["desired_state"] = "paused"
        control["drain_requested"] = True
        _close_open_epoch(control, reason="pause", now=timestamp)
        _reset_admission_ramp(
            state_dir,
            control,
            reason="pause",
            now=timestamp,
            ceiling=24,
            clear_last_observation=True,
        )
        for role in ROLE_NAMES:
            successor = control["controllers"][role].get("successor")
            if isinstance(successor, dict) and successor.get("job_id"):
                successor_jobs.append(
                    (str(successor["job_id"]), str(successor["job_token"]))
                )
        if changed:
            append_transition(
                state_dir,
                control,
                event="pause_drain_requested",
                details={"successor_job_ids": [item[0] for item in successor_jobs]},
                now=timestamp,
            )
        _save_control(state_dir, control, now=timestamp)

    if scheduler is None:
        return load_control(state_dir)

    # Resolve every exact target before crossing the first external mutation boundary.
    ledger_cut = _assert_cell_submission_cut_visible(
        state_dir,
        scheduler,
        now=timestamp,
    )
    cell_task_ids, pending_cell_task_ids = _exact_live_cell_task_actions(
        state_dir,
        scheduler,
        ledger_preimage=ledger_cut[1],
    )
    by_id = {job.job_id: job for job in scheduler.jobs}
    verified_successors: list[str] = []
    for job_id, expected_token in successor_jobs:
        job = by_id.get(job_id)
        if job is None or not job.active:
            continue
        if job.token != expected_token:
            raise SchedulerAmbiguity(
                f"refusing to cancel successor {job_id}: scheduler token does not match"
            )
        verified_successors.append(job_id)
    with control_lock(state_dir):
        _assert_dispatcher_ledger_preimage_unchanged(
            state_dir,
            expected_raw=ledger_cut[0],
            description="pause exact-target dispatcher ledger",
        )
        control = load_control(state_dir)
        previous = control.get("drain_intent")
        previous_results = (
            copy.deepcopy(previous.get("results", {}))
            if isinstance(previous, dict)
            else {}
        )
        control["drain_intent"] = {
            "drain_id": (
                str(previous.get("drain_id"))
                if isinstance(previous, dict) and previous.get("drain_id")
                else uuid.uuid4().hex
            ),
            "state": "signaling",
            "rollout_generation": control["rollout_generation"],
            "created_at": (
                previous.get("created_at")
                if isinstance(previous, dict)
                else utc_timestamp(timestamp)
            ),
            "created_timestamp": (
                previous.get("created_timestamp")
                if isinstance(previous, dict)
                else timestamp
            ),
            "cell_task_ids": cell_task_ids,
            "pending_cell_task_ids": pending_cell_task_ids,
            "successor_job_ids": sorted(verified_successors),
            "results": previous_results,
        }
        append_transition(
            state_dir,
            control,
            event="pause_exact_targets_committed",
            details={
                "cell_task_ids": cell_task_ids,
                "pending_cell_task_ids": pending_cell_task_ids,
                "successor_job_ids": sorted(verified_successors),
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)

    runner = cancel_runner or _run_subprocess
    for category, identifiers, signal_argv in (
        # The production batch script ``exec``s Python as the Slurm batch step.  Slurm
        # excludes that step from non-KILL signals unless --batch/--full is explicit.
        ("cell_usr1", cell_task_ids, ("scancel", "--batch", "--signal=USR1")),
        ("pending_cell_cancel", pending_cell_task_ids, ("scancel",)),
        ("successor_cancel", sorted(verified_successors), ("scancel",)),
    ):
        for job_id in identifiers:
            current = load_control(state_dir)["drain_intent"]
            key = f"{category}:{job_id}"
            prior = current.get("results", {}).get(key)
            if isinstance(prior, dict) and prior.get("returncode") == 0:
                continue
            command = [*signal_argv, job_id]
            proc = runner(command)
            completed = time.time() if now is None else timestamp
            _persist_drain_result(
                state_dir,
                category=category,
                job_id=job_id,
                command=command,
                proc=proc,
                now=completed,
            )
            if proc.returncode != 0:
                raise ControlError(
                    f"failed exact pause action for {job_id}: {proc.stderr.strip()[:500]}"
                )
    with control_lock(state_dir):
        control = load_control(state_dir)
        intent = control.get("drain_intent")
        if not isinstance(intent, dict):
            raise SchedulerAmbiguity("pause drain intent disappeared")
        intent["state"] = "complete"
        intent["completed_at"] = utc_timestamp(timestamp)
        intent["completed_timestamp"] = timestamp
        append_transition(
            state_dir,
            control,
            event="pause_drain_signals_complete",
            details={
                "cell_task_count": len(cell_task_ids),
                "pending_cell_task_count": len(pending_cell_task_ids),
                "successor_count": len(verified_successors),
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
    return load_control(state_dir)


def pause_control(
    state_dir: Path,
    *,
    drain: bool,
    scheduler: SchedulerSnapshot | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Fence admission, take fresh scheduler truth, and drain without a race."""

    if scheduler is not None and scheduler_reader is not None:
        raise ControlError("pause accepts scheduler or scheduler_reader, not both")
    with admission_boundary_lock(state_dir):
        snapshot = scheduler_reader() if scheduler_reader is not None else scheduler
        return _pause_control_locked(
            state_dir,
            drain=drain,
            scheduler=snapshot,
            cancel_runner=cancel_runner,
            now=now,
        )


def _require_complete_quiescent_scheduler(
    snapshot: SchedulerSnapshot, *, operation: str
) -> None:
    if not snapshot.squeue_ok or not snapshot.sacct_ok or snapshot.errors:
        raise SchedulerAmbiguity(
            f"{operation} requires complete squeue+sacct truth: "
            + "; ".join(snapshot.errors)
        )
    active_cells = sorted(
        job.job_id for job in snapshot.jobs if job.active and _cell_job(job.job_name)
    )
    malformed_named_controllers = sorted(
        job.job_id
        for job in snapshot.jobs
        if job.active
        and _controller_job_name(job.job_name)
        and parse_job_token(job.comment) is None
    )
    if malformed_named_controllers:
        raise SchedulerAmbiguity(
            f"{operation} found controller-named jobs with missing or malformed "
            f"provenance: {malformed_named_controllers}"
        )
    active_controllers = sorted(
        job.job_id
        for job in snapshot.jobs
        if job.active
        and (
            _controller_job_name(job.job_name)
            or job.comment.startswith(TOKEN_PREFIX)
            or parse_job_token(job.comment) is not None
        )
    )
    if active_cells or active_controllers:
        raise ControlError(
            f"{operation} requires a fully drained control plane; "
            f"active_cells={active_cells}, active_controllers={active_controllers}"
        )


def effective_protected_capacity_binding(
    control: Mapping[str, Any], *, verify_files: bool = True
) -> dict[str, Any]:
    """Return the generation-scoped marker/certificate authority.

    Generation one uses the immutable initialization marker.  Every later
    generation must publish a complete replacement marker and static certificate
    in the same transaction as its effective fleet; no base-only immutable marker
    may authorize a later overlay.
    """

    immutable = control["immutable"]
    record = control.get("capacity", {}).get("current_contract")
    if record is None:
        binding = {
            "capacity_generation": int(
                control.get("capacity", {}).get("current_generation", 1)
            ),
            "path": str(
                Path(
                    str(immutable["protected_capacity_marker_path"])
                ).resolve()
            ),
            "sha256": str(
                immutable["protected_capacity_marker_sha256"]
            ),
            "marker_id": str(immutable["protected_capacity_marker_id"]),
        }
    else:
        _validate_capacity_contract_record(
            record,
            expected_generation=int(
                control["capacity"]["current_generation"]
            ),
        )
        binding = {
            "capacity_generation": int(record["capacity_generation"]),
            "path": str(
                Path(record["protected_capacity_marker_path"]).resolve()
            ),
            "sha256": str(record["protected_capacity_marker_sha256"]),
            "marker_id": str(record["protected_capacity_marker_id"]),
        }
    del verify_files
    try:
        contract = _load_protected_capacity_contract(
            control,
            path=binding["path"],
            expected_marker_id=str(binding["marker_id"]),
            expected_sha256=str(binding["sha256"]),
        )
    except protected_capacity.ProtectedCapacityError as exc:
        raise ImmutablePinError(
            f"effective protected-capacity authority drifted: {exc}"
        ) from exc
    if contract.capacity_generation != binding["capacity_generation"]:
        raise ImmutablePinError(
            "effective protected-capacity generation drifted"
        )
    binding.update(
        {
                "static_feasibility_certificate_path": str(
                    contract.static_feasibility_certificate_path
                ),
                "static_feasibility_certificate_sha256": (
                    contract.static_feasibility_certificate_sha256
                ),
                "static_feasibility_certificate_id": (
                    contract.static_feasibility_certificate_id
                ),
                "static_feasibility_configured_client_ceiling": (
                    contract.static_feasibility_configured_client_ceiling
                ),
                "static_feasibility_certified_saturation_target": (
                    contract.static_feasibility_certified_saturation_target
                ),
                "effective_fleet_contract_path": str(
                    contract.effective_fleet_contract_path
                ),
                "effective_fleet_contract_sha256": (
                    contract.effective_fleet_contract_sha256
                ),
                "base_fleet_contract_sha256": (
                    contract.base_fleet_contract_sha256
                ),
                "additive_overlay_contract_path": str(
                    contract.additive_overlay_contract_path
                ),
                "additive_overlay_contract_sha256": (
                    contract.additive_overlay_contract_sha256
                ),
        }
    )
    return binding


def load_effective_protected_capacity_contract(
    control: Mapping[str, Any], *, verify_files: bool = True
) -> protected_capacity.ProtectedCapacityContract:
    """Load the effective generation under the immutable tag/source authority.

    External production components must use this boundary instead of calling
    :func:`protected_capacity.load_contract` directly.  It joins the current
    generation record to its marker/certificate authority and then enforces the
    annotated-tag object and exact frozen dispatcher/qualification source hashes.
    """

    authority = effective_protected_capacity_binding(
        control, verify_files=verify_files
    )
    return _load_protected_capacity_contract(
        control,
        path=authority["path"],
        expected_marker_id=str(authority["marker_id"]),
        expected_sha256=str(authority["sha256"]),
    )


def effective_fleet_contract_binding(
    control: Mapping[str, Any], *, verify_files: bool = True
) -> dict[str, Any]:
    """Return the sealed operational fleet identity effective for this generation.

    The release-bundle fleet remains part of the immutable release identity.  Capacity
    overlays are separate, marker-last operational artifacts and may only increase the
    deterministic replica layout.  This distinction lets the serving capacity change
    without rewriting any scientific/run/model/environment pin.
    """

    immutable = control["immutable"]
    record = control.get("capacity", {}).get("current_contract")
    if record is None:
        authority = effective_protected_capacity_binding(
            control, verify_files=verify_files
        )
        path = Path(
            authority.get(
                "effective_fleet_contract_path",
                immutable["fleet_contract_path"],
            )
        ).resolve()
        sha256 = str(
            authority.get(
                "effective_fleet_contract_sha256",
                immutable["fleet_contract_sha256"],
            )
        )
        payload = _load_json_object(path, description="effective fleet contract")
        return {
            "capacity_generation": int(
                control.get("capacity", {}).get("current_generation", 1)
            ),
            "path": str(path),
            "sha256": sha256,
            "fleet_id": str(payload.get("fleet_id")),
            "logical_replicas": int(payload.get("logical_replica_count", -1)),
            "allocated_gpus": int(payload.get("allocated_gpu_count", -1)),
            "profile_replicas": {
                str(profile.get("serving_profile")): len(profile.get("replicas", []))
                for profile in payload.get("profiles", [])
                if isinstance(profile, dict)
            },
            "is_capacity_overlay": (
                sha256 != str(immutable["fleet_contract_sha256"])
            ),
            "protected_capacity": authority,
        }
    _validate_capacity_contract_record(
        record,
        expected_generation=int(control["capacity"]["current_generation"]),
    )
    path = Path(record["path"]).resolve()
    marker = Path(record["marker_path"]).resolve()
    if verify_files:
        if (
            path.is_symlink()
            or not path.is_file()
            or sha256_file(path) != record["sha256"]
            or marker.is_symlink()
            or not marker.is_file()
            or sha256_file(marker) != record["marker_sha256"]
        ):
            raise ImmutablePinError("effective capacity fleet artifact drifted")
        _verify_capacity_contract_marker(marker)
    authority = effective_protected_capacity_binding(
        control, verify_files=verify_files
    )
    expected_authority = {
        "capacity_generation": int(authority["capacity_generation"]),
        "path": str(
            Path(authority["effective_fleet_contract_path"]).resolve()
        ),
        "sha256": str(authority["effective_fleet_contract_sha256"]),
        "protected_capacity_marker_path": str(
            Path(authority["path"]).resolve()
        ),
        "protected_capacity_marker_sha256": str(authority["sha256"]),
        "protected_capacity_marker_id": str(authority["marker_id"]),
        "static_feasibility_certificate_path": str(
            Path(
                authority["static_feasibility_certificate_path"]
            ).resolve()
        ),
        "static_feasibility_certificate_sha256": str(
            authority["static_feasibility_certificate_sha256"]
        ),
        "static_feasibility_certificate_id": str(
            authority["static_feasibility_certificate_id"]
        ),
        "base_fleet_contract_sha256": str(
            authority["base_fleet_contract_sha256"]
        ),
        "additive_overlay_contract_path": str(
            Path(authority["additive_overlay_contract_path"]).resolve()
        ),
        "additive_overlay_contract_sha256": str(
            authority["additive_overlay_contract_sha256"]
        ),
    }
    observed_authority = {
        field: (
            str(Path(record[field]).resolve())
            if field.endswith("_path") or field == "path"
            else record[field]
        )
        for field in expected_authority
    }
    if observed_authority != expected_authority:
        raise ImmutablePinError(
            "effective fleet control record differs from its protected "
            "marker/certificate authority"
        )
    return {
        "capacity_generation": int(record["capacity_generation"]),
        "path": str(path),
        "sha256": str(record["sha256"]),
        "fleet_id": str(record["fleet_id"]),
        "logical_replicas": int(record["logical_replicas"]),
        "allocated_gpus": int(record["allocated_gpus"]),
        "profile_replicas": copy.deepcopy(record["profile_replicas"]),
        "is_capacity_overlay": True,
        "protected_capacity": authority,
    }


def validate_capacity_readiness_pending_state(
    control: Mapping[str, Any],
    *,
    require_fleet_gate: bool = False,
    verify_files: bool = True,
) -> Mapping[str, Any]:
    """Validate the sole drained state allowed to build post-capacity gates."""

    capacity = control.get("capacity")
    active = (
        capacity.get("active_transition")
        if isinstance(capacity, Mapping)
        else None
    )
    hold = control.get("admission_safety_hold")
    if (
        control.get("desired_state") != "paused"
        or control.get("drain_requested") is not True
        or not isinstance(active, Mapping)
        or active.get("phase") != "readiness_pending"
        or not isinstance(hold, Mapping)
        or hold.get("active") is not True
        or hold.get("mode") != "operator"
    ):
        raise ControlError(
            "draining control is not an exact capacity readiness-pending state"
        )
    transition_id = active.get("transition_id")
    capacity_reason = f"capacity-transition:{transition_id}"
    old_ids = active.get("old_fleet_job_ids")
    new_contract = active.get("new_contract")
    if (
        not isinstance(transition_id, str)
        or not transition_id
        or capacity_reason not in hold.get("reasons", [])
        or not isinstance(old_ids, list)
        or not all(isinstance(job_id, str) and job_id.isdigit() for job_id in old_ids)
        or len(old_ids) != len(set(old_ids))
        or active.get("last_retirement_error") is not None
        or not isinstance(active.get("published_timestamp"), (int, float))
        or active.get("last_fleet_launch_error") is not None
        or not isinstance(
            active.get("fleet_launch_completed_timestamp"), (int, float)
        )
        or not isinstance(new_contract, Mapping)
        or active.get("to_generation") != capacity.get("current_generation")
        or capacity.get("current_contract") != new_contract
    ):
        raise ControlError(
            "capacity readiness-pending state has incomplete retirement or fleet proof"
        )
    binding = effective_fleet_contract_binding(
        control, verify_files=verify_files
    )
    if (
        binding["capacity_generation"] != active["to_generation"]
        or binding["sha256"] != new_contract.get("sha256")
        or Path(str(binding["path"])).resolve()
        != Path(str(new_contract.get("path", ""))).resolve()
    ):
        raise ControlError("capacity readiness-pending fleet binding drifted")
    if require_fleet_gate:
        fleet_gate = control.get("readiness", {}).get("fleet")
        if (
            not isinstance(fleet_gate, Mapping)
            or fleet_gate.get("passed") is not True
            or fleet_gate.get("capacity_generation") != active["to_generation"]
        ):
            raise ControlError(
                "capacity smoke execution requires the fresh generation fleet gate"
            )
    return active


def load_effective_fleet_contract(
    control: Mapping[str, Any], *, verify_files: bool = True
) -> FrozenFleetContract:
    binding = effective_fleet_contract_binding(control, verify_files=verify_files)
    immutable = control["immutable"]
    try:
        models = load_model_contracts(
            immutable["model_contract_path"],
            expected_sha256=immutable["model_contract_sha256"],
        )
        return load_fleet_contract(
            binding["path"],
            model_contracts=models,
            expected_sha256=binding["sha256"],
            allow_capacity_layout=True,
        )
    except (FleetContractError, ModelContractError, OSError, ValueError) as exc:
        raise ImmutablePinError(
            f"effective capacity fleet contract is invalid: {exc}"
        ) from exc


def _trusted_generation_control_evidence(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    fleet_binding: Mapping[str, Any],
    target_rollout_generation: int,
    now: float,
) -> GenerationEvidence:
    """Seal the exact control facts that authorize one catalog generation."""

    capacity_generation = int(fleet_binding["capacity_generation"])
    history = [
        copy.deepcopy(record)
        for record in control.get("capacity", {}).get("history", [])
        if isinstance(record, Mapping)
        and record.get("phase") == "completed"
        and record.get("to_generation") == capacity_generation
    ]
    if capacity_generation == 1:
        if history:
            raise ControlError("capacity generation one has transition history")
        capacity_transition = None
    else:
        if len(history) != 1:
            raise ControlError(
                "trusted capacity generation lacks one completed predecessor transition"
            )
        transition = history[0]
        if (
            transition.get("from_generation") != capacity_generation - 1
            or transition.get("to_generation") != capacity_generation
        ):
            raise ControlError("trusted capacity transition is not chain-continuous")
        new_contract = transition.get("new_contract")
        if (
            not isinstance(new_contract, Mapping)
            or new_contract.get("sha256") != fleet_binding["sha256"]
            or _SHA256_RE.fullmatch(
                str(transition.get("archive_sha256", ""))
            )
            is None
        ):
            raise ControlError(
                "trusted capacity transition lacks its sealed fleet/archive identity"
            )
        capacity_transition = {
            "transition_id": transition.get("transition_id"),
            "from_generation": transition.get("from_generation"),
            "to_generation": transition.get("to_generation"),
            "fleet_contract_sha256": new_contract.get("sha256"),
            "capacity_contract_marker_sha256": new_contract.get(
                "marker_sha256"
            ),
            "archive_path": transition.get("archive_path"),
            "archive_sha256": transition.get("archive_sha256"),
        }

    fleet_gate = control.get("readiness", {}).get("fleet")
    if (
        not isinstance(fleet_gate, Mapping)
        or fleet_gate.get("passed") is not True
        or not isinstance(fleet_gate.get("evidence"), str)
        or _SHA256_RE.fullmatch(str(fleet_gate.get("sha256", ""))) is None
    ):
        raise ReadinessError(
            "trusted-generation publication requires the fleet readiness gate"
        )
    _validate_attestation(
        control,
        "fleet",
        Path(str(fleet_gate["evidence"])).resolve(),
        str(fleet_gate["sha256"]),
        now=None,
    )
    scheduler_binding = fleet_scheduler_policy_binding(
        control, require_attested=True
    )
    assert scheduler_binding is not None
    if capacity_generation > 1 and (
        fleet_gate.get("capacity_generation") != capacity_generation
    ):
        raise ReadinessError(
            "capacity-transition catalog requires generation-bound fleet readiness"
        )

    runtime_record = control.get(RUNTIME_ATTESTATION_STATE_KEY)
    runtime_binding = None
    if (
        isinstance(runtime_record, Mapping)
        and runtime_record.get("generation") == target_rollout_generation
    ):
        runtime_path = Path(str(runtime_record.get("path", ""))).resolve()
        if (
            runtime_path.is_symlink()
            or not runtime_path.is_file()
            or sha256_file(runtime_path) != runtime_record.get("sha256")
        ):
            raise ImmutablePinError(
                "trusted-generation runtime attestation drifted"
            )
        runtime_binding = {
            "path": str(runtime_path),
            "sha256": str(runtime_record["sha256"]),
            "attestation_id": runtime_record.get("attestation_id"),
        }
    snapshot_record = control.get(SNAPSHOT_ATTESTATION_STATE_KEY)
    snapshot_binding = None
    if (
        isinstance(snapshot_record, Mapping)
        and snapshot_record.get("generation") == target_rollout_generation
    ):
        snapshot_path = Path(str(snapshot_record.get("path", ""))).resolve()
        if (
            snapshot_path.is_symlink()
            or not snapshot_path.is_file()
            or sha256_file(snapshot_path) != snapshot_record.get("sha256")
        ):
            raise ReadinessError(
                "trusted-generation snapshot integrity seal drifted"
            )
        snapshot_binding = {
            "path": str(snapshot_path),
            "sha256": str(snapshot_record["sha256"]),
            "seal_id": snapshot_record.get("seal_id"),
        }

    record: dict[str, Any] = {
        "schema_version": 1,
        "kind": "schema5_trusted_generation_control_evidence",
        "immutable_sha256": control["immutable_sha256"],
        "release_id": control["immutable"]["release_id"],
        "release_fleet_contract_sha256": control["immutable"][
            "fleet_contract_sha256"
        ],
        "fleet_contract_path": str(Path(str(fleet_binding["path"])).resolve()),
        "fleet_contract_sha256": fleet_binding["sha256"],
        "capacity_generation": capacity_generation,
        "rollout_generation": target_rollout_generation,
        "fleet_readiness": {
            "path": str(Path(str(fleet_gate["evidence"])).resolve()),
            "sha256": fleet_gate["sha256"],
            "attested_timestamp": fleet_gate.get("attested_timestamp"),
            "capacity_generation": fleet_gate.get("capacity_generation"),
            "scheduler_safety_evidence_id": scheduler_binding[
                "scheduler_safety_evidence_id"
            ],
            "scheduler_safety_policy_id": scheduler_binding[
                "scheduler_safety_policy_id"
            ],
            "scheduler_safety_policy_contract_id": scheduler_binding[
                "scheduler_safety_policy_contract_id"
            ],
            "transport_uncertainty_binding_sha256": scheduler_binding[
                "transport_uncertainty_binding_sha256"
            ],
            "transport_censor_protocol_version": scheduler_binding[
                "transport_censor_protocol_version"
            ],
            "transport_censor_protocol_hash": scheduler_binding[
                "transport_censor_protocol_hash"
            ],
        },
        "runtime_integrity": runtime_binding,
        "snapshot_integrity": snapshot_binding,
        "capacity_transition": capacity_transition,
        "captured_timestamp": float(now),
    }
    record["evidence_id"] = sha256_value(record)
    evidence_root = (
        state_dir
        / TRUSTED_GENERATION_EVIDENCE_DIRNAME
        / f"capacity-g{capacity_generation:06d}"
        / f"rollout-g{target_rollout_generation:06d}"
    )
    evidence_path = evidence_root / "CONTROL_GENERATION_EVIDENCE.json"
    if evidence_path.exists() or evidence_path.is_symlink():
        if evidence_path.is_symlink() or not evidence_path.is_file():
            raise ControlError("trusted-generation control evidence is unsafe")
        existing = _load_json_object(
            evidence_path, description="trusted-generation control evidence"
        )
        # Runtime/snapshot attestations may be added by the resume transaction after
        # the initial paused readiness proof.  They cannot revoke or alter the stable
        # generation identity; the first marker-last proof remains authoritative.
        stable_fields = {
            "schema_version",
            "kind",
            "immutable_sha256",
            "release_id",
            "release_fleet_contract_sha256",
            "fleet_contract_path",
            "fleet_contract_sha256",
            "capacity_generation",
            "rollout_generation",
            "fleet_readiness",
            "capacity_transition",
        }
        if (
            any(existing.get(field) != record.get(field) for field in stable_fields)
            or evidence_path.stat().st_mode & 0o222
            or evidence_path.stat().st_nlink != 1
        ):
            raise ControlError(
                "trusted-generation control evidence conflicts with sealed history"
            )
    else:
        evidence_root.mkdir(parents=True, exist_ok=True)
        _atomic_publish_readonly_json(evidence_path, record)
    return GenerationEvidence(
        kind="control_generation",
        path=evidence_path.resolve(),
        sha256=sha256_file(evidence_path),
    )


def refresh_trusted_generation_catalog(
    state_dir: Path,
    *,
    target_rollout_generation: int | None = None,
    now: float | None = None,
) -> TrustedGenerationCatalog:
    """Catalog every sealed endpoint for the current/next authorized generation.

    The endpoint-history collector proves process-level scheduler and serving
    provenance.  This control-plane layer additionally proves the endpoint belongs to
    the effective frozen fleet and binds the generation to readiness/capacity evidence.
    """

    state_dir = state_dir.expanduser().resolve()
    timestamp = time.time() if now is None else float(now)
    current = load_control(state_dir, verify_files=True)
    completed_drain = (
        current.get("drain_requested") is True
        and isinstance(current.get("drain_intent"), Mapping)
        and current["drain_intent"].get("state") == "complete"
    )
    paused_next_generation = (
        current["desired_state"] == "paused"
        and (
            not current.get("drain_requested", False)
            or completed_drain
        )
    )
    if target_rollout_generation is None:
        target_rollout_generation = int(current["rollout_generation"])
        if paused_next_generation:
            target_rollout_generation += 1
    target_rollout_generation = int(target_rollout_generation)
    if target_rollout_generation < 1:
        raise ControlError("trusted-generation rollout must be positive")
    allowed_rollouts = {int(current["rollout_generation"])}
    if paused_next_generation:
        allowed_rollouts.add(int(current["rollout_generation"]) + 1)
    if target_rollout_generation not in allowed_rollouts:
        raise ControlError(
            "trusted-generation target is not the current or fenced next rollout"
        )

    binding = effective_fleet_contract_binding(current, verify_files=True)
    effective_fleet = load_effective_fleet_contract(current, verify_files=True)
    models = load_model_contracts(
        current["immutable"]["model_contract_path"],
        expected_sha256=current["immutable"]["model_contract_sha256"],
    )
    pool = Path(current["immutable"]["server_pool_root"]).resolve()
    try:
        endpoint_catalog = collect_endpoint_history_catalog(pool)
    except (OSError, ValueError) as exc:
        raise ControlError(f"endpoint-history catalog is untrusted: {exc}") from exc
    target_records = [
        record
        for record in endpoint_catalog.records
        if record.allowed_generation_tuple[:4]
        == (
            current["immutable"]["fleet_contract_sha256"],
            binding["sha256"],
            int(binding["capacity_generation"]),
            target_rollout_generation,
        )
    ]
    if not target_records:
        raise ReadinessError(
            "trusted-generation publication found no sealed endpoint for its generation"
        )
    for record in target_records:
        entry = record.server_entry
        try:
            replica = effective_fleet.for_replica(
                str(entry.serving_profile), int(entry.replica_index)
            )
            identity = models.for_size(entry.model_size)
        except (FleetContractError, ModelContractError, TypeError, ValueError) as exc:
            raise ControlError(
                f"endpoint history is outside the effective fleet: {exc}"
            ) from exc
        if (
            entry.server_pool_id != server_pool_id(pool)
            or entry.server_pool_id != effective_fleet.fleet_id
            or entry.replica_id != replica.replica_id
            or entry.model_size != replica.model_size
            or entry.release_id != current["immutable"]["release_id"]
            or entry.environment_hash
            != current["immutable"]["serving_environment_sha256"]
            or entry.model_contract_sha256
            != current["immutable"]["model_contract_sha256"]
            or entry.hf_id != identity.hf_id
            or entry.model_revision != identity.model_revision
            or entry.tokenizer_id != identity.tokenizer_id
            or entry.tokenizer_revision != identity.tokenizer_revision
        ):
            raise ControlError(
                "endpoint-history record differs from frozen fleet/model provenance"
            )

    control_evidence = _trusted_generation_control_evidence(
        state_dir,
        current,
        fleet_binding=binding,
        target_rollout_generation=target_rollout_generation,
        now=timestamp,
    )
    fleet_gate = current["readiness"]["fleet"]
    evidence = [
        control_evidence,
        GenerationEvidence(
            kind="fleet_readiness",
            path=Path(str(fleet_gate["evidence"])).resolve(),
            sha256=str(fleet_gate["sha256"]),
        ),
        GenerationEvidence(
            kind="effective_fleet_contract",
            path=Path(str(binding["path"])).resolve(),
            sha256=str(binding["sha256"]),
        ),
    ]
    capacity_record = current.get("capacity", {}).get("current_contract")
    if isinstance(capacity_record, Mapping):
        evidence.append(
            GenerationEvidence(
                kind="capacity_contract_marker",
                path=Path(str(capacity_record["marker_path"])).resolve(),
                sha256=str(capacity_record["marker_sha256"]),
            )
        )
    try:
        return publish_trusted_generation_catalog(
            state_dir,
            server_pool_root=pool,
            server_pool_id=effective_fleet.fleet_id,
            endpoint_records=endpoint_catalog.records,
            release_fleet_contract_sha256=current["immutable"][
                "fleet_contract_sha256"
            ],
            fleet_contract_sha256=str(binding["sha256"]),
            capacity_generation=int(binding["capacity_generation"]),
            rollout_generation=target_rollout_generation,
            generation_evidence=evidence,
            now=timestamp,
        )
    except GenerationCatalogError as exc:
        raise ControlError(f"trusted-generation catalog failed: {exc}") from exc


def load_trusted_generation_catalog(
    state_dir: Path,
    *,
    server_pool_root: Path | None = None,
) -> TrustedGenerationCatalog:
    """Load the current immutable catalog through a control-bound pool root."""

    current = load_control(state_dir, verify_files=True)
    expected_pool = Path(current["immutable"]["server_pool_root"]).resolve()
    if server_pool_root is not None and server_pool_root.resolve() != expected_pool:
        raise ControlError("trusted-generation server-pool override drifted")
    try:
        catalog = load_current_trusted_generation_catalog(
            state_dir,
            server_pool_root=expected_pool,
            required=True,
        )
    except GenerationCatalogError as exc:
        raise ControlError(f"trusted-generation catalog is invalid: {exc}") from exc
    assert catalog is not None
    return catalog


def _resume_catalog_pin(
    catalog: TrustedGenerationCatalog,
    *,
    release_fleet_contract_sha256: str,
    fleet_contract_sha256: str,
    capacity_generation: int,
    rollout_generation: int,
) -> dict[str, Any]:
    return {
        **_trusted_generation_catalog_binding(catalog),
        "release_fleet_contract_sha256": release_fleet_contract_sha256,
        "fleet_contract_sha256": fleet_contract_sha256,
        "capacity_generation": capacity_generation,
        "rollout_generation": rollout_generation,
    }


def _validate_resume_catalog_authority(
    state_dir: Path,
    current: Mapping[str, Any],
    *,
    target_rollout_generation: int,
    catalog: TrustedGenerationCatalog,
) -> dict[str, Any]:
    """Prove a catalog covers the whole effective fleet and latest readiness bytes."""

    fleet_binding = effective_fleet_contract_binding(
        current, verify_files=True
    )
    release_fleet = str(current["immutable"]["fleet_contract_sha256"])
    effective_fleet_sha256 = str(fleet_binding["sha256"])
    capacity_generation = int(fleet_binding["capacity_generation"])
    expected_prefix = (
        release_fleet,
        effective_fleet_sha256,
        capacity_generation,
        int(target_rollout_generation),
    )
    generations = [
        row
        for row in catalog.generations
        if (
            row.get("release_fleet_contract_sha256"),
            row.get("fleet_contract_sha256"),
            row.get("capacity_generation"),
            row.get("rollout_generation"),
        )
        == expected_prefix
    ]
    if len(generations) != 1:
        raise ReadinessError(
            "trusted-generation catalog lacks the exact resume generation"
        )
    evidence = generations[0].get("evidence")
    if not isinstance(evidence, list):
        raise ReadinessError(
            "trusted-generation resume proof has malformed evidence"
        )
    evidence_hashes = {
        (str(row.get("kind")), str(row.get("sha256")))
        for row in evidence
        if isinstance(row, Mapping)
    }
    fleet_gate = current.get("readiness", {}).get("fleet")
    required_evidence = {
        ("control_generation", next(
            (
                str(row.get("sha256"))
                for row in evidence
                if isinstance(row, Mapping)
                and row.get("kind") == "control_generation"
            ),
            "",
        )),
        (
            "fleet_readiness",
            str(
                fleet_gate.get("sha256")
                if isinstance(fleet_gate, Mapping)
                else ""
            ),
        ),
        ("effective_fleet_contract", effective_fleet_sha256),
    }
    capacity_contract = current.get("capacity", {}).get("current_contract")
    if isinstance(capacity_contract, Mapping):
        marker_sha256 = str(capacity_contract.get("marker_sha256", ""))
        if _SHA256_RE.fullmatch(marker_sha256) is None:
            raise ReadinessError(
                "effective capacity contract lacks its immutable marker hash"
            )
        required_evidence.add(
            ("capacity_contract_marker", marker_sha256)
        )
    if (
        ("control_generation", "") in required_evidence
        or not required_evidence.issubset(evidence_hashes)
    ):
        raise ReadinessError(
            "trusted-generation catalog does not bind current fleet readiness"
        )
    target_tuples = {
        identity
        for identity in catalog.allowed_generation_tuples
        if identity[:4] == expected_prefix
    }
    if not target_tuples:
        raise ReadinessError(
            "trusted-generation catalog contains no endpoint for resume"
        )
    pool = Path(str(current["immutable"]["server_pool_root"])).resolve()
    try:
        endpoint_history = collect_endpoint_history_catalog(pool)
        effective_fleet = load_effective_fleet_contract(
            current, verify_files=True
        )
    except (OSError, ValueError, ImmutablePinError) as exc:
        raise ReadinessError(
            f"cannot prove resume endpoint-history coverage: {exc}"
        ) from exc
    target_records = [
        record
        for record in endpoint_history.records
        if record.allowed_generation_tuple[:4] == expected_prefix
    ]
    history_tuples = {
        record.allowed_generation_tuple for record in target_records
    }
    expected_replicas = {
        str(replica.replica_id) for replica in effective_fleet.replicas
    }
    observed_replicas = {
        str(record.server_entry.replica_id) for record in target_records
    }
    if (
        target_tuples != history_tuples
        or observed_replicas != expected_replicas
    ):
        raise ReadinessError(
            "trusted-generation catalog does not cover every exact fleet endpoint"
        )
    return _resume_catalog_pin(
        catalog,
        release_fleet_contract_sha256=release_fleet,
        fleet_contract_sha256=effective_fleet_sha256,
        capacity_generation=capacity_generation,
        rollout_generation=target_rollout_generation,
    )


def _load_resume_catalog_pin(
    state_dir: Path,
    current: Mapping[str, Any],
    *,
    target_rollout_generation: int,
) -> dict[str, Any]:
    try:
        catalog = load_current_trusted_generation_catalog(
            state_dir,
            server_pool_root=Path(
                str(current["immutable"]["server_pool_root"])
            ).resolve(),
            required=True,
        )
    except GenerationCatalogError as exc:
        raise ReadinessError(
            f"resume trusted-generation catalog is invalid: {exc}"
        ) from exc
    assert catalog is not None
    return _validate_resume_catalog_authority(
        state_dir,
        current,
        target_rollout_generation=target_rollout_generation,
        catalog=catalog,
    )


def _validate_pinned_resume_catalog(
    state_dir: Path,
    current: Mapping[str, Any],
) -> dict[str, Any]:
    intent = current.get("resume_intent")
    pin = (
        intent.get("trusted_generation_catalog")
        if isinstance(intent, Mapping)
        else None
    )
    if not isinstance(pin, Mapping):
        raise ReadinessError(
            "resume transaction lacks a trusted-generation catalog pin"
        )
    marker = Path(str(pin.get("marker_path", ""))).resolve()
    try:
        catalog = validate_trusted_generation_catalog(
            marker,
            server_pool_root=Path(
                str(current["immutable"]["server_pool_root"])
            ).resolve(),
        )
    except GenerationCatalogError as exc:
        raise ReadinessError(
            f"pinned resume trusted-generation catalog is invalid: {exc}"
        ) from exc
    expected = _validate_resume_catalog_authority(
        state_dir,
        current,
        target_rollout_generation=int(current["rollout_generation"]),
        catalog=catalog,
    )
    if dict(pin) != expected:
        raise ReadinessError(
            "resume trusted-generation catalog pin drifted"
        )
    _validate_initial_qualification_generation(
        current,
        resume_catalog_pin=expected,
        target_rollout_generation=int(current["rollout_generation"]),
    )
    return expected


def effective_fleet_supervisor_command(
    control: Mapping[str, Any],
) -> list[str]:
    """Rebind only the contract flags in the frozen supervisor command."""

    command = list(control["immutable"]["fleet_supervisor_command"])
    binding = effective_fleet_contract_binding(control, verify_files=True)
    authority = effective_protected_capacity_binding(
        control, verify_files=True
    )
    replacements = {
        "--fleet-contract": str(binding["path"]),
        "--fleet-contract-sha256": str(binding["sha256"]),
        "--protected-capacity-marker": str(authority["path"]),
        "--protected-capacity-marker-sha256": str(authority["sha256"]),
        "--protected-capacity-marker-id": str(authority["marker_id"]),
    }
    for flag, replacement in replacements.items():
        try:
            index = command.index(flag)
        except ValueError as exc:
            raise ImmutablePinError(
                f"frozen fleet supervisor command lacks {flag}"
            ) from exc
        if index + 1 >= len(command):
            raise ImmutablePinError(
                f"frozen fleet supervisor command has no value for {flag}"
            )
        command[index + 1] = replacement
    return command


def _capacity_profile_counts(fleet: FrozenFleetContract) -> dict[str, int]:
    return {
        profile: len(fleet.by_profile[profile])
        for profile in sorted(fleet.by_profile)
    }


def _verify_capacity_contract_marker(marker_path: Path) -> dict[str, Any]:
    marker = _load_json_object(
        marker_path, description="capacity contract completion marker"
    )
    required = {
        "schema_version",
        "kind",
        "complete",
        "transition_id",
        "capacity_generation",
        "release_id",
        "immutable_sha256",
        "model_contract_sha256",
        "contract_path",
        "contract_sha256",
        "checksum_path",
        "checksum_sha256",
        "logical_replicas",
        "allocated_gpus",
        "profile_replicas",
        "created_at",
        "created_timestamp",
    }
    if (
        set(marker) != required
        or marker.get("schema_version") != 1
        or marker.get("kind") != "schema5_capacity_contract"
        or marker.get("complete") is not True
        or marker.get("release_id") != PRODUCTION_RELEASE_ID
        or _SHA256_RE.fullmatch(str(marker.get("immutable_sha256", ""))) is None
        or _SHA256_RE.fullmatch(str(marker.get("model_contract_sha256", ""))) is None
        or _SHA256_RE.fullmatch(str(marker.get("contract_sha256", ""))) is None
        or _SHA256_RE.fullmatch(str(marker.get("checksum_sha256", ""))) is None
    ):
        raise ImmutablePinError("capacity contract marker is malformed")
    contract_path = Path(str(marker["contract_path"])).resolve()
    checksum_path = Path(str(marker["checksum_path"])).resolve()
    if (
        marker_path.is_symlink()
        or not marker_path.is_file()
        or marker_path.stat().st_nlink != 1
        or marker_path.stat().st_mode & 0o222
        or contract_path.is_symlink()
        or not contract_path.is_file()
        or contract_path.stat().st_nlink != 1
        or contract_path.stat().st_mode & 0o222
        or sha256_file(contract_path) != marker["contract_sha256"]
        or checksum_path.is_symlink()
        or not checksum_path.is_file()
        or checksum_path.stat().st_nlink != 1
        or checksum_path.stat().st_mode & 0o222
        or sha256_file(checksum_path) != marker["checksum_sha256"]
        or checksum_path.read_text(encoding="utf-8").strip().split()
        != [marker["contract_sha256"], contract_path.name]
    ):
        raise ImmutablePinError("sealed capacity contract bytes drifted")
    return marker


def _seal_capacity_contract(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    transition_id: str,
    to_generation: int,
    source_path: Path,
    expected_sha256: str,
    protected_capacity_authority: Mapping[str, Any],
    now: float,
) -> dict[str, Any]:
    """Archive a fleet and bind its exact generation-scoped safety authority."""

    source = source_path.expanduser().resolve()
    if (
        source.is_symlink()
        or not source.is_file()
        or _SHA256_RE.fullmatch(expected_sha256) is None
        or sha256_file(source) != expected_sha256
    ):
        raise ImmutablePinError(
            "capacity contract is missing, symlinked, or differs from --sha256"
        )
    source_sidecar = source.with_suffix(".sha256")
    if (
        source_sidecar.is_symlink()
        or not source_sidecar.is_file()
        or source_sidecar.read_text(encoding="utf-8").strip().split()
        != [expected_sha256, source.name]
    ):
        raise ImmutablePinError(
            "capacity contract checksum sidecar does not bind the supplied file"
        )
    current_binding = effective_fleet_contract_binding(control, verify_files=True)
    _assert_additive_capacity_contract(
        Path(current_binding["path"]).resolve(), source
    )
    immutable = control["immutable"]
    try:
        models = load_model_contracts(
            immutable["model_contract_path"],
            expected_sha256=immutable["model_contract_sha256"],
        )
        fleet = load_fleet_contract(
            source,
            model_contracts=models,
            expected_sha256=expected_sha256,
            allow_capacity_layout=True,
        )
    except (FleetContractError, ModelContractError, OSError, ValueError) as exc:
        raise ImmutablePinError(f"capacity contract validation failed: {exc}") from exc
    current = load_effective_fleet_contract(control)
    current_counts = _capacity_profile_counts(current)
    proposed_counts = _capacity_profile_counts(fleet)
    if any(
        proposed_counts[profile] < current_counts[profile]
        for profile in current_counts
    ):
        raise ImmutablePinError(
            "capacity transition may not remove an existing profile replica"
        )
    if proposed_counts == current_counts:
        raise ImmutablePinError("capacity contract does not change the fleet layout")
    required_authority = {
        "protected_capacity_marker_path",
        "protected_capacity_marker_sha256",
        "protected_capacity_marker_id",
        "static_feasibility_certificate_path",
        "static_feasibility_certificate_sha256",
        "static_feasibility_certificate_id",
        "base_fleet_contract_sha256",
        "additive_overlay_contract_path",
        "additive_overlay_contract_sha256",
    }
    if not isinstance(protected_capacity_authority, Mapping) or set(
        protected_capacity_authority
    ) != required_authority:
        raise ImmutablePinError(
            "capacity transition safety authority has the wrong fields"
        )
    try:
        capacity_contract = _load_protected_capacity_contract(
            control,
            path=protected_capacity_authority[
                "protected_capacity_marker_path"
            ],
            expected_marker_id=str(
                protected_capacity_authority[
                    "protected_capacity_marker_id"
                ]
            ),
            expected_sha256=str(
                protected_capacity_authority[
                    "protected_capacity_marker_sha256"
                ]
            ),
        )
        protected_capacity.authorize_fleet(fleet, capacity_contract)
    except protected_capacity.ProtectedCapacityError as exc:
        raise ImmutablePinError(
            f"capacity transition safety authority drifted: {exc}"
        ) from exc
    if (
        capacity_contract.capacity_generation != to_generation
        or capacity_contract.effective_fleet_contract_path != source
        or capacity_contract.effective_fleet_contract_sha256
        != expected_sha256
        or {
            "protected_capacity_marker_path": str(capacity_contract.path),
            "protected_capacity_marker_sha256": capacity_contract.sha256,
            "protected_capacity_marker_id": capacity_contract.marker_id,
            "static_feasibility_certificate_path": str(
                capacity_contract.static_feasibility_certificate_path
            ),
            "static_feasibility_certificate_sha256": (
                capacity_contract.static_feasibility_certificate_sha256
            ),
            "static_feasibility_certificate_id": (
                capacity_contract.static_feasibility_certificate_id
            ),
            "base_fleet_contract_sha256": (
                capacity_contract.base_fleet_contract_sha256
            ),
            "additive_overlay_contract_path": str(
                capacity_contract.additive_overlay_contract_path
            ),
            "additive_overlay_contract_sha256": (
                capacity_contract.additive_overlay_contract_sha256
            ),
        }
        != dict(protected_capacity_authority)
    ):
        raise ImmutablePinError(
            "capacity transition marker/certificate generation binding drifted"
        )

    def record(marker_path: Path) -> dict[str, Any]:
        return {
            "capacity_generation": to_generation,
            # The protected marker binds this staged immutable path exactly.
            # The independent copy below is audit evidence, not runtime authority.
            "path": str(source),
            "sha256": expected_sha256,
            "marker_path": str(marker_path.resolve()),
            "marker_sha256": sha256_file(marker_path),
            **dict(protected_capacity_authority),
            "fleet_id": fleet.fleet_id,
            "logical_replicas": len(fleet.replicas),
            "allocated_gpus": sum(
                item.gpus_per_replica for item in fleet.replicas
            ),
            "profile_replicas": proposed_counts,
            "activated_at": utc_timestamp(now),
            "activated_timestamp": now,
        }

    root = state_dir / "capacity-transitions" / transition_id / "contract"
    marker_path = root / CAPACITY_CONTRACT_COMPLETE
    if marker_path.exists():
        marker = _verify_capacity_contract_marker(marker_path)
        if (
            marker["contract_sha256"] != expected_sha256
            or marker["capacity_generation"] != to_generation
            or marker["immutable_sha256"] != control["immutable_sha256"]
        ):
            raise ImmutablePinError(
                "existing capacity contract marker conflicts with this transition"
            )
        return record(marker_path)
    root.mkdir(parents=True, exist_ok=True)
    intent_path = root / "CONTRACT_CAPTURE_INTENT.json"
    intent = {
        "schema_version": 1,
        "kind": "schema5_capacity_contract_capture_intent",
        "transition_id": transition_id,
        "capacity_generation": to_generation,
        "source_path": str(source),
        "source_sha256": expected_sha256,
        "protected_capacity_marker_sha256": (
            protected_capacity_authority[
                "protected_capacity_marker_sha256"
            ]
        ),
        "static_feasibility_certificate_sha256": (
            protected_capacity_authority[
                "static_feasibility_certificate_sha256"
            ]
        ),
        "immutable_sha256": control["immutable_sha256"],
    }
    if intent_path.exists() or intent_path.is_symlink():
        if _load_json_object(intent_path, description="capacity contract intent") != intent:
            raise ImmutablePinError("capacity contract capture intent conflicts")
    else:
        _atomic_write_json(intent_path, intent)
    target = root / "fleet_contract.json"
    target_sidecar = target.with_suffix(".sha256")
    if target.exists() or target.is_symlink():
        if (
            target.is_symlink()
            or not target.is_file()
            or target.stat().st_ino == source.stat().st_ino
            or sha256_file(target) != expected_sha256
        ):
            raise ImmutablePinError(
                "partial capacity contract copy is not independent and exact"
            )
    else:
        shutil.copyfile(source, target)
    if target.stat().st_ino == source.stat().st_ino or sha256_file(target) != expected_sha256:
        raise ImmutablePinError("capacity contract copy is not independent and exact")
    expected_sidecar = f"{expected_sha256}  {target.name}\n"
    if target_sidecar.exists() or target_sidecar.is_symlink():
        if (
            target_sidecar.is_symlink()
            or not target_sidecar.is_file()
            or target_sidecar.read_text(encoding="utf-8") != expected_sidecar
        ):
            raise ImmutablePinError(
                "partial capacity contract checksum sidecar conflicts"
            )
    else:
        io.atomic_write_text(target_sidecar, expected_sidecar)
    marker = {
        "schema_version": 1,
        "kind": "schema5_capacity_contract",
        "complete": True,
        "transition_id": transition_id,
        "capacity_generation": to_generation,
        "release_id": immutable["release_id"],
        "immutable_sha256": control["immutable_sha256"],
        "model_contract_sha256": immutable["model_contract_sha256"],
        "contract_path": str(target.resolve()),
        "contract_sha256": expected_sha256,
        "checksum_path": str(target_sidecar.resolve()),
        "checksum_sha256": sha256_file(target_sidecar),
        "logical_replicas": len(fleet.replicas),
        "allocated_gpus": sum(item.gpus_per_replica for item in fleet.replicas),
        "profile_replicas": proposed_counts,
        "created_at": utc_timestamp(now),
        "created_timestamp": now,
    }
    for path in (intent_path, target, target_sidecar):
        path.chmod(0o444)
    _atomic_publish_readonly_json(marker_path, marker)
    root.chmod(0o555)
    _verify_capacity_contract_marker(marker_path)
    return record(marker_path)


def _fleet_contract_reconciliation_identity(
    control: Mapping[str, Any],
) -> tuple[str, dict[str, str], dict[str, str], dict[str, str]]:
    binding = effective_fleet_contract_binding(control, verify_files=True)
    contract = _load_json_object(
        Path(binding["path"]), description="effective fleet contract"
    )
    pool_id = contract.get("fleet_id")
    profiles = contract.get("profiles")
    if pool_id != "schema5-v1" or not isinstance(profiles, list):
        raise ImmutablePinError("fleet contract lacks its reconciliation identity")
    replica_profiles: dict[str, str] = {}
    replica_job_names: dict[str, str] = {}
    replica_qos: dict[str, str] = {}
    for profile in profiles:
        if not isinstance(profile, dict):
            raise ImmutablePinError("fleet contract profile is malformed")
        profile_name = profile.get("serving_profile")
        replicas = profile.get("replicas")
        if not isinstance(profile_name, str) or not isinstance(replicas, list):
            raise ImmutablePinError("fleet contract profile identity is malformed")
        for replica in replicas:
            if not isinstance(replica, dict):
                raise ImmutablePinError("fleet contract replica is malformed")
            replica_id = replica.get("replica_id")
            job_name = replica.get("scheduler_job_name")
            qos = replica.get("qos")
            if (
                not isinstance(replica_id, str)
                or not replica_id
                or not isinstance(job_name, str)
                or not job_name
                or not isinstance(qos, str)
                or re.fullmatch(r"[A-Za-z0-9_.-]+", qos) is None
                or replica.get("pool_id", pool_id) != pool_id
                or replica_id in replica_profiles
            ):
                raise ImmutablePinError(
                    "fleet contract does not provide a bijective scheduler identity"
                )
            replica_profiles[replica_id] = profile_name
            replica_job_names[replica_id] = job_name
            replica_qos[replica_id] = qos
    if (
        len(replica_profiles) != binding["logical_replicas"]
        or len(set(replica_job_names.values())) != len(replica_job_names)
    ):
        raise ImmutablePinError("fleet contract replica cardinality is inconsistent")
    return str(pool_id), replica_profiles, replica_job_names, replica_qos


def _default_fleet_retirement_evidence(
    control: Mapping[str, Any],
    *,
    scheduler: fleet_transactions.SchedulerSnapshot | None = None,
) -> dict[str, Any]:
    """Resolve exact active fleet IDs through the supervisor's transaction join."""

    pool_root = Path(control["immutable"]["server_pool_root"]).resolve()
    pool_id, replica_profiles, replica_job_names, replica_qos = (
        _fleet_contract_reconciliation_identity(control)
    )
    snapshot = scheduler or fleet_transactions.query_scheduler()
    if not snapshot.squeue_ok or not snapshot.sacct_ok or snapshot.errors:
        raise SchedulerAmbiguity(
            "capacity transition requires complete fleet squeue+sacct truth: "
            + "; ".join(snapshot.errors)
        )
    fleet_sha256 = str(
        effective_fleet_contract_binding(control, verify_files=True)["sha256"]
    )
    with fleet_transactions.read_transaction_lock(pool_root) as directory:
        current_path = directory / fleet_transactions.CURRENT_FILENAME
        current = _load_json_object(
            current_path, description="fleet transaction CURRENT"
        )
        ledger_generation = current.get("current_generation")
        if (
            not isinstance(ledger_generation, int)
            or isinstance(ledger_generation, bool)
            or ledger_generation < 1
        ):
            raise SchedulerAmbiguity(
                "fleet transaction CURRENT has an invalid generation"
            )
        ledgers = fleet_transactions.read_generation_ledgers(
            directory,
            pool_root=pool_root,
            pool_id=pool_id,
            fleet_sha256=fleet_sha256,
            current_generation=ledger_generation,
            replica_ids=sorted(replica_profiles),
        )
        expected_names = set(replica_job_names.values())
        scoped_rows = tuple(
            row
            for row in snapshot.rows
            if row.job_name in expected_names
            or row.comment.startswith("asys-s5-fleet:")
        )
        reconciliation = fleet_transactions.reconcile_scheduler_rows(
            scoped_rows,
            ledgers,
            pool_id=pool_id,
            fleet_sha256=fleet_sha256,
            replica_profiles=replica_profiles,
            replica_job_names=replica_job_names,
            replica_qos=replica_qos,
        )
    allocations = [
        {
            "job_id": allocation.row.job_id,
            "replica_id": allocation.replica_id,
            "profile": allocation.profile,
            "ledger_generation": allocation.ledger_generation,
            "scheduler_state": allocation.row.state,
            "intent_token": allocation.attempt["intent_token"],
            "sbatch_path": allocation.attempt["sbatch_path"],
            "sbatch_sha256": allocation.attempt["sbatch_sha256"],
        }
        for allocation in reconciliation.active_allocations
    ]
    return {
        "pool_root": str(pool_root),
        "pool_id": pool_id,
        "fleet_sha256": fleet_sha256,
        "ledger_generation": ledger_generation,
        "scheduler_captured_timestamp": snapshot.captured_at,
        "active_allocations": allocations,
        "old_fleet_job_ids": sorted(
            (row["job_id"] for row in allocations), key=int
        ),
    }


def _capacity_archive_source_files(
    state_dir: Path, control: Mapping[str, Any]
) -> list[tuple[str, Path]]:
    """Select stable control/fleet evidence; mutable log streams are excluded."""

    sources: dict[str, Path] = {}

    def add(logical: str, path: Path, *, required: bool = True) -> None:
        resolved = path.expanduser().resolve()
        if not path.exists():
            if required:
                raise ControlError(f"capacity archive source is missing: {path}")
            return
        if path.is_symlink() or not resolved.is_file():
            raise ControlError(f"capacity archive source is unsafe: {path}")
        sources[logical] = resolved

    add("control/control.json", _state_path(state_dir))
    add("control/immutable_pins.json", state_dir / IMMUTABLE_PINS_FILENAME)
    add("control/transitions.jsonl", state_dir / TRANSITION_JOURNAL)
    add(
        "control/reconciliation.json",
        state_dir / RECONCILIATION_FILENAME,
        required=False,
    )
    fleet_binding = effective_fleet_contract_binding(control, verify_files=True)
    add("fleet/fleet_contract.json", Path(fleet_binding["path"]))
    authority = fleet_binding["protected_capacity"]
    add(
        "fleet/protected_capacity_marker.json",
        Path(authority["path"]),
    )
    add(
        "fleet/static_feasibility_certificate.json",
        Path(authority["static_feasibility_certificate_path"]),
    )
    record = control["capacity"]["current_contract"]
    if isinstance(record, Mapping):
        add("fleet/capacity_contract_complete.json", Path(record["marker_path"]))
    pool_root = Path(control["immutable"]["server_pool_root"]).resolve()
    transaction_root = fleet_transactions.state_directory(pool_root)
    if transaction_root.is_symlink() or not transaction_root.is_dir():
        raise ControlError("fleet transaction state is unavailable for archive")
    for path in sorted(transaction_root.rglob("*")):
        if not path.is_file() or path.name == fleet_transactions.LOCK_FILENAME:
            continue
        if path.is_symlink():
            raise ControlError(f"fleet transaction archive source is symlinked: {path}")
        relative = path.relative_to(transaction_root).as_posix()
        add(f"fleet/transactions/{relative}", path)
    # Preserve the immutable scripts referenced by every ledger attempt even when the
    # renderer stores them outside the pool's transaction-state directory.
    for logical, ledger_path in list(sources.items()):
        if not logical.startswith("fleet/transactions/ledgers/"):
            continue
        ledger = _load_json_object(ledger_path, description="fleet ledger")
        for replica_id, record in sorted(ledger.get("replicas", {}).items()):
            for attempt_index, attempt in enumerate(record.get("attempts", [])):
                if not isinstance(attempt, dict) or not attempt.get("sbatch_path"):
                    raise ControlError("fleet ledger attempt lacks immutable sbatch path")
                add(
                    (
                        "fleet/sbatch/"
                        f"{replica_id}/attempt-{attempt_index:04d}.sbatch"
                    ),
                    Path(str(attempt["sbatch_path"])),
                )
    return sorted(sources.items())


def _capacity_file_inventory(
    sources: Sequence[tuple[str, Path]],
) -> tuple[list[dict[str, Any]], str]:
    rows = [
        {
            "path": logical,
            "source": str(path),
            "size": path.stat().st_size,
            "sha256": sha256_file(path),
        }
        for logical, path in sources
    ]
    return rows, sha256_value(rows)


def _verify_capacity_archive(archive_root: Path) -> dict[str, Any]:
    marker_path = archive_root / CAPACITY_ARCHIVE_COMPLETE
    if (
        marker_path.is_symlink()
        or not marker_path.is_file()
        or marker_path.stat().st_nlink != 1
        or marker_path.stat().st_mode & 0o222
    ):
        raise ControlError("capacity archive completion marker is not sealed")
    marker = _load_json_object(marker_path, description="capacity archive marker")
    if (
        marker.get("schema_version") != 1
        or marker.get("kind") != "schema5_capacity_archive"
        or marker.get("complete") is not True
        or _SHA256_RE.fullmatch(str(marker.get("inventory_sha256", ""))) is None
    ):
        raise ControlError("capacity archive completion marker is invalid")
    inventory_path = archive_root / "INVENTORY.json"
    inventory = _load_json_object(inventory_path, description="capacity archive inventory")
    rows = inventory.get("files")
    if (
        inventory.get("schema_version") != 1
        or inventory.get("kind") != "schema5_capacity_archive_inventory"
        or not isinstance(rows, list)
        or sha256_value(rows) != marker["inventory_sha256"]
        or sha256_file(inventory_path) != marker.get("inventory_file_sha256")
    ):
        raise ControlError("capacity archive inventory is invalid")
    payload_root = archive_root / "payload"
    for row in rows:
        if not isinstance(row, dict) or set(row) != {"path", "size", "sha256"}:
            raise ControlError("capacity archive inventory row is invalid")
        relative = Path(str(row["path"]))
        if relative.is_absolute() or ".." in relative.parts:
            raise ControlError("capacity archive inventory path escapes its payload")
        target = payload_root / relative
        if (
            target.is_symlink()
            or not target.is_file()
            or target.stat().st_size != row["size"]
            or sha256_file(target) != row["sha256"]
        ):
            raise ControlError(f"capacity archive payload drifted: {relative}")
    if any(path.stat().st_mode & 0o222 for path in archive_root.rglob("*")):
        raise ControlError("capacity archive is not sealed read-only")
    return marker


def _create_capacity_archive(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    transition_id: str,
    now: float,
) -> tuple[Path, str]:
    """Copy and seal a marker-last, crash-recoverable capacity preimage."""

    archive_root = state_dir / "capacity-transitions" / transition_id / "archive"
    marker_path = archive_root / CAPACITY_ARCHIVE_COMPLETE
    if marker_path.exists():
        marker = _verify_capacity_archive(archive_root)
        return archive_root, sha256_file(marker_path)
    archive_root.mkdir(parents=True, exist_ok=True)
    intent_path = archive_root / "ARCHIVE_INTENT.json"
    intent = {
        "schema_version": 1,
        "kind": "schema5_capacity_archive_intent",
        "transition_id": transition_id,
        "immutable_sha256": control["immutable_sha256"],
    }
    if intent_path.exists():
        if _load_json_object(intent_path, description="capacity archive intent") != intent:
            raise ControlError("capacity archive intent conflicts with this transition")
    else:
        _atomic_write_json(intent_path, intent)
    sources = _capacity_archive_source_files(state_dir, control)
    before, before_sha256 = _capacity_file_inventory(sources)
    payload_root = archive_root / "payload"
    inventory_path = archive_root / "INVENTORY.json"
    expected_copied_rows = [
        {
            "path": source_row["path"],
            "size": source_row["size"],
            "sha256": source_row["sha256"],
        }
        for source_row in before
    ]
    reuse_pre_marker = False
    if inventory_path.exists() or inventory_path.is_symlink():
        if inventory_path.is_symlink() or not inventory_path.is_file():
            raise ControlError("partial capacity archive inventory is unsafe")
        existing_inventory = _load_json_object(
            inventory_path, description="partial capacity archive inventory"
        )
        if existing_inventory != {
            "schema_version": 1,
            "kind": "schema5_capacity_archive_inventory",
            "files": expected_copied_rows,
        }:
            raise ControlError(
                "partial capacity archive inventory conflicts with current sources"
            )
        if payload_root.is_symlink() or not payload_root.is_dir():
            raise ControlError("partial capacity archive payload is missing or unsafe")
        actual_files: set[str] = set()
        actual_dirs: set[str] = set()
        for path in payload_root.rglob("*"):
            if path.is_symlink():
                raise ControlError(
                    f"partial capacity archive contains a symlink: {path}"
                )
            relative = path.relative_to(payload_root).as_posix()
            if path.is_file():
                actual_files.add(relative)
            elif path.is_dir():
                actual_dirs.add(relative)
        expected_files = {row["path"] for row in expected_copied_rows}
        expected_dirs = {
            parent.as_posix()
            for logical in expected_files
            for parent in Path(logical).parents
            if parent != Path(".")
        }
        if actual_files != expected_files or actual_dirs != expected_dirs:
            raise ControlError(
                "partial capacity archive payload topology conflicts with inventory"
            )
        for row, (_logical, source) in zip(
            expected_copied_rows, sources, strict=True
        ):
            target = payload_root / row["path"]
            if (
                target.stat().st_size != row["size"]
                or sha256_file(target) != row["sha256"]
                or target.stat().st_ino == source.stat().st_ino
            ):
                raise ControlError(
                    f"partial capacity archive payload drifted: {row['path']}"
                )
        reuse_pre_marker = True
    elif payload_root.exists() or payload_root.is_symlink():
        if payload_root.is_symlink() or not payload_root.is_dir():
            raise ControlError("partial capacity archive payload is unsafe")
        # No inventory means the copy never reached its complete pre-marker preimage.
        # This exact transition-local tree is safe to rebuild after making sealed
        # partial directories traversable again.
        for path in sorted(payload_root.rglob("*"), reverse=True):
            if path.is_symlink():
                raise ControlError(
                    f"partial capacity archive contains a symlink: {path}"
                )
            path.chmod(0o755 if path.is_dir() else 0o600)
        payload_root.chmod(0o755)
        shutil.rmtree(payload_root)

    copied_rows: list[dict[str, Any]] = []
    if reuse_pre_marker:
        copied_rows = expected_copied_rows
    else:
        payload_root.mkdir()
        for source_row, (logical, source) in zip(before, sources, strict=True):
            target = payload_root / logical
            target.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(source, target)
            copied_rows.append(
                {
                    "path": logical,
                    "size": target.stat().st_size,
                    "sha256": sha256_file(target),
                }
            )
            if (
                copied_rows[-1]["size"] != source_row["size"]
                or copied_rows[-1]["sha256"] != source_row["sha256"]
                or target.stat().st_ino == source.stat().st_ino
            ):
                raise ControlError(
                    f"capacity archive copy verification failed: {source}"
                )
    after, after_sha256 = _capacity_file_inventory(sources)
    if after != before or after_sha256 != before_sha256:
        raise ControlError("capacity archive sources changed during capture")
    inventory = {
        "schema_version": 1,
        "kind": "schema5_capacity_archive_inventory",
        "files": copied_rows,
    }
    if not reuse_pre_marker:
        _atomic_write_json(inventory_path, inventory)
    for path in sorted(payload_root.rglob("*"), reverse=True):
        path.chmod(0o555 if path.is_dir() else 0o444)
    payload_root.chmod(0o555)
    intent_path.chmod(0o444)
    inventory_path.chmod(0o444)
    marker = {
        "schema_version": 1,
        "kind": "schema5_capacity_archive",
        "complete": True,
        "transition_id": transition_id,
        "immutable_sha256": control["immutable_sha256"],
        "created_at": utc_timestamp(now),
        "created_timestamp": now,
        "source_inventory_sha256": before_sha256,
        "inventory_sha256": sha256_value(copied_rows),
        "inventory_file_sha256": sha256_file(inventory_path),
        "file_count": len(copied_rows),
    }
    _atomic_publish_readonly_json(marker_path, marker)
    archive_root.chmod(0o555)
    _verify_capacity_archive(archive_root)
    return archive_root, sha256_file(marker_path)


def _activate_operator_hold(
    hold: MutableMapping[str, Any], *, reason: str, now: float
) -> None:
    event = "updated" if hold["active"] else "activated"
    prior_reasons = list(hold["reasons"]) if hold["active"] else []
    if not hold["active"]:
        hold["activation_id"] = uuid.uuid4().hex
        hold["activated_at"] = utc_timestamp(now)
        hold["activated_timestamp"] = now
    reasons = sorted(set([*prior_reasons, reason]))
    hold.update(
        {
            "active": True,
            "mode": "operator",
            "reasons": reasons,
            "consecutive_clean_polls": 0,
            "semantic_clean_after_activation": False,
            "updated_at": utc_timestamp(now),
            "updated_timestamp": now,
            "acknowledged_at": None,
            "acknowledged_timestamp": None,
        }
    )
    hold["history"].append(
        {
            "event": event,
            "mode": "operator",
            "reasons": reasons,
            "at": utc_timestamp(now),
            "timestamp": now,
        }
    )


def _consume_capacity_remediation_incidents_locked(
    state_dir: Path,
    control: MutableMapping[str, Any],
    *,
    transition_id: str,
    incident_keys: Sequence[str],
    now: float,
) -> list[str]:
    """Consume the exact capacity incidents sealed by this transition's intent.

    The caller holds ``control_lock`` and publishes the capacity transition in the
    same control replacement.  The intent is marker-first and the journal writes are
    idempotent by transition and alert identity, so a crash before ``control.json``
    replacement replays the same closed set exactly once.  Scientific/data-integrity
    incidents outside this set remain layered on the operator hold and continue to
    block transition completion.
    """

    consumed = sorted(set(incident_keys))
    if (
        len(consumed) != len(incident_keys)
        or any(key not in CAPACITY_REMEDIATION_ALERT_KEYS for key in consumed)
    ):
        raise ControlError(
            "capacity transition incident intent contains an invalid dedupe key"
        )
    if not consumed:
        return []
    hold = control["admission_safety_hold"]
    resolved_alert_ids: list[str] = []
    durable_alert_records = _read_jsonl_locked(
        state_dir / ALERT_JOURNAL, missing_ok=True
    )
    for alert in control.get("alerts", []):
        if (
            isinstance(alert, dict)
            and alert.get("dedupe_key") in consumed
            and alert.get("resolved_at") is None
        ):
            journal_identity = {
                "action": "resolved",
                "alert_id": alert["alert_id"],
                "dedupe_key": alert["dedupe_key"],
                "capacity_transition_id": transition_id,
            }
            prior = [
                row
                for row in durable_alert_records
                if all(row.get(key) == value for key, value in journal_identity.items())
            ]
            if len(prior) > 1:
                raise ControlError(
                    "capacity incident resolution journal contains duplicate replay"
                )
            if prior:
                resolution_at = prior[0].get("at")
                resolution_timestamp = prior[0].get("timestamp")
                if (
                    not isinstance(resolution_at, str)
                    or not isinstance(resolution_timestamp, (int, float))
                    or isinstance(resolution_timestamp, bool)
                ):
                    raise ControlError(
                        "capacity incident resolution replay timestamp is invalid"
                    )
            else:
                resolution_at = utc_timestamp(now)
                resolution_timestamp = now
                record = {
                    "at": resolution_at,
                    "timestamp": resolution_timestamp,
                    **journal_identity,
                }
                _append_jsonl(state_dir / ALERT_JOURNAL, record)
                durable_alert_records.append(record)
            alert["resolved_at"] = resolution_at
            alert["resolved_timestamp"] = resolution_timestamp
            resolved_alert_ids.append(str(alert["alert_id"]))
    hold["reasons"] = sorted(
        reason for reason in hold["reasons"] if reason not in consumed
    )
    hold["updated_at"] = utc_timestamp(now)
    hold["updated_timestamp"] = now
    hold["history"].append(
        {
            "event": "updated",
            "mode": hold["mode"],
            "reasons": list(hold["reasons"]),
            "update_reason": "capacity_remediation_consumed",
            "consumed_reasons": consumed,
            "transition_id": transition_id,
            "at": utc_timestamp(now),
            "timestamp": now,
        }
    )
    _append_capacity_transition_event_once(
        state_dir,
        control,
        event="capacity_remediation_incidents_consumed",
        details={
            "transition_id": transition_id,
            "dedupe_keys": consumed,
            "resolved_alert_ids": resolved_alert_ids,
        },
        now=now,
    )
    return consumed


def _append_capacity_transition_event_once(
    state_dir: Path,
    control: MutableMapping[str, Any],
    *,
    event: str,
    details: Mapping[str, Any],
    now: float,
) -> dict[str, Any]:
    """Append one transition event, adopting a journaled pre-save replay."""

    transition_id = details.get("transition_id")
    if not isinstance(transition_id, str) or not transition_id:
        raise ControlError("capacity transition event lacks a transition identity")
    durable = _read_jsonl_locked(state_dir / TRANSITION_JOURNAL, missing_ok=True)
    memory = list(control.get("transition_history", []))
    if durable[: len(memory)] != memory:
        raise ControlError("transition journal diverged during capacity replay")
    matches = [
        row
        for row in durable
        if row.get("event") == event
        and isinstance(row.get("details"), dict)
        and row["details"].get("transition_id") == transition_id
    ]
    if len(matches) > 1:
        raise ControlError(
            f"capacity transition event {event!r} was journaled more than once"
        )
    if matches:
        if matches[0].get("details") != dict(details):
            raise ControlError(
                f"capacity transition event {event!r} conflicts with durable replay"
            )
        if len(durable) > len(memory):
            control["transition_history"] = copy.deepcopy(durable)
            validate_transition_history(control)
        return matches[0]
    return append_transition(
        state_dir,
        control,
        event=event,
        details=details,
        now=now,
    )


def _clear_capacity_operator_hold(
    hold: MutableMapping[str, Any], *, transition_id: str, now: float
) -> None:
    expected_reason = f"capacity-transition:{transition_id}"
    if (
        not hold["active"]
        or hold["mode"] != "operator"
        or hold["reasons"] != [expected_reason]
    ):
        raise ControlError(
            "capacity transition cannot clear a hold containing unresolved "
            "non-capacity reasons"
        )
    previous_reasons = list(hold["reasons"])
    hold["history"].append(
        {
            "event": "cleared",
            "mode": "operator",
            "reasons": previous_reasons,
            "at": utc_timestamp(now),
            "timestamp": now,
            "clear_reason": "capacity_generation_readiness_complete",
        }
    )
    hold.update(
        {
            "active": False,
            "mode": None,
            "reasons": [],
            "consecutive_clean_polls": 0,
            "semantic_clean_after_activation": False,
            "activated_at": None,
            "activated_timestamp": None,
            "activation_id": None,
            "updated_at": utc_timestamp(now),
            "updated_timestamp": now,
            "acknowledged_at": None,
            "acknowledged_timestamp": None,
        }
    )


def _write_capacity_retirement_intent(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    transition_id: str,
    from_generation: int,
    to_generation: int,
    old_fleet_job_ids: Sequence[str],
    fleet_evidence_sha256: str,
    consumed_capacity_incidents: Sequence[str],
) -> tuple[Path, str, list[str]]:
    path = (
        state_dir
        / "capacity-transitions"
        / transition_id
        / CAPACITY_RETIREMENT_INTENT
    )
    intended_incidents = sorted(set(consumed_capacity_incidents))
    if (
        len(intended_incidents) != len(consumed_capacity_incidents)
        or any(
            key not in CAPACITY_REMEDIATION_ALERT_KEYS
            for key in intended_incidents
        )
    ):
        raise ControlError(
            "capacity retirement intent contains an invalid incident set"
        )
    payload = {
        "schema_version": 2,
        "kind": "schema5_capacity_fleet_retirement_intent",
        "transition_id": transition_id,
        "immutable_sha256": control["immutable_sha256"],
        "from_capacity_generation": from_generation,
        "to_capacity_generation": to_generation,
        "old_fleet_job_ids": list(old_fleet_job_ids),
        "fleet_evidence_sha256": fleet_evidence_sha256,
        "consumed_capacity_incidents": intended_incidents,
    }
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() or path.is_symlink():
        if (
            path.is_symlink()
            or not path.is_file()
            or path.stat().st_nlink != 1
            or path.stat().st_mode & 0o222
        ):
            raise SchedulerAmbiguity(
                "existing exact fleet-retirement intent is not a sealed "
                "single-link file"
            )
        existing = _load_json_object(
            path, description="capacity retirement intent"
        )
        expected_identity = {
            key: value
            for key, value in payload.items()
            if key != "consumed_capacity_incidents"
        }
        observed_identity = {
            key: value
            for key, value in existing.items()
            if key != "consumed_capacity_incidents"
        }
        recorded_incidents = existing.get("consumed_capacity_incidents")
        if (
            observed_identity != expected_identity
            or not isinstance(recorded_incidents, list)
            or recorded_incidents != sorted(set(recorded_incidents))
            or any(
                not isinstance(key, str)
                or key not in CAPACITY_REMEDIATION_ALERT_KEYS
                for key in recorded_incidents
            )
        ):
            raise SchedulerAmbiguity(
                "existing exact fleet-retirement intent conflicts with transition"
            )
        intended_incidents = list(recorded_incidents)
    else:
        _atomic_publish_readonly_json(path, payload)
    return path.resolve(), sha256_file(path), intended_incidents


def _directory_file_inventory(root: Path) -> tuple[list[dict[str, Any]], str]:
    rows: list[dict[str, Any]] = []
    if root.is_symlink() or not root.is_dir():
        raise ControlError(f"fleet transaction state is unsafe: {root}")
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise ControlError(f"fleet transaction state contains symlink: {path}")
        if path.is_file():
            rows.append(
                {
                    "path": path.relative_to(root).as_posix(),
                    "size": path.stat().st_size,
                    "sha256": sha256_file(path),
                }
            )
    return rows, sha256_value(rows)


def _retire_fleet_transaction_state(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    transition_id: str,
    now: float,
) -> dict[str, Any]:
    """Move the old hash-bound ledger aside before the replacement supervisor starts."""

    pool_root = Path(control["immutable"]["server_pool_root"]).resolve()
    source = fleet_transactions.state_directory(pool_root)
    transition_root = state_dir / "capacity-transitions" / transition_id
    target = transition_root / CAPACITY_FLEET_STATE_RETIREMENT
    intent_path = transition_root / "FLEET_TRANSACTION_STATE_RETIREMENT_INTENT.json"
    complete_path = transition_root / "FLEET_TRANSACTION_STATE_RETIRED.json"
    if complete_path.exists() or complete_path.is_symlink():
        if (
            complete_path.is_symlink()
            or not complete_path.is_file()
            or complete_path.stat().st_nlink != 1
            or complete_path.stat().st_mode & 0o222
        ):
            raise ControlError(
                "retired fleet transaction state marker is not sealed"
            )
        marker = _load_json_object(
            complete_path, description="retired fleet transaction state"
        )
        rows, digest = _directory_file_inventory(target)
        if (
            marker.get("complete") is not True
            or marker.get("transition_id") != transition_id
            or marker.get("inventory_sha256") != digest
            or marker.get("file_count") != len(rows)
            or source.exists()
        ):
            raise ControlError("retired fleet transaction state marker drifted")
        return marker
    if source.exists():
        rows, digest = _directory_file_inventory(source)
    elif target.exists():
        rows, digest = _directory_file_inventory(target)
    else:
        raise ControlError("old fleet transaction state disappeared before retirement")
    intent = {
        "schema_version": 1,
        "kind": "schema5_fleet_transaction_state_retirement_intent",
        "transition_id": transition_id,
        "source": str(source),
        "target": str(target),
        "inventory_sha256": digest,
        "file_count": len(rows),
    }
    if intent_path.exists() or intent_path.is_symlink():
        if (
            intent_path.is_symlink()
            or not intent_path.is_file()
            or intent_path.stat().st_nlink != 1
            or intent_path.stat().st_mode & 0o222
            or _load_json_object(
                intent_path, description="fleet state retire intent"
            )
            != intent
        ):
            raise ControlError("fleet transaction retirement intent conflicts")
    else:
        _atomic_publish_readonly_json(intent_path, intent)
    if source.exists():
        if target.exists():
            raise ControlError(
                "both live and retired fleet transaction states exist ambiguously"
            )
        os.replace(source, target)
    retired_rows, retired_digest = _directory_file_inventory(target)
    if retired_rows != rows or retired_digest != digest:
        raise ControlError("fleet transaction state changed during exact retirement")
    for path in sorted(target.rglob("*"), reverse=True):
        path.chmod(0o555 if path.is_dir() else 0o444)
    target.chmod(0o555)
    marker = {
        "schema_version": 1,
        "kind": "schema5_fleet_transaction_state_retired",
        "complete": True,
        "transition_id": transition_id,
        "retired_at": utc_timestamp(now),
        "retired_timestamp": now,
        "source": str(source),
        "target": str(target),
        "inventory_sha256": digest,
        "file_count": len(rows),
    }
    _atomic_publish_readonly_json(complete_path, marker)
    return marker


def _launch_capacity_fleet_once(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    transition: Mapping[str, Any],
    runner: (
        Callable[
            [Sequence[str], Mapping[str, str]], subprocess.CompletedProcess[str]
        ]
        | None
    ) = None,
) -> subprocess.CompletedProcess[str]:
    command = [*effective_fleet_supervisor_command(control), "--once"]
    environment = _sanitized_subprocess_environment()
    environment.update(REQUIRED_OFFLINE_ENVIRONMENT)
    environment.update(
        {
            "ASYS_RELEASE_ID": str(control["immutable"]["release_id"]),
            "ASYS_MODEL_CONTRACT_SHA256": str(
                control["immutable"]["model_contract_sha256"]
            ),
            "ASYS_FLEET_CONTRACT_SHA256": str(
                transition["new_contract"]["sha256"]
            ),
            "ASYS_RELEASE_FLEET_CONTRACT_SHA256": str(
                control["immutable"]["fleet_contract_sha256"]
            ),
            "ASYS_CAPACITY_GENERATION": str(
                transition["to_generation"]
            ),
            "ASYS_TRANSPORT_CENSOR_PROTOCOL_VERSION": str(
                control["immutable"]["transport_uncertainty_binding"][
                    "transport_censor_protocol_version"
                ]
            ),
            "ASYS_TRANSPORT_CENSOR_PROTOCOL_HASH": str(
                control["immutable"]["transport_uncertainty_binding"][
                    "transport_censor_protocol_hash"
                ]
            ),
            "ASYS_TRANSPORT_UNCERTAINTY_BINDING_SHA256": str(
                control["immutable"][
                    "transport_uncertainty_binding_sha256"
                ]
            ),
            "ASYS_HARNESS_ENVIRONMENT_SHA256": str(
                control["immutable"]["harness_environment_sha256"]
            ),
            "ASYS_SERVING_ENVIRONMENT_SHA256": str(
                control["immutable"]["serving_environment_sha256"]
            ),
            "ASYS_ROLLOUT_GENERATION": str(
                int(control["rollout_generation"]) + 1
            ),
            "ASYS_IMMUTABLE_PINS_SHA256": str(control["immutable_sha256"]),
            "ASYS_SCHEMA5_CONTROL": str(_state_path(state_dir).resolve()),
        }
    )
    if runner is not None:
        return runner(command, environment)
    return subprocess.run(
        command,
        capture_output=True,
        text=True,
        check=False,
        timeout=900.0,
        env=environment,
    )


def _capacity_gates_are_fresh(
    control: Mapping[str, Any], transition: Mapping[str, Any]
) -> None:
    generation = int(transition["to_generation"])
    published = float(transition.get("published_timestamp", math.inf))
    failures: list[str] = []
    for gate in transition["invalidated_readiness"]:
        record = control["readiness"].get(gate, {})
        if (
            record.get("passed") is not True
            or record.get("capacity_generation") != generation
            or not isinstance(record.get("attested_timestamp"), (int, float))
            or float(record["attested_timestamp"]) < published
        ):
            failures.append(gate)
    if failures:
        raise ReadinessError(
            "capacity transition requires fresh generation-bound gates: "
            + ", ".join(failures)
        )


def _retired_capacity_transition_v1_reference_do_not_call(
    state_dir: Path,
    *,
    action: str,
    fleet_contract_path: Path | None = None,
    fleet_contract_sha256: str | None = None,
    protected_capacity_marker_path: Path | None = None,
    protected_capacity_marker_sha256: str | None = None,
    protected_capacity_marker_id: str | None = None,
    static_feasibility_certificate_path: Path | None = None,
    static_feasibility_certificate_sha256: str | None = None,
    static_feasibility_certificate_id: str | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    fleet_evidence_reader: (
        Callable[[Mapping[str, Any]], Mapping[str, Any]] | None
    ) = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    fleet_launch_runner: (
        Callable[
            [Sequence[str], Mapping[str, str]], subprocess.CompletedProcess[str]
        ]
        | None
    ) = None,
    resume_callback: Callable[[Path], Mapping[str, Any]] | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Non-authoritative v1 reference retained only for sealed-history review.

    The callable path is deliberately fenced.  Production and tests resolve the later
    :func:`capacity_transition`, which requires an explicit additive fleet contract.
    """

    raise ControlError(
        "retired capacity-transition v1 cannot publish a production generation"
    )

    if action not in {"status", "dry-run", "apply", "complete"}:
        raise ControlError(f"unknown capacity-transition action {action!r}")
    timestamp = time.time() if now is None else float(now)
    read_scheduler = scheduler_reader or (
        lambda: query_scheduler(tolerate_errors=False)
    )
    resolve_fleet = fleet_evidence_reader or _default_fleet_retirement_evidence
    runner = cancel_runner or _run_subprocess
    with capacity_transition_lock(state_dir):
        if action == "status":
            control = load_control(state_dir)
            return {
                "action": action,
                "capacity": copy.deepcopy(control["capacity"]),
                "admission_safety_hold": copy.deepcopy(
                    control["admission_safety_hold"]
                ),
            }
        if action == "complete":
            # A crash may occur after ``resume_control`` has durably published
            # ``running`` but before this workflow marks the transition's resume
            # receipt and opens its throughput epoch.  That state is no longer
            # quiescent and must not be forced back through the pause/drain gate.
            # The completed resume transaction is already scheduler-fenced, so the
            # marker-only retry can finish without another scheduler mutation.
            control = load_control(state_dir, verify_files=True)
            if control["capacity"]["active_transition"] is None:
                pending = [
                    row
                    for row in control["capacity"]["history"]
                    if row.get("phase") == "completed"
                    and row.get("production_resume_state") == "pending"
                ]
                if len(pending) != 1:
                    raise ControlError(
                        "capacity transition is not waiting for completion"
                    )
                transition_id = str(pending[0]["transition_id"])
                resumed = _complete_capacity_resume(
                    state_dir,
                    transition_id=transition_id,
                    resume_callback=resume,
                    now=timestamp,
                )
                return {
                    "action": action,
                    "completed": True,
                    "capacity_generation": pending[0]["to_generation"],
                    "resume_ceiling": 24,
                    "production_resumed": resumed,
                }
        with admission_boundary_lock(state_dir):
            snapshot = read_scheduler()
            _require_complete_quiescent_scheduler(
                snapshot, operation="capacity transition"
            )
            with control_lock(state_dir):
                control = load_control(state_dir, verify_files=True)
                pending_resumes = [
                    row
                    for row in control["capacity"]["history"]
                    if row.get("production_resume_state") == "pending"
                ]
                if action in {"dry-run", "apply"} and pending_resumes:
                    raise ControlError(
                        "a completed capacity transition still has a pending "
                        "production resume; retry capacity-transition complete"
                    )
                if (
                    control["desired_state"] != "paused"
                    or control.get("drain_requested") is not True
                ):
                    raise ControlError(
                        "capacity transition requires pause --drain to complete first"
                    )
                active = copy.deepcopy(control["capacity"]["active_transition"])
            if action == "dry-run":
                if active is not None:
                    return {
                        "action": action,
                        "would_resume_transition": True,
                        "transition": active,
                    }
                evidence = dict(resolve_fleet(control))
                job_ids = [str(item) for item in evidence.get("old_fleet_job_ids", [])]
                if (
                    not all(job_id.isdigit() for job_id in job_ids)
                    or len(job_ids) != len(set(job_ids))
                ):
                    raise SchedulerAmbiguity(
                        "fleet retirement evidence contains invalid job IDs"
                    )
                return {
                    "action": action,
                    "would_change": True,
                    "from_generation": control["capacity"]["current_generation"],
                    "to_generation": control["capacity"]["current_generation"] + 1,
                    "old_fleet_job_ids": sorted(job_ids, key=int),
                    "fleet_evidence_sha256": sha256_value(evidence),
                }
            if action == "complete":
                if active is None or active.get("phase") != "readiness_pending":
                    raise ControlError(
                        "capacity transition is not waiting for readiness completion"
                    )
                old_live = sorted(
                    set(active["old_fleet_job_ids"]) & snapshot.active_job_ids,
                    key=int,
                )
                if old_live:
                    raise SchedulerAmbiguity(
                        f"old fleet jobs remain active: {old_live}"
                    )
                validate_readiness(
                    control,
                    state_dir=state_dir,
                    verify_files=True,
                    now=timestamp,
                )
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    current = control["capacity"]["active_transition"]
                    if current != active:
                        raise ControlError(
                            "capacity transition changed during readiness validation"
                        )
                    critical = _active_critical_alerts(control)
                    if critical:
                        raise ControlError(
                            "capacity transition cannot complete with critical alerts: "
                            + ", ".join(critical)
                        )
                    completed = copy.deepcopy(current)
                    completed.update(
                        {
                            "phase": "completed",
                            "completed_at": utc_timestamp(timestamp),
                            "completed_timestamp": timestamp,
                        }
                    )
                    control["capacity"]["history"].append(completed)
                    control["capacity"]["active_transition"] = None
                    # The capacity transaction itself has proven the drain, exact old
                    # retirement, replacement launch, and fresh gates.  Clear the
                    # consumed drain request so the explicit resume transaction can
                    # pass its ordinary paused-state fencing contract.
                    control["drain_requested"] = False
                    control["drain_intent"] = None
                    _clear_capacity_operator_hold(
                        control["admission_safety_hold"],
                        transition_id=active["transition_id"],
                        now=timestamp,
                    )
                    _reset_admission_ramp(
                        state_dir,
                        control,
                        reason="capacity_transition_completed",
                        now=timestamp,
                        ceiling=24,
                        clear_last_observation=True,
                    )
                    append_transition(
                        state_dir,
                        control,
                        event="capacity_transition_completed",
                        details={
                            "transition_id": active["transition_id"],
                            "capacity_generation": active["to_generation"],
                            "resume_ceiling": 24,
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
                return {
                    "action": action,
                    "completed": True,
                    "capacity_generation": active["to_generation"],
                    "resume_ceiling": 24,
                }

            # apply: establish the immutable preimage and exact retirement intent once.
            if active is None:
                evidence = dict(resolve_fleet(control))
                job_ids = [str(item) for item in evidence.get("old_fleet_job_ids", [])]
                if (
                    not all(job_id.isdigit() for job_id in job_ids)
                    or len(job_ids) != len(set(job_ids))
                ):
                    raise SchedulerAmbiguity(
                        "fleet retirement evidence contains invalid job IDs"
                    )
                job_ids = sorted(job_ids, key=int)
                from_generation = int(control["capacity"]["current_generation"])
                transition_id = (
                    f"capacity-g{from_generation:06d}-to-"
                    f"g{from_generation + 1:06d}-"
                    + hashlib.sha256(
                        canonical_json(
                            {
                                "immutable_sha256": control["immutable_sha256"],
                                "job_ids": job_ids,
                            }
                        )
                    ).hexdigest()[:16]
                )
                archive_root, archive_sha256 = _create_capacity_archive(
                    state_dir,
                    control,
                    transition_id=transition_id,
                    now=timestamp,
                )
                invalidated = (
                    "static_feasibility_certificate",
                    "protected_capacity",
                    "fleet",
                    "smoke_runs",
                    "scheduler_reconciliation",
                )
                active = {
                    "transition_id": transition_id,
                    "phase": "retirement_requested",
                    "from_generation": from_generation,
                    "to_generation": from_generation + 1,
                    "created_at": utc_timestamp(timestamp),
                    "created_timestamp": timestamp,
                    "old_fleet_job_ids": job_ids,
                    "fleet_evidence_sha256": sha256_value(evidence),
                    "archive_path": str(archive_root),
                    "archive_sha256": archive_sha256,
                    "retirement_attempts": 0,
                    "retirement_results": {},
                    "last_retirement_error": None,
                    "invalidated_readiness": list(invalidated),
                }
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    if control["capacity"]["active_transition"] is not None:
                        raise ControlError(
                            "another capacity transition was published concurrently"
                        )
                    _close_open_epoch(
                        control, reason="capacity_transition", now=timestamp
                    )
                    _reset_admission_ramp(
                        state_dir,
                        control,
                        reason="capacity_transition",
                        now=timestamp,
                        ceiling=24,
                        clear_last_observation=True,
                    )
                    consumed_capacity_incidents = (
                        _consume_capacity_remediation_incidents_locked(
                            state_dir,
                            control,
                            transition_id=transition_id,
                            incident_keys=sorted(
                                set(
                                    control["admission_safety_hold"].get(
                                        "reasons", ()
                                    )
                                )
                                & CAPACITY_REMEDIATION_ALERT_KEYS
                            ),
                            now=timestamp,
                        )
                    )
                    _activate_operator_hold(
                        control["admission_safety_hold"],
                        reason=f"capacity-transition:{transition_id}",
                        now=timestamp,
                    )
                    for gate in invalidated:
                        control["readiness"][gate] = {
                            "passed": False,
                            "evidence": None,
                            "attested_at": None,
                        }
                    control["capacity"]["active_transition"] = copy.deepcopy(active)
                    append_transition(
                        state_dir,
                        control,
                        event="capacity_transition_retirement_committed",
                        details={
                            "transition_id": transition_id,
                            "old_fleet_job_ids": job_ids,
                            "archive_path": str(archive_root),
                            "archive_sha256": archive_sha256,
                            "invalidated_readiness": list(invalidated),
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
            elif active.get("phase") == "readiness_pending":
                return {
                    "action": action,
                    "transition": active,
                    "retirement_complete": True,
                    "readiness_pending": list(active["invalidated_readiness"]),
                }

            live_old_ids = sorted(
                set(active["old_fleet_job_ids"]) & snapshot.active_job_ids, key=int
            )
            results: dict[str, Any] = {}
            error: str | None = None
            for job_id in live_old_ids:
                proc = runner(["scancel", job_id])
                results[job_id] = {
                    "returncode": int(proc.returncode),
                    "stderr": proc.stderr.strip()[:1000],
                    "at": utc_timestamp(timestamp),
                }
                if proc.returncode != 0 and error is None:
                    error = (
                        f"failed exact fleet retirement {job_id}: "
                        f"{proc.stderr.strip()[:500]}"
                    )
            with control_lock(state_dir):
                control = load_control(state_dir)
                current = control["capacity"]["active_transition"]
                if (
                    not isinstance(current, dict)
                    or current.get("transition_id") != active["transition_id"]
                ):
                    raise ControlError(
                        "capacity transition changed during exact fleet retirement"
                    )
                current["retirement_attempts"] += 1
                current.setdefault("retirement_results", {}).update(results)
                current["last_retirement_error"] = error
                append_transition(
                    state_dir,
                    control,
                    event="capacity_transition_retirement_attempted",
                    details={
                        "transition_id": active["transition_id"],
                        "target_job_ids": live_old_ids,
                        "error": error,
                    },
                    now=timestamp,
                )
                _save_control(state_dir, control, now=timestamp)
            if error is not None:
                raise ControlError(error)
            fresh = read_scheduler()
            _require_complete_quiescent_scheduler(
                fresh, operation="capacity transition publication"
            )
            remaining = sorted(
                set(active["old_fleet_job_ids"]) & fresh.active_job_ids, key=int
            )
            if remaining:
                return {
                    "action": action,
                    "transition_id": active["transition_id"],
                    "retirement_requested": True,
                    "remaining_old_fleet_job_ids": remaining,
                }
            with control_lock(state_dir):
                control = load_control(state_dir)
                current = control["capacity"]["active_transition"]
                if (
                    not isinstance(current, dict)
                    or current.get("transition_id") != active["transition_id"]
                ):
                    raise ControlError(
                        "capacity transition changed before generation publication"
                    )
                current["phase"] = "readiness_pending"
                current["last_retirement_error"] = None
                current["published_at"] = utc_timestamp(timestamp)
                current["published_timestamp"] = timestamp
                control["capacity"]["current_generation"] = current["to_generation"]
                append_transition(
                    state_dir,
                    control,
                    event="capacity_generation_published",
                    details={
                        "transition_id": current["transition_id"],
                        "capacity_generation": current["to_generation"],
                        "readiness_pending": current["invalidated_readiness"],
                    },
                    now=timestamp,
                )
                _save_control(state_dir, control, now=timestamp)
            return {
                "action": action,
                "transition_id": active["transition_id"],
                "capacity_generation": active["to_generation"],
                "retirement_complete": True,
                "readiness_pending": list(active["invalidated_readiness"]),
            }


def _assert_additive_capacity_contract(
    current_path: Path, proposed_path: Path
) -> None:
    """Prove the proposal retains every existing fleet semantic byte-for-byte."""

    current = _load_json_object(current_path, description="current fleet contract")
    proposed = _load_json_object(proposed_path, description="proposed fleet contract")
    mutable_root = {"logical_replica_count", "allocated_gpu_count", "profiles"}
    if set(current) != set(proposed) or any(
        current[field] != proposed[field]
        for field in set(current) - mutable_root
    ):
        raise ImmutablePinError(
            "capacity contract changes release/model/pool/offline fleet semantics"
        )
    current_profiles = current.get("profiles")
    proposed_profiles = proposed.get("profiles")
    if not isinstance(current_profiles, list) or not isinstance(proposed_profiles, list):
        raise ImmutablePinError("capacity contract profiles are malformed")

    def by_name(rows: Sequence[Any], *, label: str) -> dict[str, Mapping[str, Any]]:
        result: dict[str, Mapping[str, Any]] = {}
        for row in rows:
            if (
                not isinstance(row, dict)
                or not isinstance(row.get("serving_profile"), str)
                or row["serving_profile"] in result
            ):
                raise ImmutablePinError(
                    f"{label} fleet profiles are malformed or duplicated"
                )
            result[row["serving_profile"]] = row
        return result

    old_by_name = by_name(current_profiles, label="current")
    new_by_name = by_name(proposed_profiles, label="proposed")
    if set(old_by_name) != set(new_by_name):
        raise ImmutablePinError("capacity contract adds/removes serving profiles")
    all_ids: set[str] = set()
    all_names: set[str] = set()
    for profile_name in sorted(old_by_name):
        old = old_by_name[profile_name]
        new = new_by_name[profile_name]
        if set(old) != set(new) or any(
            old[field] != new[field] for field in set(old) - {"replicas"}
        ):
            raise ImmutablePinError(
                f"capacity contract changes {profile_name} model/profile semantics"
            )
        old_replicas = old.get("replicas")
        new_replicas = new.get("replicas")
        if (
            not isinstance(old_replicas, list)
            or not isinstance(new_replicas, list)
            or len(new_replicas) < len(old_replicas)
            or new_replicas[: len(old_replicas)] != old_replicas
        ):
            raise ImmutablePinError(
                f"capacity contract replaces/mutates an existing {profile_name} replica"
            )
        for index, replica in enumerate(new_replicas):
            if (
                not isinstance(replica, dict)
                or replica.get("replica_index") != index
                or not isinstance(replica.get("replica_id"), str)
                or not isinstance(replica.get("scheduler_job_name"), str)
                or replica["replica_id"] in all_ids
                or replica["scheduler_job_name"] in all_names
            ):
                raise ImmutablePinError(
                    "capacity contract replica indices/IDs/job names are not unique"
                )
            all_ids.add(replica["replica_id"])
            all_names.add(replica["scheduler_job_name"])


def _inspect_capacity_contract(
    control: Mapping[str, Any],
    *,
    path: Path | None,
    expected_sha256: str | None,
    protected_capacity_marker_path: Path | None,
    protected_capacity_marker_sha256: str | None,
    protected_capacity_marker_id: str | None,
    static_feasibility_certificate_path: Path | None,
    static_feasibility_certificate_sha256: str | None,
    static_feasibility_certificate_id: str | None,
) -> tuple[
    Path,
    str,
    FrozenFleetContract,
    dict[str, int],
    dict[str, Any],
]:
    if path is None or expected_sha256 is None:
        raise ImmutablePinError(
            "capacity transition requires --fleet-contract and --fleet-contract-sha256"
        )
    resolved = path.expanduser().resolve()
    if (
        resolved.is_symlink()
        or not resolved.is_file()
        or _SHA256_RE.fullmatch(expected_sha256) is None
        or sha256_file(resolved) != expected_sha256
    ):
        raise ImmutablePinError("proposed capacity contract/hash is invalid")
    sidecar = resolved.with_suffix(".sha256")
    if (
        sidecar.is_symlink()
        or not sidecar.is_file()
        or sidecar.read_text(encoding="utf-8").strip().split()
        != [expected_sha256, resolved.name]
    ):
        raise ImmutablePinError(
            "proposed capacity contract lacks its exact checksum sidecar"
        )
    current_binding = effective_fleet_contract_binding(control, verify_files=True)
    _assert_additive_capacity_contract(
        Path(current_binding["path"]).resolve(), resolved
    )
    immutable = control["immutable"]
    try:
        models = load_model_contracts(
            immutable["model_contract_path"],
            expected_sha256=immutable["model_contract_sha256"],
        )
        fleet = load_fleet_contract(
            resolved,
            model_contracts=models,
            expected_sha256=expected_sha256,
            allow_capacity_layout=True,
        )
    except (FleetContractError, ModelContractError, OSError, ValueError) as exc:
        raise ImmutablePinError(f"proposed capacity contract failed closed: {exc}") from exc
    current_counts = _capacity_profile_counts(load_effective_fleet_contract(control))
    proposed_counts = _capacity_profile_counts(fleet)
    if proposed_counts == current_counts:
        raise ImmutablePinError("proposed capacity contract does not change layout")
    reductions = {
        profile: (current_counts[profile], proposed_counts[profile])
        for profile in current_counts
        if proposed_counts[profile] < current_counts[profile]
    }
    if reductions:
        raise ImmutablePinError(
            f"proposed capacity contract removes replicas: {reductions}"
        )
    if (
        protected_capacity_marker_path is None
        or protected_capacity_marker_sha256 is None
        or protected_capacity_marker_id is None
        or static_feasibility_certificate_path is None
        or static_feasibility_certificate_sha256 is None
        or static_feasibility_certificate_id is None
    ):
        raise ImmutablePinError(
            "capacity transition requires a same-generation protected marker "
            "and static feasibility certificate"
        )
    immutable = control["immutable"]
    expected_generation = int(control["capacity"]["current_generation"]) + 1
    try:
        capacity_contract = _load_protected_capacity_contract(
            control,
            path=protected_capacity_marker_path,
            expected_marker_id=str(protected_capacity_marker_id),
            expected_sha256=str(protected_capacity_marker_sha256),
        )
        protected_capacity.authorize_fleet(fleet, capacity_contract)
    except protected_capacity.ProtectedCapacityError as exc:
        raise ImmutablePinError(
            f"proposed protected-capacity authority failed closed: {exc}"
        ) from exc
    certificate_path = static_feasibility_certificate_path.expanduser().resolve()
    if (
        capacity_contract.capacity_generation != expected_generation
        or capacity_contract.effective_fleet_contract_path != resolved
        or capacity_contract.effective_fleet_contract_sha256 != expected_sha256
        or capacity_contract.base_fleet_contract_sha256
        != immutable["fleet_contract_sha256"]
        or capacity_contract.additive_overlay_contract_path != resolved
        or capacity_contract.additive_overlay_contract_sha256
        != expected_sha256
        or capacity_contract.static_feasibility_certificate_path
        != certificate_path
        or capacity_contract.static_feasibility_certificate_sha256
        != static_feasibility_certificate_sha256
        or capacity_contract.static_feasibility_certificate_id
        != static_feasibility_certificate_id
    ):
        raise ImmutablePinError(
            "proposed marker/certificate/fleet do not form one exact capacity "
            "generation"
        )
    authority = {
        "protected_capacity_marker_path": str(capacity_contract.path),
        "protected_capacity_marker_sha256": capacity_contract.sha256,
        "protected_capacity_marker_id": capacity_contract.marker_id,
        "static_feasibility_certificate_path": str(
            capacity_contract.static_feasibility_certificate_path
        ),
        "static_feasibility_certificate_sha256": (
            capacity_contract.static_feasibility_certificate_sha256
        ),
        "static_feasibility_certificate_id": (
            capacity_contract.static_feasibility_certificate_id
        ),
        "base_fleet_contract_sha256": (
            capacity_contract.base_fleet_contract_sha256
        ),
        "additive_overlay_contract_path": str(
            capacity_contract.additive_overlay_contract_path
        ),
        "additive_overlay_contract_sha256": (
            capacity_contract.additive_overlay_contract_sha256
        ),
    }
    return resolved, expected_sha256, fleet, proposed_counts, authority


def _complete_capacity_resume(
    state_dir: Path,
    *,
    transition_id: str,
    resume_callback: Callable[[Path], Mapping[str, Any]] | None,
    now: float,
) -> bool:
    """Resume once and open the generation epoch after the transition commit."""

    def validate_binding(
        control: Mapping[str, Any],
    ) -> tuple[Mapping[str, Any], dict[str, Any], str]:
        history = control["capacity"]["history"]
        matches = [
            row for row in history if row.get("transition_id") == transition_id
        ]
        if (
            len(matches) != 1
            or not history
            or history[-1] is not matches[0]
            or control["capacity"].get("active_transition") is not None
        ):
            raise ControlError(
                "completed capacity transition history is ambiguous or stale"
            )
        completed = matches[0]
        new_contract = completed.get("new_contract")
        current_contract = control["capacity"].get("current_contract")
        to_generation = completed.get("to_generation")
        if (
            completed.get("phase") != "completed"
            or not isinstance(to_generation, int)
            or isinstance(to_generation, bool)
            or to_generation != control["capacity"].get("current_generation")
            or not isinstance(new_contract, dict)
            or current_contract != new_contract
        ):
            raise ControlError(
                "completed capacity transition no longer binds current capacity"
            )
        binding = effective_fleet_contract_binding(control, verify_files=True)
        if (
            binding["capacity_generation"] != to_generation
            or binding["sha256"] != new_contract.get("sha256")
            or Path(str(binding["path"])).resolve()
            != Path(str(new_contract.get("path", ""))).resolve()
        ):
            raise ControlError(
                "completed capacity transition fleet binding drifted"
            )
        fleet_generation = (
            f"capacity-g{to_generation:06d}-"
            f"{str(binding['sha256'])[:16]}"
        )
        return completed, binding, fleet_generation

    initial = load_control(state_dir)
    completed, _binding, fleet_generation = validate_binding(initial)
    if completed.get("production_resume_state") == "complete":
        epoch_number = completed.get("throughput_epoch")
        epochs = initial["throughput_epochs"]
        if (
            not isinstance(epoch_number, int)
            or isinstance(epoch_number, bool)
            or epoch_number < 1
            or epoch_number > len(epochs)
            or epochs[epoch_number - 1].get("fleet_generation")
            != fleet_generation
            or epochs[epoch_number - 1].get("rollout_generation")
            != initial["rollout_generation"]
            or epochs[epoch_number - 1].get("closed_at") is not None
            or epoch_number != len(epochs)
        ):
            raise ControlError(
                "completed capacity resume throughput epoch is inconsistent"
            )
        return True
    if completed.get("production_resume_state") != "pending":
        raise ControlError("capacity transition resume state is invalid")
    if resume_callback is None:
        return False
    resumed = resume_callback(state_dir)
    if resumed.get("desired_state") != "running":
        raise ControlError("capacity transition resume did not publish running state")
    with control_lock(state_dir):
        control = load_control(state_dir)
        if control.get("desired_state") != "running":
            raise ControlError(
                "capacity resume callback returned before running was durable"
            )
        completed, binding, fleet_generation = validate_binding(control)
        if completed.get("production_resume_state") != "pending":
            raise ControlError("capacity transition resume state is invalid")
        epochs = control["throughput_epochs"]
        open_epoch = (
            epochs[-1] if epochs and epochs[-1].get("closed_at") is None else None
        )
        if open_epoch is not None:
            if open_epoch.get("fleet_generation") != fleet_generation:
                raise ControlError(
                    "unexpected throughput epoch was opened during capacity resume"
                )
        else:
            open_epoch = {
                "epoch": len(epochs) + 1,
                "rollout_generation": control["rollout_generation"],
                "fleet_generation": fleet_generation,
                "started_at": utc_timestamp(now),
                "started_timestamp": now,
                "closed_at": None,
                "samples": [],
            }
            epochs.append(open_epoch)
            append_transition(
                state_dir,
                control,
                event="throughput_epoch_started",
                details={
                    "epoch": open_epoch["epoch"],
                    "rollout_generation": control["rollout_generation"],
                    "fleet_generation": fleet_generation,
                    "reason": "capacity_transition",
                },
                now=now,
            )
        completed["production_resume_state"] = "complete"
        completed["resumed_at"] = utc_timestamp(now)
        completed["resumed_timestamp"] = now
        completed["throughput_epoch"] = int(open_epoch["epoch"])
        append_transition(
            state_dir,
            control,
            event="capacity_transition_resumed",
            details={
                "transition_id": transition_id,
                "capacity_generation": binding["capacity_generation"],
                "ceiling": 24,
                "throughput_epoch": open_epoch["epoch"],
            },
            now=now,
        )
        _save_control(state_dir, control, now=now)
    return True


def capacity_transition(
    state_dir: Path,
    *,
    action: str,
    fleet_contract_path: Path | None = None,
    fleet_contract_sha256: str | None = None,
    protected_capacity_marker_path: Path | None = None,
    protected_capacity_marker_sha256: str | None = None,
    protected_capacity_marker_id: str | None = None,
    static_feasibility_certificate_path: Path | None = None,
    static_feasibility_certificate_sha256: str | None = None,
    static_feasibility_certificate_id: str | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    fleet_evidence_reader: (
        Callable[[Mapping[str, Any]], Mapping[str, Any]] | None
    ) = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    fleet_launch_runner: (
        Callable[
            [Sequence[str], Mapping[str, str]], subprocess.CompletedProcess[str]
        ]
        | None
    ) = None,
    resume_callback: Callable[[Path], Mapping[str, Any]] | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Execute a crash-safe capacity generation transition.

    ``dry-run`` is read-only and requires an explicit checksummed contract. ``apply``
    seals that contract, commits exact retirement IDs before any ``scancel``, retires
    the hash-bound old transaction ledger, publishes the operational overlay, and
    invokes the same one-shot transactional fleet reconciler used by the supervisor.
    ``complete`` is the only path that can clear the operator hold and resume at 24.
    """

    if action not in {"status", "dry-run", "apply", "complete"}:
        raise ControlError(f"unknown capacity-transition action {action!r}")
    timestamp = time.time() if now is None else float(now)
    read_scheduler = scheduler_reader or (
        lambda: query_scheduler(tolerate_errors=False)
    )
    resolve_fleet = fleet_evidence_reader or _default_fleet_retirement_evidence
    cancel = cancel_runner or _run_subprocess
    # The CLI supplies this explicitly so injected read-only scheduler fixtures cannot
    # accidentally submit controller jobs.  This also makes the resume crash boundary
    # directly testable.
    resume = resume_callback

    with capacity_transition_lock(state_dir):
        if action == "status":
            control = load_control(state_dir)
            return {
                "action": action,
                "capacity": copy.deepcopy(control["capacity"]),
                "effective_fleet": effective_fleet_contract_binding(control),
                "admission_safety_hold": copy.deepcopy(
                    control["admission_safety_hold"]
                ),
            }
        if action == "complete":
            # A crash may occur after ``resume_control`` has durably published
            # ``running`` but before this workflow marks the resume receipt and opens
            # its throughput epoch.  That marker-only retry is intentionally valid in
            # the non-quiescent running state: the completed resume transaction has
            # already fenced scheduler identity.
            control = load_control(state_dir, verify_files=True)
            if control["capacity"]["active_transition"] is None:
                pending = [
                    row
                    for row in control["capacity"]["history"]
                    if row.get("phase") == "completed"
                    and row.get("production_resume_state") == "pending"
                ]
                if len(pending) != 1:
                    raise ControlError(
                        "capacity transition is not waiting for completion"
                    )
                transition_id = str(pending[0]["transition_id"])
                resumed = _complete_capacity_resume(
                    state_dir,
                    transition_id=transition_id,
                    resume_callback=resume,
                    now=timestamp,
                )
                return {
                    "action": action,
                    "completed": True,
                    "capacity_generation": pending[0]["to_generation"],
                    "resume_ceiling": 24,
                    "production_resumed": resumed,
                }
        with admission_boundary_lock(state_dir):
            snapshot = read_scheduler()
            _require_complete_quiescent_scheduler(
                snapshot, operation="capacity transition"
            )
            with control_lock(state_dir):
                control = load_control(state_dir, verify_files=True)
                pending_resumes = [
                    row
                    for row in control["capacity"]["history"]
                    if row.get("production_resume_state") == "pending"
                ]
                if action in {"dry-run", "apply"} and pending_resumes:
                    raise ControlError(
                        "a completed capacity transition still has a pending "
                        "production resume; retry capacity-transition complete"
                    )
                if (
                    control["desired_state"] != "paused"
                    or control.get("drain_requested") is not True
                ):
                    raise ControlError(
                        "capacity transition requires pause --drain to complete first"
                    )
                # Schema-1 controls created before this workflow remain readable and
                # acquire the overlay field on their first transition write.
                control["capacity"].setdefault("current_contract", None)
                active = copy.deepcopy(control["capacity"]["active_transition"])

            if action == "dry-run":
                if active is not None:
                    return {
                        "action": action,
                        "would_resume_transition": True,
                        "transition": active,
                    }
                (
                    proposed_path,
                    proposed_hash,
                    fleet,
                    proposed_counts,
                    proposed_authority,
                ) = (
                    _inspect_capacity_contract(
                        control,
                        path=fleet_contract_path,
                        expected_sha256=fleet_contract_sha256,
                        protected_capacity_marker_path=(
                            protected_capacity_marker_path
                        ),
                        protected_capacity_marker_sha256=(
                            protected_capacity_marker_sha256
                        ),
                        protected_capacity_marker_id=(
                            protected_capacity_marker_id
                        ),
                        static_feasibility_certificate_path=(
                            static_feasibility_certificate_path
                        ),
                        static_feasibility_certificate_sha256=(
                            static_feasibility_certificate_sha256
                        ),
                        static_feasibility_certificate_id=(
                            static_feasibility_certificate_id
                        ),
                    )
                )
                evidence = dict(resolve_fleet(control))
                job_ids = sorted(
                    (str(item) for item in evidence.get("old_fleet_job_ids", [])),
                    key=int,
                )
                if (
                    not all(item.isdigit() for item in job_ids)
                    or len(job_ids) != len(set(job_ids))
                ):
                    raise SchedulerAmbiguity(
                        "fleet retirement evidence contains invalid job IDs"
                    )
                return {
                    "action": action,
                    "dry_run": True,
                    "would_change": True,
                    "from_generation": control["capacity"]["current_generation"],
                    "to_generation": control["capacity"]["current_generation"] + 1,
                    "fleet_contract_path": str(proposed_path),
                    "fleet_contract_sha256": proposed_hash,
                    "logical_replicas": len(fleet.replicas),
                    "allocated_gpus": sum(
                        item.gpus_per_replica for item in fleet.replicas
                    ),
                    "profile_replicas": proposed_counts,
                    "protected_capacity": proposed_authority,
                    "old_fleet_job_ids": job_ids,
                    "fleet_evidence_sha256": sha256_value(evidence),
                }

            if action == "complete":
                if active is None:
                    pending = [
                        row
                        for row in control["capacity"]["history"]
                        if row.get("phase") == "completed"
                        and row.get("production_resume_state") == "pending"
                    ]
                    if len(pending) != 1:
                        raise ControlError(
                            "capacity transition is not waiting for completion"
                        )
                    transition_id = str(pending[0]["transition_id"])
                    resumed = _complete_capacity_resume(
                        state_dir,
                        transition_id=transition_id,
                        resume_callback=resume,
                        now=timestamp,
                    )
                    return {
                        "action": action,
                        "completed": True,
                        "capacity_generation": pending[0]["to_generation"],
                        "resume_ceiling": 24,
                        "production_resumed": resumed,
                    }
                if active.get("phase") != "readiness_pending":
                    raise ControlError(
                        "replacement fleet launch/readiness is not complete"
                    )
                old_live = sorted(
                    set(active["old_fleet_job_ids"]) & snapshot.active_job_ids,
                    key=int,
                )
                if old_live:
                    raise SchedulerAmbiguity(
                        f"old fleet jobs remain active: {old_live}"
                    )
                _capacity_gates_are_fresh(control, active)
                client_gate = control["admission_ramp"].get("capacity_gate")
                if isinstance(client_gate, Mapping):
                    authorization = _verified_client_capacity_authorization(
                        state_dir,
                        control,
                        target_ceiling=int(client_gate["target_ceiling"]),
                        attested_timestamp=timestamp,
                    )
                    if authorization is None:
                        raise ControlError(
                            "capacity transition cannot complete until the sealed "
                            "client-placement authorization, no-requeue canary, and "
                            "post-transition readiness evidence cover requested "
                            f"ceiling {client_gate['target_ceiling']}"
                        )
                    raise ControlError(
                        "verified client-capacity evidence must be attached with "
                        "attest-client-capacity before transition completion"
                    )
                validate_readiness(
                    control,
                    state_dir=state_dir,
                    verify_files=True,
                    now=timestamp,
                )
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    current = control["capacity"]["active_transition"]
                    if current != active:
                        raise ControlError(
                            "capacity transition changed during readiness validation"
                        )
                    critical = _active_critical_alerts(control)
                    if critical:
                        raise ControlError(
                            "capacity transition cannot complete with critical alerts: "
                            + ", ".join(critical)
                        )
                    completed = copy.deepcopy(current)
                    completed.update(
                        {
                            "phase": "completed",
                            "completed_at": utc_timestamp(timestamp),
                            "completed_timestamp": timestamp,
                            "production_resume_state": "pending",
                        }
                    )
                    control["capacity"]["history"].append(completed)
                    control["capacity"]["active_transition"] = None
                    control["drain_requested"] = False
                    control["drain_intent"] = None
                    _clear_capacity_operator_hold(
                        control["admission_safety_hold"],
                        transition_id=active["transition_id"],
                        now=timestamp,
                    )
                    _reset_admission_ramp(
                        state_dir,
                        control,
                        reason="capacity_transition_completed",
                        now=timestamp,
                        ceiling=24,
                        clear_last_observation=True,
                    )
                    append_transition(
                        state_dir,
                        control,
                        event="capacity_transition_completed",
                        details={
                            "transition_id": active["transition_id"],
                            "capacity_generation": active["to_generation"],
                            "resume_ceiling": 24,
                            "resume_pending": True,
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
                resumed = _complete_capacity_resume(
                    state_dir,
                    transition_id=active["transition_id"],
                    resume_callback=resume,
                    now=timestamp,
                )
                return {
                    "action": action,
                    "completed": True,
                    "capacity_generation": active["to_generation"],
                    "resume_ceiling": 24,
                    "production_resumed": resumed,
                }

            # ``apply``: establish the marker-last contract/archive and exact-ID intent.
            if active is None:
                (
                    proposed_path,
                    proposed_hash,
                    _fleet,
                    _counts,
                    proposed_authority,
                ) = (
                    _inspect_capacity_contract(
                        control,
                        path=fleet_contract_path,
                        expected_sha256=fleet_contract_sha256,
                        protected_capacity_marker_path=(
                            protected_capacity_marker_path
                        ),
                        protected_capacity_marker_sha256=(
                            protected_capacity_marker_sha256
                        ),
                        protected_capacity_marker_id=(
                            protected_capacity_marker_id
                        ),
                        static_feasibility_certificate_path=(
                            static_feasibility_certificate_path
                        ),
                        static_feasibility_certificate_sha256=(
                            static_feasibility_certificate_sha256
                        ),
                        static_feasibility_certificate_id=(
                            static_feasibility_certificate_id
                        ),
                    )
                )
                evidence = dict(resolve_fleet(control))
                job_ids = [str(item) for item in evidence.get("old_fleet_job_ids", [])]
                if (
                    not all(item.isdigit() for item in job_ids)
                    or len(job_ids) != len(set(job_ids))
                ):
                    raise SchedulerAmbiguity(
                        "fleet retirement evidence contains invalid job IDs"
                    )
                job_ids = sorted(job_ids, key=int)
                from_generation = int(control["capacity"]["current_generation"])
                to_generation = from_generation + 1
                transition_id = (
                    f"capacity-g{from_generation:06d}-to-g{to_generation:06d}-"
                    + hashlib.sha256(
                        canonical_json(
                            {
                                "immutable_sha256": control["immutable_sha256"],
                                "current_fleet": effective_fleet_contract_binding(
                                    control
                                )["sha256"],
                                "new_fleet": proposed_hash,
                                "protected_capacity_marker": (
                                    proposed_authority[
                                        "protected_capacity_marker_sha256"
                                    ]
                                ),
                                "static_feasibility_certificate": (
                                    proposed_authority[
                                        "static_feasibility_certificate_sha256"
                                    ]
                                ),
                                "job_ids": job_ids,
                            }
                        )
                    ).hexdigest()[:16]
                )
                archive_root, archive_sha256 = _create_capacity_archive(
                    state_dir,
                    control,
                    transition_id=transition_id,
                    now=timestamp,
                )
                contract_record = _seal_capacity_contract(
                    state_dir,
                    control,
                    transition_id=transition_id,
                    to_generation=to_generation,
                    source_path=proposed_path,
                    expected_sha256=proposed_hash,
                    protected_capacity_authority=proposed_authority,
                    now=timestamp,
                )
                evidence_sha = sha256_value(evidence)
                incident_intent = sorted(
                    set(control["admission_safety_hold"].get("reasons", ()))
                    & CAPACITY_REMEDIATION_ALERT_KEYS
                )
                (
                    retirement_path,
                    retirement_sha,
                    consumed_capacity_incidents,
                ) = (
                    _write_capacity_retirement_intent(
                        state_dir,
                        control,
                        transition_id=transition_id,
                        from_generation=from_generation,
                        to_generation=to_generation,
                        old_fleet_job_ids=job_ids,
                        fleet_evidence_sha256=evidence_sha,
                        consumed_capacity_incidents=incident_intent,
                    )
                )
                invalidated = (
                    "static_feasibility_certificate",
                    "protected_capacity",
                    "fleet",
                    "smoke_runs",
                    "scheduler_reconciliation",
                )
                active = {
                    "transition_id": transition_id,
                    "phase": "retirement_requested",
                    "from_generation": from_generation,
                    "to_generation": to_generation,
                    "created_at": utc_timestamp(timestamp),
                    "created_timestamp": timestamp,
                    "old_fleet_job_ids": job_ids,
                    "fleet_evidence_sha256": evidence_sha,
                    "archive_path": str(archive_root),
                    "archive_sha256": archive_sha256,
                    "retirement_intent_path": str(retirement_path),
                    "retirement_intent_sha256": retirement_sha,
                    "retirement_attempts": 0,
                    "retirement_results": {},
                    "last_retirement_error": None,
                    "new_contract": contract_record,
                    "fleet_launch_attempts": 0,
                    "fleet_launch_results": [],
                    "last_fleet_launch_error": None,
                    "invalidated_readiness": list(invalidated),
                    "consumed_capacity_incidents": (
                        consumed_capacity_incidents
                    ),
                }
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    control["capacity"].setdefault("current_contract", None)
                    if control["capacity"]["active_transition"] is not None:
                        raise ControlError(
                            "another capacity transition was published concurrently"
                        )
                    _close_open_epoch(
                        control, reason="capacity_transition", now=timestamp
                    )
                    _reset_admission_ramp(
                        state_dir,
                        control,
                        reason="capacity_transition",
                        now=timestamp,
                        ceiling=24,
                        clear_last_observation=True,
                    )
                    consumed_capacity_incidents = (
                        _consume_capacity_remediation_incidents_locked(
                            state_dir,
                            control,
                            transition_id=transition_id,
                            incident_keys=active[
                                "consumed_capacity_incidents"
                            ],
                            now=timestamp,
                        )
                    )
                    _activate_operator_hold(
                        control["admission_safety_hold"],
                        reason=f"capacity-transition:{transition_id}",
                        now=timestamp,
                    )
                    for gate in invalidated:
                        control["readiness"][gate] = {
                            "passed": False,
                            "evidence": None,
                            "attested_at": None,
                        }
                    control["capacity"]["active_transition"] = copy.deepcopy(active)
                    _append_capacity_transition_event_once(
                        state_dir,
                        control,
                        event="capacity_transition_retirement_committed",
                        details={
                            "transition_id": transition_id,
                            "old_fleet_job_ids": job_ids,
                            "retirement_intent": str(retirement_path),
                            "retirement_intent_sha256": retirement_sha,
                            "new_fleet_contract_sha256": proposed_hash,
                            "archive_path": str(archive_root),
                            "archive_sha256": archive_sha256,
                            "consumed_capacity_incidents": (
                                consumed_capacity_incidents
                            ),
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)

            if active.get("phase") == "retirement_requested":
                live_old_ids = sorted(
                    set(active["old_fleet_job_ids"]) & snapshot.active_job_ids,
                    key=int,
                )
                results: dict[str, Any] = {}
                error: str | None = None
                attempts_path = (
                    state_dir
                    / "capacity-transitions"
                    / active["transition_id"]
                    / CAPACITY_RETIREMENT_ATTEMPTS
                )
                for job_id in live_old_ids:
                    proc = cancel(["scancel", job_id])
                    result = {
                        "job_id": job_id,
                        "returncode": int(proc.returncode),
                        "stderr": proc.stderr.strip()[:1000],
                        "at": utc_timestamp(timestamp),
                        "timestamp": timestamp,
                    }
                    _append_jsonl(attempts_path, result)
                    results[job_id] = result
                    if proc.returncode != 0 and error is None:
                        error = (
                            f"failed exact fleet retirement {job_id}: "
                            f"{proc.stderr.strip()[:500]}"
                        )
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    current = control["capacity"]["active_transition"]
                    if (
                        not isinstance(current, dict)
                        or current.get("transition_id") != active["transition_id"]
                    ):
                        raise ControlError(
                            "capacity transition changed during exact retirement"
                        )
                    current["retirement_attempts"] += 1
                    current["retirement_results"].update(results)
                    current["last_retirement_error"] = error
                    append_transition(
                        state_dir,
                        control,
                        event="capacity_transition_retirement_attempted",
                        details={
                            "transition_id": active["transition_id"],
                            "target_job_ids": live_old_ids,
                            "error": error,
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
                if error is not None:
                    raise ControlError(error)
                fresh = read_scheduler()
                _require_complete_quiescent_scheduler(
                    fresh, operation="capacity transition publication"
                )
                remaining = sorted(
                    set(active["old_fleet_job_ids"]) & fresh.active_job_ids,
                    key=int,
                )
                if remaining:
                    return {
                        "action": action,
                        "transition_id": active["transition_id"],
                        "retirement_requested": True,
                        "remaining_old_fleet_job_ids": remaining,
                    }
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    current = control["capacity"]["active_transition"]
                    if (
                        not isinstance(current, dict)
                        or current.get("transition_id") != active["transition_id"]
                    ):
                        raise ControlError(
                            "capacity transition changed before generation publication"
                        )
                    _retire_fleet_transaction_state(
                        state_dir,
                        control,
                        transition_id=active["transition_id"],
                        now=timestamp,
                    )
                    current["phase"] = "fleet_launch_pending"
                    current["last_retirement_error"] = None
                    current["published_at"] = utc_timestamp(timestamp)
                    current["published_timestamp"] = timestamp
                    control["capacity"]["current_generation"] = current["to_generation"]
                    control["capacity"]["current_contract"] = copy.deepcopy(
                        current["new_contract"]
                    )
                    append_transition(
                        state_dir,
                        control,
                        event="capacity_generation_published",
                        details={
                            "transition_id": current["transition_id"],
                            "capacity_generation": current["to_generation"],
                            "fleet_contract_sha256": current["new_contract"]["sha256"],
                            "logical_replicas": current["new_contract"][
                                "logical_replicas"
                            ],
                            "allocated_gpus": current["new_contract"][
                                "allocated_gpus"
                            ],
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
                    active = copy.deepcopy(current)

            if active.get("phase") == "fleet_launch_pending":
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    current = control["capacity"]["active_transition"]
                    if (
                        not isinstance(current, dict)
                        or current.get("transition_id") != active["transition_id"]
                    ):
                        raise ControlError("capacity launch intent changed")
                    current["fleet_launch_attempts"] += 1
                    attempt_number = int(current["fleet_launch_attempts"])
                    current["last_fleet_launch_error"] = "launch_in_progress"
                    append_transition(
                        state_dir,
                        control,
                        event="capacity_fleet_launch_started",
                        details={
                            "transition_id": active["transition_id"],
                            "attempt": attempt_number,
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
                launch = _launch_capacity_fleet_once(
                    state_dir,
                    load_control(state_dir, verify_files=True),
                    transition=active,
                    runner=fleet_launch_runner,
                )
                launch_record = {
                    "attempt": attempt_number,
                    "returncode": int(launch.returncode),
                    "stdout": launch.stdout.strip()[-2000:],
                    "stderr": launch.stderr.strip()[-2000:],
                    "at": utc_timestamp(timestamp),
                    "timestamp": timestamp,
                }
                _append_jsonl(
                    state_dir
                    / "capacity-transitions"
                    / active["transition_id"]
                    / CAPACITY_FLEET_LAUNCH_ATTEMPTS,
                    launch_record,
                )
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    current = control["capacity"]["active_transition"]
                    if (
                        not isinstance(current, dict)
                        or current.get("transition_id") != active["transition_id"]
                        or current.get("phase") != "fleet_launch_pending"
                    ):
                        raise ControlError(
                            "capacity transition changed during fleet launch"
                        )
                    current["fleet_launch_results"].append(launch_record)
                    current["last_fleet_launch_error"] = (
                        None
                        if launch.returncode == 0
                        else f"one-shot fleet reconcile rc={launch.returncode}"
                    )
                    if launch.returncode == 0:
                        current["phase"] = "readiness_pending"
                        current["fleet_launch_completed_at"] = utc_timestamp(timestamp)
                        current["fleet_launch_completed_timestamp"] = timestamp
                    append_transition(
                        state_dir,
                        control,
                        event="capacity_fleet_launch_finished",
                        details={
                            "transition_id": active["transition_id"],
                            "attempt": attempt_number,
                            "returncode": int(launch.returncode),
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
                    active = copy.deepcopy(current)
                if launch.returncode != 0:
                    raise ControlError(
                        "replacement fleet transactional launch failed; retry apply: "
                        + launch.stderr.strip()[:500]
                    )

            return {
                "action": action,
                "transition_id": active["transition_id"],
                "capacity_generation": active["to_generation"],
                "fleet_contract_sha256": active["new_contract"]["sha256"],
                "replacement_launch_complete": (
                    active.get("phase") == "readiness_pending"
                ),
                "readiness_pending": list(active["invalidated_readiness"]),
            }


def _validate_final_fleet_retirement_evidence(
    control: Mapping[str, Any], evidence: Mapping[str, Any]
) -> list[str]:
    """Validate the complete ledger/squeue/sacct join used to freeze exact IDs."""

    expected_fields = {
        "pool_root",
        "pool_id",
        "fleet_sha256",
        "ledger_generation",
        "scheduler_captured_timestamp",
        "active_allocations",
        "old_fleet_job_ids",
    }
    if not isinstance(evidence, dict) or set(evidence) != expected_fields:
        raise SchedulerAmbiguity(
            "final fleet retirement evidence has the wrong fields"
        )
    pool_id, replica_profiles, _, _ = (
        _fleet_contract_reconciliation_identity(control)
    )
    ledger_generation = evidence.get("ledger_generation")
    captured = evidence.get("scheduler_captured_timestamp")
    allocations = evidence.get("active_allocations")
    if (
        evidence.get("pool_root")
        != str(Path(control["immutable"]["server_pool_root"]).resolve())
        or evidence.get("pool_id") != pool_id
        or evidence.get("fleet_sha256")
        != effective_fleet_contract_binding(control, verify_files=True)["sha256"]
        or not isinstance(ledger_generation, int)
        or isinstance(ledger_generation, bool)
        or ledger_generation < 1
        or not isinstance(captured, (int, float))
        or isinstance(captured, bool)
        or captured < 0
        or not isinstance(allocations, list)
    ):
        raise SchedulerAmbiguity(
            "final fleet retirement evidence does not bind the frozen fleet"
        )
    allocation_fields = {
        "job_id",
        "replica_id",
        "profile",
        "ledger_generation",
        "scheduler_state",
        "intent_token",
        "sbatch_path",
        "sbatch_sha256",
    }
    observed_job_ids: list[str] = []
    observed_replicas: set[str] = set()
    for allocation in allocations:
        if not isinstance(allocation, dict) or set(allocation) != allocation_fields:
            raise SchedulerAmbiguity(
                "final fleet retirement allocation evidence is malformed"
            )
        job_id = str(allocation.get("job_id", ""))
        replica_id = str(allocation.get("replica_id", ""))
        allocation_generation = allocation.get("ledger_generation")
        sbatch_path = Path(str(allocation.get("sbatch_path", ""))).expanduser()
        if (
            not job_id.isdigit()
            or replica_id not in replica_profiles
            or replica_id in observed_replicas
            or allocation.get("profile") != replica_profiles[replica_id]
            # A healthy current fleet may legitimately contain allocations adopted
            # from older sealed generations.  The transactional reconciliation that
            # builds this evidence already binds every allocation to its exact
            # generation ledger and intent.  Reject only future/invalid generations;
            # requiring every live replica to come from CURRENT would make a rolling
            # supervisor generation impossible to finalize.
            or not isinstance(allocation_generation, int)
            or isinstance(allocation_generation, bool)
            or allocation_generation < 1
            or allocation_generation > ledger_generation
            or normalize_scheduler_state(str(allocation.get("scheduler_state", "")))
            not in ACTIVE_SCHEDULER_STATES
            or re.fullmatch(
                r"[0-9a-f]{32}", str(allocation.get("intent_token", ""))
            )
            is None
            or not sbatch_path.is_absolute()
            or sbatch_path.is_symlink()
            or not sbatch_path.is_file()
            or _SHA256_RE.fullmatch(
                str(allocation.get("sbatch_sha256", ""))
            )
            is None
            or sha256_file(sbatch_path) != allocation.get("sbatch_sha256")
        ):
            raise SchedulerAmbiguity(
                f"final fleet retirement allocation is untrusted: {replica_id!r}"
            )
        observed_job_ids.append(job_id)
        observed_replicas.add(replica_id)
    job_ids = evidence.get("old_fleet_job_ids")
    if (
        not isinstance(job_ids, list)
        or not all(isinstance(job_id, str) and job_id.isdigit() for job_id in job_ids)
        or len(job_ids) != len(set(job_ids))
        or job_ids != sorted(job_ids, key=int)
        or set(job_ids) != set(observed_job_ids)
        or len(observed_job_ids) != len(set(observed_job_ids))
    ):
        raise SchedulerAmbiguity(
            "final fleet retirement evidence does not map exact unique job IDs"
        )
    return list(job_ids)


def _active_fleet_scope_job_ids(
    control: Mapping[str, Any], snapshot: SchedulerSnapshot
) -> list[str]:
    """Return every active job in the frozen fleet namespace, including malformed ones."""

    _, _, replica_job_names, _ = _fleet_contract_reconciliation_identity(control)
    expected_names = set(replica_job_names.values())
    scoped = {
        job.job_id
        for job in snapshot.jobs
        if job.active
        and (
            job.job_name in expected_names
            or job.comment.startswith("asys-s5-fleet:")
        )
    }
    malformed = sorted(job_id for job_id in scoped if not job_id.isdigit())
    if malformed:
        raise SchedulerAmbiguity(
            f"canonical fleet scope contains malformed job IDs: {malformed}"
        )
    return sorted(scoped, key=int)


def _validate_final_fleet_retirement_intent(
    control: Mapping[str, Any],
    intent: Mapping[str, Any],
    *,
    retirement_root: Path,
) -> list[str]:
    expected_fields = {
        "schema_version",
        "kind",
        "release_id",
        "immutable_sha256",
        "capacity_generation",
        "created_at",
        "created_timestamp",
        "exact_job_ids",
        "semantic_preflight",
        "semantic_preflight_sha256",
        "semantic_report_sha256",
        "fleet_evidence",
        "fleet_evidence_sha256",
        "retirement_id",
    }
    without_id = dict(intent)
    retirement_id = without_id.pop("retirement_id", None)
    semantic_preflight_path = (
        retirement_root.parent / FINAL_SEMANTIC_PREFLIGHT_FILENAME
    ).resolve()
    if (
        semantic_preflight_path.is_symlink()
        or not semantic_preflight_path.is_file()
        or semantic_preflight_path.stat().st_mode & 0o222
    ):
        raise ControlError(
            "final fleet retirement intent lacks sealed semantic preflight"
        )
    semantic_preflight_sha256 = sha256_file(semantic_preflight_path)
    if (
        not isinstance(intent, dict)
        or set(intent) != expected_fields
        or intent.get("schema_version") != 1
        or intent.get("kind") != "schema5_final_fleet_retirement_intent"
        or intent.get("release_id") != control["immutable"]["release_id"]
        or intent.get("immutable_sha256") != control["immutable_sha256"]
        or intent.get("capacity_generation")
        != control["capacity"]["current_generation"]
        or not isinstance(intent.get("created_timestamp"), (int, float))
        or isinstance(intent.get("created_timestamp"), bool)
        or intent.get("created_at")
        != utc_timestamp(float(intent.get("created_timestamp", -1)))
        or Path(str(intent.get("semantic_preflight", ""))).resolve()
        != semantic_preflight_path
        or intent.get("semantic_preflight_sha256")
        != semantic_preflight_sha256
        or retirement_id != sha256_value(without_id)
    ):
        raise ControlError("final fleet retirement intent is invalid")
    _, report_sha256, _, _ = _verify_final_semantic_preflight(
        retirement_root.parent,
        control=control,
    )
    if intent.get("semantic_report_sha256") != report_sha256:
        raise ControlError(
            "final fleet retirement intent semantic preflight drifted"
        )
    evidence = intent.get("fleet_evidence")
    if not isinstance(evidence, dict):
        raise ControlError("final fleet retirement intent lacks fleet evidence")
    job_ids = _validate_final_fleet_retirement_evidence(control, evidence)
    if (
        intent.get("fleet_evidence_sha256") != sha256_value(evidence)
        or intent.get("exact_job_ids") != job_ids
    ):
        raise ControlError("final fleet retirement intent evidence identity drifted")
    return job_ids


def _prepare_final_fleet_retirement(
    control: Mapping[str, Any],
    *,
    final_root: Path,
    snapshot: SchedulerSnapshot,
    semantic_preflight_path: Path,
    semantic_report_sha256: str,
    fleet_evidence_reader: Callable[
        [Mapping[str, Any]], Mapping[str, Any]
    ],
    now: float,
) -> tuple[Path, dict[str, Any]]:
    """Publish or adopt the immutable exact-ID intent before the first scancel."""

    retirement_root = final_root / FINAL_FLEET_RETIREMENT_DIRNAME
    if retirement_root.is_symlink() or (
        retirement_root.exists() and not retirement_root.is_dir()
    ):
        raise ControlError(
            f"final fleet retirement root is unsafe: {retirement_root}"
        )
    retirement_root.mkdir(parents=True, exist_ok=True)
    intent_path = retirement_root / FINAL_FLEET_RETIREMENT_INTENT_FILENAME
    complete_path = retirement_root / FINAL_FLEET_RETIREMENT_COMPLETE_FILENAME
    expected_preflight = (
        final_root / FINAL_SEMANTIC_PREFLIGHT_FILENAME
    ).resolve()
    verified_report_sha256: str | None = None
    verified_preflight_sha256: str | None = None
    if semantic_preflight_path.is_file() and not semantic_preflight_path.is_symlink():
        (
            _report,
            verified_report_sha256,
            _preflight,
            verified_preflight_sha256,
        ) = _verify_final_semantic_preflight(
            final_root,
            control=control,
        )
    if (
        semantic_preflight_path.resolve() != expected_preflight
        or semantic_preflight_path.is_symlink()
        or not semantic_preflight_path.is_file()
        or semantic_preflight_path.stat().st_mode & 0o222
        or sha256_file(semantic_preflight_path) != verified_preflight_sha256
        or semantic_report_sha256 != verified_report_sha256
    ):
        raise ControlError(
            "fleet retirement requires the sealed final semantic preflight"
        )

    evidence = dict(fleet_evidence_reader(control))
    current_ids = _validate_final_fleet_retirement_evidence(control, evidence)
    scoped_ids = _active_fleet_scope_job_ids(control, snapshot)
    if scoped_ids != current_ids:
        raise SchedulerAmbiguity(
            "final fleet scheduler snapshots disagree with the durable ledger join: "
            f"control={scoped_ids}, fleet={current_ids}"
        )
    if intent_path.exists():
        if intent_path.is_symlink() or not intent_path.is_file():
            raise ControlError("final fleet retirement intent is unsafe")
        intent = _load_json_object(
            intent_path, description="final fleet retirement intent"
        )
        exact_ids = _validate_final_fleet_retirement_intent(
            control,
            intent,
            retirement_root=retirement_root,
        )
        unexpected = sorted(set(current_ids) - set(exact_ids), key=int)
        if unexpected:
            raise SchedulerAmbiguity(
                "a new canonical fleet allocation appeared after final retirement "
                f"was committed: {unexpected}"
            )
    else:
        unexpected_entries = sorted(
            path.name
            for path in retirement_root.iterdir()
            if path.name
            not in {
                FINAL_FLEET_RETIREMENT_ATTEMPTS_FILENAME,
                FINAL_FLEET_RETIREMENT_COMPLETE_FILENAME,
            }
        )
        if unexpected_entries:
            raise ControlError(
                "unrecognized partial final fleet retirement state: "
                + ", ".join(unexpected_entries)
            )
        intent = {
            "schema_version": 1,
            "kind": "schema5_final_fleet_retirement_intent",
            "release_id": control["immutable"]["release_id"],
            "immutable_sha256": control["immutable_sha256"],
            "capacity_generation": control["capacity"]["current_generation"],
            "created_at": utc_timestamp(now),
            "created_timestamp": now,
            "exact_job_ids": current_ids,
            "semantic_preflight": str(semantic_preflight_path.resolve()),
            "semantic_preflight_sha256": sha256_file(
                semantic_preflight_path
            ),
            "semantic_report_sha256": semantic_report_sha256,
            "fleet_evidence": evidence,
            "fleet_evidence_sha256": sha256_value(evidence),
        }
        intent["retirement_id"] = sha256_value(intent)
        _atomic_publish_readonly_json(intent_path, intent)
    if complete_path.exists():
        _verify_final_fleet_retirement(retirement_root, control=control)
    return retirement_root, intent


def _validate_final_fleet_retirement_attempts(
    path: Path, *, retirement_id: str, exact_job_ids: Sequence[str]
) -> list[dict[str, Any]]:
    attempts = _read_jsonl_locked(path)
    expected_targets = set(exact_job_ids)
    expected_fields = {
        "schema_version",
        "kind",
        "retirement_id",
        "attempt",
        "started_at",
        "started_timestamp",
        "target_job_ids",
        "results",
        "exception",
        "post_scheduler_captured_timestamp",
        "remaining_job_ids",
    }
    for index, attempt in enumerate(attempts, start=1):
        targets = attempt.get("target_job_ids")
        results = attempt.get("results")
        remaining = attempt.get("remaining_job_ids")
        if (
            set(attempt) != expected_fields
            or attempt.get("schema_version") != 1
            or attempt.get("kind") != "schema5_final_fleet_retirement_attempt"
            or attempt.get("retirement_id") != retirement_id
            or attempt.get("attempt") != index
            or not isinstance(attempt.get("started_timestamp"), (int, float))
            or isinstance(attempt.get("started_timestamp"), bool)
            or attempt.get("started_at")
            != utc_timestamp(float(attempt.get("started_timestamp", -1)))
            or not isinstance(targets, list)
            or not all(isinstance(job_id, str) for job_id in targets)
            or len(targets) != len(set(targets))
            or not set(targets).issubset(expected_targets)
            or not isinstance(results, dict)
            or not set(results).issubset(set(targets))
            or attempt.get("exception") is not None
            and not isinstance(attempt.get("exception"), str)
            or (
                attempt.get("post_scheduler_captured_timestamp") is not None
                and (
                    not isinstance(
                        attempt.get("post_scheduler_captured_timestamp"),
                        (int, float),
                    )
                    or isinstance(
                        attempt.get("post_scheduler_captured_timestamp"), bool
                    )
                )
            )
            or (
                remaining is not None
                and (
                    not isinstance(remaining, list)
                    or not set(remaining).issubset(expected_targets)
                )
            )
        ):
            raise ControlError("final fleet retirement attempt journal is invalid")
        for job_id, result in results.items():
            if (
                not isinstance(result, dict)
                or set(result) != {"returncode", "stderr"}
                or not isinstance(result.get("returncode"), int)
                or not isinstance(result.get("stderr"), str)
            ):
                raise ControlError(
                    f"final fleet retirement result is invalid for {job_id}"
                )
    return attempts


def _verify_final_fleet_retirement(
    retirement_root: Path, *, control: Mapping[str, Any]
) -> tuple[dict[str, Any], str]:
    intent_path = retirement_root / FINAL_FLEET_RETIREMENT_INTENT_FILENAME
    attempts_path = retirement_root / FINAL_FLEET_RETIREMENT_ATTEMPTS_FILENAME
    marker_path = retirement_root / FINAL_FLEET_RETIREMENT_COMPLETE_FILENAME
    intent = _load_json_object(intent_path, description="final fleet retirement intent")
    exact_ids = _validate_final_fleet_retirement_intent(
        control,
        intent,
        retirement_root=retirement_root,
    )
    attempts = _validate_final_fleet_retirement_attempts(
        attempts_path,
        retirement_id=str(intent["retirement_id"]),
        exact_job_ids=exact_ids,
    )
    marker = _load_json_object(
        marker_path, description="final fleet retirement completion marker"
    )
    expected_fields = {
        "schema_version",
        "kind",
        "complete",
        "release_id",
        "immutable_sha256",
        "capacity_generation",
        "retirement_id",
        "intent_sha256",
        "retired_job_ids",
        "attempt_count",
        "attempts_sha256",
        "scheduler_captured_timestamp",
        "completed_at",
        "completed_timestamp",
        "completion_id",
    }
    without_id = dict(marker)
    completion_id = without_id.pop("completion_id", None)
    if (
        set(marker) != expected_fields
        or marker.get("schema_version") != 1
        or marker.get("kind") != "schema5_final_fleet_retirement"
        or marker.get("complete") is not True
        or marker.get("release_id") != control["immutable"]["release_id"]
        or marker.get("immutable_sha256") != control["immutable_sha256"]
        or marker.get("capacity_generation")
        != control["capacity"]["current_generation"]
        or marker.get("retirement_id") != intent["retirement_id"]
        or marker.get("intent_sha256") != sha256_file(intent_path)
        or marker.get("retired_job_ids") != exact_ids
        or marker.get("attempt_count") != len(attempts)
        or marker.get("attempts_sha256") != sha256_file(attempts_path)
        or not isinstance(marker.get("scheduler_captured_timestamp"), (int, float))
        or isinstance(marker.get("scheduler_captured_timestamp"), bool)
        or not isinstance(marker.get("completed_timestamp"), (int, float))
        or isinstance(marker.get("completed_timestamp"), bool)
        or marker.get("completed_at")
        != utc_timestamp(float(marker.get("completed_timestamp", -1)))
        or completion_id != sha256_value(without_id)
    ):
        raise ControlError("final fleet retirement completion marker is invalid")
    if (
        retirement_root.stat().st_mode & 0o222
        or any(
            path.is_symlink() or path.stat().st_mode & 0o222
            for path in (intent_path, attempts_path, marker_path)
        )
    ):
        raise ControlError("final fleet retirement evidence is not sealed read-only")
    return marker, sha256_file(marker_path)


def _advance_final_fleet_retirement(
    retirement_root: Path,
    control: Mapping[str, Any],
    *,
    scheduler_reader: Callable[[], SchedulerSnapshot],
    cancel_runner: Callable[[Sequence[str]], subprocess.CompletedProcess[str]],
    now: float,
) -> tuple[dict[str, Any] | None, list[str]]:
    """Retire only marker-pinned IDs, then marker-last seal zero-fleet proof."""

    intent_path = retirement_root / FINAL_FLEET_RETIREMENT_INTENT_FILENAME
    attempts_path = retirement_root / FINAL_FLEET_RETIREMENT_ATTEMPTS_FILENAME
    marker_path = retirement_root / FINAL_FLEET_RETIREMENT_COMPLETE_FILENAME
    intent = _load_json_object(intent_path, description="final fleet retirement intent")
    exact_ids = _validate_final_fleet_retirement_intent(
        control,
        intent,
        retirement_root=retirement_root,
    )
    if marker_path.exists():
        marker, _ = _verify_final_fleet_retirement(
            retirement_root, control=control
        )
        snapshot = scheduler_reader()
        _require_complete_quiescent_scheduler(
            snapshot, operation="completed final fleet retirement"
        )
        active = _active_fleet_scope_job_ids(control, snapshot)
        if active:
            raise SchedulerAmbiguity(
                f"canonical fleet reappeared after sealed retirement: {active}"
            )
        return marker, []

    snapshot = scheduler_reader()
    _require_complete_quiescent_scheduler(
        snapshot, operation="final fleet retirement"
    )
    active = _active_fleet_scope_job_ids(control, snapshot)
    unexpected = sorted(set(active) - set(exact_ids), key=int)
    if unexpected:
        raise SchedulerAmbiguity(
            "refusing to retire fleet IDs outside the marker-first intent: "
            f"{unexpected}"
        )
    targets = sorted(set(active) & set(exact_ids), key=int)
    prior_attempts = _read_jsonl_locked(attempts_path, missing_ok=True)
    attempt_number = len(prior_attempts) + 1
    results: dict[str, dict[str, Any]] = {}
    command_errors: list[str] = []
    retryable_exception: FinalizerRetryableError | None = None
    for job_id in targets:
        try:
            proc = cancel_runner(["scancel", job_id])
            results[job_id] = {
                "returncode": int(proc.returncode),
                "stderr": proc.stderr.strip()[:1000],
            }
            if proc.returncode != 0:
                command_errors.append(
                    f"failed exact final fleet retirement {job_id}: "
                    f"{proc.stderr.strip()[:500]}"
                )
        except FinalizerRetryableError as exc:
            retryable_exception = exc
            command_errors.append(f"{type(exc).__name__}: {exc}")
            break
        except subprocess.TimeoutExpired as exc:
            retryable_exception = FinalizerTimeoutError(
                f"exact fleet retirement command timed out: {exc}"
            )
            command_errors.append(
                f"{type(retryable_exception).__name__}: "
                f"{retryable_exception}"
            )
            break
        except TimeoutError as exc:
            retryable_exception = FinalizerTimeoutError(str(exc))
            command_errors.append(
                f"{type(retryable_exception).__name__}: "
                f"{retryable_exception}"
            )
            break
        except ConnectionError as exc:
            retryable_exception = FinalizerConnectionError(str(exc))
            command_errors.append(
                f"{type(retryable_exception).__name__}: "
                f"{retryable_exception}"
            )
            break

    post_snapshot: SchedulerSnapshot | None = None
    remaining: list[str] | None = None
    deterministic_error: FinalizerProvenanceError | None = None
    post_read_error: FinalizerSchedulerReadError | None = None
    try:
        post_snapshot = scheduler_reader()
        _require_complete_quiescent_scheduler(
            post_snapshot, operation="final fleet retirement verification"
        )
        post_active = _active_fleet_scope_job_ids(control, post_snapshot)
        unexpected = sorted(set(post_active) - set(exact_ids), key=int)
        if unexpected:
            deterministic_error = FinalizerProvenanceError(
                "new fleet IDs appeared during exact retirement: "
                + ", ".join(unexpected)
            )
        else:
            remaining = sorted(set(post_active) & set(exact_ids), key=int)
    except FinalizerProvenanceError as exc:
        deterministic_error = exc
    except Exception as exc:
        post_read_error = FinalizerSchedulerReadError(
            "cannot reconcile final fleet retirement through complete "
            f"post-command scheduler truth: {type(exc).__name__}: {exc}"
        )
        command_errors.append(
            f"{type(post_read_error).__name__}: {post_read_error}"
        )

    exception = "; ".join(command_errors) if command_errors else None
    if attempts_path.exists():
        attempts_path.chmod(0o644)
    attempt_record = {
        "schema_version": 1,
        "kind": "schema5_final_fleet_retirement_attempt",
        "retirement_id": intent["retirement_id"],
        "attempt": attempt_number,
        "started_at": utc_timestamp(now),
        "started_timestamp": now,
        "target_job_ids": targets,
        "results": results,
        "exception": exception,
        "post_scheduler_captured_timestamp": (
            post_snapshot.captured_at if post_snapshot is not None else None
        ),
        "remaining_job_ids": remaining,
    }
    _append_jsonl(attempts_path, attempt_record)
    if deterministic_error is not None:
        raise deterministic_error
    if post_read_error is not None:
        raise post_read_error
    assert post_snapshot is not None and remaining is not None
    if remaining:
        if retryable_exception is not None:
            raise retryable_exception
        if command_errors:
            raise FinalizerNodeError(
                "exact final fleet retirement remains active after scheduler "
                f"command errors: {remaining}; {exception}"
            )
        # A zero return from scancel is only an admission of the request, not proof
        # that the allocation has left scheduler truth.
        return None, remaining

    # Complete post-command truth is authoritative.  A nonzero scancel, timeout, or
    # natural-exit race is accepted when every marker-pinned allocation is terminal or
    # absent; no command return code alone can permanently block finalization.

    attempts = _validate_final_fleet_retirement_attempts(
        attempts_path,
        retirement_id=str(intent["retirement_id"]),
        exact_job_ids=exact_ids,
    )
    intent_path.chmod(0o444)
    attempts_path.chmod(0o444)
    marker = {
        "schema_version": 1,
        "kind": "schema5_final_fleet_retirement",
        "complete": True,
        "release_id": control["immutable"]["release_id"],
        "immutable_sha256": control["immutable_sha256"],
        "capacity_generation": control["capacity"]["current_generation"],
        "retirement_id": intent["retirement_id"],
        "intent_sha256": sha256_file(intent_path),
        "retired_job_ids": exact_ids,
        "attempt_count": len(attempts),
        "attempts_sha256": sha256_file(attempts_path),
        "scheduler_captured_timestamp": post_snapshot.captured_at,
        "completed_at": utc_timestamp(now),
        "completed_timestamp": now,
    }
    marker["completion_id"] = sha256_value(marker)
    _atomic_publish_readonly_json(marker_path, marker)
    retirement_root.chmod(0o555)
    verified, _ = _verify_final_fleet_retirement(
        retirement_root, control=control
    )
    return verified, []


class _FinalizerInterruptionController:
    """Own one finalizer child until a requested drain has fully reaped it."""

    def __init__(self) -> None:
        self.requested_signal: signal.Signals | None = None
        self.active_child: subprocess.Popen[str] | None = None

    @property
    def requested(self) -> bool:
        return self.requested_signal is not None

    def request(self, signum: int) -> None:
        observed = signal.Signals(signum)
        if self.requested_signal is None:
            self.requested_signal = observed
        child = self.active_child
        if child is not None and child.poll() is None:
            _signal_process_group(child, signal.SIGTERM)

    def register(self, child: subprocess.Popen[str]) -> None:
        if self.active_child is not None:
            raise FinalizerInvariantError(
                "finalizer interruption controller already owns a child"
            )
        self.active_child = child
        if self.requested and child.poll() is None:
            _signal_process_group(child, signal.SIGTERM)

    def release_reaped(self, child: subprocess.Popen[str]) -> None:
        if self.active_child is not child:
            raise FinalizerInvariantError(
                "finalizer interruption controller lost child ownership"
            )
        if child.poll() is None:
            raise FinalizerInvariantError(
                "finalizer child ownership was released before reap"
            )
        self.active_child = None

    def raise_if_requested(self) -> None:
        if self.requested_signal is not None:
            raise FinalizerInterruptedError(
                "autonomous finalizer received "
                f"{self.requested_signal.name}; active child was terminated and reaped"
            )


def _terminate_and_reap_finalizer_child(
    child: subprocess.Popen[str],
) -> tuple[str, str]:
    """TERM, bounded-wait, KILL, and reap one process group."""

    _signal_process_group(child, signal.SIGTERM)
    try:
        return child.communicate(
            timeout=FINALIZER_CHILD_TERMINATE_GRACE_SECONDS
        )
    except subprocess.TimeoutExpired:
        _signal_process_group(child, signal.SIGKILL)
        return child.communicate()


def _run_finalizer_process(
    argv: Sequence[str],
    *,
    environment: Mapping[str, str],
    timeout_seconds: float,
    interruption: _FinalizerInterruptionController | None = None,
) -> subprocess.CompletedProcess[str]:
    """Run one frozen stage while retaining ownership through TERM/KILL/reap."""

    if (
        not isinstance(timeout_seconds, (int, float))
        or isinstance(timeout_seconds, bool)
        or not math.isfinite(float(timeout_seconds))
        or float(timeout_seconds) <= 0
        or float(timeout_seconds) > FINALIZER_SNAPSHOT_DEADLINE_SECONDS
    ):
        raise FinalizerInvariantError(
            "finalizer subprocess deadline must be positive and no greater than "
            f"{FINALIZER_SNAPSHOT_DEADLINE_SECONDS:.0f}s"
        )
    controller = interruption or _FinalizerInterruptionController()
    controller.raise_if_requested()
    child = subprocess.Popen(
        list(argv),
        env=dict(environment),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        start_new_session=True,
    )
    try:
        controller.register(child)
    except BaseException:
        _terminate_and_reap_finalizer_child(child)
        raise
    deadline = time.monotonic() + float(timeout_seconds)
    stdout = ""
    stderr = ""
    failure: BaseException | None = None
    try:
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                stdout, stderr = _terminate_and_reap_finalizer_child(child)
                failure = FinalizerTimeoutError(
                    "finalizer command exceeded "
                    f"{timeout_seconds:.0f}s and was terminated: "
                    f"{shlex.join(list(argv))}; stderr={stderr.strip()[:500]}"
                )
                break
            try:
                stdout, stderr = child.communicate(
                    timeout=min(FINALIZER_CHILD_POLL_SECONDS, remaining)
                )
                if controller.requested:
                    failure = FinalizerInterruptedError(
                        "autonomous finalizer received "
                        f"{controller.requested_signal.name}; active child was "
                        "terminated and reaped"
                    )
                break
            except subprocess.TimeoutExpired:
                if controller.requested:
                    stdout, stderr = _terminate_and_reap_finalizer_child(child)
                    failure = FinalizerInterruptedError(
                        "autonomous finalizer received "
                        f"{controller.requested_signal.name}; active child was "
                        "terminated and reaped"
                    )
                    break
    finally:
        if child.poll() is None:
            stdout, stderr = _terminate_and_reap_finalizer_child(child)
        controller.release_reaped(child)
    if failure is not None:
        raise failure
    controller.raise_if_requested()
    return subprocess.CompletedProcess(
        list(argv), int(child.returncode), stdout, stderr
    )


@contextmanager
def _finalizer_signal_handlers(
    interruption: _FinalizerInterruptionController,
) -> Iterator[None]:
    """Translate Slurm USR1/TERM into bounded child drain requests."""

    if threading.current_thread() is not threading.main_thread():
        raise FinalizerInvariantError(
            "autonomous finalizer signal ownership requires the main thread"
        )

    def request_stop(signum: int, _frame: Any) -> None:
        interruption.request(signum)

    watched = (signal.SIGUSR1, signal.SIGTERM)
    previous = {sig: signal.signal(sig, request_stop) for sig in watched}
    try:
        yield
    finally:
        try:
            child = interruption.active_child
            if child is not None:
                if child.poll() is None:
                    _terminate_and_reap_finalizer_child(child)
                interruption.release_reaped(child)
        finally:
            # Retain USR1/TERM ownership until every child is gone.  Restoring the
            # default TERM disposition earlier would reopen the orphan window during
            # the bounded cleanup itself.
            for sig, handler in previous.items():
                signal.signal(sig, handler)


def _finalizer_environment(control: Mapping[str, Any]) -> dict[str, str]:
    immutable = control["immutable"]
    environment = _sanitized_subprocess_environment()
    for name in tuple(environment):
        if name.startswith(("PYTHON", "PIP_", "CONDA_")) or name == "VIRTUAL_ENV":
            environment.pop(name, None)
    environment.update(production_environment(control))
    environment.update(
        {
            "ASYS_RESULTS_ROOT": str(Path(immutable["results_root"]).resolve()),
            "ASYS_RELEASE_WORKTREE": str(
                Path(immutable["release_worktree"]).resolve()
            ),
            "ASYS_HARNESS_ENVIRONMENT_PREFIX": str(
                Path(immutable["harness_environment_prefix"]).resolve()
            ),
            "ASYS_HARNESS_ENVIRONMENT_SHA256": str(
                immutable["harness_environment_sha256"]
            ),
            "ASYS_IMMUTABLE_PINS_SHA256": str(control["immutable_sha256"]),
            "ASYS_MODEL_CONTRACT": str(
                Path(immutable["model_contract_path"]).resolve()
            ),
            "ASYS_MODEL_CONTRACT_SHA256": str(
                immutable["model_contract_sha256"]
            ),
            "ASYS_RELEASE_ID": str(immutable["release_id"]),
            "ASYS_RELEASE_GIT_COMMIT": str(immutable["git_commit"]),
            "ASYS_SOURCE_TREE_SHA256": str(immutable["source_tree_sha256"]),
            "PYTHONDONTWRITEBYTECODE": "1",
        }
    )
    return environment


_FINAL_TRANSPORT_ACCOUNTING_FIELDS = (
    "validated_qids",
    "useful_qids",
    "completed_qids",
    "length_censored_qids",
    "protocol_censored_qids",
    "transport_censored_qids",
    "transport_affected_qids",
    "topology_transport_censored_coordinates",
    "transport_censored_coordinates",
    "auxiliary_outcomes",
    "auxiliary_completed",
    "auxiliary_length_censored",
    "auxiliary_protocol_censored",
    "auxiliary_transport_censored",
)
_FINAL_INTEGRITY_OUTCOME_FIELDS = (
    "malformed_lines",
    "duplicate_qids",
    "unexpected_qids",
    "invalid_rows",
    "untrusted_valid_rows",
)
FINAL_AGGREGATE_OUTCOME_FIELDS = frozenset(
    (
        *_FINAL_TRANSPORT_ACCOUNTING_FIELDS,
        *_FINAL_INTEGRITY_OUTCOME_FIELDS,
        "stale_unmanifested_dirs",
        "contract_errors",
    )
)
FINAL_RUN_OUTCOME_FIELDS = frozenset(
    (
        *_FINAL_TRANSPORT_ACCOUNTING_FIELDS,
        *_FINAL_INTEGRITY_OUTCOME_FIELDS,
    )
)
FINAL_ACCEPTANCE_CHECK_NAMES = frozenset(
    {
        "exact_complete_cells",
        "no_noncomplete_cells",
        "exact_validated_qids",
        "top_level_partition_exact",
        "auxiliary_partition_exact",
        "useful_transport_partition_exact",
        "transport_coordinate_partition_exact",
        "topology_transport_coordinate_qid_bound",
        "transport_affected_qid_bounds_exact",
        "transport_protocol_exact",
        "zero_integrity_errors",
        "schema5_only",
        "throughput_projection_acceptable",
    }
)


def _validate_final_outcome_schema(
    outcomes: Any,
    *,
    expected_fields: frozenset[str],
    context: str,
) -> Mapping[str, int]:
    if not isinstance(outcomes, Mapping):
        raise ControlError(
            f"final semantic {context} outcomes must be an object"
        )
    observed_fields = set(outcomes)
    if observed_fields != expected_fields:
        raise ControlError(
            f"final semantic {context} outcome fields are not exact: "
            f"missing={sorted(expected_fields - observed_fields, key=repr)!r}, "
            f"unexpected={sorted(observed_fields - expected_fields, key=repr)!r}"
        )
    for field in sorted(expected_fields):
        value = outcomes[field]
        if (
            not isinstance(value, int)
            or isinstance(value, bool)
            or value < 0
        ):
            raise ControlError(
                f"final semantic {context} outcome {field} is not a "
                "non-negative integer"
            )
    return outcomes


def _recompute_final_acceptance_checks(
    *,
    semantic: Mapping[str, Any],
    outcomes: Mapping[str, int],
) -> dict[str, bool]:
    states = semantic["states"]
    transport_protocol = semantic["transport_censor_protocol"]
    integrity_errors = sum(
        outcomes[field]
        for field in (
            *_FINAL_INTEGRITY_OUTCOME_FIELDS,
            "stale_unmanifested_dirs",
            "contract_errors",
        )
    )
    return {
        "exact_complete_cells": (
            states.get("complete") == EXPECTED_TOTAL_CELLS
        ),
        "no_noncomplete_cells": (
            sum(
                count
                for state, count in states.items()
                if state != "complete"
            )
            == 0
        ),
        "exact_validated_qids": (
            outcomes["validated_qids"] == EXPECTED_TOTAL_QIDS
        ),
        "top_level_partition_exact": (
            outcomes["validated_qids"]
            == outcomes["completed_qids"]
            + outcomes["length_censored_qids"]
            + outcomes["protocol_censored_qids"]
            + outcomes["transport_censored_qids"]
        ),
        "auxiliary_partition_exact": (
            outcomes["auxiliary_outcomes"]
            == outcomes["auxiliary_completed"]
            + outcomes["auxiliary_length_censored"]
            + outcomes["auxiliary_protocol_censored"]
            + outcomes["auxiliary_transport_censored"]
        ),
        "useful_transport_partition_exact": (
            outcomes["validated_qids"]
            == outcomes["useful_qids"]
            + outcomes["transport_affected_qids"]
        ),
        "transport_coordinate_partition_exact": (
            outcomes["transport_censored_coordinates"]
            == outcomes["topology_transport_censored_coordinates"]
            + outcomes["auxiliary_transport_censored"]
        ),
        "topology_transport_coordinate_qid_bound": (
            outcomes["topology_transport_censored_coordinates"]
            >= outcomes["transport_censored_qids"]
        ),
        "transport_affected_qid_bounds_exact": (
            outcomes["transport_censored_qids"]
            <= outcomes["transport_affected_qids"]
            <= outcomes["transport_censored_coordinates"]
        ),
        "transport_protocol_exact": transport_protocol
        == {
            "version": TRANSPORT_CENSOR_PROTOCOL_VERSION,
            "hash": TRANSPORT_CENSOR_PROTOCOL_HASH,
        },
        "zero_integrity_errors": integrity_errors == 0,
        "schema5_only": semantic["artifact_schema_counts"]
        == {"5": EXPECTED_TOTAL_QIDS},
        # At exact terminal cardinality there is no unfinished stratum whose
        # projected throughput can invalidate completion.
        "throughput_projection_acceptable": (
            outcomes["validated_qids"] == EXPECTED_TOTAL_QIDS
        ),
    }


def _validate_final_semantic_report(report: Mapping[str, Any]) -> None:
    semantic = report.get("semantic")
    acceptance = report.get("final_acceptance")
    if (
        not isinstance(semantic, dict)
        or semantic.get("scan_successful") is not True
        or semantic.get("scan_errors") != []
        or not isinstance(acceptance, dict)
    ):
        raise ControlError("final semantic scan did not pass every acceptance check")
    if set(acceptance) != {"passed", "checks"}:
        raise ControlError("final semantic acceptance fields are not exact")
    reported_checks = acceptance.get("checks")
    if (
        not isinstance(acceptance.get("passed"), bool)
        or not isinstance(reported_checks, Mapping)
        or set(reported_checks) != FINAL_ACCEPTANCE_CHECK_NAMES
        or any(not isinstance(value, bool) for value in reported_checks.values())
    ):
        raise ControlError(
            "final semantic acceptance check names or types are not exact"
        )
    if acceptance["passed"] is not True:
        raise ControlError(
            "final semantic scan did not pass every acceptance check"
        )
    states = semantic.get("states")
    outcomes = _validate_final_outcome_schema(
        semantic.get("outcomes"),
        expected_fields=FINAL_AGGREGATE_OUTCOME_FIELDS,
        context="aggregate",
    )
    if (
        states != {"complete": EXPECTED_TOTAL_CELLS}
        or outcomes["validated_qids"] != EXPECTED_TOTAL_QIDS
        or semantic.get("artifact_schema_counts")
        != {"5": EXPECTED_TOTAL_QIDS}
    ):
        raise ControlError(
            "final semantic scan does not contain the exact 22,680/4,524,660 "
            "schema-5 result set"
        )
    if semantic.get("transport_censor_protocol") != {
        "version": TRANSPORT_CENSOR_PROTOCOL_VERSION,
        "hash": TRANSPORT_CENSOR_PROTOCOL_HASH,
    }:
        raise ControlError(
            "final semantic scan does not bind the frozen transport-censor protocol"
        )
    for name in (
        *_FINAL_INTEGRITY_OUTCOME_FIELDS,
        "stale_unmanifested_dirs",
        "contract_errors",
    ):
        if outcomes[name] != 0:
            raise ControlError(f"final semantic outcome {name} is nonzero")
    _validate_final_transport_accounting(
        outcomes,
        expected_qids=EXPECTED_TOTAL_QIDS,
        context="aggregate",
    )
    runs = semantic.get("runs")
    catalog_binding = semantic.get("trusted_generation_catalog")
    if (
        not isinstance(catalog_binding, dict)
        or set(catalog_binding)
        != {
            "catalog_id",
            "marker_path",
            "marker_sha256",
            "inventory_sha256",
            "catalog_payload_sha256",
            "allowed_generation_tuple_count",
        }
        or _SHA256_RE.fullmatch(str(catalog_binding.get("catalog_id", "")))
        is None
        or _SHA256_RE.fullmatch(
            str(catalog_binding.get("marker_sha256", ""))
        )
        is None
        or _SHA256_RE.fullmatch(
            str(catalog_binding.get("inventory_sha256", ""))
        )
        is None
        or _SHA256_RE.fullmatch(
            str(catalog_binding.get("catalog_payload_sha256", ""))
        )
        is None
        or not isinstance(catalog_binding.get("marker_path"), str)
        or not Path(catalog_binding["marker_path"]).is_absolute()
        or not isinstance(
            catalog_binding.get("allowed_generation_tuple_count"), int
        )
        or isinstance(
            catalog_binding.get("allowed_generation_tuple_count"), bool
        )
        or catalog_binding["allowed_generation_tuple_count"] < 1
    ):
        raise ControlError(
            "final semantic report lacks an exact trusted-generation catalog"
        )
    if not isinstance(runs, dict) or set(runs) != set(REQUIRED_RUNS):
        raise ControlError("final semantic report does not cover the exact run set")
    run_outcomes: list[Mapping[str, Any]] = []
    run_rows: list[Mapping[str, Any]] = []
    for run_id, expected_cells in REQUIRED_RUNS.items():
        row = runs[run_id]
        row_outcomes = (
            _validate_final_outcome_schema(
                row.get("outcomes"),
                expected_fields=FINAL_RUN_OUTCOME_FIELDS,
                context=run_id,
            )
            if isinstance(row, dict)
            else None
        )
        if (
            not isinstance(row, dict)
            or not isinstance(row_outcomes, Mapping)
            or row.get("manifest_cells") != expected_cells
            or row.get("expected_qids") != REQUIRED_RUN_QIDS[run_id]
            or row.get("states") != {"complete": expected_cells}
            or row_outcomes.get("validated_qids")
            != REQUIRED_RUN_QIDS[run_id]
            or row.get("artifact_schema_counts")
            != {"5": REQUIRED_RUN_QIDS[run_id]}
            or row.get("contract_errors") != []
            or row.get("stale_unmanifested_dirs") != 0
        ):
            raise ControlError(
                f"final semantic report for {run_id} violates its frozen contract"
            )
        for name in _FINAL_INTEGRITY_OUTCOME_FIELDS:
            if row_outcomes[name] != 0:
                raise ControlError(
                    f"final semantic outcome {run_id}/{name} is nonzero"
                )
        _validate_final_transport_accounting(
            row_outcomes,
            expected_qids=REQUIRED_RUN_QIDS[run_id],
            context=run_id,
        )
        run_outcomes.append(row_outcomes)
        run_rows.append(row)
    for field in (
        *_FINAL_TRANSPORT_ACCOUNTING_FIELDS,
        *_FINAL_INTEGRITY_OUTCOME_FIELDS,
    ):
        if outcomes[field] != sum(
            row[field] for row in run_outcomes
        ):
            raise ControlError(
                f"final semantic aggregate {field} is not the exact run sum"
            )
    if outcomes["stale_unmanifested_dirs"] != sum(
        int(row["stale_unmanifested_dirs"]) for row in run_rows
    ):
        raise ControlError(
            "final semantic aggregate stale_unmanifested_dirs is not the "
            "exact run sum"
        )
    if outcomes["contract_errors"] != sum(
        len(row["contract_errors"]) for row in run_rows
    ):
        raise ControlError(
            "final semantic aggregate contract_errors is not the exact run sum"
        )
    recomputed_checks = _recompute_final_acceptance_checks(
        semantic=semantic,
        outcomes=outcomes,
    )
    if (
        dict(reported_checks) != recomputed_checks
        or acceptance["passed"] is not all(recomputed_checks.values())
    ):
        raise ControlError(
            "final semantic acceptance checks do not match independently "
            "recomputed terminal acceptance"
        )


def _validate_final_transport_accounting(
    outcomes: Mapping[str, Any],
    *,
    expected_qids: int,
    context: str,
) -> None:
    """Validate trusted cardinality and useful/transport partitions exactly."""

    fields = _FINAL_TRANSPORT_ACCOUNTING_FIELDS
    values: dict[str, int] = {}
    for field in fields:
        if field not in outcomes:
            raise ControlError(
                f"final semantic {context} transport accounting is missing "
                f"{field}"
            )
        value = outcomes[field]
        if (
            not isinstance(value, int)
            or isinstance(value, bool)
            or value < 0
        ):
            raise ControlError(
                f"final semantic {context} {field} is not a non-negative integer"
            )
        values[field] = value
    if values["validated_qids"] != expected_qids:
        raise ControlError(
            f"final semantic {context} validated-QID cardinality is not exact"
        )
    if values["validated_qids"] != (
        values["completed_qids"]
        + values["length_censored_qids"]
        + values["protocol_censored_qids"]
        + values["transport_censored_qids"]
    ):
        raise ControlError(
            f"final semantic {context} top-level termination partition is not exact"
        )
    if values["auxiliary_outcomes"] != (
        values["auxiliary_completed"]
        + values["auxiliary_length_censored"]
        + values["auxiliary_protocol_censored"]
        + values["auxiliary_transport_censored"]
    ):
        raise ControlError(
            f"final semantic {context} auxiliary termination partition is not exact"
        )
    if values["validated_qids"] != (
        values["useful_qids"] + values["transport_affected_qids"]
    ):
        raise ControlError(
            f"final semantic {context} useful/transport QID partition is not exact"
        )
    # Every ambiguous topology attempt is retained in one observed coordinate.
    # Concurrent terminal waves can retain multiple independently censored siblings
    # even though map-order propagation yields only one top-level QID terminal.
    # Auxiliary transport censors are retained in exactly one self-consistency sample.
    if values["transport_censored_coordinates"] != (
        values["topology_transport_censored_coordinates"]
        + values["auxiliary_transport_censored"]
    ):
        raise ControlError(
            f"final semantic {context} transport-coordinate partition is not exact"
        )
    if (
        values["topology_transport_censored_coordinates"]
        < values["transport_censored_qids"]
    ):
        raise ControlError(
            f"final semantic {context} topology transport coordinate/QID bound "
            "is invalid"
        )
    if not (
        values["transport_censored_qids"]
        <= values["transport_affected_qids"]
        <= values["transport_censored_coordinates"]
    ):
        raise ControlError(
            f"final semantic {context} transport-affected QID bounds are invalid"
        )


def _trusted_generation_catalog_binding(
    catalog: TrustedGenerationCatalog,
) -> dict[str, Any]:
    return {
        "catalog_id": catalog.catalog_id,
        "marker_path": str(catalog.marker_path),
        "marker_sha256": catalog.marker_sha256,
        "inventory_sha256": catalog.inventory_sha256,
        "catalog_payload_sha256": catalog.catalog_sha256,
        "allowed_generation_tuple_count": len(
            catalog.allowed_generation_tuples
        ),
    }


def _load_sealed_final_semantic_report(path: Path) -> tuple[dict[str, Any], str]:
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_mode & 0o222
    ):
        raise ControlError("final semantic evidence is unsafe or unsealed")
    report = _load_json_object(path, description="final semantic report")
    _validate_final_semantic_report(report)
    return report, sha256_file(path)


def _final_semantic_control_contract(
    control: Mapping[str, Any],
) -> dict[str, Any]:
    """Project the exact stable control state authorized to finalize results."""

    return {
        "immutable_sha256": control["immutable_sha256"],
        "release_id": control["immutable"]["release_id"],
        "desired_state": control["desired_state"],
        "drain_requested": control["drain_requested"],
        "rollout_generation": control["rollout_generation"],
        "capacity_generation": control["capacity"]["current_generation"],
        "capacity_transition": copy.deepcopy(
            control["capacity"]["active_transition"]
        ),
        "admission_ceiling": control["admission"]["current_ceiling"],
        "admission_safety_hold": copy.deepcopy(
            control["admission_safety_hold"]
        ),
    }


def _final_semantic_source_contract(
    control: Mapping[str, Any],
) -> tuple[dict[str, Any], str]:
    """Hash every final result-source byte before a semantic scan is adopted.

    This is intentionally stronger than binding only the immutable manifests.  A
    crash may leave a valid-looking ``semantic_validation.json`` without its
    marker.  Reusing that report is safe only when the complete run trees are
    byte-identical to the trees protected by the durable pre-scan intent.
    """

    runs: list[dict[str, Any]] = []
    for pinned in control["immutable"]["runs"]:
        run_root = Path(str(pinned["run_root"])).resolve()
        manifest_path = Path(str(pinned["manifest_path"])).resolve()
        if (
            manifest_path.is_symlink()
            or not manifest_path.is_file()
            or sha256_file(manifest_path) != pinned["manifest_sha256"]
        ):
            raise ImmutablePinError(
                "final semantic source manifest drifted: "
                f"{pinned['run_id']}"
            )
        inventory, _file_inventory_sha256 = _directory_inventory(run_root)
        directories = sorted(
            path.relative_to(run_root).as_posix()
            for path in run_root.rglob("*")
            if path.is_dir() and not path.is_symlink()
        )
        inventory_sha256 = sha256_value(
            {"files": inventory, "directories": directories}
        )
        runs.append(
            {
                "run_id": str(pinned["run_id"]),
                "run_root": str(run_root),
                "manifest_sha256": str(pinned["manifest_sha256"]),
                "benchmark_contract_sha256": str(
                    pinned["benchmark_contract_sha256"]
                ),
                "policy_sha256": str(pinned["policy_sha256"]),
                "cell_count": int(pinned["cell_count"]),
                "file_count": len(inventory),
                "directory_count": len(directories),
                "total_bytes": sum(int(row["size"]) for row in inventory),
                "tree_inventory_sha256": inventory_sha256,
            }
        )
    contract = {
        "schema_version": 1,
        "kind": "schema5_final_semantic_source_contract",
        "control": _final_semantic_control_contract(control),
        "runs": runs,
    }
    return contract, sha256_value(contract)


def _validate_semantic_report_source_binding(
    report: Mapping[str, Any], source_contract: Mapping[str, Any]
) -> None:
    expected = {
        str(row["run_id"]): row for row in source_contract["runs"]
    }
    observed = report.get("semantic", {}).get("runs")
    if not isinstance(observed, dict) or set(observed) != set(expected):
        raise ControlError("final semantic report source run set drifted")
    for run_id, contract in expected.items():
        row = observed[run_id]
        if (
            not isinstance(row, dict)
            or row.get("run_root") != contract["run_root"]
            or row.get("manifest_sha256") != contract["manifest_sha256"]
            or row.get("benchmark_contract_sha256")
            != contract["benchmark_contract_sha256"]
            or row.get("artifact_policy_sha256") != contract["policy_sha256"]
        ):
            raise ControlError(
                f"final semantic report source binding drifted: {run_id}"
            )


def _final_semantic_intent_path(final_root: Path) -> Path:
    return final_root / FINAL_SEMANTIC_INTENT_FILENAME


def _validate_final_semantic_intent(
    path: Path,
    *,
    final_root: Path,
    control: Mapping[str, Any],
    source_contract: Mapping[str, Any],
    source_contract_sha256: str,
) -> tuple[dict[str, Any], str]:
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_mode & 0o222
        or path.stat().st_nlink != 1
    ):
        raise ControlError("final semantic transaction intent is unsafe or unsealed")
    intent = _load_json_object(
        path, description="final semantic transaction intent"
    )
    expected_fields = {
        "schema_version",
        "kind",
        "release_id",
        "immutable_sha256",
        "capacity_generation",
        "rollout_generation",
        "control_contract",
        "control_contract_sha256",
        "source_contract",
        "source_contract_sha256",
        "semantic_report",
        "created_at",
        "created_timestamp",
        "intent_id",
    }
    without_id = dict(intent)
    intent_id = without_id.pop("intent_id", None)
    timestamp = intent.get("created_timestamp")
    control_contract = _final_semantic_control_contract(control)
    if (
        set(intent) != expected_fields
        or intent.get("schema_version") != 1
        or intent.get("kind") != "schema5_final_semantic_transaction_intent"
        or intent.get("release_id") != control["immutable"]["release_id"]
        or intent.get("immutable_sha256") != control["immutable_sha256"]
        or intent.get("capacity_generation")
        != control["capacity"]["current_generation"]
        or intent.get("rollout_generation") != control["rollout_generation"]
        or intent.get("control_contract") != control_contract
        or intent.get("control_contract_sha256")
        != sha256_value(control_contract)
        or intent.get("source_contract") != source_contract
        or intent.get("source_contract_sha256") != source_contract_sha256
        or Path(str(intent.get("semantic_report", ""))).resolve()
        != (final_root / FINAL_SEMANTIC_FILENAME).resolve()
        or not isinstance(timestamp, (int, float))
        or isinstance(timestamp, bool)
        or not math.isfinite(float(timestamp))
        or float(timestamp) < 0
        or intent.get("created_at") != utc_timestamp(float(timestamp))
        or intent_id != sha256_value(without_id)
    ):
        raise ControlError(
            "final semantic transaction intent does not bind current sources"
        )
    return intent, sha256_file(path)


def _write_independent_archive_copy(source: Path, destination: Path) -> None:
    """Copy one stable preimage through the crash-recoverable publisher.

    These preimages are transaction metadata and semantic summaries, not the large
    result corpus.  Reading from one descriptor lets us prove a stable source cut;
    the shared immutable publisher then provides owned-temp recovery and atomic
    no-clobber installation instead of leaving an ownerless read-only ``.tmp`` after
    SIGKILL.
    """

    source = Path(os.path.abspath(os.fspath(source.expanduser())))
    if source.is_symlink() or not source.is_file():
        raise ControlError(f"cannot archive unsafe semantic preimage: {source}")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(source, flags)
    except OSError as exc:
        raise ControlError(
            f"cannot open semantic preimage for archival: {source}: {exc}"
        ) from exc
    try:
        before = os.fstat(descriptor)
        blocks: list[bytes] = []
        while block := os.read(descriptor, 1024 * 1024):
            blocks.append(block)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    identity = lambda item: (  # noqa: E731
        item.st_dev,
        item.st_ino,
        item.st_mode,
        item.st_nlink,
        item.st_size,
        item.st_mtime_ns,
        item.st_ctime_ns,
    )
    current = source.stat(follow_symlinks=False)
    if (
        not stat.S_ISREG(before.st_mode)
        or before.st_nlink != 1
        or identity(before) != identity(after)
        or identity(current) != identity(after)
    ):
        raise ControlError(
            f"semantic preimage changed during archival: {source}"
        )
    payload = b"".join(blocks)
    _atomic_publish_readonly_bytes(destination, payload)
    destination_stat = destination.stat(follow_symlinks=False)
    source_stat = source.stat(follow_symlinks=False)
    if (
        destination_stat.st_dev,
        destination_stat.st_ino,
    ) == (
        source_stat.st_dev,
        source_stat.st_ino,
    ):
        raise ControlError(
            f"semantic preimage archive shares an inode: {source}"
        )


def _archive_stale_final_semantic_evidence(
    final_root: Path, *, reason: str, now: float
) -> dict[str, Any] | None:
    """Preserve rejected canonical preimages before a clean transaction starts."""

    targets = [
        final_root / FINAL_SEMANTIC_INTENT_FILENAME,
        final_root / FINAL_SEMANTIC_FILENAME,
    ]
    present = [path for path in targets if path.exists() or path.is_symlink()]
    if not present:
        return None
    identities: list[dict[str, Any]] = []
    for path in present:
        if path.is_symlink() or not path.is_file():
            raise ControlError(
                f"refusing unsafe stale semantic evidence: {path}"
            )
        identities.append(
            {
                "name": path.name,
                "size": path.stat().st_size,
                "sha256": sha256_file(path),
            }
        )
    archive_id = sha256_value({"reason": reason, "preimages": identities})
    archive_root = (
        final_root / FINAL_SEMANTIC_ARCHIVE_DIRNAME / archive_id
    )
    marker_path = archive_root / "ARCHIVE_COMPLETE.json"
    if archive_root.is_symlink():
        raise ControlError("semantic recovery archive root is a symlink")
    if marker_path.exists():
        marker = _load_json_object(
            marker_path, description="semantic recovery archive marker"
        )
        without_id = dict(marker)
        completion_id = without_id.pop("completion_id", None)
        archived_timestamp = marker.get("archived_timestamp")
        if (
            set(marker)
            != {
                "schema_version",
                "kind",
                "complete",
                "archive_id",
                "reason",
                "preimages",
                "archived_at",
                "archived_timestamp",
                "completion_id",
            }
            or marker.get("schema_version") != 1
            or marker.get("kind")
            != "schema5_final_semantic_recovery_archive"
            or marker.get("archive_id") != archive_id
            or marker.get("reason") != reason
            or marker.get("preimages") != identities
            or marker.get("complete") is not True
            or not isinstance(archived_timestamp, (int, float))
            or isinstance(archived_timestamp, bool)
            or not math.isfinite(float(archived_timestamp))
            or float(archived_timestamp) < 0
            or marker.get("archived_at")
            != utc_timestamp(float(archived_timestamp))
            or completion_id != sha256_value(without_id)
            or marker_path.is_symlink()
            or not marker_path.is_file()
            or marker_path.stat().st_nlink != 1
            or not archive_root.is_dir()
        ):
            raise ControlError("semantic recovery archive marker drifted")
        for row in identities:
            archived = archive_root / str(row["name"])
            if (
                archived.is_symlink()
                or not archived.is_file()
                or archived.stat().st_nlink != 1
                or sha256_file(archived) != row["sha256"]
                or archived.stat().st_size != row["size"]
            ):
                raise ControlError("semantic recovery archive preimage drifted")
            archived.chmod(0o444)
        marker_path.chmod(0o444)
        archive_root.chmod(0o555)
    else:
        archive_root.mkdir(parents=True, exist_ok=True)
        io._fsync_directory(archive_root.parent)
        expected_names = {str(row["name"]) for row in identities}
        observed_names: set[str] = set()
        for candidate in archive_root.iterdir():
            if candidate.is_symlink() or not candidate.is_file():
                raise ControlError(
                    "incomplete semantic recovery archive contains an unsafe member"
                )
            observed_names.add(candidate.name)
        if observed_names - expected_names:
            raise ControlError(
                "incomplete semantic recovery archive contains unlisted preimages"
            )
        by_name = {path.name: path for path in present}
        for row in identities:
            name = str(row["name"])
            archived = archive_root / name
            if archived.exists():
                if (
                    archived.is_symlink()
                    or not archived.is_file()
                    or archived.stat().st_nlink != 1
                    or archived.stat().st_size != row["size"]
                    or sha256_file(archived) != row["sha256"]
                ):
                    raise ControlError(
                        "incomplete semantic recovery archive preimage drifted"
                    )
                archived.chmod(0o444)
            else:
                _write_independent_archive_copy(by_name[name], archived)
        marker = {
            "schema_version": 1,
            "kind": "schema5_final_semantic_recovery_archive",
            "complete": True,
            "archive_id": archive_id,
            "reason": reason,
            "preimages": identities,
            "archived_at": utc_timestamp(now),
            "archived_timestamp": now,
        }
        marker["completion_id"] = sha256_value(marker)
        _atomic_publish_readonly_json(marker_path, marker)
        archive_root.chmod(0o555)
    for path in present:
        # The complete archive is now the durable preimage.  Removing the canonical
        # name makes the next scan unambiguously start a new transaction.
        io.remove_file(path)
    return marker


def _create_final_semantic_intent(
    final_root: Path,
    *,
    control: Mapping[str, Any],
    source_contract: Mapping[str, Any],
    source_contract_sha256: str,
    now: float,
) -> tuple[dict[str, Any], str]:
    path = _final_semantic_intent_path(final_root)
    control_contract = _final_semantic_control_contract(control)
    intent: dict[str, Any] = {
        "schema_version": 1,
        "kind": "schema5_final_semantic_transaction_intent",
        "release_id": control["immutable"]["release_id"],
        "immutable_sha256": control["immutable_sha256"],
        "capacity_generation": control["capacity"]["current_generation"],
        "rollout_generation": control["rollout_generation"],
        "control_contract": control_contract,
        "control_contract_sha256": sha256_value(control_contract),
        "source_contract": copy.deepcopy(dict(source_contract)),
        "source_contract_sha256": source_contract_sha256,
        "semantic_report": str(
            (final_root / FINAL_SEMANTIC_FILENAME).resolve()
        ),
        "created_at": utc_timestamp(now),
        "created_timestamp": now,
    }
    intent["intent_id"] = sha256_value(intent)
    _atomic_publish_readonly_json(path, intent)
    return _validate_final_semantic_intent(
        path,
        final_root=final_root,
        control=control,
        source_contract=source_contract,
        source_contract_sha256=source_contract_sha256,
    )


def _verify_final_semantic_preflight(
    final_root: Path,
    *,
    control: Mapping[str, Any],
) -> tuple[dict[str, Any], str, dict[str, Any], str]:
    """Verify the marker-last semantic gate that authorizes fleet retirement."""

    semantic_path = final_root / FINAL_SEMANTIC_FILENAME
    marker_path = final_root / FINAL_SEMANTIC_PREFLIGHT_FILENAME
    source_contract, source_contract_sha256 = _final_semantic_source_contract(
        control
    )
    intent_path = _final_semantic_intent_path(final_root)
    intent, intent_sha256 = _validate_final_semantic_intent(
        intent_path,
        final_root=final_root,
        control=control,
        source_contract=source_contract,
        source_contract_sha256=source_contract_sha256,
    )
    report, report_sha256 = _load_sealed_final_semantic_report(semantic_path)
    _validate_semantic_report_source_binding(report, source_contract)
    marker = _load_json_object(
        marker_path, description="final semantic preflight marker"
    )
    expected_fields = {
        "schema_version",
        "kind",
        "complete",
        "release_id",
        "immutable_sha256",
        "capacity_generation",
        "rollout_generation",
        "completed_at",
        "completed_timestamp",
        "run_ids",
        "complete_cells",
        "trusted_qids",
        "semantic_report",
        "semantic_report_sha256",
        "semantic_intent",
        "semantic_intent_sha256",
        "semantic_intent_id",
        "source_contract_sha256",
        "preflight_id",
    }
    without_id = dict(marker)
    preflight_id = without_id.pop("preflight_id", None)
    timestamp = marker.get("completed_timestamp")
    if (
        set(marker) != expected_fields
        or marker.get("schema_version") != 2
        or marker.get("kind") != "schema5_final_semantic_preflight"
        or marker.get("complete") is not True
        or marker.get("release_id") != control["immutable"]["release_id"]
        or marker.get("immutable_sha256") != control["immutable_sha256"]
        or marker.get("capacity_generation")
        != control["capacity"]["current_generation"]
        or marker.get("rollout_generation") != control["rollout_generation"]
        or not isinstance(timestamp, (int, float))
        or isinstance(timestamp, bool)
        or timestamp < 0
        or marker.get("completed_at") != utc_timestamp(float(timestamp))
        or marker.get("run_ids") != list(REQUIRED_RUNS)
        or marker.get("complete_cells") != EXPECTED_TOTAL_CELLS
        or marker.get("trusted_qids") != EXPECTED_TOTAL_QIDS
        or Path(str(marker.get("semantic_report", ""))).resolve()
        != semantic_path.resolve()
        or marker.get("semantic_report_sha256") != report_sha256
        or Path(str(marker.get("semantic_intent", ""))).resolve()
        != intent_path.resolve()
        or marker.get("semantic_intent_sha256") != intent_sha256
        or marker.get("semantic_intent_id") != intent["intent_id"]
        or marker.get("source_contract_sha256")
        != source_contract_sha256
        or preflight_id != sha256_value(without_id)
        or marker_path.is_symlink()
        or not marker_path.is_file()
        or marker_path.stat().st_mode & 0o222
    ):
        raise ControlError("final semantic preflight marker is invalid")
    return report, report_sha256, marker, sha256_file(marker_path)


def _ensure_final_semantic_preflight(
    final_root: Path,
    *,
    control: Mapping[str, Any],
    state_dir: Path,
    results_root: Path,
    environment: Mapping[str, str],
    harness_python: Path,
    release_root: Path,
    run_command: Callable[
        [Sequence[str], Mapping[str, str], float],
        subprocess.CompletedProcess[str],
    ],
    now: float,
) -> tuple[dict[str, Any], str, dict[str, Any], str]:
    """Validate transient scan output before publishing canonical semantic evidence.

    A rejected or partial scan never reaches either canonical path.  If a crash lands
    after the validated report is sealed but before the marker is published, a retry
    revalidates those exact bytes and completes the marker-last transaction.
    """

    semantic_path = final_root / FINAL_SEMANTIC_FILENAME
    marker_path = final_root / FINAL_SEMANTIC_PREFLIGHT_FILENAME
    if marker_path.exists() or marker_path.is_symlink():
        return _verify_final_semantic_preflight(final_root, control=control)

    source_contract, source_contract_sha256 = _final_semantic_source_contract(
        control
    )
    intent_path = _final_semantic_intent_path(final_root)
    intent: dict[str, Any] | None = None
    intent_sha256: str | None = None
    stale_reason: str | None = None
    if intent_path.exists() or intent_path.is_symlink():
        try:
            intent, intent_sha256 = _validate_final_semantic_intent(
                intent_path,
                final_root=final_root,
                control=control,
                source_contract=source_contract,
                source_contract_sha256=source_contract_sha256,
            )
        except ControlError as exc:
            stale_reason = f"intent_rejected:{type(exc).__name__}:{exc}"
    elif semantic_path.exists() or semantic_path.is_symlink():
        stale_reason = "semantic_report_without_transaction_intent"

    report: dict[str, Any] | None = None
    report_sha256: str | None = None
    if stale_reason is None and intent is not None and (
        semantic_path.exists() or semantic_path.is_symlink()
    ):
        try:
            report, report_sha256 = _load_sealed_final_semantic_report(
                semantic_path
            )
            _validate_semantic_report_source_binding(report, source_contract)
        except ControlError as exc:
            stale_reason = f"semantic_report_rejected:{type(exc).__name__}:{exc}"

    if stale_reason is not None:
        _archive_stale_final_semantic_evidence(
            final_root, reason=stale_reason, now=now
        )
        intent = None
        intent_sha256 = None
        report = None
        report_sha256 = None

    if intent is None:
        intent, intent_sha256 = _create_final_semantic_intent(
            final_root,
            control=control,
            source_contract=source_contract,
            source_contract_sha256=source_contract_sha256,
            now=now,
        )

    if report is None:
        command = [
            str(harness_python),
            "-u",
            str(release_root / "scripts" / "schema5_monitor.py"),
            "--cadence",
            "daily",
            "--config",
            str(release_root / "configs" / "schema5_monitoring.v1.json"),
            "--results-root",
            str(results_root),
            "--state-dir",
            str(state_dir),
        ]
        proc = run_command(
            command, environment, FINALIZER_COMMAND_DEADLINE_SECONDS
        )
        if proc.returncode not in MONITOR_SUCCESS_RETURN_CODES:
            raise ControlError(
                "final semantic scan failed: "
                f"rc={proc.returncode}; {proc.stderr.strip()[:1000]}"
            )
        try:
            transient = json.loads(proc.stdout)
        except json.JSONDecodeError as exc:
            raise ControlError(
                "final semantic scan did not emit one JSON report"
            ) from exc
        if not isinstance(transient, dict):
            raise ControlError("final semantic report is not a JSON object")
        # This check deliberately precedes the canonical write.  Partial data cannot
        # poison a later retry and, most importantly, cannot authorize any scancel.
        _validate_final_semantic_report(transient)
        _validate_semantic_report_source_binding(transient, source_contract)
        post_contract, post_contract_sha256 = _final_semantic_source_contract(
            control
        )
        if (
            post_contract != source_contract
            or post_contract_sha256 != source_contract_sha256
        ):
            raise ControlError(
                "final semantic result sources changed during the scan"
            )
        _atomic_publish_readonly_json(semantic_path, transient)
        report, report_sha256 = _load_sealed_final_semantic_report(semantic_path)
        _validate_semantic_report_source_binding(report, source_contract)

    marker = {
        "schema_version": 2,
        "kind": "schema5_final_semantic_preflight",
        "complete": True,
        "release_id": control["immutable"]["release_id"],
        "immutable_sha256": control["immutable_sha256"],
        "capacity_generation": control["capacity"]["current_generation"],
        "rollout_generation": control["rollout_generation"],
        "completed_at": utc_timestamp(now),
        "completed_timestamp": now,
        "run_ids": list(REQUIRED_RUNS),
        "complete_cells": EXPECTED_TOTAL_CELLS,
        "trusted_qids": EXPECTED_TOTAL_QIDS,
        "semantic_report": str(semantic_path.resolve()),
        "semantic_report_sha256": report_sha256,
        "semantic_intent": str(intent_path.resolve()),
        "semantic_intent_sha256": intent_sha256,
        "semantic_intent_id": intent["intent_id"],
        "source_contract_sha256": source_contract_sha256,
    }
    marker["preflight_id"] = sha256_value(marker)
    _atomic_publish_readonly_json(marker_path, marker)
    return _verify_final_semantic_preflight(final_root, control=control)


def _validate_primary_analysis_cache(
    cache_root: Path,
    control: Mapping[str, Any],
    *,
    trusted_catalog: TrustedGenerationCatalog | None = None,
    allow_interrupted_publication: bool = False,
) -> tuple[dict[str, Any], str]:
    marker_path = cache_root / "ingest_manifest_v1.json"
    marker = _load_json_object(marker_path, description="primary analysis cache")
    run_ids = list(REQUIRED_RUNS)
    exact_zero_fields = (
        "n_bad_lines",
        "n_bad_cells",
        "n_dupes_dropped",
        "n_cells_with_dupes",
        "n_unexpected_n",
    )
    if (
        marker.get("analysis_mode") != "primary-schema5"
        or marker.get("mixed_protocol") is not False
        or marker.get("exact_token_policy") != "schema5-required"
        or marker.get("run_ids") != run_ids
        or marker.get("manifest_scoped") is not True
        or marker.get("manifest_cells_by_run") != REQUIRED_RUNS
        or marker.get("n_cell_dirs") != EXPECTED_TOTAL_CELLS
        or marker.get("n_cells_complete") != EXPECTED_TOTAL_CELLS
        or marker.get("completion_states") != {"complete": EXPECTED_TOTAL_CELLS}
        or marker.get("validated_qids_by_completion_state")
        != {"complete": EXPECTED_TOTAL_QIDS}
        or marker.get("artifact_schema_counts")
        != {"5": EXPECTED_TOTAL_QIDS}
        or any(marker.get(field) != 0 for field in exact_zero_fields)
        or marker.get("unexpected_n_cells") != []
        or marker.get("qid_mismatch_cells") != []
        or set(marker.get("run_contracts", {})) != set(REQUIRED_RUNS)
        or any(
            value != 0
            for value in marker.get("stale_dirs_by_run", {}).values()
        )
        or any(
            value != 0
            for value in marker.get("missing_dirs_by_run", {}).values()
        )
        or set(marker.get("stale_dirs_by_run", {})) != set(REQUIRED_RUNS)
        or set(marker.get("missing_dirs_by_run", {})) != set(REQUIRED_RUNS)
    ):
        raise ControlError(
            "primary analysis cache is not an exact schema-5-only final cache"
        )
    preservation = marker.get("supplementary_preservation")
    if (
        not isinstance(preservation, dict)
        or preservation.get("active_artifact_validated_qids")
        != EXPECTED_TOTAL_QIDS
        or preservation.get("sealed_scientifically_excluded_qids") != 0
        or preservation.get("unmanifested_opt_in_qids_not_in_acceptance") != 0
    ):
        raise ControlError(
            "primary analysis cache contains supplementary or excluded outcomes"
        )
    runtime = marker.get("analysis_runtime")
    immutable = control["immutable"]
    if (
        not isinstance(runtime, dict)
        or runtime.get("release_worktree")
        != str(Path(immutable["release_worktree"]).resolve())
        or runtime.get("harness_prefix")
        != str(Path(immutable["harness_environment_prefix"]).resolve())
        or runtime.get("immutable_pins_sha256") != control["immutable_sha256"]
        or runtime.get("model_contract_sha256")
        != immutable["model_contract_sha256"]
        or runtime.get("release_id") != immutable["release_id"]
        or runtime.get("git_commit") != immutable["git_commit"]
        or runtime.get("source_tree_sha256") != immutable["source_tree_sha256"]
    ):
        raise ControlError("primary analysis cache runtime provenance drifted")
    if trusted_catalog is None:
        canonical_state_dir = (
            Path(str(immutable["results_root"])).resolve()
            / CONTROL_STATE_DIRNAME
        )
        try:
            trusted_catalog = load_current_trusted_generation_catalog(
                canonical_state_dir,
                server_pool_root=Path(
                    str(immutable["server_pool_root"])
                ).resolve(),
                required=True,
            )
        except GenerationCatalogError as exc:
            raise ControlError(
                f"primary analysis catalog authority is invalid: {exc}"
            ) from exc
        assert trusted_catalog is not None
    catalog_contract = marker.get("trusted_generation_catalog")
    if (
        not isinstance(catalog_contract, dict)
        or set(catalog_contract)
        != {
            "marker_path",
            "marker_sha256",
            "inventory_sha256",
            "catalog_payload_sha256",
            "catalog_id",
            "server_pool_root",
            "allowed_generation_tuple_count",
            "validated_qids",
            "observed_coordinate_generation_tuple_count",
            "observed_calibration_endpoint_count",
            "passed",
        }
        or catalog_contract.get("passed") is not True
        or Path(str(catalog_contract.get("marker_path", ""))).resolve()
        != trusted_catalog.marker_path
        or catalog_contract.get("marker_sha256")
        != trusted_catalog.marker_sha256
        or catalog_contract.get("inventory_sha256")
        != trusted_catalog.inventory_sha256
        or catalog_contract.get("catalog_payload_sha256")
        != trusted_catalog.catalog_sha256
        or catalog_contract.get("catalog_id") != trusted_catalog.catalog_id
        or Path(
            str(catalog_contract.get("server_pool_root", ""))
        ).resolve()
        != Path(str(immutable["server_pool_root"])).resolve()
        or catalog_contract.get("allowed_generation_tuple_count")
        != len(trusted_catalog.allowed_generation_tuples)
        or catalog_contract.get("validated_qids") != EXPECTED_TOTAL_QIDS
        or not isinstance(
            catalog_contract.get(
                "observed_coordinate_generation_tuple_count"
            ),
            int,
        )
        or isinstance(
            catalog_contract.get(
                "observed_coordinate_generation_tuple_count"
            ),
            bool,
        )
        or catalog_contract[
            "observed_coordinate_generation_tuple_count"
        ]
        < 1
        or not isinstance(
            catalog_contract.get("observed_calibration_endpoint_count"),
            int,
        )
        or isinstance(
            catalog_contract.get("observed_calibration_endpoint_count"),
            bool,
        )
        or catalog_contract["observed_calibration_endpoint_count"] < 0
    ):
        raise ControlError(
            "primary analysis cache trusted-generation contract drifted"
        )
    if (
        not allow_interrupted_publication
        and (cache_root / ".cache_generation_in_progress.json").exists()
    ):
        raise ControlError("primary analysis cache publication is incomplete")
    required_artifacts = (
        "items_v1.parquet",
        "agents_v1.parquet",
        "cells_dedup_v1.parquet",
        "incident_items_scientifically_excluded_v1.parquet",
        "incident_agents_scientifically_excluded_v1.parquet",
    )
    contracts = marker.get("cache_artifacts")
    if not isinstance(contracts, dict) or set(contracts) != set(required_artifacts):
        raise ControlError("primary analysis cache artifact contract is incomplete")
    for filename in required_artifacts:
        path = cache_root / filename
        if path.is_symlink() or not path.is_file():
            raise ControlError(f"primary analysis cache lacks {filename}")
        expected = contracts[filename]
        if (
            not isinstance(expected, dict)
            or set(expected) != {"sha256", "size"}
            or expected.get("sha256") != sha256_file(path)
            or expected.get("size") != path.stat().st_size
        ):
            raise ControlError(f"primary analysis cache artifact drifted: {filename}")
    cache_contract_sha256 = marker.get("cache_contract_sha256")
    expected_generation_id = sha256_value(
        {
            "analysis_mode": marker["analysis_mode"],
            "run_ids": marker["run_ids"],
            "cache_contract_sha256": cache_contract_sha256,
            "cache_artifacts": contracts,
        }
    )
    if (
        _SHA256_RE.fullmatch(str(cache_contract_sha256 or "")) is None
        or marker.get("cache_generation_id") != expected_generation_id
        or (
            not allow_interrupted_publication
            and (cache_root / "ingest_manifest_v1.previous.json").exists()
        )
    ):
        raise ControlError("primary analysis cache generation identity is invalid")
    return marker, sha256_file(marker_path)


def _validate_primary_cache_build_marker(path: Path) -> dict[str, Any]:
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
    ):
        raise ControlError("primary analysis cache build marker is unsafe")
    marker = _load_json_object(
        path, description="primary analysis cache build marker"
    )
    started_at = marker.get("started_at")
    pid = marker.get("pid")
    if (
        set(marker)
        != {
            "cache_build_schema_version",
            "status",
            "analysis_mode",
            "run_ids",
            "pid",
            "started_at",
        }
        or marker.get("cache_build_schema_version") != 1
        or marker.get("status") != "in_progress"
        or marker.get("analysis_mode") != "primary-schema5"
        or marker.get("run_ids") != list(REQUIRED_RUNS)
        or not isinstance(pid, int)
        or isinstance(pid, bool)
        or pid < 1
        or not isinstance(started_at, (int, float))
        or isinstance(started_at, bool)
        or not math.isfinite(float(started_at))
        or float(started_at) < 0
    ):
        raise ControlError(
            "primary analysis cache build marker does not bind the final build"
        )
    return marker


def _resume_primary_analysis_cache_publication(
    cache_root: Path,
    *,
    final_root: Path,
    control: Mapping[str, Any],
    trusted_catalog: TrustedGenerationCatalog,
    now: float,
) -> tuple[dict[str, Any], str] | None:
    """Finish a manifest-last cache commit left between publication boundaries.

    If the new manifest already authenticates every exact artifact, the expensive
    analysis build is complete.  Preserve the transaction metadata independently,
    withdraw ``previous`` first, and remove the in-progress marker last.  A crash at
    every boundary is replayable from the deterministic generation-addressed archive.
    Truly partial generations return ``None`` and are handled by the full preimage
    recovery transaction below.
    """

    manifest_path = cache_root / "ingest_manifest_v1.json"
    in_progress_path = cache_root / ".cache_generation_in_progress.json"
    previous_path = cache_root / "ingest_manifest_v1.previous.json"
    metadata_paths = (in_progress_path, previous_path)
    if not manifest_path.exists() or not any(
        path.exists() or path.is_symlink() for path in metadata_paths
    ):
        return None
    try:
        marker, _ = _validate_primary_analysis_cache(
            cache_root,
            control,
            trusted_catalog=trusted_catalog,
            allow_interrupted_publication=True,
        )
    except ControlError:
        return None
    if in_progress_path.exists() or in_progress_path.is_symlink():
        _validate_primary_cache_build_marker(in_progress_path)
    present_rows: list[dict[str, Any]] = []
    for path in metadata_paths:
        if not (path.exists() or path.is_symlink()):
            continue
        if (
            path.is_symlink()
            or not path.is_file()
            or path.stat().st_nlink != 1
        ):
            raise ControlError(
                f"primary analysis cache publication metadata is unsafe: {path}"
            )
        present_rows.append(
            {
                "name": path.name,
                "size": path.stat().st_size,
                "sha256": sha256_file(path),
            }
        )
    publication_id = sha256_value(
        {
            "cache_root": str(cache_root.resolve()),
            "cache_generation_id": marker["cache_generation_id"],
        }
    )
    recovery_root = (
        final_root
        / FINAL_ANALYSIS_CACHE_PUBLICATION_RECOVERY_DIRNAME
        / publication_id
    ).resolve()
    archive_root = recovery_root / "preimage"
    intent_path = recovery_root / "RECOVERY_INTENT.json"
    complete_path = recovery_root / "RECOVERY_COMPLETE.json"
    recovery_root.parent.mkdir(parents=True, exist_ok=True)
    if recovery_root.is_symlink() or (
        recovery_root.exists() and not recovery_root.is_dir()
    ):
        raise ControlError(
            "primary analysis cache publication recovery root is unsafe"
        )
    recovery_root.mkdir(parents=True, exist_ok=True)
    if intent_path.exists() or intent_path.is_symlink():
        intent = _load_json_object(
            intent_path,
            description="primary cache publication recovery intent",
        )
        original_rows = intent.get("metadata")
        without_id = dict(intent)
        intent_id = without_id.pop("intent_id", None)
        created_timestamp = intent.get("created_timestamp")
        if (
            set(intent)
            != {
                "schema_version",
                "kind",
                "publication_id",
                "cache_root",
                "cache_generation_id",
                "metadata",
                "created_at",
                "created_timestamp",
                "intent_id",
            }
            or intent.get("schema_version") != 1
            or intent.get("kind")
            != "schema5_primary_cache_publication_recovery_intent"
            or intent.get("publication_id") != publication_id
            or Path(str(intent.get("cache_root", ""))).resolve()
            != cache_root.resolve()
            or intent.get("cache_generation_id")
            != marker["cache_generation_id"]
            or not isinstance(original_rows, list)
            or not original_rows
            or not isinstance(created_timestamp, (int, float))
            or isinstance(created_timestamp, bool)
            or not math.isfinite(float(created_timestamp))
            or float(created_timestamp) < 0
            or intent.get("created_at")
            != utc_timestamp(float(created_timestamp))
            or intent_id != sha256_value(without_id)
            or intent_path.is_symlink()
            or intent_path.stat().st_nlink != 1
            or intent_path.stat().st_mode & 0o222
        ):
            raise ControlError(
                "primary analysis cache publication recovery intent drifted"
            )
    else:
        if not present_rows:
            raise ControlError(
                "primary analysis cache publication recovery lost its metadata"
            )
        intent = {
            "schema_version": 1,
            "kind": "schema5_primary_cache_publication_recovery_intent",
            "publication_id": publication_id,
            "cache_root": str(cache_root.resolve()),
            "cache_generation_id": marker["cache_generation_id"],
            "metadata": present_rows,
            "created_at": utc_timestamp(now),
            "created_timestamp": float(now),
        }
        intent["intent_id"] = sha256_value(intent)
        _atomic_publish_readonly_json(intent_path, intent)
        original_rows = intent["metadata"]
    if (
        not isinstance(original_rows, list)
        or {
            str(row.get("name", ""))
            for row in original_rows
            if isinstance(row, Mapping)
        }
        - {path.name for path in metadata_paths}
    ):
        raise ControlError(
            "primary analysis cache publication recovery metadata is invalid"
        )
    archive_root.mkdir(parents=True, exist_ok=True)
    by_name = {path.name: path for path in metadata_paths}
    for row in original_rows:
        if (
            not isinstance(row, Mapping)
            or set(row) != {"name", "size", "sha256"}
            or row.get("name") not in by_name
            or not isinstance(row.get("size"), int)
            or isinstance(row.get("size"), bool)
            or row["size"] < 0
            or _SHA256_RE.fullmatch(str(row.get("sha256", ""))) is None
        ):
            raise ControlError(
                "primary analysis cache publication recovery metadata is invalid"
            )
        source = by_name[str(row["name"])]
        archived = archive_root / str(row["name"])
        if archived.exists() or archived.is_symlink():
            if (
                archived.is_symlink()
                or not archived.is_file()
                or archived.stat().st_nlink != 1
                or archived.stat().st_size != row["size"]
                or sha256_file(archived) != row["sha256"]
            ):
                raise ControlError(
                    "primary analysis cache publication archive drifted"
                )
        else:
            if (
                source.is_symlink()
                or not source.is_file()
                or source.stat().st_nlink != 1
                or source.stat().st_size != row["size"]
                or sha256_file(source) != row["sha256"]
            ):
                raise ControlError(
                    "primary analysis cache publication preimage disappeared"
                )
            _write_independent_archive_copy(source, archived)
    archive_rows, archive_sha256 = _directory_inventory(archive_root)
    if len(archive_rows) != len(original_rows):
        raise ControlError(
            "primary analysis cache publication archive is incomplete"
        )
    completion = {
        "schema_version": 1,
        "kind": "schema5_primary_cache_publication_recovery",
        "complete": True,
        "publication_id": publication_id,
        "intent_sha256": sha256_file(intent_path),
        "archive": str(archive_root.resolve()),
        "inventory_sha256": archive_sha256,
        "file_count": len(archive_rows),
        "completed_at": utc_timestamp(
            float(intent["created_timestamp"])
        ),
        "completed_timestamp": float(intent["created_timestamp"]),
    }
    completion["completion_id"] = sha256_value(completion)
    if complete_path.exists() or complete_path.is_symlink():
        observed = _load_json_object(
            complete_path,
            description="primary cache publication recovery marker",
        )
        if (
            observed != completion
            or complete_path.is_symlink()
            or complete_path.stat().st_nlink != 1
            or complete_path.stat().st_mode & 0o222
        ):
            raise ControlError(
                "primary analysis cache publication recovery marker drifted"
            )
    else:
        _seal_read_only_tree(archive_root)
        _atomic_publish_readonly_json(complete_path, completion)
    _seal_read_only_tree(archive_root)
    intent_path.chmod(0o444)
    complete_path.chmod(0o444)
    recovery_root.chmod(0o555)
    # Withdraw the superseded manifest before making the new generation visible.
    for path in (previous_path, in_progress_path):
        if not (path.exists() or path.is_symlink()):
            continue
        row = next(
            (
                item
                for item in original_rows
                if item["name"] == path.name
            ),
            None,
        )
        if (
            row is None
            or path.is_symlink()
            or not path.is_file()
            or path.stat().st_nlink != 1
            or path.stat().st_size != row["size"]
            or sha256_file(path) != row["sha256"]
        ):
            raise ControlError(
                "primary analysis cache publication metadata changed before commit"
            )
        io.remove_file(path)
    return _validate_primary_analysis_cache(
        cache_root,
        control,
        trusted_catalog=trusted_catalog,
    )


def _recover_interrupted_primary_analysis_cache(
    cache_root: Path,
    *,
    final_root: Path,
    now: float,
) -> dict[str, Any] | None:
    """Archive one exact interrupted cache generation and reopen a clean target.

    A cache is publishable only when its manifest exists and neither transaction
    marker exists.  Every other nonempty state is a recoverable generation preimage,
    not scientific corruption.  The marker-first recovery directory makes rename
    crashes idempotent and preserves the complete preimage for audit.
    """

    recovery_parent = (
        final_root / FINAL_ANALYSIS_CACHE_RECOVERY_DIRNAME
    ).resolve()
    if recovery_parent.exists():
        for candidate in sorted(recovery_parent.iterdir()):
            if candidate.is_symlink() or not candidate.is_dir():
                raise ControlError(
                    "primary analysis cache recovery namespace is unsafe"
                )
            intent_candidate = candidate / "RECOVERY_INTENT.json"
            archive_candidate = candidate / "preimage"
            marker_candidate = candidate / "RECOVERY_COMPLETE.json"
            if not intent_candidate.exists() or marker_candidate.exists():
                continue
            intent_value = _load_json_object(
                intent_candidate,
                description="interrupted primary cache recovery intent",
            )
            created_timestamp = intent_value.get("created_timestamp")
            if (
                set(intent_value)
                != {
                    "schema_version",
                    "kind",
                    "recovery_id",
                    "cache_root",
                    "archive",
                    "inventory_sha256",
                    "file_count",
                    "created_at",
                    "created_timestamp",
                }
                or intent_value.get("schema_version") != 1
                or intent_value.get("kind")
                != "schema5_primary_cache_recovery_intent"
                or intent_value.get("recovery_id") != candidate.name
                or Path(str(intent_value.get("cache_root", ""))).resolve()
                != cache_root.resolve()
                or Path(str(intent_value.get("archive", ""))).resolve()
                != archive_candidate.resolve()
                or _SHA256_RE.fullmatch(
                    str(intent_value.get("inventory_sha256", ""))
                )
                is None
                or not isinstance(intent_value.get("file_count"), int)
                or isinstance(intent_value.get("file_count"), bool)
                or int(intent_value.get("file_count", -1)) < 1
                or not isinstance(created_timestamp, (int, float))
                or isinstance(created_timestamp, bool)
                or not math.isfinite(float(created_timestamp))
                or float(created_timestamp) < 0
                or intent_value.get("created_at")
                != utc_timestamp(float(created_timestamp))
                or intent_candidate.is_symlink()
                or intent_candidate.stat().st_nlink != 1
                or intent_candidate.stat().st_mode & 0o222
            ):
                raise ControlError(
                    "interrupted primary cache recovery intent is invalid"
                )
            if archive_candidate.exists() or archive_candidate.is_symlink():
                if archive_candidate.is_symlink() or not archive_candidate.is_dir():
                    raise ControlError(
                        "interrupted primary cache recovery archive is unsafe"
                    )
            else:
                if (
                    cache_root.is_symlink()
                    or not cache_root.is_dir()
                ):
                    raise ControlError(
                        "interrupted primary cache recovery lost its exact preimage"
                    )
                source_rows, source_sha256 = _directory_inventory(cache_root)
                if (
                    source_sha256 != intent_value.get("inventory_sha256")
                    or len(source_rows) != intent_value.get("file_count")
                ):
                    raise ControlError(
                        "interrupted primary cache recovery source changed "
                        "before marker-first rename"
                    )
                os.replace(cache_root, archive_candidate)
                io._fsync_directory(archive_candidate.parent)
            archived_rows, archived_sha256 = _directory_inventory(
                archive_candidate
            )
            if (
                archived_sha256 != intent_value.get("inventory_sha256")
                or len(archived_rows) != intent_value.get("file_count")
            ):
                raise ControlError(
                    "interrupted primary cache recovery archive drifted"
                )
            _seal_read_only_tree(archive_candidate)
            if cache_root.exists() and any(cache_root.iterdir()):
                raise ControlError(
                    "interrupted primary cache recovery conflicts with a new build"
                )
            cache_root.mkdir(parents=True, exist_ok=True)
            completed_timestamp = float(
                intent_value["created_timestamp"]
            )
            recovered = {
                "schema_version": 1,
                "kind": "schema5_primary_cache_recovery",
                "complete": True,
                "recovery_id": candidate.name,
                "intent_sha256": sha256_file(intent_candidate),
                "archive": str(archive_candidate.resolve()),
                "inventory_sha256": archived_sha256,
                "file_count": len(archived_rows),
                "completed_at": utc_timestamp(completed_timestamp),
                "completed_timestamp": completed_timestamp,
            }
            recovered["completion_id"] = sha256_value(recovered)
            _atomic_publish_readonly_json(marker_candidate, recovered)
    manifest = cache_root / "ingest_manifest_v1.json"
    in_progress = cache_root / ".cache_generation_in_progress.json"
    previous = cache_root / "ingest_manifest_v1.previous.json"
    if not cache_root.exists():
        return None
    if cache_root.is_symlink() or not cache_root.is_dir():
        raise ControlError("primary analysis cache root is unsafe")
    entries = list(cache_root.iterdir())
    interrupted = bool(
        entries
        and (
            not manifest.is_file()
            or in_progress.exists()
            or previous.exists()
        )
    )
    if not interrupted:
        return None
    rows, inventory_sha256 = _directory_inventory(cache_root)
    recovery_id = sha256_value(
        {
            "cache_root": str(cache_root.resolve()),
            "inventory_sha256": inventory_sha256,
            "rows": rows,
        }
    )
    recovery_root = (
        final_root / FINAL_ANALYSIS_CACHE_RECOVERY_DIRNAME / recovery_id
    ).resolve()
    archive = recovery_root / "preimage"
    intent_path = recovery_root / "RECOVERY_INTENT.json"
    marker_path = recovery_root / "RECOVERY_COMPLETE.json"
    intent = {
        "schema_version": 1,
        "kind": "schema5_primary_cache_recovery_intent",
        "recovery_id": recovery_id,
        "cache_root": str(cache_root.resolve()),
        "archive": str(archive),
        "inventory_sha256": inventory_sha256,
        "file_count": len(rows),
        "created_at": utc_timestamp(now),
        "created_timestamp": float(now),
    }
    recovery_root.mkdir(parents=True, exist_ok=True)
    if intent_path.exists():
        existing = _load_json_object(
            intent_path, description="primary cache recovery intent"
        )
        created_timestamp = existing.get("created_timestamp")
        stable_existing = {
            key: value
            for key, value in existing.items()
            if key not in {"created_at", "created_timestamp"}
        }
        stable_requested = {
            key: value
            for key, value in intent.items()
            if key not in {"created_at", "created_timestamp"}
        }
        if (
            stable_existing != stable_requested
            or not isinstance(created_timestamp, (int, float))
            or isinstance(created_timestamp, bool)
            or not math.isfinite(float(created_timestamp))
            or float(created_timestamp) < 0
            or existing.get("created_at")
            != utc_timestamp(float(created_timestamp))
            or intent_path.is_symlink()
            or intent_path.stat().st_nlink != 1
            or intent_path.stat().st_mode & 0o222
        ):
            raise ControlError(
                "primary analysis cache recovery intent conflicts with replay"
            )
        intent = existing
    else:
        _atomic_publish_readonly_json(intent_path, intent)
    if archive.exists():
        archived_rows, archived_sha256 = _directory_inventory(archive)
        if archived_rows != rows or archived_sha256 != inventory_sha256:
            raise ControlError(
                "primary analysis cache recovery archive drifted"
            )
    else:
        os.replace(cache_root, archive)
        io._fsync_directory(archive.parent)
    _seal_read_only_tree(archive)
    cache_root.mkdir(parents=True, exist_ok=True)
    marker = {
        "schema_version": 1,
        "kind": "schema5_primary_cache_recovery",
        "complete": True,
        "recovery_id": recovery_id,
        "intent_sha256": sha256_file(intent_path),
        "archive": str(archive),
        "inventory_sha256": inventory_sha256,
        "file_count": len(rows),
        "completed_at": intent["created_at"],
        "completed_timestamp": intent["created_timestamp"],
    }
    marker["completion_id"] = sha256_value(marker)
    if marker_path.exists():
        existing = _load_json_object(
            marker_path, description="primary cache recovery marker"
        )
        if existing != marker or marker_path.stat().st_mode & 0o222:
            raise ControlError(
                "primary analysis cache recovery marker conflicts with replay"
            )
    else:
        _atomic_publish_readonly_json(marker_path, marker)
    return marker


def _directory_inventory(root: Path) -> tuple[list[dict[str, Any]], str]:
    if root.is_symlink() or not root.is_dir():
        raise ControlError(f"final artifact tree is missing or unsafe: {root}")
    rows: list[dict[str, Any]] = []
    for path in sorted(root.rglob("*")):
        if path.is_symlink():
            raise ControlError(f"final artifact tree contains a symlink: {path}")
        if path.is_dir():
            continue
        if not path.is_file():
            raise ControlError(f"final artifact tree contains a special file: {path}")
        if path.stat().st_nlink != 1:
            raise ControlError(f"final artifact tree contains a hardlink: {path}")
        rows.append(
            {
                "path": path.relative_to(root).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256_file(path),
            }
        )
    return rows, sha256_value(rows)


def _seal_read_only_tree(root: Path) -> None:
    for path in sorted(root.rglob("*"), reverse=True):
        path.chmod(0o555 if path.is_dir() else 0o444)
    root.chmod(0o555)


def _active_manifest_cell_locks(control: Mapping[str, Any]) -> list[str]:
    active: list[str] = []
    for run in control["immutable"]["runs"]:
        run_root = Path(run["run_root"]).resolve()
        snapshot = load_manifest(run_root)
        if (
            snapshot.sha256 != run["manifest_sha256"]
            or len(snapshot.cells) != run["cell_count"]
        ):
            raise ImmutablePinError(
                f"manifest drift while scanning final locks: {run['run_id']}"
            )
        for cell in snapshot.cells:
            cell_directory = run_root / "cells" / cell.cell_id
            if is_cell_active(cell_directory):
                active.append(f"{run['run_id']}/{cell.cell_id}")
    return active


_FINAL_CONTROL_WRITER_EXCLUSION = threading.local()


@contextmanager
def _final_control_writer_exclusion(state_dir: Path) -> Iterator[None]:
    """Exclude auxiliary state writers without introducing a lock cycle.

    The global cross-process order is monitor persistence, watchdog mirror, admission
    boundary, control, then component-local locks.  ``finalize_sweep`` already owns the
    admission boundary when it reaches its writer guards, so these two earlier locks
    are *only* acquired with nonblocking try-locks.  Contention aborts the finalizer and
    releases admission for a clean retry; it never waits in reverse order.

    The context is locally re-entrant so the public cut builder independently enforces
    exclusion while a normal finalizer can retain the same locks across retirement and
    marker-last cut publication.
    """

    canonical_state_dir = state_dir.expanduser().resolve()
    depth = int(getattr(_FINAL_CONTROL_WRITER_EXCLUSION, "depth", 0))
    if depth:
        if (
            getattr(_FINAL_CONTROL_WRITER_EXCLUSION, "state_dir", None)
            != canonical_state_dir
        ):
            raise ControlError(
                "nested final control writer exclusion changed state directory"
            )
        _FINAL_CONTROL_WRITER_EXCLUSION.depth = depth + 1
        try:
            yield
        finally:
            _FINAL_CONTROL_WRITER_EXCLUSION.depth = depth
        return

    with ExitStack() as stack:
        try:
            stack.enter_context(
                _file_lock(
                    state_dir / "monitoring" / ".persist.lock",
                    nonblocking=True,
                )
            )
            stack.enter_context(
                _file_lock(
                    state_dir
                    / "locks"
                    / "external-watchdog-mirror.lock",
                    nonblocking=True,
                )
            )
        except ControlError as exc:
            raise ControlError(
                "final control cut found an active monitor/watchdog writer; "
                "retry after that transaction commits"
            ) from exc
        _FINAL_CONTROL_WRITER_EXCLUSION.state_dir = canonical_state_dir
        _FINAL_CONTROL_WRITER_EXCLUSION.depth = 1
        try:
            yield
        finally:
            _FINAL_CONTROL_WRITER_EXCLUSION.depth = 0
            del _FINAL_CONTROL_WRITER_EXCLUSION.state_dir


@contextmanager
def _final_writer_exclusion(control: Mapping[str, Any], state_dir: Path) -> Iterator[None]:
    """Prove and retain exclusion over every final control-plane writer."""

    with ExitStack() as stack:
        stack.enter_context(_final_control_writer_exclusion(state_dir))
        for role in ROLE_NAMES:
            stack.enter_context(role_singleton_lock(state_dir, role))
        stack.enter_context(
            fleet_transactions.read_transaction_lock(
                Path(control["immutable"]["server_pool_root"])
            )
        )
        yield


def _final_watchdog_journal_validation(
    state_dir: Path,
    *,
    control: Mapping[str, Any],
) -> dict[str, Any]:
    """Semantically validate and hash-bind the watchdog journal selected by a cut."""

    root = _external_watchdog_mirror_root(state_dir)
    required = _watchdog_mirror_required(control)
    if not os.path.lexists(root):
        if required:
            raise ControlError(
                "final control cut requires the external watchdog mirror"
            )
        proof: dict[str, Any] = {
            "schema_version": 1,
            "kind": "schema5_final_watchdog_journal_validation",
            "required": False,
            "present": False,
            "status_receipt_count": 0,
            "action_intent_count": 0,
            "action_receipt_count": 0,
            "cycle_intent_count": 0,
            "cycle_receipt_count": 0,
            "latest_sequence": None,
            "latest_receipt_id": None,
            "latest_pointer_id": None,
            "files": [],
        }
        proof["validation_id"] = sha256_value(proof)
        return proof
    if root.is_symlink() or not root.is_dir():
        raise ControlError("final control cut watchdog mirror root is unsafe")

    allowed_directories = {
        "status_receipts",
        "action_intents",
        "action_receipts",
        "cycle_intents",
        "cycle_receipts",
    }
    for member in sorted(root.iterdir(), key=lambda item: item.name):
        if member.is_symlink() or (
            member.is_dir() and member.name not in allowed_directories
        ) or (
            member.is_file() and member.name != "LATEST.json"
        ) or not (member.is_dir() or member.is_file()):
            raise ControlError(
                f"final control cut watchdog mirror has a foreign member: {member}"
            )

    statuses = _load_watchdog_status_observations(state_dir)
    action_intents = _load_watchdog_action_intents(state_dir)
    action_receipts = _load_watchdog_action_receipts(state_dir)
    cycle_intents = _load_watchdog_cycle_intents(state_dir)
    cycle_receipts = _load_watchdog_cycle_receipts(state_dir)
    if len(action_intents) != len(action_receipts):
        raise ControlError(
            "final control cut watchdog action journal is incomplete"
        )
    if len(cycle_intents) != len(cycle_receipts):
        raise ControlError(
            "final control cut watchdog cycle journal is incomplete"
        )

    pointer_path = root / "LATEST.json"
    latest_sequence: int | None = None
    latest_receipt_id: str | None = None
    latest_pointer_id: str | None = None
    if cycle_receipts:
        if not os.path.lexists(pointer_path):
            raise ControlError(
                "final control cut watchdog journal lacks its latest pointer"
            )
        pointer, _raw = _watchdog_mirror_read(
            pointer_path,
            description="final control cut watchdog latest pointer",
            read_only=False,
        )
        latest, latest_path = cycle_receipts[-1]
        expected_pointer = _watchdog_latest_pointer_value(
            receipt=latest,
            receipt_path=latest_path,
        )
        if pointer != expected_pointer:
            raise ControlError(
                "final control cut watchdog pointer conflicts with its journal tail"
            )
        latest_sequence = int(latest["sequence"])
        latest_receipt_id = str(latest["receipt_id"])
        latest_pointer_id = str(pointer["pointer_id"])
    elif os.path.lexists(pointer_path):
        raise ControlError(
            "final control cut watchdog pointer exists without a cycle receipt"
        )
    if required and not cycle_receipts:
        raise ControlError(
            "final control cut requires a completed external watchdog cycle"
        )

    files: list[dict[str, Any]] = []
    for path in sorted(
        (member for member in root.rglob("*") if member.is_file()),
        key=lambda item: item.relative_to(state_dir).as_posix(),
    ):
        raw, metadata = _stable_final_control_cut_preimage(path)
        files.append(
            {
                "path": path.relative_to(state_dir).as_posix(),
                "size": metadata.st_size,
                "sha256": hashlib.sha256(raw).hexdigest(),
            }
        )
    proof = {
        "schema_version": 1,
        "kind": "schema5_final_watchdog_journal_validation",
        "required": required,
        "present": True,
        "status_receipt_count": len(statuses),
        "action_intent_count": len(action_intents),
        "action_receipt_count": len(action_receipts),
        "cycle_intent_count": len(cycle_intents),
        "cycle_receipt_count": len(cycle_receipts),
        "latest_sequence": latest_sequence,
        "latest_receipt_id": latest_receipt_id,
        "latest_pointer_id": latest_pointer_id,
        "files": files,
    }
    proof["validation_id"] = sha256_value(proof)
    return proof


def _validate_final_watchdog_journal_proof(
    projection: Any,
    *,
    included_files: Sequence[Mapping[str, Any]],
    mutable_preimages: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    """Bind semantic watchdog validation to the exact captured file preimages."""

    proof = (
        projection.get("external_watchdog_journal")
        if isinstance(projection, Mapping)
        else None
    )
    fields = {
        "schema_version",
        "kind",
        "required",
        "present",
        "status_receipt_count",
        "action_intent_count",
        "action_receipt_count",
        "cycle_intent_count",
        "cycle_receipt_count",
        "latest_sequence",
        "latest_receipt_id",
        "latest_pointer_id",
        "files",
        "validation_id",
    }
    if not isinstance(proof, dict) or set(proof) != fields:
        raise ControlError(
            "final control-plane watchdog journal proof is missing or malformed"
        )
    without_id = dict(proof)
    validation_id = without_id.pop("validation_id", None)
    counts = (
        proof.get("status_receipt_count"),
        proof.get("action_intent_count"),
        proof.get("action_receipt_count"),
        proof.get("cycle_intent_count"),
        proof.get("cycle_receipt_count"),
    )
    files = proof.get("files")
    latest_sequence = proof.get("latest_sequence")
    latest_receipt_id = proof.get("latest_receipt_id")
    latest_pointer_id = proof.get("latest_pointer_id")
    if (
        proof.get("schema_version") != 1
        or proof.get("kind")
        != "schema5_final_watchdog_journal_validation"
        or not isinstance(proof.get("required"), bool)
        or not isinstance(proof.get("present"), bool)
        or any(
            not isinstance(value, int)
            or isinstance(value, bool)
            or value < 0
            for value in counts
        )
        or proof["action_intent_count"]
        != proof["action_receipt_count"]
        or proof["cycle_intent_count"]
        != proof["cycle_receipt_count"]
        or (
            latest_sequence is not None
            and (
                not isinstance(latest_sequence, int)
                or isinstance(latest_sequence, bool)
                or latest_sequence < 1
            )
        )
        or (
            latest_receipt_id is not None
            and _SHA256_RE.fullmatch(str(latest_receipt_id)) is None
        )
        or (
            latest_pointer_id is not None
            and _SHA256_RE.fullmatch(str(latest_pointer_id)) is None
        )
        or (
            proof["cycle_receipt_count"] == 0
            and any(
                value is not None
                for value in (
                    latest_sequence,
                    latest_receipt_id,
                    latest_pointer_id,
                )
            )
        )
        or (
            proof["cycle_receipt_count"] > 0
            and (
                latest_sequence != proof["cycle_receipt_count"]
                or latest_receipt_id is None
                or latest_pointer_id is None
            )
        )
        or (
            proof["required"] is True
            and (
                proof["present"] is not True
                or proof["cycle_receipt_count"] < 1
            )
        )
        or validation_id != sha256_value(without_id)
        or not isinstance(files, list)
        or files
        != sorted(
            files,
            key=lambda row: (
                str(row.get("path", ""))
                if isinstance(row, Mapping)
                else repr(row)
            ),
        )
        or any(
            not isinstance(row, dict)
            or set(row) != {"path", "size", "sha256"}
            or not str(row.get("path", "")).startswith(
                EXTERNAL_WATCHDOG_MIRROR_DIRNAME + "/"
            )
            or not isinstance(row.get("size"), int)
            or isinstance(row.get("size"), bool)
            or int(row.get("size", -1)) < 0
            or _SHA256_RE.fullmatch(str(row.get("sha256", ""))) is None
            for row in files
        )
    ):
        raise ControlError(
            "final control-plane watchdog journal proof is invalid"
        )
    if proof["present"] is False and (
        any(counts)
        or files
        or any(
            value is not None
            for value in (
                latest_sequence,
                latest_receipt_id,
                latest_pointer_id,
            )
        )
    ):
        raise ControlError(
            "absent final watchdog journal proof contains captured state"
        )

    captured = sorted(
        (
            {
                "path": str(row["path"]),
                "size": int(row["size"]),
                "sha256": str(row["sha256"]),
            }
            for row in [*included_files, *mutable_preimages]
            if str(row["path"]).startswith(
                EXTERNAL_WATCHDOG_MIRROR_DIRNAME + "/"
            )
        ),
        key=lambda row: row["path"],
    )
    if files != captured:
        raise ControlError(
            "final watchdog semantic proof differs from captured journal preimages"
        )
    return proof


def _final_control_cut_projection(
    control: Mapping[str, Any],
    *,
    external_watchdog_journal: Mapping[str, Any],
) -> dict[str, Any]:
    finalization = control["finalization"]
    return {
        "schema_version": 1,
        "kind": "schema5_final_control_plane_projection",
        "immutable": copy.deepcopy(control["immutable"]),
        "immutable_sha256": control["immutable_sha256"],
        "desired_state": control["desired_state"],
        "drain_requested": control["drain_requested"],
        "admission": copy.deepcopy(control["admission"]),
        "capacity": {
            "current_generation": control["capacity"]["current_generation"],
            "current_contract": copy.deepcopy(
                control["capacity"].get("current_contract")
            ),
            "effective_fleet": effective_fleet_contract_binding(
                control, verify_files=True
            ),
            "effective_protected_capacity": (
                effective_protected_capacity_binding(
                    control, verify_files=True
                )
            ),
        },
        "rollout_generation": control["rollout_generation"],
        "external_watchdog_journal": copy.deepcopy(
            dict(external_watchdog_journal)
        ),
        "finalization": {
            "schema_version": finalization["schema_version"],
            "protocol": finalization["protocol"],
            "state": finalization["state"],
            "intent_id": finalization["intent_id"],
            "requested_at": finalization["requested_at"],
            "requested_timestamp": finalization["requested_timestamp"],
            "semantic_evidence": copy.deepcopy(
                finalization["semantic_evidence"]
            ),
            "consumed_capacity_incidents": copy.deepcopy(
                finalization["consumed_capacity_incidents"]
            ),
            "output_root": finalization["output_root"],
            "phase_evidence": copy.deepcopy(finalization["phase_evidence"]),
        },
    }


def _stable_final_control_cut_preimage(
    path: Path,
) -> tuple[bytes, os.stat_result]:
    """Read one one-link regular file without racing a replacement.

    A control-plane cut includes live mutable journals, so a path-level
    ``read_bytes`` followed by ``stat`` is insufficient: a writer could replace
    the lexical path while the read is in progress.  Reading through one
    no-follow descriptor and comparing only stable identity fields avoids both
    that race and false drift from access-time updates.
    """

    lexical = Path(os.path.abspath(os.fspath(path.expanduser())))
    try:
        resolved = lexical.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise ControlError(
            f"final control cut source is unavailable: {lexical}: {exc}"
        ) from exc
    if resolved != lexical or lexical.is_symlink():
        raise ControlError(
            f"final control cut source traverses a symlink: {lexical}"
        )
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    try:
        descriptor = os.open(lexical, flags)
    except OSError as exc:
        raise ControlError(
            f"cannot open final control cut source: {lexical}: {exc}"
        ) from exc
    try:
        before = os.fstat(descriptor)
        blocks: list[bytes] = []
        while block := os.read(descriptor, 1024 * 1024):
            blocks.append(block)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    identity = lambda item: (  # noqa: E731
        item.st_dev,
        item.st_ino,
        item.st_mode,
        item.st_nlink,
        item.st_size,
        item.st_mtime_ns,
        item.st_ctime_ns,
    )
    try:
        current = lexical.stat(follow_symlinks=False)
    except OSError as exc:
        raise ControlError(
            f"final control cut source disappeared after read: {lexical}: {exc}"
        ) from exc
    if (
        not stat.S_ISREG(before.st_mode)
        or before.st_nlink != 1
        or identity(before) != identity(after)
        or identity(current) != identity(after)
    ):
        raise ControlError(
            f"final control cut source changed during read: {lexical}"
        )
    return b"".join(blocks), current


def _decode_final_control_cut_preimage(
    row: Mapping[str, Any],
) -> bytes:
    """Decode and re-prove one mutable preimage embedded in a sealed intent."""

    try:
        payload = str(row["payload"]).encode("ascii")
        decoded = base64.b64decode(payload, validate=True)
    except (KeyError, UnicodeEncodeError, ValueError, binascii.Error) as exc:
        raise ControlError(
            "final control-plane mutable preimage is not canonical base64"
        ) from exc
    if (
        len(decoded) != row.get("size")
        or hashlib.sha256(decoded).hexdigest() != row.get("sha256")
    ):
        raise ControlError(
            "final control-plane mutable preimage checksum drifted"
        )
    return decoded


def _validate_final_control_cut_rows(
    intent: Mapping[str, Any],
) -> tuple[
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
]:
    """Validate the closed, disjoint file classification in one cut intent."""

    included = intent.get("included_files")
    mutable_preimages = intent.get("mutable_preimages")
    excluded = intent.get("excluded_files")

    def safe_relative(value: Any) -> bool:
        if not isinstance(value, str) or not value:
            return False
        candidate = Path(value)
        return (
            not candidate.is_absolute()
            and ".." not in candidate.parts
            and candidate.as_posix() == value
        )

    included_valid = isinstance(included, list) and all(
        isinstance(row, dict)
        and set(row) == {"path", "size", "sha256"}
        and safe_relative(row["path"])
        and isinstance(row["size"], int)
        and not isinstance(row["size"], bool)
        and row["size"] >= 0
        and _SHA256_RE.fullmatch(str(row["sha256"])) is not None
        for row in included
    )
    mutable_valid = isinstance(mutable_preimages, list) and all(
        isinstance(row, dict)
        and set(row)
        == {"path", "size", "sha256", "encoding", "payload"}
        and row["encoding"] == "base64"
        and safe_relative(row["path"])
        and isinstance(row["size"], int)
        and not isinstance(row["size"], bool)
        and row["size"] >= 0
        and _SHA256_RE.fullmatch(str(row["sha256"])) is not None
        and isinstance(row["payload"], str)
        for row in mutable_preimages
    )
    excluded_valid = isinstance(excluded, list) and all(
        isinstance(row, dict)
        and set(row) == {"path", "size", "mtime_ns", "reason"}
        and row["reason"] in {"runtime_log", "advisory_lock"}
        and safe_relative(row["path"])
        and isinstance(row["size"], int)
        and not isinstance(row["size"], bool)
        and row["size"] >= 0
        and isinstance(row["mtime_ns"], int)
        and not isinstance(row["mtime_ns"], bool)
        and row["mtime_ns"] >= 0
        for row in excluded
    )
    if not (included_valid and mutable_valid and excluded_valid):
        raise ControlError(
            "final control-plane cut file classification is malformed"
        )
    assert isinstance(included, list)
    assert isinstance(mutable_preimages, list)
    assert isinstance(excluded, list)
    for row in mutable_preimages:
        _decode_final_control_cut_preimage(row)
    groups = (included, mutable_preimages, excluded)
    if any(
        [str(row["path"]) for row in group]
        != sorted(str(row["path"]) for row in group)
        for group in groups
    ):
        raise ControlError(
            "final control-plane cut file classification is not sorted"
        )
    all_paths = [
        str(row["path"]) for group in groups for row in group
    ]
    if len(all_paths) != len(set(all_paths)):
        raise ControlError(
            "final control-plane cut file classification is duplicated"
        )
    return included, mutable_preimages, excluded


def _final_control_cut_source_inventory(
    state_dir: Path,
) -> tuple[
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
]:
    """Classify one locked control-plane cut into immutable copies and exclusions."""

    included: list[dict[str, Any]] = []
    mutable_preimages: list[dict[str, Any]] = []
    excluded: list[dict[str, Any]] = []
    for root, directory_names, file_names in os.walk(
        state_dir, topdown=True, followlinks=False
    ):
        directory_names.sort()
        file_names.sort()
        root_path = Path(root)
        for name in directory_names:
            path = root_path / name
            if path.is_symlink() or not path.is_dir():
                raise ControlError(
                    f"final control cut contains an unsafe directory: {path}"
                )
        for name in file_names:
            path = root_path / name
            relative = path.relative_to(state_dir).as_posix()
            if path.is_symlink() or not path.is_file():
                raise ControlError(
                    f"final control cut contains an unsafe file: {path}"
                )
            parts = Path(relative).parts
            if (
                "logs" in parts
                or name.endswith(".log")
                or name.endswith(".out")
            ):
                metadata = path.stat(follow_symlinks=False)
                if not stat.S_ISREG(metadata.st_mode):
                    raise ControlError(
                        f"final control cut contains an unsafe log: {path}"
                    )
                excluded.append(
                    {
                        "path": relative,
                        "size": metadata.st_size,
                        "mtime_ns": metadata.st_mtime_ns,
                        "reason": "runtime_log",
                    }
                )
                continue
            if name.endswith(".lock"):
                metadata = path.stat(follow_symlinks=False)
                if not stat.S_ISREG(metadata.st_mode):
                    raise ControlError(
                        f"final control cut contains an unsafe lock: {path}"
                    )
                excluded.append(
                    {
                        "path": relative,
                        "size": metadata.st_size,
                        "mtime_ns": metadata.st_mtime_ns,
                        "reason": "advisory_lock",
                    }
                )
                continue
            raw, metadata = _stable_final_control_cut_preimage(path)
            row = {
                "path": relative,
                "size": metadata.st_size,
                "sha256": hashlib.sha256(raw).hexdigest(),
            }
            if (
                name.endswith(".jsonl")
                or name in {CONTROL_FILENAME, "ledger.json"}
                or metadata.st_mode & 0o222
            ):
                mutable_preimages.append(
                    {
                        **row,
                        "encoding": "base64",
                        "payload": base64.b64encode(raw).decode("ascii"),
                    }
                )
            else:
                included.append(row)
    included.sort(key=lambda row: str(row["path"]))
    mutable_preimages.sort(key=lambda row: str(row["path"]))
    excluded.sort(key=lambda row: str(row["path"]))
    if len(
        {
            str(row["path"])
            for row in [*included, *mutable_preimages, *excluded]
        }
    ) != (
        len(included) + len(mutable_preimages) + len(excluded)
    ):
        raise ControlError("final control cut source inventory is duplicated")
    return included, mutable_preimages, excluded


def _validate_final_control_cut_intent(
    path: Path,
    *,
    state_dir: Path,
    control: Mapping[str, Any],
    bindings: Mapping[str, Any],
) -> tuple[dict[str, Any], str]:
    intent = _load_json_object(
        path, description="final control-plane cut intent"
    )
    expected_fields = {
        "schema_version",
        "kind",
        "source_root",
        "immutable_sha256",
        "capacity_generation",
        "rollout_generation",
        "finalization_intent_id",
        "bindings",
        "control_projection",
        "included_files",
        "mutable_preimages",
        "excluded_files",
        "created_at",
        "created_timestamp",
        "intent_id",
    }
    without_id = dict(intent)
    intent_id = without_id.pop("intent_id", None)
    created = intent.get("created_timestamp")
    (
        included_files,
        mutable_preimages,
        _excluded_files,
    ) = _validate_final_control_cut_rows(intent)
    projection = intent.get("control_projection")
    _validate_final_watchdog_journal_proof(
        projection,
        included_files=included_files,
        mutable_preimages=mutable_preimages,
    )
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
        or set(intent) != expected_fields
        or intent.get("schema_version") != 1
        or intent.get("kind") != "schema5_final_control_plane_cut_intent"
        or Path(str(intent.get("source_root", ""))).resolve()
        != state_dir.resolve()
        or intent.get("immutable_sha256") != control["immutable_sha256"]
        or intent.get("capacity_generation")
        != control["capacity"]["current_generation"]
        or intent.get("rollout_generation") != control["rollout_generation"]
        or intent.get("finalization_intent_id")
        != control["finalization"]["intent_id"]
        or intent.get("bindings") != dict(bindings)
        or not isinstance(projection, dict)
        or projection.get("immutable_sha256") != control["immutable_sha256"]
        or projection.get("rollout_generation")
        != control["rollout_generation"]
        or projection.get("finalization", {}).get("intent_id")
        != control["finalization"]["intent_id"]
        or not isinstance(created, (int, float))
        or isinstance(created, bool)
        or not math.isfinite(float(created))
        or float(created) < 0
        or intent.get("created_at") != utc_timestamp(float(created))
        or intent_id != sha256_value(without_id)
    ):
        raise ControlError("final control-plane cut intent is invalid or drifted")
    return intent, sha256_file(path)


def _validate_final_control_plane_cut(
    payload_root: Path,
    *,
    expected_bindings: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], str]:
    marker_path = payload_root / FINAL_CONTROL_CUT_COMPLETE_FILENAME
    intent_path = payload_root / FINAL_CONTROL_CUT_INTENT_FILENAME
    marker = _load_json_object(
        marker_path, description="final control-plane cut completion"
    )
    intent = _load_json_object(
        intent_path, description="snapshotted final control-plane cut intent"
    )
    intent_without_id = dict(intent)
    sealed_intent_id = intent_without_id.pop("intent_id", None)
    (
        included_files,
        mutable_preimages,
        excluded_files,
    ) = _validate_final_control_cut_rows(intent)
    projection = intent.get("control_projection")
    _validate_final_watchdog_journal_proof(
        projection,
        included_files=included_files,
        mutable_preimages=mutable_preimages,
    )
    intent_created = intent.get("created_timestamp")
    if (
        set(intent)
        != {
            "schema_version",
            "kind",
            "source_root",
            "immutable_sha256",
            "capacity_generation",
            "rollout_generation",
            "finalization_intent_id",
            "bindings",
            "control_projection",
            "included_files",
            "mutable_preimages",
            "excluded_files",
            "created_at",
            "created_timestamp",
            "intent_id",
        }
        or intent.get("schema_version") != 1
        or intent.get("kind") != "schema5_final_control_plane_cut_intent"
        or not Path(str(intent.get("source_root", ""))).is_absolute()
        or _SHA256_RE.fullmatch(str(intent.get("immutable_sha256", "")))
        is None
        or not isinstance(intent.get("capacity_generation"), int)
        or isinstance(intent.get("capacity_generation"), bool)
        or not isinstance(intent.get("rollout_generation"), int)
        or isinstance(intent.get("rollout_generation"), bool)
        or not isinstance(intent.get("bindings"), dict)
        or not isinstance(projection, dict)
        or projection.get("immutable_sha256")
        != intent.get("immutable_sha256")
        or projection.get("rollout_generation")
        != intent.get("rollout_generation")
        or projection.get("finalization", {}).get("intent_id")
        != intent.get("finalization_intent_id")
        or not isinstance(intent_created, (int, float))
        or isinstance(intent_created, bool)
        or not math.isfinite(float(intent_created))
        or float(intent_created) < 0
        or intent.get("created_at")
        != utc_timestamp(float(intent_created))
        or sealed_intent_id != sha256_value(intent_without_id)
    ):
        raise ControlError("snapshotted final control-plane cut intent is invalid")
    without_id = dict(marker)
    completion_id = without_id.pop("completion_id", None)
    completed = marker.get("completed_timestamp")
    expected_files = {
        f"source/{row['path']}" for row in included_files
    } | {
        f"mutable_preimages/{row['path']}" for row in mutable_preimages
    } | {
        FINAL_CONTROL_CUT_INTENT_FILENAME,
        FINAL_CONTROL_CUT_PROJECTION_FILENAME,
        FINAL_CONTROL_CUT_EXCLUSIONS_FILENAME,
    }
    observed_rows, _observed_sha256 = _directory_inventory(payload_root)
    inventory_rows = [
        row
        for row in observed_rows
        if row["path"] != FINAL_CONTROL_CUT_COMPLETE_FILENAME
    ]
    inventory_sha256 = sha256_value(inventory_rows)
    observed_files = {str(row["path"]) for row in inventory_rows}
    if (
        payload_root.is_symlink()
        or not payload_root.is_dir()
        or payload_root.stat().st_mode & 0o222
        or set(marker)
        != {
            "schema_version",
            "kind",
            "complete",
            "intent_id",
            "intent_sha256",
            "bindings",
            "inventory_sha256",
            "file_count",
            "completed_at",
            "completed_timestamp",
            "completion_id",
        }
        or marker.get("schema_version") != 1
        or marker.get("kind") != "schema5_final_control_plane_cut"
        or marker.get("complete") is not True
        or marker.get("intent_id") != intent.get("intent_id")
        or marker.get("intent_sha256") != sha256_file(intent_path)
        or marker.get("bindings") != intent.get("bindings")
        or (
            expected_bindings is not None
            and marker.get("bindings") != dict(expected_bindings)
        )
        or marker.get("inventory_sha256") != inventory_sha256
        or marker.get("file_count") != len(inventory_rows)
        or observed_files != expected_files
        or not isinstance(completed, (int, float))
        or isinstance(completed, bool)
        or not math.isfinite(float(completed))
        or float(completed) < 0
        or marker.get("completed_at") != utc_timestamp(float(completed))
        or completion_id != sha256_value(without_id)
    ):
        raise ControlError("final control-plane cut is incomplete or drifted")
    for member in payload_root.rglob("*"):
        metadata = member.stat(follow_symlinks=False)
        if (
            member.is_symlink()
            or metadata.st_mode & 0o222
            or (
                not stat.S_ISDIR(metadata.st_mode)
                and not stat.S_ISREG(metadata.st_mode)
            )
            or (
                stat.S_ISREG(metadata.st_mode)
                and metadata.st_nlink != 1
            )
        ):
            raise ControlError(
                f"final control-plane cut member is unsafe: {member}"
            )
    projection_path = payload_root / FINAL_CONTROL_CUT_PROJECTION_FILENAME
    exclusions_path = payload_root / FINAL_CONTROL_CUT_EXCLUSIONS_FILENAME
    if (
        _load_json_object(
            projection_path, description="final control-plane projection"
        )
        != intent["control_projection"]
        or _load_json_object(
            exclusions_path, description="final control-plane exclusions"
        )
        != {
            "schema_version": 1,
            "kind": "schema5_final_control_plane_exclusions",
            "files": intent["excluded_files"],
        }
    ):
        raise ControlError("final control-plane cut projection drifted")
    for row in intent["included_files"]:
        destination = payload_root / "source" / str(row["path"])
        if (
            destination.is_symlink()
            or not destination.is_file()
            or destination.stat().st_nlink != 1
            or destination.stat().st_mode & 0o222
            or destination.stat().st_size != row["size"]
            or sha256_file(destination) != row["sha256"]
        ):
            raise ControlError(
                f"final control-plane cut member drifted: {row['path']}"
            )
    for row in intent["mutable_preimages"]:
        destination = payload_root / "mutable_preimages" / str(row["path"])
        expected_payload = _decode_final_control_cut_preimage(row)
        if (
            destination.is_symlink()
            or not destination.is_file()
            or destination.stat().st_nlink != 1
            or destination.stat().st_mode & 0o222
            or destination.stat().st_size != row["size"]
            or destination.read_bytes() != expected_payload
        ):
            raise ControlError(
                "final control-plane mutable preimage drifted: "
                f"{row['path']}"
            )
    return marker, sha256_file(marker_path)


def _ensure_final_control_plane_cut(
    state_dir: Path,
    *,
    final_root: Path,
    bindings: Mapping[str, Any],
    now: float,
) -> tuple[Path, dict[str, Any], str]:
    """Freeze one successor-invariant control source under exact writer exclusion."""

    with _final_control_writer_exclusion(state_dir):
        return _ensure_final_control_plane_cut_locked(
            state_dir,
            final_root=final_root,
            bindings=bindings,
            now=now,
        )


def _ensure_final_control_plane_cut_locked(
    state_dir: Path,
    *,
    final_root: Path,
    bindings: Mapping[str, Any],
    now: float,
) -> tuple[Path, dict[str, Any], str]:
    """Freeze one successor-invariant control source for the final snapshot."""

    cut_root = (final_root / FINAL_CONTROL_CUT_DIRNAME).resolve()
    payload_root = cut_root / FINAL_CONTROL_CUT_PAYLOAD_DIRNAME
    intent_path = cut_root / FINAL_CONTROL_CUT_INTENT_FILENAME
    marker_path = payload_root / FINAL_CONTROL_CUT_COMPLETE_FILENAME
    cut_root.mkdir(parents=True, exist_ok=True)
    if cut_root.is_symlink() or not cut_root.is_dir():
        raise ControlError("final control-plane cut root is unsafe")
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        if intent_path.exists() or intent_path.is_symlink():
            # A real process death can occur after link(2) installs the winner but
            # before the publisher removes its owned temporary hardlink.  Replay the
            # same canonical payload first so the generic publisher can collapse
            # that exact namespace back to a one-link immutable intent.
            existing_intent = _load_json_object(
                intent_path,
                description="recoverable final control-plane cut intent",
            )
            _atomic_publish_readonly_json(intent_path, existing_intent)
            intent, intent_sha256 = _validate_final_control_cut_intent(
                intent_path,
                state_dir=state_dir,
                control=control,
                bindings=bindings,
            )
        else:
            watchdog_journal = _final_watchdog_journal_validation(
                state_dir,
                control=control,
            )
            (
                included,
                mutable_preimages,
                excluded,
            ) = _final_control_cut_source_inventory(state_dir)
            intent = {
                "schema_version": 1,
                "kind": "schema5_final_control_plane_cut_intent",
                "source_root": str(state_dir.resolve()),
                "immutable_sha256": control["immutable_sha256"],
                "capacity_generation": control["capacity"][
                    "current_generation"
                ],
                "rollout_generation": control["rollout_generation"],
                "finalization_intent_id": control["finalization"]["intent_id"],
                "bindings": copy.deepcopy(dict(bindings)),
                "control_projection": _final_control_cut_projection(
                    control,
                    external_watchdog_journal=watchdog_journal,
                ),
                "included_files": included,
                "mutable_preimages": mutable_preimages,
                "excluded_files": excluded,
                "created_at": utc_timestamp(now),
                "created_timestamp": float(now),
            }
            intent["intent_id"] = sha256_value(intent)
            _atomic_publish_readonly_json(intent_path, intent)
            intent, intent_sha256 = _validate_final_control_cut_intent(
                intent_path,
                state_dir=state_dir,
                control=control,
                bindings=bindings,
            )
    if marker_path.exists() or marker_path.is_symlink():
        existing_marker = _load_json_object(
            marker_path,
            description="recoverable final control-plane cut completion",
        )
        _atomic_publish_readonly_json(marker_path, existing_marker)
        # Marker publication is the last content mutation.  A process may die after
        # that atomic link but before the recursive chmod; seal first, then verify the
        # marker-bound inventory.  Tampered bytes still fail the subsequent proof.
        _seal_read_only_tree(payload_root)
        intent_path.chmod(0o444)
        cut_root.chmod(0o555)
        marker, marker_sha256 = _validate_final_control_plane_cut(
            payload_root, expected_bindings=bindings
        )
        return payload_root, marker, marker_sha256
    if payload_root.is_symlink() or (
        payload_root.exists() and not payload_root.is_dir()
    ):
        raise ControlError("final control-plane cut payload root is unsafe")
    payload_root.mkdir(parents=True, exist_ok=True)
    source_root = payload_root / "source"
    source_root.mkdir(parents=True, exist_ok=True)
    for row in intent["included_files"]:
        source = state_dir / str(row["path"])
        destination = source_root / str(row["path"])
        if (
            source.is_symlink()
            or not source.is_file()
            or source.stat().st_nlink != 1
            or source.stat().st_mode & 0o222
            or source.stat().st_size != row["size"]
            or sha256_file(source) != row["sha256"]
        ):
            raise ControlError(
                f"final control-plane immutable source drifted: {row['path']}"
            )
        _write_independent_archive_copy(source, destination)
    mutable_root = payload_root / "mutable_preimages"
    mutable_root.mkdir(parents=True, exist_ok=True)
    for row in intent["mutable_preimages"]:
        destination = mutable_root / str(row["path"])
        _atomic_publish_readonly_bytes(
            destination,
            _decode_final_control_cut_preimage(row),
        )
    _atomic_publish_readonly_json(
        payload_root / FINAL_CONTROL_CUT_INTENT_FILENAME,
        intent,
    )
    _atomic_publish_readonly_json(
        payload_root / FINAL_CONTROL_CUT_PROJECTION_FILENAME,
        intent["control_projection"],
    )
    _atomic_publish_readonly_json(
        payload_root / FINAL_CONTROL_CUT_EXCLUSIONS_FILENAME,
        {
            "schema_version": 1,
            "kind": "schema5_final_control_plane_exclusions",
            "files": intent["excluded_files"],
        },
    )
    inventory_rows, inventory_sha256 = _directory_inventory(payload_root)
    marker = {
        "schema_version": 1,
        "kind": "schema5_final_control_plane_cut",
        "complete": True,
        "intent_id": intent["intent_id"],
        "intent_sha256": intent_sha256,
        "bindings": copy.deepcopy(dict(bindings)),
        "inventory_sha256": inventory_sha256,
        "file_count": len(inventory_rows),
        "completed_at": utc_timestamp(now),
        "completed_timestamp": float(now),
    }
    marker["completion_id"] = sha256_value(marker)
    _atomic_publish_readonly_json(marker_path, marker)
    _seal_read_only_tree(payload_root)
    intent_path.chmod(0o444)
    cut_root.chmod(0o555)
    marker, marker_sha256 = _validate_final_control_plane_cut(
        payload_root, expected_bindings=bindings
    )
    return payload_root, marker, marker_sha256


def _canonical_final_snapshot_sources(
    control: Mapping[str, Any],
    *,
    final_root: Path,
    trusted_catalog_root: Path,
    include_semantic_archive: bool | None = None,
) -> tuple[tuple[str, Path], ...]:
    """Derive the one canonical name-to-origin map for a final snapshot."""

    immutable = control["immutable"]
    run_sources = {
        str(run["run_id"]): Path(str(run["run_root"])).resolve()
        for run in immutable["runs"]
    }
    if set(run_sources) != set(REQUIRED_RUNS):
        raise FinalizerProvenanceError(
            "final snapshot run origins differ from the frozen run set"
        )
    resolved_final_root = final_root.expanduser().resolve()
    sources: dict[str, Path] = {
        **run_sources,
        "control": (
            resolved_final_root
            / FINAL_CONTROL_CUT_DIRNAME
            / FINAL_CONTROL_CUT_PAYLOAD_DIRNAME
        ).resolve(),
        "semantic_validation": (
            resolved_final_root / FINAL_SEMANTIC_FILENAME
        ).resolve(),
        "semantic_intent": (
            resolved_final_root / FINAL_SEMANTIC_INTENT_FILENAME
        ).resolve(),
        "semantic_preflight": (
            resolved_final_root / FINAL_SEMANTIC_PREFLIGHT_FILENAME
        ).resolve(),
        "primary_analysis_cache": (
            resolved_final_root / FINAL_ANALYSIS_CACHE_DIRNAME
        ).resolve(),
        "fleet_retirement": (
            resolved_final_root / FINAL_FLEET_RETIREMENT_DIRNAME
        ).resolve(),
        "server_pool": Path(
            str(immutable["server_pool_root"])
        ).resolve(),
        "trusted_generation_catalog": (
            trusted_catalog_root.expanduser().resolve()
        ),
    }
    semantic_archive = (
        resolved_final_root / FINAL_SEMANTIC_ARCHIVE_DIRNAME
    )
    if include_semantic_archive is None:
        if semantic_archive.is_symlink():
            raise FinalizerProvenanceError(
                "final semantic recovery archive may not be a symlink"
            )
        include_semantic_archive = semantic_archive.is_dir()
    if include_semantic_archive:
        sources["semantic_recovery_archive"] = semantic_archive.resolve()
    if (
        not FINAL_SNAPSHOT_REQUIRED_SOURCES.issubset(sources)
        or set(sources)
        - FINAL_SNAPSHOT_REQUIRED_SOURCES
        - FINAL_SNAPSHOT_OPTIONAL_SOURCES
    ):
        raise FinalizerProvenanceError(
            "canonical final snapshot source set is invalid"
        )
    return tuple(sorted(sources.items()))


def _final_snapshot_source_rows(
    sources: Sequence[tuple[str, Path]],
) -> list[dict[str, str]]:
    rows = [
        {"name": str(name), "path": str(Path(path).expanduser().resolve())}
        for name, path in sources
    ]
    if (
        rows != sorted(rows, key=lambda row: row["name"])
        or len({row["name"] for row in rows}) != len(rows)
        or any(
            re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]*", row["name"])
            is None
            or not Path(row["path"]).is_absolute()
            for row in rows
        )
    ):
        raise FinalizerProvenanceError(
            "final snapshot source origins are not canonical"
        )
    return rows


def _canonical_final_control_cut_bindings(
    control: Mapping[str, Any],
    *,
    semantic_report_sha256: str,
    semantic_preflight_sha256: str,
    retirement: Mapping[str, Any],
    retirement_marker_sha256: str,
    cache_payload: Mapping[str, Any],
    cache_marker_sha256: str,
    cache_tree_sha256: str,
    trusted_catalog: TrustedGenerationCatalog,
) -> dict[str, Any]:
    """Bind the snapshotted control cut to the exact accepted final artifacts."""

    return {
        "immutable_sha256": control["immutable_sha256"],
        "capacity_generation": control["capacity"]["current_generation"],
        "rollout_generation": control["rollout_generation"],
        "finalization_intent_id": control["finalization"]["intent_id"],
        "semantic_report_sha256": semantic_report_sha256,
        "semantic_preflight_sha256": semantic_preflight_sha256,
        "retirement_id": retirement["retirement_id"],
        "retirement_completion_id": retirement["completion_id"],
        "retirement_marker_sha256": retirement_marker_sha256,
        "cache_marker_sha256": cache_marker_sha256,
        "cache_generation_id": cache_payload["cache_generation_id"],
        "cache_tree_sha256": cache_tree_sha256,
        "trusted_generation_catalog_id": trusted_catalog.catalog_id,
        "trusted_generation_catalog_marker_sha256": (
            trusted_catalog.marker_sha256
        ),
    }


def _validate_final_snapshot_marker(
    snapshot_root: Path,
    *,
    expected_sources: Sequence[tuple[str, Path]] | None = None,
    expected_control_cut_bindings: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], str]:
    """Recursively re-prove a marker-last recovery snapshot from its inventories."""

    if (
        snapshot_root.is_symlink()
        or not snapshot_root.is_dir()
        or snapshot_root.stat().st_mode & 0o222
    ):
        raise ControlError("final snapshot root is missing, unsafe, or writable")
    marker_path = snapshot_root / "SNAPSHOT_COMPLETE.json"
    marker = _load_json_object(marker_path, description="final snapshot marker")
    marker_fields = {
        "schema_version",
        "snapshot_id",
        "snapshot_kind",
        "completed_at",
        "file_count",
        "total_bytes",
        "snapshot_inventory_sha256",
        "verified",
        "read_only",
    }
    if (
        set(marker) != marker_fields
        or marker.get("schema_version") != FINAL_SNAPSHOT_SCHEMA_VERSION
        or marker.get("snapshot_kind") != FINAL_SNAPSHOT_KIND
        or not isinstance(marker.get("snapshot_id"), str)
        or re.fullmatch(
            rf"{re.escape(FINAL_SNAPSHOT_ID_PREFIX)}-[0-9a-f]{{16}}",
            str(marker.get("snapshot_id", "")),
        )
        is None
        or not isinstance(marker.get("completed_at"), str)
        or marker.get("verified") is not True
        or marker.get("read_only") is not True
        or not isinstance(marker.get("file_count"), int)
        or isinstance(marker.get("file_count"), bool)
        or marker.get("file_count", 0) < 1
        or not isinstance(marker.get("total_bytes"), int)
        or isinstance(marker.get("total_bytes"), bool)
        or marker.get("total_bytes", -1) < 0
        or _SHA256_RE.fullmatch(
            str(marker.get("snapshot_inventory_sha256", ""))
        )
        is None
    ):
        raise ControlError("final snapshot completion marker is invalid")
    try:
        time.strptime(str(marker["completed_at"]), "%Y-%m-%dT%H:%M:%SZ")
    except ValueError as exc:
        raise ControlError(
            "final snapshot completion timestamp is non-canonical"
        ) from exc

    control_paths = {
        name: snapshot_root / name
        for name in FINAL_SNAPSHOT_CONTROL_FILENAMES
    }
    for name, path in control_paths.items():
        if (
            path.is_symlink()
            or not path.is_file()
            or path.stat().st_nlink != 1
            or path.stat().st_mode & 0o222
        ):
            raise ControlError(
                f"final snapshot control artifact is unsafe: {name}"
            )

    source_inventory = control_paths["SOURCE_INVENTORY.sha256"]
    copy_inventory = control_paths["SNAPSHOT_INVENTORY.sha256"]
    source_bytes = source_inventory.read_bytes()
    inventory_bytes = copy_inventory.read_bytes()
    if source_bytes != inventory_bytes:
        raise ControlError("final snapshot source/copy inventories differ")
    try:
        inventory_text = inventory_bytes.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ControlError("final snapshot inventory is not UTF-8") from exc
    inventory: list[dict[str, Any]] = []
    canonical_lines: list[str] = []
    logical_paths: list[str] = []
    for line_number, line in enumerate(inventory_text.splitlines(), 1):
        digest, separator, logical = line.partition("  ")
        relative = Path(logical)
        if (
            not separator
            or _SHA256_RE.fullmatch(digest) is None
            or not logical
            or relative.is_absolute()
            or ".." in relative.parts
            or relative.as_posix() != logical
            or logical in FINAL_SNAPSHOT_CONTROL_FILENAMES
        ):
            raise ControlError(
                f"final snapshot inventory row is invalid: {line_number}"
            )
        canonical_lines.append(f"{digest}  {logical}\n")
        logical_paths.append(logical)
        inventory.append({"path": logical, "sha256": digest})
    if (
        not inventory
        or "".join(canonical_lines).encode("utf-8") != inventory_bytes
        or logical_paths != sorted(logical_paths)
        or len(logical_paths) != len(set(logical_paths))
    ):
        raise ControlError(
            "final snapshot inventory is empty, non-canonical, or duplicated"
        )

    directory_path = control_paths["DIRECTORY_INVENTORY.txt"]
    try:
        directory_text = directory_path.read_text(encoding="utf-8")
    except (OSError, UnicodeError) as exc:
        raise ControlError("cannot read final snapshot directory inventory") from exc
    directories = directory_text.splitlines()
    if (
        "".join(f"{name}\n" for name in directories) != directory_text
        or directories != sorted(directories)
        or len(directories) != len(set(directories))
    ):
        raise ControlError(
            "final snapshot directory inventory is non-canonical or duplicated"
        )
    for logical in directories:
        relative = Path(logical)
        path = snapshot_root / relative
        if (
            not logical
            or relative.is_absolute()
            or ".." in relative.parts
            or relative.as_posix() != logical
            or path.is_symlink()
            or not path.is_dir()
            or path.stat().st_mode & 0o222
        ):
            raise ControlError(
                f"final snapshot directory is missing or unsafe: {logical}"
            )

    observed_files: set[str] = set()
    observed_directories: set[str] = set()
    for root, directory_names, file_names in os.walk(
        snapshot_root, topdown=True, followlinks=False
    ):
        directory_names.sort()
        file_names.sort()
        root_path = Path(root)
        for name in directory_names:
            path = root_path / name
            if path.is_symlink() or not path.is_dir():
                raise ControlError(
                    f"final snapshot contains an unsafe directory: {path}"
                )
            observed_directories.add(
                path.relative_to(snapshot_root).as_posix()
            )
        for name in file_names:
            path = root_path / name
            if (
                path.is_symlink()
                or not path.is_file()
                or path.stat().st_nlink != 1
                or path.stat().st_mode & 0o222
            ):
                raise ControlError(
                    f"final snapshot contains an unsafe file: {path}"
                )
            relative = path.relative_to(snapshot_root).as_posix()
            if (
                path.parent == snapshot_root
                and name in FINAL_SNAPSHOT_CONTROL_FILENAMES
            ):
                continue
            observed_files.add(relative)
    if observed_files != set(logical_paths) or observed_directories != set(
        directories
    ):
        raise ControlError(
            "final snapshot has missing or unlisted members: "
            f"files={sorted(observed_files ^ set(logical_paths))[:10]}, "
            f"directories={sorted(observed_directories ^ set(directories))[:10]}"
        )

    total_bytes = 0
    for row in inventory:
        path = snapshot_root / str(row["path"])
        if sha256_file(path) != row["sha256"]:
            raise ControlError(
                f"final snapshot payload checksum drifted: {row['path']}"
            )
        total_bytes += path.stat().st_size
    inventory_sha256 = hashlib.sha256(inventory_bytes).hexdigest()

    catalog = _load_json_object(
        control_paths["SNAPSHOT_CATALOG.json"],
        description="final snapshot catalog",
    )
    catalog_fields = {
        "schema_version",
        "snapshot_id",
        "snapshot_kind",
        "created_at",
        "copy_contract",
        "sources",
        "file_count",
        "directory_count",
        "total_bytes",
        "source_inventory_sha256",
        "snapshot_inventory_sha256",
        "elapsed_seconds",
    }
    sources = catalog.get("sources")
    if (
        set(catalog) != catalog_fields
        or catalog.get("schema_version") != FINAL_SNAPSHOT_SCHEMA_VERSION
        or catalog.get("snapshot_kind") != FINAL_SNAPSHOT_KIND
        or catalog.get("snapshot_id") != marker["snapshot_id"]
        or catalog.get("snapshot_id")
        != f"{FINAL_SNAPSHOT_ID_PREFIX}-{inventory_sha256[:16]}"
        or not isinstance(catalog.get("created_at"), str)
        or catalog.get("copy_contract")
        != "independent_regular_files_no_hardlinks_no_symlinks"
        or not isinstance(sources, list)
        or not sources
        or catalog.get("file_count") != len(inventory)
        or catalog.get("directory_count") != len(directories)
        or catalog.get("total_bytes") != total_bytes
        or catalog.get("source_inventory_sha256") != inventory_sha256
        or catalog.get("snapshot_inventory_sha256") != inventory_sha256
        or not isinstance(catalog.get("elapsed_seconds"), (int, float))
        or isinstance(catalog.get("elapsed_seconds"), bool)
        or not math.isfinite(float(catalog["elapsed_seconds"]))
        or float(catalog["elapsed_seconds"]) < 0
        or marker.get("file_count") != len(inventory)
        or marker.get("total_bytes") != total_bytes
        or marker.get("snapshot_inventory_sha256") != inventory_sha256
    ):
        raise ControlError("final snapshot catalog/inventory contract is invalid")
    try:
        created = time.strptime(str(catalog["created_at"]), "%Y-%m-%dT%H:%M:%SZ")
        completed = time.strptime(
            str(marker["completed_at"]), "%Y-%m-%dT%H:%M:%SZ"
        )
    except ValueError as exc:
        raise ControlError("final snapshot catalog timestamp is invalid") from exc
    if created > completed:
        raise ControlError("final snapshot marker predates its catalog")
    source_names: list[str] = []
    observed_source_rows: list[dict[str, str]] = []
    for source in sources:
        if (
            not isinstance(source, dict)
            or set(source) != {"name", "path"}
            or re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9._-]*", str(source.get("name", ""))
            )
            is None
            or not isinstance(source.get("path"), str)
            or not Path(str(source["path"])).is_absolute()
            or str(Path(str(source["path"])).resolve())
            != str(source["path"])
        ):
            raise ControlError("final snapshot catalog source is invalid")
        source_names.append(str(source["name"]))
        observed_source_rows.append(
            {
                "name": str(source["name"]),
                "path": str(source["path"]),
            }
        )
    if (
        len(source_names) != len(set(source_names))
        or observed_source_rows
        != sorted(observed_source_rows, key=lambda row: row["name"])
        or not FINAL_SNAPSHOT_REQUIRED_SOURCES.issubset(source_names)
        or set(source_names)
        - FINAL_SNAPSHOT_REQUIRED_SOURCES
        - FINAL_SNAPSHOT_OPTIONAL_SOURCES
        or {
            Path(path).parts[0] for path in [*logical_paths, *directories]
        }
        != set(source_names)
    ):
        raise ControlError("final snapshot catalog source set is invalid")
    if expected_sources is not None:
        expected_source_rows = _final_snapshot_source_rows(expected_sources)
        if observed_source_rows != expected_source_rows:
            raise FinalizerProvenanceError(
                "final snapshot source origins differ from the canonical "
                "name-to-path map"
            )
    _validate_final_control_plane_cut(
        snapshot_root / "control",
        expected_bindings=expected_control_cut_bindings,
    )
    return marker, sha256_file(marker_path)


def _final_snapshot_control_hashes(snapshot_root: Path) -> dict[str, str]:
    return {
        name: sha256_file(snapshot_root / name)
        for name in sorted(FINAL_SNAPSHOT_CONTROL_FILENAMES)
    }


def _validate_zero_writer_proof(
    proof: Any,
    *,
    control: Mapping[str, Any],
    semantic_preflight: Mapping[str, Any],
    fleet_retirement: Mapping[str, Any],
    autonomous_finalizer: Mapping[str, Any] | None,
) -> None:
    expected_fields = {
        "schema_version",
        "kind",
        "immutable_sha256",
        "capacity_generation",
        "rollout_generation",
        "desired_state",
        "drain_requested",
        "control_contract_sha256",
        "semantic_preflight_id",
        "fleet_retirement_id",
        "fleet_retirement_completion_id",
        "scheduler_captured_at",
        "scheduler_captured_timestamp",
        "scheduler_squeue_ok",
        "scheduler_sacct_ok",
        "scheduler_errors",
        "active_cell_job_ids",
        "active_controller_job_ids",
        "active_fleet_job_ids",
        "publisher_finalizer",
        "active_finalizer_job_ids",
        "other_active_finalizer_job_ids",
        "successor_retirement",
        "active_cell_locks",
        "proof_id",
    }
    if not isinstance(proof, dict):
        raise ControlError("FINAL_COMPLETE zero-writer proof is not an object")
    without_id = dict(proof)
    proof_id = without_id.pop("proof_id", None)
    timestamp = proof.get("scheduler_captured_timestamp")
    if (
        set(proof) != expected_fields
        or proof.get("schema_version") != 2
        or proof.get("kind") != "schema5_final_zero_writer_proof"
        or proof.get("immutable_sha256") != control["immutable_sha256"]
        or proof.get("capacity_generation")
        != control["capacity"]["current_generation"]
        or proof.get("rollout_generation") != control["rollout_generation"]
        or proof.get("desired_state") != "paused"
        or proof.get("drain_requested") is not True
        or proof.get("control_contract_sha256")
        != sha256_value(_final_semantic_control_contract(control))
        or proof.get("semantic_preflight_id")
        != semantic_preflight.get("preflight_id")
        or proof.get("fleet_retirement_id")
        != fleet_retirement.get("retirement_id")
        or proof.get("fleet_retirement_completion_id")
        != fleet_retirement.get("completion_id")
        or not isinstance(timestamp, (int, float))
        or isinstance(timestamp, bool)
        or not math.isfinite(float(timestamp))
        or float(timestamp) < 0
        or proof.get("scheduler_captured_at")
        != utc_timestamp(float(timestamp))
        or proof.get("scheduler_squeue_ok") is not True
        or proof.get("scheduler_sacct_ok") is not True
        or proof.get("scheduler_errors") != []
        or proof.get("active_cell_job_ids") != []
        or proof.get("active_controller_job_ids") != []
        or proof.get("active_fleet_job_ids") != []
        or proof.get("publisher_finalizer")
        != (
            None
            if autonomous_finalizer is None
            else autonomous_finalizer.get("publisher")
        )
        or proof.get("active_finalizer_job_ids")
        != (
            []
            if autonomous_finalizer is None
            else [autonomous_finalizer["publisher"]["job_id"]]
        )
        or proof.get("other_active_finalizer_job_ids") != []
        or proof.get("successor_retirement")
        != (
            None
            if autonomous_finalizer is None
            else autonomous_finalizer.get("successor_retirement")
        )
        or proof.get("active_cell_locks") != []
        or proof_id != sha256_value(without_id)
    ):
        raise ControlError(
            "FINAL_COMPLETE zero-writer proof is malformed or stale"
        )


def _verify_final_complete(
    output_root: Path, *, control: Mapping[str, Any]
) -> dict[str, Any]:
    marker_path = output_root / FINAL_COMPLETE_FILENAME
    if (
        marker_path.is_symlink()
        or not marker_path.is_file()
        or marker_path.stat().st_nlink != 1
    ):
        raise ControlError("FINAL_COMPLETE.json is missing or unsafe")
    marker = _load_json_object(marker_path, description="final completion marker")
    expected_fields = {
        "schema_version",
        "kind",
        "complete",
        "release_id",
        "immutable_sha256",
        "capacity_generation",
        "rollout_generation",
        "completed_at",
        "completed_timestamp",
        "run_ids",
        "complete_cells",
        "trusted_qids",
        "semantic_report",
        "semantic_report_sha256",
        "semantic_preflight",
        "semantic_preflight_sha256",
        "analysis_cache",
        "analysis_manifest_sha256",
        "analysis_tree_sha256",
        "trusted_generation_catalog",
        "trusted_generation_catalog_marker_sha256",
        "trusted_generation_catalog_inventory_sha256",
        "trusted_generation_catalog_payload_sha256",
        "trusted_generation_catalog_id",
        "snapshot",
        "snapshot_marker_sha256",
        "snapshot_control_artifacts",
        "snapshot_source_map",
        "control_cut_bindings",
        "fleet_retirement",
        "fleet_retirement_marker_sha256",
        "autonomous_finalizer",
        "zero_writer_proof",
        "final_id",
    }
    without_id = dict(marker)
    final_id = without_id.pop("final_id", None)
    completed_timestamp = marker.get("completed_timestamp")
    if (
        set(marker) != expected_fields
        or marker.get("schema_version") != 4
        or marker.get("kind") != "schema5_final_completion"
        or marker.get("complete") is not True
        or marker.get("complete_cells") != EXPECTED_TOTAL_CELLS
        or marker.get("trusted_qids") != EXPECTED_TOTAL_QIDS
        or marker.get("run_ids") != list(REQUIRED_RUNS)
        or not isinstance(completed_timestamp, (int, float))
        or isinstance(completed_timestamp, bool)
        or not math.isfinite(float(completed_timestamp))
        or float(completed_timestamp) < 0
        or marker.get("completed_at")
        != utc_timestamp(float(completed_timestamp))
        or final_id != sha256_value(without_id)
    ):
        raise ControlError("FINAL_COMPLETE.json is malformed")
    semantic_path = Path(str(marker["semantic_report"]))
    semantic_preflight_path = Path(str(marker["semantic_preflight"]))
    cache_root = Path(str(marker["analysis_cache"]))
    snapshot_root = Path(str(marker["snapshot"]))
    retirement_root = Path(str(marker["fleet_retirement"]))
    catalog_marker_path = Path(
        str(marker["trusted_generation_catalog"])
    ).resolve()
    snapshot_control_artifacts = marker.get("snapshot_control_artifacts")
    if (
        semantic_path.is_symlink()
        or not semantic_path.is_file()
        or sha256_file(semantic_path) != marker["semantic_report_sha256"]
        or semantic_preflight_path.is_symlink()
        or not semantic_preflight_path.is_file()
        or semantic_preflight_path.resolve()
        != (output_root / FINAL_SEMANTIC_PREFLIGHT_FILENAME).resolve()
        or sha256_file(semantic_preflight_path)
        != marker["semantic_preflight_sha256"]
        or sha256_file(cache_root / "ingest_manifest_v1.json")
        != marker["analysis_manifest_sha256"]
        or _directory_inventory(cache_root)[1] != marker["analysis_tree_sha256"]
        or catalog_marker_path.is_symlink()
        or not catalog_marker_path.is_file()
        or snapshot_root.is_symlink()
        or snapshot_root.resolve()
        != (output_root / FINAL_SNAPSHOT_DIRNAME).resolve()
        or sha256_file(
            retirement_root / FINAL_FLEET_RETIREMENT_COMPLETE_FILENAME
        )
        != marker["fleet_retirement_marker_sha256"]
        or retirement_root.is_symlink()
        or retirement_root.resolve()
        != (output_root / FINAL_FLEET_RETIREMENT_DIRNAME).resolve()
    ):
        raise ControlError("FINAL_COMPLETE.json referenced artifact drifted")
    try:
        trusted_catalog = validate_trusted_generation_catalog(
            catalog_marker_path,
            server_pool_root=Path(
                str(control["immutable"]["server_pool_root"])
            ).resolve(),
        )
    except GenerationCatalogError as exc:
        raise ControlError(
            f"FINAL_COMPLETE trusted-generation catalog is invalid: {exc}"
        ) from exc
    if (
        trusted_catalog.marker_sha256
        != marker["trusted_generation_catalog_marker_sha256"]
        or trusted_catalog.inventory_sha256
        != marker["trusted_generation_catalog_inventory_sha256"]
        or trusted_catalog.catalog_sha256
        != marker["trusted_generation_catalog_payload_sha256"]
        or trusted_catalog.catalog_id
        != marker["trusted_generation_catalog_id"]
    ):
        raise ControlError("FINAL_COMPLETE trusted-generation pins drifted")
    _, semantic_sha256, _, semantic_preflight_sha256 = (
        _verify_final_semantic_preflight(output_root, control=control)
    )
    semantic_report = _load_json_object(
        semantic_path, description="FINAL_COMPLETE semantic report"
    )
    if (
        semantic_sha256 != marker["semantic_report_sha256"]
        or semantic_preflight_sha256 != marker["semantic_preflight_sha256"]
        or semantic_report.get("semantic", {}).get(
            "trusted_generation_catalog"
        )
        != _trusted_generation_catalog_binding(trusted_catalog)
    ):
        raise ControlError("FINAL_COMPLETE.json semantic preflight drifted")
    cache_payload, cache_marker_sha256 = _validate_primary_analysis_cache(
        cache_root,
        control,
        trusted_catalog=trusted_catalog,
    )
    _, cache_tree_sha256 = _directory_inventory(cache_root)
    if (
        cache_marker_sha256 != marker["analysis_manifest_sha256"]
        or cache_tree_sha256 != marker["analysis_tree_sha256"]
    ):
        raise ControlError("FINAL_COMPLETE primary analysis cache drifted")
    fleet_retirement, retirement_marker_sha256 = (
        _verify_final_fleet_retirement(retirement_root, control=control)
    )
    claimed_source_map = marker.get("snapshot_source_map")
    include_semantic_archive = bool(
        isinstance(claimed_source_map, list)
        and any(
            isinstance(row, Mapping)
            and row.get("name") == "semantic_recovery_archive"
            for row in claimed_source_map
        )
    )
    expected_sources = _canonical_final_snapshot_sources(
        control,
        final_root=output_root,
        trusted_catalog_root=trusted_catalog.marker_path.parent,
        include_semantic_archive=include_semantic_archive,
    )
    expected_source_rows = _final_snapshot_source_rows(expected_sources)
    expected_control_cut_bindings = (
        _canonical_final_control_cut_bindings(
            control,
            semantic_report_sha256=semantic_sha256,
            semantic_preflight_sha256=semantic_preflight_sha256,
            retirement=fleet_retirement,
            retirement_marker_sha256=retirement_marker_sha256,
            cache_payload=cache_payload,
            cache_marker_sha256=cache_marker_sha256,
            cache_tree_sha256=cache_tree_sha256,
            trusted_catalog=trusted_catalog,
        )
    )
    if claimed_source_map != expected_source_rows:
        raise ControlError(
            "FINAL_COMPLETE snapshot source origins drifted from the canonical map"
        )
    if marker.get("control_cut_bindings") != expected_control_cut_bindings:
        raise ControlError(
            "FINAL_COMPLETE control-cut bindings drifted from final artifacts"
        )
    _, snapshot_marker_sha256 = _validate_final_snapshot_marker(
        snapshot_root,
        expected_sources=expected_sources,
        expected_control_cut_bindings=expected_control_cut_bindings,
    )
    if (
        snapshot_marker_sha256 != marker["snapshot_marker_sha256"]
        or not isinstance(snapshot_control_artifacts, dict)
        or set(snapshot_control_artifacts)
        != FINAL_SNAPSHOT_CONTROL_FILENAMES
        or snapshot_control_artifacts
        != _final_snapshot_control_hashes(snapshot_root)
    ):
        raise ControlError("FINAL_COMPLETE.json snapshot controls drifted")
    snapshot_catalog_marker = (
        snapshot_root
        / "trusted_generation_catalog"
        / CATALOG_MARKER
    )
    try:
        snapshot_catalog = validate_trusted_generation_catalog(
            snapshot_catalog_marker,
            server_pool_root=snapshot_root / "server_pool",
        )
    except GenerationCatalogError as exc:
        raise ControlError(
            f"final snapshot trusted-generation catalog is invalid: {exc}"
        ) from exc
    if (
        snapshot_catalog.marker_sha256 != trusted_catalog.marker_sha256
        or snapshot_catalog.inventory_sha256
        != trusted_catalog.inventory_sha256
        or snapshot_catalog.catalog_sha256 != trusted_catalog.catalog_sha256
        or snapshot_catalog.catalog_id != trusted_catalog.catalog_id
    ):
        raise ControlError(
            "final snapshot trusted-generation catalog differs from FINAL_COMPLETE"
        )
    if (
        marker.get("release_id") != control["immutable"]["release_id"]
        or marker.get("immutable_sha256") != control["immutable_sha256"]
        or marker.get("capacity_generation")
        != control["capacity"]["current_generation"]
        or marker.get("rollout_generation") != control["rollout_generation"]
    ):
        raise ControlError("FINAL_COMPLETE.json does not bind the current control")
    semantic_preflight = _load_json_object(
        semantic_preflight_path,
        description="final semantic preflight marker",
    )
    autonomous_finalizer = marker.get("autonomous_finalizer")
    if autonomous_finalizer is None:
        if control["finalization"]["state"] != "idle":
            raise ControlError(
                "manual FINAL_COMPLETE cannot bless an autonomous finalization"
            )
    elif (
        not isinstance(autonomous_finalizer, dict)
        or autonomous_finalizer
        != _autonomous_finalizer_completion_binding(control)
    ):
        raise ControlError(
            "FINAL_COMPLETE autonomous finalizer retirement binding drifted"
        )
    _validate_zero_writer_proof(
        marker.get("zero_writer_proof"),
        control=control,
        semantic_preflight=semantic_preflight,
        fleet_retirement=fleet_retirement,
        autonomous_finalizer=autonomous_finalizer,
    )
    if marker_path.stat().st_mode & 0o222:
        raise ControlError("FINAL_COMPLETE.json is not sealed read-only")
    return marker


def _verify_completed_finalization_control_binding(
    control: Mapping[str, Any],
) -> dict[str, Any]:
    """Re-prove the exact terminal marker bound by completed control state.

    This helper deliberately accepts an already-loaded control object.  It must not
    call :func:`load_control`: completed-state validation invokes it from the control
    loader, and a second load would recurse instead of proving the terminal artifact.
    """

    finalization = control["finalization"]
    if finalization.get("state") != "complete":
        raise ControlError(
            "terminal finalization binding requires complete control state"
        )
    completion = finalization["completion_marker"]
    output_root = Path(str(finalization["output_root"])).expanduser().resolve()
    marker_path = output_root / FINAL_COMPLETE_FILENAME
    bound_path = Path(str(completion["path"])).expanduser()
    if (
        not bound_path.is_absolute()
        or bound_path != marker_path
        or marker_path.is_symlink()
        or not marker_path.is_file()
        or marker_path.stat().st_nlink != 1
        or marker_path.stat().st_mode & 0o222
    ):
        raise ControlError(
            "completed finalization marker is missing, unsafe, or not exactly bound"
        )
    marker_sha256 = sha256_file(marker_path)
    if marker_sha256 != completion["sha256"]:
        raise ControlError("completed finalization marker checksum drifted")
    verified = _verify_final_complete(output_root, control=control)
    if verified.get("final_id") != completion["final_id"]:
        raise ControlError("completed finalization marker identity drifted")
    return verified


def _record_autonomous_finalizer_phase(
    state_dir: Path,
    *,
    publisher_finalizer: Mapping[str, Any],
    phase: str,
    bindings: Mapping[str, Any],
    now: float,
) -> dict[str, Any]:
    """Commit one monotonic phase and merge marker-bound artifact identities."""

    if phase not in {"validating", "retiring_fleet", "snapshotting"}:
        raise FinalizerInvariantError(f"unsupported finalizer phase {phase!r}")
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        finalization = control["finalization"]
        active = finalization.get("active_job")
        if (
            finalization.get("state") not in ACTIVE_FINALIZATION_STATES
            or not isinstance(active, Mapping)
            or _finalizer_job_identity(active)
            != _finalizer_job_identity(publisher_finalizer)
        ):
            raise ControllerFenced(
                "autonomous finalizer phase publisher no longer owns control"
            )
        evidence = finalization["phase_evidence"]
        existing = evidence.get(phase)
        changed = False
        if existing is None:
            existing = {
                "entered_at": utc_timestamp(now),
                "entered_timestamp": now,
                **copy.deepcopy(dict(bindings)),
            }
            evidence[phase] = existing
            changed = True
            event = f"{phase}_entered"
        else:
            event = f"{phase}_artifacts_bound"
            for field, value in bindings.items():
                if field not in existing:
                    raise FinalizerInvariantError(
                        f"{phase} phase binding has an unknown field {field}"
                    )
                prior = existing[field]
                if prior is not None and value is not None and prior != value:
                    raise FinalizerProvenanceError(
                        f"{phase} phase binding drifted for {field}"
                    )
                if prior is None and value is not None:
                    existing[field] = copy.deepcopy(value)
                    changed = True
        current_state = str(finalization["state"])
        current_rank = FINALIZER_PHASE_ORDER.get(current_state, 0)
        target_rank = FINALIZER_PHASE_ORDER[phase]
        if current_rank < target_rank:
            if target_rank != current_rank + 1:
                raise FinalizerInvariantError(
                    f"finalizer phase cannot skip from {current_state} to {phase}"
                )
            finalization["state"] = phase
            changed = True
        if changed:
            _append_finalization_history(
                finalization,
                event=event,
                details={
                    "phase": phase,
                    "bindings": copy.deepcopy(dict(existing)),
                },
                now=now,
            )
            _save_control(state_dir, control, now=now)
        return copy.deepcopy(existing)


def finalize_sweep(
    state_dir: Path,
    *,
    output_root: Path | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    fleet_evidence_reader: (
        Callable[[Mapping[str, Any]], Mapping[str, Any]] | None
    ) = None,
    command_runner: (
        Callable[
            [Sequence[str], Mapping[str, str], float],
            subprocess.CompletedProcess[str],
        ]
        | None
    ) = None,
    snapshot_builder: (
        Callable[[Path, Sequence[tuple[str, Path]], Mapping[str, str]], Mapping[str, Any]]
        | None
    ) = None,
    lock_scanner: Callable[[Mapping[str, Any]], Sequence[str]] | None = None,
    writer_guard: Callable[[Mapping[str, Any], Path], Any] | None = None,
    publisher_finalizer: Mapping[str, Any] | None = None,
    interruption_controller: _FinalizerInterruptionController | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Publish FINAL_COMPLETE last, after exact data, cache, and snapshot proofs."""

    timestamp = time.time() if now is None else float(now)
    state_dir = state_dir.expanduser().resolve()
    initial = load_control(state_dir, verify_files=True)
    if publisher_finalizer is None:
        if initial["finalization"]["state"] != "idle":
            raise ControllerFenced(
                "autonomous finalization must bind its exact publisher"
            )
    else:
        publisher_identity = _finalizer_job_identity(publisher_finalizer)
        active_record = initial["finalization"].get("active_job")
        if (
            initial["finalization"]["state"] not in ACTIVE_FINALIZATION_STATES
            or not isinstance(active_record, Mapping)
            or _finalizer_job_identity(active_record) != publisher_identity
        ):
            raise ControllerFenced(
                "autonomous finalizer publisher no longer owns control state"
            )
    results_root = Path(initial["immutable"]["results_root"]).resolve()
    final_root = (
        output_root.expanduser().resolve()
        if output_root is not None
        else results_root / "recovery" / "schema5-v1.2-r13" / "final"
    )
    if (
        publisher_finalizer is not None
        and final_root
        != Path(str(initial["finalization"]["output_root"])).expanduser().resolve()
    ):
        raise ControllerFenced(
            "autonomous finalizer output root differs from its durable intent"
        )
    marker_path = final_root / FINAL_COMPLETE_FILENAME
    if marker_path.exists():
        return _verify_final_complete(final_root, control=initial)
    final_root.mkdir(parents=True, exist_ok=True)
    read_scheduler = scheduler_reader or (
        lambda: query_scheduler(tolerate_errors=False)
    )
    run_command = command_runner or (
        lambda argv, environment, timeout: _run_finalizer_process(
            argv,
            environment=environment,
            timeout_seconds=timeout,
            interruption=interruption_controller,
        )
    )
    scan_locks = lock_scanner or _active_manifest_cell_locks
    guard_factory = writer_guard or _final_writer_exclusion
    resolve_fleet = fleet_evidence_reader or _default_fleet_retirement_evidence
    retire_runner = cancel_runner or _run_subprocess
    if interruption_controller is not None:
        interruption_controller.raise_if_requested()
    with finalizer_lock(state_dir):
        # Pause is itself fenced by admission-boundary.lock. A live worker may need
        # one retry after receiving USR1; no audit or cache is written until it drains.
        current = load_control(state_dir)
        if (
            current["desired_state"] != "paused"
            or current.get("drain_requested") is not True
        ):
            pause_control(
                state_dir,
                drain=True,
                scheduler=read_scheduler(),
                cancel_runner=cancel_runner,
                now=timestamp,
            )
        with admission_boundary_lock(state_dir):
            snapshot = read_scheduler()
            _require_complete_quiescent_scheduler(
                snapshot, operation="finalization"
            )
            current = load_control(state_dir, verify_files=True)
            if current["capacity"]["active_transition"] is not None:
                raise ControlError(
                    "finalization cannot cross an incomplete capacity transition"
                )
            if current["admission_safety_hold"]["active"]:
                raise ControlError(
                    "finalization cannot publish through an admission safety hold"
                )
            # Freeze every endpoint identity before the semantic scan.  The monitor
            # and analysis cache consume this exact immutable revision; historical
            # trust never depends on whatever registry pointers remain current later.
            trusted_catalog = refresh_trusted_generation_catalog(
                state_dir,
                target_rollout_generation=int(current["rollout_generation"]),
                now=timestamp,
            )
            trusted_catalog_binding = _trusted_generation_catalog_binding(
                trusted_catalog
            )
            environment = _finalizer_environment(current)
            if interruption_controller is not None:
                interruption_controller.raise_if_requested()
            immutable = current["immutable"]
            harness_python = (
                Path(immutable["harness_environment_prefix"]).resolve()
                / "bin"
                / "python"
            )
            release_root = Path(immutable["release_worktree"]).resolve()
            semantic_path = final_root / FINAL_SEMANTIC_FILENAME
            semantic_preflight_path = (
                final_root / FINAL_SEMANTIC_PREFLIGHT_FILENAME
            )
            semantic_intent_path = (
                final_root / FINAL_SEMANTIC_INTENT_FILENAME
            )
            if publisher_finalizer is not None:
                _record_autonomous_finalizer_phase(
                    state_dir,
                    publisher_finalizer=publisher_finalizer,
                    phase="validating",
                    bindings={
                        "semantic_report_path": str(semantic_path.resolve()),
                        "semantic_intent_path": str(
                            semantic_intent_path.resolve()
                        ),
                        "semantic_preflight_path": str(
                            semantic_preflight_path.resolve()
                        ),
                        "semantic_report_sha256": None,
                        "semantic_intent_sha256": None,
                        "semantic_intent_id": None,
                        "semantic_preflight_sha256": None,
                        "semantic_preflight_id": None,
                    },
                    now=timestamp,
                )

            # Phase one: retain serving capacity while proving the complete dataset.
            # Admission is paused and both controller writers are excluded, but the
            # fleet remains available until the exact semantic report is validated and
            # marker-last sealed.  A partial scan exits here with zero scancel calls and
            # no retirement intent.
            with guard_factory(current, state_dir):
                locked = sorted(str(item) for item in scan_locks(current))
                if locked:
                    raise ControlError(
                        "finalization found active cell locks: "
                        + ", ".join(locked[:20])
                    )
                (
                    _semantic,
                    semantic_report_sha256,
                    _semantic_preflight,
                    semantic_preflight_sha256,
                ) = _ensure_final_semantic_preflight(
                    final_root,
                    control=current,
                    state_dir=state_dir,
                    results_root=results_root,
                    environment=environment,
                    harness_python=harness_python,
                    release_root=release_root,
                    run_command=run_command,
                    now=timestamp,
                )
                if (
                    _semantic.get("semantic", {}).get(
                        "trusted_generation_catalog"
                    )
                    != trusted_catalog_binding
                ):
                    raise ControlError(
                        "final semantic scan did not bind the sealed generation catalog"
                    )
                if publisher_finalizer is not None:
                    semantic_intent = _load_json_object(
                        semantic_intent_path,
                        description="final semantic intent",
                    )
                    _record_autonomous_finalizer_phase(
                        state_dir,
                        publisher_finalizer=publisher_finalizer,
                        phase="validating",
                        bindings={
                            "semantic_report_sha256": semantic_report_sha256,
                            "semantic_intent_sha256": sha256_file(
                                semantic_intent_path
                            ),
                            "semantic_intent_id": semantic_intent["intent_id"],
                            "semantic_preflight_sha256": (
                                semantic_preflight_sha256
                            ),
                            "semantic_preflight_id": _semantic_preflight[
                                "preflight_id"
                            ],
                        },
                        now=timestamp,
                    )
            if interruption_controller is not None:
                interruption_controller.raise_if_requested()

            # Phase two: only sealed semantic acceptance can authorize the immutable
            # exact-ID retirement intent.  Refresh scheduler truth after the potentially
            # long semantic scan before freezing those IDs.
            retirement_root = (
                final_root / FINAL_FLEET_RETIREMENT_DIRNAME
            )
            retirement_intent_path = (
                retirement_root / FINAL_FLEET_RETIREMENT_INTENT_FILENAME
            )
            retirement_marker_path = (
                retirement_root / FINAL_FLEET_RETIREMENT_COMPLETE_FILENAME
            )
            if publisher_finalizer is not None:
                _record_autonomous_finalizer_phase(
                    state_dir,
                    publisher_finalizer=publisher_finalizer,
                    phase="retiring_fleet",
                    bindings={
                        "semantic_report_sha256": semantic_report_sha256,
                        "semantic_preflight_sha256": (
                            semantic_preflight_sha256
                        ),
                        "semantic_preflight_id": _semantic_preflight[
                            "preflight_id"
                        ],
                        "retirement_root": str(retirement_root.resolve()),
                        "retirement_intent_path": str(
                            retirement_intent_path.resolve()
                        ),
                        "retirement_intent_sha256": None,
                        "retirement_id": None,
                        "retirement_marker_path": str(
                            retirement_marker_path.resolve()
                        ),
                        "retirement_marker_sha256": None,
                        "retirement_completion_id": None,
                    },
                    now=timestamp,
                )
            if interruption_controller is not None:
                interruption_controller.raise_if_requested()
            retirement_snapshot = read_scheduler()
            _require_complete_quiescent_scheduler(
                retirement_snapshot,
                operation="semantic-approved final fleet retirement",
            )
            retirement_root, _ = _prepare_final_fleet_retirement(
                current,
                final_root=final_root,
                snapshot=retirement_snapshot,
                semantic_preflight_path=semantic_preflight_path,
                semantic_report_sha256=semantic_report_sha256,
                fleet_evidence_reader=resolve_fleet,
                now=timestamp,
            )
            retirement_intent = _load_json_object(
                retirement_intent_path,
                description="final fleet retirement intent",
            )
            if publisher_finalizer is not None:
                _record_autonomous_finalizer_phase(
                    state_dir,
                    publisher_finalizer=publisher_finalizer,
                    phase="retiring_fleet",
                    bindings={
                        "retirement_intent_sha256": sha256_file(
                            retirement_intent_path
                        ),
                        "retirement_id": retirement_intent["retirement_id"],
                    },
                    now=timestamp,
                )
            with guard_factory(current, state_dir):
                locked = sorted(str(item) for item in scan_locks(current))
                if locked:
                    raise ControlError(
                        "finalization found active cell locks after semantic preflight: "
                        + ", ".join(locked[:20])
                    )
                retirement, remaining_fleet = _advance_final_fleet_retirement(
                    retirement_root,
                    current,
                    scheduler_reader=read_scheduler,
                    cancel_runner=retire_runner,
                    now=timestamp,
                )
                if retirement is None:
                    return {
                        "complete": False,
                        "phase": "fleet_retirement_pending",
                        "retirement_id": _load_json_object(
                            retirement_root
                            / FINAL_FLEET_RETIREMENT_INTENT_FILENAME,
                            description="final fleet retirement intent",
                        )["retirement_id"],
                        "remaining_fleet_job_ids": remaining_fleet,
                    }
                _, retirement_marker_sha256 = _verify_final_fleet_retirement(
                    retirement_root, control=current
                )
                if publisher_finalizer is not None:
                    _record_autonomous_finalizer_phase(
                        state_dir,
                        publisher_finalizer=publisher_finalizer,
                        phase="retiring_fleet",
                        bindings={
                            "retirement_marker_sha256": (
                                retirement_marker_sha256
                            ),
                            "retirement_completion_id": retirement[
                                "completion_id"
                            ],
                        },
                        now=timestamp,
                    )
                if interruption_controller is not None:
                    interruption_controller.raise_if_requested()

                cache_root = final_root / FINAL_ANALYSIS_CACHE_DIRNAME
                cache_marker = cache_root / "ingest_manifest_v1.json"
                snapshot_root = final_root / FINAL_SNAPSHOT_DIRNAME
                snapshot_marker_path = (
                    snapshot_root / "SNAPSHOT_COMPLETE.json"
                )
                if publisher_finalizer is not None:
                    _record_autonomous_finalizer_phase(
                        state_dir,
                        publisher_finalizer=publisher_finalizer,
                        phase="snapshotting",
                        bindings={
                            "retirement_root": str(retirement_root.resolve()),
                            "retirement_marker_path": str(
                                retirement_marker_path.resolve()
                            ),
                            "retirement_marker_sha256": (
                                retirement_marker_sha256
                            ),
                            "retirement_completion_id": retirement[
                                "completion_id"
                            ],
                            "cache_root": str(cache_root.resolve()),
                            "cache_marker_path": str(cache_marker.resolve()),
                            "cache_marker_sha256": None,
                            "cache_generation_id": None,
                            "cache_tree_sha256": None,
                            "snapshot_root": str(snapshot_root.resolve()),
                            "snapshot_marker_path": str(
                                snapshot_marker_path.resolve()
                            ),
                            "snapshot_marker_sha256": None,
                            "snapshot_id": None,
                        },
                        now=timestamp,
                    )
                resumed_cache = None
                if cache_root.exists() and any(cache_root.iterdir()):
                    resumed_cache = _resume_primary_analysis_cache_publication(
                        cache_root,
                        final_root=final_root,
                        control=current,
                        trusted_catalog=trusted_catalog,
                        now=timestamp,
                    )
                    if (
                        resumed_cache is None
                        and (
                            not cache_marker.exists()
                            or (
                                cache_root
                                / ".cache_generation_in_progress.json"
                            ).exists()
                            or (
                                cache_root
                                / "ingest_manifest_v1.previous.json"
                            ).exists()
                        )
                    ):
                        _recover_interrupted_primary_analysis_cache(
                            cache_root,
                            final_root=final_root,
                            now=timestamp,
                        )
                if not cache_marker.exists():
                    if cache_root.exists() and any(cache_root.iterdir()):
                        _recover_interrupted_primary_analysis_cache(
                            cache_root,
                            final_root=final_root,
                            now=timestamp,
                        )
                    cache_root.mkdir(parents=True, exist_ok=True)
                    command = [
                        str(harness_python),
                        "-I",
                        "-u",
                        str(release_root / "analysis" / "nb_lib" / "ingest.py"),
                        "--mode",
                        "primary-schema5",
                        "--run-id",
                        *list(REQUIRED_RUNS),
                        "--out-dir",
                        str(cache_root),
                        "--trusted-generation-catalog",
                        str(trusted_catalog.marker_path),
                        "--server-pool-root",
                        str(Path(immutable["server_pool_root"]).resolve()),
                    ]
                    proc = run_command(
                        command, environment, FINALIZER_COMMAND_DEADLINE_SECONDS
                    )
                    if proc.returncode != 0:
                        raise ControlError(
                            "primary analysis cache build failed: "
                            f"rc={proc.returncode}; {proc.stderr.strip()[:1000]}"
                        )
                    if interruption_controller is not None:
                        interruption_controller.raise_if_requested()
                    _resume_primary_analysis_cache_publication(
                        cache_root,
                        final_root=final_root,
                        control=current,
                        trusted_catalog=trusted_catalog,
                        now=timestamp,
                    )
                cache_payload, cache_marker_sha256 = _validate_primary_analysis_cache(
                    cache_root,
                    current,
                    trusted_catalog=trusted_catalog,
                )
                _seal_read_only_tree(cache_root)
                _, cache_tree_sha256 = _directory_inventory(cache_root)
                if publisher_finalizer is not None:
                    _record_autonomous_finalizer_phase(
                        state_dir,
                        publisher_finalizer=publisher_finalizer,
                        phase="snapshotting",
                        bindings={
                            "cache_marker_sha256": cache_marker_sha256,
                            "cache_generation_id": cache_payload[
                                "cache_generation_id"
                            ],
                            "cache_tree_sha256": cache_tree_sha256,
                        },
                        now=timestamp,
                    )

                control_cut_bindings = (
                    _canonical_final_control_cut_bindings(
                        current,
                        semantic_report_sha256=semantic_report_sha256,
                        semantic_preflight_sha256=semantic_preflight_sha256,
                        retirement=retirement,
                        retirement_marker_sha256=retirement_marker_sha256,
                        cache_payload=cache_payload,
                        cache_marker_sha256=cache_marker_sha256,
                        cache_tree_sha256=cache_tree_sha256,
                        trusted_catalog=trusted_catalog,
                    )
                )
                (
                    control_cut_source,
                    _control_cut_marker,
                    _control_cut_marker_sha256,
                ) = _ensure_final_control_plane_cut(
                    state_dir,
                    final_root=final_root,
                    bindings=control_cut_bindings,
                    now=timestamp,
                )
                sources = list(
                    _canonical_final_snapshot_sources(
                        current,
                        final_root=final_root,
                        trusted_catalog_root=(
                            trusted_catalog.marker_path.parent
                        ),
                    )
                )
                if dict(sources).get("control") != control_cut_source.resolve():
                    raise FinalizerProvenanceError(
                        "canonical final snapshot control origin differs from "
                        "the sealed control cut"
                    )
                if interruption_controller is not None:
                    interruption_controller.raise_if_requested()
                if snapshot_builder is None:
                    snapshot_script = (
                        release_root / "scripts" / "create_recovery_snapshot.py"
                    )
                    command = [
                        str(harness_python),
                        "-u",
                        str(snapshot_script),
                        "--snapshot-root",
                        str(snapshot_root),
                        "--snapshot-kind",
                        FINAL_SNAPSHOT_KIND,
                    ]
                    for name, source in sources:
                        command.extend(("--source", f"{name}={source}"))
                    proc = run_command(
                        command,
                        environment,
                        FINALIZER_SNAPSHOT_DEADLINE_SECONDS,
                    )
                    if proc.returncode != 0:
                        raise ControlError(
                            "final snapshot creation failed: "
                            f"rc={proc.returncode}; {proc.stderr.strip()[:1000]}"
                        )
                    verify_command = [
                        str(harness_python),
                        "-u",
                        str(snapshot_script),
                        "--snapshot-root",
                        str(snapshot_root),
                        "--snapshot-kind",
                        FINAL_SNAPSHOT_KIND,
                        "--verify-only",
                    ]
                    for name, source in sources:
                        verify_command.extend(
                            ("--source", f"{name}={source}")
                        )
                    verify = run_command(
                        verify_command,
                        environment,
                        FINALIZER_SNAPSHOT_DEADLINE_SECONDS,
                    )
                    if verify.returncode != 0:
                        raise ControlError(
                            "final snapshot verification failed: "
                            f"rc={verify.returncode}; {verify.stderr.strip()[:1000]}"
                        )
                else:
                    snapshot_builder(snapshot_root, sources, environment)
                if interruption_controller is not None:
                    interruption_controller.raise_if_requested()
                snapshot_payload, snapshot_marker_sha256 = (
                    _validate_final_snapshot_marker(
                        snapshot_root,
                        expected_sources=sources,
                        expected_control_cut_bindings=(
                            control_cut_bindings
                        ),
                    )
                )
                if publisher_finalizer is not None:
                    _record_autonomous_finalizer_phase(
                        state_dir,
                        publisher_finalizer=publisher_finalizer,
                        phase="snapshotting",
                        bindings={
                            "snapshot_marker_sha256": snapshot_marker_sha256,
                            "snapshot_id": snapshot_payload["snapshot_id"],
                        },
                        now=timestamp,
                    )

                # Re-prove scheduler and per-cell locks immediately before the one
                # publication that declares the experiment final.
                autonomous_binding: dict[str, Any] | None = None
                if interruption_controller is not None:
                    interruption_controller.raise_if_requested()
                if publisher_finalizer is not None:
                    _retire_autonomous_finalizer_successor(
                        state_dir,
                        publisher_record=publisher_finalizer,
                        scheduler_reader=read_scheduler,
                        cancel_runner=cancel_runner,
                        now=timestamp,
                    )
                    current = load_control(state_dir, verify_files=True)
                    autonomous_binding = (
                        _autonomous_finalizer_completion_binding(current)
                    )
                    if (
                        autonomous_binding["publisher"]
                        != _finalizer_job_identity(publisher_finalizer)
                    ):
                        raise ControllerFenced(
                            "autonomous finalizer publisher changed before marker "
                            "publication"
                        )
                final_scheduler = read_scheduler()
                _require_complete_quiescent_scheduler(
                    final_scheduler, operation="final marker publication"
                )
                final_active_fleet = _active_fleet_scope_job_ids(
                    current, final_scheduler
                )
                final_locks = sorted(str(item) for item in scan_locks(current))
                if final_active_fleet or final_locks:
                    raise ControlError(
                        "writer exclusion changed before FINAL_COMPLETE publication: "
                        f"fleet={final_active_fleet}, locks={final_locks[:20]}"
                    )
                active_finalizers = _finalizer_namespace_active_job_ids(
                    final_scheduler
                )
                expected_finalizers = (
                    []
                    if autonomous_binding is None
                    else [autonomous_binding["publisher"]["job_id"]]
                )
                if active_finalizers != expected_finalizers:
                    raise SchedulerAmbiguity(
                        "final marker publication has unexpected active finalizers: "
                        f"expected={expected_finalizers}, observed={active_finalizers}"
                    )
                if autonomous_binding is not None:
                    _finalizer_scheduler_observation(
                        final_scheduler,
                        autonomous_binding["publisher"],
                        require_active=True,
                        context="final marker publisher",
                    )
                zero_writer_proof: dict[str, Any] = {
                    "schema_version": 2,
                    "kind": "schema5_final_zero_writer_proof",
                    "immutable_sha256": current["immutable_sha256"],
                    "capacity_generation": current["capacity"][
                        "current_generation"
                    ],
                    "rollout_generation": current["rollout_generation"],
                    "desired_state": current["desired_state"],
                    "drain_requested": current["drain_requested"],
                    "control_contract_sha256": sha256_value(
                        _final_semantic_control_contract(current)
                    ),
                    "semantic_preflight_id": _semantic_preflight[
                        "preflight_id"
                    ],
                    "fleet_retirement_id": retirement["retirement_id"],
                    "fleet_retirement_completion_id": retirement[
                        "completion_id"
                    ],
                    "scheduler_captured_at": utc_timestamp(
                        final_scheduler.captured_at
                    ),
                    "scheduler_captured_timestamp": (
                        final_scheduler.captured_at
                    ),
                    "scheduler_squeue_ok": final_scheduler.squeue_ok,
                    "scheduler_sacct_ok": final_scheduler.sacct_ok,
                    "scheduler_errors": list(final_scheduler.errors),
                    "active_cell_job_ids": [],
                    "active_controller_job_ids": [],
                    "active_fleet_job_ids": [],
                    "publisher_finalizer": (
                        None
                        if autonomous_binding is None
                        else autonomous_binding["publisher"]
                    ),
                    "active_finalizer_job_ids": active_finalizers,
                    "other_active_finalizer_job_ids": [],
                    "successor_retirement": (
                        None
                        if autonomous_binding is None
                        else autonomous_binding["successor_retirement"]
                    ),
                    "active_cell_locks": [],
                }
                zero_writer_proof["proof_id"] = sha256_value(
                    zero_writer_proof
                )
                _validate_zero_writer_proof(
                    zero_writer_proof,
                    control=current,
                    semantic_preflight=_semantic_preflight,
                    fleet_retirement=retirement,
                    autonomous_finalizer=autonomous_binding,
                )
                if interruption_controller is not None:
                    interruption_controller.raise_if_requested()
                final_payload: dict[str, Any] = {
                    "schema_version": 4,
                    "kind": "schema5_final_completion",
                    "complete": True,
                    "release_id": immutable["release_id"],
                    "immutable_sha256": current["immutable_sha256"],
                    "capacity_generation": current["capacity"]["current_generation"],
                    "rollout_generation": current["rollout_generation"],
                    "completed_at": utc_timestamp(timestamp),
                    "completed_timestamp": timestamp,
                    "run_ids": list(REQUIRED_RUNS),
                    "complete_cells": EXPECTED_TOTAL_CELLS,
                    "trusted_qids": EXPECTED_TOTAL_QIDS,
                    "semantic_report": str(semantic_path),
                    "semantic_report_sha256": semantic_report_sha256,
                    "semantic_preflight": str(semantic_preflight_path),
                    "semantic_preflight_sha256": semantic_preflight_sha256,
                    "analysis_cache": str(cache_root),
                    "analysis_manifest_sha256": cache_marker_sha256,
                    "analysis_tree_sha256": cache_tree_sha256,
                    "trusted_generation_catalog": str(
                        trusted_catalog.marker_path
                    ),
                    "trusted_generation_catalog_marker_sha256": (
                        trusted_catalog.marker_sha256
                    ),
                    "trusted_generation_catalog_inventory_sha256": (
                        trusted_catalog.inventory_sha256
                    ),
                    "trusted_generation_catalog_payload_sha256": (
                        trusted_catalog.catalog_sha256
                    ),
                    "trusted_generation_catalog_id": (
                        trusted_catalog.catalog_id
                    ),
                    "snapshot": str(snapshot_root),
                    "snapshot_marker_sha256": snapshot_marker_sha256,
                    "snapshot_control_artifacts": (
                        _final_snapshot_control_hashes(snapshot_root)
                    ),
                    "snapshot_source_map": _final_snapshot_source_rows(
                        sources
                    ),
                    "control_cut_bindings": control_cut_bindings,
                    "fleet_retirement": str(retirement_root),
                    "fleet_retirement_marker_sha256": (
                        retirement_marker_sha256
                    ),
                    "autonomous_finalizer": autonomous_binding,
                    "zero_writer_proof": zero_writer_proof,
                }
                final_payload["final_id"] = sha256_value(final_payload)
                _atomic_publish_readonly_json(marker_path, final_payload)
    return _verify_final_complete(final_root, control=current)


def finalizer_job_token(
    *, intent_id: str, attempt: int, intent_token: str
) -> str:
    if _SHA256_RE.fullmatch(intent_id) is None:
        raise ControlError("finalizer intent ID is invalid")
    if attempt < 1:
        raise ControlError("finalizer attempt must be positive")
    if re.fullmatch(r"[0-9a-f]{32}", intent_token) is None:
        raise ControlError("finalizer job intent token is invalid")
    return (
        f"{FINALIZER_JOB_TOKEN_PREFIX};intent={intent_id};"
        f"attempt={attempt};token={intent_token}"
    )


def _resolved_finalizer_harness_python(
    immutable: Mapping[str, Any],
) -> Path:
    """Return the sealed, inventory-pinned target of ``bin/python``.

    Conda environments normally expose ``bin/python`` as a same-prefix symlink.
    Rejecting that lexical symlink made autonomous finalization unusable in the
    production environment.  Trust is instead anchored in the sealed environment
    manifest: both the lexical entry and its resolved regular target must occur
    exactly in the pinned directory inventory, and the target itself must be a
    read-only executable inode inside the harness prefix.
    """

    try:
        harness = (
            Path(str(immutable["harness_environment_prefix"]))
            .expanduser()
            .resolve(strict=True)
        )
        lexical = harness / "bin" / "python"
        target = lexical.resolve(strict=True)
        relative_target = target.relative_to(harness)
        relative_lexical = lexical.relative_to(harness)
    except (KeyError, OSError, RuntimeError, ValueError) as exc:
        raise ImmutablePinError(
            "autonomous finalizer Python is unavailable or escapes its harness"
        ) from exc
    if target == harness:
        raise ImmutablePinError(
            "autonomous finalizer Python resolves to the harness directory"
        )
    try:
        target_stat = target.stat(follow_symlinks=False)
    except OSError as exc:
        raise ImmutablePinError(
            "autonomous finalizer Python target cannot be inspected"
        ) from exc
    if (
        not stat.S_ISREG(target_stat.st_mode)
        or target_stat.st_nlink != 1
        or stat.S_IMODE(target_stat.st_mode) & 0o222
        or stat.S_IMODE(target_stat.st_mode) & 0o111 == 0
    ):
        raise ImmutablePinError(
            "autonomous finalizer Python target is not a sealed executable"
        )
    try:
        canonical_target, target_bytes = _read_stable_authorization_file(
            target,
            description="pinned autonomous finalizer harness Python",
        )
    except ReadinessError as exc:
        raise ImmutablePinError(str(exc)) from exc
    if canonical_target != target:
        raise ImmutablePinError(
            "autonomous finalizer Python target is not canonical"
        )

    manifest_path = Path(
        str(immutable.get("harness_environment_manifest_path", ""))
    ).expanduser()
    try:
        canonical_manifest, raw_manifest = _read_stable_authorization_file(
            manifest_path,
            description="pinned finalizer harness environment manifest",
        )
        manifest = _parse_authorization_json(
            raw_manifest,
            description="pinned finalizer harness environment manifest",
        )
    except ReadinessError as exc:
        raise ImmutablePinError(str(exc)) from exc
    if (
        canonical_manifest != manifest_path.resolve()
        or hashlib.sha256(raw_manifest).hexdigest()
        != immutable.get("harness_environment_sha256")
        or Path(str(manifest.get("prefix", ""))).expanduser().resolve()
        != harness
    ):
        raise ImmutablePinError(
            "autonomous finalizer harness manifest does not match immutable pins"
        )
    inventory = manifest.get("directory_inventory")
    entries = inventory.get("entries") if isinstance(inventory, Mapping) else None
    if not isinstance(entries, list):
        raise ImmutablePinError(
            "autonomous finalizer harness inventory is missing"
        )
    by_path: dict[str, Mapping[str, Any]] = {}
    for entry in entries:
        if (
            not isinstance(entry, Mapping)
            or not isinstance(entry.get("path"), str)
            or entry["path"] in by_path
        ):
            raise ImmutablePinError(
                "autonomous finalizer harness inventory is malformed"
            )
        by_path[entry["path"]] = entry
    lexical_entry = by_path.get(relative_lexical.as_posix())
    target_entry = by_path.get(relative_target.as_posix())
    if lexical.is_symlink():
        try:
            link_target = os.readlink(lexical)
        except OSError as exc:
            raise ImmutablePinError(
                "autonomous finalizer Python symlink cannot be inspected"
            ) from exc
        if (
            not isinstance(lexical_entry, Mapping)
            or lexical_entry.get("type") != "symlink"
            or lexical_entry.get("target") != link_target
        ):
            raise ImmutablePinError(
                "autonomous finalizer Python symlink is not inventory-pinned"
            )
    elif (
        not isinstance(lexical_entry, Mapping)
        or lexical_entry.get("type") != "file"
        or target != lexical
    ):
        raise ImmutablePinError(
            "autonomous finalizer Python lexical entry is unsafe"
        )
    target_sha256 = hashlib.sha256(target_bytes).hexdigest()
    if (
        not isinstance(target_entry, Mapping)
        or target_entry.get("type") != "file"
        or target_entry.get("mode") != stat.S_IMODE(target_stat.st_mode)
        or target_entry.get("size") != len(target_bytes)
        or target_entry.get("sha256") != target_sha256
    ):
        raise ImmutablePinError(
            "autonomous finalizer Python target is not inventory-pinned"
        )
    return target


def _render_finalizer_sbatch(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    intent_id: str,
    attempt: int,
    intent_token: str,
) -> Path:
    token = finalizer_job_token(
        intent_id=intent_id,
        attempt=attempt,
        intent_token=intent_token,
    )
    immutable = control["immutable"]
    python = _resolved_finalizer_harness_python(immutable)
    release = Path(str(immutable["release_worktree"])).resolve()
    script = release / "slurm" / "schema5_control.py"
    if (
        script.is_symlink()
        or not script.is_file()
    ):
        raise ImmutablePinError("autonomous finalizer runtime is not immutable")
    finalizer_root = state_dir / FINALIZER_STATE_DIRNAME
    finalizer_root.mkdir(parents=True, exist_ok=True)
    if finalizer_root.is_symlink() or not finalizer_root.is_dir():
        raise ImmutablePinError(
            "autonomous finalizer state directory is unsafe"
        )
    root = finalizer_root / "sbatch"
    log_root = finalizer_root / "logs"
    for directory, description in (
        (root, "sbatch"),
        (log_root, "log"),
    ):
        directory.mkdir(exist_ok=True)
        if directory.is_symlink() or not directory.is_dir():
            raise ImmutablePinError(
                f"autonomous finalizer {description} directory is unsafe"
            )
    target = root / f"finalizer.a{attempt:06d}.{intent_token}.sbatch"
    log = log_root / f"finalizer.a{attempt:06d}.%j.out"
    payload = f"""#!/bin/bash
#SBATCH --job-name=asys-s5-final-a{attempt:06d}
#SBATCH --partition={PRODUCTION_CONTROLLER_PARTITION}
#SBATCH --cpus-per-task=1
#SBATCH --mem={FINALIZER_JOB_MEMORY}
#SBATCH --time={FINALIZER_JOB_TIME_LIMIT}
#SBATCH --signal=B:USR1@1200
#SBATCH --no-requeue
#SBATCH --export=NONE
#SBATCH --output={shlex.quote(str(log))}

set -euo pipefail
umask 027
{_trusted_shell_prelude()}\
unset PYTHONHOME PYTHONPATH VIRTUAL_ENV CONDA_PREFIX CONDA_DEFAULT_ENV
export PYTHONDONTWRITEBYTECODE=1
export PYTHONNOUSERSITE=1
export PYTHONSAFEPATH=1
export HF_HUB_OFFLINE=1
export TRANSFORMERS_OFFLINE=1
export HF_DATASETS_OFFLINE=1
export HF_HOME={shlex.quote(str(Path(str(immutable["hf_home"])).resolve()))}
export ASYS_IMMUTABLE_PINS_SHA256={shlex.quote(str(control["immutable_sha256"]))}
exec {shlex.quote(str(python))} -I -u {shlex.quote(str(script))} \
  --state-dir {shlex.quote(str(state_dir.resolve()))} finalizer-worker \
  --intent-id {shlex.quote(intent_id)} --attempt {attempt}
"""
    required = {
        "#SBATCH --no-requeue",
        "#SBATCH --export=NONE",
        "#SBATCH --signal=B:USR1@1200",
        f"#SBATCH --partition={PRODUCTION_CONTROLLER_PARTITION}",
        f"export PATH={TRUSTED_SYSTEM_PATH}",
        "export GIT_NO_REPLACE_OBJECTS=1",
        f"--intent-id {intent_id} --attempt {attempt}",
    }
    if not all(fragment in payload for fragment in required):
        raise ControlError("rendered autonomous finalizer sbatch is incomplete")
    _validate_trusted_sbatch_bootstrap(
        payload, description="autonomous finalizer sbatch"
    )
    if target.exists():
        if (
            target.is_symlink()
            or not target.is_file()
            or target.read_text(encoding="utf-8") != payload
            or target.stat().st_mode & 0o222
        ):
            raise ImmutablePinError(
                f"autonomous finalizer sbatch drifted: {target}"
            )
        return target
    _atomic_publish_readonly_text(target, payload)
    return target


def _finalizer_scheduler_matches(
    snapshot: SchedulerSnapshot, record: Mapping[str, Any]
) -> list[SchedulerJob]:
    return [
        job
        for job in snapshot.jobs
        if job.comment == record.get("job_token")
    ]


def _finalizer_job_identity(
    record: Mapping[str, Any], *, verify_sbatch: bool = True
) -> dict[str, Any]:
    _validate_finalizer_job_record(record, context="identity")
    job_id = record.get("job_id")
    if not isinstance(job_id, str) or not job_id.isdigit():
        raise ControlError("finalizer identity requires an accepted numeric job ID")
    sbatch_path = Path(str(record["sbatch_path"])).expanduser().resolve()
    if verify_sbatch and (
        sbatch_path.is_symlink()
        or not sbatch_path.is_file()
        or sbatch_path.stat().st_nlink != 1
        or sbatch_path.stat().st_mode & 0o222
        or sha256_file(sbatch_path) != record["sbatch_sha256"]
    ):
        raise ImmutablePinError(
            f"finalizer identity sbatch is unsafe or drifted: {sbatch_path}"
        )
    receipt_path = Path(str(record["spooled_receipt_path"])).resolve()
    if verify_sbatch:
        receipt = _load_json_object(
            receipt_path, description="finalizer exact spool receipt"
        )
        expected_receipt = {
            "schema_version": 1,
            "kind": "schema5_exact_sbatch_spool_receipt",
            "job_id": job_id,
            "job_token": str(record["job_token"]),
            "sbatch_path": str(sbatch_path),
            "sbatch_sha256": str(record["sbatch_sha256"]),
            "spooled_sbatch_sha256": str(record["sbatch_sha256"]),
            "submission_transport": str(record["submission_transport"]),
            "submission_argv": list(record["submission_argv"]),
            "submission_argv_sha256": str(record["submission_argv_sha256"]),
            "submitted_held": True,
            "persistent_hold": bool(record["persistent_hold"]),
        }
        _validate_exact_sbatch_receipt(
            receipt_path, expected=expected_receipt
        )
        if sha256_file(receipt_path) != record["spooled_receipt_sha256"]:
            raise ImmutablePinError("finalizer exact spool receipt hash drifted")
    identity: dict[str, Any] = {
        "attempt": int(record["attempt"]),
        "intent_token": str(record["intent_token"]),
        "job_token": str(record["job_token"]),
        "sbatch_path": str(sbatch_path),
        "sbatch_sha256": str(record["sbatch_sha256"]),
        "submission_transport": str(record["submission_transport"]),
        "submission_argv": list(record["submission_argv"]),
        "submission_argv_sha256": str(record["submission_argv_sha256"]),
        "persistent_hold": bool(record["persistent_hold"]),
        "spooled_receipt_path": str(receipt_path),
        "spooled_receipt_sha256": str(record["spooled_receipt_sha256"]),
        "dependency_job_id": record.get("dependency_job_id"),
        "job_id": job_id,
    }
    identity["identity_id"] = sha256_value(identity)
    return identity


def _validate_finalizer_identity(value: Any, *, context: str) -> None:
    expected = {
        "attempt",
        "intent_token",
        "job_token",
        "sbatch_path",
        "sbatch_sha256",
        "submission_transport",
        "submission_argv",
        "submission_argv_sha256",
        "persistent_hold",
        "spooled_receipt_path",
        "spooled_receipt_sha256",
        "dependency_job_id",
        "job_id",
        "identity_id",
    }
    without_id = dict(value) if isinstance(value, dict) else {}
    identity_id = without_id.pop("identity_id", None)
    dependency = value.get("dependency_job_id") if isinstance(value, dict) else None
    attempt = value.get("attempt") if isinstance(value, dict) else None
    intent_token = value.get("intent_token") if isinstance(value, dict) else None
    token = str(value.get("job_token", "")) if isinstance(value, dict) else ""
    try:
        exact_submission_argv = _exact_sbatch_submission_argv(
            token=token,
            dependency_job_id=dependency if isinstance(dependency, str) else None,
        )
    except ControlError:
        exact_submission_argv = None
    if (
        not isinstance(value, dict)
        or set(value) != expected
        or not isinstance(value.get("attempt"), int)
        or isinstance(value.get("attempt"), bool)
        or int(value["attempt"]) < 1
        or re.fullmatch(r"[0-9a-f]{32}", str(value.get("intent_token", "")))
        is None
        or not str(value.get("job_token", "")).startswith(
            FINALIZER_JOB_TOKEN_PREFIX + ";"
        )
        or not Path(str(value.get("sbatch_path", ""))).is_absolute()
        or _SHA256_RE.fullmatch(str(value.get("sbatch_sha256", ""))) is None
        or value.get("submission_transport")
        != EXACT_SBATCH_SUBMISSION_TRANSPORT
        or not isinstance(value.get("submission_argv"), list)
        or not all(
            isinstance(item, str) for item in value.get("submission_argv", [])
        )
        or value.get("submission_argv") != exact_submission_argv
        or value.get("submission_argv_sha256")
        != _submission_argv_sha256(value.get("submission_argv", []))
        or not isinstance(value.get("persistent_hold"), bool)
        or not Path(str(value.get("spooled_receipt_path", ""))).is_absolute()
        or _SHA256_RE.fullmatch(
            str(value.get("spooled_receipt_sha256", ""))
        )
        is None
        or (
            dependency is not None
            and (not isinstance(dependency, str) or not dependency.isdigit())
        )
        or not str(value.get("job_id", "")).isdigit()
        or identity_id != sha256_value(without_id)
        or re.fullmatch(
            rf"{re.escape(FINALIZER_JOB_TOKEN_PREFIX)};"
            rf"intent=[0-9a-f]{{64}};attempt={int(attempt or 0)};"
            rf"token={re.escape(str(intent_token or ''))}",
            token,
        )
        is None
    ):
        raise ControlError(f"{context} finalizer identity is invalid")


def _finalizer_scheduler_observation(
    snapshot: SchedulerSnapshot,
    identity: Mapping[str, Any],
    *,
    require_active: bool | None,
    context: str,
) -> dict[str, Any]:
    _validate_finalizer_identity(identity, context=context)
    matching_token = [
        job for job in snapshot.jobs if job.comment == identity["job_token"]
    ]
    same_id = [
        job for job in snapshot.jobs if job.job_id == str(identity["job_id"])
    ]
    if len(matching_token) != 1 or len(same_id) != 1 or matching_token != same_id:
        raise SchedulerAmbiguity(
            f"{context} finalizer scheduler identity is absent or ambiguous"
        )
    job = matching_token[0]
    normalized_state = _validate_finalizer_scheduler_envelope(
        job,
        identity,
        require_active=require_active,
        context=context,
    )
    return {
        "job_id": job.job_id,
        "job_name": job.job_name,
        "state": normalized_state,
        "comment": job.comment,
        "command": job.command,
        "source": job.source,
        "dependency": job.dependency,
    }


def _validate_finalizer_scheduler_envelope(
    job: SchedulerJob,
    record: Mapping[str, Any],
    *,
    require_active: bool | None,
    context: str,
) -> str:
    """Validate scheduler identity before any held finalizer can be released."""

    attempt = record.get("attempt")
    dependency = record.get("dependency_job_id")
    if (
        not isinstance(attempt, int)
        or isinstance(attempt, bool)
        or attempt < 1
        or not job.job_id.isdigit()
        or job.comment != record.get("job_token")
    ):
        raise SchedulerAmbiguity(
            f"{context} finalizer scheduler envelope is invalid"
        )
    expected_name = f"asys-s5-final-a{attempt:06d}"
    normalized_state = normalize_scheduler_state(job.state)
    if (
        job.job_name != expected_name
        or (
            dependency is None
            and bool(_normalized_scheduler_dependency(job.dependency))
        )
        or (
            dependency is not None
            and not _dependency_binds_exact_afterany(
                job.dependency, str(dependency)
            )
        )
        or normalized_state
        not in ACTIVE_SCHEDULER_STATES | TERMINAL_SCHEDULER_STATES
        or (require_active is True and normalized_state not in ACTIVE_SCHEDULER_STATES)
        or (
            require_active is False
            and normalized_state not in TERMINAL_SCHEDULER_STATES
        )
    ):
        raise SchedulerAmbiguity(
            f"{context} finalizer scheduler provenance is invalid"
        )
    return normalized_state


def _finalizer_namespace_active_job_ids(
    snapshot: SchedulerSnapshot,
) -> list[str]:
    scoped = {
        job.job_id
        for job in snapshot.jobs
        if job.active
        and (
            job.comment.startswith(FINALIZER_JOB_TOKEN_PREFIX + ";")
            or job.job_name.startswith("asys-s5-final-")
        )
    }
    malformed = sorted(job_id for job_id in scoped if not job_id.isdigit())
    if malformed:
        raise SchedulerAmbiguity(
            f"autonomous finalizer namespace has malformed job IDs: {malformed}"
        )
    return sorted(scoped, key=int)


def _require_complete_finalizer_scheduler(
    snapshot: SchedulerSnapshot, *, operation: str
) -> None:
    if not snapshot.squeue_ok or not snapshot.sacct_ok or snapshot.errors:
        raise SchedulerAmbiguity(
            f"{operation} requires complete squeue+sacct scheduler truth"
        )


def _successor_retirement_root(
    control: Mapping[str, Any], transaction_id: str
) -> Path:
    state_dir = (
        Path(str(control["immutable"]["results_root"])).expanduser().resolve()
        / CONTROL_STATE_DIRNAME
    )
    finalizer_root = state_dir / FINALIZER_STATE_DIRNAME
    retirement_root = (
        finalizer_root / FINALIZER_SUCCESSOR_RETIREMENT_DIRNAME
    )
    for path in (finalizer_root, retirement_root):
        if path.is_symlink() or (path.exists() and not path.is_dir()):
            raise ControlError(
                f"finalizer successor-retirement directory is unsafe: {path}"
            )
    transaction_root = retirement_root / transaction_id
    if transaction_root.is_symlink() or (
        transaction_root.exists() and not transaction_root.is_dir()
    ):
        raise ControlError(
            "finalizer successor-retirement transaction directory is unsafe: "
            f"{transaction_root}"
        )
    return transaction_root


def _successor_retirement_intent_identity(
    control: Mapping[str, Any],
    *,
    publisher: Mapping[str, Any],
    successor: Mapping[str, Any],
) -> dict[str, Any]:
    finalization = control["finalization"]
    payload: dict[str, Any] = {
        "schema_version": FINALIZER_SUCCESSOR_RETIREMENT_SCHEMA_VERSION,
        "protocol": FINALIZER_SUCCESSOR_RETIREMENT_PROTOCOL,
        "kind": "schema5_finalizer_successor_retirement_intent_identity",
        "release_id": control["immutable"]["release_id"],
        "immutable_sha256": control["immutable_sha256"],
        "finalization_intent_id": finalization["intent_id"],
        "publisher": dict(publisher),
        "successor": dict(successor),
    }
    payload["transaction_id"] = sha256_value(payload)
    return payload


def _validate_successor_retirement_intent(
    control: Mapping[str, Any],
    intent: Mapping[str, Any],
    *,
    binding: Mapping[str, Any],
) -> None:
    expected = {
        "schema_version",
        "protocol",
        "kind",
        "release_id",
        "immutable_sha256",
        "finalization_intent_id",
        "publisher",
        "successor",
        "created_at",
        "created_timestamp",
        "transaction_id",
    }
    timestamp = intent.get("created_timestamp")
    identity = {
        key: copy.deepcopy(value)
        for key, value in intent.items()
        if key not in {"created_at", "created_timestamp", "transaction_id"}
    }
    expected_transaction_id = sha256_value(identity)
    if (
        set(intent) != expected
        or intent.get("schema_version")
        != FINALIZER_SUCCESSOR_RETIREMENT_SCHEMA_VERSION
        or intent.get("protocol") != FINALIZER_SUCCESSOR_RETIREMENT_PROTOCOL
        or intent.get("kind")
        != "schema5_finalizer_successor_retirement_intent_identity"
        or intent.get("release_id") != control["immutable"]["release_id"]
        or intent.get("immutable_sha256") != control["immutable_sha256"]
        or intent.get("finalization_intent_id")
        != control["finalization"]["intent_id"]
        or not isinstance(timestamp, (int, float))
        or isinstance(timestamp, bool)
        or not math.isfinite(float(timestamp))
        or float(timestamp) < 0
        or intent.get("created_at") != utc_timestamp(float(timestamp))
        or intent.get("transaction_id") != expected_transaction_id
        or intent.get("transaction_id") != binding["transaction_id"]
    ):
        raise ControlError("finalizer successor-retirement intent is invalid")
    _validate_finalizer_identity(intent.get("publisher"), context="publisher")
    _validate_finalizer_identity(intent.get("successor"), context="successor")
    if (
        intent["publisher"]["job_token"]
        != finalizer_job_token(
            intent_id=str(intent["finalization_intent_id"]),
            attempt=int(intent["publisher"]["attempt"]),
            intent_token=str(intent["publisher"]["intent_token"]),
        )
        or intent["successor"]["job_token"]
        != finalizer_job_token(
            intent_id=str(intent["finalization_intent_id"]),
            attempt=int(intent["successor"]["attempt"]),
            intent_token=str(intent["successor"]["intent_token"]),
        )
        or
        intent["publisher"]["identity_id"] != binding["publisher_identity_id"]
        or intent["successor"]["identity_id"] != binding["successor_identity_id"]
    ):
        raise ControlError(
            "finalizer successor-retirement intent identity binding drifted"
        )


def _validate_successor_retirement_receipt(
    control: Mapping[str, Any],
    receipt: Mapping[str, Any],
    *,
    intent: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> None:
    expected = {
        "schema_version",
        "protocol",
        "kind",
        "transaction_id",
        "finalization_intent_id",
        "immutable_sha256",
        "intent_sha256",
        "publisher",
        "successor",
        "captured_at",
        "captured_timestamp",
        "scheduler_squeue_ok",
        "scheduler_sacct_ok",
        "scheduler_errors",
        "publisher_observation",
        "successor_observation",
        "active_finalizer_job_ids",
        "other_active_finalizer_job_ids",
        "receipt_id",
    }
    without_id = dict(receipt)
    receipt_id = without_id.pop("receipt_id", None)
    timestamp = receipt.get("captured_timestamp")
    publisher_observation = receipt.get("publisher_observation")
    successor_observation = receipt.get("successor_observation")
    observation_fields = {
        "job_id",
        "job_name",
        "state",
        "comment",
        "command",
        "source",
        "dependency",
    }
    if (
        set(receipt) != expected
        or receipt.get("schema_version")
        != FINALIZER_SUCCESSOR_RETIREMENT_SCHEMA_VERSION
        or receipt.get("protocol") != FINALIZER_SUCCESSOR_RETIREMENT_PROTOCOL
        or receipt.get("kind")
        != "schema5_finalizer_successor_retirement_complete"
        or receipt.get("transaction_id") != intent["transaction_id"]
        or receipt.get("finalization_intent_id")
        != control["finalization"]["intent_id"]
        or receipt.get("immutable_sha256") != control["immutable_sha256"]
        or receipt.get("intent_sha256") != binding["intent_sha256"]
        or receipt.get("publisher") != intent["publisher"]
        or receipt.get("successor") != intent["successor"]
        or not isinstance(timestamp, (int, float))
        or isinstance(timestamp, bool)
        or not math.isfinite(float(timestamp))
        or float(timestamp) < 0
        or receipt.get("captured_at") != utc_timestamp(float(timestamp))
        or receipt.get("scheduler_squeue_ok") is not True
        or receipt.get("scheduler_sacct_ok") is not True
        or receipt.get("scheduler_errors") != []
        or not isinstance(publisher_observation, dict)
        or set(publisher_observation) != observation_fields
        or not isinstance(successor_observation, dict)
        or set(successor_observation) != observation_fields
        or publisher_observation.get("job_id")
        != intent["publisher"]["job_id"]
        or publisher_observation.get("comment")
        != intent["publisher"]["job_token"]
        or normalize_scheduler_state(
            str(publisher_observation.get("state", ""))
        )
        not in ACTIVE_SCHEDULER_STATES
        or successor_observation.get("job_id")
        != intent["successor"]["job_id"]
        or successor_observation.get("comment")
        != intent["successor"]["job_token"]
        or normalize_scheduler_state(
            str(successor_observation.get("state", ""))
        )
        not in TERMINAL_SCHEDULER_STATES
        or receipt.get("active_finalizer_job_ids")
        != [intent["publisher"]["job_id"]]
        or receipt.get("other_active_finalizer_job_ids") != []
        or receipt_id != sha256_value(without_id)
        or receipt_id != binding.get("receipt_id")
    ):
        raise ControlError(
            "finalizer successor-retirement completion receipt is invalid"
        )


def _load_sealed_finalizer_artifact(
    path: Path, *, description: str
) -> tuple[dict[str, Any], str]:
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
    ):
        raise ControlError(f"{description} is missing, unsafe, or unsealed")
    return _load_json_object(path, description=description), sha256_file(path)


def _verify_successor_retirement_artifacts(
    control: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any] | None]:
    _validate_successor_retirement_binding(binding)
    transaction_id = str(binding["transaction_id"])
    root = _successor_retirement_root(control, transaction_id)
    intent_path = Path(str(binding["intent_path"])).expanduser().resolve()
    expected_intent_path = (
        root / FINALIZER_SUCCESSOR_RETIREMENT_INTENT_FILENAME
    ).resolve()
    if intent_path != expected_intent_path:
        raise ControlError(
            "finalizer successor-retirement intent path escapes its transaction"
        )
    intent, intent_sha256 = _load_sealed_finalizer_artifact(
        intent_path, description="finalizer successor-retirement intent"
    )
    if intent_sha256 != binding["intent_sha256"]:
        raise ControlError("finalizer successor-retirement intent checksum drifted")
    _validate_successor_retirement_intent(
        control, intent, binding=binding
    )
    receipt_path_value = binding.get("receipt_path")
    if receipt_path_value is None:
        return intent, None
    receipt_path = Path(str(receipt_path_value)).expanduser().resolve()
    expected_receipt_path = (
        root / FINALIZER_SUCCESSOR_RETIREMENT_COMPLETE_FILENAME
    ).resolve()
    if receipt_path != expected_receipt_path:
        raise ControlError(
            "finalizer successor-retirement receipt path escapes its transaction"
        )
    receipt, receipt_sha256 = _load_sealed_finalizer_artifact(
        receipt_path, description="finalizer successor-retirement receipt"
    )
    if receipt_sha256 != binding["receipt_sha256"]:
        raise ControlError("finalizer successor-retirement receipt checksum drifted")
    _validate_successor_retirement_receipt(
        control, receipt, intent=intent, binding=binding
    )
    return intent, receipt


def _ensure_successor_retirement_intent(
    state_dir: Path,
    *,
    publisher_record: Mapping[str, Any],
    now: float,
) -> dict[str, Any]:
    publisher = _finalizer_job_identity(publisher_record)
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        finalization = control["finalization"]
        if finalization["state"] not in ACTIVE_FINALIZATION_STATES:
            raise ControllerFenced(
                "successor retirement requires active finalization"
            )
        current_publisher = finalization.get("active_job")
        successor_record = finalization.get("successor_job")
        if (
            not isinstance(current_publisher, Mapping)
            or _finalizer_job_identity(current_publisher) != publisher
            or current_publisher.get("state") in {"terminal", "cancelled"}
            or not isinstance(successor_record, Mapping)
        ):
            raise ControllerFenced(
                "successor retirement publisher or successor identity changed"
            )
        successor = _finalizer_job_identity(successor_record)
        identity = _successor_retirement_intent_identity(
            control, publisher=publisher, successor=successor
        )
        transaction_id = str(identity["transaction_id"])
        root = _successor_retirement_root(control, transaction_id)
        intent_path = (
            root / FINALIZER_SUCCESSOR_RETIREMENT_INTENT_FILENAME
        )
        root.mkdir(parents=True, exist_ok=True)
        if root.is_symlink() or not root.is_dir():
            raise ControlError(
                "finalizer successor-retirement transaction root is unsafe"
            )
        if intent_path.exists():
            intent, intent_sha256 = _load_sealed_finalizer_artifact(
                intent_path,
                description="orphaned finalizer successor-retirement intent",
            )
            provisional = {
                "schema_version": FINALIZER_SUCCESSOR_RETIREMENT_SCHEMA_VERSION,
                "protocol": FINALIZER_SUCCESSOR_RETIREMENT_PROTOCOL,
                "transaction_id": transaction_id,
                "publisher_identity_id": publisher["identity_id"],
                "successor_identity_id": successor["identity_id"],
                "intent_path": str(intent_path.resolve()),
                "intent_sha256": intent_sha256,
                "receipt_path": None,
                "receipt_sha256": None,
                "receipt_id": None,
            }
            _validate_successor_retirement_intent(
                control, intent, binding=provisional
            )
        else:
            intent = {
                **identity,
                "created_at": utc_timestamp(now),
                "created_timestamp": now,
            }
            _atomic_publish_readonly_json(intent_path, intent)
            intent_sha256 = sha256_file(intent_path)
        binding = {
            "schema_version": FINALIZER_SUCCESSOR_RETIREMENT_SCHEMA_VERSION,
            "protocol": FINALIZER_SUCCESSOR_RETIREMENT_PROTOCOL,
            "transaction_id": transaction_id,
            "publisher_identity_id": publisher["identity_id"],
            "successor_identity_id": successor["identity_id"],
            "intent_path": str(intent_path.resolve()),
            "intent_sha256": intent_sha256,
            "receipt_path": None,
            "receipt_sha256": None,
            "receipt_id": None,
        }
        existing = finalization.get("successor_retirement")
        if existing is not None:
            _verify_successor_retirement_artifacts(control, existing)
            if existing["transaction_id"] != transaction_id:
                raise ControllerFenced(
                    "a different finalizer successor-retirement transaction is active"
                )
            return copy.deepcopy(existing)
        if successor_record.get("state") in {"terminal", "cancelled"}:
            raise ControllerFenced(
                "terminal successor lacks its durable retirement transaction"
            )
        finalization["successor_retirement"] = binding
        _append_finalization_history(
            finalization,
            event="successor_retirement_intent",
            details={
                "transaction_id": transaction_id,
                "publisher_job_id": publisher["job_id"],
                "successor_job_id": successor["job_id"],
                "intent_sha256": intent_sha256,
            },
            now=now,
        )
        append_transition(
            state_dir,
            control,
            event="finalizer_successor_retirement_intent",
            details={
                "transaction_id": transaction_id,
                "publisher_job_id": publisher["job_id"],
                "successor_job_id": successor["job_id"],
            },
            now=now,
        )
        _save_control(state_dir, control, now=now)
        return copy.deepcopy(binding)


def _retire_autonomous_finalizer_successor(
    state_dir: Path,
    *,
    publisher_record: Mapping[str, Any],
    scheduler_reader: Callable[[], SchedulerSnapshot],
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ),
    now: float,
) -> dict[str, Any]:
    """Retire one exact after-any successor before final marker publication."""

    binding = _ensure_successor_retirement_intent(
        state_dir, publisher_record=publisher_record, now=now
    )
    control = load_control(state_dir, verify_files=True)
    intent, receipt = _verify_successor_retirement_artifacts(control, binding)
    if receipt is not None:
        return copy.deepcopy(binding)
    publisher = intent["publisher"]
    successor = intent["successor"]
    snapshot = scheduler_reader()
    _require_complete_finalizer_scheduler(
        snapshot, operation="finalizer successor retirement"
    )
    _finalizer_scheduler_observation(
        snapshot,
        publisher,
        require_active=True,
        context="publisher",
    )
    successor_observation = _finalizer_scheduler_observation(
        snapshot,
        successor,
        require_active=None,
        context="successor",
    )
    allowed_active_ids = {publisher["job_id"], successor["job_id"]}
    unexpected = sorted(
        set(_finalizer_namespace_active_job_ids(snapshot)) - allowed_active_ids,
        key=int,
    )
    if unexpected:
        raise SchedulerAmbiguity(
            "unmapped autonomous finalizer jobs are active during successor "
            f"retirement: {unexpected}"
        )
    if successor_observation["state"] in ACTIVE_SCHEDULER_STATES:
        invoke = cancel_runner or _run_subprocess
        proc = invoke(["scancel", str(successor["job_id"])])
        post_cancel = scheduler_reader()
        _require_complete_finalizer_scheduler(
            post_cancel, operation="finalizer successor cancellation receipt"
        )
        _finalizer_scheduler_observation(
            post_cancel,
            publisher,
            require_active=True,
            context="publisher",
        )
        successor_observation = _finalizer_scheduler_observation(
            post_cancel,
            successor,
            require_active=None,
            context="successor",
        )
        snapshot = post_cancel
        if successor_observation["state"] in ACTIVE_SCHEDULER_STATES:
            if proc.returncode != 0:
                raise ControlError(
                    "scheduler rejected exact finalizer successor cancellation: "
                    f"rc={proc.returncode}; {proc.stderr.strip()[:500]}"
                )
            raise SchedulerVisibilityPending(
                "finalizer successor cancellation is not terminal in complete "
                "scheduler truth"
            )
    active_finalizers = _finalizer_namespace_active_job_ids(snapshot)
    if active_finalizers != [publisher["job_id"]]:
        raise SchedulerAmbiguity(
            "finalizer successor retirement did not leave exactly its publisher "
            f"active: {active_finalizers}"
        )
    receipt_payload: dict[str, Any] = {
        "schema_version": FINALIZER_SUCCESSOR_RETIREMENT_SCHEMA_VERSION,
        "protocol": FINALIZER_SUCCESSOR_RETIREMENT_PROTOCOL,
        "kind": "schema5_finalizer_successor_retirement_complete",
        "transaction_id": intent["transaction_id"],
        "finalization_intent_id": intent["finalization_intent_id"],
        "immutable_sha256": control["immutable_sha256"],
        "intent_sha256": binding["intent_sha256"],
        "publisher": publisher,
        "successor": successor,
        "captured_at": utc_timestamp(snapshot.captured_at),
        "captured_timestamp": snapshot.captured_at,
        "scheduler_squeue_ok": snapshot.squeue_ok,
        "scheduler_sacct_ok": snapshot.sacct_ok,
        "scheduler_errors": list(snapshot.errors),
        "publisher_observation": _finalizer_scheduler_observation(
            snapshot,
            publisher,
            require_active=True,
            context="publisher",
        ),
        "successor_observation": successor_observation,
        "active_finalizer_job_ids": active_finalizers,
        "other_active_finalizer_job_ids": [],
    }
    receipt_payload["receipt_id"] = sha256_value(receipt_payload)
    receipt_path = (
        _successor_retirement_root(control, str(intent["transaction_id"]))
        / FINALIZER_SUCCESSOR_RETIREMENT_COMPLETE_FILENAME
    )
    if receipt_path.exists():
        existing_receipt, receipt_sha256 = _load_sealed_finalizer_artifact(
            receipt_path,
            description="existing finalizer successor-retirement receipt",
        )
        provisional = {
            **binding,
            "receipt_path": str(receipt_path.resolve()),
            "receipt_sha256": receipt_sha256,
            "receipt_id": existing_receipt.get("receipt_id"),
        }
        _validate_successor_retirement_receipt(
            control,
            existing_receipt,
            intent=intent,
            binding=provisional,
        )
        receipt_payload = existing_receipt
    else:
        _atomic_publish_readonly_json(receipt_path, receipt_payload)
        receipt_sha256 = sha256_file(receipt_path)
    completed_binding = {
        **binding,
        "receipt_path": str(receipt_path.resolve()),
        "receipt_sha256": receipt_sha256,
        "receipt_id": receipt_payload["receipt_id"],
    }
    with control_lock(state_dir):
        updated = load_control(state_dir, verify_files=True)
        finalization = updated["finalization"]
        current_binding = finalization.get("successor_retirement")
        current_publisher = finalization.get("active_job")
        current_successor = finalization.get("successor_job")
        if (
            not isinstance(current_binding, Mapping)
            or current_binding["transaction_id"] != binding["transaction_id"]
            or not isinstance(current_publisher, Mapping)
            or _finalizer_job_identity(current_publisher) != publisher
            or not isinstance(current_successor, Mapping)
            or _finalizer_job_identity(current_successor) != successor
            or finalization["state"] not in ACTIVE_FINALIZATION_STATES
        ):
            raise SchedulerAmbiguity(
                "finalizer identities changed before retirement receipt commit"
            )
        finalization["successor_retirement"] = completed_binding
        current_successor["state"] = (
            "cancelled"
            if successor_observation["state"] == "CANCELLED"
            else "terminal"
        )
        _append_finalization_history(
            finalization,
            event="successor_retirement_complete",
            details={
                "transaction_id": binding["transaction_id"],
                "receipt_id": receipt_payload["receipt_id"],
                "receipt_sha256": receipt_sha256,
                "successor_state": successor_observation["state"],
            },
            now=now,
        )
        append_transition(
            state_dir,
            updated,
            event="finalizer_successor_retirement_complete",
            details={
                "transaction_id": binding["transaction_id"],
                "receipt_id": receipt_payload["receipt_id"],
            },
            now=now,
        )
        _save_control(state_dir, updated, now=now)
    return copy.deepcopy(completed_binding)


def _autonomous_finalizer_completion_binding(
    control: Mapping[str, Any],
) -> dict[str, Any]:
    finalization = control["finalization"]
    publisher_record = finalization.get("active_job")
    successor_record = finalization.get("successor_job")
    retirement = finalization.get("successor_retirement")
    if (
        not isinstance(publisher_record, Mapping)
        or not isinstance(successor_record, Mapping)
        or successor_record.get("state") not in {"terminal", "cancelled"}
        or not isinstance(retirement, Mapping)
        or retirement.get("receipt_path") is None
    ):
        raise ControlError(
            "autonomous finalization lacks terminal successor-retirement proof"
        )
    publisher = _finalizer_job_identity(publisher_record)
    successor = _finalizer_job_identity(successor_record)
    intent, receipt = _verify_successor_retirement_artifacts(control, retirement)
    if (
        receipt is None
        or intent["publisher"] != publisher
        or intent["successor"] != successor
    ):
        raise ControlError(
            "autonomous finalizer completion identities do not match retirement"
        )
    return {
        "publisher": publisher,
        "successor": successor,
        "successor_retirement": {
            "transaction_id": retirement["transaction_id"],
            "receipt_path": retirement["receipt_path"],
            "receipt_sha256": retirement["receipt_sha256"],
            "receipt_id": retirement["receipt_id"],
        },
    }


def _parse_sbatch_job_id(proc: subprocess.CompletedProcess[str]) -> str:
    if proc.returncode != 0:
        raise ControlError(
            f"finalizer sbatch was rejected rc={proc.returncode}: "
            f"{proc.stderr.strip()[:500]}"
        )
    value = proc.stdout.strip().split(";", 1)[0]
    if not value.isdigit():
        raise ControlError(
            f"finalizer sbatch returned an invalid job ID: {proc.stdout!r}"
        )
    return value


def _append_finalizer_transition_once(
    state_dir: Path,
    control: MutableMapping[str, Any],
    *,
    event: str,
    details: Mapping[str, Any],
    now: float,
) -> dict[str, Any]:
    """Append or adopt one exact finalizer transition after a journal-ahead crash."""

    durable = _read_jsonl_locked(
        state_dir / TRANSITION_JOURNAL, missing_ok=True
    )
    memory = list(control.get("transition_history", []))
    if durable[: len(memory)] != memory:
        raise ControlError(
            "transition journal diverged during finalizer transaction replay"
        )
    matches = [
        row
        for row in durable
        if row.get("event") == event
        and row.get("details") == dict(details)
    ]
    if len(matches) > 1:
        raise ControlError(
            f"finalizer transition event {event!r} was journaled more than once"
        )
    if matches:
        if len(durable) > len(memory):
            control["transition_history"] = copy.deepcopy(durable)
            validate_transition_history(control)
        return matches[0]
    return append_transition(
        state_dir,
        control,
        event=event,
        details=details,
        now=now,
    )


def _finalizer_record_scheduler_observation(
    snapshot: SchedulerSnapshot,
    record: Mapping[str, Any],
    job: SchedulerJob,
    *,
    require_active: bool | None,
    context: str,
) -> dict[str, Any]:
    provisional = copy.deepcopy(dict(record))
    if provisional.get("job_id") not in (None, job.job_id):
        raise SchedulerAmbiguity(
            f"{context} finalizer scheduler job ID conflicts with control"
        )
    provisional["job_id"] = job.job_id
    identity = _finalizer_job_identity(provisional)
    return _finalizer_scheduler_observation(
        snapshot,
        identity,
        require_active=require_active,
        context=context,
    )


def _submit_finalizer_job(
    state_dir: Path,
    *,
    field: str,
    attempt: int,
    dependency_job_id: str | None,
    snapshot: SchedulerSnapshot,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    if field not in {"active_job", "successor_job"}:
        raise ControlError("finalizer job field is invalid")
    if not snapshot.squeue_ok or not snapshot.sacct_ok or snapshot.errors:
        raise SchedulerAmbiguity(
            "finalizer submission requires complete squeue+sacct truth"
        )
    timestamp = snapshot.captured_at if now is None else float(now)
    runner = submit_runner or _run_subprocess
    created = False
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        finalization = control["finalization"]
        if finalization["state"] not in ACTIVE_FINALIZATION_STATES:
            raise ControlError("autonomous finalization is not active")
        record = finalization.get(field)
        if isinstance(record, dict):
            if (
                int(record["attempt"]) != int(attempt)
                or record.get("dependency_job_id") != dependency_job_id
            ):
                raise SchedulerAmbiguity(
                    f"finalizer {field} submission intent changed"
                )
            matches = _finalizer_scheduler_matches(snapshot, record)
            if len(matches) > 1:
                raise SchedulerAmbiguity(
                    f"finalizer {field} maps to multiple scheduler jobs"
                )
            if len(matches) == 1:
                job = matches[0]
                try:
                    _validate_finalizer_scheduler_envelope(
                        job,
                        record,
                        require_active=None,
                        context=field,
                    )
                except SchedulerAmbiguity as exc:
                    raise SchedulerAmbiguity(
                        f"finalizer {field} scheduler identity is ambiguous"
                    ) from exc
                proof = _prove_exact_sbatch_and_release(
                    state_dir,
                    record=record,
                    job_id=job.job_id,
                    submit_runner=runner,
                    release_after_proof=True,
                    now=timestamp,
                    scheduler_job=job,
                )
                record.update(proof)
                record["job_id"] = job.job_id
                try:
                    _finalizer_record_scheduler_observation(
                        snapshot,
                        record,
                        job,
                        require_active=None,
                        context=field,
                    )
                except SchedulerAmbiguity as exc:
                    raise SchedulerAmbiguity(
                        f"finalizer {field} scheduler identity is ambiguous"
                    ) from exc
                newly_adopted = record.get("job_id") is None
                newly_adopted = record.get("submitted_timestamp") is None
                record["submitted_at"] = utc_timestamp(timestamp)
                record["submitted_timestamp"] = timestamp
                record["state"] = (
                    "submitted" if job.active else "terminal"
                )
                if newly_adopted:
                    _append_finalization_history(
                        finalization,
                        event="job_submitted",
                        details={
                            "field": field,
                            "attempt": attempt,
                            "job_id": job.job_id,
                        },
                        now=timestamp,
                    )
                    _append_finalizer_transition_once(
                        state_dir,
                        control,
                        event="finalizer_submitted",
                        details={
                            "field": field,
                            "attempt": attempt,
                            "job_id": job.job_id,
                        },
                        now=timestamp,
                    )
                _save_control(state_dir, control, now=timestamp)
                return copy.deepcopy(record)
            if record.get("job_id") is not None:
                same_id = [
                    job
                    for job in snapshot.jobs
                    if job.job_id == str(record["job_id"])
                ]
                if same_id:
                    raise SchedulerAmbiguity(
                        f"finalizer {field} job ID has a token mismatch"
                    )
                submitted = record.get("submitted_timestamp")
                if (
                    isinstance(submitted, (int, float))
                    and timestamp - float(submitted)
                    < SUBMISSION_VISIBILITY_GRACE_SECONDS
                ):
                    raise SchedulerVisibilityPending(
                        f"finalizer {field} is inside scheduler visibility grace"
                    )
                raise SchedulerAmbiguity(
                    f"accepted finalizer {field} disappeared from complete scheduler truth"
                )
            age = timestamp - float(record["created_timestamp"])
            if age < SUBMISSION_VISIBILITY_GRACE_SECONDS:
                raise SchedulerVisibilityPending(
                    f"finalizer {field} submission is inside visibility grace"
                )
        if attempt != int(finalization["next_attempt"]):
            raise ControlError(
                "finalizer submission attempt differs from durable next_attempt"
            )
        intent_token = uuid.uuid4().hex
        intent_id = str(finalization["intent_id"])
        sbatch_path = _render_finalizer_sbatch(
            state_dir,
            control,
            intent_id=intent_id,
            attempt=attempt,
            intent_token=intent_token,
        )
        record = {
            "attempt": attempt,
            "intent_token": intent_token,
            "job_token": finalizer_job_token(
                intent_id=intent_id,
                attempt=attempt,
                intent_token=intent_token,
            ),
            "sbatch_path": str(sbatch_path),
            "sbatch_sha256": sha256_file(sbatch_path),
            "submission_transport": EXACT_SBATCH_SUBMISSION_TRANSPORT,
            "submission_argv": _exact_sbatch_submission_argv(
                token=finalizer_job_token(
                    intent_id=intent_id,
                    attempt=attempt,
                    intent_token=intent_token,
                ),
                dependency_job_id=dependency_job_id,
            ),
            "submission_argv_sha256": None,
            "persistent_hold": False,
            "spooled_receipt_path": None,
            "spooled_receipt_sha256": None,
            "released_at": None,
            "released_timestamp": None,
            "dependency_job_id": dependency_job_id,
            "job_id": None,
            "state": "submitting",
            "created_at": utc_timestamp(timestamp),
            "created_timestamp": timestamp,
            "submitted_at": None,
            "submitted_timestamp": None,
        }
        record["submission_argv_sha256"] = _submission_argv_sha256(
            record["submission_argv"]
        )
        finalization[field] = record
        # Advance the allocator in the same durable mutation as the scheduler intent.
        # A crash after this save can adopt or reset the intent without ever reusing
        # an attempt number.
        finalization["next_attempt"] = attempt + 1
        _append_finalization_history(
            finalization,
            event="job_submission_intent",
            details={
                "field": field,
                "attempt": attempt,
                "intent_token": intent_token,
                "dependency_job_id": dependency_job_id,
            },
            now=timestamp,
        )
        _append_finalizer_transition_once(
            state_dir,
            control,
            event="finalizer_submission_intent",
            details={
                "field": field,
                "attempt": attempt,
                "intent_token": intent_token,
                "dependency_job_id": dependency_job_id,
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        record_copy = copy.deepcopy(record)
        created = True
    if not created:
        raise AssertionError("finalizer submission record was not created")
    sbatch_payload = _stable_readonly_preimage(
        Path(record_copy["sbatch_path"]),
        description="finalizer sbatch at exact submission boundary",
    )
    if (
        hashlib.sha256(sbatch_payload).hexdigest()
        != record_copy["sbatch_sha256"]
    ):
        raise ImmutablePinError(
            "finalizer sbatch changed before exact submission"
        )
    proc = runner(
        _ExactSbatchInvocation(
            record_copy["submission_argv"],
            sbatch_payload,
        )
    )
    completed_at = time.time() if now is None else timestamp
    try:
        job_id = _parse_sbatch_job_id(proc)
    except ControlError as exc:
        submission_error = FinalizerSubmissionError(
            f"finalizer sbatch was rejected: {exc}"
        )
        with control_lock(state_dir):
            control = load_control(state_dir)
            finalization = control["finalization"]
            finalization["last_error"] = {
                "kind": type(submission_error).__name__,
                "message": str(submission_error)[:2000],
                "transient": True,
                "at": utc_timestamp(completed_at),
                "timestamp": completed_at,
            }
            _append_finalization_history(
                finalization,
                event="job_submission_rejected",
                details={"field": field, "attempt": attempt},
                now=completed_at,
            )
            _save_control(state_dir, control, now=completed_at)
        raise submission_error from exc
    proof = _prove_exact_sbatch_and_release(
        state_dir,
        record=record_copy,
        job_id=job_id,
        submit_runner=runner,
        release_after_proof=True,
        now=completed_at,
    )
    with control_lock(state_dir):
        control = load_control(state_dir)
        finalization = control["finalization"]
        current = finalization.get(field)
        if (
            not isinstance(current, dict)
            or current.get("intent_token") != record_copy["intent_token"]
        ):
            raise SchedulerAmbiguity(
                "finalizer submission intent changed during sbatch"
            )
        current["job_id"] = job_id
        current["state"] = "submitted"
        current["submitted_at"] = utc_timestamp(completed_at)
        current["submitted_timestamp"] = completed_at
        current.update(proof)
        finalization["last_error"] = None
        _append_finalization_history(
            finalization,
            event="job_submitted",
            details={"field": field, "attempt": attempt, "job_id": job_id},
            now=completed_at,
        )
        _append_finalizer_transition_once(
            state_dir,
            control,
            event="finalizer_submitted",
            details={"field": field, "attempt": attempt, "job_id": job_id},
            now=completed_at,
        )
        _save_control(state_dir, control, now=completed_at)
        return copy.deepcopy(current)


def _finalization_semantic_evidence(
    state_dir: Path,
    report_path: Path,
    report: Mapping[str, Any],
) -> dict[str, Any]:
    path = _safe_finalization_semantic_report_path(state_dir, report_path)
    file_stat = path.lstat()
    if (
        not stat.S_ISREG(file_stat.st_mode)
        or file_stat.st_nlink != 1
        or file_stat.st_mode & 0o222
    ):
        raise ControlError(
            "autonomous finalization requires sealed monitor semantic evidence"
        )
    _validate_final_semantic_report(report)
    captured = report.get("captured_timestamp")
    if not isinstance(captured, (int, float)) or isinstance(captured, bool):
        raise ControlError("final semantic monitor evidence lacks capture time")
    return {
        "path": str(path),
        "sha256": sha256_file(path),
        "captured_timestamp": float(captured),
    }


def _safe_finalization_semantic_report_path(
    state_dir: Path, report_path: Path
) -> Path:
    """Validate the lexical report path without following any symlink component."""

    expanded = report_path.expanduser()
    if not expanded.is_absolute():
        raise ControlError(
            "autonomous finalization semantic evidence path must be absolute"
        )
    lexical = Path(os.path.abspath(os.fspath(expanded)))
    if lexical != expanded:
        raise ControlError(
            "autonomous finalization semantic evidence path is not lexical"
        )
    monitoring_root = state_dir / "monitoring"
    if monitoring_root not in lexical.parents:
        raise ControlError(
            "autonomous finalization semantic evidence escapes monitoring root"
        )
    current = Path(lexical.anchor)
    for component in lexical.parts[1:]:
        current /= component
        try:
            component_stat = current.lstat()
        except OSError as exc:
            raise ControlError(
                "autonomous finalization semantic evidence path is unavailable"
            ) from exc
        if stat.S_ISLNK(component_stat.st_mode):
            raise ControlError(
                "autonomous finalization semantic evidence path traverses a symlink"
            )
    return lexical


def _finalization_capacity_incident_plan(
    state_dir: Path, control: Mapping[str, Any]
) -> list[str]:
    """Return the only critical causes exact completion may consume.

    A journal-ahead raise has no control-resident alert identity that this transaction
    can resolve safely.  It must first be reconciled by the normal alert retry path.
    Every cause outside the explicit capacity-remediation class remains blocking.
    """

    hold = control["admission_safety_hold"]
    hold_reasons = (
        set(str(reason) for reason in hold["reasons"])
        if hold["active"]
        else set()
    )
    control_critical = set(_active_critical_alerts(control))
    journal_critical = set(_active_critical_alerts_from_journal(state_dir))
    journal_ahead = sorted(journal_critical - control_critical)
    if journal_ahead:
        raise ControlError(
            "finalization cannot consume journal-ahead critical alerts before "
            "control reconciliation: "
            + ", ".join(journal_ahead)
        )
    active_causes = hold_reasons | control_critical | journal_critical
    blocking = sorted(active_causes - CAPACITY_REMEDIATION_ALERT_KEYS)
    if blocking:
        raise ControlError(
            "finalization remains blocked by non-capacity safety causes: "
            + ", ".join(blocking)
        )
    return sorted(active_causes & CAPACITY_REMEDIATION_ALERT_KEYS)


def _append_finalization_transition_once(
    state_dir: Path,
    control: MutableMapping[str, Any],
    *,
    event: str,
    details: Mapping[str, Any],
    intent_id: str,
    now: float,
) -> dict[str, Any]:
    """Append one finalization event, adopting a journal-ahead replay exactly once."""

    if (
        _SHA256_RE.fullmatch(intent_id) is None
        or details.get("intent_id") != intent_id
    ):
        raise ControlError("finalization transition event lacks its exact intent")
    durable = _read_jsonl_locked(
        state_dir / TRANSITION_JOURNAL, missing_ok=True
    )
    memory = list(control.get("transition_history", []))
    if durable[: len(memory)] != memory:
        raise ControlError("transition journal diverged during finalization replay")
    matches = [
        row
        for row in durable
        if row.get("event") == event
        and isinstance(row.get("details"), dict)
        and row["details"].get("intent_id") == intent_id
    ]
    if len(matches) > 1:
        raise ControlError(
            f"finalization transition event {event!r} was journaled more than once"
        )
    if matches:
        if matches[0].get("details") != dict(details):
            raise ControlError(
                f"finalization transition event {event!r} conflicts with replay"
            )
        if len(durable) > len(memory):
            control["transition_history"] = copy.deepcopy(durable)
            validate_transition_history(control)
        return matches[0]
    return append_transition(
        state_dir,
        control,
        event=event,
        details=details,
        now=now,
    )


def _consume_finalization_capacity_incidents_locked(
    state_dir: Path,
    control: MutableMapping[str, Any],
    *,
    intent_id: str,
    incident_keys: Sequence[str],
    alert_resolution_plan: Sequence[Mapping[str, Any]],
    now: float,
) -> list[str]:
    """Resolve and clear only the capacity incidents sealed by finalization intent."""

    consumed = sorted(set(incident_keys))
    if (
        consumed != list(incident_keys)
        or any(key not in CAPACITY_REMEDIATION_ALERT_KEYS for key in consumed)
    ):
        raise ControlError(
            "finalization request intent contains an invalid capacity incident set"
        )
    frozen_plan = _validate_finalization_capacity_alert_resolution_plan(
        list(alert_resolution_plan),
        consumed_capacity_incidents=consumed,
    )
    if not consumed:
        return []
    hold = control["admission_safety_hold"]
    hold_reasons = (
        {str(reason) for reason in hold["reasons"]}
        if hold["active"]
        else set()
    )
    active_critical_causes = (
        hold_reasons
        | set(_active_critical_alerts(control))
        | set(_active_critical_alerts_from_journal(state_dir))
    )
    unbound_causes = active_critical_causes - set(consumed)
    unbound_noncapacity = sorted(
        unbound_causes - CAPACITY_REMEDIATION_ALERT_KEYS
    )
    if unbound_noncapacity:
        raise ControlError(
            "finalization capacity consumption is blocked by non-capacity "
            "safety causes: "
            + ", ".join(unbound_noncapacity)
        )
    if unbound_causes:
        raise ControlError(
            "finalization capacity consumption encountered a newly active "
            "capacity cause outside its immutable incident set: "
            + ", ".join(sorted(unbound_causes))
        )
    durable_alert_records = _read_jsonl_locked(
        state_dir / ALERT_JOURNAL, missing_ok=True
    )
    frozen_alert_ids = {
        str(alert_id)
        for row in frozen_plan
        for alert_id in row["alert_ids"]
    }
    current_unresolved_ids = {
        str(alert["alert_id"])
        for alert in control.get("alerts", [])
        if isinstance(alert, Mapping)
        and alert.get("dedupe_key") in consumed
        and alert.get("resolved_at") is None
    }
    if not current_unresolved_ids.issubset(frozen_alert_ids):
        raise ControlError(
            "finalization capacity consumption encountered a newly active "
            "capacity alert outside its immutable resolution plan"
        )
    resolution_actions: list[
        tuple[MutableMapping[str, Any], dict[str, Any], bool]
    ] = []
    for resolution_binding in frozen_plan:
        dedupe_key = str(resolution_binding["dedupe_key"])
        for alert_id in resolution_binding["alert_ids"]:
            matches = [
                alert
                for alert in control.get("alerts", [])
                if isinstance(alert, dict)
                and alert.get("alert_id") == alert_id
            ]
            if (
                len(matches) != 1
                or matches[0].get("dedupe_key") != dedupe_key
            ):
                raise ControlError(
                    "finalization alert-resolution plan no longer maps to "
                    "exact control alert identity"
                )
            alert = matches[0]
            prior_raises = [
                row
                for row in durable_alert_records
                if row.get("action") == "raised"
                and row.get("alert_id") == alert_id
                and row.get("dedupe_key") == dedupe_key
            ]
            if not prior_raises:
                raise ControlError(
                    "finalization alert-resolution plan lacks its durable raise"
                )
            prior_resolutions = [
                row
                for row in durable_alert_records
                if row.get("action") == "resolved"
                and row.get("alert_id") == alert_id
                and row.get("dedupe_key") == dedupe_key
            ]
            bound_resolutions = [
                row
                for row in prior_resolutions
                if row.get("finalization_intent_id") == intent_id
            ]
            if len(bound_resolutions) > 1:
                raise ControlError(
                    "finalization incident resolution journal contains duplicate replay"
                )
            if bound_resolutions:
                resolution = bound_resolutions[0]
            elif prior_resolutions:
                resolution = prior_resolutions[0]
            else:
                resolution = {
                    "at": utc_timestamp(now),
                    "timestamp": now,
                    "action": "resolved",
                    "alert_id": alert_id,
                    "dedupe_key": dedupe_key,
                    "finalization_intent_id": intent_id,
                }
            resolution_timestamp = resolution.get("timestamp")
            if (
                not isinstance(resolution.get("at"), str)
                or not isinstance(resolution_timestamp, (int, float))
                or isinstance(resolution_timestamp, bool)
            ):
                raise ControlError(
                    "finalization incident resolution replay timestamp is invalid"
                )
            resolution_actions.append(
                (alert, resolution, not bool(prior_resolutions))
            )

    if hold["active"]:
        remaining = sorted(
            reason for reason in hold["reasons"] if reason not in consumed
        )
        if remaining:
            raise ControlError(
                "finalization capacity consumption would clear unrelated "
                "non-capacity hold causes: "
                + ", ".join(remaining)
            )

    # All conflict and replay validation above is read-only.  Only after that
    # preflight succeeds may the transaction append resolution evidence and
    # update its in-memory control projection.
    for alert, resolution, append_resolution in resolution_actions:
        if append_resolution:
            _append_jsonl(state_dir / ALERT_JOURNAL, resolution)
        if alert.get("resolved_at") is None:
            alert["resolved_at"] = resolution["at"]
            alert["resolved_timestamp"] = resolution["timestamp"]

    if hold["active"]:
        previous_reasons = list(hold["reasons"])
        previous_mode = hold["mode"]
        hold["history"].append(
            {
                "event": "cleared",
                "mode": previous_mode,
                "reasons": previous_reasons,
                "at": utc_timestamp(now),
                "timestamp": now,
                "clear_reason": "exact_completion_finalization",
                "consumed_reasons": consumed,
                "finalization_intent_id": intent_id,
            }
        )
        hold.update(
            {
                "active": False,
                "mode": None,
                "reasons": [],
                "consecutive_clean_polls": 0,
                "semantic_clean_after_activation": False,
                "activated_at": None,
                "activated_timestamp": None,
                "activation_id": None,
                "updated_at": utc_timestamp(now),
                "updated_timestamp": now,
                "acknowledged_at": None,
                "acknowledged_timestamp": None,
            }
        )
    _append_finalization_transition_once(
        state_dir,
        control,
        event="finalization_capacity_incidents_consumed",
        details={
            "intent_id": intent_id,
            "dedupe_keys": consumed,
            "resolved_alert_ids": sorted(frozen_alert_ids),
        },
        intent_id=intent_id,
        now=now,
    )
    return consumed


def _pending_finalization_request_payload(
    control: Mapping[str, Any],
) -> dict[str, Any] | None:
    """Return one fenced request transaction not yet adopted by control state."""

    fenced: dict[str, dict[str, Any]] = {}
    adopted: set[str] = set()
    for row in control.get("transition_history", []):
        if not isinstance(row, Mapping) or not isinstance(
            row.get("details"), Mapping
        ):
            continue
        details = row["details"]
        if row.get("event") == "autonomous_finalization_admission_fenced":
            payload = details.get("request_payload")
            if not isinstance(payload, dict):
                raise ControlError(
                    "finalization admission fence lacks its resumable request payload"
                )
            validated = _validate_finalization_request_intent_payload(
                control, payload
            )
            intent_id = str(validated["intent_id"])
            if intent_id in fenced and fenced[intent_id] != validated:
                raise ControlError(
                    "finalization admission fence repeats a conflicting intent"
                )
            fenced[intent_id] = copy.deepcopy(validated)
        elif row.get("event") == "autonomous_finalization_requested":
            intent_id = details.get("intent_id")
            if isinstance(intent_id, str):
                adopted.add(intent_id)
    pending = [
        payload
        for intent_id, payload in fenced.items()
        if intent_id not in adopted
    ]
    if len(pending) > 1:
        raise ControlError(
            "multiple unadopted autonomous finalization requests are fenced"
        )
    if pending and (
        control.get("desired_state") != "paused"
        or control.get("drain_requested") is not True
        or control.get("finalization", {}).get("state") != "idle"
    ):
        raise ControlError(
            "pending autonomous finalization request lost its admission fence"
        )
    return copy.deepcopy(pending[0]) if pending else None


def request_autonomous_finalization(
    state_dir: Path,
    *,
    semantic_report_path: Path,
    semantic_report: Mapping[str, Any] | None = None,
    scheduler: SchedulerSnapshot | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Request finalization, submit its successor chain, then gracefully drain."""

    state_dir = state_dir.expanduser().resolve()
    timestamp = time.time() if now is None else float(now)
    if scheduler is not None and scheduler_reader is not None:
        raise ControlError("finalization accepts scheduler or scheduler_reader, not both")
    resolved_report_path = _safe_finalization_semantic_report_path(
        state_dir, semantic_report_path
    )
    report = _load_json_object(
        resolved_report_path,
        description="autonomous finalization semantic report",
    )
    if semantic_report is not None and dict(semantic_report) != report:
        raise ControlError(
            "semantic report override differs from sealed evidence"
        )
    evidence = _finalization_semantic_evidence(
        state_dir, resolved_report_path, report
    )
    with admission_boundary_lock(state_dir):
        with control_lock(state_dir):
            control = load_control(state_dir, verify_files=True)
            finalization = control["finalization"]
            if finalization["state"] == "complete":
                return copy.deepcopy(finalization)
            if finalization["state"] == "blocked":
                raise ControlError(
                    "blocked finalization requires scientific-integrity review"
                )
            if finalization["state"] == "idle":
                manual_marker = (
                    Path(str(finalization["output_root"]))
                    / FINAL_COMPLETE_FILENAME
                )
                if manual_marker.exists() or manual_marker.is_symlink():
                    _verify_final_complete(
                        Path(str(finalization["output_root"])).resolve(),
                        control=control,
                    )
                    return copy.deepcopy(finalization)
                if control["capacity"]["active_transition"] is not None:
                    raise ControlError(
                        "finalization cannot begin during a capacity transition"
                    )
                pending_request = _pending_finalization_request_payload(
                    control
                )
                if pending_request is None:
                    consumed_capacity_incidents = (
                        _finalization_capacity_incident_plan(
                            state_dir, control
                        )
                    )
                    capacity_alert_resolution_plan = (
                        _finalization_capacity_alert_resolution_plan(
                            control, consumed_capacity_incidents
                        )
                    )
                    request_identity = (
                        _finalization_request_intent_identity(
                            control,
                            semantic_evidence=evidence,
                            consumed_capacity_incidents=(
                                consumed_capacity_incidents
                            ),
                            capacity_alert_resolution_plan=(
                                capacity_alert_resolution_plan
                            ),
                        )
                    )
                    pending_request = {
                        **request_identity,
                        "requested_at": utc_timestamp(timestamp),
                        "requested_timestamp": timestamp,
                        "intent_id": sha256_value(request_identity),
                    }
                    _validate_finalization_request_intent_payload(
                        control, pending_request
                    )
                    control["desired_state"] = "paused"
                    control["drain_requested"] = True
                    _close_open_epoch(
                        control,
                        reason="autonomous_finalization_requested",
                        now=timestamp,
                    )
                    _reset_admission_ramp(
                        state_dir,
                        control,
                        reason="autonomous_finalization_requested",
                        now=timestamp,
                        ceiling=24,
                        clear_last_observation=True,
                    )
                    append_transition(
                        state_dir,
                        control,
                        event="autonomous_finalization_admission_fenced",
                        details={
                            "intent_id": pending_request["intent_id"],
                            "request_payload": copy.deepcopy(
                                pending_request
                            ),
                            "effective_ceiling": 0,
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
                evidence = copy.deepcopy(
                    pending_request["semantic_evidence"]
                )
                consumed_capacity_incidents = list(
                    pending_request["consumed_capacity_incidents"]
                )
                capacity_alert_resolution_plan = copy.deepcopy(
                    pending_request["capacity_alert_resolution_plan"]
                )
                request_intent, request_binding = (
                    _publish_finalization_request_intent(
                        state_dir,
                        control,
                        semantic_evidence=evidence,
                        consumed_capacity_incidents=(
                            consumed_capacity_incidents
                        ),
                        capacity_alert_resolution_plan=(
                            capacity_alert_resolution_plan
                        ),
                        now=float(
                            pending_request["requested_timestamp"]
                        ),
                    )
                )
                if request_intent != pending_request:
                    raise ControlError(
                        "published finalization request differs from its "
                        "durable admission fence"
                    )
                evidence = copy.deepcopy(
                    request_intent["semantic_evidence"]
                )
                intent_id = str(request_intent["intent_id"])
                requested_timestamp = float(
                    request_intent["requested_timestamp"]
                )
                consumed_capacity_incidents = list(
                    request_intent["consumed_capacity_incidents"]
                )
                capacity_alert_resolution_plan = copy.deepcopy(
                    request_intent["capacity_alert_resolution_plan"]
                )
                _consume_finalization_capacity_incidents_locked(
                    state_dir,
                    control,
                    intent_id=intent_id,
                    incident_keys=consumed_capacity_incidents,
                    alert_resolution_plan=capacity_alert_resolution_plan,
                    now=requested_timestamp,
                )
                finalization.update(
                    {
                        "state": "requested",
                        "intent_id": intent_id,
                        "requested_at": request_intent["requested_at"],
                        "requested_timestamp": requested_timestamp,
                        "semantic_evidence": evidence,
                        "request_intent": request_binding,
                        "consumed_capacity_incidents": (
                            consumed_capacity_incidents
                        ),
                        "attempts": 0,
                        "worker_attempts": [],
                        "next_attempt": 1,
                        "phase_evidence": {
                            "validating": None,
                            "retiring_fleet": None,
                            "snapshotting": None,
                        },
                        "active_job": None,
                        "successor_job": None,
                        "successor_retirement": None,
                        "last_error": None,
                        "completion_marker": None,
                    }
                )
                _append_finalization_history(
                    finalization,
                    event="requested",
                    details={
                        "semantic_evidence": evidence,
                        "request_intent": request_binding,
                        "consumed_capacity_incidents": (
                            consumed_capacity_incidents
                        ),
                    },
                    now=requested_timestamp,
                )
                _append_finalization_transition_once(
                    state_dir,
                    control,
                    event="autonomous_finalization_requested",
                    details={
                        "intent_id": intent_id,
                        "semantic_evidence": evidence,
                        "request_intent": request_binding,
                        "consumed_capacity_incidents": (
                            consumed_capacity_incidents
                        ),
                    },
                    intent_id=intent_id,
                    now=requested_timestamp,
                )
                _save_control(state_dir, control, now=timestamp)
    read_scheduler = scheduler_reader or (
        lambda: query_scheduler(tolerate_errors=False)
    )
    snapshot = scheduler or read_scheduler()
    reconcile_autonomous_finalization(
        state_dir,
        snapshot=snapshot,
        submit_runner=submit_runner,
        now=timestamp,
    )
    pause_snapshot = read_scheduler() if scheduler is None else snapshot
    pause_control(
        state_dir,
        drain=True,
        scheduler=pause_snapshot,
        cancel_runner=cancel_runner,
        now=timestamp,
    )
    with control_lock(state_dir):
        control = load_control(state_dir)
        finalization = control["finalization"]
        if finalization["state"] == "requested":
            active = finalization.get("active_job")
            successor = finalization.get("successor_job")
            if not isinstance(active, Mapping) or not isinstance(
                successor, Mapping
            ):
                raise SchedulerAmbiguity(
                    "finalizer reconciliation did not establish a durable pair"
                )
            finalization["state"] = "draining"
            _append_finalization_history(
                finalization,
                event="draining",
                details={
                    "active_job_id": active["job_id"],
                    "successor_job_id": successor["job_id"],
                },
                now=timestamp,
            )
            append_transition(
                state_dir,
                control,
                event="autonomous_finalization_draining",
                details={"intent_id": finalization["intent_id"]},
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
        return copy.deepcopy(finalization)


def _promote_finalizer_successor(
    state_dir: Path, *, job_id: str, attempt: int, now: float
) -> dict[str, Any]:
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        finalization = control["finalization"]
        if finalization["state"] not in ACTIVE_FINALIZATION_STATES:
            raise ControllerFenced(
                "finalizer promotion is fenced after finalization stops"
            )
        active = finalization.get("active_job")
        successor = finalization.get("successor_job")
        if (
            isinstance(active, dict)
            and active.get("job_id") == job_id
            and active.get("attempt") == attempt
        ):
            if active.get("state") in {"terminal", "cancelled"}:
                raise ControllerFenced(
                    "terminal finalizer job cannot be replayed as active"
                )
            active["state"] = "started"
            _save_control(state_dir, control, now=now)
            return copy.deepcopy(active)
        if (
            not isinstance(successor, dict)
            or successor.get("job_id") != job_id
            or successor.get("attempt") != attempt
        ):
            raise ControllerFenced(
                "finalizer worker does not own the active or successor identity"
            )
        if successor.get("state") in {"terminal", "cancelled"}:
            raise ControllerFenced(
                "retired finalizer successor cannot be promoted"
            )
        retirement = finalization.get("successor_retirement")
        if isinstance(retirement, Mapping):
            intent, receipt = _verify_successor_retirement_artifacts(
                control, retirement
            )
            if receipt is not None:
                raise ControllerFenced(
                    "successor has a terminal retirement receipt"
                )
            if intent["successor"] != _finalizer_job_identity(successor):
                raise SchedulerAmbiguity(
                    "successor promotion conflicts with a different retirement "
                    "transaction"
                )
            finalization["successor_retirement"] = None
            _append_finalization_history(
                finalization,
                event="successor_retirement_superseded_by_promotion",
                details={
                    "transaction_id": retirement["transaction_id"],
                    "promoted_job_id": job_id,
                    "attempt": attempt,
                },
                now=now,
            )
        if isinstance(active, dict):
            active["state"] = "terminal"
        successor["state"] = "started"
        finalization["active_job"] = successor
        finalization["successor_job"] = None
        finalization["next_attempt"] = max(
            int(finalization["next_attempt"]), attempt + 1
        )
        _append_finalization_history(
            finalization,
            event="successor_started",
            details={"job_id": job_id, "attempt": attempt},
            now=now,
        )
        _save_control(state_dir, control, now=now)
        return copy.deepcopy(successor)


def _reset_finalizer_chain_for_retry(
    state_dir: Path,
    *,
    reason: str,
    now: float,
) -> None:
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        finalization = control["finalization"]
        if finalization["state"] not in ACTIVE_FINALIZATION_STATES:
            raise ControllerFenced("finalizer retry reset is no longer authorized")
        marker_path = (
            Path(str(finalization["output_root"])) / FINAL_COMPLETE_FILENAME
        )
        if marker_path.exists():
            raise ControlError(
                "cannot replace a finalizer chain after FINAL_COMPLETE publication"
            )
        retirement = finalization.get("successor_retirement")
        details: dict[str, Any] = {"reason": reason}
        if isinstance(retirement, Mapping):
            _verify_successor_retirement_artifacts(control, retirement)
            details["successor_retirement_transaction_id"] = retirement[
                "transaction_id"
            ]
        for field in ("active_job", "successor_job"):
            record = finalization.get(field)
            if isinstance(record, dict):
                record["state"] = "terminal"
                details[f"{field}_job_id"] = record.get("job_id")
        finalization["active_job"] = None
        finalization["successor_job"] = None
        finalization["successor_retirement"] = None
        _append_finalization_history(
            finalization,
            event="chain_reset_for_retry",
            details=details,
            now=now,
        )
        append_transition(
            state_dir,
            control,
            event="autonomous_finalizer_chain_reset",
            details=details,
            now=now,
        )
        _save_control(state_dir, control, now=now)


def _finalizer_submission_rejected(
    finalization: Mapping[str, Any],
    *,
    field: str,
    record: Mapping[str, Any],
) -> bool:
    error = finalization.get("last_error")
    if (
        not isinstance(error, Mapping)
        or error.get("kind") != "FinalizerSubmissionError"
        or not str(error.get("message", "")).startswith(
            "finalizer sbatch was rejected:"
        )
    ):
        return False
    return any(
        row.get("event") == "job_submission_rejected"
        and isinstance(row.get("details"), Mapping)
        and row["details"].get("field") == field
        and row["details"].get("attempt") == record.get("attempt")
        for row in reversed(finalization.get("history", []))
    )


def _finalizer_record_missing_after_grace(
    finalization: Mapping[str, Any],
    *,
    field: str,
    record: Mapping[str, Any],
    snapshot: SchedulerSnapshot,
) -> bool:
    if _finalizer_scheduler_matches(snapshot, record):
        return False
    job_id = record.get("job_id")
    if job_id is not None and any(
        job.job_id == str(job_id) for job in snapshot.jobs
    ):
        raise SchedulerAmbiguity(
            f"finalizer {field} job ID exists with a different token"
        )
    if _finalizer_submission_rejected(
        finalization, field=field, record=record
    ):
        return True
    reference = (
        record.get("submitted_timestamp")
        if record.get("submitted_timestamp") is not None
        else record.get("created_timestamp")
    )
    if (
        not isinstance(reference, (int, float))
        or isinstance(reference, bool)
    ):
        raise ControlError(
            f"finalizer {field} visibility timestamp is invalid"
        )
    if snapshot.captured_at - float(reference) < SUBMISSION_VISIBILITY_GRACE_SECONDS:
        raise SchedulerVisibilityPending(
            f"finalizer {field} is inside scheduler visibility grace"
        )
    return True


def _retire_unavailable_finalizer_successor(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    expected_active: Mapping[str, Any],
    expected_successor: Mapping[str, Any],
    scheduler_job: SchedulerJob | None,
    reason: str,
    now: float,
) -> None:
    """Clear one proven-unavailable successor before allocating its replacement."""

    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        finalization = control["finalization"]
        active = finalization.get("active_job")
        successor = finalization.get("successor_job")
        if (
            not isinstance(active, Mapping)
            or not isinstance(successor, Mapping)
            or active.get("job_token") != expected_active.get("job_token")
            or successor.get("job_token") != expected_successor.get("job_token")
            or finalization.get("successor_retirement") is not None
        ):
            raise SchedulerAmbiguity(
                "finalizer identities changed before successor replacement"
            )
        publisher_observation = _finalizer_scheduler_observation(
            snapshot,
            _finalizer_job_identity(active),
            require_active=True,
            context="replacement publisher",
        )
        successor_observation: dict[str, Any] | None = None
        if scheduler_job is not None:
            successor_observation = _finalizer_record_scheduler_observation(
                snapshot,
                successor,
                scheduler_job,
                require_active=False,
                context="retired successor",
            )
        elif not _finalizer_record_missing_after_grace(
            finalization,
            field="successor_job",
            record=successor,
            snapshot=snapshot,
        ):
            raise AssertionError("missing successor was not eligible for replacement")
        details = {
            "intent_id": finalization["intent_id"],
            "publisher_job_id": active["job_id"],
            "successor_attempt": successor["attempt"],
            "successor_job_id": successor.get("job_id"),
            "successor_job_token": successor["job_token"],
            "successor_record": copy.deepcopy(dict(successor)),
            "publisher_observation": publisher_observation,
            "successor_observation": successor_observation,
            "scheduler_state": (
                None
                if successor_observation is None
                else successor_observation["state"]
            ),
            "reason": reason,
        }
        _append_finalization_history(
            finalization,
            event="successor_retired_for_replacement",
            details=details,
            now=now,
        )
        finalization["successor_job"] = None
        _append_finalizer_transition_once(
            state_dir,
            control,
            event="finalizer_successor_retired_for_replacement",
            details=details,
            now=now,
        )
        _save_control(state_dir, control, now=now)


def _adopt_completed_finalizer_phase_evidence(
    control: Mapping[str, Any],
    finalization: MutableMapping[str, Any],
    *,
    marker: Mapping[str, Any],
    now: float,
) -> None:
    """Recover all durable phases from one independently verified final marker."""

    evidence = finalization["phase_evidence"]
    snapshotting = evidence.get("snapshotting")
    if isinstance(snapshotting, Mapping) and all(
        snapshotting.get(field) is not None
        for field in (
            "cache_marker_sha256",
            "cache_generation_id",
            "cache_tree_sha256",
            "snapshot_marker_sha256",
            "snapshot_id",
        )
    ):
        return
    required_marker_fields = {
        "semantic_report",
        "semantic_report_sha256",
        "semantic_preflight",
        "semantic_preflight_sha256",
        "analysis_cache",
        "analysis_manifest_sha256",
        "analysis_tree_sha256",
        "snapshot",
        "snapshot_marker_sha256",
        "fleet_retirement",
        "fleet_retirement_marker_sha256",
    }
    if not required_marker_fields.issubset(marker):
        raise FinalizerInvariantError(
            "verified final marker lacks phase-adoption bindings"
        )
    output_root = Path(str(finalization["output_root"])).resolve()
    semantic_preflight = _load_json_object(
        Path(str(marker["semantic_preflight"])),
        description="phase-adoption semantic preflight",
    )
    semantic_intent_path = (
        output_root / FINAL_SEMANTIC_INTENT_FILENAME
    ).resolve()
    semantic_intent = _load_json_object(
        semantic_intent_path,
        description="phase-adoption semantic intent",
    )
    retirement_root = Path(str(marker["fleet_retirement"])).resolve()
    retirement_intent_path = (
        retirement_root / FINAL_FLEET_RETIREMENT_INTENT_FILENAME
    )
    retirement_intent = _load_json_object(
        retirement_intent_path,
        description="phase-adoption retirement intent",
    )
    retirement_marker_path = (
        retirement_root / FINAL_FLEET_RETIREMENT_COMPLETE_FILENAME
    )
    retirement_marker = _load_json_object(
        retirement_marker_path,
        description="phase-adoption retirement marker",
    )
    cache_root = Path(str(marker["analysis_cache"])).resolve()
    cache_marker_path = cache_root / "ingest_manifest_v1.json"
    cache_marker = _load_json_object(
        cache_marker_path,
        description="phase-adoption analysis cache",
    )
    snapshot_root = Path(str(marker["snapshot"])).resolve()
    snapshot_marker_path = snapshot_root / "SNAPSHOT_COMPLETE.json"
    snapshot_marker = _load_json_object(
        snapshot_marker_path,
        description="phase-adoption snapshot marker",
    )
    rows = {
        "validating": {
            "entered_at": utc_timestamp(now),
            "entered_timestamp": now,
            "semantic_report_path": str(
                Path(str(marker["semantic_report"])).resolve()
            ),
            "semantic_intent_path": str(semantic_intent_path),
            "semantic_preflight_path": str(
                Path(str(marker["semantic_preflight"])).resolve()
            ),
            "semantic_report_sha256": marker["semantic_report_sha256"],
            "semantic_intent_sha256": sha256_file(semantic_intent_path),
            "semantic_intent_id": semantic_intent["intent_id"],
            "semantic_preflight_sha256": marker[
                "semantic_preflight_sha256"
            ],
            "semantic_preflight_id": semantic_preflight["preflight_id"],
        },
        "retiring_fleet": {
            "entered_at": utc_timestamp(now),
            "entered_timestamp": now,
            "semantic_report_sha256": marker["semantic_report_sha256"],
            "semantic_preflight_sha256": marker[
                "semantic_preflight_sha256"
            ],
            "semantic_preflight_id": semantic_preflight["preflight_id"],
            "retirement_root": str(retirement_root),
            "retirement_intent_path": str(retirement_intent_path),
            "retirement_intent_sha256": sha256_file(
                retirement_intent_path
            ),
            "retirement_id": retirement_intent["retirement_id"],
            "retirement_marker_path": str(retirement_marker_path),
            "retirement_marker_sha256": marker[
                "fleet_retirement_marker_sha256"
            ],
            "retirement_completion_id": retirement_marker["completion_id"],
        },
        "snapshotting": {
            "entered_at": utc_timestamp(now),
            "entered_timestamp": now,
            "retirement_root": str(retirement_root),
            "retirement_marker_path": str(retirement_marker_path),
            "retirement_marker_sha256": marker[
                "fleet_retirement_marker_sha256"
            ],
            "retirement_completion_id": retirement_marker["completion_id"],
            "cache_root": str(cache_root),
            "cache_marker_path": str(cache_marker_path),
            "cache_marker_sha256": marker["analysis_manifest_sha256"],
            "cache_generation_id": cache_marker["cache_generation_id"],
            "cache_tree_sha256": marker["analysis_tree_sha256"],
            "snapshot_root": str(snapshot_root),
            "snapshot_marker_path": str(snapshot_marker_path),
            "snapshot_marker_sha256": marker["snapshot_marker_sha256"],
            "snapshot_id": snapshot_marker["snapshot_id"],
        },
    }
    changed = False
    for phase, row in rows.items():
        existing = evidence.get(phase)
        if existing is None:
            evidence[phase] = row
            changed = True
            continue
        for field, value in row.items():
            prior = existing[field]
            if field in {"entered_at", "entered_timestamp"}:
                continue
            if prior is not None and prior != value:
                raise FinalizerProvenanceError(
                    f"completed marker conflicts with {phase}/{field}"
                )
            if prior is None:
                existing[field] = value
                changed = True
    if changed:
        _append_finalization_history(
            finalization,
            event="completed_artifact_phases_adopted",
            details={"final_id": marker.get("final_id")},
            now=now,
        )


def _commit_autonomous_finalization_complete(
    state_dir: Path, *, now: float
) -> dict[str, Any]:
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        finalization = control["finalization"]
        marker_path = (
            Path(str(finalization["output_root"])) / FINAL_COMPLETE_FILENAME
        )
        if finalization["state"] == "complete":
            verified = _verify_final_complete(
                Path(str(finalization["output_root"])), control=control
            )
            if (
                finalization["completion_marker"]["sha256"]
                != sha256_file(marker_path)
                or finalization["completion_marker"]["final_id"]
                != verified["final_id"]
            ):
                raise ControlError(
                    "completed finalization control binding drifted"
                )
            return copy.deepcopy(finalization)
        if finalization["state"] not in ACTIVE_FINALIZATION_STATES:
            raise ControllerFenced(
                "finalization completion commit is no longer authorized"
            )
        _autonomous_finalizer_completion_binding(control)
        verified = _verify_final_complete(
            Path(str(finalization["output_root"])), control=control
        )
        _adopt_completed_finalizer_phase_evidence(
            control,
            finalization,
            marker=verified,
            now=now,
        )
        finalization["state"] = "complete"
        finalization["completion_marker"] = {
            "path": str(marker_path.resolve()),
            "sha256": sha256_file(marker_path),
            "final_id": str(verified["final_id"]),
        }
        finalization["last_error"] = None
        _append_finalization_history(
            finalization,
            event="complete",
            details={
                "final_id": verified["final_id"],
                "successor_retirement_receipt_id": finalization[
                    "successor_retirement"
                ]["receipt_id"],
            },
            now=now,
        )
        append_transition(
            state_dir,
            control,
            event="autonomous_finalization_complete",
            details={
                "intent_id": finalization["intent_id"],
                "final_id": verified["final_id"],
                "successor_retirement_receipt_id": finalization[
                    "successor_retirement"
                ]["receipt_id"],
            },
            now=now,
        )
        _save_control(state_dir, control, now=now)
        return copy.deepcopy(finalization)


def _read_finalizer_scheduler_truth(
    reader: Callable[[], SchedulerSnapshot],
) -> SchedulerSnapshot:
    """Return complete scheduler truth or one explicit retryable read error."""

    try:
        snapshot = reader()
    except FinalizerRetryableError:
        raise
    except (
        SchedulerAmbiguity,
        SchedulerVisibilityPending,
        ControlError,
        OSError,
        subprocess.TimeoutExpired,
        TimeoutError,
        ConnectionError,
    ) as exc:
        raise FinalizerSchedulerReadError(
            f"finalizer scheduler read failed: {type(exc).__name__}: {exc}"
        ) from exc
    if (
        not isinstance(snapshot, SchedulerSnapshot)
        or not snapshot.squeue_ok
        or not snapshot.sacct_ok
        or snapshot.errors
    ):
        raise FinalizerSchedulerReadError(
            "finalizer scheduler read returned incomplete squeue+sacct truth"
        )
    return snapshot


def _typed_finalizer_failure(
    exc: BaseException,
    *,
    finalization: Mapping[str, Any],
) -> tuple[BaseException, bool]:
    """Classify only an explicit typed infrastructure allowlist as retryable."""

    if isinstance(
        exc,
        (
            FinalizerRetryableError,
            SchedulerVisibilityPending,
        ),
    ):
        return exc, True
    if isinstance(exc, subprocess.TimeoutExpired):
        return (
            FinalizerTimeoutError(
                f"finalizer subprocess timed out: {exc}"
            ),
            True,
        )
    if isinstance(exc, TimeoutError):
        return FinalizerTimeoutError(str(exc)), True
    if isinstance(exc, ConnectionError):
        return FinalizerConnectionError(str(exc)), True
    if isinstance(
        exc,
        (
            FinalizerDeterministicError,
            ImmutablePinError,
            ReadinessError,
            GenerationCatalogError,
        ),
    ):
        return exc, False
    state = str(finalization.get("state", ""))
    if isinstance(exc, ControlError):
        if state == "validating":
            return FinalizerSemanticError(str(exc)), False
        if state == "retiring_fleet":
            return FinalizerProvenanceError(str(exc)), False
        if state == "snapshotting":
            phase = finalization.get("phase_evidence", {}).get("snapshotting")
            if (
                isinstance(phase, Mapping)
                and phase.get("cache_marker_sha256") is None
            ):
                return FinalizerCacheError(str(exc)), False
            return FinalizerSnapshotError(str(exc)), False
        return FinalizerInvariantError(str(exc)), False
    # Unknown exception classes are never admitted into the retry allowlist.
    return exc, False


def _authenticate_or_adopt_finalizer_worker(
    state_dir: Path,
    *,
    intent_id: str,
    attempt: int,
    job_id: str,
    scheduler_reader: Callable[[], SchedulerSnapshot],
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ),
    now: float,
) -> SchedulerSnapshot | None:
    """Fence one worker or adopt its accepted-before-ID submission exactly once.

    A Slurm allocation may start after ``sbatch`` accepted it but before the
    submitter committed the numeric job ID.  The running allocation is allowed to
    close that transaction only when complete scheduler truth maps its environment
    job ID to one exact durable token, immutable sbatch, dependency, and attempt.
    All foreign or ambiguous workers are fenced before the broad execution-failure
    handler, so they cannot mutate authoritative finalization state.
    """

    current = load_control(state_dir, verify_files=True)
    finalization = current["finalization"]
    if finalization.get("intent_id") != intent_id:
        raise ControllerFenced("finalizer worker lost its durable intent")
    if any(
        row["attempt"] == attempt and row["job_id"] == job_id
        for row in finalization["worker_attempts"]
    ):
        return None
    candidates = [
        (field, record)
        for field, record in (
            ("active_job", finalization.get("active_job")),
            ("successor_job", finalization.get("successor_job")),
        )
        if isinstance(record, Mapping) and record.get("attempt") == attempt
    ]
    if len(candidates) != 1:
        raise ControllerFenced(
            "finalizer worker attempt does not match one durable job"
        )
    field, record = candidates[0]
    recorded_job_id = record.get("job_id")
    if recorded_job_id is not None:
        if recorded_job_id != job_id:
            raise ControllerFenced(
                "finalizer worker job ID differs from its durable identity"
            )
        return None
    if record.get("state") != "submitting":
        raise ControllerFenced(
            "ID-less finalizer worker is not backed by a submitting intent"
        )

    snapshot = _read_finalizer_scheduler_truth(scheduler_reader)
    matches = _finalizer_scheduler_matches(snapshot, record)
    if len(matches) != 1 or matches[0].job_id != job_id:
        raise ControllerFenced(
            "ID-less finalizer worker is absent or ambiguous in scheduler truth"
        )
    try:
        _validate_finalizer_scheduler_envelope(
            matches[0],
            record,
            require_active=True,
            context=f"worker self-adoption {field}",
        )
    except ControlError as exc:
        raise ControllerFenced(
            "ID-less finalizer worker scheduler provenance is invalid"
        ) from exc
    adopted = _submit_finalizer_job(
        state_dir,
        field=field,
        attempt=attempt,
        dependency_job_id=record.get("dependency_job_id"),
        snapshot=snapshot,
        submit_runner=submit_runner,
        now=now,
    )
    if adopted.get("job_id") != job_id:
        raise ControllerFenced(
            "finalizer worker self-adoption committed a different job ID"
        )
    return snapshot


def _finalizer_drain_backoff_seconds(
    finalization: Mapping[str, Any], *, now: float
) -> float:
    """Return the remaining durable cadence after the latest drain-pending cut."""

    for row in reversed(finalization.get("history", [])):
        if row.get("event") != "drain_pending":
            continue
        details = row.get("details")
        not_before = (
            details.get("retry_not_before_timestamp")
            if isinstance(details, Mapping)
            else None
        )
        if (
            not isinstance(not_before, (int, float))
            or isinstance(not_before, bool)
            or not math.isfinite(float(not_before))
        ):
            raise FinalizerInvariantError(
                "durable finalizer drain backoff is malformed"
            )
        return max(0.0, float(not_before) - float(now))
    return 0.0


def _exact_live_finalizer_draining_controllers(
    control: Mapping[str, Any],
    snapshot: SchedulerSnapshot,
) -> list[str]:
    """Map every live schema-5 controller to one exact durable record."""

    scoped = [
        job
        for job in snapshot.jobs
        if job.active
        and (
            _controller_job_name(job.job_name)
            or job.comment.startswith(TOKEN_PREFIX)
            or parse_job_token(job.comment) is not None
        )
    ]
    if not scoped:
        return []
    malformed_ids = sorted(
        {job.job_id for job in scoped if not job.job_id.isdigit()}
    )
    if malformed_ids:
        raise SchedulerAmbiguity(
            "draining controller namespace has malformed job IDs: "
            f"{malformed_ids}"
        )
    malformed_provenance_ids = sorted(
        {
            job.job_id
            for job in scoped
            if _controller_job_name(job.job_name)
            and parse_job_token(job.comment) is None
        },
        key=int,
    )
    if malformed_provenance_ids:
        raise SchedulerAmbiguity(
            "controller-named jobs have missing or malformed provenance during "
            f"drain: {malformed_provenance_ids}"
        )
    mapped: dict[str, tuple[str, str, str]] = {}
    for role in ROLE_NAMES:
        role_state = control["controllers"][role]
        for field in ("active", "successor", "submission_intent"):
            record = role_state.get(field)
            if not isinstance(record, Mapping):
                continue
            token = str(record.get("job_token", ""))
            matches = [job for job in scoped if job.comment == token]
            if len(matches) > 1:
                raise SchedulerAmbiguity(
                    f"draining controller {role}/{field} maps to duplicate jobs"
                )
            if not matches:
                recorded_id = record.get("job_id")
                if recorded_id is not None and any(
                    job.job_id == str(recorded_id) for job in scoped
                ):
                    raise SchedulerAmbiguity(
                        f"draining controller {role}/{field} has a token mismatch"
                    )
                continue
            job = matches[0]
            recorded_id = record.get("job_id")
            sbatch_path = str(record.get("sbatch_path", ""))
            dependency = record.get("dependency_job_id")
            parsed = parse_job_token(token)
            expected_name = _rendered_controller_job_name(
                role,
                record.get("generation"),
                record.get("intent_token"),
            )
            if (
                parsed is None
                or parsed.get("role") != role
                or job.job_name != expected_name
                or (
                    recorded_id is not None
                    and str(recorded_id) != job.job_id
                )
                or not job.job_id.isdigit()
                or (
                    dependency is None
                    and bool(_normalized_scheduler_dependency(job.dependency))
                )
                or (
                    dependency is not None
                    and not _dependency_binds_exact_afterany(
                        job.dependency, str(dependency)
                    )
                )
            ):
                raise SchedulerAmbiguity(
                    f"draining controller {role}/{field} provenance is invalid"
                )
            identity = (role, token, sbatch_path)
            prior = mapped.setdefault(job.job_id, identity)
            if prior != identity:
                raise SchedulerAmbiguity(
                    f"draining controller job {job.job_id} maps to multiple identities"
                )
    unexpected = sorted(
        {job.job_id for job in scoped} - set(mapped),
        key=int,
    )
    if unexpected:
        raise SchedulerAmbiguity(
            f"unmapped schema-5 controllers remain live during drain: {unexpected}"
        )
    return sorted(mapped, key=int)


def _finalizer_drain_observation(
    state_dir: Path,
    *,
    control: Mapping[str, Any],
    snapshot: SchedulerSnapshot,
    now: float,
) -> dict[str, Any]:
    """Return one complete, exact drain cut without mutating scheduler state."""

    _require_complete_finalizer_scheduler(
        snapshot, operation="autonomous finalizer drain"
    )
    ledger_cut = _assert_cell_submission_cut_visible(
        state_dir, snapshot, now=now
    )
    running_cells, pending_cells = _exact_live_cell_task_actions(
        state_dir,
        snapshot,
        ledger_preimage=ledger_cut[1],
    )
    mapped_cell_set = {*running_cells, *pending_cells}
    live_cell_set = {
        job.job_id
        for job in snapshot.jobs
        if job.active and _cell_job(job.job_name)
    }
    malformed_cells = sorted(
        {
            value
            for value in mapped_cell_set | live_cell_set
            if _EXACT_CELL_TASK_ID.fullmatch(value) is None
        }
    )
    if malformed_cells:
        raise SchedulerAmbiguity(
            f"finalizer drain has malformed cell task IDs: {malformed_cells}"
        )
    sort_cell = lambda value: tuple(
        int(part) for part in value.split("_", 1)
    )
    mapped_cells = sorted(mapped_cell_set, key=sort_cell)
    live_cells = sorted(live_cell_set, key=sort_cell)
    if mapped_cells != live_cells:
        raise SchedulerAmbiguity(
            "live cell drain mapping differs from complete scheduler truth"
        )
    _assert_dispatcher_ledger_preimage_unchanged(
        state_dir,
        expected_raw=ledger_cut[0],
        description="finalizer drain dispatcher ledger",
    )
    controllers = _exact_live_finalizer_draining_controllers(control, snapshot)
    locks = sorted(_active_manifest_cell_locks(control))
    return {
        "captured_timestamp": float(snapshot.captured_at),
        "active_cell_task_ids": live_cells,
        "active_controller_job_ids": controllers,
        "active_cell_locks": locks,
        "pending": bool(live_cells or controllers or locks),
    }


def _begin_finalizer_worker_attempt(
    state_dir: Path,
    *,
    intent_id: str,
    attempt: int,
    job_id: str,
    now: float,
) -> str:
    """Count one exact worker identity once, before any scheduler read."""

    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        finalization = control["finalization"]
        if finalization.get("intent_id") != intent_id:
            raise ControllerFenced(
                "finalizer worker attempt lost its durable intent"
            )
        if finalization.get("state") == "blocked":
            return "blocked"
        if finalization.get("state") == "complete":
            return "complete"
        for row in finalization["worker_attempts"]:
            if row["attempt"] == attempt and row["job_id"] == job_id:
                return str(row["status"])
        identities = [
            record
            for record in (
                finalization.get("active_job"),
                finalization.get("successor_job"),
            )
            if isinstance(record, Mapping)
            and record.get("attempt") == attempt
            and record.get("job_id") == job_id
        ]
        if len(identities) != 1:
            raise ControllerFenced(
                "finalizer worker attempt does not match one durable job"
            )
        if int(finalization["attempts"]) >= FINALIZER_MAX_TRANSIENT_ATTEMPTS:
            error = FinalizerRetryLimitError(
                "autonomous finalizer exhausted its bounded retry budget"
            )
            finalization["state"] = "blocked"
            finalization["last_error"] = {
                "kind": type(error).__name__,
                "message": str(error),
                "transient": False,
                "at": utc_timestamp(now),
                "timestamp": now,
            }
            _append_finalization_history(
                finalization,
                event="retry_budget_exhausted",
                details={"attempt": attempt, "job_id": job_id},
                now=now,
            )
            append_transition(
                state_dir,
                control,
                event="autonomous_finalization_blocked",
                details={
                    "attempt": attempt,
                    "job_id": job_id,
                    "error": str(error),
                },
                now=now,
            )
            _save_control(state_dir, control, now=now)
            return "exhausted"
        finalization["worker_attempts"].append(
            {
                "attempt": attempt,
                "job_id": job_id,
                "status": "started",
                "started_at": utc_timestamp(now),
                "started_timestamp": now,
                "finished_at": None,
                "finished_timestamp": None,
            }
        )
        finalization["attempts"] = len(finalization["worker_attempts"])
        _append_finalization_history(
            finalization,
            event="worker_attempt_started",
            details={"attempt": attempt, "job_id": job_id},
            now=now,
        )
        _save_control(state_dir, control, now=now)
        return "started"


def _finish_finalizer_worker_attempt(
    state_dir: Path,
    *,
    attempt: int,
    job_id: str,
    status: str,
    now: float,
) -> None:
    if status not in FINALIZER_WORKER_ATTEMPT_STATES - {"started"}:
        raise FinalizerInvariantError(
            f"invalid finalizer worker terminal status {status!r}"
        )
    with control_lock(state_dir):
        control = load_control(state_dir)
        rows = [
            row
            for row in control["finalization"]["worker_attempts"]
            if row["attempt"] == attempt and row["job_id"] == job_id
        ]
        if len(rows) != 1:
            raise FinalizerInvariantError(
                "finalizer worker attempt record is missing or duplicated"
            )
        row = rows[0]
        if row["status"] == status:
            return
        if row["status"] != "started":
            raise FinalizerInvariantError(
                "finalizer worker attempt already has a different outcome"
            )
        row["status"] = status
        row["finished_at"] = utc_timestamp(now)
        row["finished_timestamp"] = now
        _save_control(state_dir, control, now=now)


def reconcile_autonomous_finalization(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Idempotently ensure one active finalizer and one after-any successor."""

    timestamp = snapshot.captured_at if now is None else float(now)
    if not snapshot.squeue_ok or not snapshot.sacct_ok or snapshot.errors:
        raise SchedulerAmbiguity(
            "finalizer reconciliation requires complete scheduler truth"
        )
    current = load_control(state_dir, verify_files=True)
    finalization = current["finalization"]
    if finalization["state"] == "complete":
        publisher_id = finalization["active_job"]["job_id"]
        active_finalizers = _finalizer_namespace_active_job_ids(snapshot)
        unexpected = sorted(
            set(active_finalizers) - {publisher_id}, key=int
        )
        successor_id = finalization["successor_job"]["job_id"]
        if successor_id in active_finalizers or unexpected:
            raise SchedulerAmbiguity(
                "completed finalization has an active retired or foreign "
                f"finalizer: successor={successor_id in active_finalizers}, "
                f"unexpected={unexpected}"
            )
        if publisher_id in active_finalizers:
            _finalizer_scheduler_observation(
                snapshot,
                _finalizer_job_identity(finalization["active_job"]),
                require_active=True,
                context="completed publisher",
            )
        return _commit_autonomous_finalization_complete(
            state_dir, now=timestamp
        )
    if finalization["state"] == "idle":
        pending_request = _pending_finalization_request_payload(current)
        if pending_request is not None:
            return request_autonomous_finalization(
                state_dir,
                semantic_report_path=Path(
                    str(pending_request["semantic_evidence"]["path"])
                ),
                scheduler=snapshot,
                submit_runner=submit_runner,
                now=timestamp,
            )
        return copy.deepcopy(finalization)
    if finalization["state"] == "blocked":
        return copy.deepcopy(finalization)
    # An accepted sbatch can outlive the process before its numeric job ID reaches
    # control.json.  Adopt only the unique scheduler row bound to the exact durable
    # token and immutable sbatch; do this before any identity requires ``job_id``.
    for field in ("active_job", "successor_job"):
        current = load_control(state_dir, verify_files=True)
        finalization = current["finalization"]
        record = finalization.get(field)
        if not isinstance(record, Mapping) or record.get("job_id") is not None:
            continue
        matches = _finalizer_scheduler_matches(snapshot, record)
        if len(matches) > 1:
            raise SchedulerAmbiguity(
                f"finalizer {field} maps to multiple scheduler jobs"
            )
        if len(matches) == 1:
            _submit_finalizer_job(
                state_dir,
                field=field,
                attempt=int(record["attempt"]),
                dependency_job_id=record.get("dependency_job_id"),
                snapshot=snapshot,
                submit_runner=submit_runner,
                now=timestamp,
            )
    current = load_control(state_dir, verify_files=True)
    finalization = current["finalization"]
    active = finalization.get("active_job")
    successor = finalization.get("successor_job")
    active_matches = (
        _finalizer_scheduler_matches(snapshot, active)
        if isinstance(active, Mapping)
        else []
    )
    successor_matches = (
        _finalizer_scheduler_matches(snapshot, successor)
        if isinstance(successor, Mapping)
        else []
    )
    if len(active_matches) > 1 or len(successor_matches) > 1:
        raise SchedulerAmbiguity("duplicate autonomous finalizer jobs are visible")
    active_live = (
        [job for job in active_matches if job.active]
        if isinstance(active, Mapping)
        else []
    )
    successor_live = (
        [job for job in successor_matches if job.active]
        if isinstance(successor, Mapping)
        else []
    )
    if active_matches:
        _finalizer_record_scheduler_observation(
            snapshot,
            active,
            active_matches[0],
            require_active=bool(active_live),
            context="active",
        )
    if successor_matches:
        _finalizer_record_scheduler_observation(
            snapshot,
            successor,
            successor_matches[0],
            require_active=bool(successor_live),
            context="successor",
        )
    expected_live_ids = {
        str(record["job_id"])
        for record in (active, successor)
        if isinstance(record, Mapping) and record.get("job_id") is not None
    }
    unexpected_live = sorted(
        set(_finalizer_namespace_active_job_ids(snapshot)) - expected_live_ids,
        key=int,
    )
    if unexpected_live:
        raise SchedulerAmbiguity(
            f"unmapped autonomous finalizer jobs are live: {unexpected_live}"
        )
    if isinstance(active, Mapping) and not active_matches:
        _finalizer_record_missing_after_grace(
            finalization,
            field="active_job",
            record=active,
            snapshot=snapshot,
        )
    retirement = finalization.get("successor_retirement")
    if isinstance(retirement, Mapping):
        _, receipt = _verify_successor_retirement_artifacts(
            current, retirement
        )
        marker_path = (
            Path(str(finalization["output_root"])) / FINAL_COMPLETE_FILENAME
        )
        if receipt is not None and marker_path.exists():
            successor_id = str(successor["job_id"])
            if successor_live or successor_id in _finalizer_namespace_active_job_ids(
                snapshot
            ):
                raise SchedulerAmbiguity(
                    "cannot adopt FINAL_COMPLETE while its retired successor is "
                    "active"
                )
            return _commit_autonomous_finalization_complete(
                state_dir, now=timestamp
            )
        if active_live:
            # The publisher still owns the transaction.  Reconciliation must not
            # resurrect a successor after its marker-last retirement begins.
            return copy.deepcopy(finalization)
        if successor_live:
            _promote_finalizer_successor(
                state_dir,
                job_id=successor_live[0].job_id,
                attempt=int(successor["attempt"]),
                now=timestamp,
            )
            active = load_control(state_dir)["finalization"]["active_job"]
            successor = None
            active_live = successor_live
            successor_live = []
        else:
            _reset_finalizer_chain_for_retry(
                state_dir,
                reason=(
                    "retirement_complete_without_marker"
                    if receipt is not None
                    else "retirement_publisher_and_successor_terminal"
                ),
                now=timestamp,
            )
            latest = load_control(state_dir)["finalization"]
            active = latest["active_job"]
            successor = latest["successor_job"]
            active_live = []
            successor_live = []
    if active_live and isinstance(successor, Mapping) and not successor_live:
        terminal_job = successor_matches[0] if successor_matches else None
        terminal_state = (
            normalize_scheduler_state(terminal_job.state)
            if terminal_job is not None
            else None
        )
        if terminal_state is not None and terminal_state not in {
            "CANCELLED",
            "REVOKED",
        }:
            raise SchedulerAmbiguity(
                "after-any successor reached an execution terminal state while "
                f"its publisher remains live: {terminal_state}"
            )
        reason = (
            f"terminal_{terminal_state.lower()}"
            if terminal_state is not None
            else (
                "submission_rejected"
                if _finalizer_submission_rejected(
                    finalization,
                    field="successor_job",
                    record=successor,
                )
                else "missing_after_visibility_grace"
            )
        )
        _retire_unavailable_finalizer_successor(
            state_dir,
            snapshot=snapshot,
            expected_active=active,
            expected_successor=successor,
            scheduler_job=terminal_job,
            reason=reason,
            now=timestamp,
        )
        latest = load_control(state_dir)["finalization"]
        active = latest["active_job"]
        successor = None
        successor_matches = []
        successor_live = []
    if not active_live and successor_live:
        _promote_finalizer_successor(
            state_dir,
            job_id=successor_live[0].job_id,
            attempt=int(successor["attempt"]),
            now=timestamp,
        )
        active = load_control(state_dir)["finalization"]["active_job"]
        successor = None
        active_live = successor_live
        successor_live = []
    if not active_live:
        latest = load_control(state_dir)["finalization"]
        if latest.get("active_job") is not None:
            _reset_finalizer_chain_for_retry(
                state_dir,
                reason="recorded_finalizer_chain_is_terminal",
                now=timestamp,
            )
            latest = load_control(state_dir)["finalization"]
        attempt = int(latest["next_attempt"])
        active = _submit_finalizer_job(
            state_dir,
            field="active_job",
            attempt=attempt,
            dependency_job_id=None,
            snapshot=snapshot,
            submit_runner=submit_runner,
            now=timestamp,
        )
        successor = None
    if not successor_live and successor is None:
        latest = load_control(state_dir)["finalization"]
        active = latest["active_job"]
        attempt = int(latest["next_attempt"])
        _submit_finalizer_job(
            state_dir,
            field="successor_job",
            attempt=attempt,
            dependency_job_id=str(active["job_id"]),
            snapshot=snapshot,
            submit_runner=submit_runner,
            now=timestamp,
        )
    return copy.deepcopy(load_control(state_dir)["finalization"])


def _run_autonomous_finalizer_worker_impl(
    state_dir: Path,
    *,
    intent_id: str,
    attempt: int,
    job_id: str | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    finalize_runner: Callable[..., Mapping[str, Any]] | None = None,
    sleep_runner: Callable[[float], None] | None = None,
    interruption_controller: _FinalizerInterruptionController,
    now: float | None = None,
) -> int:
    """Advance one resumable finalization attempt and preserve its successor."""

    timestamp = time.time() if now is None else float(now)
    slurm_job_id = job_id or os.environ.get("SLURM_JOB_ID", "")
    if not slurm_job_id.isdigit():
        raise ControllerFenced("finalizer worker requires a numeric SLURM_JOB_ID")
    current = load_control(state_dir, verify_files=True)
    if current["finalization"].get("intent_id") != intent_id:
        raise ControllerFenced("finalizer intent ID no longer owns control state")
    read_scheduler = scheduler_reader or (
        lambda: query_scheduler(tolerate_errors=False)
    )
    def sleeper(seconds: float) -> None:
        if sleep_runner is not None:
            sleep_runner(seconds)
            interruption_controller.raise_if_requested()
            return
        deadline = time.monotonic() + max(0.0, float(seconds))
        while True:
            interruption_controller.raise_if_requested()
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return
            time.sleep(min(FINALIZER_CHILD_POLL_SECONDS, remaining))
    if current["finalization"]["state"] == "complete":
        active = current["finalization"].get("active_job")
        if (
            not isinstance(active, Mapping)
            or active.get("job_id") != slurm_job_id
            or active.get("attempt") != attempt
        ):
            raise ControllerFenced(
                "completed finalization only accepts its exact publisher replay"
            )
        reconcile_autonomous_finalization(
            state_dir,
            snapshot=_read_finalizer_scheduler_truth(read_scheduler),
            submit_runner=submit_runner,
            now=timestamp,
        )
        return 0
    try:
        adopted_snapshot = _authenticate_or_adopt_finalizer_worker(
            state_dir,
            intent_id=intent_id,
            attempt=attempt,
            job_id=slurm_job_id,
            scheduler_reader=read_scheduler,
            submit_runner=submit_runner,
            now=timestamp,
        )
    except FinalizerRetryableError:
        # An ID-less worker cannot safely write failure state until complete
        # scheduler truth authenticates it.  Its after-any successor remains the
        # durable retry mechanism.
        return 75
    attempt_recorded = False
    try:
        backoff = _finalizer_drain_backoff_seconds(
            load_control(state_dir)["finalization"], now=timestamp
        )
        if backoff > 0:
            sleeper(backoff)
            if now is None:
                timestamp = time.time()
        attempt_status = _begin_finalizer_worker_attempt(
            state_dir,
            intent_id=intent_id,
            attempt=attempt,
            job_id=slurm_job_id,
            now=timestamp,
        )
        if attempt_status == "complete":
            return 0
        if attempt_status in {"pending", "retryable_failed"}:
            return 75
        if attempt_status in {"blocked", "exhausted"}:
            if attempt_status == "exhausted":
                record_alert(
                    state_dir,
                    kind="finalization-failure",
                    severity="critical",
                    message=(
                        "FinalizerRetryLimitError: autonomous finalizer "
                        "exhausted its bounded retry budget"
                    ),
                    dedupe_key="finalization:blocked",
                    send_email=True,
                    now=timestamp,
                )
            return 2
        attempt_recorded = True
        interruption_controller.raise_if_requested()
        # Obtain complete scheduler truth before promoting a running after-any
        # successor into the active slot.  If this read fails, the durable pair is
        # left unchanged, so the exact recorded successor remains adoptable by the
        # next controller/watchdog reconciliation instead of becoming an unpaired
        # active job.
        snapshot = adopted_snapshot or _read_finalizer_scheduler_truth(
            read_scheduler
        )
        publisher_record = _promote_finalizer_successor(
            state_dir, job_id=slurm_job_id, attempt=attempt, now=timestamp
        )
        reconcile_autonomous_finalization(
            state_dir,
            snapshot=snapshot,
            submit_runner=submit_runner,
            now=timestamp,
        )
        with control_lock(state_dir):
            control = load_control(state_dir)
            finalization = control["finalization"]
            if finalization["state"] == "requested":
                finalization["state"] = "draining"
                _append_finalization_history(
                    finalization,
                    event="draining",
                    details={
                        "active_job_id": publisher_record["job_id"],
                        "successor_job_id": (
                            None
                            if finalization.get("successor_job") is None
                            else finalization["successor_job"].get("job_id")
                        ),
                    },
                    now=timestamp,
                )
                _append_finalizer_transition_once(
                    state_dir,
                    control,
                    event="autonomous_finalization_draining",
                    details={"intent_id": finalization["intent_id"]},
                    now=timestamp,
                )
            finalization["last_error"] = None
            _append_finalization_history(
                finalization,
                event="attempt_execution_started",
                details={"attempt": attempt, "job_id": slurm_job_id},
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
            phase_rank = FINALIZER_PHASE_ORDER.get(
                str(finalization["state"]), 0
            )
            output_root = Path(str(finalization["output_root"])).resolve()
        if phase_rank == 0:
            durable = load_control(state_dir)
            drain_intent = durable.get("drain_intent")
            if (
                not isinstance(drain_intent, Mapping)
                or drain_intent.get("state") != "complete"
            ):
                pause_control(
                    state_dir,
                    drain=True,
                    scheduler=snapshot,
                    cancel_runner=cancel_runner,
                    now=timestamp,
                )
            drain_snapshot = _read_finalizer_scheduler_truth(read_scheduler)
            drain_control = load_control(state_dir, verify_files=True)
            drain = _finalizer_drain_observation(
                state_dir,
                control=drain_control,
                snapshot=drain_snapshot,
                now=timestamp,
            )
            if drain["pending"]:
                retry_not_before = timestamp + FINALIZER_DRAIN_RETRY_SECONDS
                with control_lock(state_dir):
                    control = load_control(state_dir)
                    finalization = control["finalization"]
                    if finalization["state"] not in {"requested", "draining"}:
                        raise FinalizerInvariantError(
                            "finalizer phase advanced during drain observation"
                        )
                    finalization["state"] = "draining"
                    finalization["last_error"] = None
                    _append_finalization_history(
                        finalization,
                        event="drain_pending",
                        details={
                            **drain,
                            "attempt": attempt,
                            "job_id": slurm_job_id,
                            "retry_not_before_timestamp": retry_not_before,
                        },
                        now=timestamp,
                    )
                    _save_control(state_dir, control, now=timestamp)
                _finish_finalizer_worker_attempt(
                    state_dir,
                    attempt=attempt,
                    job_id=slurm_job_id,
                    status="pending",
                    now=timestamp,
                )
                sleeper(FINALIZER_DRAIN_RETRY_SECONDS)
                return 75
            _record_autonomous_finalizer_phase(
                state_dir,
                publisher_finalizer=publisher_record,
                phase="validating",
                bindings={
                    "semantic_report_path": str(
                        (output_root / FINAL_SEMANTIC_FILENAME).resolve()
                    ),
                    "semantic_intent_path": str(
                        (
                            output_root
                            / FINAL_SEMANTIC_INTENT_FILENAME
                        ).resolve()
                    ),
                    "semantic_preflight_path": str(
                        (
                            output_root
                            / FINAL_SEMANTIC_PREFLIGHT_FILENAME
                        ).resolve()
                    ),
                    "semantic_report_sha256": None,
                    "semantic_intent_sha256": None,
                    "semantic_intent_id": None,
                    "semantic_preflight_sha256": None,
                    "semantic_preflight_id": None,
                },
                now=timestamp,
            )
        runner = finalize_runner or finalize_sweep
        wrapped_scheduler_reader = lambda: _read_finalizer_scheduler_truth(
            read_scheduler
        )
        runner_kwargs: dict[str, Any] = {
            "output_root": output_root,
            "scheduler_reader": wrapped_scheduler_reader,
            "cancel_runner": cancel_runner,
            "publisher_finalizer": publisher_record,
            "now": timestamp,
        }
        if finalize_runner is None:
            runner_kwargs["interruption_controller"] = (
                interruption_controller
            )
        result = runner(state_dir, **runner_kwargs)
        interruption_controller.raise_if_requested()
        if result.get("complete") is not True:
            with control_lock(state_dir):
                control = load_control(state_dir)
                finalization = control["finalization"]
                _append_finalization_history(
                    finalization,
                    event="attempt_pending",
                    details={"attempt": attempt, "result": dict(result)},
                    now=timestamp,
                )
                _save_control(state_dir, control, now=timestamp)
            _finish_finalizer_worker_attempt(
                state_dir,
                attempt=attempt,
                job_id=slurm_job_id,
                status="pending",
                now=timestamp,
            )
            return 75
        _commit_autonomous_finalization_complete(state_dir, now=timestamp)
        _finish_finalizer_worker_attempt(
            state_dir,
            attempt=attempt,
            job_id=slurm_job_id,
            status="complete",
            now=timestamp,
        )
        return 0
    except ControllerFenced:
        # A foreign, stale, or concurrently superseded worker never gets to turn
        # its loss of authority into a scientific-integrity state mutation.
        raise
    except Exception as exc:
        observed = load_control(state_dir)["finalization"]
        typed_error, retryable = _typed_finalizer_failure(
            exc,
            finalization=observed,
        )
        retry_exhausted = bool(
            retryable
            and int(observed["attempts"])
            >= FINALIZER_MAX_TRANSIENT_ATTEMPTS
        )
        if retry_exhausted:
            typed_error = FinalizerRetryLimitError(
                "autonomous finalizer exhausted its bounded retry budget "
                f"after {type(exc).__name__}: {exc}"
            )
            retryable = False
        with control_lock(state_dir):
            control = load_control(state_dir)
            finalization = control["finalization"]
            if attempt_recorded:
                rows = [
                    row
                    for row in finalization["worker_attempts"]
                    if row["attempt"] == attempt
                    and row["job_id"] == slurm_job_id
                ]
                if len(rows) != 1:
                    raise FinalizerInvariantError(
                        "finalizer failure lost its worker attempt record"
                    )
                row = rows[0]
                if row["status"] == "started":
                    row["status"] = (
                        "retryable_failed" if retryable else "blocked"
                    )
                    row["finished_at"] = utc_timestamp(timestamp)
                    row["finished_timestamp"] = timestamp
            finalization["last_error"] = {
                "kind": type(typed_error).__name__,
                "message": str(typed_error)[:2000],
                "transient": retryable,
                "at": utc_timestamp(timestamp),
                "timestamp": timestamp,
            }
            if not retryable:
                finalization["state"] = "blocked"
            _append_finalization_history(
                finalization,
                event=(
                    "retry_budget_exhausted"
                    if retry_exhausted
                    else "blocked"
                    if not retryable
                    else "attempt_failed_transient"
                ),
                details={
                    "attempt": attempt,
                    "error_kind": type(typed_error).__name__,
                    "error": str(typed_error)[:2000],
                },
                now=timestamp,
            )
            append_transition(
                state_dir,
                control,
                event=(
                    "autonomous_finalization_blocked"
                    if not retryable
                    else "autonomous_finalization_retryable"
                ),
                details={
                    "attempt": attempt,
                    "error_kind": type(typed_error).__name__,
                    "error": str(typed_error)[:2000],
                },
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
        record_alert(
            state_dir,
            kind="finalization-failure",
            severity="critical",
            message=f"{type(typed_error).__name__}: {typed_error}",
            dedupe_key=(
                "finalization:blocked"
                if not retryable
                else "finalization:execution"
            ),
            send_email=True,
            now=timestamp,
        )
        return 75 if retryable else 2


def run_autonomous_finalizer_worker(
    state_dir: Path,
    *,
    intent_id: str,
    attempt: int,
    job_id: str | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    finalize_runner: Callable[..., Mapping[str, Any]] | None = None,
    sleep_runner: Callable[[float], None] | None = None,
    interruption_controller: _FinalizerInterruptionController | None = None,
    now: float | None = None,
) -> int:
    """Run one signal-owned finalizer worker with no orphanable child."""

    controller = (
        interruption_controller
        if interruption_controller is not None
        else _FinalizerInterruptionController()
    )
    with _finalizer_signal_handlers(controller):
        return _run_autonomous_finalizer_worker_impl(
            state_dir,
            intent_id=intent_id,
            attempt=attempt,
            job_id=job_id,
            scheduler_reader=scheduler_reader,
            submit_runner=submit_runner,
            cancel_runner=cancel_runner,
            finalize_runner=finalize_runner,
            sleep_runner=sleep_runner,
            interruption_controller=controller,
            now=now,
        )


def set_admission_ceiling(
    state_dir: Path, *, ceiling: int, now: float | None = None
) -> dict[str, Any]:
    if ceiling not in ADMISSION_RAMP_STAGES:
        raise ControlError(
            "schema-5 admission ceiling must be one of the closed rollout stages "
            f"{ADMISSION_RAMP_STAGES}"
        )
    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        previous = control["admission"]["current_ceiling"]
        if previous == ceiling:
            return control
        if ceiling > previous:
            raise ControlError(
                "raising admission is monitor-controlled and requires a complete "
                "checksummed clean-window proof"
            )
        _reset_admission_ramp(
            state_dir,
            control,
            reason="manual_ceiling_decrease",
            now=timestamp,
            ceiling=ceiling,
            clear_last_observation=True,
        )
        append_transition(
            state_dir,
            control,
            event="admission_ceiling_changed",
            details={"previous": previous, "current": ceiling},
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        return control


def _active_critical_alerts(control: Mapping[str, Any]) -> list[str]:
    return sorted(
        str(alert.get("dedupe_key"))
        for alert in control.get("alerts", [])
        if isinstance(alert, dict)
        and alert.get("resolved_at") is None
        and alert.get("severity") == "critical"
    )


def _active_critical_alerts_from_journal(state_dir: Path) -> list[str]:
    """Recover critical alert facts durable ahead of ``control.json``.

    Alert raises are fsynced before the control replacement.  A process death in that
    window must be admission-safe even though the in-memory hold never reached
    ``control.json``.  Resolution records close the exact alert ID; email journal rows
    do not affect alert liveness.
    """

    states: dict[str, dict[str, Any]] = {}
    common = {"at", "timestamp", "action", "alert_id"}
    for record in _read_jsonl_locked(
        state_dir / ALERT_JOURNAL, missing_ok=True
    ):
        action = record.get("action")
        if (
            not isinstance(record.get("at"), str)
            or not record["at"]
            or not isinstance(record.get("timestamp"), (int, float))
            or isinstance(record.get("timestamp"), bool)
            or not math.isfinite(float(record["timestamp"]))
            or float(record["timestamp"]) < 0
            or not isinstance(record.get("alert_id"), str)
            or not record["alert_id"]
        ):
            raise ControlError("alert journal contains invalid common fields")
        alert_id = str(record["alert_id"])
        if action == "raised":
            dedupe_key = record.get("dedupe_key")
            severity = record.get("severity")
            if (
                set(record)
                != common
                | {
                    "kind",
                    "severity",
                    "message",
                    "dedupe_key",
                    "occurrences",
                }
                or not isinstance(dedupe_key, str)
                or not dedupe_key
                or not isinstance(record.get("kind"), str)
                or not record["kind"]
                or not isinstance(record.get("message"), str)
                or not record["message"]
                or severity not in {"warning", "critical"}
                or not isinstance(record.get("occurrences"), int)
                or isinstance(record.get("occurrences"), bool)
                or record["occurrences"] < 1
            ):
                raise ControlError("alert journal contains an invalid raise record")
            prior = states.get(alert_id)
            if prior is None:
                states[alert_id] = {
                    "dedupe_key": dedupe_key,
                    "kind": record["kind"],
                    "severity": severity,
                    "occurrences": record["occurrences"],
                    "active": True,
                    "last_attempt": 0,
                }
            elif (
                prior["dedupe_key"] != dedupe_key
                or prior["kind"] != record["kind"]
                or prior["severity"] != severity
                or prior["active"] is not True
                or record["occurrences"] != prior["occurrences"] + 1
            ):
                raise ControlError(
                    "alert journal duplicate raise changes alert identity"
                )
            else:
                prior["occurrences"] = record["occurrences"]
        elif action == "resolved":
            resolution_extras = set(record) - (common | {"dedupe_key"})
            if resolution_extras not in (
                set(),
                {"capacity_transition_id"},
                {"finalization_intent_id"},
            ):
                raise ControlError(
                    "alert journal contains an invalid resolution record"
                )
            prior = states.get(alert_id)
            dedupe_key = record.get("dedupe_key")
            if (
                prior is None
                or not isinstance(dedupe_key, str)
                or dedupe_key != prior["dedupe_key"]
            ):
                raise ControlError(
                    "alert journal resolution does not match a raised alert"
                )
            if (
                "capacity_transition_id" in record
                and (
                    not isinstance(record["capacity_transition_id"], str)
                    or not record["capacity_transition_id"]
                )
            ) or (
                "finalization_intent_id" in record
                and _SHA256_RE.fullmatch(
                    str(record["finalization_intent_id"])
                )
                is None
            ):
                raise ControlError(
                    "alert journal resolution transaction identity is invalid"
                )
            # A retry after journal-ahead/control-behind recovery can allocate a new
            # alert ID for the same dedupe key.  Resolving that durable incident closes
            # every earlier active ID for the key, while later raises remain ordered
            # after this row and become active again.
            for state in states.values():
                if state["dedupe_key"] == dedupe_key:
                    state["active"] = False
        elif action == "email_attempt_started":
            if (
                set(record) != common | {"attempt", "intent_token"}
                or alert_id not in states
                or not isinstance(record.get("attempt"), int)
                or isinstance(record.get("attempt"), bool)
                or record["attempt"] != states[alert_id]["last_attempt"] + 1
                or re.fullmatch(r"[0-9a-f]{32}", str(record.get("intent_token", "")))
                is None
            ):
                raise ControlError(
                    "alert journal contains an invalid email-attempt record"
                )
            states[alert_id]["last_attempt"] = record["attempt"]
        elif action in {"email_delivered", "email_retry_scheduled"}:
            if (
                set(record)
                != common
                | {
                    "attempt",
                    "delivered",
                    "error",
                    "next_retry_timestamp",
                }
                or alert_id not in states
                or record.get("attempt") != states[alert_id]["last_attempt"]
                or not isinstance(record.get("delivered"), bool)
                or (
                    record.get("error") is not None
                    and not isinstance(record.get("error"), str)
                )
            ):
                raise ControlError(
                    "alert journal contains an invalid email-result record"
                )
            retry_at = record.get("next_retry_timestamp")
            if action == "email_delivered":
                if record["delivered"] is not True or retry_at is not None:
                    raise ControlError(
                        "alert journal delivered email result is inconsistent"
                    )
            elif (
                record["delivered"] is not False
                or not isinstance(retry_at, (int, float))
                or isinstance(retry_at, bool)
                or not math.isfinite(float(retry_at))
                or float(retry_at) < float(record["timestamp"])
            ):
                raise ControlError(
                    "alert journal retry email result is inconsistent"
                )
        else:
            raise ControlError(
                f"alert journal contains unknown action {action!r}"
            )
    return sorted(
        {
            state["dedupe_key"]
            for state in states.values()
            if state["active"] is True and state["severity"] == "critical"
        }
    )


def _active_ramp_blocking_alerts(control: Mapping[str, Any]) -> list[str]:
    return sorted(
        str(alert.get("dedupe_key"))
        for alert in control.get("alerts", [])
        if isinstance(alert, dict)
        and alert.get("resolved_at") is None
        and (
            alert.get("severity") == "critical"
            or alert.get("dedupe_key") in ADMISSION_RAMP_BLOCKING_ALERT_KEYS
        )
    )


def _read_admission_ramp_evidence(
    state_dir: Path, evidence_path: Path, expected_sha256: str
) -> tuple[dict[str, Any], dict[str, Any], str]:
    path = evidence_path.expanduser().resolve()
    root = (state_dir.expanduser().resolve() / "monitoring").resolve()
    try:
        path.relative_to(root)
    except ValueError as exc:
        raise ControlError(
            f"admission ramp evidence must be under {root}, found {path}"
        ) from exc
    if evidence_path.is_symlink() or not path.is_file():
        raise ControlError("admission ramp evidence must be a regular non-symlink file")
    if path.stat().st_nlink != 1:
        raise ControlError("admission ramp evidence must not have hardlink aliases")
    if path.stat().st_mode & 0o222:
        raise ControlError("admission ramp evidence must be sealed read-only")
    try:
        payload = path.read_bytes()
        observed_sha256 = hashlib.sha256(payload).hexdigest()
        report = json.loads(payload.decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ControlError(f"cannot read admission ramp evidence {path}: {exc}") from exc
    if _SHA256_RE.fullmatch(expected_sha256) is None:
        raise ControlError("admission ramp evidence SHA-256 is invalid")
    if observed_sha256 != expected_sha256:
        raise ControlError(
            f"admission ramp evidence hash mismatch: expected {expected_sha256}, "
            f"observed {observed_sha256}"
        )
    if not isinstance(report, dict):
        raise ControlError("admission ramp evidence report must be an object")
    observation = report.get("ramp_observation")
    expected_fields = {
        "schema_version",
        "protocol",
        "captured_timestamp",
        "committed_timestamp",
        "cadence",
        "control_immutable_sha256",
        "rollout_generation",
        "admission_ceiling",
        "fleet_generation",
        "production_health_clean",
        "semantic_integrity_clean",
        "critical_finding_keys",
        "promotion_blocking_finding_keys",
        "run_validated_qids",
        "run_useful_qids",
    }
    if not isinstance(observation, dict) or set(observation) != expected_fields:
        raise ControlError("admission ramp observation fields are not exact")
    if (
        observation.get("schema_version") != 1
        or observation.get("protocol") != ADMISSION_RAMP_EVIDENCE_PROTOCOL
        or observation.get("cadence") not in MONITOR_CADENCE_SECONDS
        or observation.get("captured_timestamp") != report.get("captured_timestamp")
        or not isinstance(observation.get("committed_timestamp"), (int, float))
        or isinstance(observation.get("committed_timestamp"), bool)
        or float(observation["committed_timestamp"])
        < float(observation["captured_timestamp"])
        or observation.get("cadence") != report.get("cadence")
    ):
        raise ControlError("admission ramp observation identity is invalid")
    critical_keys = observation.get("critical_finding_keys")
    if (
        not isinstance(critical_keys, list)
        or critical_keys != sorted(set(critical_keys))
        or not all(isinstance(value, str) and value for value in critical_keys)
    ):
        raise ControlError("admission ramp critical-finding evidence is invalid")
    blocking_keys = observation.get("promotion_blocking_finding_keys")
    if (
        not isinstance(blocking_keys, list)
        or blocking_keys != sorted(set(blocking_keys))
        or not all(isinstance(value, str) and value for value in blocking_keys)
        or not set(critical_keys).issubset(blocking_keys)
    ):
        raise ControlError("admission ramp promotion-blocking evidence is invalid")
    health = report.get("health")
    live = health.get("control") if isinstance(health, dict) else None
    if (
        not isinstance(health, dict)
        or not isinstance(live, dict)
        or observation.get("fleet_generation") != health.get("fleet_generation")
        or observation.get("rollout_generation") != live.get("rollout_generation")
        or observation.get("admission_ceiling")
        != live.get("admission", {}).get("current_ceiling")
    ):
        raise ControlError("admission ramp evidence disagrees with live report fields")
    cadence = str(observation["cadence"])
    if cadence == "health":
        if (
            observation.get("semantic_integrity_clean") is not None
            or observation.get("run_validated_qids") is not None
            or observation.get("run_useful_qids") is not None
        ):
            raise ControlError("health ramp evidence must not claim semantic progress")
    else:
        semantic = report.get("semantic")
        runs = semantic.get("runs") if isinstance(semantic, dict) else None
        if not isinstance(runs, dict) or set(runs) != set(REQUIRED_RUNS):
            raise ControlError("semantic ramp evidence does not cover all production runs")
        validated_qids: dict[str, int] = {}
        useful_qids: dict[str, int] = {}
        for run_id in REQUIRED_RUNS:
            outcomes = (
                runs[run_id].get("outcomes")
                if isinstance(runs[run_id], dict)
                else None
            )
            validated = (
                outcomes.get("validated_qids")
                if isinstance(outcomes, dict)
                else None
            )
            useful = (
                outcomes.get("useful_qids")
                if isinstance(outcomes, dict)
                else None
            )
            if (
                not isinstance(validated, int)
                or isinstance(validated, bool)
                or not isinstance(useful, int)
                or isinstance(useful, bool)
            ):
                raise ControlError(
                    f"semantic ramp evidence lacks trusted/useful QIDs for {run_id}"
                )
            validated_qids[run_id] = validated
            useful_qids[run_id] = useful
        if (
            not _valid_run_qid_map(validated_qids)
            or observation.get("run_validated_qids") != validated_qids
        ):
            raise ControlError("semantic ramp per-run validated-QID evidence is invalid")
        if (
            not _valid_run_qid_map(useful_qids)
            or observation.get("run_useful_qids") != useful_qids
            or any(
                useful_qids[run_id] > validated_qids[run_id]
                for run_id in REQUIRED_RUNS
            )
        ):
            raise ControlError("semantic ramp per-run useful-QID evidence is invalid")
        total = semantic.get("outcomes", {}).get("validated_qids")
        if total != sum(validated_qids.values()):
            raise ControlError("semantic ramp aggregate QIDs disagree with its run totals")
        useful_total = semantic.get("outcomes", {}).get("useful_qids")
        if useful_total != sum(useful_qids.values()):
            raise ControlError(
                "semantic ramp aggregate useful QIDs disagree with its run totals"
            )
        if not isinstance(observation.get("semantic_integrity_clean"), bool):
            raise ControlError("semantic ramp integrity evidence must be boolean")
    return report, observation, observed_sha256


def _ramp_observation_record(
    *, path: Path, sha256: str, observation: Mapping[str, Any], clean: bool
) -> dict[str, Any]:
    return {
        "path": str(path.expanduser().resolve()),
        "sha256": sha256,
        "captured_timestamp": float(observation["captured_timestamp"]),
        "timestamp": float(observation["committed_timestamp"]),
        "cadence": str(observation["cadence"]),
        "clean": bool(clean),
        "run_validated_qids": copy.deepcopy(
            observation.get("run_validated_qids")
        ),
        "run_useful_qids": copy.deepcopy(observation.get("run_useful_qids")),
    }


def _read_sealed_capacity_json(
    state_dir: Path,
    path_value: str | Path,
    expected_sha256: str,
    *,
    description: str,
) -> tuple[Path, dict[str, Any], str]:
    path = Path(path_value).expanduser().resolve()
    root = (state_dir.expanduser().resolve() / "capacity-transitions").resolve()
    try:
        path.relative_to(root)
    except ValueError as exc:
        raise ControlError(
            f"{description} must be under {root}, found {path}"
        ) from exc
    if (
        Path(path_value).is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
    ):
        raise ControlError(
            f"{description} must be a sealed, single-link regular file"
        )
    if _SHA256_RE.fullmatch(str(expected_sha256)) is None:
        raise ControlError(f"{description} SHA-256 is invalid")
    try:
        payload = path.read_bytes()
        observed_sha256 = hashlib.sha256(payload).hexdigest()
        value = json.loads(payload.decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ControlError(f"cannot read {description} {path}: {exc}") from exc
    if observed_sha256 != expected_sha256:
        raise ControlError(
            f"{description} hash mismatch: expected {expected_sha256}, "
            f"observed {observed_sha256}"
        )
    if not isinstance(value, dict):
        raise ControlError(f"{description} must be a JSON object")
    return path, value, observed_sha256


def _read_client_capacity_authorization(
    state_dir: Path,
    control: Mapping[str, Any],
    evidence_path: Path,
    expected_sha256: str,
    *,
    attested_timestamp: float,
) -> dict[str, Any]:
    """Verify a sealed higher-stage client-placement capacity generation.

    This is deliberately stronger than a self-asserted ``passed`` marker.  The
    authorization binds three other immutable artifacts: complete scheduler
    placement/headroom truth, a no-requeue client canary, and post-transition
    readiness/reconciliation.  All four files are re-hashed before every promotion.
    """

    path, report, observed_sha256 = _read_sealed_capacity_json(
        state_dir,
        evidence_path,
        expected_sha256,
        description="client-capacity authorization",
    )
    required = {
        "schema_version",
        "protocol",
        "passed",
        "control_immutable_sha256",
        "capacity_generation",
        "capacity_contract_sha256",
        "authorized_cell_ceiling",
        "partition",
        "preempt_mode",
        "nonpreemptible_client_slots",
        "cpu_limit",
        "memory_limit_mib",
        "max_submit_jobs",
        "qos_limit",
        "reserve_jobs",
        "cell_cpus",
        "cell_memory_mib",
        "scheduler_evidence",
        "canary_evidence",
        "accepted_submission_evidence",
        "readiness_evidence",
        "captured_timestamp",
    }
    if set(report) != required:
        raise ControlError("client-capacity authorization fields are not exact")
    generation = report.get("capacity_generation")
    authorized_ceiling = report.get("authorized_cell_ceiling")
    capacity = control.get("capacity")
    contract = (
        capacity.get("current_contract")
        if isinstance(capacity, Mapping)
        else None
    )
    history = capacity.get("history") if isinstance(capacity, Mapping) else None
    active_transition = (
        capacity.get("active_transition")
        if isinstance(capacity, Mapping)
        else None
    )
    completed_generation = bool(
        isinstance(history, list)
        and history
        and history[-1].get("to_generation") == generation
        and history[-1].get("phase") == "completed"
    )
    readiness_pending_generation = bool(
        isinstance(active_transition, Mapping)
        and active_transition.get("phase") == "readiness_pending"
        and active_transition.get("to_generation") == generation
    )
    generation_transition = (
        active_transition
        if readiness_pending_generation
        else history[-1]
        if completed_generation
        else None
    )
    # The authorization is necessarily captured while the transition is in
    # ``readiness_pending`` so it can gate transition completion.  Completion later
    # copies that same fleet-launch boundary into history and adds a newer
    # ``completed_timestamp``.  Comparing against the latter would make immutable
    # evidence retroactively invalid as a consequence of the very completion it
    # authorized.
    generation_ready_timestamp = (
        generation_transition.get("fleet_launch_completed_timestamp")
        if isinstance(generation_transition, Mapping)
        else None
    )
    if (
        report.get("schema_version")
        != CLIENT_CAPACITY_AUTHORIZATION_SCHEMA_VERSION
        or report.get("protocol") != CLIENT_CAPACITY_AUTHORIZATION_PROTOCOL
        or report.get("passed") is not True
        or report.get("control_immutable_sha256")
        != control.get("immutable_sha256")
        or not isinstance(generation, int)
        or isinstance(generation, bool)
        or generation < 2
        or generation != (
            capacity.get("current_generation")
            if isinstance(capacity, Mapping)
            else None
        )
        or not isinstance(contract, Mapping)
        or report.get("capacity_contract_sha256") != contract.get("sha256")
        or authorized_ceiling not in {192, 384}
        or report.get("partition") == PRODUCTION_CONTROLLER_PARTITION
        or not isinstance(report.get("partition"), str)
        or not report["partition"]
        or report.get("preempt_mode") != "OFF"
        or report.get("qos_limit") != DEFAULT_ADMISSION["qos_limit"]
        or report.get("reserve_jobs") != DEFAULT_ADMISSION["reserve"]
        or report.get("cell_cpus") != DEFAULT_ADMISSION["cell_cpus"]
        or report.get("cell_memory_mib") != 4096
        or not isinstance(report.get("nonpreemptible_client_slots"), int)
        or isinstance(report.get("nonpreemptible_client_slots"), bool)
        or report["nonpreemptible_client_slots"] < authorized_ceiling
        or not isinstance(report.get("cpu_limit"), int)
        or isinstance(report.get("cpu_limit"), bool)
        or report["cpu_limit"] < authorized_ceiling
        or not isinstance(report.get("memory_limit_mib"), int)
        or isinstance(report.get("memory_limit_mib"), bool)
        or report["memory_limit_mib"] < authorized_ceiling * 4096
        or not isinstance(report.get("max_submit_jobs"), int)
        or isinstance(report.get("max_submit_jobs"), bool)
        or report["max_submit_jobs"]
        < authorized_ceiling + DEFAULT_ADMISSION["reserve"]
        or not isinstance(report.get("captured_timestamp"), (int, float))
        or isinstance(report.get("captured_timestamp"), bool)
        or not (completed_generation or readiness_pending_generation)
        or not isinstance(generation_ready_timestamp, (int, float))
        or isinstance(generation_ready_timestamp, bool)
        or float(report["captured_timestamp"])
        < float(generation_ready_timestamp)
        or not isinstance(generation_transition, Mapping)
        or not isinstance(generation_transition.get("transition_id"), str)
        or not generation_transition.get("transition_id")
    ):
        raise ControlError(
            "client-capacity authorization is not bound to one completed, current "
            "non-preemptible capacity generation"
        )

    evidence_reports: dict[str, tuple[Path, dict[str, Any], str]] = {}
    for name, field in (
        ("scheduler", "scheduler_evidence"),
        ("canary", "canary_evidence"),
        ("accepted_submission", "accepted_submission_evidence"),
        ("readiness", "readiness_evidence"),
    ):
        reference = report.get(field)
        if (
            not isinstance(reference, dict)
            or set(reference) != {"path", "sha256"}
            or not isinstance(reference.get("path"), str)
            or _SHA256_RE.fullmatch(str(reference.get("sha256", ""))) is None
        ):
            raise ControlError(
                f"client-capacity {name} evidence reference is invalid"
            )
        evidence_reports[name] = _read_sealed_capacity_json(
            state_dir,
            reference["path"],
            reference["sha256"],
            description=f"client-capacity {name} evidence",
        )

    scheduler_report = evidence_reports["scheduler"][1]
    placement = scheduler_report.get("client_placement")
    raw_scheduler_contract = scheduler_report.get(
        "raw_client_capacity_contract"
    )
    expected_placement = {
        "capacity_generation": generation,
        "partition": report["partition"],
        "preempt_mode": "OFF",
        "nonpreemptible_client_slots": report["nonpreemptible_client_slots"],
        "cpu_limit": report["cpu_limit"],
        "memory_limit_mib": report["memory_limit_mib"],
        "max_submit_jobs": report["max_submit_jobs"],
        "qos_limit": report["qos_limit"],
        "reserve_jobs": report["reserve_jobs"],
    }
    if (
        set(scheduler_report)
        != {"passed", "client_placement", "raw_client_capacity_contract"}
        or
        scheduler_report.get("passed") is not True
        or placement != expected_placement
        or not isinstance(raw_scheduler_contract, Mapping)
    ):
        raise ControlError(
            "client-capacity scheduler evidence does not prove exact placement "
            "and resource headroom"
        )
    try:
        raw_scheduler_summary = (
            scheduler_safety.validate_client_capacity_contract(
                raw_scheduler_contract,
                expected_partition=str(report["partition"]),
                expected_cpu_limit=int(report["cpu_limit"]),
                expected_memory_limit_mib=int(report["memory_limit_mib"]),
                expected_max_submit_jobs=int(report["max_submit_jobs"]),
            )
        )
    except scheduler_safety.SchedulerSafetyError as exc:
        raise ControlError(
            "client-capacity scheduler evidence contains an invalid raw "
            f"contract: {exc}"
        ) from exc
    if (
        raw_scheduler_summary["partition"] != report["partition"]
        or raw_scheduler_contract.get("captured_timestamp")
        != report["captured_timestamp"]
    ):
        raise ControlError(
            "client-capacity authorization capture timestamp is not the "
            "referenced apply-time scheduler capture"
        )
    canary_report = evidence_reports["canary"][1]
    accepted_submission_report = evidence_reports["accepted_submission"][1]
    accepted_submission_path = evidence_reports["accepted_submission"][0]
    accepted_submission_intent = _load_sealed_builder_json(
        accepted_submission_path.parent / CLIENT_CAPACITY_SUBMISSION_INTENT,
        description="client-capacity submission intent",
    )
    (
        verified_accepted_path,
        verified_accepted_report,
        verified_accepted_sha256,
    ) = _load_client_capacity_submission_accepted(
        accepted_submission_path.parent,
        submission_intent=accepted_submission_intent,
    )
    if (
        canary_report.get("passed") is not True
        or canary_report.get("capacity_generation") != generation
        or canary_report.get("authorized_cell_ceiling") != authorized_ceiling
        or canary_report.get("partition") != report["partition"]
        or canary_report.get("preempt_mode") != "OFF"
        or canary_report.get("no_requeue") is not True
        or canary_report.get("cell_cpus") != 1
        or canary_report.get("cell_memory_mib") != 4096
        or accepted_submission_report.get("passed") is not True
        or accepted_submission_report.get("protocol")
        != CLIENT_CAPACITY_SUBMISSION_PROTOCOL
        or accepted_submission_report.get("job_id")
        != canary_report.get("job_id")
        or accepted_submission_report.get("capacity_generation")
        != generation
        or accepted_submission_report.get("target_ceiling")
        != authorized_ceiling
        or accepted_submission_report.get("partition") != report["partition"]
        or accepted_submission_report.get("sbatch_path")
        != canary_report.get("sbatch_path")
        or accepted_submission_report.get("sbatch_sha256")
        != canary_report.get("sbatch_sha256")
        or verified_accepted_path != accepted_submission_path
        or verified_accepted_report != accepted_submission_report
        or verified_accepted_sha256
        != evidence_reports["accepted_submission"][2]
    ):
        raise ControlError(
            "client-capacity canary evidence is incomplete or inconsistent"
        )
    readiness_report = evidence_reports["readiness"][1]
    readiness_fields = {
        "passed",
        "capacity_generation",
        "scheduler_reconciliation_passed",
        "fleet_readiness_passed",
        "client_canary_passed",
        "control_immutable_sha256",
        "rollout_generation",
        "transition_id",
        "fleet_evidence",
        "fleet_evidence_sha256",
        "smoke_evidence",
        "smoke_evidence_sha256",
        "scheduler_reconciliation_evidence",
        "scheduler_reconciliation_evidence_sha256",
    }
    if (
        set(readiness_report) != readiness_fields
        or
        readiness_report.get("passed") is not True
        or readiness_report.get("capacity_generation") != generation
        or readiness_report.get("scheduler_reconciliation_passed") is not True
        or readiness_report.get("fleet_readiness_passed") is not True
        or readiness_report.get("client_canary_passed") is not True
        or readiness_report.get("control_immutable_sha256")
        != control.get("immutable_sha256")
        or readiness_report.get("rollout_generation")
        != control.get("rollout_generation")
        or readiness_report.get("transition_id")
        != generation_transition.get("transition_id")
    ):
        raise ControlError(
            "client-capacity readiness evidence is not bound to the current "
            "control, rollout, and capacity transition"
        )
    readiness = control.get("readiness")
    if not isinstance(readiness, Mapping):
        raise ControlError("client-capacity readiness gate state is missing")
    gate_reference_fields = {
        "fleet": ("fleet_evidence", "fleet_evidence_sha256"),
        "smoke_runs": ("smoke_evidence", "smoke_evidence_sha256"),
        "scheduler_reconciliation": (
            "scheduler_reconciliation_evidence",
            "scheduler_reconciliation_evidence_sha256",
        ),
    }
    for gate, (path_field, sha_field) in gate_reference_fields.items():
        gate_record = readiness.get(gate)
        report_gate_path = readiness_report.get(path_field)
        report_gate_sha = readiness_report.get(sha_field)
        if (
            not isinstance(gate_record, Mapping)
            or gate_record.get("passed") is not True
            or gate_record.get("capacity_generation") != generation
            or not isinstance(gate_record.get("evidence"), str)
            or _SHA256_RE.fullmatch(str(gate_record.get("sha256", "")))
            is None
            or not isinstance(report_gate_path, str)
            or _SHA256_RE.fullmatch(str(report_gate_sha or "")) is None
        ):
            raise ControlError(
                f"client-capacity current {gate} readiness record is invalid"
            )
        current_gate_path = Path(
            str(gate_record["evidence"])
        ).expanduser().resolve()
        referenced_gate_path = Path(report_gate_path).expanduser().resolve()
        if (
            referenced_gate_path != current_gate_path
            or report_gate_sha != gate_record["sha256"]
            or current_gate_path.is_symlink()
            or not current_gate_path.is_file()
            or current_gate_path.stat().st_nlink != 1
            or sha256_file(current_gate_path) != report_gate_sha
        ):
            raise ControlError(
                f"client-capacity readiness evidence does not rehash the "
                f"exact current {gate} gate"
            )

    record = {
        "capacity_generation": generation,
        "authorized_cell_ceiling": authorized_ceiling,
        "path": str(path),
        "sha256": observed_sha256,
        "control_immutable_sha256": str(report["control_immutable_sha256"]),
        "capacity_contract_sha256": str(report["capacity_contract_sha256"]),
        "partition": str(report["partition"]),
        "preempt_mode": "OFF",
        "nonpreemptible_client_slots": int(
            report["nonpreemptible_client_slots"]
        ),
        "cpu_limit": int(report["cpu_limit"]),
        "memory_limit_mib": int(report["memory_limit_mib"]),
        "max_submit_jobs": int(report["max_submit_jobs"]),
        "scheduler_evidence_sha256": evidence_reports["scheduler"][2],
        "canary_evidence_sha256": evidence_reports["canary"][2],
        "accepted_submission_evidence_sha256": evidence_reports[
            "accepted_submission"
        ][2],
        "readiness_evidence_sha256": evidence_reports["readiness"][2],
        "captured_timestamp": float(report["captured_timestamp"]),
        "attested_at": utc_timestamp(attested_timestamp),
        "attested_timestamp": float(attested_timestamp),
    }
    _validate_client_capacity_authorization_record(record)
    return record


def _verified_client_capacity_authorization(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    target_ceiling: int,
    attested_timestamp: float,
) -> dict[str, Any] | None:
    if target_ceiling <= PRODUCTION_NONPREEMPTIBLE_CELL_CAP:
        return None
    candidates = [
        record
        for record in control["admission_ramp"]["client_capacity_authorizations"]
        if record["capacity_generation"]
        == control["capacity"]["current_generation"]
        and record["authorized_cell_ceiling"] >= target_ceiling
    ]
    for record in reversed(candidates):
        verified = _read_client_capacity_authorization(
            state_dir,
            control,
            Path(record["path"]),
            str(record["sha256"]),
            attested_timestamp=float(record["attested_timestamp"]),
        )
        if verified != record:
            raise ControlError(
                "stored client-capacity authorization differs from sealed evidence"
            )
        return copy.deepcopy(record)
    return None


def _client_capacity_contract_summary(
    control: Mapping[str, Any],
    *,
    target_ceiling: int,
    state_dir: Path | None = None,
    verify_files: bool,
) -> dict[str, Any]:
    """Return the exact client placement/resource contract for one staged ceiling."""
    if (
        not isinstance(target_ceiling, int)
        or isinstance(target_ceiling, bool)
        or target_ceiling < 1
        or target_ceiling > PRODUCTION_DESIGN_CELL_CAP
    ):
        raise ControlError(
            f"client ceiling {target_ceiling!r} is outside the protected "
            f"1..{PRODUCTION_DESIGN_CELL_CAP} production design"
        )
    immutable = control.get("immutable")
    if not isinstance(immutable, Mapping):
        raise ControlError("protected client capacity lacks immutable pins")
    summary = {
        "partition": str(immutable["protected_client_partition"]),
        "qos": str(immutable["protected_client_qos"]),
        "preempt_mode": "OFF",
        "cpu_limit": int(immutable["protected_client_cpus"]),
        "memory_limit_mib": int(
            immutable["protected_client_memory_mib"]
        ),
        "max_submit_jobs": int(
            immutable["protected_client_submit_headroom"]
        ),
        "reserve_jobs": int(
            immutable["protected_client_reserve_jobs"]
        ),
        "nonpreemptible_client_slots": int(
            immutable["protected_client_slots"]
        ),
        "authorized_cell_ceiling": PRODUCTION_DESIGN_CELL_CAP,
        "capacity_generation": int(
            control["capacity"]["current_generation"]
        ),
        "authorization_sha256": str(
            effective_protected_capacity_binding(
                control, verify_files=verify_files
            )["sha256"]
        ),
    }
    if (
        summary["nonpreemptible_client_slots"] < target_ceiling
        or summary["cpu_limit"] < target_ceiling
        or summary["memory_limit_mib"] < target_ceiling * 4096
        or summary["reserve_jobs"] < int(DEFAULT_ADMISSION["reserve"])
        or summary["max_submit_jobs"]
        < target_ceiling + int(DEFAULT_ADMISSION["reserve"])
    ):
        raise ControlError(
            "immutable protected client capacity cannot sustain the requested "
            "production ceiling"
        )
    if verify_files:
        if state_dir is None:
            raise ControlError(
                "protected client-capacity verification requires the control "
                "state root"
            )
        try:
            capacity_authority = effective_protected_capacity_binding(
                control, verify_files=True
            )
            contract = _load_protected_capacity_contract(
                control,
                path=capacity_authority["path"],
                expected_marker_id=str(capacity_authority["marker_id"]),
                expected_sha256=str(capacity_authority["sha256"]),
            )
            placement = protected_capacity.authorize_client(
                contract,
                partition=summary["partition"],
                qos=summary["qos"],
                required_slots=PRODUCTION_DESIGN_CELL_CAP,
                required_reserve_jobs=int(DEFAULT_ADMISSION["reserve"]),
            )
        except protected_capacity.ProtectedCapacityError as exc:
            raise ControlError(
                f"sealed protected client capacity is invalid: {exc}"
            ) from exc
        expected_capacity = {
            "slots": summary["nonpreemptible_client_slots"],
            "cpus": summary["cpu_limit"],
            "memory_mib": summary["memory_limit_mib"],
            "reserve_jobs": summary["reserve_jobs"],
            "submit_headroom": summary["max_submit_jobs"],
        }
        if dict(placement.capacity) != expected_capacity:
            raise ControlError(
                "sealed protected client capacity differs from immutable pins"
            )
    return summary


def _client_capacity_build_transition(
    control: Mapping[str, Any],
) -> Mapping[str, Any]:
    capacity = control.get("capacity")
    if not isinstance(capacity, Mapping):
        raise ControlError("client-capacity build lacks capacity state")
    generation = capacity.get("current_generation")
    if not isinstance(generation, int) or generation < 2:
        raise ControlError(
            "higher client capacity requires a published capacity generation "
            "after generation one"
        )
    active = capacity.get("active_transition")
    if (
        isinstance(active, Mapping)
        and active.get("phase") == "readiness_pending"
        and active.get("to_generation") == generation
    ):
        return active
    history = capacity.get("history")
    if (
        isinstance(history, list)
        and history
        and isinstance(history[-1], Mapping)
        and history[-1].get("phase") == "completed"
        and history[-1].get("to_generation") == generation
    ):
        return history[-1]
    raise ControlError(
        "client-capacity build requires the current readiness-pending or completed "
        "capacity generation"
    )


def _client_capacity_build_root(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    target_ceiling: int,
) -> tuple[Path, Mapping[str, Any]]:
    transition = _client_capacity_build_transition(control)
    transition_id = transition.get("transition_id")
    if not isinstance(transition_id, str) or not transition_id:
        raise ControlError("capacity generation lacks its transition identity")
    root = (
        state_dir.expanduser().resolve()
        / "capacity-transitions"
        / transition_id
        / f"client-capacity-{target_ceiling}"
    )
    return root, transition


def _load_sealed_builder_json(path: Path, *, description: str) -> dict[str, Any]:
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
    ):
        raise ControlError(
            f"{description} must be a sealed, single-link regular file: {path}"
        )
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ControlError(f"cannot read {description} {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise ControlError(f"{description} must be a JSON object")
    return value


def _write_sealed_builder_json(
    path: Path, payload: Mapping[str, Any], *, description: str
) -> None:
    if path.exists() or path.is_symlink():
        existing = _load_sealed_builder_json(path, description=description)
        if existing != dict(payload):
            raise ControlError(f"{description} conflicts with its durable preimage")
        return
    _atomic_publish_readonly_json(path, payload)


def _client_capacity_canary_sbatch(
    *,
    partition: str,
    target_ceiling: int,
    capacity_generation: int,
    intent_token: str,
    output_path: Path,
) -> str:
    comment = (
        "asys-s5-client-capacity:"
        f"generation={capacity_generation}:target={target_ceiling}:"
        f"intent={intent_token}"
    )
    payload = "\n".join(
        (
            "#!/bin/bash",
            f"#SBATCH --job-name=asys-s5-client-cap-g{capacity_generation}-{target_ceiling}",
            f"#SBATCH --comment={comment}",
            f"#SBATCH --partition={partition}",
            "#SBATCH --cpus-per-task=1",
            "#SBATCH --mem=4G",
            "#SBATCH --time=00:10:00",
            "#SBATCH --no-requeue",
            "#SBATCH --export=NONE",
            f"#SBATCH --output={output_path}",
            "",
            "set -euo pipefail",
            "umask 027",
            _trusted_shell_prelude().rstrip(),
            "/bin/true",
            "",
        )
    )
    _validate_trusted_sbatch_bootstrap(
        payload, description="client-capacity canary sbatch"
    )
    return payload


def _client_capacity_canary_job_name(
    *, capacity_generation: int, target_ceiling: int
) -> str:
    return f"asys-s5-client-cap-g{capacity_generation}-{target_ceiling}"


def _client_capacity_canary_comment(
    *,
    capacity_generation: int,
    target_ceiling: int,
    intent_token: str,
) -> str:
    return (
        "asys-s5-client-capacity:"
        f"generation={capacity_generation}:target={target_ceiling}:"
        f"intent={intent_token}"
    )


def _client_capacity_submission_argv(
    *, sbatch_path: Path, job_comment: str
) -> list[str]:
    return [
        "sbatch",
        "--parsable",
        f"--comment={job_comment}",
        str(sbatch_path.resolve()),
    ]


def _client_capacity_command_matches(
    command: str,
    *,
    sbatch_path: Path,
    submit_argv: Sequence[str],
) -> bool:
    try:
        tokens = shlex.split(command)
    except ValueError:
        return False
    if len(tokens) == 1:
        try:
            return Path(tokens[0]).expanduser().resolve() == sbatch_path.resolve()
        except (OSError, RuntimeError):
            return False
    return (
        len(tokens) == len(submit_argv)
        and Path(tokens[0]).name == "sbatch"
        and tokens[1:] == list(submit_argv)[1:]
    )


def _client_capacity_submission_scheduler_snapshot(
    *,
    scheduler_user: str,
    job_name: str,
    job_comment: str,
    sbatch_path: Path,
    submit_argv: Sequence[str],
    runner: Callable[[Sequence[str]], subprocess.CompletedProcess[str]],
    now: float,
) -> tuple[
    SchedulerSnapshot,
    list[SchedulerJob],
    list[str],
    dict[str, dict[str, Any]],
]:
    """Capture complete, name-scoped squeue+sacct truth for one canary intent."""

    if not scheduler_user or any(
        character in scheduler_user for character in ("\x00", "\n", "\r")
    ):
        raise ControlError("client-capacity scheduler user is unsafe")
    raw: dict[str, dict[str, Any]] = {}

    def scoped_runner(argv: Sequence[str]) -> subprocess.CompletedProcess[str]:
        command = list(argv)
        if command[0] not in {"squeue", "sacct"}:
            raise SchedulerAmbiguity(
                "client-capacity scheduler reconciliation invoked an unexpected "
                f"command: {command!r}"
            )
        command.extend(["--name", job_name])
        try:
            process = runner(command)
        except (OSError, subprocess.TimeoutExpired) as exc:
            raise SchedulerAmbiguity(
                f"client-capacity {command[0]} query failed: {exc}"
            ) from exc
        raw[command[0]] = {
            "argv": command,
            "returncode": int(process.returncode),
            "stdout": process.stdout,
            "stderr": process.stderr,
            "stdout_sha256": hashlib.sha256(
                process.stdout.encode("utf-8")
            ).hexdigest(),
            "stderr_sha256": hashlib.sha256(
                process.stderr.encode("utf-8")
            ).hexdigest(),
        }
        return process

    try:
        snapshot = query_scheduler(
            runner=scoped_runner,
            user=scheduler_user,
            now=now,
            tolerate_errors=False,
        )
    except (ControlError, SchedulerAmbiguity) as exc:
        raise SchedulerAmbiguity(
            f"client-capacity submission requires complete squeue+sacct truth: {exc}"
        ) from exc
    if (
        not snapshot.squeue_ok
        or not snapshot.sacct_ok
        or set(raw) != {"squeue", "sacct"}
    ):
        raise SchedulerAmbiguity(
            "client-capacity submission requires complete squeue+sacct truth"
        )

    source_candidates: dict[str, list[SchedulerJob]] = {}
    for source in ("squeue", "sacct"):
        rows = [
            job
            for job in parse_scheduler_rows(
                raw[source]["stdout"],
                source=source,
                require_placement=True,
            )
            if not (source == "sacct" and "." in job.job_id)
        ]
        near = [
            job
            for job in rows
            if job.job_name == job_name
            or job.comment == job_comment
            or job_comment in job.command
        ]
        for job in near:
            if (
                job.job_name != job_name
                or job.comment != job_comment
                or not job.job_id.isdigit()
                or not _client_capacity_command_matches(
                    job.command,
                    sbatch_path=sbatch_path,
                    submit_argv=submit_argv,
                )
            ):
                raise SchedulerAmbiguity(
                    "client-capacity canary scheduler identity is foreign or "
                    f"drifted: job_id={job.job_id!r} source={source!r}"
                )
        if len({job.job_id for job in near}) > 1:
            raise SchedulerAmbiguity(
                f"client-capacity canary intent maps to multiple {source} jobs"
            )
        source_candidates[source] = near
        raw[source]["candidate_job_ids"] = [job.job_id for job in near]
    candidate_ids = {
        job.job_id
        for rows in source_candidates.values()
        for job in rows
    }
    if len(candidate_ids) > 1:
        raise SchedulerAmbiguity(
            "client-capacity canary intent maps to multiple scheduler jobs: "
            + ", ".join(sorted(candidate_ids))
        )
    candidates = [
        job for job in snapshot.jobs if job.job_id in candidate_ids
    ]
    if len(candidates) != len(candidate_ids):
        raise SchedulerAmbiguity(
            "client-capacity joined scheduler truth lost an exact candidate"
        )
    candidate_sources = [
        source for source, rows in source_candidates.items() if rows
    ]
    return snapshot, candidates, candidate_sources, raw


def _client_capacity_submission_attempts(
    submission_root: Path,
    *,
    submission_intent: Mapping[str, Any],
) -> list[dict[str, Any]]:
    attempts_root = (
        submission_root / CLIENT_CAPACITY_SUBMISSION_ATTEMPTS_DIRECTORY
    )
    if not attempts_root.exists():
        return []
    if attempts_root.is_symlink() or not attempts_root.is_dir():
        raise ControlError(
            "client-capacity submission attempts root is missing or unsafe"
        )
    directories = sorted(attempts_root.iterdir(), key=lambda path: path.name)
    if any(
        path.is_symlink()
        or not path.is_dir()
        or re.fullmatch(r"[0-9]{6}", path.name) is None
        for path in directories
    ):
        raise ControlError(
            "client-capacity submission attempts contain an unsafe entry"
        )
    attempts: list[dict[str, Any]] = []
    for ordinal, directory in enumerate(directories, start=1):
        if directory.name != f"{ordinal:06d}":
            raise ControlError(
                "client-capacity submission attempt ordinals are not contiguous"
            )
        intent_path = directory / "ATTEMPT_INTENT.json"
        if not intent_path.exists() and not intent_path.is_symlink():
            if ordinal == len(directories) and not any(directory.iterdir()):
                # ``mkdir`` and the marker-first atomic intent publication are two
                # filesystem boundaries.  A kill between them leaves a harmless,
                # empty ordinal shell that the next replay completes in place.
                continue
            raise ControlError(
                f"client-capacity submission attempt {ordinal} lacks its intent"
            )
        unexpected = {
            path.name
            for path in directory.iterdir()
        } - {
            "ATTEMPT_INTENT.json",
            "SBATCH_RESULT.json",
            "RETRY_AUTHORIZATION.json",
            "observations",
        }
        observations_path = directory / "observations"
        if unexpected or (
            observations_path.exists()
            and (
                observations_path.is_symlink()
                or not observations_path.is_dir()
            )
        ):
            raise ControlError(
                f"client-capacity submission attempt {ordinal} contains "
                "unexpected or unsafe entries"
            )
        attempt = _load_sealed_builder_json(
            intent_path,
            description=f"client-capacity submission attempt {ordinal} intent",
        )
        expected_fields = {
            "schema_version",
            "protocol",
            "attempt",
            "submission_intent_sha256",
            "control_immutable_sha256",
            "capacity_generation",
            "rollout_generation",
            "transition_id",
            "partition",
            "target_ceiling",
            "intent_token",
            "job_name",
            "job_comment",
            "sbatch_path",
            "sbatch_sha256",
            "submit_argv",
            "retry_authorization",
            "created_at",
            "created_timestamp",
        }
        if (
            set(attempt) != expected_fields
            or attempt.get("schema_version") != 1
            or attempt.get("protocol") != CLIENT_CAPACITY_SUBMISSION_PROTOCOL
            or attempt.get("attempt") != ordinal
            or attempt.get("submission_intent_sha256")
            != sha256_file(
                submission_root / CLIENT_CAPACITY_SUBMISSION_INTENT
            )
            or any(
                attempt.get(field) != submission_intent.get(field)
                for field in (
                    "control_immutable_sha256",
                    "capacity_generation",
                    "rollout_generation",
                    "transition_id",
                    "partition",
                    "target_ceiling",
                    "intent_token",
                    "job_name",
                    "job_comment",
                    "sbatch_path",
                    "sbatch_sha256",
                    "submit_argv",
                )
            )
            or (
                ordinal == 1
                and attempt.get("retry_authorization") is not None
            )
            or (
                ordinal > 1
                and (
                    not isinstance(attempt.get("retry_authorization"), dict)
                    or set(attempt["retry_authorization"])
                    != {"path", "sha256"}
                )
            )
        ):
            raise ControlError(
                f"client-capacity submission attempt {ordinal} intent drifted"
            )
        result_path = directory / "SBATCH_RESULT.json"
        result = (
            _load_sealed_builder_json(
                result_path,
                description=(
                    f"client-capacity submission attempt {ordinal} result"
                ),
            )
            if result_path.exists() or result_path.is_symlink()
            else None
        )
        if result is not None:
            required_result = {
                "schema_version",
                "protocol",
                "attempt",
                "attempt_intent_sha256",
                "returncode",
                "stdout",
                "stderr",
                "stdout_sha256",
                "stderr_sha256",
                "job_id",
                "outcome",
                "completed_at",
                "completed_timestamp",
            }
            if (
                set(result) != required_result
                or result.get("schema_version") != 1
                or result.get("protocol")
                != CLIENT_CAPACITY_SUBMISSION_PROTOCOL
                or result.get("attempt") != ordinal
                or result.get("attempt_intent_sha256")
                != sha256_file(intent_path)
                or not isinstance(result.get("returncode"), int)
                or not isinstance(result.get("stdout"), str)
                or not isinstance(result.get("stderr"), str)
                or hashlib.sha256(
                    result.get("stdout", "").encode("utf-8")
                ).hexdigest()
                != result.get("stdout_sha256")
                or hashlib.sha256(
                    result.get("stderr", "").encode("utf-8")
                ).hexdigest()
                != result.get("stderr_sha256")
                or result.get("outcome")
                not in {"accepted_stdout", "rejected", "ambiguous"}
                or (
                    result.get("outcome") == "accepted_stdout"
                    and result.get("returncode") != 0
                )
                or (
                    result.get("outcome") == "rejected"
                    and result.get("returncode") == 0
                )
                or (
                    result.get("outcome") == "accepted_stdout"
                    and (
                        not isinstance(result.get("job_id"), str)
                        or not result["job_id"].isdigit()
                        or result["stdout"].strip().split(";", 1)[0]
                        != result["job_id"]
                    )
                )
                or (
                    result.get("outcome") != "accepted_stdout"
                    and result.get("job_id") is not None
                )
            ):
                raise ControlError(
                    f"client-capacity submission attempt {ordinal} result drifted"
                )
        attempts.append(
            {
                "ordinal": ordinal,
                "directory": directory,
                "intent_path": intent_path,
                "intent": attempt,
                "result_path": result_path,
                "result": result,
            }
        )
        if ordinal > 1:
            retry_reference = attempt["retry_authorization"]
            retry_path = (
                attempts[-2]["directory"] / "RETRY_AUTHORIZATION.json"
            ).resolve()
            if retry_reference != {
                "path": str(retry_path),
                "sha256": (
                    sha256_file(retry_path)
                    if retry_path.is_file() and not retry_path.is_symlink()
                    else ""
                ),
            }:
                raise ControlError(
                    f"client-capacity submission attempt {ordinal} retry "
                    "authorization reference drifted"
                )
            _load_client_capacity_retry_authorization(
                retry_path,
                previous_attempt=attempts[-2],
                to_attempt=ordinal,
            )
    return attempts


def _record_client_capacity_submission_observation(
    attempt: Mapping[str, Any],
    *,
    raw: Mapping[str, Mapping[str, Any]],
    candidates: Sequence[SchedulerJob],
    candidate_sources: Sequence[str],
    now: float,
) -> dict[str, Any]:
    directory = Path(attempt["directory"])
    observations_root = directory / "observations"
    observations_root.mkdir(parents=True, exist_ok=True)
    existing = sorted(observations_root.iterdir(), key=lambda path: path.name)
    if any(
        path.is_symlink()
        or not path.is_dir()
        or re.fullmatch(r"[0-9]{6}", path.name) is None
        for path in existing
    ):
        raise ControlError(
            "client-capacity submission observations contain an unsafe entry"
        )
    expected_names = [
        f"{index:06d}" for index in range(1, len(existing) + 1)
    ]
    if [path.name for path in existing] != expected_names:
        raise ControlError(
            "client-capacity submission observation ordinals are not contiguous"
        )
    for path in existing:
        unexpected = {
            child.name for child in path.iterdir()
        } - {
            "SQUEUE_OBSERVATION.json",
            "SACCT_OBSERVATION.json",
            "OBSERVATION_COMPLETE.json",
        }
        if unexpected:
            raise ControlError(
                "client-capacity submission observation contains unexpected entries"
            )
    if existing:
        partial_root = existing[-1]
        partial_complete = partial_root / "OBSERVATION_COMPLETE.json"
        if not partial_complete.exists() and not partial_complete.is_symlink():
            partial_sources: dict[str, tuple[Path, dict[str, Any]]] = {}
            for source, filename in (
                ("squeue", "SQUEUE_OBSERVATION.json"),
                ("sacct", "SACCT_OBSERVATION.json"),
            ):
                source_path = partial_root / filename
                if not source_path.exists() and not source_path.is_symlink():
                    continue
                source_payload = _load_sealed_builder_json(
                    source_path,
                    description=(
                        f"partial client-capacity {source} submission observation"
                    ),
                )
                if (
                    source_payload.get("schema_version") != 1
                    or source_payload.get("protocol")
                    != CLIENT_CAPACITY_SUBMISSION_PROTOCOL
                    or source_payload.get("attempt") != attempt["ordinal"]
                    or source_payload.get("observation") != len(existing)
                    or source_payload.get("source") != source
                    or source_payload.get("complete") is not True
                    or source_payload.get("returncode") != 0
                    or not isinstance(
                        source_payload.get("captured_timestamp"), (int, float)
                    )
                    or isinstance(
                        source_payload.get("captured_timestamp"), bool
                    )
                    or not isinstance(
                        source_payload.get("candidate_job_ids"), list
                    )
                    or not isinstance(source_payload.get("stdout"), str)
                    or not isinstance(source_payload.get("stderr"), str)
                    or any(
                        not isinstance(job_id, str) or not job_id.isdigit()
                        for job_id in source_payload.get(
                            "candidate_job_ids", []
                        )
                    )
                    or hashlib.sha256(
                        source_payload.get("stdout", "").encode("utf-8")
                    ).hexdigest()
                    != source_payload.get("stdout_sha256")
                    or hashlib.sha256(
                        source_payload.get("stderr", "").encode("utf-8")
                    ).hexdigest()
                    != source_payload.get("stderr_sha256")
                ):
                    raise ControlError(
                        "partial client-capacity submission observation drifted"
                    )
                partial_sources[source] = (source_path, source_payload)
            partial_candidate_ids = sorted(
                {
                    job_id
                    for _path, payload in partial_sources.values()
                    for job_id in payload["candidate_job_ids"]
                }
            )
            if len(partial_sources) == 2:
                timestamps = {
                    float(payload["captured_timestamp"])
                    for _path, payload in partial_sources.values()
                }
                captured_at = {
                    payload.get("captured_at")
                    for _path, payload in partial_sources.values()
                }
                if (
                    len(timestamps) != 1
                    or len(captured_at) != 1
                    or len(partial_candidate_ids) > 1
                ):
                    raise SchedulerAmbiguity(
                        "partial client-capacity scheduler source observations "
                        "cannot be joined unambiguously"
                    )
                recovered = {
                    "schema_version": 1,
                    "protocol": CLIENT_CAPACITY_SUBMISSION_PROTOCOL,
                    "attempt": int(attempt["ordinal"]),
                    "observation": len(existing),
                    "complete": True,
                    "captured_at": next(iter(captured_at)),
                    "captured_timestamp": next(iter(timestamps)),
                    "candidate_job_ids": partial_candidate_ids,
                    "candidate_sources": sorted(
                        source
                        for source, (_path, payload) in partial_sources.items()
                        if payload["candidate_job_ids"]
                    ),
                    "squeue": {
                        "path": str(partial_sources["squeue"][0].resolve()),
                        "sha256": sha256_file(partial_sources["squeue"][0]),
                    },
                    "sacct": {
                        "path": str(partial_sources["sacct"][0].resolve()),
                        "sha256": sha256_file(partial_sources["sacct"][0]),
                    },
                }
                _write_sealed_builder_json(
                    partial_complete,
                    recovered,
                    description=(
                        "recovered client-capacity submission observation "
                        "completion"
                    ),
                )
                verified = _load_client_capacity_submission_observation(
                    partial_complete,
                    attempt_ordinal=int(attempt["ordinal"]),
                )
                return {
                    "path": str(partial_complete.resolve()),
                    "sha256": sha256_file(partial_complete),
                    "payload": verified,
                }
            if partial_candidate_ids:
                raise SchedulerVisibilityPending(
                    "a partial durable client-capacity observation contains an "
                    "exact candidate; retry is forbidden until reconciled"
                )
    ordinal = len(existing) + 1
    observation_root = observations_root / f"{ordinal:06d}"
    observation_root.mkdir()
    source_references: dict[str, dict[str, str]] = {}
    for source, filename in (
        ("squeue", "SQUEUE_OBSERVATION.json"),
        ("sacct", "SACCT_OBSERVATION.json"),
    ):
        source_payload = {
            "schema_version": 1,
            "protocol": CLIENT_CAPACITY_SUBMISSION_PROTOCOL,
            "attempt": int(attempt["ordinal"]),
            "observation": ordinal,
            "source": source,
            "complete": True,
            "captured_at": utc_timestamp(now),
            "captured_timestamp": float(now),
            **dict(raw[source]),
        }
        source_path = observation_root / filename
        _write_sealed_builder_json(
            source_path,
            source_payload,
            description=f"client-capacity {source} submission observation",
        )
        source_references[source] = {
            "path": str(source_path.resolve()),
            "sha256": sha256_file(source_path),
        }
    complete = {
        "schema_version": 1,
        "protocol": CLIENT_CAPACITY_SUBMISSION_PROTOCOL,
        "attempt": int(attempt["ordinal"]),
        "observation": ordinal,
        "complete": True,
        "captured_at": utc_timestamp(now),
        "captured_timestamp": float(now),
        "candidate_job_ids": [job.job_id for job in candidates],
        "candidate_sources": sorted(set(candidate_sources)),
        "squeue": source_references["squeue"],
        "sacct": source_references["sacct"],
    }
    complete_path = observation_root / "OBSERVATION_COMPLETE.json"
    _write_sealed_builder_json(
        complete_path,
        complete,
        description="client-capacity submission observation completion",
    )
    return {
        "path": str(complete_path.resolve()),
        "sha256": sha256_file(complete_path),
        "payload": complete,
    }


def _load_client_capacity_submission_observation(
    marker: Path,
    *,
    attempt_ordinal: int,
) -> dict[str, Any]:
    payload = _load_sealed_builder_json(
        marker,
        description="client-capacity submission observation completion",
    )
    required = {
        "schema_version",
        "protocol",
        "attempt",
        "observation",
        "complete",
        "captured_at",
        "captured_timestamp",
        "candidate_job_ids",
        "candidate_sources",
        "squeue",
        "sacct",
    }
    if (
        set(payload) != required
        or payload.get("schema_version") != 1
        or payload.get("protocol") != CLIENT_CAPACITY_SUBMISSION_PROTOCOL
        or payload.get("attempt") != attempt_ordinal
        or not isinstance(payload.get("observation"), int)
        or isinstance(payload.get("observation"), bool)
        or payload["observation"] < 1
        or marker.parent.name != f"{payload['observation']:06d}"
        or payload.get("complete") is not True
        or not isinstance(payload.get("captured_at"), str)
        or not isinstance(payload.get("captured_timestamp"), (int, float))
        or isinstance(payload.get("captured_timestamp"), bool)
        or not isinstance(payload.get("candidate_job_ids"), list)
        or any(
            not isinstance(job_id, str) or not job_id.isdigit()
            for job_id in payload.get("candidate_job_ids", [])
        )
        or len(payload.get("candidate_job_ids", []))
        != len(set(payload.get("candidate_job_ids", [])))
        or not isinstance(payload.get("candidate_sources"), list)
        or payload.get("candidate_sources")
        != sorted(set(payload.get("candidate_sources", [])))
        or any(
            source not in {"squeue", "sacct"}
            for source in payload.get("candidate_sources", [])
        )
    ):
        raise ControlError(
            "client-capacity submission observation completion drifted"
        )
    source_job_ids: dict[str, list[str]] = {}
    for source, filename in (
        ("squeue", "SQUEUE_OBSERVATION.json"),
        ("sacct", "SACCT_OBSERVATION.json"),
    ):
        reference = payload.get(source)
        source_path = marker.parent / filename
        if (
            not isinstance(reference, dict)
            or reference
            != {
                "path": str(source_path.resolve()),
                "sha256": (
                    sha256_file(source_path)
                    if source_path.is_file() and not source_path.is_symlink()
                    else ""
                ),
            }
        ):
            raise ControlError(
                f"client-capacity submission {source} observation reference drifted"
            )
        source_payload = _load_sealed_builder_json(
            source_path,
            description=f"client-capacity submission {source} observation",
        )
        source_required = {
            "schema_version",
            "protocol",
            "attempt",
            "observation",
            "source",
            "complete",
            "captured_at",
            "captured_timestamp",
            "argv",
            "returncode",
            "stdout",
            "stderr",
            "stdout_sha256",
            "stderr_sha256",
            "candidate_job_ids",
        }
        if (
            set(source_payload) != source_required
            or source_payload.get("schema_version") != 1
            or source_payload.get("protocol")
            != CLIENT_CAPACITY_SUBMISSION_PROTOCOL
            or source_payload.get("attempt") != attempt_ordinal
            or source_payload.get("observation") != payload["observation"]
            or source_payload.get("source") != source
            or source_payload.get("complete") is not True
            or source_payload.get("captured_timestamp")
            != payload["captured_timestamp"]
            or source_payload.get("captured_at") != payload["captured_at"]
            or source_payload.get("returncode") != 0
            or not isinstance(source_payload.get("argv"), list)
            or not source_payload["argv"]
            or source_payload["argv"][0] != source
            or not isinstance(source_payload.get("stdout"), str)
            or not isinstance(source_payload.get("stderr"), str)
            or hashlib.sha256(
                source_payload.get("stdout", "").encode("utf-8")
            ).hexdigest()
            != source_payload.get("stdout_sha256")
            or hashlib.sha256(
                source_payload.get("stderr", "").encode("utf-8")
            ).hexdigest()
            != source_payload.get("stderr_sha256")
            or not isinstance(source_payload.get("candidate_job_ids"), list)
            or any(
                not isinstance(job_id, str) or not job_id.isdigit()
                for job_id in source_payload.get("candidate_job_ids", [])
            )
        ):
            raise ControlError(
                f"client-capacity submission {source} observation drifted"
            )
        source_job_ids[source] = list(source_payload["candidate_job_ids"])
    observed_ids = sorted(
        {
            job_id
            for job_ids in source_job_ids.values()
            for job_id in job_ids
        }
    )
    observed_sources = sorted(
        source for source, job_ids in source_job_ids.items() if job_ids
    )
    if (
        observed_ids != payload["candidate_job_ids"]
        or observed_sources != payload["candidate_sources"]
    ):
        raise ControlError(
            "client-capacity submission observation source join drifted"
        )
    return payload


def _load_client_capacity_retry_authorization(
    path: Path,
    *,
    previous_attempt: Mapping[str, Any],
    to_attempt: int,
) -> dict[str, Any]:
    authorization = _load_sealed_builder_json(
        path,
        description="client-capacity retry authorization",
    )
    required = {
        "schema_version",
        "protocol",
        "passed",
        "from_attempt",
        "to_attempt",
        "submission_intent_sha256",
        "previous_attempt_intent",
        "previous_result",
        "absence_observations",
        "minimum_absence_seconds",
        "absence_interval_seconds",
        "authorized_at",
        "authorized_timestamp",
    }
    previous_result = previous_attempt.get("result")
    expected_result_reference = (
        {
            "path": str(previous_attempt["result_path"].resolve()),
            "sha256": sha256_file(previous_attempt["result_path"]),
        }
        if previous_result is not None
        else None
    )
    if (
        set(authorization) != required
        or authorization.get("schema_version") != 1
        or authorization.get("protocol")
        != CLIENT_CAPACITY_SUBMISSION_PROTOCOL
        or authorization.get("passed") is not True
        or authorization.get("from_attempt") != previous_attempt["ordinal"]
        or authorization.get("to_attempt") != to_attempt
        or authorization.get("submission_intent_sha256")
        != sha256_file(
            Path(previous_attempt["directory"]).parent.parent
            / CLIENT_CAPACITY_SUBMISSION_INTENT
        )
        or authorization.get("previous_attempt_intent")
        != {
            "path": str(previous_attempt["intent_path"].resolve()),
            "sha256": sha256_file(previous_attempt["intent_path"]),
        }
        or authorization.get("previous_result")
        != expected_result_reference
        or not isinstance(authorization.get("absence_observations"), list)
        or len(authorization["absence_observations"]) != 2
        or authorization.get("minimum_absence_seconds")
        != CLIENT_CAPACITY_SUBMISSION_ABSENCE_SECONDS
        or not isinstance(
            authorization.get("absence_interval_seconds"), (int, float)
        )
        or isinstance(
            authorization.get("absence_interval_seconds"), bool
        )
        or not isinstance(
            authorization.get("authorized_timestamp"), (int, float)
        )
        or isinstance(authorization.get("authorized_timestamp"), bool)
        or not isinstance(authorization.get("authorized_at"), str)
        or (
            isinstance(previous_result, Mapping)
            and previous_result.get("outcome") == "accepted_stdout"
        )
    ):
        raise ControlError("client-capacity retry authorization drifted")

    observations: list[dict[str, Any]] = []
    observation_paths: list[Path] = []
    expected_root = (
        Path(previous_attempt["directory"]).resolve() / "observations"
    )
    if any(
        record["payload"].get("candidate_job_ids")
        for record in _client_capacity_submission_observations(
            previous_attempt
        )
    ):
        raise ControlError(
            "client-capacity retry is forbidden after any exact candidate "
            "observation"
        )
    for reference in authorization["absence_observations"]:
        if (
            not isinstance(reference, dict)
            or set(reference) != {"path", "sha256", "captured_timestamp"}
            or not isinstance(reference.get("path"), str)
            or _SHA256_RE.fullmatch(str(reference.get("sha256", ""))) is None
            or not isinstance(reference.get("captured_timestamp"), (int, float))
            or isinstance(reference.get("captured_timestamp"), bool)
        ):
            raise ControlError(
                "client-capacity retry absence reference drifted"
            )
        observation_path = Path(reference["path"]).expanduser().resolve()
        if (
            not observation_path.is_relative_to(expected_root)
            or observation_path.name != "OBSERVATION_COMPLETE.json"
            or observation_path.is_symlink()
            or not observation_path.is_file()
            or observation_path.stat().st_nlink != 1
            or observation_path.stat().st_mode & 0o222
            or sha256_file(observation_path) != reference["sha256"]
        ):
            raise ControlError(
                "client-capacity retry absence reference drifted"
            )
        observation = _load_client_capacity_submission_observation(
            observation_path,
            attempt_ordinal=int(previous_attempt["ordinal"]),
        )
        if (
            observation.get("candidate_job_ids") != []
            or observation.get("captured_timestamp")
            != reference["captured_timestamp"]
        ):
            raise ControlError(
                "client-capacity retry observation is not a complete absence"
            )
        observation_paths.append(observation_path)
        observations.append(observation)
    if observation_paths[0] == observation_paths[1]:
        raise ControlError(
            "client-capacity retry repeats one absence observation"
        )
    first_timestamp = float(observations[0]["captured_timestamp"])
    second_timestamp = float(observations[1]["captured_timestamp"])
    lower_bound = float(previous_attempt["intent"]["created_timestamp"])
    if previous_result is not None:
        lower_bound = max(
            lower_bound,
            float(previous_result["completed_timestamp"]),
        )
    interval = second_timestamp - first_timestamp
    if (
        first_timestamp < lower_bound
        or second_timestamp
        < lower_bound + CLIENT_CAPACITY_SUBMISSION_ABSENCE_SECONDS
        or interval < CLIENT_CAPACITY_SUBMISSION_ABSENCE_SECONDS
        or float(authorization["absence_interval_seconds"]) != interval
        or float(authorization["authorized_timestamp"]) < second_timestamp
    ):
        raise ControlError(
            "client-capacity retry absence interval is insufficient or drifted"
        )
    return authorization


def _publish_client_capacity_retry_authorization(
    previous_attempt: Mapping[str, Any],
    *,
    to_attempt: int,
    submission_intent_path: Path,
    absence_observations: Sequence[Mapping[str, Any]],
    now: float,
) -> dict[str, str]:
    if len(absence_observations) < 2:
        raise ControlError(
            "client-capacity retry lacks two absence observations"
        )
    selected = list(absence_observations[-2:])
    references = [
        {
            "path": str(Path(record["path"]).resolve()),
            "sha256": str(record["sha256"]),
            "captured_timestamp": float(
                record["payload"]["captured_timestamp"]
            ),
        }
        for record in selected
    ]
    previous_result = previous_attempt.get("result")
    authorization_path = (
        Path(previous_attempt["directory"]) / "RETRY_AUTHORIZATION.json"
    )
    payload = {
        "schema_version": 1,
        "protocol": CLIENT_CAPACITY_SUBMISSION_PROTOCOL,
        "passed": True,
        "from_attempt": int(previous_attempt["ordinal"]),
        "to_attempt": int(to_attempt),
        "submission_intent_sha256": sha256_file(submission_intent_path),
        "previous_attempt_intent": {
            "path": str(previous_attempt["intent_path"].resolve()),
            "sha256": sha256_file(previous_attempt["intent_path"]),
        },
        "previous_result": (
            {
                "path": str(previous_attempt["result_path"].resolve()),
                "sha256": sha256_file(previous_attempt["result_path"]),
            }
            if previous_result is not None
            else None
        ),
        "absence_observations": references,
        "minimum_absence_seconds": CLIENT_CAPACITY_SUBMISSION_ABSENCE_SECONDS,
        "absence_interval_seconds": (
            references[1]["captured_timestamp"]
            - references[0]["captured_timestamp"]
        ),
        "authorized_at": utc_timestamp(now),
        "authorized_timestamp": float(now),
    }
    if authorization_path.exists() or authorization_path.is_symlink():
        _load_client_capacity_retry_authorization(
            authorization_path,
            previous_attempt=previous_attempt,
            to_attempt=to_attempt,
        )
    else:
        _write_sealed_builder_json(
            authorization_path,
            payload,
            description="client-capacity retry authorization",
        )
        _load_client_capacity_retry_authorization(
            authorization_path,
            previous_attempt=previous_attempt,
            to_attempt=to_attempt,
        )
    return {
        "path": str(authorization_path.resolve()),
        "sha256": sha256_file(authorization_path),
    }


def _client_capacity_submission_observations(
    attempt: Mapping[str, Any],
) -> list[dict[str, Any]]:
    observations_root = Path(attempt["directory"]) / "observations"
    if not observations_root.exists():
        return []
    records: list[dict[str, Any]] = []
    for directory in sorted(observations_root.iterdir(), key=lambda path: path.name):
        if directory.is_symlink() or not directory.is_dir():
            raise ControlError(
                "client-capacity submission observation directory is unsafe"
            )
        marker = directory / "OBSERVATION_COMPLETE.json"
        if not marker.exists() and not marker.is_symlink():
            # A source observation may have been fsynced immediately before a
            # process kill.  It is sealed history but not an absence proof because
            # the marker-last join was never published.
            continue
        payload = _load_client_capacity_submission_observation(
            marker,
            attempt_ordinal=int(attempt["ordinal"]),
        )
        records.append(
            {
                "path": str(marker.resolve()),
                "sha256": sha256_file(marker),
                "payload": payload,
            }
        )
    return records


def _client_capacity_absence_observations(
    attempt: Mapping[str, Any],
) -> list[dict[str, Any]]:
    return [
        record
        for record in _client_capacity_submission_observations(attempt)
        if record["payload"].get("candidate_job_ids") == []
    ]


def _load_client_capacity_submission_accepted(
    submission_root: Path,
    *,
    submission_intent: Mapping[str, Any],
) -> tuple[Path, dict[str, Any], str]:
    path = submission_root / CLIENT_CAPACITY_SUBMISSION_ACCEPTED
    accepted = _load_sealed_builder_json(
        path, description="client-capacity accepted submission"
    )
    required = {
        "schema_version",
        "protocol",
        "passed",
        "job_id",
        "job_name",
        "job_comment",
        "scheduler_user",
        "control_immutable_sha256",
        "capacity_generation",
        "rollout_generation",
        "transition_id",
        "partition",
        "target_ceiling",
        "intent_token",
        "sbatch_path",
        "sbatch_sha256",
        "submit_argv",
        "submission_intent",
        "attempt",
        "scheduler_observation",
        "scheduler_sources",
        "accepted_at",
        "accepted_timestamp",
    }
    if (
        set(accepted) != required
        or accepted.get("schema_version") != 1
        or accepted.get("protocol") != CLIENT_CAPACITY_SUBMISSION_PROTOCOL
        or accepted.get("passed") is not True
        or not isinstance(accepted.get("job_id"), str)
        or not accepted["job_id"].isdigit()
        or any(
            accepted.get(field) != submission_intent.get(field)
            for field in (
                "job_name",
                "job_comment",
                "scheduler_user",
                "control_immutable_sha256",
                "capacity_generation",
                "rollout_generation",
                "transition_id",
                "partition",
                "target_ceiling",
                "intent_token",
                "sbatch_path",
                "sbatch_sha256",
                "submit_argv",
            )
        )
        or accepted.get("submission_intent")
        != {
            "path": str(
                (submission_root / CLIENT_CAPACITY_SUBMISSION_INTENT).resolve()
            ),
            "sha256": sha256_file(
                submission_root / CLIENT_CAPACITY_SUBMISSION_INTENT
            ),
        }
        or not isinstance(accepted.get("attempt"), dict)
        or set(accepted["attempt"])
        != {"ordinal", "intent_path", "intent_sha256", "result_path", "result_sha256"}
        or not isinstance(accepted.get("scheduler_observation"), dict)
        or set(accepted["scheduler_observation"]) != {"path", "sha256"}
        or not isinstance(accepted.get("scheduler_sources"), list)
        or not accepted["scheduler_sources"]
        or any(
            source not in {"squeue", "sacct"}
            for source in accepted["scheduler_sources"]
        )
    ):
        raise ControlError("client-capacity accepted submission drifted")
    attempts = _client_capacity_submission_attempts(
        submission_root,
        submission_intent=submission_intent,
    )
    attempt_reference = accepted["attempt"]
    attempt_ordinal = attempt_reference.get("ordinal")
    if (
        not isinstance(attempt_ordinal, int)
        or isinstance(attempt_ordinal, bool)
        or attempt_ordinal < 1
        or attempt_ordinal > len(attempts)
    ):
        raise ControlError("client-capacity accepted attempt reference drifted")
    canonical_attempt = attempts[attempt_ordinal - 1]
    expected_attempt_reference = {
        "ordinal": attempt_ordinal,
        "intent_path": str(canonical_attempt["intent_path"].resolve()),
        "intent_sha256": sha256_file(canonical_attempt["intent_path"]),
        "result_path": (
            str(canonical_attempt["result_path"].resolve())
            if canonical_attempt["result"] is not None
            else None
        ),
        "result_sha256": (
            sha256_file(canonical_attempt["result_path"])
            if canonical_attempt["result"] is not None
            else None
        ),
    }
    if attempt_reference != expected_attempt_reference:
        raise ControlError("client-capacity accepted attempt reference drifted")
    for path_field, sha_field in (
        ("intent_path", "intent_sha256"),
        ("result_path", "result_sha256"),
    ):
        raw_path = attempt_reference.get(path_field)
        raw_sha = attempt_reference.get(sha_field)
        if raw_path is None and raw_sha is None and path_field == "result_path":
            continue
        if not isinstance(raw_path, str) or _SHA256_RE.fullmatch(
            str(raw_sha or "")
        ) is None:
            raise ControlError("client-capacity accepted attempt reference drifted")
        reference_path = Path(raw_path).expanduser().resolve()
        if (
            reference_path.is_symlink()
            or not reference_path.is_file()
            or reference_path.stat().st_nlink != 1
            or reference_path.stat().st_mode & 0o222
            or sha256_file(reference_path) != raw_sha
        ):
            raise ControlError("client-capacity accepted attempt reference drifted")
    observation_reference = accepted["scheduler_observation"]
    observation_path = Path(
        observation_reference["path"]
    ).expanduser().resolve()
    expected_observations_root = (
        Path(canonical_attempt["directory"]).resolve() / "observations"
    )
    if (
        not observation_path.is_relative_to(expected_observations_root)
        or observation_path.name != "OBSERVATION_COMPLETE.json"
        or observation_path.is_symlink()
        or not observation_path.is_file()
        or observation_path.stat().st_nlink != 1
        or observation_path.stat().st_mode & 0o222
        or sha256_file(observation_path) != observation_reference["sha256"]
    ):
        raise ControlError(
            "client-capacity accepted scheduler_observation drifted"
        )
    observation = _load_client_capacity_submission_observation(
        observation_path,
        attempt_ordinal=attempt_ordinal,
    )
    if (
        observation.get("candidate_job_ids") != [accepted["job_id"]]
        or observation.get("candidate_sources")
        != accepted["scheduler_sources"]
    ):
        raise ControlError(
            "client-capacity accepted scheduler observation drifted"
        )
    return path, accepted, sha256_file(path)


def _publish_client_capacity_submission_accepted(
    *,
    submission_root: Path,
    submission_intent_path: Path,
    submission_intent: Mapping[str, Any],
    attempt: Mapping[str, Any],
    observation: Mapping[str, Any],
    job_id: str,
    now: float,
) -> dict[str, Any]:
    result = attempt["result"]
    if (
        not job_id.isdigit()
        or observation["payload"].get("candidate_job_ids") != [job_id]
        or not observation["payload"].get("candidate_sources")
        or (
            isinstance(result, Mapping)
            and result.get("outcome") == "accepted_stdout"
            and result.get("job_id") != job_id
        )
    ):
        raise SchedulerAmbiguity(
            "client-capacity accepted candidate conflicts with its durable "
            "attempt or scheduler observation"
        )
    attempt_reference = {
        "ordinal": attempt["ordinal"],
        "intent_path": str(attempt["intent_path"].resolve()),
        "intent_sha256": sha256_file(attempt["intent_path"]),
        "result_path": (
            str(attempt["result_path"].resolve())
            if result is not None
            else None
        ),
        "result_sha256": (
            sha256_file(attempt["result_path"])
            if result is not None
            else None
        ),
    }
    accepted_path = submission_root / CLIENT_CAPACITY_SUBMISSION_ACCEPTED
    accepted = {
        "schema_version": 1,
        "protocol": CLIENT_CAPACITY_SUBMISSION_PROTOCOL,
        "passed": True,
        "job_id": job_id,
        "job_name": submission_intent["job_name"],
        "job_comment": submission_intent["job_comment"],
        "scheduler_user": submission_intent["scheduler_user"],
        "control_immutable_sha256": submission_intent[
            "control_immutable_sha256"
        ],
        "capacity_generation": submission_intent["capacity_generation"],
        "rollout_generation": submission_intent["rollout_generation"],
        "transition_id": submission_intent["transition_id"],
        "partition": submission_intent["partition"],
        "target_ceiling": submission_intent["target_ceiling"],
        "intent_token": submission_intent["intent_token"],
        "sbatch_path": submission_intent["sbatch_path"],
        "sbatch_sha256": submission_intent["sbatch_sha256"],
        "submit_argv": submission_intent["submit_argv"],
        "submission_intent": {
            "path": str(submission_intent_path.resolve()),
            "sha256": sha256_file(submission_intent_path),
        },
        "attempt": attempt_reference,
        "scheduler_observation": {
            "path": observation["path"],
            "sha256": observation["sha256"],
        },
        "scheduler_sources": list(
            observation["payload"]["candidate_sources"]
        ),
        "accepted_at": utc_timestamp(now),
        "accepted_timestamp": float(now),
    }
    _write_sealed_builder_json(
        accepted_path,
        accepted,
        description="client-capacity accepted submission",
    )
    _load_client_capacity_submission_accepted(
        submission_root,
        submission_intent=submission_intent,
    )
    return {
        "action": "submit",
        "state": "adopted",
        "job_id": job_id,
        "accepted_submission": str(accepted_path.resolve()),
        "accepted_submission_sha256": sha256_file(accepted_path),
    }


def _submit_client_capacity_canary(
    *,
    root: Path,
    control: Mapping[str, Any],
    transition: Mapping[str, Any],
    partition: str,
    target_ceiling: int,
    intent_token: str,
    sbatch_path: Path,
    sbatch_sha256: str,
    scheduler_user: str,
    scheduler_runner: Callable[
        [Sequence[str]], subprocess.CompletedProcess[str]
    ],
    submit_runner: Callable[
        [Sequence[str]], subprocess.CompletedProcess[str]
    ],
    now: float,
) -> dict[str, Any]:
    """Submit or adopt one exact canary after a marker-first scheduler transaction."""

    submission_root = root / CLIENT_CAPACITY_SUBMISSION_DIRECTORY
    submission_root.mkdir(parents=True, exist_ok=True)
    with _file_lock(submission_root / ".lock"):
        unexpected_submission_entries = {
            path.name for path in submission_root.iterdir()
        } - {
            ".lock",
            CLIENT_CAPACITY_SUBMISSION_INTENT,
            CLIENT_CAPACITY_SUBMISSION_ATTEMPTS_DIRECTORY,
            CLIENT_CAPACITY_SUBMISSION_ACCEPTED,
        }
        if unexpected_submission_entries:
            raise ControlError(
                "client-capacity submission root contains unexpected entries"
            )
        job_name = _client_capacity_canary_job_name(
            capacity_generation=int(control["capacity"]["current_generation"]),
            target_ceiling=target_ceiling,
        )
        job_comment = _client_capacity_canary_comment(
            capacity_generation=int(control["capacity"]["current_generation"]),
            target_ceiling=target_ceiling,
            intent_token=intent_token,
        )
        submit_argv = _client_capacity_submission_argv(
            sbatch_path=sbatch_path,
            job_comment=job_comment,
        )
        submission_intent_path = (
            submission_root / CLIENT_CAPACITY_SUBMISSION_INTENT
        )
        proposed_intent = {
            "schema_version": 1,
            "protocol": CLIENT_CAPACITY_SUBMISSION_PROTOCOL,
            "scheduler_user": scheduler_user,
            "control_immutable_sha256": control["immutable_sha256"],
            "capacity_generation": int(
                control["capacity"]["current_generation"]
            ),
            "rollout_generation": control["rollout_generation"],
            "transition_id": transition["transition_id"],
            "partition": partition,
            "target_ceiling": target_ceiling,
            "intent_token": intent_token,
            "job_name": job_name,
            "job_comment": job_comment,
            "sbatch_path": str(sbatch_path.resolve()),
            "sbatch_sha256": sbatch_sha256,
            "submit_argv": submit_argv,
            "created_at": utc_timestamp(now),
            "created_timestamp": float(now),
        }
        if submission_intent_path.exists() or submission_intent_path.is_symlink():
            submission_intent = _load_sealed_builder_json(
                submission_intent_path,
                description="client-capacity submission intent",
            )
            stable = set(proposed_intent) - {"created_at", "created_timestamp"}
            if (
                set(submission_intent) != set(proposed_intent)
                or any(
                    submission_intent.get(field) != proposed_intent[field]
                    for field in stable
                )
            ):
                raise ControlError("client-capacity submission intent drifted")
        else:
            _write_sealed_builder_json(
                submission_intent_path,
                proposed_intent,
                description="client-capacity submission intent",
            )
            submission_intent = proposed_intent

        accepted_path = submission_root / CLIENT_CAPACITY_SUBMISSION_ACCEPTED
        if accepted_path.exists() or accepted_path.is_symlink():
            path, accepted, accepted_sha = (
                _load_client_capacity_submission_accepted(
                    submission_root,
                    submission_intent=submission_intent,
                )
            )
            return {
                "action": "submit",
                "state": "already_submitted",
                "job_id": accepted["job_id"],
                "accepted_submission": str(path.resolve()),
                "accepted_submission_sha256": accepted_sha,
            }

        attempts = _client_capacity_submission_attempts(
            submission_root,
            submission_intent=submission_intent,
        )
        _snapshot, candidates, candidate_sources, raw = (
            _client_capacity_submission_scheduler_snapshot(
                scheduler_user=scheduler_user,
                job_name=job_name,
                job_comment=job_comment,
                sbatch_path=sbatch_path,
                submit_argv=submit_argv,
                runner=scheduler_runner,
                now=now,
            )
        )
        if candidates and not attempts:
            raise SchedulerAmbiguity(
                "client-capacity canary appeared without a marker-first attempt"
            )

        observation: dict[str, Any] | None = None
        if attempts:
            observation = _record_client_capacity_submission_observation(
                attempts[-1],
                raw=raw,
                candidates=candidates,
                candidate_sources=candidate_sources,
                now=now,
            )
        if candidates:
            assert observation is not None
            return _publish_client_capacity_submission_accepted(
                submission_root=submission_root,
                submission_intent_path=submission_intent_path,
                submission_intent=submission_intent,
                attempt=attempts[-1],
                observation=observation,
                job_id=candidates[0].job_id,
                now=now,
            )

        previous = attempts[-1] if attempts else None
        if previous is not None:
            historical_candidates = [
                record
                for record in _client_capacity_submission_observations(
                    previous
                )
                if record["payload"].get("candidate_job_ids")
            ]
            historical_job_ids = {
                job_id
                for record in historical_candidates
                for job_id in record["payload"]["candidate_job_ids"]
            }
            if len(historical_job_ids) > 1:
                raise SchedulerAmbiguity(
                    "client-capacity attempt history contains multiple exact "
                    "candidate job IDs"
                )
            if historical_candidates:
                historical_job_id = next(iter(historical_job_ids))
                matching = [
                    record
                    for record in historical_candidates
                    if record["payload"]["candidate_job_ids"]
                    == [historical_job_id]
                ]
                return _publish_client_capacity_submission_accepted(
                    submission_root=submission_root,
                    submission_intent_path=submission_intent_path,
                    submission_intent=submission_intent,
                    attempt=previous,
                    observation=matching[0],
                    job_id=historical_job_id,
                    now=now,
                )
            result = previous["result"]
            accepted_stdout = (
                isinstance(result, Mapping)
                and result.get("outcome") == "accepted_stdout"
            )
            ambiguous = result is None or (
                isinstance(result, Mapping)
                and result.get("outcome") == "ambiguous"
            )
            if accepted_stdout:
                return {
                    "action": "submit",
                    "state": "submission_pending",
                    "job_id": result["job_id"],
                    "reason": "accepted sbatch job is not yet visible",
                }
            if ambiguous or (
                isinstance(result, Mapping)
                and result.get("outcome") == "rejected"
            ):
                absences = _client_capacity_absence_observations(previous)
                enough_absence = (
                    len(absences) >= 2
                    and float(
                        absences[-1]["payload"]["captured_timestamp"]
                    )
                    - float(
                        absences[-2]["payload"]["captured_timestamp"]
                    )
                    >= CLIENT_CAPACITY_SUBMISSION_ABSENCE_SECONDS
                    and float(
                        absences[-1]["payload"]["captured_timestamp"]
                    )
                    >= float(previous["intent"]["created_timestamp"])
                    + CLIENT_CAPACITY_SUBMISSION_ABSENCE_SECONDS
                )
                if not enough_absence:
                    return {
                        "action": "submit",
                        "state": "submission_pending",
                        "job_id": None,
                        "reason": (
                            "ambiguous or rejected sbatch attempt requires two "
                            "complete absence observations at least 60 seconds apart"
                        ),
                    }

        retry_authorization = (
            _publish_client_capacity_retry_authorization(
                previous,
                to_attempt=len(attempts) + 1,
                submission_intent_path=submission_intent_path,
                absence_observations=absences,
                now=now,
            )
            if previous is not None
            else None
        )
        attempts_root = (
            submission_root / CLIENT_CAPACITY_SUBMISSION_ATTEMPTS_DIRECTORY
        )
        attempts_root.mkdir(parents=True, exist_ok=True)
        ordinal = len(attempts) + 1
        attempt_root = attempts_root / f"{ordinal:06d}"
        if attempt_root.exists():
            if (
                attempt_root.is_symlink()
                or not attempt_root.is_dir()
                or any(attempt_root.iterdir())
            ):
                raise ControlError(
                    "client-capacity empty attempt-shell recovery is unsafe"
                )
        else:
            attempt_root.mkdir()
        attempt_intent_path = attempt_root / "ATTEMPT_INTENT.json"
        attempt_intent = {
            "schema_version": 1,
            "protocol": CLIENT_CAPACITY_SUBMISSION_PROTOCOL,
            "attempt": ordinal,
            "submission_intent_sha256": sha256_file(submission_intent_path),
            "control_immutable_sha256": submission_intent[
                "control_immutable_sha256"
            ],
            "capacity_generation": submission_intent["capacity_generation"],
            "rollout_generation": submission_intent["rollout_generation"],
            "transition_id": submission_intent["transition_id"],
            "partition": submission_intent["partition"],
            "target_ceiling": submission_intent["target_ceiling"],
            "intent_token": submission_intent["intent_token"],
            "job_name": submission_intent["job_name"],
            "job_comment": submission_intent["job_comment"],
            "sbatch_path": submission_intent["sbatch_path"],
            "sbatch_sha256": submission_intent["sbatch_sha256"],
            "submit_argv": submission_intent["submit_argv"],
            "retry_authorization": retry_authorization,
            "created_at": utc_timestamp(now),
            "created_timestamp": float(now),
        }
        _write_sealed_builder_json(
            attempt_intent_path,
            attempt_intent,
            description=f"client-capacity submission attempt {ordinal} intent",
        )
        try:
            process = submit_runner(submit_argv)
            returncode = int(process.returncode)
            stdout = process.stdout
            stderr = process.stderr
            raw_job_id = stdout.strip().split(";", 1)[0]
            if returncode == 0 and raw_job_id.isdigit():
                outcome = "accepted_stdout"
                job_id: str | None = raw_job_id
            elif returncode != 0:
                outcome = "rejected"
                job_id = None
            else:
                outcome = "ambiguous"
                job_id = None
        except (OSError, subprocess.TimeoutExpired) as exc:
            returncode = -1
            stdout = ""
            stderr = f"{type(exc).__name__}: {exc}"
            outcome = "ambiguous"
            job_id = None
        result_path = attempt_root / "SBATCH_RESULT.json"
        result = {
            "schema_version": 1,
            "protocol": CLIENT_CAPACITY_SUBMISSION_PROTOCOL,
            "attempt": ordinal,
            "attempt_intent_sha256": sha256_file(attempt_intent_path),
            "returncode": returncode,
            "stdout": stdout,
            "stderr": stderr,
            "stdout_sha256": hashlib.sha256(stdout.encode("utf-8")).hexdigest(),
            "stderr_sha256": hashlib.sha256(stderr.encode("utf-8")).hexdigest(),
            "job_id": job_id,
            "outcome": outcome,
            "completed_at": utc_timestamp(now),
            "completed_timestamp": float(now),
        }
        _write_sealed_builder_json(
            result_path,
            result,
            description=f"client-capacity submission attempt {ordinal} result",
        )
        if outcome == "rejected":
            return {
                "action": "submit",
                "state": "submission_pending",
                "job_id": None,
                "reason": "sbatch rejected; retry requires two clean absence observations",
                "returncode": returncode,
            }
        return {
            "action": "submit",
            "state": "submission_pending",
            "job_id": job_id,
            "reason": "sbatch crossed; replay will adopt through scheduler truth",
        }


def _capture_client_capacity_canary(
    *,
    job_id: str,
    partition: str,
    target_ceiling: int,
    capacity_generation: int,
    sbatch_path: Path,
    sbatch_sha256: str,
    expected_job_comment: str,
    expected_submit_argv: Sequence[str],
    runner: Callable[
        [Sequence[str]], subprocess.CompletedProcess[str]
    ],
) -> dict[str, Any]:
    if not job_id.isdigit():
        raise ControlError("client-capacity canary job ID must be numeric")
    argv = [
        "sacct",
        "-X",
        "-nP",
        "-j",
        job_id,
        "--format=JobIDRaw,State,Partition,ReqCPUS,ReqMem,ExitCode,SubmitLine",
    ]
    process = runner(argv)
    if process.returncode != 0:
        raise ControlError(
            "client-capacity canary sacct query failed: "
            + process.stderr.strip()[:500]
        )
    rows = [row for row in process.stdout.splitlines() if row.strip()]
    if len(rows) != 1:
        raise ControlError(
            "client-capacity canary must have exactly one sacct allocation row"
        )
    fields = rows[0].split("|", 6)
    if len(fields) != 7:
        raise ControlError("client-capacity canary sacct fields are malformed")
    observed_job, state, observed_partition, cpus, memory, exit_code, submit_line = (
        field.strip() for field in fields
    )
    try:
        submit_tokens = shlex.split(submit_line)
    except ValueError as exc:
        raise ControlError("client-capacity canary SubmitLine is malformed") from exc
    submitted_paths = [
        Path(token).expanduser().resolve()
        for token in submit_tokens[1:]
        if not token.startswith("-")
    ]
    sbatch_payload = sbatch_path.read_text(encoding="utf-8")
    if (
        observed_job != job_id
        or state.split("+", 1)[0] != "COMPLETED"
        or observed_partition != partition
        or cpus != "1"
        or scheduler_safety._parse_memory_mib(  # noqa: SLF001
            memory, field="client-capacity canary ReqMem"
        )
        != 4096
        or exit_code != "0:0"
        or not submit_tokens
        or Path(submit_tokens[0]).name != "sbatch"
        or _submit_line_comment(submit_line, source="sacct")
        != expected_job_comment
        or submit_tokens[1:] != list(expected_submit_argv)[1:]
        or submitted_paths != [sbatch_path.resolve()]
        or sha256_file(sbatch_path) != sbatch_sha256
        or "#SBATCH --no-requeue" not in sbatch_payload.splitlines()
        or "#SBATCH --export=NONE" not in sbatch_payload.splitlines()
    ):
        raise ControlError(
            "client-capacity canary does not prove the exact completed "
            "1-CPU/4-GiB/no-requeue placement"
        )
    _validate_trusted_sbatch_bootstrap(
        sbatch_payload, description="completed client-capacity canary sbatch"
    )
    return {
        "passed": True,
        "capacity_generation": capacity_generation,
        "authorized_cell_ceiling": target_ceiling,
        "partition": partition,
        "preempt_mode": "OFF",
        "no_requeue": True,
        "cell_cpus": 1,
        "cell_memory_mib": 4096,
        "job_id": job_id,
        "sbatch_path": str(sbatch_path.resolve()),
        "sbatch_sha256": sbatch_sha256,
        "sacct_argv": argv,
        "sacct_raw_output": process.stdout,
        "sacct_raw_output_sha256": hashlib.sha256(
            process.stdout.encode("utf-8")
        ).hexdigest(),
        "submit_line": submit_line,
    }


def build_client_capacity_generation(
    state_dir: Path,
    *,
    action: str,
    partition: str,
    target_ceiling: int,
    scheduler_runner: Callable[..., subprocess.CompletedProcess[str]]
    | None = None,
    submission_scheduler_runner: Callable[
        [Sequence[str]], subprocess.CompletedProcess[str]
    ]
    | None = None,
    submit_runner: Callable[
        [Sequence[str]], subprocess.CompletedProcess[str]
    ]
    | None = None,
    scheduler_user: str | None = None,
    command_runner: Callable[
        [Sequence[str]], subprocess.CompletedProcess[str]
    ]
    | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Build marker-last client capacity through one recoverable canary submission."""

    if action not in {"dry-run", "prepare", "submit", "apply"}:
        raise ControlError(
            "build-client-capacity action must be dry-run, prepare, submit, or apply"
        )
    if target_ceiling not in {192, 384}:
        raise ControlError("client-capacity target must be 192 or 384")
    if re.fullmatch(r"[A-Za-z0-9_.-]+", partition or "") is None:
        raise ControlError("client-capacity partition identity is unsafe")
    timestamp = time.time() if now is None else float(now)
    command = command_runner or _run_subprocess
    with capacity_transition_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        root, transition = _client_capacity_build_root(
            state_dir, control, target_ceiling=target_ceiling
        )
        generation = int(control["capacity"]["current_generation"])
        if (
            control.get("desired_state") != "paused"
            or control.get("drain_requested") is not True
        ):
            raise ControlError(
                "client-capacity evidence must be built while production is paused "
                "and drained"
            )
        live_capacity = (
            scheduler_safety.capture_observed_client_capacity_contract(
                partition=partition,
                runner=scheduler_runner,
                captured_timestamp=timestamp,
            )
        )
        live_summary = scheduler_safety.validate_client_capacity_contract(
            live_capacity,
            expected_partition=partition,
            expected_cpu_limit=int(live_capacity["qos"]["cpu_limit"]),
            expected_memory_limit_mib=int(
                live_capacity["qos"]["memory_limit_mib"]
            ),
            expected_max_submit_jobs=int(
                live_capacity["qos"]["max_submit_jobs"]
            ),
        )
        slots = min(
            int(live_summary["cpu_limit"]),
            int(live_summary["memory_limit_mib"]) // 4096,
            int(live_summary["max_submit_jobs"])
            - int(DEFAULT_ADMISSION["reserve"]),
        )
        if slots < target_ceiling:
            raise ControlError(
                f"candidate client placement proves only {slots} slots, below "
                f"target {target_ceiling}"
            )
        marker_path = root / CLIENT_CAPACITY_COMPLETE
        if marker_path.exists():
            marker_sha = sha256_file(marker_path)
            record = _read_client_capacity_authorization(
                state_dir,
                control,
                marker_path,
                marker_sha,
                attested_timestamp=timestamp,
            )
            return {
                "action": action,
                "state": "already_complete",
                "authorization": str(marker_path.resolve()),
                "sha256": marker_sha,
                "record": record,
            }
        scheduler_preflight_path = (
            root / CLIENT_CAPACITY_SCHEDULER_PREFLIGHT_EVIDENCE
        )
        if action in {"submit", "apply"} and not scheduler_preflight_path.is_file():
            raise ControlError(
                f"build-client-capacity {action} requires a completed prepare "
                "scheduler preflight"
            )

        intent_token = hashlib.sha256(
            canonical_json(
                {
                    "protocol": CLIENT_CAPACITY_BUILD_PROTOCOL,
                    "immutable_sha256": control["immutable_sha256"],
                    "capacity_generation": generation,
                    "rollout_generation": control["rollout_generation"],
                    "transition_id": transition["transition_id"],
                    "partition": partition,
                    "target_ceiling": target_ceiling,
                }
            )
        ).hexdigest()[:32]
        sbatch_path = root / CLIENT_CAPACITY_CANARY_SBATCH
        canary_output = root / "client_capacity_canary_%j.out"
        sbatch_payload = _client_capacity_canary_sbatch(
            partition=partition,
            target_ceiling=target_ceiling,
            capacity_generation=generation,
            intent_token=intent_token,
            output_path=canary_output,
        )
        sbatch_sha = hashlib.sha256(sbatch_payload.encode("utf-8")).hexdigest()
        intent_path = root / CLIENT_CAPACITY_BUILD_INTENT
        intent = {
            "schema_version": 1,
            "protocol": CLIENT_CAPACITY_BUILD_PROTOCOL,
            "intent_token": intent_token,
            "control_immutable_sha256": control["immutable_sha256"],
            "capacity_generation": generation,
            "rollout_generation": control["rollout_generation"],
            "transition_id": transition["transition_id"],
            "partition": partition,
            "target_ceiling": target_ceiling,
            "sbatch_path": str(sbatch_path.resolve()),
            "sbatch_sha256": sbatch_sha,
            "created_at": utc_timestamp(timestamp),
            "created_timestamp": timestamp,
        }
        if action == "dry-run":
            return {
                "action": action,
                "would_change": True,
                "intent": intent,
                "live_client_capacity": live_summary,
                "nonpreemptible_client_slots": slots,
                "next_action": "prepare",
            }

        root.mkdir(parents=True, exist_ok=True)
        if intent_path.exists():
            stored_intent = _load_sealed_builder_json(
                intent_path, description="client-capacity build intent"
            )
            stable_fields = set(intent) - {"created_at", "created_timestamp"}
            if any(stored_intent.get(key) != intent[key] for key in stable_fields):
                raise ControlError(
                    "client-capacity build intent conflicts with this generation"
                )
            intent = stored_intent
        else:
            _write_sealed_builder_json(
                intent_path,
                intent,
                description="client-capacity build intent",
            )
        if sbatch_path.exists() or sbatch_path.is_symlink():
            if (
                sbatch_path.is_symlink()
                or not sbatch_path.is_file()
                or sbatch_path.stat().st_nlink != 1
                or sbatch_path.stat().st_mode & 0o222
                or sbatch_path.read_text(encoding="utf-8") != sbatch_payload
                or sha256_file(sbatch_path) != sbatch_sha
            ):
                raise ControlError("client-capacity canary sbatch drifted")
        else:
            _atomic_publish_readonly_text(sbatch_path, sbatch_payload)

        scheduler_payload = {
            "passed": True,
            "client_placement": {
                "capacity_generation": generation,
                "partition": partition,
                "preempt_mode": "OFF",
                "nonpreemptible_client_slots": slots,
                "cpu_limit": int(live_summary["cpu_limit"]),
                "memory_limit_mib": int(live_summary["memory_limit_mib"]),
                "max_submit_jobs": int(live_summary["max_submit_jobs"]),
                "qos_limit": int(DEFAULT_ADMISSION["qos_limit"]),
                "reserve_jobs": int(DEFAULT_ADMISSION["reserve"]),
            },
            "raw_client_capacity_contract": live_capacity,
        }
        stable_scheduler_fields = (
            "partition",
            "cpu_limit",
            "memory_limit_mib",
            "max_submit_jobs",
            "scheduler_policy_contract_id",
        )

        def validate_stored_scheduler(
            stored_scheduler: Mapping[str, Any], *, description: str
        ) -> Mapping[str, Any]:
            if set(stored_scheduler) != {
                "passed",
                "client_placement",
                "raw_client_capacity_contract",
            }:
                raise ControlError(f"{description} fields are not exact")
            stored_raw = stored_scheduler.get(
                "raw_client_capacity_contract"
            )
            if not isinstance(stored_raw, Mapping):
                raise ControlError(f"{description} is malformed")
            try:
                stored_summary = (
                    scheduler_safety.validate_client_capacity_contract(
                        stored_raw,
                        expected_partition=partition,
                        expected_cpu_limit=int(live_summary["cpu_limit"]),
                        expected_memory_limit_mib=int(
                            live_summary["memory_limit_mib"]
                        ),
                        expected_max_submit_jobs=int(
                            live_summary["max_submit_jobs"]
                        ),
                    )
                )
            except scheduler_safety.SchedulerSafetyError as exc:
                raise ControlError(
                    f"{description} raw contract is invalid: {exc}"
                ) from exc
            if (
                stored_scheduler.get("passed") is not True
                or stored_scheduler.get("client_placement")
                != scheduler_payload["client_placement"]
                or any(
                    stored_summary[field] != live_summary[field]
                    for field in stable_scheduler_fields
                )
            ):
                raise ControlError(f"{description} drifted")
            return stored_raw

        if scheduler_preflight_path.exists():
            preflight_scheduler = _load_sealed_builder_json(
                scheduler_preflight_path,
                description="client-capacity scheduler preflight",
            )
            validate_stored_scheduler(
                preflight_scheduler,
                description="stored client-capacity scheduler preflight",
            )
        elif action == "prepare":
            _write_sealed_builder_json(
                scheduler_preflight_path,
                scheduler_payload,
                description="client-capacity scheduler preflight",
            )
        else:
            # The check above deliberately rejects apply-before-prepare. Keep this
            # branch explicit so a later refactor cannot turn apply into an implicit
            # mutable preflight.
            raise ControlError(
                "client-capacity scheduler preflight disappeared before apply"
            )

        if action == "prepare":
            return {
                "action": action,
                "state": "canary_prepared",
                "intent": str(intent_path.resolve()),
                "intent_sha256": sha256_file(intent_path),
                "scheduler_preflight": str(
                    scheduler_preflight_path.resolve()
                ),
                "scheduler_preflight_sha256": sha256_file(
                    scheduler_preflight_path
                ),
                "sbatch": str(sbatch_path.resolve()),
                "sbatch_sha256": sbatch_sha,
                "next_action": "submit",
            }

        if action == "submit":
            canary_scheduler = (
                submission_scheduler_runner or _run_subprocess
            )
            canary_submitter = submit_runner or _run_subprocess
            operating_system_user = pwd.getpwuid(os.getuid()).pw_name
            if (
                scheduler_user is not None
                and scheduler_user != operating_system_user
                and (
                    submission_scheduler_runner is None
                    or submit_runner is None
                )
            ):
                raise ControlError(
                    "client-capacity scheduler account override is permitted "
                    "only at an injected test boundary"
                )
            effective_scheduler_user = (
                scheduler_user or operating_system_user
            )
            if re.fullmatch(
                r"[A-Za-z_][A-Za-z0-9_.-]*[$]?",
                effective_scheduler_user,
            ) is None:
                raise ControlError(
                    "client-capacity scheduler account identity is unsafe"
                )
            return _submit_client_capacity_canary(
                root=root,
                control=control,
                transition=transition,
                partition=partition,
                target_ceiling=target_ceiling,
                intent_token=intent_token,
                sbatch_path=sbatch_path,
                sbatch_sha256=sbatch_sha,
                scheduler_user=effective_scheduler_user,
                scheduler_runner=canary_scheduler,
                submit_runner=canary_submitter,
                now=timestamp,
            )

        # Apply recaptures the live scheduler/QOS contract and publishes that
        # apply-time observation as the canonical evidence. The prepare capture is
        # retained separately as immutable preflight history.
        scheduler_path = root / CLIENT_CAPACITY_SCHEDULER_EVIDENCE
        if scheduler_path.exists():
            stored_scheduler = _load_sealed_builder_json(
                scheduler_path, description="client-capacity scheduler evidence"
            )
            canonical_scheduler_contract = validate_stored_scheduler(
                stored_scheduler,
                description="stored client-capacity scheduler evidence",
            )
        else:
            _write_sealed_builder_json(
                scheduler_path,
                scheduler_payload,
                description="client-capacity scheduler evidence",
            )
            canonical_scheduler_contract = live_capacity
        submission_root = root / CLIENT_CAPACITY_SUBMISSION_DIRECTORY
        submission_intent = _load_sealed_builder_json(
            submission_root / CLIENT_CAPACITY_SUBMISSION_INTENT,
            description="client-capacity submission intent",
        )
        (
            accepted_submission_path,
            accepted_submission,
            accepted_submission_sha256,
        ) = _load_client_capacity_submission_accepted(
            submission_root,
            submission_intent=submission_intent,
        )
        canary_job_id = accepted_submission["job_id"]

        if (
            isinstance(control["capacity"].get("active_transition"), Mapping)
            and control["capacity"]["active_transition"].get("phase")
            == "readiness_pending"
        ):
            validate_capacity_readiness_pending_state(
                control, require_fleet_gate=True, verify_files=True
            )
            _capacity_gates_are_fresh(
                control, control["capacity"]["active_transition"]
            )
        validate_readiness(
            control,
            state_dir=state_dir,
            verify_files=True,
            now=timestamp,
        )
        canary_payload = _capture_client_capacity_canary(
            job_id=str(canary_job_id),
            partition=partition,
            target_ceiling=target_ceiling,
            capacity_generation=generation,
            sbatch_path=sbatch_path,
            sbatch_sha256=sbatch_sha,
            expected_job_comment=accepted_submission["job_comment"],
            expected_submit_argv=accepted_submission["submit_argv"],
            runner=command,
        )
        canary_path = root / CLIENT_CAPACITY_CANARY_EVIDENCE
        _write_sealed_builder_json(
            canary_path,
            canary_payload,
            description="client-capacity canary evidence",
        )
        readiness_payload = {
            "passed": True,
            "capacity_generation": generation,
            "scheduler_reconciliation_passed": True,
            "fleet_readiness_passed": True,
            "client_canary_passed": True,
            "control_immutable_sha256": control["immutable_sha256"],
            "rollout_generation": control["rollout_generation"],
            "transition_id": transition["transition_id"],
            "fleet_evidence": control["readiness"]["fleet"].get("evidence"),
            "fleet_evidence_sha256": control["readiness"]["fleet"].get("sha256"),
            "smoke_evidence": control["readiness"]["smoke_runs"].get("evidence"),
            "smoke_evidence_sha256": control["readiness"]["smoke_runs"].get("sha256"),
            "scheduler_reconciliation_evidence": control["readiness"][
                "scheduler_reconciliation"
            ].get("evidence"),
            "scheduler_reconciliation_evidence_sha256": control["readiness"][
                "scheduler_reconciliation"
            ].get("sha256"),
        }
        readiness_path = root / CLIENT_CAPACITY_READINESS_EVIDENCE
        _write_sealed_builder_json(
            readiness_path,
            readiness_payload,
            description="client-capacity readiness evidence",
        )
        contract = control["capacity"].get("current_contract")
        if not isinstance(contract, Mapping):
            raise ControlError(
                "higher client-capacity build lacks the current capacity contract"
            )
        authorization = {
            "schema_version": CLIENT_CAPACITY_AUTHORIZATION_SCHEMA_VERSION,
            "protocol": CLIENT_CAPACITY_AUTHORIZATION_PROTOCOL,
            "passed": True,
            "control_immutable_sha256": control["immutable_sha256"],
            "capacity_generation": generation,
            "capacity_contract_sha256": contract["sha256"],
            "authorized_cell_ceiling": target_ceiling,
            "partition": partition,
            "preempt_mode": "OFF",
            "nonpreemptible_client_slots": slots,
            "cpu_limit": int(live_summary["cpu_limit"]),
            "memory_limit_mib": int(live_summary["memory_limit_mib"]),
            "max_submit_jobs": int(live_summary["max_submit_jobs"]),
            "qos_limit": int(DEFAULT_ADMISSION["qos_limit"]),
            "reserve_jobs": int(DEFAULT_ADMISSION["reserve"]),
            "cell_cpus": int(DEFAULT_ADMISSION["cell_cpus"]),
            "cell_memory_mib": 4096,
            "scheduler_evidence": {
                "path": str(scheduler_path.resolve()),
                "sha256": sha256_file(scheduler_path),
            },
            "canary_evidence": {
                "path": str(canary_path.resolve()),
                "sha256": sha256_file(canary_path),
            },
            "accepted_submission_evidence": {
                "path": str(accepted_submission_path.resolve()),
                "sha256": accepted_submission_sha256,
            },
            "readiness_evidence": {
                "path": str(readiness_path.resolve()),
                "sha256": sha256_file(readiness_path),
            },
            "captured_timestamp": float(
                canonical_scheduler_contract["captured_timestamp"]
            ),
        }
        _write_sealed_builder_json(
            marker_path,
            authorization,
            description="client-capacity complete marker",
        )
        marker_sha = sha256_file(marker_path)
        _read_client_capacity_authorization(
            state_dir,
            control,
            marker_path,
            marker_sha,
            attested_timestamp=timestamp,
        )
        return {
            "action": action,
            "state": "complete",
            "authorization": str(marker_path.resolve()),
            "sha256": marker_sha,
            "submit_command": None,
        }


def attest_client_capacity_generation(
    state_dir: Path,
    *,
    evidence_path: Path,
    expected_sha256: str,
    now: float | None = None,
) -> dict[str, Any]:
    """Attach one sealed higher-stage placement generation without clearing its hold."""

    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir, verify_files=True)
        active_transition = control["capacity"].get("active_transition")
        if active_transition is not None and (
            not isinstance(active_transition, Mapping)
            or active_transition.get("phase") != "readiness_pending"
        ):
            raise ControlError(
                "client capacity can be attested only after transition fleet "
                "publication and readiness"
            )
        record = _read_client_capacity_authorization(
            state_dir,
            control,
            evidence_path,
            expected_sha256,
            attested_timestamp=timestamp,
        )
        existing = next(
            (
                item
                for item in control["admission_ramp"][
                    "client_capacity_authorizations"
                ]
                if item["capacity_generation"] == record["capacity_generation"]
                and item["sha256"] == record["sha256"]
            ),
            None,
        )
        if existing is not None:
            if existing != record:
                raise ControlError(
                    "client-capacity attestation is not idempotent"
                )
            return control
        control["admission_ramp"]["client_capacity_authorizations"].append(
            record
        )
        gate = control["admission_ramp"].get("capacity_gate")
        if (
            isinstance(gate, dict)
            and gate["capacity_generation"] == record["capacity_generation"]
            and record["authorized_cell_ceiling"] >= gate["target_ceiling"]
        ):
            control["admission_ramp"]["capacity_gate"] = None
        _reset_admission_ramp(
            state_dir,
            control,
            reason="client_capacity_generation_attested",
            now=timestamp,
            clear_last_observation=True,
        )
        append_transition(
            state_dir,
            control,
            event="client_capacity_generation_attested",
            details={
                "capacity_generation": record["capacity_generation"],
                "authorized_cell_ceiling": record[
                    "authorized_cell_ceiling"
                ],
                "path": record["path"],
                "sha256": record["sha256"],
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        return copy.deepcopy(control)


def _request_client_capacity_transition_locked(
    state_dir: Path,
    control: dict[str, Any],
    *,
    from_ceiling: int,
    target_ceiling: int,
    now: float,
) -> None:
    """Persist the fail-closed capacity gate while the control lock is held."""

    ramp = control["admission_ramp"]
    existing_gate = ramp.get("capacity_gate")
    if existing_gate is not None:
        if (
            existing_gate.get("from_ceiling") != from_ceiling
            or existing_gate.get("target_ceiling") != target_ceiling
        ):
            raise ControlError(
                "another client-capacity transition request is unresolved"
            )
    else:
        _reset_admission_ramp(
            state_dir,
            control,
            reason="client_capacity_generation_required",
            now=now,
        )
        gate = {
            "state": "capacity_transition_required",
            "from_ceiling": int(from_ceiling),
            "target_ceiling": int(target_ceiling),
            "capacity_generation": int(
                control["capacity"]["current_generation"]
            ),
            "control_immutable_sha256": str(control["immutable_sha256"]),
            "requested_at": utc_timestamp(now),
            "requested_timestamp": float(now),
            "reason": "sealed_client_capacity_authorization_missing",
        }
        ramp["capacity_gate"] = gate
        append_transition(
            state_dir,
            control,
            event="client_capacity_transition_required",
            details=copy.deepcopy(gate),
            now=now,
        )

    dedupe_key = "monitor:capacity-gate"
    active_alert = next(
        (
            alert
            for alert in reversed(control["alerts"])
            if alert.get("dedupe_key") == dedupe_key
            and alert.get("resolved_at") is None
        ),
        None,
    )
    if active_alert is None:
        message = (
            f"admission stage {target_ceiling} requires a sealed non-preemptible "
            "client-placement capacity generation; the current protected-capacity "
            f"contract is authorized only through {PRODUCTION_NONPREEMPTIBLE_CELL_CAP}"
        )
        email = _new_alert_email_state()
        email.update(
            {
                "requested": True,
                "next_retry_at": utc_timestamp(now),
                "next_retry_timestamp": float(now),
            }
        )
        alert = {
            "alert_id": uuid.uuid4().hex,
            "kind": "client-capacity-generation",
            "severity": "critical",
            "message": message,
            "dedupe_key": dedupe_key,
            "first_at": utc_timestamp(now),
            "first_timestamp": float(now),
            "last_at": utc_timestamp(now),
            "last_timestamp": float(now),
            "occurrences": 1,
            "resolved_at": None,
            "email": email,
        }
        control["alerts"].append(alert)
        _append_jsonl(
            state_dir / ALERT_JOURNAL,
            {
                "at": utc_timestamp(now),
                "timestamp": float(now),
                "action": "raised",
                "alert_id": alert["alert_id"],
                "kind": alert["kind"],
                "severity": alert["severity"],
                "message": alert["message"],
                "dedupe_key": alert["dedupe_key"],
                "occurrences": 1,
            },
        )
        append_transition(
            state_dir,
            control,
            event="alert_raised",
            details={
                "alert_id": alert["alert_id"],
                "kind": alert["kind"],
                "severity": "critical",
                "dedupe_key": dedupe_key,
            },
            now=now,
        )
    _update_admission_safety_hold_locked(
        state_dir,
        control,
        active_critical_keys=(dedupe_key,),
        clean_poll=False,
        semantic_scan_clean=None,
        timestamp=now,
    )
    ramp["last_action"] = {
        "action": "capacity_gate_held",
        "reason": "sealed_client_capacity_authorization_missing",
        "at": utc_timestamp(now),
        "timestamp": float(now),
        "current_ceiling": int(from_ceiling),
        "required_ceiling": int(target_ceiling),
        "capacity_generation": int(
            control["capacity"]["current_generation"]
        ),
        "base_nonpreemptible_cap": PRODUCTION_NONPREEMPTIBLE_CELL_CAP,
        "effective_ceiling": 0,
    }


def _start_admission_ramp_window(
    ramp: MutableMapping[str, Any],
    *,
    control: Mapping[str, Any],
    observation: Mapping[str, Any],
    record: Mapping[str, Any],
    epoch: Mapping[str, Any],
    now: float,
) -> None:
    validated_qids = observation.get("run_validated_qids")
    useful_qids = observation.get("run_useful_qids")
    if (
        not _valid_run_qid_map(validated_qids)
        or not _valid_run_qid_map(useful_qids)
        or any(
            useful_qids[run_id] > validated_qids[run_id]
            for run_id in REQUIRED_RUNS
        )
    ):
        raise ControlError(
            "a ramp window can start only from complete trusted/useful per-run "
            "QID evidence"
        )
    ramp["window"] = {
        "rollout_generation": int(control["rollout_generation"]),
        "fleet_generation": str(observation["fleet_generation"]),
        "throughput_epoch": int(epoch["epoch"]),
        "ceiling": int(control["admission"]["current_ceiling"]),
        "started_at": utc_timestamp(now),
        "started_timestamp": now,
        "baseline_run_validated_qids": copy.deepcopy(validated_qids),
        "latest_run_validated_qids": copy.deepcopy(validated_qids),
        "baseline_run_useful_qids": copy.deepcopy(useful_qids),
        "latest_run_useful_qids": copy.deepcopy(useful_qids),
        "observations": [copy.deepcopy(dict(record))],
    }


def _verify_admission_ramp_window_evidence(
    state_dir: Path, observations: Sequence[Mapping[str, Any]]
) -> str:
    """Re-open every sealed report before using its chain to raise admission."""

    identities: set[tuple[str, str]] = set()
    for record in observations:
        path = Path(str(record["path"]))
        digest = str(record["sha256"])
        identity = (str(path.expanduser().resolve()), digest)
        if identity in identities:
            raise ControlError("admission ramp window repeats one evidence file")
        identities.add(identity)
        _report, observation, observed_sha256 = _read_admission_ramp_evidence(
            state_dir, path, digest
        )
        if (
            observed_sha256 != digest
            or float(observation["captured_timestamp"])
            != float(record["captured_timestamp"])
            or float(observation["committed_timestamp"])
            != float(record["timestamp"])
            or observation["cadence"] != record["cadence"]
            or observation.get("run_validated_qids")
            != record.get("run_validated_qids")
            or observation.get("run_useful_qids")
            != record.get("run_useful_qids")
        ):
            raise ControlError("admission ramp evidence chain record drifted")
    return sha256_value(observations)


def record_successful_poll(
    state_dir: Path,
    *,
    useful_qids: int,
    fleet_generation: str,
    strata_with_throughput: int | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Append generation-scoped throughput accounting after a successful live poll."""
    if useful_qids < 0:
        raise ControlError("useful_qids must be non-negative")
    if not fleet_generation:
        raise ControlError("fleet_generation must be non-empty")
    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        try:
            _require_production_running(control)
        except ControlError as exc:
            raise ControlError(
                "throughput epochs cannot start or advance while paused or resuming"
            ) from exc
        critical_alerts = _active_critical_alerts(control)
        if critical_alerts:
            raise ControlError(
                "throughput epochs cannot advance with unresolved critical alerts: "
                + ", ".join(critical_alerts)
            )
        epochs = control["throughput_epochs"]
        open_epoch = (
            epochs[-1] if epochs and epochs[-1].get("closed_at") is None else None
        )
        if (
            open_epoch is not None
            and open_epoch["fleet_generation"] != fleet_generation
        ):
            _close_open_epoch(control, reason="material_fleet_change", now=timestamp)
            _reset_admission_ramp(
                state_dir,
                control,
                reason="material_fleet_change",
                now=timestamp,
                ceiling=24,
                clear_last_observation=True,
            )
            open_epoch = None
        if open_epoch is None:
            open_epoch = {
                "epoch": len(epochs) + 1,
                "rollout_generation": control["rollout_generation"],
                "fleet_generation": fleet_generation,
                "started_at": utc_timestamp(timestamp),
                "started_timestamp": timestamp,
                "closed_at": None,
                "samples": [],
            }
            epochs.append(open_epoch)
            append_transition(
                state_dir,
                control,
                event="throughput_epoch_started",
                details={
                    "epoch": open_epoch["epoch"],
                    "rollout_generation": control["rollout_generation"],
                    "fleet_generation": fleet_generation,
                },
                now=timestamp,
            )
        samples = open_epoch["samples"]
        if samples and useful_qids < samples[-1]["useful_qids"]:
            raise ControlError(
                "useful QID total regressed within one throughput epoch"
            )
        sample: dict[str, Any] = {
            "at": utc_timestamp(timestamp),
            "timestamp": timestamp,
            "useful_qids": useful_qids,
        }
        if strata_with_throughput is not None:
            if strata_with_throughput < 0:
                raise ControlError("strata_with_throughput must be non-negative")
            sample["strata_with_throughput"] = strata_with_throughput
        samples.append(sample)
        append_transition(
            state_dir,
            control,
            event="successful_production_poll",
            details={
                "epoch": open_epoch["epoch"],
                "useful_qids": useful_qids,
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        return control


def record_admission_ramp_observation(
    state_dir: Path,
    *,
    evidence_path: Path,
    evidence_sha256: str,
    now: float | None = None,
) -> dict[str, Any]:
    """Record one immutable monitor observation and promote only from a full proof.

    Promotion is intentionally not an operator switch.  It is derived under the
    control lock from a read-only checksummed report, the current rollout generation,
    the open material-fleet throughput epoch, alert state, continuous five-minute
    health evidence, and exact per-run semantic progress.
    """

    _report, observation, observed_sha256 = _read_admission_ramp_evidence(
        state_dir, evidence_path, evidence_sha256
    )
    timestamp = (
        float(observation["committed_timestamp"]) if now is None else float(now)
    )
    if timestamp != float(observation["committed_timestamp"]):
        raise ControlError("admission ramp evidence timestamp differs from commit time")
    resolved_path = evidence_path.expanduser().resolve()
    with control_lock(state_dir):
        control = load_control(state_dir)
        ramp = control["admission_ramp"]
        prior = ramp.get("last_observation")
        if isinstance(prior, dict) and (
            prior.get("path") == str(resolved_path)
            and prior.get("sha256") == observed_sha256
        ):
            return control
        if isinstance(prior, dict) and float(prior.get("timestamp", -1.0)) >= timestamp:
            raise ControlError("admission ramp evidence is stale or reordered")

        record = _ramp_observation_record(
            path=resolved_path,
            sha256=observed_sha256,
            observation=observation,
            clean=False,
        )
        ramp["last_observation"] = record
        identity_matches = bool(
            observation.get("control_immutable_sha256")
            == control["immutable_sha256"]
            and observation.get("rollout_generation")
            == control["rollout_generation"]
            and observation.get("admission_ceiling")
            == control["admission"]["current_ceiling"]
        )
        if not identity_matches or control["desired_state"] != "running":
            _reset_admission_ramp(
                state_dir,
                control,
                reason=(
                    "production_not_running"
                    if control["desired_state"] != "running"
                    else "monitor_control_identity_changed"
                ),
                now=timestamp,
            )
            ramp["last_observation"] = record
            _save_control(state_dir, control, now=timestamp)
            return control

        epochs = control["throughput_epochs"]
        epoch = epochs[-1] if epochs and epochs[-1].get("closed_at") is None else None
        fleet_generation = str(observation.get("fleet_generation", ""))
        if isinstance(epoch, dict) and epoch.get("fleet_generation") != fleet_generation:
            _close_open_epoch(control, reason="material_fleet_change", now=timestamp)
            _reset_admission_ramp(
                state_dir,
                control,
                reason="material_fleet_change",
                now=timestamp,
                ceiling=24,
                clear_last_observation=True,
            )
            ramp["last_observation"] = record
            _save_control(state_dir, control, now=timestamp)
            return control
        epoch_matches = bool(
            isinstance(epoch, dict)
            and epoch.get("fleet_generation") == fleet_generation
            and epoch.get("rollout_generation") == control["rollout_generation"]
        )

        critical_evidence = list(observation["critical_finding_keys"])
        blocking_evidence = list(observation["promotion_blocking_finding_keys"])
        active_blocking = _active_ramp_blocking_alerts(control)
        blocking_requires_base_stage = bool(
            (set(blocking_evidence) | set(active_blocking))
            - CLIENT_CAPACITY_GATE_ALERT_KEYS
        )
        semantic_clean = observation.get("semantic_integrity_clean")
        evidence_clean = bool(
            observation.get("production_health_clean") is True
            and not blocking_evidence
            and (
                observation["cadence"] == "health"
                or semantic_clean is True
            )
        )
        clean = bool(evidence_clean and not active_blocking and epoch_matches)
        record["clean"] = clean
        ramp["last_observation"] = record

        window = ramp.get("window")
        if isinstance(window, dict):
            last = window["observations"][-1]
            gap = timestamp - float(last["timestamp"])
            window_identity_matches = bool(
                window["rollout_generation"] == control["rollout_generation"]
                and window["fleet_generation"] == fleet_generation
                and isinstance(epoch, dict)
                and window["throughput_epoch"] == epoch.get("epoch")
                and window["ceiling"] == control["admission"]["current_ceiling"]
            )
            if not window_identity_matches:
                _reset_admission_ramp(
                    state_dir,
                    control,
                    reason="ramp_identity_changed",
                    now=timestamp,
                    ceiling=(24 if window["fleet_generation"] != fleet_generation else None),
                )
                window = None
            elif gap > ADMISSION_RAMP_MAX_OBSERVATION_GAP_SECONDS:
                _reset_admission_ramp(
                    state_dir,
                    control,
                    reason="health_observation_gap",
                    now=timestamp,
                )
                window = None
            elif not clean:
                _reset_admission_ramp(
                    state_dir,
                    control,
                    reason=(
                        "promotion_blocking_alert"
                        if blocking_evidence or active_blocking
                        else "unclean_monitor_observation"
                    ),
                    now=timestamp,
                    ceiling=(
                        24
                        if blocking_requires_base_stage
                        else None
                    ),
                )
                window = None

        if not clean:
            if (
                (blocking_evidence or active_blocking)
                and blocking_requires_base_stage
                and control["admission"]["current_ceiling"] != 24
            ):
                _reset_admission_ramp(
                    state_dir,
                    control,
                    reason="promotion_blocking_alert",
                    now=timestamp,
                    ceiling=24,
                )
            ramp["last_action"] = {
                "action": "blocked",
                "reason": (
                    "promotion_blocking_alert"
                    if blocking_evidence or active_blocking
                    else "unclean_monitor_observation"
                ),
                "at": utc_timestamp(timestamp),
                "timestamp": timestamp,
                "critical_finding_keys": critical_evidence,
                "promotion_blocking_finding_keys": blocking_evidence,
                "active_promotion_blocking_alerts": active_blocking,
                "evidence": str(resolved_path),
                "evidence_sha256": observed_sha256,
            }
            _save_control(state_dir, control, now=timestamp)
            return control

        if control["admission"]["current_ceiling"] == ADMISSION_RAMP_STAGES[-1]:
            ramp["window"] = None
            ramp["last_action"] = {
                "action": "terminal_stage_healthy",
                "at": utc_timestamp(timestamp),
                "timestamp": timestamp,
                "ceiling": ADMISSION_RAMP_STAGES[-1],
                "evidence": str(resolved_path),
                "evidence_sha256": observed_sha256,
            }
            _save_control(state_dir, control, now=timestamp)
            return control

        if ramp.get("window") is None:
            if observation["cadence"] not in {"semantic", "daily"}:
                ramp["last_action"] = {
                    "action": "waiting_for_semantic_baseline",
                    "at": utc_timestamp(timestamp),
                    "timestamp": timestamp,
                    "evidence": str(resolved_path),
                    "evidence_sha256": observed_sha256,
                }
                _save_control(state_dir, control, now=timestamp)
                return control
            assert isinstance(epoch, dict)
            _start_admission_ramp_window(
                ramp,
                control=control,
                observation=observation,
                record=record,
                epoch=epoch,
                now=timestamp,
            )
            append_transition(
                state_dir,
                control,
                event="admission_ramp_window_started",
                details={
                    "ceiling": control["admission"]["current_ceiling"],
                    "rollout_generation": control["rollout_generation"],
                    "fleet_generation": fleet_generation,
                    "throughput_epoch": epoch["epoch"],
                    "baseline_run_validated_qids": observation[
                        "run_validated_qids"
                    ],
                    "baseline_run_useful_qids": observation[
                        "run_useful_qids"
                    ],
                    "evidence_sha256": observed_sha256,
                },
                now=timestamp,
            )
            ramp["last_action"] = {
                "action": "window_started",
                "at": utc_timestamp(timestamp),
                "timestamp": timestamp,
                "ceiling": control["admission"]["current_ceiling"],
            }
            _save_control(state_dir, control, now=timestamp)
            return control

        window = ramp["window"]
        window["observations"].append(record)
        if observation["cadence"] in {"semantic", "daily"}:
            validated_qids = observation["run_validated_qids"]
            useful_qids = observation["run_useful_qids"]
            assert _valid_run_qid_map(validated_qids)
            assert _valid_run_qid_map(useful_qids)
            if any(
                validated_qids[run_id]
                < window["latest_run_validated_qids"][run_id]
                for run_id in REQUIRED_RUNS
            ):
                _reset_admission_ramp(
                    state_dir,
                    control,
                    reason="per_run_validated_qid_regression",
                    now=timestamp,
                )
                _save_control(state_dir, control, now=timestamp)
                return control
            if any(
                useful_qids[run_id] < window["latest_run_useful_qids"][run_id]
                for run_id in REQUIRED_RUNS
            ):
                _reset_admission_ramp(
                    state_dir,
                    control,
                    reason="per_run_useful_qid_regression",
                    now=timestamp,
                )
                _save_control(state_dir, control, now=timestamp)
                return control
            window["latest_run_validated_qids"] = copy.deepcopy(validated_qids)
            window["latest_run_useful_qids"] = copy.deepcopy(useful_qids)

        ceiling = int(control["admission"]["current_ceiling"])
        requirement = ADMISSION_RAMP_REQUIREMENTS.get(ceiling)
        if requirement is None:
            _reset_admission_ramp(
                state_dir,
                control,
                reason="terminal_stage",
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
            return control
        elapsed = timestamp - float(window["started_timestamp"])
        all_runs_progressed = all(
            window["latest_run_useful_qids"][run_id]
            > window["baseline_run_useful_qids"][run_id]
            for run_id in REQUIRED_RUNS
        )
        all_run_progress_required = ceiling == 24
        progress_gate_passed = bool(
            all_runs_progressed or not all_run_progress_required
        )
        can_promote = bool(
            observation["cadence"] in {"semantic", "daily"}
            and elapsed >= float(requirement["clean_seconds"])
            and progress_gate_passed
        )
        if not can_promote:
            ramp["last_action"] = {
                "action": "window_advanced",
                "at": utc_timestamp(timestamp),
                "timestamp": timestamp,
                "ceiling": ceiling,
                "clean_seconds": elapsed,
                "required_clean_seconds": requirement["clean_seconds"],
                "all_runs_progressed": all_runs_progressed,
                "all_run_progress_required": all_run_progress_required,
            }
            _save_control(state_dir, control, now=timestamp)
            return control

        evidence_chain_sha256 = _verify_admission_ramp_window_evidence(
            state_dir, window["observations"]
        )
        validate_readiness(control, state_dir=state_dir, verify_files=True)
        next_ceiling = int(requirement["next_ceiling"])
        client_capacity_authorization = (
            _verified_client_capacity_authorization(
                state_dir,
                control,
                target_ceiling=next_ceiling,
                attested_timestamp=timestamp,
            )
        )
        if (
            next_ceiling > PRODUCTION_NONPREEMPTIBLE_CELL_CAP
            and client_capacity_authorization is None
        ):
            _request_client_capacity_transition_locked(
                state_dir,
                control,
                from_ceiling=ceiling,
                target_ceiling=next_ceiling,
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
            return copy.deepcopy(control)
        ramp["capacity_gate"] = None
        promotion = {
            "from_ceiling": ceiling,
            "to_ceiling": next_ceiling,
            "at": utc_timestamp(timestamp),
            "timestamp": timestamp,
            "rollout_generation": control["rollout_generation"],
            "fleet_generation": fleet_generation,
            "throughput_epoch": epoch["epoch"],
            "clean_seconds": elapsed,
            "required_clean_seconds": requirement["clean_seconds"],
            "all_runs_progressed": all_runs_progressed,
            "all_run_progress_required": all_run_progress_required,
            "baseline_run_validated_qids": copy.deepcopy(
                window["baseline_run_validated_qids"]
            ),
            "final_run_validated_qids": copy.deepcopy(
                window["latest_run_validated_qids"]
            ),
            "baseline_run_useful_qids": copy.deepcopy(
                window["baseline_run_useful_qids"]
            ),
            "final_run_useful_qids": copy.deepcopy(
                window["latest_run_useful_qids"]
            ),
            "observations": copy.deepcopy(window["observations"]),
            "evidence_sha256": evidence_chain_sha256,
            "capacity_generation": int(
                control["capacity"]["current_generation"]
            ),
            "client_capacity_authorization_sha256": (
                client_capacity_authorization["sha256"]
                if client_capacity_authorization is not None
                else effective_protected_capacity_binding(
                    control, verify_files=True
                )["sha256"]
            ),
        }
        ramp["promotions"].append(promotion)
        control["admission"]["current_ceiling"] = next_ceiling
        control["admission_safety_hold"]["configured_ceiling"] = next_ceiling
        ramp["current_ceiling"] = next_ceiling
        if next_ceiling == ADMISSION_RAMP_STAGES[-1]:
            ramp["window"] = None
        else:
            _start_admission_ramp_window(
                ramp,
                control=control,
                observation=observation,
                record=record,
                epoch=epoch,
                now=timestamp,
            )
        ramp["last_action"] = {
            "action": "promoted",
            "at": utc_timestamp(timestamp),
            "timestamp": timestamp,
            "previous_ceiling": ceiling,
            "current_ceiling": next_ceiling,
            "evidence_sha256": promotion["evidence_sha256"],
            "capacity_generation": promotion["capacity_generation"],
            "client_capacity_authorization_sha256": promotion[
                "client_capacity_authorization_sha256"
            ],
        }
        append_transition(
            state_dir,
            control,
            event="admission_ceiling_promoted",
            details={
                "previous": ceiling,
                "current": next_ceiling,
                "rollout_generation": control["rollout_generation"],
                "fleet_generation": fleet_generation,
                "throughput_epoch": epoch["epoch"],
                "clean_seconds": elapsed,
                "evidence_sha256": promotion["evidence_sha256"],
                "capacity_generation": promotion["capacity_generation"],
                "client_capacity_authorization_sha256": promotion[
                    "client_capacity_authorization_sha256"
                ],
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        return control


def _submit_line_option(
    command: str, *, source: str, option: str
) -> str | None:
    """Recover one exact long option from an accounting SubmitLine.

    ``AccountingStoreFlags=(null)`` on the production cluster means sacct's Comment
    field is empty, and this Slurm build cannot expose Dependency through ``sacct``.
    Both values are nevertheless retained on the immutable sbatch SubmitLine. Duplicate,
    empty, or malformed options are an ambiguity rather than permission to guess.
    """

    flag = "--" + option
    if flag not in command:
        return None
    try:
        tokens = shlex.split(command)
    except ValueError as exc:
        raise SchedulerAmbiguity(f"invalid {source} SubmitLine quoting: {exc}") from exc
    values: list[str] = []
    for index, token in enumerate(tokens):
        if token.startswith(flag + "="):
            value = token.split("=", 1)[1]
            if not value:
                raise SchedulerAmbiguity(
                    f"{source} SubmitLine contains a valueless {flag}"
                )
            values.append(value)
        elif token == flag:
            if index + 1 >= len(tokens) or tokens[index + 1].startswith("--"):
                raise SchedulerAmbiguity(
                    f"{source} SubmitLine contains a valueless {flag}"
                )
            values.append(tokens[index + 1])
    if len(values) > 1:
        raise SchedulerAmbiguity(
            f"{source} SubmitLine contains duplicate {flag} options"
        )
    return values[0] if values else None


def _submit_line_comment(command: str, *, source: str) -> str | None:
    return _submit_line_option(command, source=source, option="comment")


def _submit_line_dependency(command: str, *, source: str) -> str | None:
    return _submit_line_option(command, source=source, option="dependency")


_SACCT_JOB_ID_RE = re.compile(
    r"[0-9]+(?:[_+][0-9]+)?(?:\.[A-Za-z0-9_-]+)?"
)


def _scheduler_physical_records(
    text: str, *, source: str
) -> list[tuple[int, str]]:
    """Reassemble sacct records whose final SubmitLine contains literal newlines.

    ``sacct -P`` does not escape newlines in its last field. Historical ``srun`` and
    ``sbatch --wrap`` commands can therefore occupy several physical output lines.
    The logical ``JobID`` is scheduler-owned and gives an unambiguous start marker
    while preserving the ``array_job_id_task_id`` identity emitted by ``squeue %i``.
    ``JobIDRaw`` cannot be used here: Slurm assigns a different raw allocation ID to
    most running array elements, which would split one array intent into unrelated
    jobs. Continuation text is retained byte-for-byte (apart from ``splitlines``
    newline normalization). Live squeue rows use a final Dependency field and are one
    physical line on this cluster, so they remain strict one-line records.
    """

    if source != "sacct":
        return list(enumerate(text.splitlines(), start=1))
    records: list[tuple[int, str]] = []
    for line_number, physical_line in enumerate(text.splitlines(), start=1):
        candidate = physical_line.split("|", 4)
        starts_record = (
            len(candidate) == 5
            and _SACCT_JOB_ID_RE.fullmatch(candidate[0].strip()) is not None
            and bool(candidate[1].strip())
            and bool(candidate[2].strip())
        )
        if starts_record:
            records.append((line_number, physical_line))
        elif records:
            start, existing = records[-1]
            records[-1] = (start, existing + "\n" + physical_line)
        elif physical_line.strip():
            raise SchedulerAmbiguity(
                f"malformed sacct scheduler row {line_number}: {physical_line!r}"
            )
    return records


def parse_scheduler_rows(
    text: str,
    *,
    source: str,
    require_placement: bool = False,
) -> list[SchedulerJob]:
    """Parse the common scheduler row, including scheduler-owned dependency state."""
    rows: list[SchedulerJob] = []
    for line_number, raw in _scheduler_physical_records(text, source=source):
        if not raw.strip():
            continue
        if source == "sacct":
            fields = raw.rstrip("\n").split("|", 6)
            expected_fields = 7
            legacy_fields = 5
        elif source == "squeue":
            fields = raw.rstrip("\n").split("|", 7)
            expected_fields = 8
            legacy_fields = 6
        else:
            raise SchedulerAmbiguity(f"unsupported scheduler row source {source!r}")
        if len(fields) == legacy_fields and not require_placement:
            if source == "sacct":
                job_id, name, state, comment, command = (
                    field.strip() for field in fields
                )
            else:
                job_id, name, state, comment, command, dependency = (
                    field.strip() for field in fields
                )
            partition = ""
            qos = ""
        elif len(fields) == expected_fields:
            if source == "sacct":
                job_id, name, state, partition, qos, comment, command = (
                    field.strip() for field in fields
                )
            else:
                (
                    job_id,
                    name,
                    state,
                    partition,
                    qos,
                    comment,
                    command,
                    dependency,
                ) = (field.strip() for field in fields)
        else:
            raise SchedulerAmbiguity(
                f"malformed {source} scheduler row {line_number}: {raw!r}"
            )
        normalized_state = state.upper().split()[0].rstrip("+")
        placement_required_for_row = require_placement and normalized_state in {
            "PENDING",
            "RUNNING",
            "CONFIGURING",
            "COMPLETING",
            "RESIZING",
            "SUSPENDED",
        }
        if source == "sacct":
            stored = "" if comment.lower() in {"", "(null)", "null", "none"} else comment
            if "." in job_id:
                # Accounting steps are discarded by ``query_scheduler`` and can carry
                # arbitrary multiline shell fragments rather than an sbatch command.
                # Do not ask shlex to reinterpret those unrelated payloads.
                comment = stored
                dependency = ""
            else:
                derived = _submit_line_comment(command, source=source)
                dependency = _submit_line_dependency(command, source=source) or ""
                if stored and derived and stored != derived:
                    raise SchedulerAmbiguity(
                        f"sacct Comment/SubmitLine conflict for job {job_id}"
                    )
                comment = stored or derived or ""
        if (
            not job_id
            or not name
            or not state
            or (
                placement_required_for_row
                and (
                    re.fullmatch(r"[A-Za-z0-9_.-]+", partition) is None
                    or re.fullmatch(r"[A-Za-z0-9_.-]+", qos) is None
                )
            )
        ):
            raise SchedulerAmbiguity(
                f"incomplete {source} scheduler row {line_number}: {raw!r}"
            )
        rows.append(
            SchedulerJob(
                job_id=job_id,
                job_name=name,
                state=state,
                comment=comment,
                command=command,
                source=source,
                dependency=dependency,
                partition=partition,
                qos=qos,
            )
        )
    return rows


def _run_subprocess(argv: Sequence[str]) -> subprocess.CompletedProcess[str]:
    command = _trusted_system_argv(argv)
    environment = _sanitized_subprocess_environment()
    if isinstance(argv, _ExactSbatchInvocation):
        try:
            submission_text = argv.stdin_bytes.decode("utf-8")
        except UnicodeError as exc:
            raise ControlError(
                f"exact sbatch payload is not UTF-8: {exc}"
            ) from exc
        return subprocess.run(
            command,
            capture_output=True,
            text=True,
            check=False,
            timeout=60.0,
            input=submission_text,
            env=environment,
        )
    return subprocess.run(
        command,
        capture_output=True,
        text=True,
        check=False,
        timeout=15.0,
        env=environment,
    )


def _normalized_scheduler_dependency(value: str) -> str:
    """Normalize only squeue's display annotations for cross-source comparison."""

    stripped = value.strip()
    if stripped.lower() in {"", "(null)", "null", "none"}:
        return ""
    return re.sub(r"\([^()]*\)", "", stripped)


def query_scheduler(
    *,
    runner: Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None = None,
    user: str | None = None,
    now: float | None = None,
    tolerate_errors: bool = False,
) -> SchedulerSnapshot:
    """Join live ``squeue`` and accounting ``sacct`` truth by logical job ID."""
    invoke = runner or _run_subprocess
    scheduler_user = user or os.environ.get("USER")
    if not scheduler_user:
        raise ControlError("USER is unset; scheduler queries cannot be scoped safely")
    timestamp = time.time() if now is None else float(now)
    accounting_start_text = time.strftime(
        "%Y-%m-%d", time.localtime(timestamp - 7 * 86_400)
    )
    accounting_start_timestamp = time.mktime(
        time.strptime(accounting_start_text, "%Y-%m-%d")
    )
    commands = (
        (
            "squeue",
            [
                "squeue",
                "-u",
                scheduler_user,
                "-h",
                "-r",
                "-o",
                "%i|%j|%T|%P|%q|%k|%o|%E",
            ],
        ),
        (
            "sacct",
            [
                "sacct",
                "-u",
                scheduler_user,
                "-n",
                "-P",
                "-S",
                accounting_start_text,
                "--format=JobID,JobName,State,Partition,QOS,Comment,SubmitLine",
            ],
        ),
    )
    by_id: dict[str, SchedulerJob] = {}
    squeue_rows: dict[str, SchedulerJob] = {}
    errors: list[str] = []
    succeeded: dict[str, bool] = {"squeue": False, "sacct": False}
    # Accounting is loaded first; live queue rows then override stale accounting state.
    outputs: dict[str, str] = {}
    for source, command in commands:
        try:
            proc = invoke(command)
        except (OSError, subprocess.TimeoutExpired) as exc:
            errors.append(f"{source} failed: {exc}")
            continue
        if proc.returncode != 0:
            errors.append(
                f"{source} failed rc={proc.returncode}: {proc.stderr.strip()[:500]}"
            )
            continue
        succeeded[source] = True
        outputs[source] = proc.stdout
    for source in ("sacct", "squeue"):
        if source not in outputs:
            continue
        for row in parse_scheduler_rows(
            outputs[source],
            source=source,
            require_placement=True,
        ):
            # sacct includes job steps; they are never independently submitted control
            # jobs and would make a parent job appear duplicated.
            if source == "sacct" and "." in row.job_id:
                continue
            prior = by_id.get(row.job_id)
            if source == "squeue" and prior is not None and (
                prior.job_name != row.job_name
                or (
                    bool(prior.comment)
                    and prior.comment != row.comment
                )
                or prior.partition != row.partition
                or prior.qos != row.qos
            ):
                raise SchedulerAmbiguity(
                    f"squeue/sacct identity conflict for scheduler job {row.job_id}"
                )
            live_dependency = _normalized_scheduler_dependency(row.dependency)
            accounting_dependency = (
                _normalized_scheduler_dependency(prior.dependency)
                if prior is not None
                else ""
            )
            if (
                source == "squeue"
                and prior is not None
                and live_dependency
                and accounting_dependency
                and live_dependency != accounting_dependency
            ):
                raise SchedulerAmbiguity(
                    f"squeue/sacct dependency conflict for scheduler job {row.job_id}"
                )
            if (
                source == "squeue"
                and prior is not None
                and not live_dependency
                and bool(accounting_dependency)
            ):
                # A satisfied dependency may disappear from live ``squeue %E`` while
                # accounting retains the immutable submission edge.  Keep live state
                # and command provenance, but preserve that accounting dependency.
                row = SchedulerJob(
                    job_id=row.job_id,
                    job_name=row.job_name,
                    state=row.state,
                    comment=row.comment,
                    command=row.command,
                    source=row.source,
                    dependency=prior.dependency,
                    partition=row.partition,
                    qos=row.qos,
                )
            by_id[row.job_id] = row
            if source == "squeue":
                squeue_rows[row.job_id] = row
    if errors and not tolerate_errors:
        raise ControlError("; ".join(errors))
    # sacct may report an array-parent summary while expanded live elements appear
    # only in ``squeue -r``.  That is the sole safe active sacct-only shape.  Any
    # other active accounting row is incomplete live truth: adopting it can commit
    # fairness while the occupancy view reserves zero slots, permitting a redraw.
    for job in tuple(by_id.values()):
        if job.source != "sacct" or not job.active:
            continue
        prefix = job.job_id + "_"
        children = [
            child
            for child_id, child in squeue_rows.items()
            if child_id.startswith(prefix)
            and child_id[len(prefix) :].isdigit()
            and child.active
        ]
        if not children:
            raise SchedulerAmbiguity(
                f"active sacct-only scheduler job {job.job_id} is absent from "
                "complete squeue truth"
            )
        if any(
            child.job_name != job.job_name
            or (job.comment and child.comment != job.comment)
            or child.partition != job.partition
            or child.qos != job.qos
            for child in children
        ):
            raise SchedulerAmbiguity(
                f"active sacct array parent {job.job_id} conflicts with its "
                "expanded squeue elements"
            )
    return SchedulerSnapshot(
        jobs=tuple(sorted(by_id.values(), key=lambda job: job.job_id)),
        captured_at=timestamp,
        squeue_ok=succeeded["squeue"],
        sacct_ok=succeeded["sacct"],
        errors=tuple(errors),
        accounting_start_timestamp=(
            accounting_start_timestamp if succeeded["sacct"] else None
        ),
    )


def _scoped_control_jobs(snapshot: SchedulerSnapshot) -> list[SchedulerJob]:
    return [job for job in snapshot.jobs if parse_job_token(job.comment) is not None]


def _controller_references(control: Mapping[str, Any]) -> tuple[set[str], set[str]]:
    job_ids: set[str] = set()
    tokens: set[str] = set()
    for role in ROLE_NAMES:
        role_state = control["controllers"][role]
        for field in ("active", "successor", "submission_intent"):
            record = role_state.get(field)
            if not isinstance(record, dict):
                continue
            if record.get("job_id"):
                job_ids.add(str(record["job_id"]))
            if record.get("job_token"):
                tokens.add(str(record["job_token"]))
    return job_ids, tokens


def build_reconciliation_report(
    control: Mapping[str, Any],
    snapshot: SchedulerSnapshot,
    *,
    all_jobs: bool,
    no_admit: bool,
) -> dict[str, Any]:
    """Build a fail-closed scheduler/control join without changing admission state."""
    if not all_jobs or not no_admit:
        raise ControlError("schema-5 reconciliation requires both --all and --no-admit")
    referenced_ids, referenced_tokens = _controller_references(control)
    scoped = _scoped_control_jobs(snapshot)
    active_by_token: dict[str, list[SchedulerJob]] = {}
    all_by_token: dict[str, list[SchedulerJob]] = {}
    malformed: list[str] = []
    for job in snapshot.jobs:
        if (
            job.comment.startswith(TOKEN_PREFIX)
            and parse_job_token(job.comment) is None
        ):
            malformed.append(job.job_id)
    for job in scoped:
        assert job.token is not None
        all_by_token.setdefault(job.token, []).append(job)
        if job.active:
            active_by_token.setdefault(job.token, []).append(job)
    ambiguous = {
        token: [job.job_id for job in jobs]
        for token, jobs in active_by_token.items()
        if len(jobs) > 1
    }
    unmappable = [
        job.job_id
        for job in scoped
        if job.active
        and job.job_id not in referenced_ids
        and job.token not in referenced_tokens
    ]
    missing_referenced: list[str] = []
    identity_mismatches: list[dict[str, str]] = []
    by_id = {job.job_id: job for job in snapshot.jobs}
    for job_id in referenced_ids:
        record = by_id.get(job_id)
        # Old terminal records in sacct are legitimate history; only references claiming
        # to be active/pending are checked below in the per-role summary.
        if record is None:
            missing_referenced.append(job_id)
    roles: dict[str, Any] = {}
    for role in ROLE_NAMES:
        role_state = control["controllers"][role]
        role_summary: dict[str, Any] = {}
        for field in ("active", "successor", "submission_intent"):
            expected = role_state.get(field)
            if not isinstance(expected, dict):
                role_summary[field] = None
                continue
            matches = all_by_token.get(str(expected.get("job_token", "")), [])
            live_matches = [job for job in matches if job.active]
            recorded_job_id = str(expected.get("job_id", ""))
            same_id = by_id.get(recorded_job_id)
            if (
                recorded_job_id
                and same_id is not None
                and same_id.active
                and same_id.token != expected.get("job_token")
            ):
                identity_mismatches.append(
                    {
                        "role": role,
                        "field": field,
                        "job_id": recorded_job_id,
                        "expected_token": str(expected.get("job_token", "")),
                        "observed_comment": same_id.comment,
                    }
                )
            role_summary[field] = {
                "recorded_job_id": expected.get("job_id"),
                "intent_token": expected.get("intent_token"),
                "matching_job_ids": [job.job_id for job in matches],
                "live_job_ids": [job.job_id for job in live_matches],
            }
        roles[role] = role_summary
    errors = list(snapshot.errors)
    if not snapshot.squeue_ok:
        errors.append("live squeue truth is unavailable")
    if not snapshot.sacct_ok:
        errors.append("sacct transaction history is unavailable")
    if ambiguous:
        errors.append("duplicate active controller intent tokens")
    if unmappable:
        errors.append("unmappable active schema-5 jobs")
    if malformed:
        errors.append("malformed schema-5 scheduler tokens")
    if identity_mismatches:
        errors.append("recorded controller job IDs have scheduler token mismatches")
    report = {
        "schema_version": 1,
        "gate": "scheduler_reconciliation",
        "immutable_sha256": control["immutable_sha256"],
        "captured_at": utc_timestamp(snapshot.captured_at),
        "captured_timestamp": snapshot.captured_at,
        "all": True,
        "no_admit": True,
        "scheduler": {
            "squeue_ok": snapshot.squeue_ok,
            "sacct_ok": snapshot.sacct_ok,
            "job_count": len(snapshot.jobs),
            "schema5_job_count": len(scoped),
        },
        "roles": roles,
        "ambiguous_tokens": ambiguous,
        "unmappable_job_ids": sorted(unmappable),
        "malformed_token_job_ids": sorted(malformed),
        "referenced_job_ids_absent_from_window": sorted(missing_referenced),
        "errors": errors,
        "passed": not errors,
    }
    return report


def _adopt_unique_intents(
    state_dir: Path,
    control: MutableMapping[str, Any],
    snapshot: SchedulerSnapshot,
) -> list[dict[str, Any]]:
    """Adopt jobs accepted between ``sbatch`` and durable job-ID commit."""
    adopted: list[dict[str, Any]] = []
    by_token: dict[str, list[SchedulerJob]] = {}
    for job in _scoped_control_jobs(snapshot):
        if job.token:
            by_token.setdefault(job.token, []).append(job)
    for role in ROLE_NAMES:
        role_state = control["controllers"][role]
        intent = role_state.get("submission_intent")
        if not isinstance(intent, dict) or intent.get("state") != "submitting":
            continue
        matches = by_token.get(str(intent.get("job_token", "")), [])
        active = [job for job in matches if job.active]
        if len(active) > 1:
            raise SchedulerAmbiguity(
                f"intent {intent.get('intent_token')} maps to multiple active jobs: "
                + ", ".join(job.job_id for job in active)
            )
        match = active[0] if active else (matches[-1] if len(matches) == 1 else None)
        if match is None:
            continue
        proof = _prove_exact_sbatch_and_release(
            state_dir,
            record=intent,
            job_id=match.job_id,
            submit_runner=_run_subprocess,
            release_after_proof=not bool(intent.get("hold", False)),
            now=float(snapshot.captured_at),
            scheduler_job=match,
        )
        intent.update(proof)
        _validate_exact_sbatch_record_proof(
            intent,
            job_id=match.job_id,
            context=f"controller intent {intent.get('intent_token')}",
        )
        intent["state"] = "submitted"
        intent["job_id"] = match.job_id
        intent["adopted_from_scheduler"] = True
        target = str(intent.get("target", "active"))
        if target not in {"active", "successor"}:
            raise ControlError(f"invalid controller intent target {target!r}")
        role_state[target] = copy.deepcopy(intent)
        adopted.append(
            {
                "role": role,
                "target": target,
                "job_id": match.job_id,
                "token": match.token,
            }
        )
    return adopted


def reconcile_control(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    all_jobs: bool,
    no_admit: bool,
    now: float | None = None,
) -> dict[str, Any]:
    timestamp = snapshot.captured_at if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        adopted = _adopt_unique_intents(state_dir, control, snapshot)
        report = build_reconciliation_report(
            control, snapshot, all_jobs=all_jobs, no_admit=no_admit
        )
        if adopted:
            report["adopted_intents"] = adopted
        _atomic_write_json(state_dir / RECONCILIATION_FILENAME, report)
        report_hash = sha256_file(state_dir / RECONCILIATION_FILENAME)
        control["last_reconciliation"] = {
            "passed": report["passed"],
            "evidence": str((state_dir / RECONCILIATION_FILENAME).resolve()),
            "sha256": report_hash,
            "at": report["captured_at"],
        }
        control["readiness"]["scheduler_reconciliation"] = {
            "passed": report["passed"],
            "evidence": str((state_dir / RECONCILIATION_FILENAME).resolve()),
            "sha256": report_hash,
            "attested_at": utc_timestamp(timestamp),
            "attested_timestamp": timestamp,
        }
        active_capacity = control["capacity"].get("active_transition")
        if (
            isinstance(active_capacity, dict)
            and active_capacity.get("phase") == "readiness_pending"
            and "scheduler_reconciliation"
            in active_capacity.get("invalidated_readiness", [])
        ):
            control["readiness"]["scheduler_reconciliation"][
                "capacity_generation"
            ] = int(active_capacity["to_generation"])
        append_transition(
            state_dir,
            control,
            event="scheduler_reconciled",
            details={
                "passed": report["passed"],
                "adopted": adopted,
                "errors": report["errors"],
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
    return report


def _controller_resource(control: Mapping[str, Any], role: str) -> dict[str, str]:
    _validate_role(role)
    return {
        # Controllers never issue scientific model requests.  Their durable successor
        # and cross-supervisor takeover protocols make preemption recoverable, while
        # placing either controller on the protected scientific-client placement would
        # silently consume capacity reserved for the 384 non-preemptible cell clients.
        "partition": PRODUCTION_CONTROLLER_PARTITION,
        "memory": "4G",
        "time_limit": "12:00:00",
    }


def validate_live_controller_placement(
    *,
    job_id: str,
    role: str,
    generation: int,
    intent_token: str,
    runner: Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None = None,
) -> dict[str, str]:
    """Verify the allocation landed on the controller-only partition.

    Rendering a single-partition directive is necessary but not sufficient evidence
    for the protected 384-client resource budget.  Reparse the live Slurm record
    before a controller may claim its role or launch a managed plane.  The
    controller's own preemption is recoverable through its exact successor/takeover
    state; it must never consume the protected scientific-client CPU or memory.
    """

    _validate_role(role)
    if not isinstance(job_id, str) or not job_id.isdigit():
        raise ControllerFenced("controller placement requires an exact numeric job ID")
    expected_comment = job_token(role, generation, intent_token)
    argv = ["scontrol", "show", "job", "-o", job_id]
    invoke = runner or _run_subprocess
    try:
        process = invoke(argv)
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise ControllerFenced(
            f"cannot verify live controller placement for {job_id}: {exc}"
        ) from exc
    if process.returncode != 0:
        raise ControllerFenced(
            "live controller placement query failed "
            f"rc={process.returncode}: {process.stderr.strip()[:500]}"
        )
    lines = [line.strip() for line in process.stdout.splitlines() if line.strip()]
    if len(lines) != 1:
        raise ControllerFenced(
            "live controller placement query must return exactly one record"
        )
    try:
        tokens = shlex.split(lines[0], posix=True)
    except (TypeError, ValueError) as exc:
        raise ControllerFenced(
            f"cannot parse live controller placement for {job_id}: {exc}"
        ) from exc
    fields: dict[str, str] = {}
    for token in tokens:
        if "=" not in token:
            continue
        key, value = token.split("=", 1)
        if not key or key in fields:
            raise ControllerFenced(
                f"live controller placement has duplicate field {key!r}"
            )
        fields[key] = value.strip('"')
    if (
        fields.get("JobId") != job_id
        or fields.get("Partition") != PRODUCTION_CONTROLLER_PARTITION
        or fields.get("Requeue") != "0"
        or fields.get("Comment") != expected_comment
        or normalize_scheduler_state(fields.get("JobState", ""))
        not in ACTIVE_SCHEDULER_STATES
    ):
        raise ControllerFenced(
            "controller scheduler placement/provenance drifted: "
            f"job={job_id}, role={role}, partition={fields.get('Partition')!r}, "
            f"requeue={fields.get('Requeue')!r}, state={fields.get('JobState')!r}"
        )
    return fields


def _runtime_environment_pins(control: Mapping[str, Any]) -> dict[str, dict[str, str]]:
    immutable = control["immutable"]
    return {
        role: {
            "prefix": str(immutable[f"{role}_environment_prefix"]),
            "manifest_path": str(immutable[f"{role}_environment_manifest_path"]),
            "manifest_sha256": str(immutable[f"{role}_environment_sha256"]),
        }
        for role in ("harness", "serving")
    }


def ensure_runtime_integrity_attestation(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    generation: int,
    force_full: bool,
    now: float | None = None,
) -> dict[str, Any]:
    """Create/verify the one full-inventory attestation for a rollout generation."""

    try:
        result = runtime_integrity.ensure_generation_attestation(
            state_dir=state_dir,
            generation=generation,
            release_id=str(control["immutable"]["release_id"]),
            release_bundle_id=str(control["immutable"]["release_bundle_id"]),
            immutable_pins_sha256=str(control["immutable_sha256"]),
            environment_pins=_runtime_environment_pins(control),
            force_full=force_full,
        )
    except runtime_integrity.RuntimeIntegrityError as exc:
        raise ImmutablePinError(f"runtime environment integrity failed: {exc}") from exc
    try:
        lease = runtime_integrity.refresh_generation_lease(
            state_dir=state_dir,
            attestation_path=Path(str(result["path"])),
            attestation_sha256=str(result["sha256"]),
            generation=generation,
            release_id=str(control["immutable"]["release_id"]),
            immutable_pins_sha256=str(control["immutable_sha256"]),
            expected_environment_hashes={
                role: str(control["immutable"][f"{role}_environment_sha256"])
                for role in ("harness", "serving")
            },
            expected_prefixes={
                role: str(control["immutable"][f"{role}_environment_prefix"])
                for role in ("harness", "serving")
            },
            now=now,
        )
    except runtime_integrity.RuntimeIntegrityError as exc:
        raise ImmutablePinError(f"runtime environment lease failed: {exc}") from exc
    return {
        "schema_version": runtime_integrity.ATTESTATION_SCHEMA_VERSION,
        "generation": generation,
        "path": str(result["path"]),
        "sha256": str(result["sha256"]),
        "attestation_id": str(result["record"]["attestation_id"]),
        "lease_path": str(lease["path"]),
    }


def ensure_snapshot_integrity_attestation(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    generation: int,
    validation_context: _SnapshotValidationContext,
) -> dict[str, Any]:
    """Seal one already-completed full snapshot validation for a rollout."""

    if not validation_context.full or len(validation_context.proofs) != 2:
        raise ReadinessError(
            "snapshot generation sealing requires one full validation of two snapshots"
        )
    gate = control["readiness"].get("snapshot", {})
    evidence = gate.get("evidence")
    evidence_sha256 = gate.get("sha256")
    if (
        not isinstance(evidence, str)
        or not Path(evidence).is_absolute()
        or not isinstance(evidence_sha256, str)
        or _SHA256_RE.fullmatch(evidence_sha256) is None
    ):
        raise ReadinessError("snapshot gate lacks checksummed evidence for sealing")
    try:
        sealed = snapshot_integrity.ensure_generation_seal(
            state_dir=state_dir,
            generation=generation,
            immutable_pins_sha256=str(control["immutable_sha256"]),
            snapshot_gate_evidence_path=Path(evidence),
            snapshot_gate_evidence_sha256=evidence_sha256,
            snapshots=list(validation_context.proofs.values()),
            sealed_members=list(validation_context.members.values()),
            metadata_entries=list(validation_context.metadata.values()),
        )
        lease = snapshot_integrity.refresh_generation_lease(
            state_dir=state_dir,
            seal_path=Path(str(sealed["path"])),
            seal_sha256=str(sealed["sha256"]),
            generation=generation,
            immutable_pins_sha256=str(control["immutable_sha256"]),
            # Lease time is an actual filesystem-observation time, not the optional
            # transaction timestamp used by deterministic controller tests/logs.
            now=None,
            force=True,
        )
    except snapshot_integrity.SnapshotIntegrityError as exc:
        raise ReadinessError(f"snapshot generation sealing failed: {exc}") from exc
    return {
        "schema_version": snapshot_integrity.SEAL_SCHEMA_VERSION,
        "generation": generation,
        "path": str(sealed["path"]),
        "sha256": str(sealed["sha256"]),
        "seal_id": str(sealed["record"]["seal_id"]),
        "lease_path": str(lease["path"]),
        "member_bindings": {},
    }


def prepare_snapshot_integrity_preseal(
    state_dir: Path,
    *,
    evidence_path: Path,
    evidence_sha256: str,
    validation_context: _SnapshotValidationContext,
    now: float | None = None,
) -> dict[str, Any]:
    """Persist the initial full proof for the paused control's next generation.

    The snapshot readiness builder has already performed the expensive validation on
    its marker-last candidate.  Publishing this preseal after the candidate is renamed
    lets the subsequent ``attest`` command and all other readiness builders reuse that
    proof instead of re-reading ~96 GiB.  Admission remains disabled and the seal is
    not authoritative until the snapshot gate binds the same evidence hash.
    """

    timestamp = time.time() if now is None else float(now)
    evidence = evidence_path.expanduser().resolve()
    if sha256_file(evidence) != evidence_sha256:
        raise ReadinessError("snapshot preseal evidence changed before publication")
    with control_lock(state_dir):
        current = load_control(state_dir)
        if current["desired_state"] != "paused" or current.get("drain_requested"):
            raise ReadinessError("snapshot preseal requires paused, non-draining control")
        target_generation = int(current["rollout_generation"]) + 1
        existing = current.get(SNAPSHOT_ATTESTATION_STATE_KEY)
        if isinstance(existing, dict):
            seal = validate_snapshot_integrity_attestation(
                current, state_dir=state_dir, verify_lease=False
            )
            if (
                existing.get("generation") != target_generation
                or seal.get("snapshot_gate_evidence_path") != str(evidence)
                or seal.get("snapshot_gate_evidence_sha256") != evidence_sha256
            ):
                raise ReadinessError("existing snapshot preseal binds different evidence")
            refresh_snapshot_integrity_lease(state_dir, current)
            return copy.deepcopy(existing)
        projected = copy.deepcopy(current)
        projected["readiness"]["snapshot"] = {
            "passed": True,
            "evidence": str(evidence),
            "sha256": evidence_sha256,
            "attested_at": utc_timestamp(timestamp),
            "attested_timestamp": timestamp,
        }
        record = ensure_snapshot_integrity_attestation(
            state_dir,
            projected,
            generation=target_generation,
            validation_context=validation_context,
        )
        current[SNAPSHOT_ATTESTATION_STATE_KEY] = record
        append_transition(
            state_dir,
            current,
            event="snapshot_integrity_presealed",
            details={
                "generation": target_generation,
                "evidence": str(evidence),
                "sha256": evidence_sha256,
                "seal_id": record["seal_id"],
            },
            now=timestamp,
        )
        _save_control(state_dir, current, now=timestamp)
        return copy.deepcopy(record)


def validate_snapshot_integrity_attestation(
    control: Mapping[str, Any], *, state_dir: Path, verify_lease: bool
) -> dict[str, Any]:
    """Validate the compact rollout seal and, on hot paths, its bounded lease."""

    record = control.get(SNAPSHOT_ATTESTATION_STATE_KEY)
    generation = int(control.get("rollout_generation", 0))
    required = {
        "schema_version",
        "generation",
        "path",
        "sha256",
        "seal_id",
        "lease_path",
        "member_bindings",
    }
    if (
        not isinstance(record, dict)
        or set(record) != required
        or record.get("schema_version") != snapshot_integrity.SEAL_SCHEMA_VERSION
        or record.get("generation")
        != (
            generation
            if generation >= 1
            else generation + 1
        )
        or not isinstance(record.get("path"), str)
        or not isinstance(record.get("sha256"), str)
        or not isinstance(record.get("lease_path"), str)
        or not isinstance(record.get("member_bindings"), dict)
    ):
        raise ReadinessError("control snapshot integrity seal is malformed")
    resolved_state = Path(state_dir).expanduser().resolve()
    record_generation = int(record["generation"])
    expected_seal_path = (
        resolved_state
        / "snapshot_integrity"
        / f"snapshot.g{record_generation:06d}.json"
    )
    expected_lease_path = snapshot_integrity.generation_lease_path(
        resolved_state, record_generation
    ).resolve()
    if (
        Path(str(record["path"])).expanduser().resolve() != expected_seal_path
        or Path(str(record["lease_path"])).expanduser().resolve()
        != expected_lease_path
        or str(record["path"]) != str(expected_seal_path)
        or str(record["lease_path"]) != str(expected_lease_path)
    ):
        raise ReadinessError(
            "control snapshot integrity seal/lease path escapes its state generation"
        )
    try:
        seal = snapshot_integrity.verify_generation_seal(
            path=Path(record["path"]),
            expected_sha256=str(record["sha256"]),
            generation=int(record["generation"]),
            immutable_pins_sha256=str(control["immutable_sha256"]),
        )
        if verify_lease:
            snapshot_integrity.verify_generation_lease(
                lease_path=Path(record["lease_path"]),
                seal_path=Path(record["path"]),
                seal_sha256=str(record["sha256"]),
                generation=int(record["generation"]),
                immutable_pins_sha256=str(control["immutable_sha256"]),
            )
    except snapshot_integrity.SnapshotIntegrityError as exc:
        raise ReadinessError(f"snapshot integrity validation failed: {exc}") from exc
    gate = control.get("readiness", {}).get("snapshot", {})
    if seal.get("seal_id") != record.get("seal_id"):
        raise ReadinessError("control snapshot seal ID drifted")
    if gate.get("passed") is True and (
        seal.get("snapshot_gate_evidence_path") != gate.get("evidence")
        or seal.get("snapshot_gate_evidence_sha256") != gate.get("sha256")
    ):
        raise ReadinessError("control snapshot seal differs from snapshot gate evidence")
    snapshot_id_by_root = {
        str(row["snapshot_root"]): str(row["snapshot_id"])
        for row in seal.get("snapshots", [])
        if isinstance(row, dict)
    }
    for bound_gate, binding in record["member_bindings"].items():
        readiness_gate = control.get("readiness", {}).get(bound_gate, {})
        if (
            bound_gate not in REQUIRED_GATES
            or not isinstance(binding, dict)
            or set(binding) != {"evidence_sha256", "members"}
            or binding.get("evidence_sha256") != readiness_gate.get("sha256")
            or readiness_gate.get("passed") is not True
            or not isinstance(binding.get("members"), list)
        ):
            raise ReadinessError("control snapshot member binding is malformed or stale")
        seen: set[tuple[str, str]] = set()
        for member in binding["members"]:
            if (
                not isinstance(member, dict)
                or set(member)
                != {"snapshot_id", "snapshot_root", "logical_path", "sha256"}
                or snapshot_id_by_root.get(str(member.get("snapshot_root")))
                != member.get("snapshot_id")
                or _SHA256_RE.fullmatch(str(member.get("sha256", ""))) is None
                or not isinstance(member.get("logical_path"), str)
                or not member["logical_path"]
            ):
                raise ReadinessError("control snapshot member binding row is invalid")
            key = (str(member["snapshot_root"]), str(member["logical_path"]))
            if key in seen:
                raise ReadinessError("control snapshot member binding repeats a path")
            seen.add(key)
    return seal


def refresh_snapshot_integrity_lease(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    now: float | None = None,
) -> dict[str, Any]:
    """Centrally metadata-scan snapshots at most once per five-minute interval."""

    validate_snapshot_integrity_attestation(
        control, state_dir=state_dir, verify_lease=False
    )
    record = control[SNAPSHOT_ATTESTATION_STATE_KEY]
    try:
        return snapshot_integrity.refresh_generation_lease(
            state_dir=state_dir,
            seal_path=Path(str(record["path"])),
            seal_sha256=str(record["sha256"]),
            generation=int(record["generation"]),
            immutable_pins_sha256=str(control["immutable_sha256"]),
            now=now,
        )
    except snapshot_integrity.SnapshotIntegrityError as exc:
        raise ReadinessError(f"snapshot integrity lease refresh failed: {exc}") from exc


def _start_snapshot_lease_refresh(
    state_dir: Path,
    control: Mapping[str, Any],
) -> _SnapshotLeaseRefreshTask:
    """Start one daemon renewal without blocking the controller heartbeat loop.

    ``refresh_generation_lease`` retains the cross-node singleton lock and five-minute
    cache.  The thread only removes filesystem latency and lock wait from the controller
    liveness path; it does not permit a second local renewal while its task is retained.
    Production intentionally supplies no synthetic timestamp so the lease reflects an
    actual filesystem observation.
    """

    future: Future[dict[str, Any]] = Future()
    frozen_control = copy.deepcopy(dict(control))

    def renew() -> None:
        try:
            result = refresh_snapshot_integrity_lease(
                state_dir,
                frozen_control,
                now=None,
            )
        except BaseException as exc:  # preserve every worker failure for the owner
            future.set_exception(exc)
        else:
            future.set_result(result)

    thread = threading.Thread(
        target=renew,
        name=(
            "schema5-snapshot-lease-"
            f"g{int(control.get('rollout_generation', 0)):06d}"
        ),
        daemon=True,
    )
    thread.start()
    return _SnapshotLeaseRefreshTask(future=future, thread=thread)


def _await_snapshot_lease_refresh_with_heartbeats(
    task: _SnapshotLeaseRefreshTask,
    *,
    state_dir: Path,
    role: str,
    generation: int,
    intent_token: str,
    job_id: str,
    heartbeat_interval: float,
) -> dict[str, Any]:
    """Wait for startup renewal while proving the exact controller remains alive."""

    if heartbeat_interval <= 0:
        raise ControlError("snapshot renewal heartbeat interval must be positive")
    # The prior operation (notably runtime-environment validation) may itself have used
    # most of an interval.  Heartbeat immediately, then at every timeout until renewal
    # completes.  ``heartbeat_controller`` rechecks the fenced role identity each time.
    heartbeat_controller(
        state_dir,
        role=role,
        generation=generation,
        intent_token=intent_token,
        job_id=job_id,
        now=time.time(),
    )
    while True:
        try:
            # Half-interval waits leave headroom for control-lock and shared-filesystem
            # latency inside the heartbeat write itself while preserving the advertised
            # maximum cadence.
            return task.future.result(timeout=heartbeat_interval / 2.0)
        except FutureTimeoutError:
            heartbeat_controller(
                state_dir,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                now=time.time(),
            )


def validate_runtime_integrity_attestation(
    control: Mapping[str, Any], *, verify_metadata: bool
) -> dict[str, Any]:
    """Validate the control-bound attestation without ever refreshing drift."""

    record = control.get(RUNTIME_ATTESTATION_STATE_KEY)
    generation = int(control.get("rollout_generation", 0))
    if not isinstance(record, dict):
        raise ImmutablePinError("control lacks a runtime integrity attestation")
    required = {
        "schema_version",
        "generation",
        "path",
        "sha256",
        "attestation_id",
        "lease_path",
    }
    if (
        set(record) != required
        or record.get("schema_version") != runtime_integrity.ATTESTATION_SCHEMA_VERSION
        or record.get("generation") != generation
        or not isinstance(record.get("path"), str)
        or not isinstance(record.get("sha256"), str)
    ):
        raise ImmutablePinError("control runtime integrity attestation is malformed")
    immutable = control["immutable"]
    try:
        attestation = runtime_integrity.verify_generation_attestation(
            path=Path(record["path"]),
            expected_sha256=str(record["sha256"]),
            generation=generation,
            release_id=str(immutable["release_id"]),
            immutable_pins_sha256=str(control["immutable_sha256"]),
            expected_environment_hashes={
                role: str(immutable[f"{role}_environment_sha256"])
                for role in ("harness", "serving")
            },
            expected_prefixes={
                role: str(immutable[f"{role}_environment_prefix"])
                for role in ("harness", "serving")
            },
            verify_metadata=False,
        )
    except runtime_integrity.RuntimeIntegrityError as exc:
        raise ImmutablePinError(f"runtime environment integrity failed: {exc}") from exc
    if attestation.get("attestation_id") != record.get("attestation_id"):
        raise ImmutablePinError("control runtime attestation ID drifted")
    if attestation.get("release_bundle_id") != immutable["release_bundle_id"]:
        raise ImmutablePinError("control runtime attestation release bundle drifted")
    if verify_metadata:
        try:
            runtime_integrity.verify_generation_lease(
                lease_path=Path(str(record["lease_path"])),
                attestation_path=Path(str(record["path"])),
                attestation_sha256=str(record["sha256"]),
                generation=generation,
                release_id=str(immutable["release_id"]),
                immutable_pins_sha256=str(control["immutable_sha256"]),
                expected_environment_hashes={
                    role: str(immutable[f"{role}_environment_sha256"])
                    for role in ("harness", "serving")
                },
                expected_prefixes={
                    role: str(immutable[f"{role}_environment_prefix"])
                    for role in ("harness", "serving")
                },
            )
        except runtime_integrity.RuntimeIntegrityError as exc:
            raise ImmutablePinError(f"runtime environment lease failed: {exc}") from exc
    return copy.deepcopy(record)


def refresh_runtime_integrity_lease(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    now: float | None = None,
) -> dict[str, Any]:
    """Run the centralized metadata scan only when the five-minute lease is due."""

    record = validate_runtime_integrity_attestation(control, verify_metadata=False)
    immutable = control["immutable"]
    try:
        return runtime_integrity.refresh_generation_lease(
            state_dir=state_dir,
            attestation_path=Path(str(record["path"])),
            attestation_sha256=str(record["sha256"]),
            generation=int(control["rollout_generation"]),
            release_id=str(immutable["release_id"]),
            immutable_pins_sha256=str(control["immutable_sha256"]),
            expected_environment_hashes={
                role: str(immutable[f"{role}_environment_sha256"])
                for role in ("harness", "serving")
            },
            expected_prefixes={
                role: str(immutable[f"{role}_environment_prefix"])
                for role in ("harness", "serving")
            },
            now=now,
        )
    except runtime_integrity.RuntimeIntegrityError as exc:
        raise ImmutablePinError(f"runtime environment lease refresh failed: {exc}") from exc


def _start_runtime_lease_refresh(
    state_dir: Path,
    control: Mapping[str, Any],
) -> _RuntimeLeaseRefreshTask:
    """Start one daemon renewal without blocking controller heartbeats.

    ``refresh_generation_lease`` still owns the cross-node singleton lock and its
    five-minute cache.  Retaining the returned task prevents a controller from
    starting a second local renewal while metadata verification or lock acquisition
    is still in progress.  Production deliberately uses the observation time from
    inside the renewal rather than a timestamp captured before a possible stall.
    """

    future: Future[dict[str, Any]] = Future()
    frozen_control = copy.deepcopy(dict(control))

    def renew() -> None:
        try:
            result = refresh_runtime_integrity_lease(
                state_dir,
                frozen_control,
                now=None,
            )
        except BaseException as exc:  # preserve every worker failure for the owner
            future.set_exception(exc)
        else:
            future.set_result(result)

    thread = threading.Thread(
        target=renew,
        name=(
            "schema5-runtime-lease-"
            f"g{int(control.get('rollout_generation', 0)):06d}"
        ),
        daemon=True,
    )
    thread.start()
    return _RuntimeLeaseRefreshTask(future=future, thread=thread)


def _await_runtime_lease_refresh_with_heartbeats(
    task: _RuntimeLeaseRefreshTask,
    *,
    state_dir: Path,
    role: str,
    generation: int,
    intent_token: str,
    job_id: str,
    heartbeat_interval: float,
) -> dict[str, Any]:
    """Wait for startup renewal while proving the exact controller remains alive."""

    if heartbeat_interval <= 0:
        raise ControlError("runtime renewal heartbeat interval must be positive")
    # Callers fence and heartbeat immediately before starting the task.  Heartbeat
    # again here so this helper is safe on its own, then at half-interval while the
    # cross-node lock or metadata scan remains stalled.
    heartbeat_controller(
        state_dir,
        role=role,
        generation=generation,
        intent_token=intent_token,
        job_id=job_id,
        now=time.time(),
    )
    while True:
        try:
            return task.future.result(timeout=heartbeat_interval / 2.0)
        except FutureTimeoutError:
            heartbeat_controller(
                state_dir,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                now=time.time(),
            )


def fleet_scheduler_policy_binding(
    control: Mapping[str, Any],
    *,
    require_attested: bool,
) -> dict[str, Any] | None:
    """Return the stable scheduler contract sealed by fleet readiness.

    The timestamp-addressed scheduler evidence and policy instance are retained for
    audit, while long-running supervisors compare only ``policy_contract_id``.  This
    allows a fresh capture each tick without treating its timestamp as policy drift.
    """

    gate = control.get("readiness", {}).get("fleet")
    if not isinstance(gate, Mapping) or gate.get("passed") is not True:
        if require_attested:
            raise ReadinessError(
                "production requires attested fleet scheduler policy"
            )
        return None
    fields = {
        "scheduler_safety_evidence_id",
        "scheduler_safety_policy_id",
        "scheduler_safety_policy_contract_id",
        "transport_uncertainty_binding_sha256",
        "transport_censor_protocol_version",
        "transport_censor_protocol_hash",
    }
    if any(field not in gate for field in fields):
        raise ReadinessError(
            "fleet readiness lacks its scheduler/transport binding"
        )
    for field in (
        "scheduler_safety_evidence_id",
        "scheduler_safety_policy_id",
        "scheduler_safety_policy_contract_id",
        "transport_uncertainty_binding_sha256",
        "transport_censor_protocol_hash",
    ):
        if _SHA256_RE.fullmatch(str(gate.get(field, ""))) is None:
            raise ReadinessError(
                f"fleet readiness has invalid {field}"
            )
    immutable = control["immutable"]
    transport = immutable["transport_uncertainty_binding"]
    if (
        gate["transport_uncertainty_binding_sha256"]
        != immutable["transport_uncertainty_binding_sha256"]
        or gate["transport_censor_protocol_version"]
        != transport["transport_censor_protocol_version"]
        or gate["transport_censor_protocol_hash"]
        != transport["transport_censor_protocol_hash"]
    ):
        raise ReadinessError(
            "fleet readiness transport binding differs from immutable release"
        )
    return {field: gate[field] for field in sorted(fields)}


def production_environment(
    control: Mapping[str, Any], *, run_id: str | None = None
) -> dict[str, str]:
    """Return the exact provenance environment for controllers or one cell batch.

    The narrow dispatcher integration should call this function immediately before
    rendering a batch.  Supplying ``run_id`` adds the immutable per-run policy digest;
    multi-run arrays must instead be split by run so every worker receives one policy.
    """
    immutable = control["immutable"]
    fleet = effective_fleet_contract_binding(control, verify_files=True)
    capacity_authority = effective_protected_capacity_binding(
        control, verify_files=True
    )
    attestation = (
        validate_runtime_integrity_attestation(control, verify_metadata=False)
        if int(control.get("rollout_generation", 0)) >= 1
        else None
    )
    environment = {
        "ASYS_RELEASE_ID": str(immutable["release_id"]),
        "ASYS_RELEASE_GIT_COMMIT": str(immutable["git_commit"]),
        "ASYS_PROTECTED_CAPACITY_MARKER": str(
            capacity_authority["path"]
        ),
        "ASYS_PROTECTED_CAPACITY_MARKER_SHA256": str(
            capacity_authority["sha256"]
        ),
        "ASYS_PROTECTED_CAPACITY_MARKER_ID": str(
            capacity_authority["marker_id"]
        ),
        "ASYS_TRANSPORT_CENSOR_PROTOCOL_VERSION": str(
            immutable["transport_uncertainty_binding"][
                "transport_censor_protocol_version"
            ]
        ),
        "ASYS_TRANSPORT_CENSOR_PROTOCOL_HASH": str(
            immutable["transport_uncertainty_binding"][
                "transport_censor_protocol_hash"
            ]
        ),
        "ASYS_TRANSPORT_UNCERTAINTY_BINDING_SHA256": str(
            immutable["transport_uncertainty_binding_sha256"]
        ),
        "ASYS_CHECKPOINT_SCHEMA_VERSION": str(
            immutable["transport_uncertainty_binding"][
                "checkpoint_schema_version"
            ]
        ),
        "ASYS_ARTIFACT_SCHEMA_VERSION": str(
            immutable["transport_uncertainty_binding"][
                "artifact_schema_version"
            ]
        ),
        "ASYS_SELF_CONSISTENCY_PROTOCOL_VERSION": str(
            immutable["transport_uncertainty_binding"][
                "self_consistency_protocol_version"
            ]
        ),
        "ASYS_SELF_CONSISTENCY_PROTOCOL_HASH": str(
            immutable["transport_uncertainty_binding"][
                "self_consistency_protocol_hash"
            ]
        ),
        "ASYS_MODEL_CONTRACT_SHA256": str(immutable["model_contract_sha256"]),
        "ASYS_FLEET_CONTRACT_SHA256": str(fleet["sha256"]),
        "ASYS_FLEET_CONTRACT_PATH": str(fleet["path"]),
        "ASYS_RELEASE_FLEET_CONTRACT_SHA256": str(
            immutable["fleet_contract_sha256"]
        ),
        "ASYS_CAPACITY_GENERATION": str(fleet["capacity_generation"]),
        "ASYS_HARNESS_ENVIRONMENT_SHA256": str(immutable["harness_environment_sha256"]),
        "ASYS_SERVING_ENVIRONMENT_SHA256": str(immutable["serving_environment_sha256"]),
        "ASYS_ROLLOUT_GENERATION": str(control["rollout_generation"]),
        "ASYS_IMMUTABLE_PINS_SHA256": str(control["immutable_sha256"]),
        "HF_HUB_OFFLINE": "1",
        "TRANSFORMERS_OFFLINE": "1",
        "HF_DATASETS_OFFLINE": "1",
    }
    scheduler_binding = fleet_scheduler_policy_binding(
        control, require_attested=False
    )
    if scheduler_binding is not None:
        environment.update(
            {
                "ASYS_SCHEDULER_POLICY_CONTRACT_ID": str(
                    scheduler_binding[
                        "scheduler_safety_policy_contract_id"
                    ]
                ),
                "ASYS_SCHEDULER_SAFETY_EVIDENCE_ID": str(
                    scheduler_binding["scheduler_safety_evidence_id"]
                ),
                "ASYS_SCHEDULER_SAFETY_POLICY_ID": str(
                    scheduler_binding["scheduler_safety_policy_id"]
                ),
            }
        )
    if attestation is not None:
        environment.update(
            {
                "ASYS_RUNTIME_ATTESTATION": str(attestation["path"]),
                "ASYS_RUNTIME_ATTESTATION_SHA256": str(attestation["sha256"]),
                "ASYS_RUNTIME_INTEGRITY_LEASE": str(attestation["lease_path"]),
            }
        )
    if run_id is not None:
        matches = [run for run in immutable["runs"] if run["run_id"] == run_id]
        if len(matches) != 1:
            raise ImmutablePinError(f"run {run_id!r} is not uniquely pinned by control")
        environment["ASYS_ARTIFACT_POLICY_SHA256"] = str(matches[0]["policy_sha256"])
    return environment


def _require_production_running(control: Mapping[str, Any]) -> None:
    """Fence every admission-facing hook until transactional resume is complete."""

    if control.get("desired_state") != "running" or control.get("drain_requested"):
        raise ControlError("schema-5 admission is disabled by desired state")
    if control.get("finalization", {}).get("state") != "idle":
        raise ControlError("schema-5 admission is disabled by autonomous finalization")
    intent = control.get("resume_intent")
    if not isinstance(intent, dict) or intent.get("state") != "complete":
        raise ControlError(
            "schema-5 admission is disabled by incomplete resume transaction"
        )
    try:
        _validate_production_authorization_state(
            control,
            state_dir=(
                Path(str(control["immutable"]["results_root"]))
                / CONTROL_STATE_DIRNAME
            ),
            require_passed=True,
            verify_files=False,
        )
        _validate_resume_production_authorizations(control)
    except ReadinessError as exc:
        raise ControlError(
            f"schema-5 admission is disabled by production authorization: {exc}"
        ) from exc
    controller_ids = intent.get("controller_job_ids")
    if (
        not isinstance(controller_ids, dict)
        or set(controller_ids) != set(ROLE_NAMES)
        or not all(str(controller_ids[role]).isdigit() for role in ROLE_NAMES)
        or intent.get("scheduler_visible_job_ids") != controller_ids
    ):
        raise ControlError(
            "schema-5 admission is disabled without both controller chains"
        )
    for role in ROLE_NAMES:
        active = control["controllers"][role].get("active")
        if not isinstance(active, dict) or not str(active.get("job_id", "")):
            raise ControlError(
                f"schema-5 admission is disabled without a current {role} controller"
            )


def production_environment_from_state(
    state_dir: Path, *, run_id: str | None = None, require_running: bool = True
) -> dict[str, str]:
    """Fail-closed public hook for dispatcher batch rendering."""
    control = load_control(state_dir, verify_files=True)
    if require_running:
        _require_production_running(control)
        validate_readiness(control, state_dir=state_dir, verify_files=True)
    return production_environment(control, run_id=run_id)


def production_cell_execution(control: Mapping[str, Any]) -> dict[str, str]:
    """Return the only interpreter and release entry point allowed for cell arrays.

    Provenance fields in result metadata are not sufficient if Slurm first starts the
    worker from an ambient Conda environment or a mutable checkout.  This contract is
    deliberately path-addressed: the array invokes the frozen harness Python directly,
    and that process verifies both ``sys.prefix`` and the executing dispatcher source
    root before it is allowed to mutate a cell.
    """

    immutable = control["immutable"]
    harness_prefix = (
        Path(str(immutable["harness_environment_prefix"])).expanduser().resolve()
    )
    release_worktree = Path(str(immutable["release_worktree"])).expanduser().resolve()
    hf_home = Path(str(immutable["hf_home"])).expanduser().resolve()
    python_path = (harness_prefix / "bin" / "python").resolve()
    dispatcher_script = (release_worktree / "slurm" / "dispatch_sweeps.py").resolve()
    batch_template = (
        release_worktree / "slurm" / "run_dispatch_batch.sbatch.tmpl"
    ).resolve()
    if not hf_home.is_dir():
        raise ImmutablePinError(f"pinned Hugging Face home is missing: {hf_home}")
    for label, path in (
        ("pinned harness Python", python_path),
        ("pinned release dispatcher", dispatcher_script),
        ("pinned release cell template", batch_template),
    ):
        if not path.is_file():
            raise ImmutablePinError(f"{label} is missing: {path}")
    try:
        dispatcher_script.relative_to(release_worktree)
        batch_template.relative_to(release_worktree)
    except ValueError as exc:
        raise ImmutablePinError(
            "production cell runtime resolves outside the frozen release worktree"
        ) from exc
    try:
        python_path.relative_to(harness_prefix)
    except ValueError as exc:
        raise ImmutablePinError(
            "production cell interpreter resolves outside the frozen harness prefix"
        ) from exc
    unsafe_environment_paths = {
        label: str(path)
        for label, path in (
            ("release worktree", release_worktree),
            ("Hugging Face home", hf_home),
        )
        if any(
            character in str(path) for character in ('"', "\\", "$", "`", "\n", "\r")
        )
    }
    if unsafe_environment_paths:
        raise ImmutablePinError(
            "production environment paths are unsafe for exact shell export: "
            + ", ".join(sorted(unsafe_environment_paths))
        )
    return {
        "harness_prefix": str(harness_prefix),
        "python": str(python_path),
        "release_worktree": str(release_worktree),
        "hf_home": str(hf_home),
        "dispatcher_script": str(dispatcher_script),
        "batch_template": str(batch_template),
    }


def production_cell_execution_from_state(
    state_dir: Path, *, require_running: bool = True
) -> dict[str, str]:
    """Fail-closed public hook used when rendering a schema-5 cell array."""

    control = load_control(state_dir, verify_files=True)
    if require_running:
        _require_production_running(control)
        validate_readiness(control, state_dir=state_dir, verify_files=True)
    return production_cell_execution(control)


def admission_contract_from_state(state_dir: Path) -> dict[str, Any]:
    """Return the live, fail-closed admission contract for one dispatcher poll."""
    control = load_control(state_dir, verify_files=True)
    _require_production_running(control)
    validate_readiness(control, state_dir=state_dir, verify_files=True)
    admission = copy.deepcopy(control["admission"])
    configured_ceiling = int(admission["current_ceiling"])
    safety_hold = copy.deepcopy(control["admission_safety_hold"])
    if control["desired_state"] == "running":
        drain_intent = control.get("safety_hold_drain_intent")
        if safety_hold["active"] and not (
            _safety_hold_drain_complete_for_current_activation(control)
        ):
            raise ControlError(
                "running admission safety hold lacks a complete exact "
                "activation/generation cell drain"
            )
        if (
            not safety_hold["active"]
            and isinstance(drain_intent, Mapping)
            and drain_intent.get("rollout_generation")
            == control["rollout_generation"]
            and drain_intent.get("state") != "complete"
        ):
            raise ControlError(
                "running admission retains an unresolved recent safety-hold drain"
            )
    active_critical_alerts = sorted(
        set(_active_critical_alerts(control))
        | set(_active_critical_alerts_from_journal(state_dir))
    )
    admission["configured_ceiling"] = configured_ceiling
    admission["current_ceiling"] = (
        0
        if (
            safety_hold["active"]
            or active_critical_alerts
            or control["finalization"]["state"] != "idle"
        )
        else configured_ceiling
    )
    client_capacity = _client_capacity_contract_summary(
        control,
        target_ceiling=configured_ceiling,
        state_dir=state_dir,
        verify_files=True,
    )
    try:
        capacity_authority = effective_protected_capacity_binding(
            control, verify_files=True
        )
        capacity_contract = _load_protected_capacity_contract(
            control,
            path=capacity_authority["path"],
            expected_marker_id=str(capacity_authority["marker_id"]),
            expected_sha256=str(capacity_authority["sha256"]),
        )
        protected_capacity.authorize_client(
            capacity_contract,
            partition=str(client_capacity["partition"]),
            qos=str(client_capacity["qos"]),
            required_slots=configured_ceiling,
            required_reserve_jobs=int(admission["reserve"]),
        )
    except protected_capacity.ProtectedCapacityError as exc:
        raise ControlError(
            f"scientific client placement is outside protected capacity: {exc}"
        ) from exc
    return {
        **admission,
        "client_capacity": client_capacity,
        "safety_hold": safety_hold,
        "safety_hold_drain": copy.deepcopy(
            control.get("safety_hold_drain_intent")
        ),
        "active_critical_alerts": active_critical_alerts,
        "capacity_generation": int(control["capacity"]["current_generation"]),
        "rollout_generation": control["rollout_generation"],
        "immutable_sha256": control["immutable_sha256"],
        "protected_capacity": {
            "path": str(capacity_contract.path),
            "sha256": capacity_contract.sha256,
            "marker_id": capacity_contract.marker_id,
        },
    }


def client_capacity_contract_from_state(state_dir: Path) -> dict[str, Any]:
    """Reverify and expose the placement/TRES authority for the configured stage."""

    control = load_control(state_dir, verify_files=True)
    return _client_capacity_contract_summary(
        control,
        target_ceiling=int(control["admission"]["current_ceiling"]),
        state_dir=state_dir,
        verify_files=True,
    )


def validate_production_batch_sbatch(
    control: Mapping[str, Any], *, payload: str, task_count: int
) -> None:
    """Reject a rendered cell array that weakens any production resource invariant."""
    if task_count < 1 or task_count > int(control["admission"]["max_batch"]):
        raise ControlError(
            f"production array task count {task_count} exceeds 1..{control['admission']['max_batch']}"
        )
    required_directives = {
        "#SBATCH --cpus-per-task=1",
        "#SBATCH --mem=4G",
        "#SBATCH --time=12:00:00",
        "#SBATCH --signal=B:USR1@1200",
        "#SBATCH --no-requeue",
        "#SBATCH --export=NONE",
    }
    stripped_lines = [line.strip() for line in payload.splitlines()]
    lines = set(stripped_lines)
    missing = sorted(required_directives - lines)
    if missing:
        raise ControlError(
            "rendered production cell batch weakens required Slurm contract; missing "
            + ", ".join(missing)
        )
    _validate_trusted_sbatch_bootstrap(
        payload, description="production cell batch"
    )
    partitions = [
        line for line in stripped_lines if line.startswith("#SBATCH --partition=")
    ]
    configured_ceiling = int(control["admission"]["current_ceiling"])
    client_capacity = _client_capacity_contract_summary(
        control,
        target_ceiling=configured_ceiling,
        verify_files=False,
    )
    expected_partition = str(client_capacity["partition"])
    if partitions != [f"#SBATCH --partition={expected_partition}"]:
        raise ControlError(
            "rendered production cell batch must use exactly one non-preemptible "
            f"{expected_partition} partition directive authorized for ceiling "
            f"{configured_ceiling}"
        )
    qoses = [
        line for line in stripped_lines if line.startswith("#SBATCH --qos=")
    ]
    expected_qos = str(client_capacity["qos"])
    if qoses != [f"#SBATCH --qos={expected_qos}"]:
        raise ControlError(
            "rendered production cell batch must use exactly one protected "
            f"{expected_qos} QOS directive"
        )
    manifest_hash_arguments = [
        line
        for line in stripped_lines
        if line.startswith("--batch-manifest-sha256 ")
    ]
    if len(manifest_hash_arguments) != 1 or re.fullmatch(
        r'--batch-manifest-sha256 "[0-9a-f]{64}" \\',
        manifest_hash_arguments[0],
    ) is None:
        raise ControlError(
            "rendered production cell batch lacks one exact manifest digest"
        )
    arrays = [line for line in lines if line.startswith("#SBATCH --array=")]
    if len(arrays) != 1:
        raise ControlError(
            "rendered production cell batch must contain exactly one array"
        )
    range_text = arrays[0].split("=", 1)[1].split("%", 1)[0]
    try:
        first_text, last_text = range_text.split("-", 1)
        first, last = int(first_text), int(last_text)
    except (ValueError, TypeError) as exc:
        raise ControlError(f"invalid production array range {range_text!r}") from exc
    if first != 0 or last + 1 != task_count:
        raise ControlError(
            f"production array range {range_text!r} does not encode {task_count} tasks"
        )

    execution = production_cell_execution(control)
    required_fragments = {
        "exact pinned cell entry point": (
            "exec "
            + shlex.quote(execution["python"])
            + " -u "
            + shlex.quote(execution["dispatcher_script"])
            + " run-task"
        ),
        "runtime release verification": (
            "--expected-release-root " + shlex.quote(execution["release_worktree"])
        ),
        "runtime harness verification": (
            "--expected-harness-prefix " + shlex.quote(execution["harness_prefix"])
        ),
        "ambient Python/Conda sanitization": (
            "unset PYTHONHOME PYTHONPATH VIRTUAL_ENV CONDA_PREFIX CONDA_DEFAULT_ENV"
        ),
        "bytecode isolation": "export PYTHONDONTWRITEBYTECODE=1",
        "user-site isolation": "export PYTHONNOUSERSITE=1",
        "safe import path": "export PYTHONSAFEPATH=1",
        "offline Hugging Face": "export HF_HUB_OFFLINE=1",
        "offline Transformers": "export TRANSFORMERS_OFFLINE=1",
        "offline datasets": "export HF_DATASETS_OFFLINE=1",
    }
    required_exact_exports = {
        "exact pinned Hugging Face home": f'export HF_HOME="{execution["hf_home"]}"',
        "exact pinned release worktree": (
            f'export ASYS_RELEASE_WORKTREE="{execution["release_worktree"]}"'
        ),
    }
    absent = [
        label
        for label, fragment in required_fragments.items()
        if fragment not in payload
    ]
    absent.extend(
        label for label, line in required_exact_exports.items() if line not in lines
    )
    for variable, expected_line in (
        ("HF_HOME", required_exact_exports["exact pinned Hugging Face home"]),
        (
            "ASYS_RELEASE_WORKTREE",
            required_exact_exports["exact pinned release worktree"],
        ),
    ):
        assignments = [
            line
            for line in stripped_lines
            if line.startswith((f"export {variable}=", f"{variable}="))
        ]
        if assignments != [expected_line]:
            absent.append(f"single exact {variable} assignment")
    if absent:
        raise ControlError(
            "rendered production cell batch lacks immutable runtime contract: "
            + ", ".join(sorted(absent))
        )
    forbidden_fragments = (
        "mamba activate",
        "conda activate",
        "$ASYS_HARNESS_ENV",
        "${ASYS_HARNESS_ENV",
        'source "' + str(REPO / "slurm" / "common.sh") + '"',
    )
    present = [fragment for fragment in forbidden_fragments if fragment in payload]
    present.extend(
        line.strip()
        for line in payload.splitlines()
        if line.strip().startswith(("source ", ". "))
    )
    if present:
        raise ControlError(
            "rendered production cell batch depends on ambient environment activation: "
            + ", ".join(present)
        )


def validate_controller_generation_sbatch(
    control: Mapping[str, Any],
    *,
    payload: str,
    state_dir: Path,
    role: str,
    generation: int,
    intent_token: str,
) -> None:
    """Prove a spooled controller starts only from the frozen runtime.

    Controller jobs are long-lived trust roots.  Executing the pinned Python binary is
    not sufficient if a mutable shell bootstrap first changes imports, ``HF_HOME``, or
    result routing.  This validator is intentionally byte-oriented and is run before
    every generation file is published.
    """

    _validate_role(role)
    immutable = control["immutable"]
    fleet = effective_fleet_contract_binding(control, verify_files=True)
    release_worktree = Path(str(immutable["release_worktree"])).resolve()
    python_path = (
        Path(str(immutable["harness_environment_prefix"])).resolve() / "bin" / "python"
    )
    control_script = release_worktree / "slurm" / "schema5_control.py"
    exact_lines = {
        "#SBATCH --no-requeue",
        "#SBATCH --export=NONE",
        f"#SBATCH --partition={PRODUCTION_CONTROLLER_PARTITION}",
        "unset PYTHONHOME PYTHONPATH VIRTUAL_ENV CONDA_PREFIX CONDA_DEFAULT_ENV",
        "export PYTHONDONTWRITEBYTECODE=1",
        "export PYTHONNOUSERSITE=1",
        "export PYTHONSAFEPATH=1",
        f'export HF_HOME="{Path(str(immutable["hf_home"])).resolve()}"',
        f'export ASYS_RESULTS_ROOT="{Path(str(immutable["results_root"])).resolve()}"',
        "export HF_HUB_OFFLINE=1",
        "export TRANSFORMERS_OFFLINE=1",
        "export HF_DATASETS_OFFLINE=1",
        f'export ASYS_RELEASE_ID="{immutable["release_id"]}"',
        f'export ASYS_RELEASE_WORKTREE="{release_worktree}"',
        (
            'export ASYS_MODEL_CONTRACT_SHA256="'
            + str(immutable["model_contract_sha256"])
            + '"'
        ),
        (
            'export ASYS_FLEET_CONTRACT_SHA256="'
            + str(fleet["sha256"])
            + '"'
        ),
        f'export ASYS_FLEET_CONTRACT_PATH="{fleet["path"]}"',
        (
            'export ASYS_RELEASE_FLEET_CONTRACT_SHA256="'
            + str(immutable["fleet_contract_sha256"])
            + '"'
        ),
        f'export ASYS_CAPACITY_GENERATION="{fleet["capacity_generation"]}"',
        (
            'export ASYS_HARNESS_ENVIRONMENT_SHA256="'
            + str(immutable["harness_environment_sha256"])
            + '"'
        ),
        (
            'export ASYS_SERVING_ENVIRONMENT_SHA256="'
            + str(immutable["serving_environment_sha256"])
            + '"'
        ),
        f'export ASYS_ROLLOUT_GENERATION="{control["rollout_generation"]}"',
        f'export ASYS_IMMUTABLE_PINS_SHA256="{control["immutable_sha256"]}"',
        (
            f'exec "{python_path}" -u "{control_script}" '
            f'--state-dir "{state_dir.resolve()}" supervise \\'
        ),
        (
            f"--role {role} --generation {generation} "
            f'--intent-token "{intent_token}"'
        ),
    }
    ordered_stripped_lines = [line.strip() for line in payload.splitlines()]
    stripped_lines = set(ordered_stripped_lines)
    missing = sorted(exact_lines - stripped_lines)
    if missing:
        raise ControlError(
            "rendered controller generation lacks the immutable runtime contract: "
            + ", ".join(missing)
        )
    _validate_trusted_sbatch_bootstrap(
        payload, description="production controller generation"
    )
    partition_directives = [
        line
        for line in ordered_stripped_lines
        if line.startswith("#SBATCH --partition=")
    ]
    if partition_directives != [
        f"#SBATCH --partition={PRODUCTION_CONTROLLER_PARTITION}"
    ]:
        raise ControlError(
            "rendered production controller must use exactly one "
            f"{PRODUCTION_CONTROLLER_PARTITION} partition directive"
        )
    for variable, expected_line in (
        ("HF_HOME", f'export HF_HOME="{Path(str(immutable["hf_home"])).resolve()}"'),
        (
            "ASYS_RELEASE_WORKTREE",
            f'export ASYS_RELEASE_WORKTREE="{release_worktree}"',
        ),
        (
            "ASYS_FLEET_CONTRACT_SHA256",
            f'export ASYS_FLEET_CONTRACT_SHA256="{fleet["sha256"]}"',
        ),
        (
            "ASYS_FLEET_CONTRACT_PATH",
            f'export ASYS_FLEET_CONTRACT_PATH="{fleet["path"]}"',
        ),
        (
            "ASYS_RELEASE_FLEET_CONTRACT_SHA256",
            'export ASYS_RELEASE_FLEET_CONTRACT_SHA256="'
            + str(immutable["fleet_contract_sha256"])
            + '"',
        ),
        (
            "ASYS_CAPACITY_GENERATION",
            f'export ASYS_CAPACITY_GENERATION="{fleet["capacity_generation"]}"',
        ),
    ):
        assignments = [
            line
            for line in ordered_stripped_lines
            if line.startswith((f"export {variable}=", f"{variable}="))
        ]
        if assignments != [expected_line]:
            raise ControlError(
                f"rendered controller generation must contain one exact {variable} assignment"
            )

    forbidden_lines = []
    forbidden_fragments = (
        "mamba activate",
        "conda activate",
        "micromamba activate",
        "source ",
        ". ",
        "PYTHONPATH=",
        "PYTHONHOME=",
        "VIRTUAL_ENV=",
        "CONDA_PREFIX=",
        "CONDA_DEFAULT_ENV=",
    )
    for raw_line in payload.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        lowered = line.lower()
        if any(fragment.lower() in lowered for fragment in forbidden_fragments):
            # The single exact unset command is the only permitted mention of these
            # ambient variables.
            if (
                line
                == "unset PYTHONHOME PYTHONPATH VIRTUAL_ENV CONDA_PREFIX CONDA_DEFAULT_ENV"
            ):
                continue
            forbidden_lines.append(line)
    if forbidden_lines:
        raise ControlError(
            "rendered controller generation depends on ambient environment activation: "
            + ", ".join(forbidden_lines)
        )

    exec_lines = [line for line in stripped_lines if line.startswith("exec ")]
    if exec_lines != [
        f'exec "{python_path}" -u "{control_script}" '
        f'--state-dir "{state_dir.resolve()}" supervise \\'
    ]:
        raise ControlError(
            "rendered controller generation has a non-canonical entry point"
        )


def render_generation_sbatch(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    role: str,
    generation: int,
    intent_token: str,
) -> Path:
    """Render one immutable generation-addressed controller sbatch."""
    _validate_role(role)
    token = job_token(role, generation, intent_token)
    short = ROLE_SHORT[role]
    template_name = (
        "schema5_dispatcher.sbatch.tmpl"
        if role == "dispatcher"
        else "schema5_fleet_supervisor.sbatch.tmpl"
    )
    release_worktree = Path(control["immutable"]["release_worktree"]).resolve()
    template = release_worktree / "slurm" / template_name
    if not template.is_file():
        raise ImmutablePinError(
            f"controller template missing from frozen release: {template}"
        )
    target = state_dir / "sbatch" / f"{short}.g{generation:06d}.{intent_token}.sbatch"
    resource = _controller_resource(control, role)
    python_path = (
        Path(control["immutable"]["harness_environment_prefix"]) / "bin" / "python"
    )
    provenance = production_environment(control)
    replacements = {
        "JOB_NAME": _rendered_controller_job_name(
            role, generation, intent_token
        ),
        "JOB_TOKEN": token,
        "PARTITION": resource["partition"],
        "MEMORY": resource["memory"],
        "TIME_LIMIT": resource["time_limit"],
        "LOG_PATH": str(state_dir / "logs" / f"{short}.g{generation:06d}.%j.out"),
        "ALERT_EMAIL": str(control["alert_email"]),
        "PYTHON": str(python_path),
        "CONTROL_SCRIPT": str(release_worktree / "slurm" / "schema5_control.py"),
        "STATE_DIR": str(state_dir.resolve()),
        "GENERATION": str(generation),
        "INTENT_TOKEN": intent_token,
        "RELEASE_ID": provenance["ASYS_RELEASE_ID"],
        "RELEASE_WORKTREE": str(release_worktree),
        "MODEL_CONTRACT_SHA256": provenance["ASYS_MODEL_CONTRACT_SHA256"],
        "FLEET_CONTRACT_SHA256": provenance["ASYS_FLEET_CONTRACT_SHA256"],
        "FLEET_CONTRACT_PATH": provenance["ASYS_FLEET_CONTRACT_PATH"],
        "RELEASE_FLEET_CONTRACT_SHA256": provenance[
            "ASYS_RELEASE_FLEET_CONTRACT_SHA256"
        ],
        "CAPACITY_GENERATION": provenance["ASYS_CAPACITY_GENERATION"],
        "HARNESS_ENVIRONMENT_SHA256": provenance["ASYS_HARNESS_ENVIRONMENT_SHA256"],
        "SERVING_ENVIRONMENT_SHA256": provenance["ASYS_SERVING_ENVIRONMENT_SHA256"],
        "ROLLOUT_GENERATION": provenance["ASYS_ROLLOUT_GENERATION"],
        "IMMUTABLE_PINS_SHA256": provenance["ASYS_IMMUTABLE_PINS_SHA256"],
        "HF_HOME": str(Path(control["immutable"]["hf_home"]).resolve()),
        "RESULTS_ROOT": str(Path(control["immutable"]["results_root"]).resolve()),
    }
    unsafe = {
        name: value
        for name, value in replacements.items()
        if any(character in value for character in ('"', "\\", "$", "`", "\n", "\r"))
    }
    if unsafe:
        raise ImmutablePinError(
            "controller template values are not safe for exact double-quoted rendering: "
            + ", ".join(sorted(unsafe))
        )
    payload = template.read_text(encoding="utf-8")
    for name, value in replacements.items():
        if "{" + name + "}" not in payload:
            raise ControlError(f"controller template omitted placeholder {name}")
        payload = payload.replace("{" + name + "}", value)
    if "{" in payload or "}" in payload:
        raise ControlError(
            f"unresolved placeholder in rendered controller sbatch {target}"
        )
    validate_controller_generation_sbatch(
        control,
        payload=payload,
        state_dir=state_dir,
        role=role,
        generation=generation,
        intent_token=intent_token,
    )
    if target.exists() or target.is_symlink():
        if (
            target.is_symlink()
            or not target.is_file()
            or target.stat().st_nlink != 1
            or target.stat().st_mode & 0o222
            or target.read_text(encoding="utf-8") != payload
        ):
            raise ImmutablePinError(
                f"generation sbatch already exists with different bytes: {target}"
            )
        return target
    _atomic_publish_readonly_text(target, payload)
    return target


def _submit_argv(
    path: Path, *, token: str, dependency_job_id: str | None, hold: bool = False
) -> list[str]:
    argv = ["sbatch", "--parsable", f"--comment={token}"]
    if hold:
        argv.append("--hold")
    if dependency_job_id:
        if not dependency_job_id.isdigit():
            raise ControlError(f"unsafe dependency job ID {dependency_job_id!r}")
        argv.append(f"--dependency=afterany:{dependency_job_id}")
    argv.append(str(path))
    return argv


class _ExactSbatchInvocation(list[str]):
    """One exact stdin transport handed across the external sbatch boundary.

    The list surface preserves the existing injectable runner contract.  The
    production runner recognizes this type and supplies ``stdin_bytes`` directly to
    sbatch, so Slurm never reopens the mutable pathname after validation.
    """

    def __init__(self, argv: Sequence[str], stdin_bytes: bytes) -> None:
        super().__init__(argv)
        self.stdin_bytes = bytes(stdin_bytes)
        self.stdin_sha256 = hashlib.sha256(self.stdin_bytes).hexdigest()
        self.transport = EXACT_SBATCH_SUBMISSION_TRANSPORT


def _exact_sbatch_submission_argv(
    *,
    token: str,
    dependency_job_id: str | None,
) -> list[str]:
    if not token or any(character in token for character in ("\x00", "\n", "\r")):
        raise ControlError("exact sbatch submission token is unsafe")
    argv = ["sbatch", "--parsable", f"--comment={token}", "--hold"]
    if dependency_job_id is not None:
        if not dependency_job_id.isdigit():
            raise ControlError(
                f"unsafe exact sbatch dependency job ID {dependency_job_id!r}"
            )
        argv.append(f"--dependency=afterany:{dependency_job_id}")
    return argv


def _submission_argv_sha256(argv: Sequence[str]) -> str:
    return hashlib.sha256(
        json.dumps(
            list(argv),
            separators=(",", ":"),
            ensure_ascii=True,
        ).encode("utf-8")
    ).hexdigest()


def _exact_sbatch_receipt_path(
    state_dir: Path, *, job_token: str, job_id: str
) -> Path:
    if not job_id.isdigit():
        raise ControlError("spooled-script receipt requires a numeric job ID")
    token_digest = hashlib.sha256(job_token.encode("utf-8")).hexdigest()
    return (
        state_dir
        / SBATCH_SPOOL_RECEIPTS_DIRNAME
        / f"{token_digest}.{job_id}.json"
    ).resolve()


def _read_slurm_spooled_script(job_id: str) -> bytes:
    proc = _run_subprocess(
        ["scontrol", "write", "batch_script", job_id, "-"]
    )
    if proc.returncode != 0 or not isinstance(proc.stdout, str):
        raise SchedulerVisibilityPending(
            "cannot retrieve exact Slurm-spooled script for "
            f"job {job_id}: rc={proc.returncode}; {proc.stderr.strip()[:500]}"
        )
    return proc.stdout.encode("utf-8")


def _validate_exact_sbatch_receipt(
    path: Path,
    *,
    expected: Mapping[str, Any],
) -> tuple[dict[str, Any], str]:
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
    ):
        raise ImmutablePinError(
            f"exact Slurm-spooled script receipt is unsafe: {path}"
        )
    value = _load_json_object(
        path, description="exact Slurm-spooled script receipt"
    )
    if (
        set(value) != set(expected) | {"verified_at", "verified_timestamp"}
        or any(value.get(key) != item for key, item in expected.items())
        or not isinstance(value.get("verified_timestamp"), (int, float))
        or isinstance(value.get("verified_timestamp"), bool)
        or value.get("verified_at")
        != utc_timestamp(float(value.get("verified_timestamp", -1)))
    ):
        raise ImmutablePinError(
            "exact Slurm-spooled script receipt identity drifted"
        )
    return value, sha256_file(path)


def _exact_sbatch_release_paths(receipt_path: Path) -> tuple[Path, Path]:
    stem = receipt_path.name
    if not stem.endswith(".json"):
        raise ImmutablePinError(
            "exact Slurm spool receipt path has an invalid suffix"
        )
    prefix = stem[: -len(".json")]
    return (
        receipt_path.with_name(prefix + ".release-intent.json"),
        receipt_path.with_name(prefix + ".release-complete.json"),
    )


def _validate_exact_sbatch_release_intent(
    path: Path,
    *,
    record: Mapping[str, Any],
    job_id: str,
    receipt_path: Path,
    receipt_sha256: str,
) -> tuple[dict[str, Any], str]:
    value = _load_json_object(
        path, description="exact held-sbatch release intent"
    )
    expected_authorization = (
        "resume_transaction"
        if bool(record.get("persistent_hold"))
        else "automatic_after_spool_proof"
    )
    expected_fields = {
        "schema_version",
        "kind",
        "job_id",
        "job_token",
        "spooled_receipt_path",
        "spooled_receipt_sha256",
        "submission_argv_sha256",
        "persistent_hold",
        "authorization",
        "requested_at",
        "requested_timestamp",
        "intent_id",
    }
    without_id = dict(value)
    intent_id = without_id.pop("intent_id", None)
    requested = value.get("requested_timestamp")
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
        or set(value) != expected_fields
        or value.get("schema_version") != 1
        or value.get("kind") != "schema5_exact_sbatch_release_intent"
        or value.get("job_id") != job_id
        or value.get("job_token") != record.get("job_token")
        or value.get("spooled_receipt_path") != str(receipt_path)
        or value.get("spooled_receipt_sha256") != receipt_sha256
        or value.get("submission_argv_sha256")
        != record.get("submission_argv_sha256")
        or value.get("persistent_hold")
        is not bool(record.get("persistent_hold"))
        or value.get("authorization") != expected_authorization
        or not isinstance(requested, (int, float))
        or isinstance(requested, bool)
        or value.get("requested_at") != utc_timestamp(float(requested))
        or intent_id != sha256_value(without_id)
    ):
        raise ImmutablePinError(
            "exact held-sbatch release intent identity drifted"
        )
    return value, sha256_file(path)


def _validate_exact_sbatch_release_complete(
    path: Path,
    *,
    record: Mapping[str, Any],
    job_id: str,
    intent_path: Path,
    intent_sha256: str,
    intent_id: str,
) -> tuple[dict[str, Any], str]:
    value = _load_json_object(
        path, description="exact held-sbatch release completion"
    )
    expected_fields = {
        "schema_version",
        "kind",
        "job_id",
        "job_token",
        "release_intent_path",
        "release_intent_sha256",
        "release_intent_id",
        "scheduler_observation",
        "release_returncode",
        "release_stderr",
        "released_at",
        "released_timestamp",
        "completion_id",
    }
    without_id = dict(value)
    completion_id = without_id.pop("completion_id", None)
    released = value.get("released_timestamp")
    if (
        path.is_symlink()
        or not path.is_file()
        or path.stat().st_nlink != 1
        or path.stat().st_mode & 0o222
        or set(value) != expected_fields
        or value.get("schema_version") != 1
        or value.get("kind") != "schema5_exact_sbatch_release_complete"
        or value.get("job_id") != job_id
        or value.get("job_token") != record.get("job_token")
        or value.get("release_intent_path") != str(intent_path)
        or value.get("release_intent_sha256") != intent_sha256
        or value.get("release_intent_id") != intent_id
        or value.get("scheduler_observation")
        not in {
            "release_command_succeeded",
            "already_running",
            "already_active_nonpending",
            "already_pending_unheld",
            "already_terminal",
        }
        or (
            value.get("release_returncode") is not None
            and (
                not isinstance(value.get("release_returncode"), int)
                or isinstance(value.get("release_returncode"), bool)
            )
        )
        or not isinstance(value.get("release_stderr"), str)
        or not isinstance(released, (int, float))
        or isinstance(released, bool)
        or value.get("released_at") != utc_timestamp(float(released))
        or completion_id != sha256_value(without_id)
    ):
        raise ImmutablePinError(
            "exact held-sbatch release completion identity drifted"
        )
    return value, sha256_file(path)


def _scheduler_job_release_observation(
    job: SchedulerJob,
    *,
    record: Mapping[str, Any],
    job_id: str,
    reason: str | None = None,
) -> str | None:
    if job.job_id != job_id or job.comment != record.get("job_token"):
        raise SchedulerAmbiguity(
            "exact held-sbatch release scheduler identity mismatched"
        )
    state = normalize_scheduler_state(job.state)
    if state in TERMINAL_SCHEDULER_STATES:
        return "already_terminal"
    if state == "RUNNING":
        return "already_running"
    if state in ACTIVE_SCHEDULER_STATES - {"PENDING"}:
        return "already_active_nonpending"
    if state == "PENDING" and reason is not None:
        normalized_reason = reason.strip().lower()
        if normalized_reason.startswith("jobheld"):
            return None
        return "already_pending_unheld"
    if state not in ACTIVE_SCHEDULER_STATES | TERMINAL_SCHEDULER_STATES:
        raise SchedulerAmbiguity(
            f"exact held-sbatch release observed unknown state {state!r}"
        )
    return None


def _query_exact_sbatch_release_observation(
    *,
    record: Mapping[str, Any],
    job_id: str,
    runner: Callable[[Sequence[str]], subprocess.CompletedProcess[str]],
) -> str | None:
    proc = runner(["scontrol", "show", "job", "-o", job_id])
    if proc.returncode != 0:
        return None
    lines = [line.strip() for line in proc.stdout.splitlines() if line.strip()]
    if len(lines) != 1:
        raise SchedulerAmbiguity(
            "exact held-sbatch release query returned an ambiguous record"
        )
    try:
        tokens = shlex.split(lines[0], posix=True)
    except (TypeError, ValueError) as exc:
        raise SchedulerAmbiguity(
            "cannot parse exact held-sbatch release scheduler record"
        ) from exc
    fields: dict[str, str] = {}
    for token in tokens:
        if "=" not in token:
            continue
        key, value = token.split("=", 1)
        if not key or key in fields:
            raise SchedulerAmbiguity(
                "exact held-sbatch release scheduler record has duplicate fields"
            )
        fields[key] = value.strip('"')
    job = SchedulerJob(
        job_id=fields.get("JobId", ""),
        job_name=fields.get("JobName", ""),
        state=fields.get("JobState", ""),
        comment=fields.get("Comment", ""),
        source="scontrol",
    )
    return _scheduler_job_release_observation(
        job,
        record=record,
        job_id=job_id,
        reason=fields.get("Reason"),
    )


def _ensure_exact_sbatch_released(
    state_dir: Path,
    *,
    record: Mapping[str, Any],
    job_id: str,
    receipt_path: Path,
    receipt_sha256: str,
    now: float,
    release_runner: Callable[[Sequence[str]], subprocess.CompletedProcess[str]],
    scheduler_job: SchedulerJob | None,
    observation_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ),
) -> dict[str, Any]:
    """Marker-first release with replay adoption of an already released job."""

    intent_path, complete_path = _exact_sbatch_release_paths(receipt_path)
    if intent_path.exists() or intent_path.is_symlink():
        intent, intent_sha256 = _validate_exact_sbatch_release_intent(
            intent_path,
            record=record,
            job_id=job_id,
            receipt_path=receipt_path,
            receipt_sha256=receipt_sha256,
        )
    else:
        authorization = (
            "resume_transaction"
            if bool(record.get("persistent_hold"))
            else "automatic_after_spool_proof"
        )
        intent = {
            "schema_version": 1,
            "kind": "schema5_exact_sbatch_release_intent",
            "job_id": job_id,
            "job_token": str(record["job_token"]),
            "spooled_receipt_path": str(receipt_path),
            "spooled_receipt_sha256": receipt_sha256,
            "submission_argv_sha256": str(record["submission_argv_sha256"]),
            "persistent_hold": bool(record.get("persistent_hold")),
            "authorization": authorization,
            "requested_at": utc_timestamp(now),
            "requested_timestamp": float(now),
        }
        intent["intent_id"] = sha256_value(intent)
        _atomic_publish_readonly_json(intent_path, intent)
        intent, intent_sha256 = _validate_exact_sbatch_release_intent(
            intent_path,
            record=record,
            job_id=job_id,
            receipt_path=receipt_path,
            receipt_sha256=receipt_sha256,
        )
    if complete_path.exists() or complete_path.is_symlink():
        completion, _completion_sha256 = (
            _validate_exact_sbatch_release_complete(
                complete_path,
                record=record,
                job_id=job_id,
                intent_path=intent_path,
                intent_sha256=intent_sha256,
                intent_id=str(intent["intent_id"]),
            )
        )
        return {
            "released_at": completion["released_at"],
            "released_timestamp": float(completion["released_timestamp"]),
        }

    observation = (
        _scheduler_job_release_observation(
            scheduler_job,
            record=record,
            job_id=job_id,
        )
        if scheduler_job is not None
        else None
    )
    release_returncode: int | None = None
    release_stderr = ""
    if observation is None:
        proc = release_runner(["scontrol", "release", job_id])
        release_returncode = int(proc.returncode)
        release_stderr = proc.stderr.strip()[:500]
        if proc.returncode == 0:
            observation = "release_command_succeeded"
        else:
            if observation_runner is not None:
                observation = _query_exact_sbatch_release_observation(
                    record=record,
                    job_id=job_id,
                    runner=observation_runner,
                )
            # A complete snapshot may already prove a fast start/exit even when
            # scontrol no longer retains the record.
            if observation is None and scheduler_job is not None:
                observation = _scheduler_job_release_observation(
                    scheduler_job,
                    record=record,
                    job_id=job_id,
                )
            if observation is None:
                raise SchedulerVisibilityPending(
                    f"exact held sbatch job {job_id} remains held or its "
                    "release state is not yet provable"
                )

    completion = {
        "schema_version": 1,
        "kind": "schema5_exact_sbatch_release_complete",
        "job_id": job_id,
        "job_token": str(record["job_token"]),
        "release_intent_path": str(intent_path),
        "release_intent_sha256": intent_sha256,
        "release_intent_id": str(intent["intent_id"]),
        "scheduler_observation": observation,
        "release_returncode": release_returncode,
        "release_stderr": release_stderr,
        "released_at": utc_timestamp(now),
        "released_timestamp": float(now),
    }
    completion["completion_id"] = sha256_value(completion)
    _atomic_publish_readonly_json(complete_path, completion)
    completion, _completion_sha256 = _validate_exact_sbatch_release_complete(
        complete_path,
        record=record,
        job_id=job_id,
        intent_path=intent_path,
        intent_sha256=intent_sha256,
        intent_id=str(intent["intent_id"]),
    )
    return {
        "released_at": completion["released_at"],
        "released_timestamp": float(completion["released_timestamp"]),
    }


def _validate_exact_sbatch_release_record(
    record: Mapping[str, Any],
    *,
    job_id: str,
    receipt_path: Path,
    receipt_sha256: str,
) -> None:
    intent_path, complete_path = _exact_sbatch_release_paths(receipt_path)
    intent, intent_sha256 = _validate_exact_sbatch_release_intent(
        intent_path,
        record=record,
        job_id=job_id,
        receipt_path=receipt_path,
        receipt_sha256=receipt_sha256,
    )
    completion, _completion_sha256 = _validate_exact_sbatch_release_complete(
        complete_path,
        record=record,
        job_id=job_id,
        intent_path=intent_path,
        intent_sha256=intent_sha256,
        intent_id=str(intent["intent_id"]),
    )
    if (
        record.get("released_at") != completion["released_at"]
        or record.get("released_timestamp")
        != completion["released_timestamp"]
    ):
        raise ImmutablePinError(
            "exact held-sbatch release record differs from sealed completion"
        )


def _validate_exact_sbatch_record_proof(
    record: Mapping[str, Any],
    *,
    job_id: str,
    context: str,
) -> tuple[dict[str, Any], str]:
    """Re-prove one accepted stdin submission from its sealed Slurm spool receipt.

    Slurm's ``Command``/``SubmitLine`` presentation is not the byte authority for a
    batch script submitted on standard input.  The immutable intent, exact numeric job
    ID, scheduler token, and independently captured ``scontrol write batch_script``
    bytes are.  This verifier intentionally does not use the displayed command.
    """

    if not isinstance(job_id, str) or not job_id.isdigit():
        raise SchedulerAmbiguity(f"{context} has an invalid scheduler job ID")
    sbatch_path = Path(str(record.get("sbatch_path", ""))).expanduser()
    receipt_path = Path(
        str(record.get("spooled_receipt_path", ""))
    ).expanduser()
    submission_argv = record.get("submission_argv")
    dependency_job_id = record.get("dependency_job_id")
    try:
        exact_submission_argv = _exact_sbatch_submission_argv(
            token=str(record.get("job_token", "")),
            dependency_job_id=(
                dependency_job_id
                if isinstance(dependency_job_id, str)
                else None
            ),
        )
    except ControlError:
        exact_submission_argv = None
    if (
        not sbatch_path.is_absolute()
        or sbatch_path.is_symlink()
        or not sbatch_path.is_file()
        or sbatch_path.stat().st_nlink != 1
        or sbatch_path.stat().st_mode & 0o222
        or _SHA256_RE.fullmatch(str(record.get("sbatch_sha256", ""))) is None
        or sha256_file(sbatch_path) != record.get("sbatch_sha256")
        or record.get("submission_transport")
        != EXACT_SBATCH_SUBMISSION_TRANSPORT
        or not isinstance(submission_argv, list)
        or not all(isinstance(item, str) for item in submission_argv)
        or submission_argv != exact_submission_argv
        or record.get("submission_argv_sha256")
        != _submission_argv_sha256(submission_argv)
        or not isinstance(record.get("persistent_hold"), bool)
        or not receipt_path.is_absolute()
        or _SHA256_RE.fullmatch(
            str(record.get("spooled_receipt_sha256", ""))
        )
        is None
    ):
        raise SchedulerAmbiguity(
            f"{context} lacks an exact immutable stdin submission contract"
        )
    expected = {
        "schema_version": 1,
        "kind": "schema5_exact_sbatch_spool_receipt",
        "job_id": job_id,
        "job_token": str(record.get("job_token", "")),
        "sbatch_path": str(sbatch_path.resolve()),
        "sbatch_sha256": str(record["sbatch_sha256"]),
        "spooled_sbatch_sha256": str(record["sbatch_sha256"]),
        "submission_transport": EXACT_SBATCH_SUBMISSION_TRANSPORT,
        "submission_argv": list(submission_argv),
        "submission_argv_sha256": str(record["submission_argv_sha256"]),
        "submitted_held": True,
        "persistent_hold": bool(record["persistent_hold"]),
    }
    try:
        receipt, receipt_sha256 = _validate_exact_sbatch_receipt(
            receipt_path.resolve(), expected=expected
        )
    except (ControlError, OSError) as exc:
        raise SchedulerAmbiguity(
            f"{context} lacks its sealed exact Slurm spool proof"
        ) from exc
    if receipt_sha256 != record["spooled_receipt_sha256"]:
        raise SchedulerAmbiguity(
            f"{context} exact Slurm spool receipt checksum drifted"
        )
    if (
        not bool(record["persistent_hold"])
        and record.get("released_timestamp") is None
    ):
        raise SchedulerAmbiguity(
            f"{context} exact held submission lacks a durable release record"
        )
    if record.get("released_timestamp") is not None:
        try:
            _validate_exact_sbatch_release_record(
                record,
                job_id=job_id,
                receipt_path=receipt_path.resolve(),
                receipt_sha256=receipt_sha256,
            )
        except (ControlError, OSError) as exc:
            raise SchedulerAmbiguity(
                f"{context} lacks its sealed exact release proof"
            ) from exc
    return receipt, receipt_sha256


def _prove_exact_sbatch_and_release(
    state_dir: Path,
    *,
    record: Mapping[str, Any],
    job_id: str,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ),
    release_after_proof: bool,
    now: float,
    scheduler_job: SchedulerJob | None = None,
    release_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    observation_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
) -> dict[str, Any]:
    """Seal Slurm's exact spool proof while held, then optionally release it.

    Test runners are scheduler fakes and therefore use the exact in-memory transport
    payload as their synthetic spool unless they expose ``spooled_script`` on the
    returned process.  Production always queries Slurm independently.
    """

    path = Path(str(record["sbatch_path"])).expanduser().resolve()
    payload = _stable_readonly_preimage(
        path, description="exact sbatch submission artifact"
    )
    sbatch_sha256 = hashlib.sha256(payload).hexdigest()
    argv = list(record["submission_argv"])
    exact_argv = _exact_sbatch_submission_argv(
        token=str(record["job_token"]),
        dependency_job_id=(
            str(record["dependency_job_id"])
            if record.get("dependency_job_id") is not None
            else None
        ),
    )
    if (
        sbatch_sha256 != record["sbatch_sha256"]
        or record.get("submission_transport")
        != EXACT_SBATCH_SUBMISSION_TRANSPORT
        or record.get("submission_argv_sha256")
        != _submission_argv_sha256(argv)
        or argv != exact_argv
    ):
        raise ImmutablePinError("exact sbatch submission contract drifted")
    receipt_path = _exact_sbatch_receipt_path(
        state_dir,
        job_token=str(record["job_token"]),
        job_id=job_id,
    )
    expected = {
        "schema_version": 1,
        "kind": "schema5_exact_sbatch_spool_receipt",
        "job_id": job_id,
        "job_token": str(record["job_token"]),
        "sbatch_path": str(path),
        "sbatch_sha256": sbatch_sha256,
        "spooled_sbatch_sha256": sbatch_sha256,
        "submission_transport": EXACT_SBATCH_SUBMISSION_TRANSPORT,
        "submission_argv": argv,
        "submission_argv_sha256": _submission_argv_sha256(argv),
        "submitted_held": True,
        "persistent_hold": bool(record.get("persistent_hold", False)),
    }
    if receipt_path.exists() or receipt_path.is_symlink():
        _, receipt_sha256 = _validate_exact_sbatch_receipt(
            receipt_path, expected=expected
        )
    else:
        spool = (
            payload
            if submit_runner is not None and submit_runner is not _run_subprocess
            else _read_slurm_spooled_script(job_id)
        )
        if hashlib.sha256(spool).hexdigest() != sbatch_sha256:
            raise SchedulerAmbiguity(
                f"Slurm-spooled script differs from exact intent for job {job_id}"
            )
        receipt_path.parent.mkdir(parents=True, exist_ok=True)
        _atomic_publish_readonly_json(
            receipt_path,
            {
                **expected,
                "verified_at": utc_timestamp(now),
                "verified_timestamp": float(now),
            },
        )
        _, receipt_sha256 = _validate_exact_sbatch_receipt(
            receipt_path, expected=expected
        )
    proof_record = {
        **dict(record),
        "spooled_receipt_path": str(receipt_path),
        "spooled_receipt_sha256": receipt_sha256,
    }
    persisted_released = record.get("released_timestamp")
    release_proof: dict[str, Any] = {
        "released_at": record.get("released_at"),
        "released_timestamp": (
            float(persisted_released)
            if isinstance(persisted_released, (int, float))
            and not isinstance(persisted_released, bool)
            else None
        ),
    }
    if release_proof["released_timestamp"] is not None:
        _validate_exact_sbatch_release_record(
            proof_record,
            job_id=job_id,
            receipt_path=receipt_path,
            receipt_sha256=receipt_sha256,
        )
    elif release_after_proof or (
        not bool(record.get("persistent_hold")) and scheduler_job is not None
    ):
        if release_runner is None:
            configured_release = (
                getattr(submit_runner, "release_runner", None)
                if submit_runner is not None
                else None
            )
            release_runner = (
                configured_release
                if callable(configured_release)
                else (
                    (lambda _argv: subprocess.CompletedProcess(
                        _argv, 0, "", ""
                    ))
                    if submit_runner is not None
                    and submit_runner is not _run_subprocess
                    else _run_subprocess
                )
            )
        if observation_runner is None:
            configured_observer = (
                getattr(submit_runner, "release_observation_runner", None)
                if submit_runner is not None
                else None
            )
            observation_runner = (
                configured_observer
                if callable(configured_observer)
                else (
                    _run_subprocess
                    if submit_runner is None or submit_runner is _run_subprocess
                    else None
                )
            )
        release_proof = _ensure_exact_sbatch_released(
            state_dir,
            record=proof_record,
            job_id=job_id,
            receipt_path=receipt_path,
            receipt_sha256=receipt_sha256,
            now=now,
            release_runner=release_runner,
            scheduler_job=scheduler_job,
            observation_runner=observation_runner,
        )
    return {
        "spooled_receipt_path": str(receipt_path),
        "spooled_receipt_sha256": receipt_sha256,
        **release_proof,
    }


def _find_intent_jobs(snapshot: SchedulerSnapshot, token: str) -> list[SchedulerJob]:
    return [job for job in snapshot.jobs if job.token == token]


def _exact_live_controller_job(
    snapshot: SchedulerSnapshot, record: Mapping[str, Any]
) -> SchedulerJob | None:
    """Resolve one durable controller record through exact scheduler fencing."""

    job_id = str(record.get("job_id", ""))
    token = str(record.get("job_token", ""))
    if not job_id or not token:
        return None
    matches = [
        job for job in snapshot.jobs if job.active and job.token == token
    ]
    if len(matches) != 1 or matches[0].job_id != job_id:
        return None
    _validate_exact_sbatch_record_proof(
        record,
        job_id=job_id,
        context=f"controller job {job_id}",
    )
    return matches[0]


def submit_controller_intent(
    state_dir: Path,
    *,
    role: str,
    target: str,
    dependency_job_id: str | None,
    scheduler: SchedulerSnapshot,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    allow_resuming: bool = False,
    hold: bool = False,
    now: float | None = None,
) -> dict[str, Any]:
    """Recover or submit one role intent, committing scheduler identity exactly once."""
    _validate_role(role)
    if target not in {"active", "successor"}:
        raise ControlError("controller intent target must be active or successor")
    timestamp = time.time() if now is None else float(now)
    runner = submit_runner or _run_subprocess
    if not scheduler.squeue_ok or not scheduler.sacct_ok:
        raise SchedulerAmbiguity(
            "controller submission requires complete squeue+sacct truth"
        )

    # Phase one: under the control lock, adopt a crash-window job or persist the exact
    # submitting intent before crossing the external sbatch boundary.
    with control_lock(state_dir):
        control = load_control(state_dir)
        allowed_states = {"running", "resuming"} if allow_resuming else {"running"}
        if control["desired_state"] not in allowed_states:
            raise ControlError("desired_state=paused disables controller resurrection")
        # A fresh fleet probe is a launch gate, not a renewable lease on the
        # controller chain. ``resume_control`` proves the <=10-minute fleet view
        # before entering ``resuming`` and records the resulting transaction. Once
        # production is ``running``, successors and stale-heartbeat takeovers keep
        # verifying every immutable/readiness artifact without aging out that
        # historical launch proof; live fleet health is owned by the fleet supervisor
        # and continuous monitors. Requiring freshness here would let a nominal
        # 12-hour controller submit its first successor but prevent that successor
        # from renewing the chain after the readiness artifact became old.
        validate_readiness(
            control, state_dir=state_dir, verify_files=True, now=None
        )
        role_state = control["controllers"][role]
        current_target = role_state.get(target)
        if isinstance(current_target, dict) and current_target.get("job_id"):
            exact_matches = [
                job
                for job in scheduler.jobs
                if job.job_id == str(current_target["job_id"])
                and job.token == current_target.get("job_token")
            ]
            if len(exact_matches) > 1:
                raise SchedulerAmbiguity(
                    f"controller job {current_target['job_id']} for {role} appears more than once"
                )
            same_id_wrong_token = [
                job
                for job in scheduler.jobs
                if job.job_id == str(current_target["job_id"])
                and job.token != current_target.get("job_token")
            ]
            if same_id_wrong_token:
                raise SchedulerAmbiguity(
                    f"controller job {current_target['job_id']} for {role} has a token mismatch"
                )
            if exact_matches and exact_matches[0].active:
                if _exact_live_controller_job(
                    scheduler, current_target
                ) is None:
                    raise SchedulerAmbiguity(
                        "controller active record lacks exact scheduler proof"
                    )
                return copy.deepcopy(current_target)
            if exact_matches:
                _validate_exact_sbatch_record_proof(
                    current_target,
                    job_id=exact_matches[0].job_id,
                    context="terminal controller record",
                )
                # Accounting proves the previous exact allocation was accepted and is
                # terminal.  It is safe to create a new generation immediately.
                role_state[target] = None
                if role_state.get("submission_intent") is current_target or (
                    isinstance(role_state.get("submission_intent"), dict)
                    and role_state["submission_intent"].get("intent_token")
                    == current_target.get("intent_token")
                ):
                    role_state["submission_intent"] = None
                current_target = None
            visible_since = float(
                (current_target or {}).get(
                    "submitted_timestamp",
                    (current_target or {}).get("created_timestamp", 0.0),
                )
            )
            if (
                current_target is not None
                and timestamp - visible_since < SUBMISSION_VISIBILITY_GRACE_SECONDS
            ):
                raise SchedulerVisibilityPending(
                    f"controller job {current_target['job_id']} for {role} is inside "
                    "scheduler visibility grace"
                )
            if current_target is not None:
                raise SchedulerAmbiguity(
                    f"accepted controller job {current_target['job_id']} for {role} "
                    "disappeared from complete squeue+sacct truth; refusing to "
                    "submit a potentially duplicate replacement"
                )
        intent = role_state.get("submission_intent")
        if isinstance(intent, dict) and intent.get("state") == "submitting":
            if bool(intent.get("hold", False)) != bool(hold):
                raise SchedulerAmbiguity(
                    "controller retry changed immutable hold semantics"
                )
            token = str(intent["job_token"])
            matches = _find_intent_jobs(scheduler, token)
            if len(matches) > 1:
                raise SchedulerAmbiguity(
                    f"controller intent {token} maps to multiple scheduler jobs"
                )
            active = [job for job in matches if job.active]
            if len(active) == 1:
                proof = _prove_exact_sbatch_and_release(
                    state_dir,
                    record=intent,
                    job_id=active[0].job_id,
                    submit_runner=runner,
                    release_after_proof=not bool(intent.get("hold", False)),
                    now=timestamp,
                    scheduler_job=active[0],
                )
                intent.update(proof)
                _validate_exact_sbatch_record_proof(
                    intent,
                    job_id=active[0].job_id,
                    context="controller adoption",
                )
                intent["state"] = "submitted"
                intent["job_id"] = active[0].job_id
                intent["adopted_from_scheduler"] = True
                role_state[str(intent["target"])] = copy.deepcopy(intent)
                append_transition(
                    state_dir,
                    control,
                    event="controller_submission_adopted",
                    details={"role": role, "job_id": active[0].job_id, "token": token},
                    now=timestamp,
                )
                _save_control(state_dir, control, now=timestamp)
                return copy.deepcopy(intent)
            if matches:
                terminal = matches[0]
                proof = _prove_exact_sbatch_and_release(
                    state_dir,
                    record=intent,
                    job_id=terminal.job_id,
                    submit_runner=runner,
                    release_after_proof=False,
                    now=timestamp,
                    scheduler_job=terminal,
                )
                intent.update(proof)
                _validate_exact_sbatch_record_proof(
                    intent,
                    job_id=terminal.job_id,
                    context="terminal controller adoption",
                )
                intent["state"] = "terminal"
                intent["job_id"] = terminal.job_id
                intent["terminal_scheduler_state"] = normalize_scheduler_state(
                    terminal.state
                )
                intent["adopted_from_scheduler"] = True
                role_state[str(intent["target"])] = copy.deepcopy(intent)
                role_state["submission_intent"] = None
                role_state["next_generation"] = max(
                    int(role_state["next_generation"]), int(intent["generation"]) + 1
                )
                append_transition(
                    state_dir,
                    control,
                    event="controller_terminal_submission_adopted",
                    details={
                        "role": role,
                        "job_id": terminal.job_id,
                        "token": token,
                        "state": normalize_scheduler_state(terminal.state),
                    },
                    now=timestamp,
                )
                intent = None
            # With complete squeue+sacct truth, a prior retryable non-acceptance may be
            # retried using the *same* generation and token.  An incomplete snapshot is
            # ambiguous and therefore fail-closed.
            if intent is not None:
                age = timestamp - float(intent.get("created_timestamp", timestamp))
                if (
                    not intent.get("last_submission_rejected", False)
                    and age < SUBMISSION_VISIBILITY_GRACE_SECONDS
                ):
                    raise SchedulerVisibilityPending(
                        f"controller intent {token} is inside scheduler visibility grace "
                        f"({max(0.0, age):.1f}s/{SUBMISSION_VISIBILITY_GRACE_SECONDS:.1f}s)"
                    )
        if not (isinstance(intent, dict) and intent.get("state") == "submitting"):
            generation = int(role_state["next_generation"])
            intent_token = uuid.uuid4().hex
            token = job_token(role, generation, intent_token)
            sbatch_path = render_generation_sbatch(
                state_dir,
                control,
                role=role,
                generation=generation,
                intent_token=intent_token,
            )
            intent = {
                "state": "submitting",
                "role": role,
                "target": target,
                "generation": generation,
                "intent_token": intent_token,
                "job_token": token,
                "sbatch_path": str(sbatch_path),
                "sbatch_sha256": sha256_file(sbatch_path),
                "submission_transport": EXACT_SBATCH_SUBMISSION_TRANSPORT,
                "submission_argv": _exact_sbatch_submission_argv(
                    token=token,
                    dependency_job_id=dependency_job_id,
                ),
                "submission_argv_sha256": None,
                "persistent_hold": bool(hold),
                "spooled_receipt_path": None,
                "spooled_receipt_sha256": None,
                "released_at": None,
                "released_timestamp": None,
                "dependency_job_id": dependency_job_id,
                "controller_primitives": shared_controller_primitive_contract(),
                "hold": bool(hold),
                "created_at": utc_timestamp(timestamp),
                "created_timestamp": timestamp,
                "attempts": 0,
            }
            intent["submission_argv_sha256"] = _submission_argv_sha256(
                intent["submission_argv"]
            )
            role_state["submission_intent"] = intent
            append_transition(
                state_dir,
                control,
                event="controller_submission_intent",
                details={
                    "role": role,
                    "target": target,
                    "generation": generation,
                    "intent_token": intent_token,
                    "dependency_job_id": dependency_job_id,
                },
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
        intent_copy = copy.deepcopy(intent)

    sbatch_payload = _stable_readonly_preimage(
        Path(intent_copy["sbatch_path"]),
        description="controller sbatch at exact submission boundary",
    )
    if (
        hashlib.sha256(sbatch_payload).hexdigest()
        != intent_copy["sbatch_sha256"]
    ):
        raise ImmutablePinError(
            "controller sbatch changed before exact submission"
        )
    proc = runner(
        _ExactSbatchInvocation(
            intent_copy["submission_argv"],
            sbatch_payload,
        )
    )
    completed_at = time.time() if now is None else timestamp
    raw_job_id = proc.stdout.strip().split(";", 1)[0]
    proof: dict[str, Any] | None = None
    if proc.returncode == 0 and raw_job_id.isdigit():
        proof = _prove_exact_sbatch_and_release(
            state_dir,
            record=intent_copy,
            job_id=raw_job_id,
            submit_runner=runner,
            release_after_proof=not bool(intent_copy.get("hold", False)),
            now=completed_at,
        )

    # Phase two: commit acceptance.  A nonzero return is known rejection and remains a
    # retryable submitting intent.  A killed process never reaches this phase; the next
    # caller searches both scheduler views by token before doing anything else.
    with control_lock(state_dir):
        control = load_control(state_dir)
        role_state = control["controllers"][role]
        current_intent = role_state.get("submission_intent")
        if not isinstance(current_intent, dict) or (
            current_intent.get("intent_token") != intent_copy["intent_token"]
        ):
            raise SchedulerAmbiguity(
                "controller submission intent changed during sbatch"
            )
        current_intent["attempts"] = int(current_intent.get("attempts", 0)) + 1
        current_intent["last_attempt_at"] = utc_timestamp(completed_at)
        if proc.returncode != 0:
            current_intent["last_error"] = proc.stderr.strip()[:1000]
            current_intent["last_submission_rejected"] = True
            append_transition(
                state_dir,
                control,
                event="controller_submission_retryable",
                details={
                    "role": role,
                    "intent_token": current_intent["intent_token"],
                    "returncode": proc.returncode,
                    "error": current_intent["last_error"],
                },
                now=completed_at,
            )
            _save_control(state_dir, control, now=completed_at)
            raise ControlError(
                f"sbatch rejected controller intent for {role}: "
                f"{proc.stderr.strip()[:500]}"
            )
        job_id = raw_job_id
        if not job_id.isdigit():
            current_intent["last_error"] = f"invalid sbatch job id {job_id!r}"
            _save_control(state_dir, control, now=completed_at)
            raise SchedulerAmbiguity(
                f"sbatch returned invalid controller job id {job_id!r}"
            )
        current_intent["state"] = "submitted"
        current_intent["last_submission_rejected"] = False
        current_intent["job_id"] = job_id
        current_intent["submitted_at"] = utc_timestamp(completed_at)
        current_intent["submitted_timestamp"] = completed_at
        assert proof is not None
        current_intent.update(proof)
        role_state[target] = copy.deepcopy(current_intent)
        role_state["next_generation"] = max(
            int(role_state["next_generation"]), int(current_intent["generation"]) + 1
        )
        append_transition(
            state_dir,
            control,
            event="controller_submitted",
            details={
                "role": role,
                "target": target,
                "generation": current_intent["generation"],
                "intent_token": current_intent["intent_token"],
                "job_id": job_id,
            },
            now=completed_at,
        )
        _save_control(state_dir, control, now=completed_at)
        return copy.deepcopy(current_intent)


def _drill_state_path(state_dir: Path) -> Path:
    return state_dir / DRILL_STATE_FILENAME


def _drill_reconciliation_path(state_dir: Path, drill_id: str) -> Path:
    return state_dir / "drills" / drill_id / DRILL_RECONCILIATION_FILENAME


@contextmanager
def drill_lock(state_dir: Path) -> Iterator[None]:
    with _file_lock(state_dir / "locks" / "controller-drill.lock"):
        yield


@contextmanager
def drill_submission_boundary_lock(state_dir: Path) -> Iterator[None]:
    """Serialize the complete external ``sbatch`` transaction with drill stopping.

    The lock deliberately spans both the durable intent write and the external scheduler
    call.  ``finish_controller_drill`` takes the same lock before publishing ``stopping``.
    Consequently, a successful finish can neither overtake an in-flight submission nor
    permit a new one to start after the stopping transition.
    """

    with _file_lock(state_dir / "locks" / "controller-drill-submission-boundary.lock"):
        yield


@contextmanager
def external_watchdog_drill_lock(state_dir: Path) -> Iterator[None]:
    """Serialize the sealed external-watchdog drill transaction."""

    with _file_lock(
        state_dir / "locks" / "external-watchdog-drill.lock",
        nonblocking=True,
    ):
        yield


def _external_watchdog_drill_root(state_dir: Path) -> Path:
    return state_dir / EXTERNAL_WATCHDOG_DRILL_DIRNAME


def _external_watchdog_drill_intent_path(state_dir: Path) -> Path:
    return (
        _external_watchdog_drill_root(state_dir)
        / EXTERNAL_WATCHDOG_DRILL_INTENT_FILENAME
    )


def _external_watchdog_drill_state_path(state_dir: Path) -> Path:
    return (
        _external_watchdog_drill_root(state_dir)
        / EXTERNAL_WATCHDOG_DRILL_STATE_FILENAME
    )


def _watchdog_canonical_json(value: Mapping[str, Any]) -> bytes:
    return (
        json.dumps(value, indent=2, sort_keys=True, allow_nan=False) + "\n"
    ).encode("utf-8")


def _watchdog_self_hash(value: Mapping[str, Any], field: str) -> str:
    identity = dict(value)
    identity.pop(field, None)
    return hashlib.sha256(_watchdog_canonical_json(identity)).hexdigest()


def _read_stable_json(
    path: Path,
    *,
    description: str,
    require_read_only: bool,
) -> tuple[dict[str, Any], bytes]:
    """Read one canonical path through a stable no-follow descriptor."""

    lexical = Path(os.path.abspath(os.fspath(path.expanduser())))
    if any(character in str(lexical) for character in ("\x00", "\n", "\r")):
        raise ControlError(f"{description} path is unsafe")
    try:
        resolved = lexical.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise ControlError(f"{description} is unavailable: {exc}") from exc
    if resolved != lexical:
        raise ControlError(f"{description} traverses a symlink")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(lexical, flags)
    try:
        before = os.fstat(descriptor)
        chunks: list[bytes] = []
        while block := os.read(descriptor, 1024 * 1024):
            chunks.append(block)
        after = os.fstat(descriptor)
    finally:
        os.close(descriptor)
    identity = lambda value: (
        value.st_dev,
        value.st_ino,
        value.st_mode,
        value.st_size,
        value.st_mtime_ns,
        value.st_ctime_ns,
    )
    current = lexical.stat(follow_symlinks=False)
    if (
        not stat.S_ISREG(before.st_mode)
        or identity(before) != identity(after)
        or (current.st_dev, current.st_ino) != (after.st_dev, after.st_ino)
        or (require_read_only and stat.S_IMODE(before.st_mode) & 0o222)
        or before.st_nlink != 1
    ):
        raise ControlError(f"{description} is mutable or changed while being read")
    raw = b"".join(chunks)

    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise ControlError(f"{description} duplicates JSON key {key!r}")
            result[key] = value
        return result

    try:
        value = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=reject_duplicates,
            parse_constant=lambda token: (_ for _ in ()).throw(
                ControlError(f"{description} contains non-finite {token}")
            ),
        )
    except ControlError:
        raise
    except (UnicodeError, json.JSONDecodeError, ValueError) as exc:
        raise ControlError(f"{description} is invalid JSON: {exc}") from exc
    if not isinstance(value, dict):
        raise ControlError(f"{description} must contain one JSON object")
    return value, raw


def _publish_sealed_json_once(
    path: Path, value: Mapping[str, Any], *, description: str
) -> tuple[Path, str]:
    """Publish one immutable canonical JSON inode without replacing a prior value."""

    path = Path(os.path.abspath(os.fspath(path.expanduser())))
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.parent.resolve(strict=True) != path.parent:
        raise ControlError(f"{description} parent traverses a symlink")
    payload = _watchdog_canonical_json(value)
    lock_descriptor = os.open(
        path.parent / f".{path.name}.publish.lock",
        os.O_RDWR | os.O_CREAT | getattr(os, "O_CLOEXEC", 0),
        0o600,
    )
    try:
        fcntl.flock(lock_descriptor, fcntl.LOCK_EX)

        def interrupted_bytes(candidate: Path) -> tuple[bytes, os.stat_result]:
            if candidate.is_symlink() or not candidate.is_file():
                raise ControlError(
                    f"{description} has an unsafe interrupted publication"
                )
            flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
            if hasattr(os, "O_NOFOLLOW"):
                flags |= os.O_NOFOLLOW
            fd = os.open(candidate, flags)
            try:
                before = os.fstat(fd)
                chunks: list[bytes] = []
                while block := os.read(fd, 1024 * 1024):
                    chunks.append(block)
                after = os.fstat(fd)
            finally:
                os.close(fd)
            current = candidate.stat(follow_symlinks=False)
            if (
                not stat.S_ISREG(before.st_mode)
                or (
                    before.st_dev,
                    before.st_ino,
                    before.st_mode,
                    before.st_size,
                    before.st_mtime_ns,
                    before.st_ctime_ns,
                )
                != (
                    after.st_dev,
                    after.st_ino,
                    after.st_mode,
                    after.st_size,
                    after.st_mtime_ns,
                    after.st_ctime_ns,
                )
                or (current.st_dev, current.st_ino)
                != (after.st_dev, after.st_ino)
                or stat.S_IMODE(before.st_mode) & 0o222
            ):
                raise ControlError(
                    f"{description} interrupted publication changed"
                )
            return b"".join(chunks), after

        target_stat = (
            path.stat(follow_symlinks=False)
            if path.exists() and not path.is_symlink()
            else None
        )
        if path.is_symlink():
            raise ControlError(f"{description} target is symlinked")
        exact_candidates: list[Path] = []
        for candidate in sorted(
            child
            for child in path.parent.iterdir()
            if child.name.startswith(f".{path.name}.")
            and child.name.endswith(".publishing")
        ):
            candidate_raw, candidate_stat = interrupted_bytes(candidate)
            if target_stat is not None and (
                candidate_stat.st_dev,
                candidate_stat.st_ino,
            ) == (target_stat.st_dev, target_stat.st_ino):
                candidate.unlink()
            elif candidate_raw == payload:
                exact_candidates.append(candidate)
            else:
                raise ControlError(
                    f"{description} has a conflicting interrupted publication"
                )
        if not path.exists() and exact_candidates:
            survivor = exact_candidates.pop(0)
            os.link(survivor, path, follow_symlinks=False)
            survivor.unlink()
        for candidate in exact_candidates:
            candidate.unlink()
        if path.exists():
            existing, existing_raw = _read_stable_json(
                path, description=description, require_read_only=True
            )
            if existing != dict(value) or existing_raw != payload:
                raise ControlError(
                    f"{description} already exists with conflicting bytes"
                )
        else:
            descriptor, temporary_name = tempfile.mkstemp(
                dir=path.parent,
                prefix=f".{path.name}.",
                suffix=".publishing",
            )
            temporary = Path(temporary_name)
            try:
                with os.fdopen(descriptor, "wb") as handle:
                    handle.write(payload)
                    handle.flush()
                    os.fsync(handle.fileno())
                temporary.chmod(0o444)
                os.link(temporary, path, follow_symlinks=False)
                temporary.unlink()
            finally:
                try:
                    temporary.unlink()
                except FileNotFoundError:
                    pass
        directory = os.open(
            path.parent, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0)
        )
        try:
            os.fsync(directory)
        finally:
            os.close(directory)
    finally:
        fcntl.flock(lock_descriptor, fcntl.LOCK_UN)
        os.close(lock_descriptor)
    return path, hashlib.sha256(payload).hexdigest()


def _validate_watchdog_deployment_evidence(
    value: Mapping[str, Any],
    *,
    control: Mapping[str, Any],
) -> None:
    immutable = control.get("immutable")
    if not isinstance(immutable, Mapping):
        raise ControlError(
            "external-watchdog deployment cannot bind a missing immutable release"
        )
    try:
        capacity_authority = effective_protected_capacity_binding(
            control, verify_files=True
        )
        capacity_contract = _load_protected_capacity_contract(
            control,
            path=capacity_authority["path"],
            expected_marker_id=str(capacity_authority["marker_id"]),
            expected_sha256=str(capacity_authority["sha256"]),
        )
    except (
        KeyError,
        protected_capacity.ProtectedCapacityError,
    ) as exc:
        raise ControlError(
            "external-watchdog deployment cannot verify the release tag object"
        ) from exc
    required = {
        "schema_version",
        "protocol",
        "passed",
        "release_id",
        "release_tag",
        "release_git_commit",
        "release_tag_object",
        "chain_namespace",
        "deployment_id",
        "watchdog_code_sha256",
        "immutable_release_sha256",
        "control_sha256",
        "liveness_email",
        "forced_command_only",
        "timer_seconds",
        "systemd_service_loaded",
        "systemd_timer_active",
        "systemd_timer_enabled",
        "evidence_id",
    }
    if (
        set(value) != required
        or value.get("schema_version") != 1
        or value.get("protocol")
        != "schema5-external-watchdog-deployment-evidence-v1"
        or value.get("passed") is not True
        or value.get("release_id") != PRODUCTION_RELEASE_ID
        or value.get("release_tag") != PRODUCTION_OPERATIONAL_TAG
        or value.get("release_git_commit") != control["immutable"]["git_commit"]
        or value.get("release_tag_object")
        != capacity_contract.release_tag_object
        or value.get("chain_namespace") != "schema5-v1.2-r13"
        or value.get("control_sha256") != control["immutable_sha256"]
        or value.get("liveness_email") != control["alert_email"]
        or value.get("forced_command_only") is not True
        or value.get("timer_seconds") != 300
        or value.get("systemd_service_loaded") is not True
        or value.get("systemd_timer_active") is not True
        or value.get("systemd_timer_enabled") is not True
        or any(
            _SHA256_RE.fullmatch(str(value.get(field, ""))) is None
            for field in (
                "deployment_id",
                "watchdog_code_sha256",
                "immutable_release_sha256",
                "control_sha256",
                "evidence_id",
            )
        )
        or value.get("evidence_id")
        != _watchdog_self_hash(value, "evidence_id")
    ):
        raise ControlError(
            "external-watchdog deployment evidence is not bound to paused control"
        )


def _validate_external_watchdog_intent(value: Mapping[str, Any]) -> None:
    required = {
        "schema_version",
        "protocol",
        "intent_id",
        "drill_id",
        "immutable_sha256",
        "deployment",
        "baseline",
        "baseline_sha256",
        "namespace",
        "created_at",
        "created_timestamp",
        "expires_at",
        "expires_timestamp",
        "maximum_recovery_seconds",
    }
    namespace = value.get("namespace")
    deployment = value.get("deployment")
    if (
        set(value) != required
        or value.get("schema_version") != 1
        or value.get("protocol") != EXTERNAL_WATCHDOG_DRILL_PROTOCOL
        or _SHA256_RE.fullmatch(str(value.get("intent_id", ""))) is None
        or value.get("intent_id") != _watchdog_self_hash(value, "intent_id")
        or not isinstance(value.get("drill_id"), str)
        or not value["drill_id"]
        or _SHA256_RE.fullmatch(str(value.get("immutable_sha256", ""))) is None
        or not isinstance(deployment, dict)
        or set(deployment)
        != {
            "path",
            "sha256",
            "evidence_id",
            "deployment_id",
            "watchdog_code_sha256",
            "immutable_release_sha256",
            "control_sha256",
            "release_git_commit",
            "release_tag_object",
        }
        or not Path(str(deployment.get("path", ""))).is_absolute()
        or any(
            _SHA256_RE.fullmatch(str(deployment.get(field, ""))) is None
            for field in (
                "sha256",
                "evidence_id",
                "deployment_id",
                "watchdog_code_sha256",
                "immutable_release_sha256",
                "control_sha256",
            )
        )
        or re.fullmatch(
            r"[0-9a-f]{40}", str(deployment.get("release_git_commit", ""))
        )
        is None
        or re.fullmatch(
            r"[0-9a-f]{40}", str(deployment.get("release_tag_object", ""))
        )
        is None
        or not isinstance(value.get("baseline"), dict)
        or value.get("baseline_sha256") != sha256_value(value["baseline"])
        or not isinstance(namespace, list)
        or len(namespace) != 4
        or not isinstance(value.get("created_timestamp"), (int, float))
        or isinstance(value.get("created_timestamp"), bool)
        or not isinstance(value.get("expires_timestamp"), (int, float))
        or isinstance(value.get("expires_timestamp"), bool)
        or not float(value["created_timestamp"])
        < float(value["expires_timestamp"])
        or value.get("maximum_recovery_seconds")
        != EXTERNAL_WATCHDOG_DRILL_MAX_RECOVERY_SECONDS
    ):
        raise ControlError("external-watchdog drill intent is malformed")
    if (
        deployment["control_sha256"] != value["immutable_sha256"]
        or value["baseline"].get("immutable_sha256")
        != value["immutable_sha256"]
    ):
        raise ControlError(
            "external-watchdog drill intent identities do not agree"
        )
    identities: set[tuple[str, str]] = set()
    job_ids: set[str] = set()
    for record in namespace:
        parsed_token = (
            parse_drill_job_token(str(record.get("job_token", "")))
            if isinstance(record, dict)
            else None
        )
        if (
            not isinstance(record, dict)
            or set(record)
            != {
                "role",
                "target",
                "job_id",
                "job_token",
                "sbatch_path",
                "sbatch_sha256",
                "submission_transport",
                "submission_argv",
                "submission_argv_sha256",
                "persistent_hold",
                "spooled_receipt_path",
                "spooled_receipt_sha256",
                "released_at",
                "released_timestamp",
                "dependency_job_id",
            }
            or record.get("role") not in ROLE_NAMES
            or record.get("target") not in {"active", "successor"}
            or not str(record.get("job_id", "")).isdigit()
            or not isinstance(record.get("job_token"), str)
            or parsed_token is None
            or parsed_token.get("drill") != value["drill_id"]
            or parsed_token.get("role") != record.get("role")
            or not Path(str(record.get("sbatch_path", ""))).is_absolute()
            or _SHA256_RE.fullmatch(str(record.get("sbatch_sha256", "")))
            is None
            or record.get("submission_transport")
            != EXACT_SBATCH_SUBMISSION_TRANSPORT
            or record.get("submission_argv")
            != _exact_sbatch_submission_argv(
                token=str(record.get("job_token", "")),
                dependency_job_id=(
                    str(record["dependency_job_id"])
                    if record.get("dependency_job_id") is not None
                    else None
                ),
            )
            or record.get("submission_argv_sha256")
            != _submission_argv_sha256(record.get("submission_argv", []))
            or record.get("persistent_hold") is not False
            or not Path(
                str(record.get("spooled_receipt_path", ""))
            ).is_absolute()
            or _SHA256_RE.fullmatch(
                str(record.get("spooled_receipt_sha256", ""))
            )
            is None
            or not isinstance(record.get("released_timestamp"), (int, float))
            or isinstance(record.get("released_timestamp"), bool)
            or record.get("released_at")
            != utc_timestamp(float(record.get("released_timestamp", -1)))
            or (
                record["target"] == "active"
                and record.get("dependency_job_id") is not None
            )
            or (
                record["target"] == "successor"
                and not str(record.get("dependency_job_id", "")).isdigit()
            )
        ):
            raise ControlError(
                "external-watchdog drill namespace record is malformed"
            )
        identities.add((str(record["role"]), str(record["target"])))
        job_ids.add(str(record["job_id"]))
    if identities != {
        (role, target)
        for role in ROLE_NAMES
        for target in ("active", "successor")
    } or len(job_ids) != 4:
        raise ControlError(
            "external-watchdog drill namespace is incomplete or duplicated"
        )
    by_identity = {
        (str(record["role"]), str(record["target"])): record
        for record in namespace
    }
    if any(
        str(by_identity[(role, "successor")]["dependency_job_id"])
        != str(by_identity[(role, "active")]["job_id"])
        for role in ROLE_NAMES
    ):
        raise ControlError(
            "external-watchdog successors do not bind their exact active parents"
        )


def _validate_external_watchdog_state(
    value: Mapping[str, Any], *, intent: Mapping[str, Any]
) -> None:
    required = {
        "schema_version",
        "protocol",
        "intent_id",
        "phase",
        "revision",
        "cancellation_started_at",
        "cancellation_started_timestamp",
        "cancellation_results",
        "observations",
        "repair_attempts",
        "recovery",
        "completion_evidence",
        "last_error",
    }
    if (
        set(value) != required
        or value.get("schema_version") != 1
        or value.get("protocol") != EXTERNAL_WATCHDOG_DRILL_STATE_PROTOCOL
        or value.get("intent_id") != intent["intent_id"]
        or value.get("phase")
        not in {
            "armed",
            "cancelling",
            "cancelled",
            "recovering",
            "recovered",
            "complete",
            "expired",
        }
        or not isinstance(value.get("revision"), int)
        or isinstance(value.get("revision"), bool)
        or value["revision"] < 0
        or not isinstance(value.get("cancellation_results"), dict)
        or not isinstance(value.get("observations"), list)
        or not isinstance(value.get("repair_attempts"), int)
        or isinstance(value.get("repair_attempts"), bool)
        or value["repair_attempts"] < 0
    ):
        raise ControlError("external-watchdog drill state is malformed")
    for key, result in value["cancellation_results"].items():
        if (
            not isinstance(key, str)
            or not key.isdigit()
            or not isinstance(result, dict)
            or result.get("job_id") != key
            or result.get("state")
            not in {"accepted", "cancelled_reconciled_terminal"}
        ):
            raise ControlError(
                "external-watchdog cancellation result is malformed"
            )
    previous_timestamp: float | None = None
    for observation in value["observations"]:
        if (
            not isinstance(observation, dict)
            or set(observation)
            != {
                "schema_version",
                "intent_id",
                "captured_at",
                "captured_timestamp",
                "namespace_absent",
                "scheduler_sha256",
                "observation_id",
            }
            or observation.get("schema_version") != 1
            or observation.get("intent_id") != intent["intent_id"]
            or observation.get("namespace_absent") is not True
            or not isinstance(observation.get("captured_timestamp"), (int, float))
            or isinstance(observation.get("captured_timestamp"), bool)
            or _SHA256_RE.fullmatch(
                str(observation.get("scheduler_sha256", ""))
            )
            is None
            or observation.get("observation_id")
            != _watchdog_self_hash(observation, "observation_id")
        ):
            raise ControlError(
                "external-watchdog scheduler observation is malformed"
            )
        observed = float(observation["captured_timestamp"])
        if previous_timestamp is not None and observed <= previous_timestamp:
            raise ControlError(
                "external-watchdog observations are not strictly ordered"
            )
        previous_timestamp = observed


def _load_external_watchdog_drill(
    state_dir: Path,
) -> tuple[dict[str, Any], dict[str, Any]] | None:
    intent_path = _external_watchdog_drill_intent_path(state_dir)
    state_path = _external_watchdog_drill_state_path(state_dir)
    if not intent_path.exists() and not intent_path.is_symlink():
        if state_path.exists() or state_path.is_symlink():
            raise ControlError(
                "external-watchdog drill state exists without marker-first intent"
            )
        return None
    intent, _ = _read_stable_json(
        intent_path,
        description="external-watchdog drill intent",
        require_read_only=True,
    )
    _validate_external_watchdog_intent(intent)
    state, _ = _read_stable_json(
        state_path,
        description="external-watchdog drill state",
        require_read_only=False,
    )
    _validate_external_watchdog_state(state, intent=intent)
    return intent, state


def _external_watchdog_fences_drill_claims(state_dir: Path) -> bool:
    """Fail closed while the exact four-job namespace is frozen/cancelled."""

    intent_path = _external_watchdog_drill_intent_path(state_dir)
    state_path = _external_watchdog_drill_state_path(state_dir)
    if not intent_path.exists() and not intent_path.is_symlink():
        return False
    if not state_path.exists() and not state_path.is_symlink():
        return True
    loaded = _load_external_watchdog_drill(state_dir)
    if loaded is None:  # pragma: no cover - guarded by the marker check above.
        return False
    return loaded[1]["phase"] in {"armed", "cancelling", "cancelled"}


def _save_external_watchdog_state(
    state_dir: Path, value: MutableMapping[str, Any], *, intent: Mapping[str, Any]
) -> None:
    value["revision"] = int(value.get("revision", -1)) + 1
    _validate_external_watchdog_state(value, intent=intent)
    _atomic_write_json(_external_watchdog_drill_state_path(state_dir), value)


def _append_drill_event(
    state_dir: Path,
    state: MutableMapping[str, Any],
    *,
    event: str,
    details: Mapping[str, Any] | None = None,
    now: float,
) -> None:
    durable = _read_jsonl_locked(state_dir / DRILL_JOURNAL_FILENAME, missing_ok=True)
    memory = list(state.get("transition_history", []))
    if durable[: len(memory)] != memory:
        raise ControlError("controller-drill journal diverged from its state")
    if len(durable) > len(memory):
        state["transition_history"] = copy.deepcopy(durable)
        validate_transition_history(state)
    record = _history_record(state, event=event, details=details, now=now)
    state.setdefault("transition_history", []).append(record)
    _append_jsonl(state_dir / DRILL_JOURNAL_FILENAME, record)


def _validate_drill_state(state: Mapping[str, Any]) -> None:
    if (
        state.get("schema_version") != 1
        or state.get("protocol") != "schema5-controller-drill-v1"
    ):
        raise ControlError("controller-drill state has an unsupported schema")
    if not isinstance(state.get("drill_id"), str) or not state["drill_id"]:
        raise ControlError("controller-drill state has no drill ID")
    if state.get("shared_fencing_primitive") != SHARED_CONTROLLER_FENCING_PRIMITIVE:
        raise ControlError(
            "controller-drill state has the wrong shared fencing primitive"
        )
    if (
        state.get("shared_controller_primitives")
        != shared_controller_primitive_contract()
    ):
        raise ControlError(
            "controller-drill state has the wrong shared primitive contract"
        )
    if state.get("phase") not in {"running", "stopping", "completed"}:
        raise ControlError("controller-drill phase is invalid")
    if state.get("phase") == "completed":
        if (
            not isinstance(state.get("final_reconciliation_path"), str)
            or _SHA256_RE.fullmatch(str(state.get("final_reconciliation_sha256", "")))
            is None
        ):
            raise ControlError(
                "completed controller-drill reconciliation proof is missing"
            )
    elif (
        state.get("final_reconciliation_path") is not None
        or state.get("final_reconciliation_sha256") is not None
    ):
        raise ControlError(
            "unfinished controller drill cannot carry final reconciliation"
        )
    if not isinstance(state.get("immutable_sha256"), str):
        raise ControlError("controller-drill immutable identity is missing")
    roles = state.get("roles")
    if not isinstance(roles, dict) or set(roles) != set(ROLE_NAMES):
        raise ControlError("controller-drill role state is incomplete")
    for role, row in roles.items():
        if not isinstance(row, dict) or set(row) != {
            "next_generation",
            "active",
            "successor",
            "submission_intent",
            "heartbeat",
            "last_exit",
            "kill",
            "recovery",
        }:
            raise ControlError(f"controller-drill role state is malformed: {role}")
        if not isinstance(row["next_generation"], int) or row["next_generation"] < 1:
            raise ControlError(f"controller-drill next generation is invalid: {role}")
    if not isinstance(state.get("baseline"), dict):
        raise ControlError("controller-drill baseline is missing")
    validate_transition_history(state)


def load_drill_state(state_dir: Path) -> dict[str, Any]:
    path = _drill_state_path(state_dir)
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ControlError(f"controller drill has not been started: {path}") from exc
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ControlError(f"cannot read controller-drill state {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise ControlError("controller-drill state must be a JSON object")
    _validate_drill_state(value)
    durable = _read_jsonl_locked(state_dir / DRILL_JOURNAL_FILENAME)
    if durable[: len(value["transition_history"])] != value["transition_history"]:
        raise ControlError("controller-drill state is not a prefix of its journal")
    return value


def _save_drill_state(
    state_dir: Path, state: MutableMapping[str, Any], *, now: float
) -> None:
    state["updated_at"] = utc_timestamp(now)
    state["updated_timestamp"] = now
    _validate_drill_state(state)
    _atomic_write_json(_drill_state_path(state_dir), state)


def _optional_file_identity(path: Path) -> dict[str, Any]:
    if not path.exists():
        return {"exists": False, "sha256": None}
    if path.is_symlink() or not path.is_file():
        raise ControlError(f"drill baseline target is not a regular file: {path}")
    return {"exists": True, "sha256": sha256_file(path)}


def controller_drill_baseline(
    state_dir: Path, control: Mapping[str, Any]
) -> dict[str, Any]:
    """Hash every production-owned state surface a no-admission drill may not alter."""

    run_trees = {
        str(run["run_id"]): sha256_tree(Path(str(run["run_root"])).resolve())
        for run in control["immutable"]["runs"]
    }
    projection = {
        "rollout_generation": control["rollout_generation"],
        "admission": control["admission"],
        "throughput_epochs": control["throughput_epochs"],
        "resume_intent": control["resume_intent"],
        "drain_requested": control["drain_requested"],
        "controllers": control["controllers"],
    }
    return {
        "immutable_sha256": control["immutable_sha256"],
        "production_state_sha256": sha256_value(projection),
        "dispatcher_ledger": _optional_file_identity(state_dir / "ledger.json"),
        "run_tree_sha256": run_trees,
    }


def _assert_drill_control_paused(
    state_dir: Path, *, expected_immutable_sha256: str | None = None
) -> dict[str, Any]:
    control = load_control(state_dir, verify_files=True)
    if control["desired_state"] != "paused" or control.get("drain_requested"):
        raise ControlError(
            "controller kill drill requires desired_state=paused without a drain intent"
        )
    if (
        expected_immutable_sha256
        and control["immutable_sha256"] != expected_immutable_sha256
    ):
        raise ImmutablePinError("controller-drill immutable pins differ from control")
    if any(
        role_state.get(field) is not None
        for role_state in control["controllers"].values()
        for field in ("active", "successor", "submission_intent")
    ):
        raise ControlError(
            "controller kill drill requires empty production controller state"
        )
    return control


def _render_drill_sbatch(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    drill_id: str,
    role: str,
    generation: int,
    intent_token: str,
) -> Path:
    token = drill_job_token(drill_id, role, generation, intent_token)
    short = ROLE_SHORT[role]
    target_dir = state_dir / "drills" / drill_id / "sbatch"
    target_dir.mkdir(parents=True, exist_ok=True)
    target = target_dir / f"{short}.g{generation:06d}.{intent_token}.sbatch"
    python = Path(control["immutable"]["harness_environment_prefix"]) / "bin" / "python"
    script = (
        Path(control["immutable"]["release_worktree"]) / "slurm" / "schema5_control.py"
    )
    log_path = (
        state_dir / "drills" / drill_id / "logs" / f"{short}.g{generation:06d}.%j.out"
    )
    log_path.parent.mkdir(parents=True, exist_ok=True)
    argv = [
        str(python),
        "-I",
        "-u",
        str(script),
        "--state-dir",
        str(state_dir.resolve()),
        "supervise-drill",
        "--drill-id",
        drill_id,
        "--role",
        role,
        "--generation",
        str(generation),
        "--intent-token",
        intent_token,
    ]
    payload = "\n".join(
        [
            "#!/bin/bash",
            f"#SBATCH --job-name=asys-s5-drill-{short}-{generation:06d}",
            f"#SBATCH --comment={token}",
            f"#SBATCH --partition={PRODUCTION_CONTROLLER_PARTITION}",
            "#SBATCH --cpus-per-task=1",
            "#SBATCH --mem=4G",
            "#SBATCH --time=01:00:00",
            "#SBATCH --no-requeue",
            "#SBATCH --export=NONE",
            f"#SBATCH --output={log_path}",
            "set -euo pipefail",
            "umask 027",
            _trusted_shell_prelude().rstrip(),
            "unset PYTHONHOME PYTHONPATH VIRTUAL_ENV CONDA_PREFIX CONDA_DEFAULT_ENV",
            "export PYTHONDONTWRITEBYTECODE=1",
            "export PYTHONNOUSERSITE=1",
            "export PYTHONSAFEPATH=1",
            "export HF_HUB_OFFLINE=1",
            "export TRANSFORMERS_OFFLINE=1",
            "export HF_DATASETS_OFFLINE=1",
            "exec " + " ".join(shlex.quote(item) for item in argv),
            "",
        ]
    )
    _validate_trusted_sbatch_bootstrap(
        payload, description="controller kill-drill sbatch"
    )
    if target.exists() or target.is_symlink():
        if (
            target.is_symlink()
            or not target.is_file()
            or target.stat().st_nlink != 1
            or target.stat().st_mode & 0o222
            or target.read_text(encoding="utf-8") != payload
        ):
            raise ImmutablePinError(
                f"drill sbatch already exists with different bytes: {target}"
            )
        return target
    _atomic_publish_readonly_text(target, payload)
    return target


def _drill_token_jobs(snapshot: SchedulerSnapshot, token: str) -> list[SchedulerJob]:
    return [job for job in snapshot.jobs if job.comment == token]


def _command_binds_exact_sbatch(command: str, sbatch_path: str) -> bool:
    """Return whether scheduler command provenance contains the exact sbatch argument."""

    try:
        return sbatch_path in shlex.split(command)
    except ValueError:
        return False


def _dependency_binds_exact_afterany(dependency: str, parent_job_id: str) -> bool:
    """Accept only the one Slurm after-any edge frozen for a successor."""

    if not parent_job_id.isdigit():
        return False
    return (
        re.fullmatch(
            rf"afterany:{re.escape(parent_job_id)}(?:\([^()]*\))?",
            dependency.strip(),
        )
        is not None
    )


def _all_live_drill_jobs(snapshot: SchedulerSnapshot) -> list[SchedulerJob]:
    """Return every live row claiming the drill namespace, parsed or malformed.

    Namespace emptiness is a scheduler safety property, not a parser convenience.  A
    malformed comment must therefore fence start/resume/finish just as strongly as a
    well-formed but unmapped drill token.
    """

    return [
        job
        for job in snapshot.jobs
        if job.active and job.comment.startswith(DRILL_TOKEN_PREFIX)
    ]


def _unique_exact_drill_job(
    snapshot: SchedulerSnapshot,
    *,
    job_id: str,
    job_token: str,
    sbatch_path: str,
    require_active: bool | None,
    expected_dependency_job_id: str | None = None,
    record: Mapping[str, Any] | None = None,
) -> SchedulerJob:
    """Resolve one drill allocation and bind its immutable stdin/spool proof."""

    token_matches = _drill_token_jobs(snapshot, job_token)
    if len(token_matches) != 1:
        raise SchedulerAmbiguity(
            f"drill token must map to exactly one scheduler job; found "
            f"{[job.job_id for job in token_matches]}"
        )
    job = token_matches[0]
    if job.job_id != str(job_id):
        raise SchedulerAmbiguity(
            f"drill token maps to job {job.job_id}, not recorded exact job {job_id}"
        )
    if record is None:
        raise SchedulerAmbiguity(
            f"drill job {job_id} lacks its exact held-stdin submission record"
        )
    if (
        str(record.get("job_id", "")) != str(job_id)
        or str(record.get("job_token", "")) != job_token
        or str(Path(str(record.get("sbatch_path", ""))).resolve())
        != str(Path(sbatch_path).resolve())
        or record.get("dependency_job_id") != expected_dependency_job_id
    ):
        raise SchedulerAmbiguity(
            f"drill job {job_id} durable submission identity drifted"
        )
    _validate_exact_sbatch_record_proof(
        record,
        job_id=str(job_id),
        context=f"drill job {job_id}",
    )
    if expected_dependency_job_id is not None and not _dependency_binds_exact_afterany(
        job.dependency, expected_dependency_job_id
    ):
        raise SchedulerAmbiguity(
            f"drill job {job_id} dependency {job.dependency!r} does not bind exact "
            f"afterany parent {expected_dependency_job_id}"
        )
    if require_active is True and not job.active:
        raise SchedulerAmbiguity(f"drill job {job_id} is not active")
    if require_active is False and job.active:
        raise SchedulerAmbiguity(f"drill job {job_id} is still active")
    return job


def _reconcile_stopping_drill_intents(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    now: float,
) -> None:
    """Adopt or close every pre-stop submission intent under complete scheduler truth."""

    if not snapshot.squeue_ok or not snapshot.sacct_ok:
        raise SchedulerAmbiguity(
            "stopping drill intent reconciliation requires full truth"
        )
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        if state["phase"] not in {"stopping", "completed"}:
            raise ControlError(
                "stopping-intent reconciliation requires a stopping drill"
            )
        changed = False
        for role, row in state["roles"].items():
            intent = row.get("submission_intent")
            if not isinstance(intent, dict):
                continue
            token = str(intent.get("job_token", ""))
            matches = _drill_token_jobs(snapshot, token)
            if len(matches) > 1:
                raise SchedulerAmbiguity(
                    f"stopping {role} intent maps to duplicate jobs: "
                    f"{[job.job_id for job in matches]}"
                )
            target = str(intent.get("target", ""))
            if target not in {"active", "successor"}:
                raise ControlError(
                    f"stopping {role} intent has invalid target {target!r}"
                )
            if matches:
                job = matches[0]
                proof = _prove_exact_sbatch_and_release(
                    state_dir,
                    record=intent,
                    job_id=job.job_id,
                    submit_runner=_run_subprocess,
                    release_after_proof=True,
                    now=now,
                    scheduler_job=job,
                )
                intent.update(proof)
                expected_parent = intent.get("dependency_job_id")
                intent["job_id"] = job.job_id
                _unique_exact_drill_job(
                    snapshot,
                    job_id=job.job_id,
                    job_token=str(intent["job_token"]),
                    sbatch_path=str(intent["sbatch_path"]),
                    require_active=None,
                    expected_dependency_job_id=(
                        str(expected_parent)
                        if expected_parent is not None
                        else None
                    ),
                    record=intent,
                )
                existing = row.get(target)
                if isinstance(existing, dict) and existing.get(
                    "intent_token"
                ) != intent.get("intent_token"):
                    raise SchedulerAmbiguity(
                        f"stopping {role} intent would overwrite another {target}"
                    )
                intent["state"] = "submitted"
                intent["job_id"] = job.job_id
                intent["adopted_from_scheduler"] = True
                row[target] = copy.deepcopy(intent)
                event = "stopping_submission_adopted"
                details = {"role": role, "target": target, "job_id": job.job_id}
            else:
                age = now - float(intent.get("created_timestamp", now))
                if (
                    not intent.get("last_submission_rejected", False)
                    and age < SUBMISSION_VISIBILITY_GRACE_SECONDS
                ):
                    raise SchedulerVisibilityPending(
                        f"stopping {role} intent remains inside scheduler visibility grace "
                        f"({max(0.0, age):.1f}s/{SUBMISSION_VISIBILITY_GRACE_SECONDS:.1f}s)"
                    )
                event = "stopping_submission_closed_absent"
                details = {"role": role, "target": target, "age_seconds": age}
            row["submission_intent"] = None
            row["next_generation"] = max(
                int(row["next_generation"]), int(intent.get("generation", 0)) + 1
            )
            _append_drill_event(
                state_dir,
                state,
                event=event,
                details=details,
                now=now,
            )
            changed = True
        if changed:
            _save_drill_state(state_dir, state, now=now)


def submit_drill_intent(
    state_dir: Path,
    *,
    role: str,
    target: str,
    dependency_job_id: str | None,
    scheduler: SchedulerSnapshot,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Transactionally submit or adopt one no-op drill controller intent."""

    # This boundary is intentionally outside ``drill_lock`` and spans ``sbatch``.  The
    # finish path acquires it before changing the phase to ``stopping``, which rules out
    # a late accepted successor appearing after the completion marker.
    with drill_submission_boundary_lock(state_dir):
        return _submit_drill_intent_inside_boundary(
            state_dir,
            role=role,
            target=target,
            dependency_job_id=dependency_job_id,
            scheduler=scheduler,
            submit_runner=submit_runner,
            now=now,
        )


def _submit_drill_intent_inside_boundary(
    state_dir: Path,
    *,
    role: str,
    target: str,
    dependency_job_id: str | None,
    scheduler: SchedulerSnapshot,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Implementation of :func:`submit_drill_intent` with its boundary held."""

    _validate_role(role)
    if target not in {"active", "successor"}:
        raise ControlError("drill intent target must be active or successor")
    if not scheduler.squeue_ok or not scheduler.sacct_ok:
        raise SchedulerAmbiguity(
            "drill submission requires complete squeue+sacct truth"
        )
    timestamp = time.time() if now is None else float(now)
    runner = submit_runner or _run_subprocess
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        _assert_drill_control_paused(
            state_dir, expected_immutable_sha256=state["immutable_sha256"]
        )
        if _external_watchdog_fences_drill_claims(state_dir):
            raise ControllerFenced(
                "external-watchdog drill froze this exact controller namespace"
            )
        if state["phase"] != "running":
            raise ControlError("controller-drill submission is disabled while stopping")
        row = state["roles"][role]
        current = row.get(target)
        if isinstance(current, dict) and current.get("job_id"):
            matches = [
                job
                for job in scheduler.jobs
                if job.job_id == str(current["job_id"])
                and job.comment == current.get("job_token")
            ]
            if len(matches) > 1:
                raise SchedulerAmbiguity("drill job ID appears more than once")
            wrong_token = [
                job
                for job in scheduler.jobs
                if job.job_id == str(current["job_id"])
                and job.comment != current.get("job_token")
            ]
            if wrong_token:
                raise SchedulerAmbiguity("drill job ID has a scheduler token mismatch")
            if matches and matches[0].active:
                _unique_exact_drill_job(
                    scheduler,
                    job_id=str(current["job_id"]),
                    job_token=str(current["job_token"]),
                    sbatch_path=str(current["sbatch_path"]),
                    require_active=True,
                    expected_dependency_job_id=(
                        str(current["dependency_job_id"])
                        if current.get("dependency_job_id") is not None
                        else None
                    ),
                    record=current,
                )
                return copy.deepcopy(current)
            if matches:
                row[target] = None
            else:
                age = timestamp - float(
                    current.get(
                        "submitted_timestamp",
                        current.get("created_timestamp", timestamp),
                    )
                )
                if age < SUBMISSION_VISIBILITY_GRACE_SECONDS:
                    raise SchedulerVisibilityPending(
                        "recorded drill job is inside scheduler visibility grace"
                    )
                raise SchedulerAmbiguity(
                    f"accepted drill job {current['job_id']} disappeared from complete "
                    "squeue+sacct truth; refusing a duplicate replacement"
                )
        intent = row.get("submission_intent")
        if isinstance(intent, dict):
            matches = _drill_token_jobs(scheduler, str(intent["job_token"]))
            if len(matches) > 1:
                raise SchedulerAmbiguity("drill intent maps to multiple scheduler jobs")
            if len(matches) == 1 and matches[0].active:
                proof = _prove_exact_sbatch_and_release(
                    state_dir,
                    record=intent,
                    job_id=matches[0].job_id,
                    submit_runner=runner,
                    release_after_proof=True,
                    now=timestamp,
                    scheduler_job=matches[0],
                )
                intent.update(proof)
                intent["job_id"] = matches[0].job_id
                _unique_exact_drill_job(
                    scheduler,
                    job_id=matches[0].job_id,
                    job_token=str(intent["job_token"]),
                    sbatch_path=str(intent["sbatch_path"]),
                    require_active=True,
                    expected_dependency_job_id=(
                        str(intent["dependency_job_id"])
                        if intent.get("dependency_job_id") is not None
                        else None
                    ),
                    record=intent,
                )
                intent["state"] = "submitted"
                intent["adopted_from_scheduler"] = True
                row[str(intent["target"])] = copy.deepcopy(intent)
                row["submission_intent"] = None
                row["next_generation"] = max(
                    int(row["next_generation"]), int(intent["generation"]) + 1
                )
                _append_drill_event(
                    state_dir,
                    state,
                    event="submission_adopted",
                    details={"role": role, "job_id": matches[0].job_id},
                    now=timestamp,
                )
                _save_drill_state(state_dir, state, now=timestamp)
                return copy.deepcopy(intent)
            if matches:
                row["submission_intent"] = None
                row["next_generation"] = max(
                    int(row["next_generation"]), int(intent["generation"]) + 1
                )
                intent = None
            elif (
                not intent.get("last_submission_rejected", False)
                and timestamp - float(intent["created_timestamp"])
                < SUBMISSION_VISIBILITY_GRACE_SECONDS
            ):
                raise SchedulerVisibilityPending(
                    "drill submission is inside visibility grace"
                )
        if not isinstance(intent, dict):
            generation = int(row["next_generation"])
            intent_token = uuid.uuid4().hex
            token = drill_job_token(state["drill_id"], role, generation, intent_token)
            sbatch_path = _render_drill_sbatch(
                state_dir,
                load_control(state_dir),
                drill_id=state["drill_id"],
                role=role,
                generation=generation,
                intent_token=intent_token,
            )
            intent = {
                "state": "submitting",
                "role": role,
                "target": target,
                "generation": generation,
                "intent_token": intent_token,
                "job_token": token,
                "sbatch_path": str(sbatch_path),
                "sbatch_sha256": sha256_file(sbatch_path),
                "submission_transport": EXACT_SBATCH_SUBMISSION_TRANSPORT,
                "submission_argv": _exact_sbatch_submission_argv(
                    token=token,
                    dependency_job_id=dependency_job_id,
                ),
                "submission_argv_sha256": None,
                "persistent_hold": False,
                "spooled_receipt_path": None,
                "spooled_receipt_sha256": None,
                "released_at": None,
                "released_timestamp": None,
                "dependency_job_id": dependency_job_id,
                "controller_primitives": shared_controller_primitive_contract(),
                "created_at": utc_timestamp(timestamp),
                "created_timestamp": timestamp,
                "attempts": 0,
            }
            intent["submission_argv_sha256"] = _submission_argv_sha256(
                intent["submission_argv"]
            )
            row["submission_intent"] = intent
            _append_drill_event(
                state_dir,
                state,
                event="submission_intent",
                details={"role": role, "target": target, "generation": generation},
                now=timestamp,
            )
            _save_drill_state(state_dir, state, now=timestamp)
        intent_copy = copy.deepcopy(intent)
    sbatch_payload = _stable_readonly_preimage(
        Path(str(intent_copy["sbatch_path"])),
        description="controller-drill sbatch at exact submission boundary",
    )
    if (
        hashlib.sha256(sbatch_payload).hexdigest()
        != intent_copy["sbatch_sha256"]
    ):
        raise ImmutablePinError(
            "controller-drill sbatch changed before exact submission"
        )
    proc = runner(
        _ExactSbatchInvocation(
            intent_copy["submission_argv"],
            sbatch_payload,
        )
    )
    completed = time.time() if now is None else timestamp
    raw_job_id = proc.stdout.strip().split(";", 1)[0]
    proof: dict[str, Any] | None = None
    if proc.returncode == 0 and raw_job_id.isdigit():
        proof = _prove_exact_sbatch_and_release(
            state_dir,
            record=intent_copy,
            job_id=raw_job_id,
            submit_runner=runner,
            release_after_proof=True,
            now=completed,
        )
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        _assert_drill_control_paused(
            state_dir, expected_immutable_sha256=state["immutable_sha256"]
        )
        if _external_watchdog_fences_drill_claims(state_dir):
            raise ControllerFenced(
                "external-watchdog drill froze this exact controller namespace"
            )
        row = state["roles"][role]
        current = row.get("submission_intent")
        if (
            not isinstance(current, dict)
            or current.get("intent_token") != intent_copy["intent_token"]
        ):
            raise SchedulerAmbiguity("drill submission intent changed during sbatch")
        current["attempts"] = int(current.get("attempts", 0)) + 1
        if proc.returncode != 0:
            current["last_submission_rejected"] = True
            current["last_error"] = proc.stderr.strip()[:1000]
            _save_drill_state(state_dir, state, now=completed)
            raise ControlError(
                f"sbatch rejected drill intent: {current['last_error'][:500]}"
            )
        job_id = raw_job_id
        if not job_id.isdigit():
            raise SchedulerAmbiguity(f"sbatch returned invalid drill job ID {job_id!r}")
        if proof is None:
            raise SchedulerAmbiguity(
                "accepted controller-drill job lacks exact spool/release proof"
            )
        current.update(proof)
        current["state"] = "submitted"
        current["job_id"] = job_id
        current["submitted_at"] = utc_timestamp(completed)
        current["submitted_timestamp"] = completed
        row[target] = copy.deepcopy(current)
        row["submission_intent"] = None
        row["next_generation"] = max(
            int(row["next_generation"]), int(current["generation"]) + 1
        )
        late_for_cleanup = state["phase"] != "running"
        _append_drill_event(
            state_dir,
            state,
            event=(
                "late_submission_committed_for_cleanup"
                if late_for_cleanup
                else "submitted"
            ),
            details={"role": role, "target": target, "job_id": job_id},
            now=completed,
        )
        _save_drill_state(state_dir, state, now=completed)
        result = copy.deepcopy(current)
    if late_for_cleanup:
        raise ControlError(
            f"drill submission {job_id} was accepted after stopping and is committed for cleanup"
        )
    return result


def start_controller_drill(
    state_dir: Path,
    *,
    scheduler: SchedulerSnapshot,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    timestamp = time.time() if now is None else float(now)
    control = _assert_drill_control_paused(state_dir)
    validate_readiness(
        control, state_dir=state_dir, verify_files=True, now=timestamp
    )
    if not scheduler.squeue_ok or not scheduler.sacct_ok:
        raise SchedulerAmbiguity("controller drill requires complete scheduler truth")
    active_production = [
        job.job_id for job in _scoped_control_jobs(scheduler) if job.active
    ]
    if active_production:
        raise SchedulerAmbiguity(
            f"controller drill found live production controller jobs: {active_production}"
        )
    live_drill_rows = _all_live_drill_jobs(scheduler)
    live_drills = [job.job_id for job in live_drill_rows]
    malformed_drills = [
        job.job_id
        for job in live_drill_rows
        if parse_drill_job_token(job.comment) is None
    ]
    if malformed_drills:
        raise SchedulerAmbiguity(
            "malformed live controller-drill namespace jobs: "
            + ", ".join(sorted(malformed_drills))
        )
    path = _drill_state_path(state_dir)
    if path.exists():
        state = load_drill_state(state_dir)
        if state["phase"] == "completed":
            if live_drills:
                raise SchedulerAmbiguity(
                    f"completed controller drill still has live jobs: {sorted(live_drills)}"
                )
            validate_controller_drill_marker(
                state_dir,
                control,
                require_current_baseline=int(control["rollout_generation"]) == 0,
            )
            return state
        if live_drills and any(
            parse_drill_job_token(job.comment).get("drill") != state["drill_id"]
            for job in scheduler.jobs
            if job.active and parse_drill_job_token(job.comment) is not None
        ):
            raise SchedulerAmbiguity("another controller drill is live")
    else:
        if live_drills:
            raise SchedulerAmbiguity("unmapped controller-drill jobs are live")
        drill_id = uuid.uuid4().hex
        state = {
            "schema_version": 1,
            "protocol": "schema5-controller-drill-v1",
            "drill_id": drill_id,
            "shared_fencing_primitive": SHARED_CONTROLLER_FENCING_PRIMITIVE,
            "shared_controller_primitives": shared_controller_primitive_contract(),
            "phase": "running",
            "immutable_sha256": control["immutable_sha256"],
            "created_at": utc_timestamp(timestamp),
            "created_timestamp": timestamp,
            "updated_at": utc_timestamp(timestamp),
            "updated_timestamp": timestamp,
            "baseline": controller_drill_baseline(state_dir, control),
            "roles": {
                role: {
                    "next_generation": 1,
                    "active": None,
                    "successor": None,
                    "submission_intent": None,
                    "heartbeat": None,
                    "last_exit": None,
                    "kill": None,
                    "recovery": None,
                }
                for role in ROLE_NAMES
            },
            "transition_history": [],
            "final_reconciliation_path": None,
            "final_reconciliation_sha256": None,
        }
        with drill_lock(state_dir):
            if path.exists():
                state = load_drill_state(state_dir)
            else:
                _append_drill_event(
                    state_dir,
                    state,
                    event="started_paused",
                    details={"desired_state": "paused"},
                    now=timestamp,
                )
                _save_drill_state(state_dir, state, now=timestamp)
    for role in ROLE_NAMES:
        submit_drill_intent(
            state_dir,
            role=role,
            target="active",
            dependency_job_id=None,
            scheduler=scheduler,
            submit_runner=submit_runner,
            now=timestamp,
        )
    return load_drill_state(state_dir)


def _resolve_fenced_role_claim(
    role_state: Mapping[str, Any],
    *,
    role: str,
    expected_token: str,
    generation: int,
    intent_token: str,
    job_id: str,
    active_scheduler_job_ids: set[str],
    context: str,
    now: float,
) -> dict[str, Any]:
    """Shared exact-intent fencing primitive for production and drill controllers."""

    candidates = [
        record
        for field in ("active", "successor", "submission_intent")
        if isinstance((record := role_state.get(field)), dict)
        and record.get("job_token") == expected_token
        and int(record.get("generation", -1)) == generation
        and record.get("intent_token") == intent_token
    ]
    if not candidates:
        raise ControllerFenced(
            f"{context} job {job_id} has no durable exact intent for {role} "
            f"generation {generation}"
        )
    if any(
        record.get("controller_primitives") != shared_controller_primitive_contract()
        for record in candidates
    ):
        raise ControllerFenced(
            f"{context} job {job_id} has the wrong primitive contract"
        )
    exact_ids = {
        str(record.get("job_id")) for record in candidates if record.get("job_id")
    }
    if exact_ids and job_id not in exact_ids:
        raise ControllerFenced(
            f"{context} job {job_id} does not match recorded exact IDs {sorted(exact_ids)}"
        )
    if context in {"production", "drill"}:
        try:
            for record in candidates:
                _validate_exact_sbatch_record_proof(
                    record,
                    job_id=job_id,
                    context=f"{context} job {job_id}",
                )
        except SchedulerAmbiguity as exc:
            raise ControllerFenced(
                f"{context} job {job_id} lacks its exact spool/release proof"
            ) from exc
    active = role_state.get("active")
    if isinstance(active, dict):
        active_id = str(active.get("job_id", ""))
        if active_id and active_id != job_id and active_id in active_scheduler_job_ids:
            raise ControllerFenced(
                f"live {context} job {active_id} already owns controller role {role}"
            )
    claimed = copy.deepcopy(candidates[0])
    claimed.update(
        {
            "state": "running",
            "job_id": job_id,
            "claimed_at": utc_timestamp(now),
            "claimed_timestamp": now,
            "host": socket.gethostname(),
            "pid": os.getpid(),
            "fencing_primitive": SHARED_CONTROLLER_FENCING_PRIMITIVE,
        }
    )
    return claimed


def claim_drill_controller(
    state_dir: Path,
    *,
    drill_id: str,
    role: str,
    generation: int,
    intent_token: str,
    job_id: str,
    active_scheduler_job_ids: set[str],
    now: float | None = None,
) -> dict[str, Any]:
    _validate_role(role)
    if not job_id.isdigit():
        raise ControllerFenced(f"invalid drill SLURM_JOB_ID {job_id!r}")
    timestamp = time.time() if now is None else float(now)
    expected = drill_job_token(drill_id, role, generation, intent_token)
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        _assert_drill_control_paused(
            state_dir, expected_immutable_sha256=state["immutable_sha256"]
        )
        if _external_watchdog_fences_drill_claims(state_dir):
            raise ControllerFenced(
                "external-watchdog drill froze this exact controller namespace"
            )
        if state["drill_id"] != drill_id or state["phase"] != "running":
            raise ControllerFenced("controller drill is not accepting claims")
        row = state["roles"][role]
        claimed = _resolve_fenced_role_claim(
            row,
            role=role,
            expected_token=expected,
            generation=generation,
            intent_token=intent_token,
            job_id=job_id,
            active_scheduler_job_ids=active_scheduler_job_ids,
            context="drill",
            now=timestamp,
        )
        row["active"] = claimed
        if (
            isinstance(row.get("successor"), dict)
            and row["successor"].get("intent_token") == intent_token
        ):
            row["successor"] = None
        row["heartbeat"] = {
            "job_id": job_id,
            "generation": generation,
            "intent_token": intent_token,
            "timestamp": timestamp,
            "at": utc_timestamp(timestamp),
        }
        _append_drill_event(
            state_dir,
            state,
            event="claimed",
            details={"role": role, "generation": generation, "job_id": job_id},
            now=timestamp,
        )
        _save_drill_state(state_dir, state, now=timestamp)
        return claimed


def heartbeat_drill_controller(
    state_dir: Path,
    *,
    drill_id: str,
    role: str,
    generation: int,
    intent_token: str,
    job_id: str,
    now: float | None = None,
) -> dict[str, Any]:
    timestamp = time.time() if now is None else float(now)
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        _assert_drill_control_paused(
            state_dir, expected_immutable_sha256=state["immutable_sha256"]
        )
        if state["drill_id"] != drill_id or state["phase"] != "running":
            raise ControllerFenced("controller drill has stopped")
        active = state["roles"][role]["active"]
        identity = (job_id, generation, intent_token)
        recorded = (
            (
                str(active.get("job_id", "")),
                int(active.get("generation", -1)),
                str(active.get("intent_token", "")),
            )
            if isinstance(active, dict)
            else None
        )
        if identity != recorded:
            raise ControllerFenced("drill heartbeat no longer owns the exact role")
        heartbeat = {
            "job_id": job_id,
            "generation": generation,
            "intent_token": intent_token,
            "timestamp": timestamp,
            "at": utc_timestamp(timestamp),
        }
        state["roles"][role]["heartbeat"] = heartbeat
        _save_drill_state(state_dir, state, now=timestamp)
        return heartbeat


def _record_drill_exit(
    state_dir: Path,
    *,
    drill_id: str,
    role: str,
    generation: int,
    intent_token: str,
    job_id: str,
    reason: str,
    now: float | None = None,
) -> None:
    timestamp = time.time() if now is None else float(now)
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        if state["drill_id"] != drill_id:
            return
        row = state["roles"][role]
        active = row.get("active")
        if isinstance(active, dict) and (
            str(active.get("job_id")) == job_id
            and int(active.get("generation", -1)) == generation
            and str(active.get("intent_token")) == intent_token
        ):
            row["active"] = None
        row["last_exit"] = {
            "job_id": job_id,
            "generation": generation,
            "intent_token": intent_token,
            "reason": reason,
            "timestamp": timestamp,
            "at": utc_timestamp(timestamp),
        }
        _append_drill_event(
            state_dir,
            state,
            event="exited",
            details={"role": role, "job_id": job_id, "reason": reason},
            now=timestamp,
        )
        _save_drill_state(state_dir, state, now=timestamp)


def supervise_drill(
    state_dir: Path,
    *,
    drill_id: str,
    role: str,
    generation: int,
    intent_token: str,
    heartbeat_interval: float = HEARTBEAT_INTERVAL_SECONDS,
) -> int:
    """Exercise the real fencing/successor boundary without starting a managed plane."""

    job_id = os.environ.get("SLURM_JOB_ID", "")
    if not job_id:
        raise ControllerFenced("supervise-drill must run inside Slurm")
    stop = False

    def request_stop(_signum: int, _frame: Any) -> None:
        nonlocal stop
        stop = True

    previous = {
        sig: signal.signal(sig, request_stop) for sig in (signal.SIGTERM, signal.SIGINT)
    }
    reason = "error"
    try:
        with role_singleton_lock(state_dir, role):
            snapshot = query_scheduler()
            claim_drill_controller(
                state_dir,
                drill_id=drill_id,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                active_scheduler_job_ids=snapshot.active_job_ids | {job_id},
            )
            submit_drill_intent(
                state_dir,
                role=role,
                target="successor",
                dependency_job_id=job_id,
                scheduler=snapshot,
            )
            last_heartbeat = 0.0
            while not stop:
                state = load_drill_state(state_dir)
                if state["phase"] != "running":
                    reason = "drill_stopping"
                    return 0
                now = time.time()
                if now - last_heartbeat >= heartbeat_interval:
                    heartbeat_drill_controller(
                        state_dir,
                        drill_id=drill_id,
                        role=role,
                        generation=generation,
                        intent_token=intent_token,
                        job_id=job_id,
                        now=now,
                    )
                    snapshot = query_scheduler(tolerate_errors=True, now=now)
                    try:
                        submit_drill_intent(
                            state_dir,
                            role=role,
                            target="successor",
                            dependency_job_id=job_id,
                            scheduler=snapshot,
                            now=now,
                        )
                    except (ControlError, OSError) as exc:
                        print(
                            f"[schema5-control] drill successor retry required: {exc}",
                            file=sys.stderr,
                        )
                    last_heartbeat = now
                time.sleep(min(1.0, heartbeat_interval))
            reason = "signal"
            return 0
    finally:
        for sig, handler in previous.items():
            signal.signal(sig, handler)
        try:
            _record_drill_exit(
                state_dir,
                drill_id=drill_id,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                reason=reason,
            )
        except ControlError as exc:
            print(
                f"[schema5-control] could not record drill exit: {exc}", file=sys.stderr
            )


def controller_drill_status(
    state_dir: Path, *, snapshot: SchedulerSnapshot, now: float | None = None
) -> dict[str, Any]:
    timestamp = snapshot.captured_at if now is None else float(now)
    state = load_drill_state(state_dir)
    control = _assert_drill_control_paused(
        state_dir, expected_immutable_sha256=state["immutable_sha256"]
    )
    namespace_jobs = [
        job for job in snapshot.jobs if job.comment.startswith(DRILL_TOKEN_PREFIX)
    ]
    valid_namespace_jobs = [
        job for job in namespace_jobs if parse_drill_job_token(job.comment) is not None
    ]
    live = [job for job in namespace_jobs if job.active]
    valid_live = [
        job for job in live if parse_drill_job_token(job.comment) is not None
    ]
    malformed_live = [
        job.job_id for job in live if parse_drill_job_token(job.comment) is None
    ]
    foreign = [
        job.job_id
        for job in valid_live
        if parse_drill_job_token(job.comment).get("drill") != state["drill_id"]
    ]
    roles: dict[str, Any] = {}
    errors: list[str] = list(snapshot.errors)
    if not snapshot.squeue_ok or not snapshot.sacct_ok:
        errors.append("controller drill lacks complete scheduler truth")
    if malformed_live:
        errors.append(
            f"malformed live controller-drill namespace jobs: {sorted(malformed_live)}"
        )
    if foreign:
        errors.append(f"foreign live controller drill jobs: {sorted(foreign)}")
    recorded_tokens: set[str] = set()
    for role, row in state["roles"].items():
        role_status: dict[str, Any] = {}
        for field in ("active", "successor", "submission_intent"):
            record = row.get(field)
            if not isinstance(record, dict):
                role_status[field] = None
                continue
            token = str(record.get("job_token", ""))
            recorded_tokens.add(token)
            all_matches = [job for job in valid_namespace_jobs if job.comment == token]
            matches = [job for job in all_matches if job.active]
            if len(all_matches) > 1:
                errors.append(f"duplicate drill token history for {role} {field}")
            recorded_id = record.get("job_id")
            if (
                recorded_id
                and matches
                and any(job.job_id != str(recorded_id) for job in matches)
            ):
                errors.append(f"scheduler ID mismatch for {role} {field}")
            if recorded_id:
                exact = [job for job in matches if job.job_id == str(recorded_id)]
                if exact:
                    try:
                        _validate_exact_sbatch_record_proof(
                            record,
                            job_id=str(recorded_id),
                            context=f"controller drill {role} {field}",
                        )
                    except ControlError:
                        errors.append(
                            f"exact spool/release proof is invalid for {role} {field}"
                        )
                expected_parent = record.get("dependency_job_id")
                if (
                    exact
                    and expected_parent is not None
                    and not _dependency_binds_exact_afterany(
                        exact[0].dependency, str(expected_parent)
                    )
                ):
                    errors.append(
                        f"scheduler dependency does not bind recorded parent for {role} {field}"
                    )
            role_status[field] = {
                "recorded_job_id": recorded_id,
                "matching_job_ids": [job.job_id for job in all_matches],
                "live_job_ids": [job.job_id for job in matches],
            }
        heartbeat = row.get("heartbeat")
        role_status["heartbeat_age_seconds"] = (
            timestamp - float(heartbeat["timestamp"])
            if isinstance(heartbeat, dict)
            else None
        )
        role_status["kill"] = copy.deepcopy(row.get("kill"))
        role_status["recovery"] = copy.deepcopy(row.get("recovery"))
        roles[role] = role_status
    unexpected = [job.job_id for job in live if job.comment not in recorded_tokens]
    if unexpected:
        errors.append(f"unmapped live controller-drill jobs: {sorted(unexpected)}")
    ready = state["phase"] == "running" and all(
        roles[role]["active"] is not None
        and len(roles[role]["active"]["live_job_ids"]) == 1
        and roles[role]["successor"] is not None
        and len(roles[role]["successor"]["live_job_ids"]) == 1
        and roles[role]["heartbeat_age_seconds"] is not None
        and 0 <= roles[role]["heartbeat_age_seconds"] <= 2 * HEARTBEAT_INTERVAL_SECONDS
        for role in ROLE_NAMES
    )
    completed = False
    if state["phase"] == "completed":
        if live:
            errors.append(
                f"completed controller drill still has live jobs: "
                f"{sorted(job.job_id for job in live)}"
            )
        try:
            validate_controller_drill_marker(
                state_dir,
                control,
                require_current_baseline=int(control["rollout_generation"]) == 0,
            )
        except ControlError as exc:
            errors.append(f"completed controller drill proof is invalid: {exc}")
        completed = not errors
    return {
        "schema_version": 1,
        "drill_id": state["drill_id"],
        "phase": state["phase"],
        "desired_state": control["desired_state"],
        "roles": roles,
        "live_job_ids": sorted(job.job_id for job in live),
        "errors": errors,
        "healthy": not errors,
        "ready_for_kill": not errors and ready,
        "completed": completed,
    }


def _assert_external_watchdog_drill_guard(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    expected_baseline: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Prove that the isolated watchdog drill cannot mutate production state."""

    if not snapshot.squeue_ok or not snapshot.sacct_ok or snapshot.errors:
        raise SchedulerAmbiguity(
            "external-watchdog drill requires complete, unambiguous squeue+sacct truth"
        )
    control = _assert_drill_control_paused(state_dir)
    production_jobs = [
        job.job_id for job in _scoped_control_jobs(snapshot) if job.active
    ]
    cell_jobs = [
        job.job_id
        for job in snapshot.jobs
        if job.active and _cell_job(job.job_name)
    ]
    if production_jobs or cell_jobs:
        raise SchedulerAmbiguity(
            "external-watchdog drill requires zero production controllers and cells: "
            f"controllers={production_jobs}, cells={cell_jobs}"
        )
    baseline = controller_drill_baseline(state_dir, control)
    if expected_baseline is not None and baseline != dict(expected_baseline):
        raise ControlError(
            "external-watchdog drill production baseline changed while armed"
        )
    return control, baseline


def _external_watchdog_namespace_records(
    state_dir: Path, *, snapshot: SchedulerSnapshot
) -> list[dict[str, Any]]:
    state = load_drill_state(state_dir)
    records: list[dict[str, Any]] = []
    for role in ROLE_NAMES:
        row = state["roles"][role]
        for target in ("active", "successor"):
            record = row.get(target)
            if not isinstance(record, dict) or not record.get("job_id"):
                raise SchedulerAmbiguity(
                    f"watchdog drill requires an exact {role} {target} job"
                )
            dependency = (
                str(record["dependency_job_id"])
                if record.get("dependency_job_id") is not None
                else None
            )
            _unique_exact_drill_job(
                snapshot,
                job_id=str(record["job_id"]),
                job_token=str(record["job_token"]),
                sbatch_path=str(record["sbatch_path"]),
                require_active=True,
                expected_dependency_job_id=dependency,
                record=record,
            )
            records.append(
                {
                    "role": role,
                    "target": target,
                    "job_id": str(record["job_id"]),
                    "job_token": str(record["job_token"]),
                    "sbatch_path": str(Path(record["sbatch_path"]).resolve()),
                    "sbatch_sha256": str(record["sbatch_sha256"]),
                    "submission_transport": str(
                        record["submission_transport"]
                    ),
                    "submission_argv": list(record["submission_argv"]),
                    "submission_argv_sha256": str(
                        record["submission_argv_sha256"]
                    ),
                    "persistent_hold": False,
                    "spooled_receipt_path": str(
                        Path(record["spooled_receipt_path"]).resolve()
                    ),
                    "spooled_receipt_sha256": str(
                        record["spooled_receipt_sha256"]
                    ),
                    "released_at": str(record["released_at"]),
                    "released_timestamp": float(
                        record["released_timestamp"]
                    ),
                    "dependency_job_id": dependency,
                }
            )
    if len({record["job_id"] for record in records}) != 4:
        raise SchedulerAmbiguity(
            "external-watchdog drill namespace does not contain four unique jobs"
        )
    return records


def arm_external_watchdog_drill(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    deployment_evidence_path: Path,
    expires_seconds: float = EXTERNAL_WATCHDOG_DRILL_DEFAULT_EXPIRY_SECONDS,
    now: float | None = None,
) -> dict[str, Any]:
    """Seal an expiring, paused, admission-zero exact cancellation intent."""

    timestamp = snapshot.captured_at if now is None else float(now)
    expiry = float(expires_seconds)
    if not 120.0 <= expiry <= EXTERNAL_WATCHDOG_DRILL_MAX_EXPIRY_SECONDS:
        raise ControlError("external-watchdog drill expiry must be 120..3600 seconds")
    with external_watchdog_drill_lock(state_dir), drill_submission_boundary_lock(
        state_dir
    ):
        control, baseline = _assert_external_watchdog_drill_guard(
            state_dir, snapshot=snapshot
        )
        status = controller_drill_status(
            state_dir, snapshot=snapshot, now=timestamp
        )
        if not status["ready_for_kill"]:
            raise SchedulerAmbiguity(
                "external-watchdog drill can arm only over a globally ready "
                "controller-drill namespace: "
                + "; ".join(status["errors"])
            )
        deployment_path = Path(
            os.path.abspath(os.fspath(deployment_evidence_path.expanduser()))
        )
        deployment, deployment_raw = _read_stable_json(
            deployment_path,
            description="external-watchdog deployment evidence",
            require_read_only=True,
        )
        _validate_watchdog_deployment_evidence(deployment, control=control)
        namespace = _external_watchdog_namespace_records(
            state_dir, snapshot=snapshot
        )
        intent: dict[str, Any] = {
            "schema_version": 1,
            "protocol": EXTERNAL_WATCHDOG_DRILL_PROTOCOL,
            "drill_id": status["drill_id"],
            "immutable_sha256": control["immutable_sha256"],
            "deployment": {
                "path": str(deployment_path),
                "sha256": hashlib.sha256(deployment_raw).hexdigest(),
                "evidence_id": deployment["evidence_id"],
                "deployment_id": deployment["deployment_id"],
                "watchdog_code_sha256": deployment["watchdog_code_sha256"],
                "immutable_release_sha256": deployment[
                    "immutable_release_sha256"
                ],
                "control_sha256": deployment["control_sha256"],
                "release_git_commit": deployment["release_git_commit"],
                "release_tag_object": deployment["release_tag_object"],
            },
            "baseline": baseline,
            "baseline_sha256": sha256_value(baseline),
            "namespace": namespace,
            "created_at": utc_timestamp(timestamp),
            "created_timestamp": timestamp,
            "expires_at": utc_timestamp(timestamp + expiry),
            "expires_timestamp": timestamp + expiry,
            "maximum_recovery_seconds": (
                EXTERNAL_WATCHDOG_DRILL_MAX_RECOVERY_SECONDS
            ),
        }
        intent["intent_id"] = _watchdog_self_hash(intent, "intent_id")
        intent_path = _external_watchdog_drill_intent_path(state_dir)
        if intent_path.exists() or intent_path.is_symlink():
            existing, _ = _read_stable_json(
                intent_path,
                description="external-watchdog drill intent",
                require_read_only=True,
            )
            _validate_external_watchdog_intent(existing)
            if (
                existing["drill_id"] != intent["drill_id"]
                or existing["immutable_sha256"] != intent["immutable_sha256"]
                or existing["deployment"] != intent["deployment"]
                or existing["baseline"] != intent["baseline"]
                or existing["namespace"] != intent["namespace"]
            ):
                raise ControlError(
                    "another sealed external-watchdog drill intent already exists"
                )
            intent = existing
        else:
            _publish_sealed_json_once(
                intent_path,
                intent,
                description="external-watchdog drill intent",
            )
        state_path = _external_watchdog_drill_state_path(state_dir)
        if state_path.exists() or state_path.is_symlink():
            loaded = _load_external_watchdog_drill(state_dir)
            assert loaded is not None
            _, state = loaded
            return {
                "intent": intent,
                "state": state,
                "idempotent": True,
            }
        state: dict[str, Any] = {
            "schema_version": 1,
            "protocol": EXTERNAL_WATCHDOG_DRILL_STATE_PROTOCOL,
            "intent_id": intent["intent_id"],
            "phase": "armed",
            "revision": 0,
            "cancellation_started_at": None,
            "cancellation_started_timestamp": None,
            "cancellation_results": {},
            "observations": [],
            "repair_attempts": 0,
            "recovery": None,
            "completion_evidence": None,
            "last_error": None,
        }
        _validate_external_watchdog_state(state, intent=intent)
        _atomic_write_json(state_path, state)
        return {"intent": intent, "state": state, "idempotent": False}


def _reconcile_external_watchdog_cancellation(
    state_dir: Path,
    *,
    intent: Mapping[str, Any],
    state: MutableMapping[str, Any],
    snapshot: SchedulerSnapshot,
    now: float,
) -> bool:
    """Close accepted cancellation records only from complete terminal truth."""

    all_cancelled = True
    for record in intent["namespace"]:
        job = _unique_exact_drill_job(
            snapshot,
            job_id=str(record["job_id"]),
            job_token=str(record["job_token"]),
            sbatch_path=str(record["sbatch_path"]),
            require_active=None,
            expected_dependency_job_id=(
                str(record["dependency_job_id"])
                if record["dependency_job_id"] is not None
                else None
            ),
            record=record,
        )
        terminal = normalize_scheduler_state(job.state)
        if job.active:
            all_cancelled = False
            continue
        if terminal != "CANCELLED":
            raise SchedulerAmbiguity(
                f"watchdog drill target {job.job_id} terminated as {terminal}, "
                "not CANCELLED"
            )
        state["cancellation_results"][job.job_id] = {
            "job_id": job.job_id,
            "state": "cancelled_reconciled_terminal",
            "scheduler_state": terminal,
            "reconciled_at": utc_timestamp(now),
            "reconciled_timestamp": now,
        }
    if all_cancelled and state["phase"] in {"armed", "cancelling"}:
        state["phase"] = "cancelled"
        _save_external_watchdog_state(state_dir, state, intent=intent)
    return all_cancelled


def cancel_external_watchdog_drill_namespace(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Persist the four exact targets, then cancel only that sealed namespace."""

    timestamp = snapshot.captured_at if now is None else float(now)
    runner = cancel_runner or _run_subprocess
    with external_watchdog_drill_lock(state_dir), drill_submission_boundary_lock(
        state_dir
    ):
        loaded = _load_external_watchdog_drill(state_dir)
        if loaded is None:
            raise ControlError("external-watchdog drill has not been armed")
        intent, state = loaded
        if timestamp >= float(intent["expires_timestamp"]):
            state["phase"] = "expired"
            _save_external_watchdog_state(state_dir, state, intent=intent)
            raise ControlError("external-watchdog drill intent expired before cancellation")
        _assert_external_watchdog_drill_guard(
            state_dir,
            snapshot=snapshot,
            expected_baseline=intent["baseline"],
        )
        if state["phase"] in {"cancelled", "recovering", "recovered", "complete"}:
            return {"intent_id": intent["intent_id"], "state": state}
        if state["phase"] not in {"armed", "cancelling"}:
            raise ControlError(
                f"external-watchdog drill cannot cancel from phase {state['phase']}"
            )
        if state["phase"] == "armed":
            state["phase"] = "cancelling"
            state["cancellation_started_at"] = utc_timestamp(timestamp)
            state["cancellation_started_timestamp"] = timestamp
            _save_external_watchdog_state(state_dir, state, intent=intent)
        for record in intent["namespace"]:
            job = _unique_exact_drill_job(
                snapshot,
                job_id=str(record["job_id"]),
                job_token=str(record["job_token"]),
                sbatch_path=str(record["sbatch_path"]),
                require_active=None,
                expected_dependency_job_id=(
                    str(record["dependency_job_id"])
                    if record["dependency_job_id"] is not None
                    else None
                ),
                record=record,
            )
            terminal = normalize_scheduler_state(job.state)
            if not job.active:
                if terminal != "CANCELLED":
                    raise SchedulerAmbiguity(
                        f"watchdog drill target {job.job_id} is terminal {terminal}"
                    )
                state["cancellation_results"][job.job_id] = {
                    "job_id": job.job_id,
                    "state": "cancelled_reconciled_terminal",
                    "scheduler_state": terminal,
                    "reconciled_at": utc_timestamp(timestamp),
                    "reconciled_timestamp": timestamp,
                }
                _save_external_watchdog_state(state_dir, state, intent=intent)
                continue
            prior = state["cancellation_results"].get(job.job_id)
            if isinstance(prior, dict) and prior.get("state") == "accepted":
                continue
            proc = runner(["scancel", job.job_id])
            result = {
                "job_id": job.job_id,
                "state": "accepted",
                "returncode": int(proc.returncode),
                "stderr": proc.stderr[-500:],
                "accepted_at": utc_timestamp(timestamp),
                "accepted_timestamp": timestamp,
            }
            if proc.returncode != 0:
                state["last_error"] = (
                    f"scancel {job.job_id} failed rc={proc.returncode}: "
                    f"{proc.stderr[-500:]}"
                )
                _save_external_watchdog_state(state_dir, state, intent=intent)
                raise ControlError(state["last_error"])
            state["cancellation_results"][job.job_id] = result
            _save_external_watchdog_state(state_dir, state, intent=intent)
        _reconcile_external_watchdog_cancellation(
            state_dir,
            intent=intent,
            state=state,
            snapshot=snapshot,
            now=timestamp,
        )
        return {"intent_id": intent["intent_id"], "state": state}


def _external_watchdog_role_status(
    state_dir: Path, *, snapshot: SchedulerSnapshot, now: float
) -> dict[str, Any]:
    """Project the isolated drill chains into the ordinary watchdog role schema."""

    drill = load_drill_state(state_dir)
    jobs_by_id = {job.job_id: job for job in snapshot.jobs}
    result: dict[str, Any] = {}
    for role in ROLE_NAMES:
        row = drill["roles"][role]
        active = row.get("active") if isinstance(row.get("active"), dict) else {}
        successor = (
            row.get("successor")
            if isinstance(row.get("successor"), dict)
            else {}
        )
        active_job = jobs_by_id.get(str(active.get("job_id", "")))
        successor_job = jobs_by_id.get(str(successor.get("job_id", "")))
        heartbeat = row.get("heartbeat")
        result[role] = {
            "recorded_active_job_id": active.get("job_id"),
            "live_active": bool(active_job is not None and active_job.active),
            "active_identity_mismatch": bool(
                active_job is not None
                and active_job.active
                and active_job.comment != active.get("job_token")
            ),
            "scheduler_state": (
                active_job.state if active_job is not None else None
            ),
            "recorded_successor_job_id": successor.get("job_id"),
            "successor_live": bool(
                successor_job is not None and successor_job.active
            ),
            "successor_identity_mismatch": bool(
                successor_job is not None
                and successor_job.active
                and successor_job.comment != successor.get("job_token")
            ),
            "successor_scheduler_state": (
                successor_job.state if successor_job is not None else None
            ),
            "heartbeat": copy.deepcopy(heartbeat),
            "heartbeat_age_seconds": (
                now - float(heartbeat["timestamp"])
                if isinstance(heartbeat, dict)
                and isinstance(heartbeat.get("timestamp"), (int, float))
                else None
            ),
            "heartbeat_stale": (
                not isinstance(heartbeat, dict)
                or not isinstance(heartbeat.get("timestamp"), (int, float))
                or now - float(heartbeat["timestamp"])
                > STALE_HEARTBEAT_SECONDS
            ),
        }
    return result


def external_watchdog_drill_status(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    record_observation: bool,
    now: float | None = None,
) -> dict[str, Any]:
    """Return the forced-command status, recording only proven absent cuts."""

    timestamp = snapshot.captured_at if now is None else float(now)
    report = live_status(state_dir, snapshot=snapshot, now=timestamp)
    with external_watchdog_drill_lock(state_dir):
        loaded = _load_external_watchdog_drill(state_dir)
        if loaded is None:
            return report
        intent, state = loaded
        if timestamp >= float(intent["expires_timestamp"]) and state["phase"] not in {
            "complete",
            "expired",
        }:
            state["phase"] = "expired"
            _save_external_watchdog_state(state_dir, state, intent=intent)
        if state["phase"] in {"complete", "expired"}:
            return report
        _, baseline = _assert_external_watchdog_drill_guard(
            state_dir,
            snapshot=snapshot,
            expected_baseline=intent["baseline"],
        )
        namespace_absent = _reconcile_external_watchdog_cancellation(
            state_dir,
            intent=intent,
            state=state,
            snapshot=snapshot,
            now=timestamp,
        )
        roles = _external_watchdog_role_status(
            state_dir, snapshot=snapshot, now=timestamp
        )
        chains_absent = all(
            not row["live_active"] and not row["successor_live"]
            for row in roles.values()
        )
        if (
            record_observation
            and state["phase"] in {"cancelled", "recovering"}
            and namespace_absent
            and chains_absent
            and (
                not state["observations"]
                or float(state["observations"][-1]["captured_timestamp"])
                < timestamp
            )
        ):
            scheduler_identity = {
                "captured_timestamp": timestamp,
                "jobs": [
                    {
                        "job_id": job.job_id,
                        "state": normalize_scheduler_state(job.state),
                        "comment": job.comment,
                    }
                    for job in sorted(snapshot.jobs, key=lambda item: item.job_id)
                    if job.comment.startswith(DRILL_TOKEN_PREFIX)
                ],
            }
            observation: dict[str, Any] = {
                "schema_version": 1,
                "intent_id": intent["intent_id"],
                "captured_at": utc_timestamp(timestamp),
                "captured_timestamp": timestamp,
                "namespace_absent": True,
                "scheduler_sha256": sha256_value(scheduler_identity),
            }
            observation["observation_id"] = _watchdog_self_hash(
                observation, "observation_id"
            )
            state["observations"].append(observation)
            _save_external_watchdog_state(state_dir, state, intent=intent)
        report["controllers"] = roles
        report["effective_admission_ceiling"] = 0
        report["watchdog_drill"] = {
            "schema_version": 1,
            "protocol": EXTERNAL_WATCHDOG_DRILL_PROTOCOL,
            "active": True,
            "intent_id": intent["intent_id"],
            "drill_id": intent["drill_id"],
            "phase": state["phase"],
            "created_timestamp": intent["created_timestamp"],
            "expires_timestamp": intent["expires_timestamp"],
            "maximum_recovery_seconds": intent["maximum_recovery_seconds"],
            "admission_zero": True,
            "production_baseline_unchanged": (
                baseline == intent["baseline"]
            ),
            "namespace_job_ids": [
                record["job_id"] for record in intent["namespace"]
            ],
        }
        return report


def repair_external_watchdog_drill(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Route forced ``repair-chain`` only to the sealed paused drill namespace."""

    timestamp = snapshot.captured_at if now is None else float(now)
    with external_watchdog_drill_lock(state_dir):
        loaded = _load_external_watchdog_drill(state_dir)
        if loaded is None:
            raise ControlError("no active external-watchdog drill intent")
        intent, state = loaded
        if timestamp >= float(intent["expires_timestamp"]):
            state["phase"] = "expired"
            _save_external_watchdog_state(state_dir, state, intent=intent)
            raise ControlError("external-watchdog drill intent expired")
        _assert_external_watchdog_drill_guard(
            state_dir,
            snapshot=snapshot,
            expected_baseline=intent["baseline"],
        )
        if state["phase"] not in {"cancelled", "recovering", "recovered"}:
            raise ControlError(
                f"watchdog repair is fenced in phase {state['phase']}"
            )
        observations = state["observations"]
        if (
            len(observations) < 2
            or float(observations[-1]["captured_timestamp"])
            - float(observations[-2]["captured_timestamp"])
            < 60.0
        ):
            raise ControlError(
                "watchdog repair requires two persisted absent observations "
                "at least 60 seconds apart"
            )
        if state["phase"] == "recovered":
            return {
                "desired_state": "paused",
                "watchdog_drill": "recovered",
                "submitted": [],
            }
        state["phase"] = "recovering"
        state["repair_attempts"] = int(state["repair_attempts"]) + 1
        _save_external_watchdog_state(state_dir, state, intent=intent)
        submitted: list[dict[str, Any]] = []
        for role in ROLE_NAMES:
            record = submit_drill_intent(
                state_dir,
                role=role,
                target="active",
                dependency_job_id=None,
                scheduler=snapshot,
                submit_runner=submit_runner,
                now=timestamp,
            )
            submitted.append({"role": role, "job_id": record["job_id"]})
        return {
            "desired_state": "paused",
            "watchdog_drill": "recovering",
            "intent_id": intent["intent_id"],
            "submitted": submitted,
        }


def complete_external_watchdog_drill(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    output_path: Path,
    now: float | None = None,
) -> dict[str, Any]:
    """Seal bounded duplicate-free recovery evidence without finishing the base drill."""

    timestamp = snapshot.captured_at if now is None else float(now)
    with external_watchdog_drill_lock(state_dir):
        loaded = _load_external_watchdog_drill(state_dir)
        if loaded is None:
            raise ControlError("external-watchdog drill has not been armed")
        intent, state = loaded
        _assert_external_watchdog_drill_guard(
            state_dir,
            snapshot=snapshot,
            expected_baseline=intent["baseline"],
        )
        status = controller_drill_status(
            state_dir, snapshot=snapshot, now=timestamp
        )
        if not status["ready_for_kill"]:
            raise SchedulerAmbiguity(
                "external-watchdog recovery is not globally ready: "
                + "; ".join(status["errors"])
            )
        current = _external_watchdog_namespace_records(
            state_dir, snapshot=snapshot
        )
        original_ids = {record["job_id"] for record in intent["namespace"]}
        current_ids = {record["job_id"] for record in current}
        if original_ids & current_ids or len(current_ids) != 4:
            raise SchedulerAmbiguity(
                "external-watchdog recovery did not create one new four-job namespace"
            )
        started = state.get("cancellation_started_timestamp")
        if not isinstance(started, (int, float)) or isinstance(started, bool):
            raise ControlError(
                "external-watchdog drill lacks a persisted cancellation start"
            )
        recovery_seconds = timestamp - float(started)
        if not 0 <= recovery_seconds <= EXTERNAL_WATCHDOG_DRILL_MAX_RECOVERY_SECONDS:
            raise ControlError(
                "external-watchdog namespace recovery exceeded 15 minutes"
            )
        if (
            len(state["observations"]) < 2
            or float(state["observations"][-1]["captured_timestamp"])
            - float(state["observations"][-2]["captured_timestamp"])
            < 60.0
        ):
            raise ControlError(
                "external-watchdog completion lacks two independent observations"
            )
        deployment = intent["deployment"]
        evidence: dict[str, Any] = {
            "schema_version": 1,
            "protocol": EXTERNAL_WATCHDOG_DRILL_EVIDENCE_PROTOCOL,
            "passed": True,
            "release_id": PRODUCTION_RELEASE_ID,
            "release_tag": PRODUCTION_OPERATIONAL_TAG,
            "release_git_commit": deployment["release_git_commit"],
            "release_tag_object": deployment["release_tag_object"],
            "chain_namespace": "schema5-v1.2-r13",
            "deployment_id": deployment["deployment_id"],
            "watchdog_code_sha256": deployment["watchdog_code_sha256"],
            "immutable_release_sha256": deployment[
                "immutable_release_sha256"
            ],
            "control_sha256": deployment["control_sha256"],
            "scheduler_observations": [
                float(item["captured_timestamp"])
                for item in state["observations"][-2:]
            ],
            "namespace_cancellation_recovery_seconds": recovery_seconds,
            "duplicate_jobs": 0,
            "duplicate_admission_intents": 0,
            "fairness_mutations": 0,
        }
        evidence["evidence_id"] = _watchdog_self_hash(
            evidence, "evidence_id"
        )
        sealed_path, sealed_sha256 = _publish_sealed_json_once(
            output_path,
            evidence,
            description="external-watchdog drill evidence",
        )
        state["phase"] = "complete"
        state["recovery"] = {
            "completed_at": utc_timestamp(timestamp),
            "completed_timestamp": timestamp,
            "recovery_seconds": recovery_seconds,
            "original_job_ids": sorted(original_ids),
            "recovered_job_ids": sorted(current_ids),
        }
        state["completion_evidence"] = {
            "path": str(sealed_path),
            "sha256": sealed_sha256,
            "evidence_id": evidence["evidence_id"],
        }
        _save_external_watchdog_state(state_dir, state, intent=intent)
        return evidence


def kill_drill_controller(
    state_dir: Path,
    *,
    role: str,
    snapshot: SchedulerSnapshot,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Persist and then cancel exactly one token-and-command-verified drill job."""

    _validate_role(role)
    if not snapshot.squeue_ok or not snapshot.sacct_ok:
        raise SchedulerAmbiguity("drill kill requires complete scheduler truth")
    timestamp = snapshot.captured_at if now is None else float(now)
    status = controller_drill_status(state_dir, snapshot=snapshot, now=timestamp)
    if status["errors"]:
        raise SchedulerAmbiguity("; ".join(status["errors"]))
    runner = cancel_runner or _run_subprocess
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        _assert_drill_control_paused(
            state_dir, expected_immutable_sha256=state["immutable_sha256"]
        )
        if state["phase"] != "running":
            raise ControlError("controller drill is not running")
        row = state["roles"][role]
        if isinstance(row.get("kill"), dict) and row["kill"].get("returncode") == 0:
            return copy.deepcopy(row["kill"])
        existing_kill = row.get("kill")
        active = row.get("active")
        successor = row.get("successor")
        if isinstance(existing_kill, dict):
            kill = existing_kill
            killed_submission = kill.get("submission_record")
            if not isinstance(killed_submission, dict):
                raise SchedulerAmbiguity(
                    f"{role} persisted kill has no exact submission proof"
                )
            sbatch_path = str(kill.get("sbatch_path", ""))
            if not sbatch_path and isinstance(active, dict):
                sbatch_path = str(active.get("sbatch_path", ""))
            if not sbatch_path:
                raise SchedulerAmbiguity(
                    f"{role} persisted kill has no sbatch provenance"
                )
            target_job = _unique_exact_drill_job(
                snapshot,
                job_id=str(kill.get("job_id", "")),
                job_token=str(kill.get("job_token", "")),
                sbatch_path=sbatch_path,
                require_active=None,
                expected_dependency_job_id=(
                    str(killed_submission["dependency_job_id"])
                    if killed_submission.get("dependency_job_id") is not None
                    else None
                ),
                record=killed_submission,
            )
            if not target_job.active:
                terminal_state = normalize_scheduler_state(target_job.state)
                if terminal_state != "CANCELLED":
                    raise SchedulerAmbiguity(
                        f"persisted exact kill target {kill['job_id']} is {terminal_state}, "
                        "which does not prove scancel acceptance"
                    )
                kill["returncode"] = 0
                kill["stderr"] = ""
                kill["completed_at"] = utc_timestamp(timestamp)
                kill["completed_timestamp"] = timestamp
                kill["state"] = "cancelled_reconciled_terminal"
                kill["scheduler_terminal_state"] = terminal_state
                kill["reconciled_from_scheduler"] = True
                kill["sbatch_path"] = sbatch_path
                _append_drill_event(
                    state_dir,
                    state,
                    event="exact_kill_reconciled_terminal",
                    details={
                        "role": role,
                        "job_id": kill["job_id"],
                        "scheduler_state": kill["scheduler_terminal_state"],
                    },
                    now=timestamp,
                )
                _save_drill_state(state_dir, state, now=timestamp)
                return copy.deepcopy(kill)
            kill["state"] = "cancelling"
            kill["sbatch_path"] = sbatch_path
            kill["retry_count"] = int(kill.get("retry_count", 0)) + 1
            _append_drill_event(
                state_dir,
                state,
                event="exact_kill_retry",
                details={"role": role, "job_id": kill["job_id"]},
                now=timestamp,
            )
            _save_drill_state(state_dir, state, now=timestamp)
        else:
            if not status["ready_for_kill"]:
                raise SchedulerAmbiguity(
                    "controller drill is not globally ready for an exact kill"
                )
            if not isinstance(active, dict) or not active.get("job_id"):
                raise SchedulerAmbiguity(f"{role} has no exact active drill job")
            if not isinstance(successor, dict) or not successor.get("job_id"):
                raise SchedulerAmbiguity(f"{role} has no recorded drill successor")
            if str(successor.get("dependency_job_id", "")) != str(active["job_id"]):
                raise SchedulerAmbiguity(
                    f"{role} successor does not bind the exact active parent"
                )
            _unique_exact_drill_job(
                snapshot,
                job_id=str(active["job_id"]),
                job_token=str(active["job_token"]),
                sbatch_path=str(active["sbatch_path"]),
                require_active=True,
                expected_dependency_job_id=(
                    str(active["dependency_job_id"])
                    if active.get("dependency_job_id") is not None
                    else None
                ),
                record=active,
            )
            _unique_exact_drill_job(
                snapshot,
                job_id=str(successor["job_id"]),
                job_token=str(successor["job_token"]),
                sbatch_path=str(successor["sbatch_path"]),
                require_active=True,
                expected_dependency_job_id=str(active["job_id"]),
                record=successor,
            )
            kill = {
                "state": "cancelling",
                "job_id": str(active["job_id"]),
                "job_token": str(active["job_token"]),
                "sbatch_path": str(active["sbatch_path"]),
                "fencing_primitive": active.get("fencing_primitive"),
                "controller_primitives": active.get("controller_primitives"),
                "submission_record": copy.deepcopy(active),
                "successor_job_id": str(successor["job_id"]),
                "successor_job_token": str(successor["job_token"]),
                "successor_sbatch_path": str(successor["sbatch_path"]),
                "successor_dependency_job_id": str(active["job_id"]),
                "successor_submission_record": copy.deepcopy(successor),
                "started_at": utc_timestamp(timestamp),
                "started_timestamp": timestamp,
            }
            row["kill"] = kill
            _append_drill_event(
                state_dir,
                state,
                event="exact_kill_intent",
                details={"role": role, "job_id": kill["job_id"]},
                now=timestamp,
            )
            _save_drill_state(state_dir, state, now=timestamp)
    proc = runner(["scancel", kill["job_id"]])
    completed = time.time() if now is None else timestamp
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        current = state["roles"][role].get("kill")
        if not isinstance(current, dict) or current.get("job_id") != kill["job_id"]:
            raise SchedulerAmbiguity("drill kill intent changed during scancel")
        current["returncode"] = int(proc.returncode)
        current["stderr"] = proc.stderr.strip()[:1000]
        current["completed_at"] = utc_timestamp(completed)
        current["completed_timestamp"] = completed
        current["state"] = "cancelled" if proc.returncode == 0 else "failed"
        _append_drill_event(
            state_dir,
            state,
            event="exact_kill_result",
            details={
                "role": role,
                "job_id": kill["job_id"],
                "returncode": proc.returncode,
            },
            now=completed,
        )
        _save_drill_state(state_dir, state, now=completed)
        result = copy.deepcopy(current)
    if proc.returncode != 0:
        raise ControlError(
            f"failed exact drill kill {kill['job_id']}: {proc.stderr.strip()[:500]}"
        )
    return result


def record_drill_recovery(
    state_dir: Path,
    *,
    role: str,
    snapshot: SchedulerSnapshot,
    max_seconds: float = 900.0,
    now: float | None = None,
) -> dict[str, Any]:
    _validate_role(role)
    timestamp = snapshot.captured_at if now is None else float(now)
    status = controller_drill_status(state_dir, snapshot=snapshot, now=timestamp)
    if status["errors"]:
        raise SchedulerAmbiguity("; ".join(status["errors"]))
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        row = state["roles"][role]
        kill = row.get("kill")
        active = row.get("active")
        heartbeat = row.get("heartbeat")
        if not isinstance(kill, dict) or kill.get("returncode") != 0:
            raise ControlError(f"{role} has no successful exact kill")
        if not isinstance(active, dict) or not isinstance(heartbeat, dict):
            raise ControlError(f"{role} successor has not claimed and heartbeated")
        if str(active.get("job_id")) == str(kill.get("job_id")):
            raise ControlError(f"{role} still reports the killed allocation")
        expected_successor = (
            str(kill.get("successor_job_id", "")),
            str(kill.get("successor_job_token", "")),
            str(Path(str(kill.get("successor_sbatch_path", ""))).expanduser().resolve()),
            str(kill.get("successor_dependency_job_id", "")),
        )
        active_successor = (
            str(active.get("job_id", "")),
            str(active.get("job_token", "")),
            str(Path(str(active.get("sbatch_path", ""))).expanduser().resolve()),
            str(active.get("dependency_job_id", "")),
        )
        if not all(expected_successor) or active_successor != expected_successor:
            raise ControllerFenced(
                f"{role} recovery did not claim the exact successor frozen by the kill intent"
            )
        active_heartbeat_identity = (
            str(active.get("job_id", "")),
            int(active.get("generation", -1)),
            str(active.get("intent_token", "")),
        )
        heartbeat_identity = (
            str(heartbeat.get("job_id", "")),
            int(heartbeat.get("generation", -1)),
            str(heartbeat.get("intent_token", "")),
        )
        if active_heartbeat_identity != heartbeat_identity:
            raise ControllerFenced(
                f"{role} successor heartbeat does not own the active role"
            )
        _unique_exact_drill_job(
            snapshot,
            job_id=expected_successor[0],
            job_token=expected_successor[1],
            sbatch_path=expected_successor[2],
            require_active=True,
            expected_dependency_job_id=expected_successor[3],
            record=active,
        )
        recovered_at = float(heartbeat["timestamp"])
        recovery_seconds = recovered_at - float(kill["started_timestamp"])
        if recovery_seconds < 0 or recovery_seconds > max_seconds:
            raise ControlError(
                f"{role} recovery took {recovery_seconds:.1f}s; limit is {max_seconds:.1f}s"
            )
        recovery = {
            "passed": True,
            "killed_job_id": str(kill["job_id"]),
            "successor_job_id": str(active["job_id"]),
            "successor_job_token": str(active["job_token"]),
            "successor_sbatch_path": str(active["sbatch_path"]),
            "successor_dependency_job_id": str(active["dependency_job_id"]),
            "successor_generation": int(active["generation"]),
            "successor_intent_token": str(active["intent_token"]),
            "recovered_at": utc_timestamp(recovered_at),
            "recovered_timestamp": recovered_at,
            "recovery_seconds": recovery_seconds,
            "maximum_seconds": max_seconds,
            "fencing_primitive": active.get("fencing_primitive"),
            "controller_primitives": active.get("controller_primitives"),
        }
        row["recovery"] = recovery
        _append_drill_event(
            state_dir,
            state,
            event="recovery_verified",
            details={"role": role, **recovery},
            now=timestamp,
        )
        _save_drill_state(state_dir, state, now=timestamp)
        return copy.deepcopy(recovery)


def wait_for_drill_recovery(
    state_dir: Path,
    *,
    role: str,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    timeout_seconds: float = 900.0,
    poll_seconds: float = 5.0,
) -> dict[str, Any]:
    reader = scheduler_reader or query_scheduler
    started = time.monotonic()
    last_error: Exception | None = None
    while time.monotonic() - started <= timeout_seconds:
        snapshot = reader()
        try:
            return record_drill_recovery(
                state_dir,
                role=role,
                snapshot=snapshot,
                max_seconds=timeout_seconds,
            )
        except (ControlError, OSError) as exc:
            last_error = exc
        time.sleep(min(poll_seconds, max(0.0, timeout_seconds)))
    raise ControlError(f"{role} drill recovery timed out: {last_error}")


def _live_drill_jobs(snapshot: SchedulerSnapshot, drill_id: str) -> list[SchedulerJob]:
    return [
        job
        for job in snapshot.jobs
        if job.active
        and (parsed := parse_drill_job_token(job.comment)) is not None
        and parsed["drill"] == drill_id
    ]


def _controller_drill_marker_sha256(state_dir: Path) -> str:
    marker_path = state_dir / DRILL_COMPLETE_FILENAME
    try:
        return sha256_file(marker_path)
    except FileNotFoundError as exc:
        raise ReadinessError(
            f"controller kill drill marker is missing: {marker_path}"
        ) from exc
    except OSError as exc:
        raise ReadinessError(
            f"controller kill drill marker cannot be read: {marker_path}: {exc}"
        ) from exc


def _publish_drill_reconciliation(state_dir: Path, drill_id: str) -> tuple[Path, str]:
    """Seal or recover the immutable final no-admission reconciliation report.

    A prior attempt may have published the sealed copy and died before committing the
    completed drill state.  In that case the immutable target is the transaction's
    durable preimage: validate and reuse it instead of comparing it with a newly
    timestamped live reconciliation.
    """

    target = _drill_reconciliation_path(state_dir, drill_id)
    target.parent.mkdir(parents=True, exist_ok=True)
    target_present = target.exists() or target.is_symlink()
    if target_present and (
        target.is_symlink()
        or not target.is_file()
        or target.stat().st_nlink != 1
        or target.stat().st_mode & 0o222
    ):
        raise ImmutablePinError(
            f"drill reconciliation is not an immutable regular file: {target}"
        )
    source = target if target_present else state_dir / RECONCILIATION_FILENAME
    try:
        payload = source.read_text(encoding="utf-8")
        report = json.loads(payload)
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ControlError(f"cannot seal drill reconciliation {source}: {exc}") from exc
    control = load_control(state_dir)
    if (
        not isinstance(report, dict)
        or report.get("passed") is not True
        or report.get("immutable_sha256") != control["immutable_sha256"]
        or report.get("all") is not True
        or report.get("no_admit") is not True
        or report.get("errors") != []
    ):
        raise ControlError("cannot seal a non-clean drill reconciliation")
    if not target_present:
        _atomic_publish_readonly_text(target, payload)
    return target.resolve(), sha256_file(target)


def _validate_completed_drill_history(state: Mapping[str, Any]) -> None:
    """Validate the semantic event/role proof, not only JSON shape and hashes."""

    history = state["transition_history"]
    events = [str(record.get("event", "")) for record in history]
    if not events or events[0] != "started_paused" or events[-1] != "completed":
        raise ReadinessError(
            "controller kill drill history lacks start/completion boundaries"
        )
    if events.count("completed") != 1:
        raise ReadinessError(
            "controller kill drill history must contain exactly one completion"
        )
    try:
        stopping_index = max(
            index for index, event in enumerate(events) if event == "stopping"
        )
        completed_index = len(events) - 1
    except ValueError as exc:
        raise ReadinessError(
            "controller kill drill history lacks a stopping transition"
        ) from exc
    if stopping_index >= completed_index:
        raise ReadinessError(
            "controller kill drill stopping/completion order is invalid"
        )
    for role in ROLE_NAMES:
        row = state["roles"][role]
        kill = row.get("kill")
        recovery = row.get("recovery")
        if (
            not isinstance(kill, dict)
            or kill.get("returncode") != 0
            or kill.get("fencing_primitive") != SHARED_CONTROLLER_FENCING_PRIMITIVE
            or kill.get("controller_primitives")
            != shared_controller_primitive_contract()
            or not isinstance(recovery, dict)
            or recovery.get("passed") is not True
            or recovery.get("fencing_primitive") != SHARED_CONTROLLER_FENCING_PRIMITIVE
            or recovery.get("controller_primitives")
            != shared_controller_primitive_contract()
            or str(kill.get("job_id")) != str(recovery.get("killed_job_id"))
            or str(kill.get("successor_job_id"))
            != str(recovery.get("successor_job_id"))
            or str(kill.get("successor_job_token"))
            != str(recovery.get("successor_job_token"))
            or str(Path(str(kill.get("successor_sbatch_path", ""))).resolve())
            != str(Path(str(recovery.get("successor_sbatch_path", ""))).resolve())
            or str(kill.get("successor_dependency_job_id", ""))
            != str(recovery.get("successor_dependency_job_id", ""))
            or str(recovery.get("successor_dependency_job_id", ""))
            != str(recovery.get("killed_job_id", ""))
            or str(recovery.get("successor_job_id"))
            == str(recovery.get("killed_job_id"))
        ):
            raise ReadinessError(
                f"controller kill drill state proof is invalid for {role}"
            )
        intent_indexes = [
            index
            for index, record in enumerate(history)
            if record.get("event") == "exact_kill_intent"
            and record.get("details", {}).get("role") == role
            and str(record.get("details", {}).get("job_id")) == str(kill["job_id"])
        ]
        result_indexes = [
            index
            for index, record in enumerate(history)
            if (
                (
                    record.get("event") == "exact_kill_result"
                    and record.get("details", {}).get("returncode") == 0
                )
                or (
                    record.get("event") == "exact_kill_reconciled_terminal"
                    and record.get("details", {}).get("scheduler_state") == "CANCELLED"
                )
            )
            and record.get("details", {}).get("role") == role
            and str(record.get("details", {}).get("job_id")) == str(kill["job_id"])
        ]
        recovery_indexes = [
            index
            for index, record in enumerate(history)
            if record.get("event") == "recovery_verified"
            and record.get("details", {}).get("role") == role
            and str(record.get("details", {}).get("killed_job_id"))
            == str(kill["job_id"])
            and str(record.get("details", {}).get("successor_job_id"))
            == str(recovery["successor_job_id"])
        ]
        if not intent_indexes or not result_indexes or not recovery_indexes:
            raise ReadinessError(
                f"controller kill drill event proof is incomplete for {role}"
            )
        if not (
            min(intent_indexes)
            < max(result_indexes)
            < max(recovery_indexes)
            < stopping_index
        ):
            raise ReadinessError(
                f"controller kill drill event order is invalid for {role}"
            )


def _recover_completed_drill_journal_suffix(
    state_dir: Path, state: MutableMapping[str, Any]
) -> dict[str, Any]:
    """Replay the sole completed event if death preceded the state replacement.

    Drill events are journaled before the JSON state is atomically replaced.  The
    completed event contains every field needed to finish that one interrupted state
    transaction.  Replaying it avoids emitting a second semantic completion on retry.
    The caller holds ``drill_lock``.
    """

    durable = _read_jsonl_locked(state_dir / DRILL_JOURNAL_FILENAME)
    memory = list(state["transition_history"])
    if durable[: len(memory)] != memory:
        raise ControlError("controller-drill journal diverged from its state")
    suffix = durable[len(memory) :]
    if not suffix:
        return dict(state)
    completed = [record for record in suffix if record.get("event") == "completed"]
    if not completed:
        return dict(state)
    if state.get("phase") != "stopping" or len(suffix) != 1 or len(completed) != 1:
        raise ReadinessError(
            "controller drill has an ambiguous journal suffix around completion"
        )
    record = completed[0]
    details = record.get("details")
    if not isinstance(details, dict) or set(details) != {
        "final_reconciliation_path",
        "final_reconciliation_sha256",
    }:
        raise ReadinessError("controller drill completion journal payload is invalid")
    raw_path = Path(str(details["final_reconciliation_path"]))
    expected_path = _drill_reconciliation_path(
        state_dir, str(state["drill_id"])
    ).resolve()
    expected_sha = str(details["final_reconciliation_sha256"])
    if (
        raw_path.is_symlink()
        or raw_path.resolve() != expected_path
        or not expected_path.is_file()
        or expected_path.stat().st_mode & 0o222
        or _SHA256_RE.fullmatch(expected_sha) is None
        or sha256_file(expected_path) != expected_sha
    ):
        raise ReadinessError(
            "controller drill completion journal lacks its sealed reconciliation"
        )
    recovered = copy.deepcopy(dict(state))
    recovered["transition_history"] = copy.deepcopy(durable)
    recovered["phase"] = "completed"
    recovered["final_reconciliation_path"] = str(expected_path)
    recovered["final_reconciliation_sha256"] = expected_sha
    recovered["completed_at"] = record.get("at")
    recovered["completed_timestamp"] = record.get("timestamp")
    _validate_completed_drill_history(recovered)
    _save_drill_state(
        state_dir,
        recovered,
        now=float(record.get("timestamp")),
    )
    return recovered


def validate_controller_drill_marker(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    require_current_baseline: bool = True,
    allow_completed_drain: bool = False,
    allow_resuming: bool = False,
) -> dict[str, Any]:
    """Require marker-last proof that both paused kill drills recovered safely."""

    marker_path = state_dir / DRILL_COMPLETE_FILENAME
    if marker_path.is_symlink():
        raise ReadinessError(
            f"controller kill drill marker cannot be a symlink: {marker_path}"
        )
    try:
        marker = json.loads(marker_path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise ReadinessError(
            f"controller kill drill marker is missing: {marker_path}"
        ) from exc
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReadinessError(f"controller kill drill marker is invalid: {exc}") from exc
    expected_fields = {
        "schema_version",
        "protocol",
        "passed",
        "drill_id",
        "shared_fencing_primitive",
        "shared_controller_primitives",
        "immutable_sha256",
        "completed_at",
        "completed_timestamp",
        "baseline",
        "roles",
        "final_reconciliation_path",
        "final_reconciliation_sha256",
        "drill_state_path",
        "drill_state_sha256",
    }
    if not isinstance(marker, dict) or set(marker) != expected_fields:
        raise ReadinessError("controller kill drill marker fields differ from schema")
    if (
        marker["schema_version"] != 1
        or marker["protocol"] != "schema5-controller-kill-drill-v1"
        or marker["passed"] is not True
        or marker["immutable_sha256"] != control["immutable_sha256"]
        or marker["shared_fencing_primitive"] != SHARED_CONTROLLER_FENCING_PRIMITIVE
        or marker["shared_controller_primitives"]
        != shared_controller_primitive_contract()
    ):
        raise ReadinessError("controller kill drill marker identity is invalid")
    desired_state = control.get("desired_state")
    if desired_state != "paused" and not (
        allow_resuming and desired_state == "resuming"
    ):
        raise ReadinessError("controller kill drill can only authorize a paused resume")
    if control.get("drain_requested") and (
        not allow_completed_drain
        or not isinstance(control.get("drain_intent"), dict)
        or control["drain_intent"].get("state") != "complete"
    ):
        raise ReadinessError(
            "controller kill drill cannot authorize an incomplete pause drain"
        )
    if set(marker.get("roles", {})) != set(ROLE_NAMES):
        raise ReadinessError(
            "controller kill drill did not cover both controller roles"
        )
    for role, recovery in marker["roles"].items():
        parsed_successor = (
            parse_drill_job_token(str(recovery.get("successor_job_token", "")))
            if isinstance(recovery, dict)
            else None
        )
        if (
            not isinstance(recovery, dict)
            or recovery.get("passed") is not True
            or not str(recovery.get("killed_job_id", "")).isdigit()
            or not str(recovery.get("successor_job_id", "")).isdigit()
            or recovery.get("killed_job_id") == recovery.get("successor_job_id")
            or not isinstance(recovery.get("recovery_seconds"), (int, float))
            or float(recovery["recovery_seconds"]) < 0
            or float(recovery["recovery_seconds"]) > 900.0
            or recovery.get("fencing_primitive") != SHARED_CONTROLLER_FENCING_PRIMITIVE
            or recovery.get("controller_primitives")
            != shared_controller_primitive_contract()
            or parsed_successor is None
            or parsed_successor.get("role") != role
            or int(parsed_successor["generation"])
            != recovery.get("successor_generation")
            or parsed_successor.get("intent")
            != recovery.get("successor_intent_token")
            or not Path(
                str(recovery.get("successor_sbatch_path", ""))
            ).is_absolute()
            or recovery.get("successor_dependency_job_id")
            != recovery.get("killed_job_id")
        ):
            raise ReadinessError(
                f"controller kill drill recovery is invalid for {role}"
            )
    raw_drill_path = Path(str(marker["drill_state_path"]))
    drill_path = raw_drill_path.resolve()
    if (
        raw_drill_path.is_symlink()
        or drill_path != _drill_state_path(state_dir).resolve()
        or not drill_path.is_file()
    ):
        raise ReadinessError("controller kill drill state path is invalid")
    if sha256_file(drill_path) != marker["drill_state_sha256"]:
        raise ReadinessError("controller kill drill state drifted after completion")
    try:
        state = load_drill_state(state_dir)
    except ControlError as exc:
        raise ReadinessError(f"controller kill drill state is invalid: {exc}") from exc
    journal = _read_jsonl_locked(state_dir / DRILL_JOURNAL_FILENAME)
    if journal != state["transition_history"]:
        raise ReadinessError(
            "completed controller kill drill state does not exactly match its journal"
        )
    if state["phase"] != "completed" or state["drill_id"] != marker["drill_id"]:
        raise ReadinessError("controller kill drill state is not completed")
    if (
        state.get("immutable_sha256") != marker["immutable_sha256"]
        or state.get("shared_fencing_primitive") != marker["shared_fencing_primitive"]
        or state.get("shared_controller_primitives")
        != marker["shared_controller_primitives"]
        or state.get("baseline") != marker["baseline"]
        or state.get("completed_at") != marker["completed_at"]
        or state.get("completed_timestamp") != marker["completed_timestamp"]
        or {role: state["roles"][role].get("recovery") for role in ROLE_NAMES}
        != marker["roles"]
        or state.get("final_reconciliation_path") != marker["final_reconciliation_path"]
        or state.get("final_reconciliation_sha256")
        != marker["final_reconciliation_sha256"]
    ):
        raise ReadinessError(
            "controller kill drill marker does not exactly match state"
        )
    _validate_completed_drill_history(state)
    raw_reconciliation_path = Path(str(marker["final_reconciliation_path"]))
    reconciliation_path = raw_reconciliation_path.resolve()
    if (
        raw_reconciliation_path.is_symlink()
        or reconciliation_path
        != _drill_reconciliation_path(state_dir, state["drill_id"]).resolve()
        or not reconciliation_path.is_file()
        or reconciliation_path.stat().st_mode & 0o222
        or sha256_file(reconciliation_path) != marker["final_reconciliation_sha256"]
    ):
        raise ReadinessError(
            "controller kill drill lacks its final clean reconciliation"
        )
    try:
        sealed_reconciliation = json.loads(
            reconciliation_path.read_text(encoding="utf-8")
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise ReadinessError(f"sealed drill reconciliation is invalid: {exc}") from exc
    if (
        not isinstance(sealed_reconciliation, dict)
        or sealed_reconciliation.get("passed") is not True
        or sealed_reconciliation.get("immutable_sha256") != control["immutable_sha256"]
        or sealed_reconciliation.get("all") is not True
        or sealed_reconciliation.get("no_admit") is not True
        or sealed_reconciliation.get("errors") != []
    ):
        raise ReadinessError(
            "sealed drill reconciliation does not prove a clean no-admit join"
        )
    if require_current_baseline:
        current_baseline = controller_drill_baseline(state_dir, control)
        if current_baseline != marker["baseline"]:
            raise ReadinessError(
                "production state changed after the controller kill drill"
            )
    return marker


def _completed_drill_marker_payload(
    state_dir: Path, state: Mapping[str, Any]
) -> dict[str, Any]:
    """Build the sole completion payload from an already durable completed state."""

    if state.get("phase") != "completed":
        raise ControlError("controller drill state is not ready for marker publication")
    _validate_completed_drill_history(state)
    reconciliation_path, reconciliation_sha = _publish_drill_reconciliation(
        state_dir, str(state["drill_id"])
    )
    if (
        state.get("final_reconciliation_path") != str(reconciliation_path)
        or state.get("final_reconciliation_sha256") != reconciliation_sha
    ):
        raise ImmutablePinError(
            "completed controller drill state does not bind its sealed reconciliation"
        )
    return {
        "schema_version": 1,
        "protocol": "schema5-controller-kill-drill-v1",
        "passed": True,
        "drill_id": state["drill_id"],
        "shared_fencing_primitive": state["shared_fencing_primitive"],
        "shared_controller_primitives": state["shared_controller_primitives"],
        "immutable_sha256": state["immutable_sha256"],
        "completed_at": state["completed_at"],
        "completed_timestamp": state["completed_timestamp"],
        "baseline": state["baseline"],
        "roles": {
            role: copy.deepcopy(state["roles"][role]["recovery"])
            for role in ROLE_NAMES
        },
        "final_reconciliation_path": str(reconciliation_path),
        "final_reconciliation_sha256": reconciliation_sha,
        "drill_state_path": str(_drill_state_path(state_dir).resolve()),
        "drill_state_sha256": sha256_file(_drill_state_path(state_dir)),
    }


def finish_controller_drill(
    state_dir: Path,
    *,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    timeout_seconds: float = 120.0,
    poll_seconds: float = 2.0,
    now: float | None = None,
) -> dict[str, Any]:
    """Stop drill chains, prove no mutation, reconcile, and publish completion last."""

    reader = scheduler_reader or query_scheduler
    runner = cancel_runner or _run_subprocess
    timestamp = time.time() if now is None else float(now)
    marker_path = state_dir / DRILL_COMPLETE_FILENAME
    if marker_path.exists() or marker_path.is_symlink():
        if marker_path.is_symlink() or not marker_path.is_file():
            raise ReadinessError(
                f"controller kill drill marker is not a regular file: {marker_path}"
            )
        control = _assert_drill_control_paused(state_dir)
        completed_snapshot = reader()
        if not completed_snapshot.squeue_ok or not completed_snapshot.sacct_ok:
            raise SchedulerAmbiguity(
                "completed drill validation requires complete scheduler truth"
            )
        lingering = _all_live_drill_jobs(completed_snapshot)
        if lingering:
            raise SchedulerAmbiguity(
                f"completed controller drill still has live jobs: "
                f"{sorted(job.job_id for job in lingering)}"
            )
        return validate_controller_drill_marker(
            state_dir,
            control,
            require_current_baseline=int(control["rollout_generation"]) == 0,
        )
    # Marker publication is a separate final filesystem transaction.  If the prior
    # process died after committing the completed state, re-prove namespace emptiness
    # and the unchanged baseline, then publish the exact marker without replaying the
    # timestamped reconciliation/completion transition.
    with drill_lock(state_dir):
        prior_state = load_drill_state(state_dir)
        prior_state = _recover_completed_drill_journal_suffix(
            state_dir, prior_state
        )
    if prior_state["phase"] == "completed":
        completed_snapshot = reader()
        if not completed_snapshot.squeue_ok or not completed_snapshot.sacct_ok:
            raise SchedulerAmbiguity(
                "completed drill recovery requires complete scheduler truth"
            )
        lingering = _all_live_drill_jobs(completed_snapshot)
        if lingering:
            raise SchedulerAmbiguity(
                "completed controller drill recovery found live namespace jobs: "
                + ", ".join(sorted(job.job_id for job in lingering))
            )
        control = _assert_drill_control_paused(
            state_dir,
            expected_immutable_sha256=prior_state["immutable_sha256"],
        )
        if controller_drill_baseline(state_dir, control) != prior_state["baseline"]:
            raise ControlError(
                "production state changed after the completed controller drill"
            )
        marker = _completed_drill_marker_payload(state_dir, prior_state)
        _atomic_write_json(marker_path, marker)
        return validate_controller_drill_marker(
            state_dir,
            control,
            require_current_baseline=int(control["rollout_generation"]) == 0,
        )
    # Acquiring the same boundary used across every external sbatch call proves there
    # is no live submitter before the durable stopping transition is published.
    with drill_submission_boundary_lock(state_dir):
        with drill_lock(state_dir):
            state = load_drill_state(state_dir)
            _assert_drill_control_paused(
                state_dir, expected_immutable_sha256=state["immutable_sha256"]
            )
            if any(
                not isinstance(state["roles"][role].get("recovery"), dict)
                or state["roles"][role]["recovery"].get("passed") is not True
                for role in ROLE_NAMES
            ):
                raise ControlError(
                    "both controller drill recoveries must pass before finish"
                )
            if state["phase"] == "running":
                state["phase"] = "stopping"
                _append_drill_event(
                    state_dir,
                    state,
                    event="stopping",
                    details={"reason": "both_recoveries_passed"},
                    now=timestamp,
                )
                _save_drill_state(state_dir, state, now=timestamp)
    deadline = time.monotonic() + timeout_seconds
    cancelled_job_ids: set[str] = set()
    clean_snapshots = 0
    final_snapshot = reader()
    state = load_drill_state(state_dir)
    drill_id = state["drill_id"]
    while True:
        if not final_snapshot.squeue_ok or not final_snapshot.sacct_ok:
            raise SchedulerAmbiguity("drill finish requires complete scheduler truth")
        try:
            _reconcile_stopping_drill_intents(
                state_dir,
                snapshot=final_snapshot,
                now=final_snapshot.captured_at,
            )
        except SchedulerVisibilityPending:
            if time.monotonic() >= deadline:
                raise
            if poll_seconds > 0:
                time.sleep(poll_seconds)
            final_snapshot = reader()
            continue
        state = load_drill_state(state_dir)
        all_live_drills = _all_live_drill_jobs(final_snapshot)
        malformed = [
            job.job_id
            for job in all_live_drills
            if parse_drill_job_token(job.comment) is None
        ]
        if malformed:
            raise SchedulerAmbiguity(
                "malformed controller-drill jobs remain live during finish: "
                + ", ".join(sorted(malformed))
            )
        foreign = [
            job.job_id
            for job in all_live_drills
            if parse_drill_job_token(job.comment).get("drill") != drill_id
        ]
        if foreign:
            raise SchedulerAmbiguity(
                f"foreign controller-drill jobs remain live during finish: {sorted(foreign)}"
            )
        live = _live_drill_jobs(final_snapshot, drill_id)
        if live:
            clean_snapshots = 0
            recorded: dict[str, dict[str, Any]] = {}
            for row in state["roles"].values():
                for field in ("active", "successor", "submission_intent"):
                    record = row.get(field)
                    if isinstance(record, dict) and record.get("job_id"):
                        recorded[str(record["job_id"])] = record
            for job in live:
                record = recorded.get(job.job_id)
                if (
                    record is None
                    or job.comment != record.get("job_token")
                    or (
                        record.get("dependency_job_id") is not None
                        and not _dependency_binds_exact_afterany(
                            job.dependency, str(record["dependency_job_id"])
                        )
                    )
                ):
                    raise SchedulerAmbiguity(
                        f"refusing drill cleanup of unmapped exact job {job.job_id}"
                    )
                try:
                    _validate_exact_sbatch_record_proof(
                        record,
                        job_id=job.job_id,
                        context=f"drill cleanup job {job.job_id}",
                    )
                except ControlError as exc:
                    raise SchedulerAmbiguity(
                        f"refusing drill cleanup of unmapped exact job {job.job_id}"
                    ) from exc
            new_targets = sorted(
                (job for job in live if job.job_id not in cancelled_job_ids),
                key=lambda item: item.job_id,
            )
            if new_targets:
                with drill_lock(state_dir):
                    state = load_drill_state(state_dir)
                    cleanup_ids = set(state.get("cleanup_job_ids", []))
                    cleanup_ids.update(job.job_id for job in new_targets)
                    state["cleanup_job_ids"] = sorted(cleanup_ids)
                    _append_drill_event(
                        state_dir,
                        state,
                        event="cleanup_targets_committed",
                        details={"job_ids": [job.job_id for job in new_targets]},
                        now=timestamp,
                    )
                    _save_drill_state(state_dir, state, now=timestamp)
                for job in new_targets:
                    proc = runner(["scancel", job.job_id])
                    if proc.returncode != 0:
                        raise ControlError(
                            f"failed exact drill cleanup {job.job_id}: "
                            f"{proc.stderr.strip()[:500]}"
                        )
                    cancelled_job_ids.add(job.job_id)
        else:
            clean_snapshots += 1
            # A second independent, complete scheduler read closes the narrow window
            # in which an after-any successor is released as its parent disappears.
            if clean_snapshots >= 2:
                break
        if time.monotonic() >= deadline:
            ids = [job.job_id for job in _live_drill_jobs(final_snapshot, drill_id)]
            raise ControlError(f"controller-drill cleanup timed out for jobs {ids}")
        if poll_seconds > 0:
            time.sleep(poll_seconds)
        final_snapshot = reader()
    control = _assert_drill_control_paused(
        state_dir, expected_immutable_sha256=state["immutable_sha256"]
    )
    current_baseline = controller_drill_baseline(state_dir, control)
    if current_baseline != state["baseline"]:
        raise ControlError(
            "controller drill changed production fairness, ledger, or run data"
        )
    reconciliation = reconcile_control(
        state_dir,
        snapshot=final_snapshot,
        all_jobs=True,
        no_admit=True,
        now=timestamp,
    )
    if not reconciliation["passed"]:
        raise SchedulerAmbiguity(
            "post-drill scheduler reconciliation failed: "
            + "; ".join(reconciliation["errors"])
        )
    reconciliation_path, reconciliation_sha = _publish_drill_reconciliation(
        state_dir, drill_id
    )
    with drill_lock(state_dir):
        state = load_drill_state(state_dir)
        state["phase"] = "completed"
        state["final_reconciliation_path"] = str(reconciliation_path)
        state["final_reconciliation_sha256"] = reconciliation_sha
        state["completed_at"] = utc_timestamp(timestamp)
        state["completed_timestamp"] = timestamp
        _append_drill_event(
            state_dir,
            state,
            event="completed",
            details={
                "final_reconciliation_path": str(reconciliation_path),
                "final_reconciliation_sha256": reconciliation_sha,
            },
            now=timestamp,
        )
        _save_drill_state(state_dir, state, now=timestamp)
        _validate_completed_drill_history(state)
    marker = _completed_drill_marker_payload(state_dir, state)
    # All job cleanup, reconciliation, and state fsyncs precede this marker-last write.
    _atomic_write_json(marker_path, marker)
    return marker


def _update_admission_safety_hold_locked(
    state_dir: Path,
    control: dict[str, Any],
    *,
    active_critical_keys: Sequence[str],
    clean_poll: bool,
    semantic_scan_clean: bool | None,
    timestamp: float,
) -> bool:
    """Mutate one loaded control record while both admission/control locks are held.

    Keeping this primitive lock-free lets critical-alert persistence and ceiling-zero
    fencing share one uninterrupted admission boundary.  Callers must save ``control``
    when the return value is true.
    """

    requested = {
        str(key) for key in active_critical_keys if isinstance(key, str) and key
    }
    requested.update(_active_critical_alerts(control))
    existing_hold = control["admission_safety_hold"]
    if existing_hold["active"] and existing_hold["mode"] == "operator":
        # An operator transaction and monitor incident are two independent fences.
        # Keep incident reasons layered on the operator hold until their *own*
        # transient/integrity clearing contract has run; merely resolving the live
        # alert must never let capacity completion erase the incident.
        capacity_reasons = sorted(
            reason
            for reason in existing_hold["reasons"]
            if reason.startswith("capacity-transition:")
        )
        if len(capacity_reasons) != 1:
            raise ControlError("operator capacity hold lost its unique transaction cause")
        observed = sorted(requested)
        prior_incidents = sorted(
            reason
            for reason in existing_hold["reasons"]
            if not reason.startswith("capacity-transition:")
        )
        epoch_closed = False
        if observed:
            # Throughput acceptance is based on continuous clean operation.  A
            # critical incident invalidates the active measurement interval, while
            # ordinary controller successors never call this path.
            epoch_closed = _close_open_epoch(
                control, reason="admission_safety_hold", now=timestamp
            )
        before = copy.deepcopy(existing_hold)
        if observed:
            incident_reasons = observed
            existing_hold["consecutive_clean_polls"] = 0
            existing_hold["semantic_clean_after_activation"] = False
            existing_hold["acknowledged_at"] = None
            existing_hold["acknowledged_timestamp"] = None
        else:
            incident_reasons = prior_incidents
            if semantic_scan_clean is True and incident_reasons:
                existing_hold["semantic_clean_after_activation"] = True
            if clean_poll and incident_reasons:
                existing_hold["consecutive_clean_polls"] = (
                    int(existing_hold["consecutive_clean_polls"]) + 1
                )
            transient = [
                reason
                for reason in incident_reasons
                if reason not in SCIENTIFIC_INTEGRITY_ALERT_KEYS
            ]
            if (
                transient
                and existing_hold["consecutive_clean_polls"]
                >= ADMISSION_SAFETY_HOLD_CLEAR_POLLS
            ):
                incident_reasons = [
                    reason
                    for reason in incident_reasons
                    if reason in SCIENTIFIC_INTEGRITY_ALERT_KEYS
                ]
                existing_hold["consecutive_clean_polls"] = 0
        existing_hold["reasons"] = sorted(
            [*capacity_reasons, *incident_reasons]
        )
        existing_hold["updated_at"] = utc_timestamp(timestamp)
        existing_hold["updated_timestamp"] = timestamp
        changed = existing_hold != before or epoch_closed
        if changed:
            existing_hold["history"].append(
                {
                    "event": "updated",
                    "mode": "operator",
                    "reasons": list(existing_hold["reasons"]),
                    "at": utc_timestamp(timestamp),
                    "timestamp": timestamp,
                }
            )
            append_transition(
                state_dir,
                control,
                event="admission_safety_hold_updated",
                details={
                    "active": True,
                    "mode": "operator",
                    "reasons": list(existing_hold["reasons"]),
                    "consecutive_clean_polls": existing_hold[
                        "consecutive_clean_polls"
                    ],
                    "effective_ceiling": 0,
                },
                now=timestamp,
            )
        return changed
    reasons = sorted(requested)
    hold = existing_hold
    # The 48-hour gate is a continuous-clean-operation contract.  Persistently close
    # its active epoch at the same transaction boundary that drops admission to zero.
    # A later successful production poll opens a new epoch; controller successors
    # alone do not reset it.
    changed = bool(
        reasons
        and _close_open_epoch(
            control, reason="admission_safety_hold", now=timestamp
        )
    )
    event: str | None = None
    if reasons:
        mode = (
            "integrity"
            if set(reasons) & SCIENTIFIC_INTEGRITY_ALERT_KEYS
            else "transient"
        )
        if hold["active"] and hold["mode"] in {"integrity", "operator"}:
            mode = str(hold["mode"])
        if not hold["active"]:
            hold["active"] = True
            hold["activation_id"] = uuid.uuid4().hex
            hold["activated_at"] = utc_timestamp(timestamp)
            hold["activated_timestamp"] = timestamp
            event = "activated"
            changed = True
        elif hold["reasons"] != reasons or hold["mode"] != mode:
            event = "updated"
            changed = True
        elif (
            hold["consecutive_clean_polls"] != 0
            or hold["semantic_clean_after_activation"] is True
        ):
            event = "updated"
            changed = True
        hold["mode"] = mode
        hold["reasons"] = reasons
        hold["consecutive_clean_polls"] = 0
        # Any newly observed critical finding invalidates a prior clean scan;
        # integrity acknowledgement must always follow the latest incident.
        hold["semantic_clean_after_activation"] = False
        hold["updated_at"] = utc_timestamp(timestamp)
        hold["updated_timestamp"] = timestamp
        hold["acknowledged_at"] = None
        hold["acknowledged_timestamp"] = None
    elif hold["active"]:
        if semantic_scan_clean is True:
            if not hold["semantic_clean_after_activation"]:
                changed = True
            hold["semantic_clean_after_activation"] = True
        if clean_poll:
            hold["consecutive_clean_polls"] = (
                int(hold["consecutive_clean_polls"]) + 1
            )
            changed = True
        hold["updated_at"] = utc_timestamp(timestamp)
        hold["updated_timestamp"] = timestamp
        if (
            hold["mode"] == "transient"
            and hold["consecutive_clean_polls"]
            >= ADMISSION_SAFETY_HOLD_CLEAR_POLLS
        ):
            previous_reasons = list(hold["reasons"])
            hold["history"].append(
                {
                    "event": "cleared",
                    "mode": "transient",
                    "reasons": previous_reasons,
                    "at": utc_timestamp(timestamp),
                    "timestamp": timestamp,
                    "clear_reason": "two_clean_health_polls",
                }
            )
            hold.update(
                {
                    "active": False,
                    "mode": None,
                    "reasons": [],
                    "consecutive_clean_polls": 0,
                    "semantic_clean_after_activation": False,
                    "activated_at": None,
                    "activated_timestamp": None,
                    "activation_id": None,
                    "acknowledged_at": None,
                    "acknowledged_timestamp": None,
                }
            )
            event = "cleared"
    if event in {"activated", "updated"}:
        hold["history"].append(
            {
                "event": event,
                "mode": hold["mode"],
                "reasons": list(hold["reasons"]),
                "at": utc_timestamp(timestamp),
                "timestamp": timestamp,
            }
        )
    if changed or event is not None:
        append_transition(
            state_dir,
            control,
            event=f"admission_safety_hold_{event or 'observed'}",
            details={
                "active": hold["active"],
                "mode": hold["mode"],
                "reasons": list(hold["reasons"]),
                "consecutive_clean_polls": hold[
                    "consecutive_clean_polls"
                ],
                "effective_ceiling": 0 if hold["active"] else hold[
                    "configured_ceiling"
                ],
            },
            now=timestamp,
        )
    return changed or event is not None


def update_admission_safety_hold(
    state_dir: Path,
    *,
    active_critical_keys: Sequence[str] = (),
    clean_poll: bool = False,
    semantic_scan_clean: bool | None = None,
    scheduler: SchedulerSnapshot | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    signal_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Transactionally fence cell admission from durable monitor truth.

    The staged ramp ceiling remains intact as ``configured_ceiling`` so a transient
    incident cannot silently promote or demote the scientific rollout.  The public
    dispatcher contract exposes an effective ceiling of zero while this record is
    active.  Two distinct clean polls clear transient holds; integrity holds require a
    clean semantic scan followed by the explicit :func:`acknowledge_admission_hold`.
    """

    timestamp = time.time() if now is None else float(now)
    if scheduler is not None and scheduler_reader is not None:
        raise ControlError(
            "safety-hold update accepts scheduler or scheduler_reader, not both"
        )
    with admission_boundary_lock(state_dir):
        current = load_control(state_dir)
        if (
            current["desired_state"] == "running"
            and current["admission_safety_hold"]["active"]
            and not _safety_hold_drain_complete_for_current_activation(
                current
            )
        ):
            # A clean poll is not evidence that an earlier signal failure was
            # repaired.  Complete the exact activation/generation drain before
            # advancing any clean counter or releasing any transient cause.
            _ensure_safety_hold_cell_drain_locked(
                state_dir,
                scheduler=scheduler,
                scheduler_reader=scheduler_reader,
                signal_runner=signal_runner,
                now=timestamp,
            )
        with control_lock(state_dir):
            control = load_control(state_dir)
            was_active = bool(control["admission_safety_hold"]["active"])
            changed = _update_admission_safety_hold_locked(
                state_dir,
                control,
                active_critical_keys=active_critical_keys,
                clean_poll=clean_poll,
                semantic_scan_clean=semantic_scan_clean,
                timestamp=timestamp,
            )
            if changed:
                _save_control(state_dir, control, now=timestamp)
            is_active = bool(control["admission_safety_hold"]["active"])
        if is_active and (
            not was_active
            or not _safety_hold_drain_complete_for_current_activation(
                control
            )
        ):
            control = _ensure_safety_hold_cell_drain_locked(
                state_dir,
                scheduler=scheduler,
                scheduler_reader=scheduler_reader,
                signal_runner=signal_runner,
                now=timestamp,
            )
        return copy.deepcopy(control)


def acknowledge_admission_hold(
    state_dir: Path, *, note: str, now: float | None = None
) -> dict[str, Any]:
    """Explicitly release a semantically-cleared scientific-integrity hold."""

    if not isinstance(note, str) or not note.strip():
        raise ControlError("ack-hold requires a non-empty operator note")
    timestamp = time.time() if now is None else float(now)
    with admission_boundary_lock(state_dir):
        with control_lock(state_dir):
            control = load_control(state_dir)
            hold = control["admission_safety_hold"]
            layered_operator_integrity = bool(
                hold["active"]
                and hold["mode"] == "operator"
                and set(hold["reasons"]) & SCIENTIFIC_INTEGRITY_ALERT_KEYS
            )
            if (
                not hold["active"]
                or (
                    hold["mode"] != "integrity"
                    and not layered_operator_integrity
                )
            ):
                raise ControlError("there is no active scientific-integrity hold")
            capacity_remediation = sorted(
                set(hold["reasons"]) & CAPACITY_REMEDIATION_ALERT_KEYS
            )
            if capacity_remediation:
                raise ControlError(
                    "capacity-gate hold requires the controlled capacity-transition "
                    "workflow and cannot be released by ack-hold: "
                    + ", ".join(capacity_remediation)
                )
            active_critical = _active_critical_alerts(control)
            if active_critical:
                raise ControlError(
                    "cannot acknowledge hold with unresolved critical alerts: "
                    + ", ".join(active_critical)
                )
            if hold["semantic_clean_after_activation"] is not True:
                raise ControlError(
                    "cannot acknowledge hold before a clean post-incident semantic scan"
                )
            previous_reasons = list(hold["reasons"])
            if layered_operator_integrity:
                remaining = [
                    reason
                    for reason in hold["reasons"]
                    if reason not in SCIENTIFIC_INTEGRITY_ALERT_KEYS
                ]
                if not any(
                    reason.startswith("capacity-transition:")
                    for reason in remaining
                ):
                    raise ControlError(
                        "layered integrity acknowledgement lost capacity cause"
                    )
                hold["history"].append(
                    {
                        "event": "updated",
                        "mode": "operator",
                        "reasons": remaining,
                        "at": utc_timestamp(timestamp),
                        "timestamp": timestamp,
                        "clear_reason": "explicit_layered_integrity_acknowledgement",
                        "operator_note": note.strip()[:2000],
                    }
                )
                hold.update(
                    {
                        "reasons": remaining,
                        "consecutive_clean_polls": 0,
                        "semantic_clean_after_activation": False,
                        "updated_at": utc_timestamp(timestamp),
                        "updated_timestamp": timestamp,
                        "acknowledged_at": utc_timestamp(timestamp),
                        "acknowledged_timestamp": timestamp,
                    }
                )
                append_transition(
                    state_dir,
                    control,
                    event="admission_safety_hold_acknowledged",
                    details={
                        "previous_reasons": previous_reasons,
                        "remaining_operator_reasons": remaining,
                        "operator_note": note.strip()[:2000],
                    },
                    now=timestamp,
                )
                _save_control(state_dir, control, now=timestamp)
                return copy.deepcopy(control)
            hold["history"].append(
                {
                    "event": "cleared",
                    "mode": "integrity",
                    "reasons": previous_reasons,
                    "at": utc_timestamp(timestamp),
                    "timestamp": timestamp,
                    "clear_reason": "explicit_operator_acknowledgement",
                    "operator_note": note.strip()[:2000],
                }
            )
            hold.update(
                {
                    "active": False,
                    "mode": None,
                    "reasons": [],
                    "consecutive_clean_polls": 0,
                    "semantic_clean_after_activation": False,
                    "activated_at": None,
                    "activated_timestamp": None,
                    "activation_id": None,
                    "updated_at": utc_timestamp(timestamp),
                    "updated_timestamp": timestamp,
                    "acknowledged_at": utc_timestamp(timestamp),
                    "acknowledged_timestamp": timestamp,
                }
            )
            append_transition(
                state_dir,
                control,
                event="admission_safety_hold_acknowledged",
                details={
                    "previous_reasons": previous_reasons,
                    "operator_note": note.strip()[:2000],
                    "effective_ceiling": hold["configured_ceiling"],
                },
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
            return copy.deepcopy(control)


def _new_alert_email_state() -> dict[str, Any]:
    return {
        "requested": False,
        "attempted": False,
        "delivered": False,
        "attempt_count": 0,
        "attempted_at": None,
        "attempted_timestamp": None,
        "delivered_at": None,
        "delivered_timestamp": None,
        "next_retry_at": None,
        "next_retry_timestamp": None,
        "in_flight_token": None,
        "error": None,
    }


def _attempt_alert_email(
    state_dir: Path,
    *,
    alert_id: str,
    mail_runner: (
        Callable[[Sequence[str], str], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> bool:
    """Deliver one alert from a persisted intent and durably schedule failures."""

    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        match = next(
            (row for row in control["alerts"] if row.get("alert_id") == alert_id),
            None,
        )
        if match is None:
            raise ControlError(f"unknown alert email target {alert_id!r}")
        email_state = match.get("email")
        if not isinstance(email_state, dict):
            email_state = _new_alert_email_state()
            match["email"] = email_state
        if (
            match.get("resolved_at") is not None
            or email_state.get("requested") is not True
            or email_state.get("delivered") is True
        ):
            return bool(email_state.get("delivered"))
        next_retry = email_state.get("next_retry_timestamp")
        if isinstance(next_retry, (int, float)) and timestamp < float(next_retry):
            return False
        in_flight = email_state.get("in_flight_token")
        last_attempt = email_state.get("attempted_timestamp")
        if (
            isinstance(in_flight, str)
            and in_flight
            and isinstance(last_attempt, (int, float))
            and timestamp - float(last_attempt) < 300.0
        ):
            return False
        token = uuid.uuid4().hex
        attempt_count = int(email_state.get("attempt_count", 0)) + 1
        email_state.update(
            {
                "attempted": True,
                "attempt_count": attempt_count,
                "attempted_at": utc_timestamp(timestamp),
                "attempted_timestamp": timestamp,
                "in_flight_token": token,
                "error": None,
            }
        )
        _append_jsonl(
            state_dir / ALERT_JOURNAL,
            {
                "at": utc_timestamp(timestamp),
                "timestamp": timestamp,
                "action": "email_attempt_started",
                "alert_id": alert_id,
                "attempt": attempt_count,
                "intent_token": token,
            },
        )
        _save_control(state_dir, control, now=timestamp)
        recipient = str(control["alert_email"])
        severity = str(match["severity"])
        kind = str(match["kind"])
        message = str(match["message"])

    subject = f"[agents-scaling:{severity}] {kind}"
    body = (
        f"Schema-5 sweep alert\n\nKind: {kind}\nSeverity: {severity}\n"
        f"Time: {utc_timestamp(timestamp)}\nState: {state_dir}\n\n{message}\n"
    )
    delivered = False
    error: str | None = None
    try:
        if mail_runner is not None:
            proc = mail_runner(["mail", "-s", subject, recipient], body)
        else:
            proc = subprocess.run(
                _trusted_system_argv(["mail", "-s", subject, recipient]),
                input=body,
                capture_output=True,
                text=True,
                check=False,
                timeout=30.0,
                env=_sanitized_subprocess_environment(),
            )
        delivered = proc.returncode == 0
        error = None if delivered else proc.stderr.strip()[:500]
    except Exception as exc:
        error = f"{type(exc).__name__}: {exc}"[:500]

    completed = time.time() if now is None else timestamp
    with control_lock(state_dir):
        control = load_control(state_dir)
        match = next(
            row for row in control["alerts"] if row.get("alert_id") == alert_id
        )
        email_state = match["email"]
        if email_state.get("in_flight_token") != token:
            raise ControlError("alert email delivery intent was superseded")
        email_state["in_flight_token"] = None
        email_state["error"] = error
        if delivered:
            email_state["delivered"] = True
            email_state["delivered_at"] = utc_timestamp(completed)
            email_state["delivered_timestamp"] = completed
            email_state["next_retry_at"] = None
            email_state["next_retry_timestamp"] = None
        else:
            delay = EMAIL_RETRY_DELAYS_SECONDS[
                min(attempt_count - 1, len(EMAIL_RETRY_DELAYS_SECONDS) - 1)
            ]
            retry_at = completed + delay
            email_state["next_retry_at"] = utc_timestamp(retry_at)
            email_state["next_retry_timestamp"] = retry_at
        _append_jsonl(
            state_dir / ALERT_JOURNAL,
            {
                "at": utc_timestamp(completed),
                "timestamp": completed,
                "action": "email_delivered" if delivered else "email_retry_scheduled",
                "alert_id": alert_id,
                "attempt": attempt_count,
                "delivered": delivered,
                "error": error,
                "next_retry_timestamp": email_state["next_retry_timestamp"],
            },
        )
        _save_control(state_dir, control, now=completed)
    return delivered


def retry_pending_alert_emails(
    state_dir: Path,
    *,
    mail_runner: (
        Callable[[Sequence[str], str], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
    maximum_attempts: int | None = None,
) -> dict[str, Any]:
    """Retry all eligible unresolved alerts; only confirmed delivery deduplicates."""

    timestamp = time.time() if now is None else float(now)
    control = load_control(state_dir)
    eligible: list[str] = []
    for alert in control["alerts"]:
        email = alert.get("email")
        if (
            alert.get("resolved_at") is not None
            or not isinstance(email, dict)
            or email.get("requested") is not True
            or email.get("delivered") is True
            or (
                maximum_attempts is not None
                and int(email.get("attempt_count", 0)) >= maximum_attempts
            )
        ):
            continue
        next_retry = email.get("next_retry_timestamp")
        if next_retry is None or timestamp >= float(next_retry):
            eligible.append(str(alert["alert_id"]))
    delivered: list[str] = []
    attempted: list[str] = []
    for alert_id in eligible:
        attempted.append(alert_id)
        if _attempt_alert_email(
            state_dir,
            alert_id=alert_id,
            mail_runner=mail_runner,
            now=timestamp,
        ):
            delivered.append(alert_id)
    return {"attempted": attempted, "delivered": delivered}


def record_alert(
    state_dir: Path,
    *,
    kind: str,
    severity: str,
    message: str,
    dedupe_key: str,
    send_email: bool = False,
    mail_runner: (
        Callable[[Sequence[str], str], subprocess.CompletedProcess[str]] | None
    ) = None,
    scheduler: SchedulerSnapshot | None = None,
    scheduler_reader: Callable[[], SchedulerSnapshot] | None = None,
    signal_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Persist a deduplicated alert before attempting best-effort email delivery."""
    if severity not in {"warning", "critical"}:
        raise ControlError("alert severity must be warning or critical")
    if not kind or not message or not dedupe_key:
        raise ControlError("alert kind, message, and dedupe key must be non-empty")
    if scheduler is not None and scheduler_reader is not None:
        raise ControlError("critical alert accepts scheduler or scheduler_reader, not both")
    timestamp = time.time() if now is None else float(now)
    # A critical alert is itself a fail-closed admission fact.  Persist it while
    # owning the same cross-node boundary as cell sbatch so a new array cannot slip
    # between detection and the durable hold update below.
    boundary = (
        admission_boundary_lock(state_dir)
        if severity == "critical"
        else nullcontext()
    )
    drain_error: Exception | None = None
    with boundary:
        with control_lock(state_dir):
            control = load_control(state_dir)
            active = next(
                (
                    alert
                    for alert in reversed(control["alerts"])
                    if alert.get("dedupe_key") == dedupe_key
                    and alert.get("resolved_at") is None
                ),
                None,
            )
            if active is None:
                payload: dict[str, Any] = {
                    "alert_id": uuid.uuid4().hex,
                    "kind": kind,
                    "severity": severity,
                    "message": message,
                    "dedupe_key": dedupe_key,
                    "first_at": utc_timestamp(timestamp),
                    "first_timestamp": timestamp,
                    "last_at": utc_timestamp(timestamp),
                    "last_timestamp": timestamp,
                    "occurrences": 1,
                    "resolved_at": None,
                    "email": _new_alert_email_state(),
                }
                control["alerts"].append(payload)
            else:
                if (
                    active.get("kind") != kind
                    or active.get("severity") != severity
                ):
                    raise ControlError(
                        "active alert dedupe key cannot change kind or severity"
                    )
                active["occurrences"] = int(active.get("occurrences", 1)) + 1
                active["last_at"] = utc_timestamp(timestamp)
                active["last_timestamp"] = timestamp
                active["message"] = message
                payload = active
            if send_email and payload["email"].get("delivered") is not True:
                payload["email"]["requested"] = True
                if payload["email"].get("next_retry_timestamp") is None:
                    payload["email"]["next_retry_at"] = utc_timestamp(timestamp)
                    payload["email"]["next_retry_timestamp"] = timestamp
            journal_record = {
                "at": utc_timestamp(timestamp),
                "timestamp": timestamp,
                "action": "raised",
                "alert_id": payload["alert_id"],
                "kind": kind,
                "severity": severity,
                "message": message,
                "dedupe_key": dedupe_key,
                "occurrences": payload["occurrences"],
            }
            _append_jsonl(state_dir / ALERT_JOURNAL, journal_record)
            append_transition(
                state_dir,
                control,
                event="alert_raised",
                details={
                    "alert_id": payload["alert_id"],
                    "kind": kind,
                    "severity": severity,
                    "dedupe_key": dedupe_key,
                },
                now=timestamp,
            )
            if severity == "critical":
                _update_admission_safety_hold_locked(
                    state_dir,
                    control,
                    active_critical_keys=(dedupe_key,),
                    clean_poll=False,
                    semantic_scan_clean=None,
                    timestamp=timestamp,
                )
            _save_control(state_dir, control, now=timestamp)
            alert_id = str(payload["alert_id"])
        if severity == "critical":
            try:
                _ensure_safety_hold_cell_drain_locked(
                    state_dir,
                    scheduler=scheduler,
                    scheduler_reader=scheduler_reader,
                    signal_runner=signal_runner,
                    now=timestamp,
                )
            except Exception as exc:
                # The critical alert and ceiling-zero hold are already durable.  Finish
                # best-effort alert delivery after releasing the admission boundary,
                # then surface the drain failure so the controller cannot report a
                # healthy monitor cycle.
                drain_error = exc
    if send_email:
        _attempt_alert_email(
            state_dir,
            alert_id=alert_id,
            mail_runner=mail_runner,
            now=timestamp,
        )
    if drain_error is not None:
        raise drain_error
    return next(
        alert
        for alert in load_control(state_dir)["alerts"]
        if alert["alert_id"] == alert_id
    )


def resolve_alert(
    state_dir: Path, *, dedupe_key: str, now: float | None = None
) -> dict[str, Any]:
    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        matches = [
            alert
            for alert in control["alerts"]
            if alert.get("dedupe_key") == dedupe_key
            and alert.get("resolved_at") is None
        ]
        for alert in matches:
            alert["resolved_at"] = utc_timestamp(timestamp)
            alert["resolved_timestamp"] = timestamp
            _append_jsonl(
                state_dir / ALERT_JOURNAL,
                {
                    "at": utc_timestamp(timestamp),
                    "timestamp": timestamp,
                    "action": "resolved",
                    "alert_id": alert["alert_id"],
                    "dedupe_key": dedupe_key,
                },
            )
        if matches:
            append_transition(
                state_dir,
                control,
                event="alert_resolved",
                details={"dedupe_key": dedupe_key, "count": len(matches)},
                now=timestamp,
            )
            _save_control(state_dir, control, now=timestamp)
        return control


def _heartbeat_age(record: Any, now: float) -> float | None:
    if not isinstance(record, dict) or not isinstance(
        record.get("timestamp"), (int, float)
    ):
        return None
    return max(0.0, now - float(record["timestamp"]))


def controller_liveness_age(role_state: Mapping[str, Any], now: float) -> float | None:
    """Age a role from heartbeat, falling back to its most recent durable submission."""
    heartbeat_age = _heartbeat_age(role_state.get("heartbeat"), now)
    if heartbeat_age is not None:
        return heartbeat_age
    candidates: list[float] = []
    for field in ("active", "successor", "submission_intent"):
        record = role_state.get(field)
        if not isinstance(record, dict):
            continue
        for timestamp_field in (
            "claimed_timestamp",
            "submitted_timestamp",
            "created_timestamp",
        ):
            value = record.get(timestamp_field)
            if isinstance(value, (int, float)):
                candidates.append(float(value))
                break
    return max(0.0, now - max(candidates)) if candidates else None


def _cell_job(name: str) -> bool:
    return name == "asys-cells" or any(
        name.startswith(prefix) for prefix in CELL_JOB_PREFIXES
    )


def _finalizer_status_row(
    snapshot: SchedulerSnapshot,
    record: Any,
    *,
    timestamp: float,
    field: str,
) -> dict[str, Any]:
    """Project one durable finalizer identity onto current scheduler truth."""

    if not isinstance(record, Mapping):
        return {
            "recorded": False,
            "recorded_job_id": None,
            "scheduler_job_id": None,
            "attempt": None,
            "job_token": None,
            "sbatch_path": None,
            "dependency_job_id": None,
            "live": False,
            "scheduler_state": None,
            "identity_mismatch": False,
            "adoptable": False,
            "missing": False,
            "missing_after_grace": False,
            "visibility_pending": False,
            "terminal": False,
            "provenance": None,
        }
    job_id = record.get("job_id")
    same_id = (
        [job for job in snapshot.jobs if job.job_id == str(job_id)]
        if isinstance(job_id, str) and job_id
        else []
    )
    same_token = [
        job
        for job in snapshot.jobs
        if job.comment == str(record.get("job_token", ""))
    ]
    provenance: dict[str, Any] | None = None
    identity_mismatch = False
    adoptable = False
    if (
        isinstance(job_id, str)
        and job_id.isdigit()
        and len(same_id) == 1
        and len(same_token) == 1
        and same_id[0] is same_token[0]
    ):
        try:
            provenance = _finalizer_record_scheduler_observation(
                snapshot,
                record,
                same_id[0],
                require_active=None,
                context=f"live-status {field}",
            )
        except (ControlError, SchedulerAmbiguity):
            identity_mismatch = True
    elif (
        job_id is None
        and len(same_token) == 1
        and record.get("state") == "submitting"
    ):
        provisional = copy.deepcopy(dict(record))
        provisional["job_id"] = same_token[0].job_id
        try:
            provenance = _finalizer_record_scheduler_observation(
                snapshot,
                provisional,
                same_token[0],
                require_active=None,
                context=f"live-status adoptable {field}",
            )
            adoptable = True
        except (ControlError, SchedulerAmbiguity):
            identity_mismatch = True
    elif same_id or same_token:
        identity_mismatch = True
    created = record.get(
        "submitted_timestamp", record.get("created_timestamp")
    )
    age = (
        max(0.0, timestamp - float(created))
        if isinstance(created, (int, float)) and not isinstance(created, bool)
        else None
    )
    missing = provenance is None and not identity_mismatch
    visibility_pending = bool(
        missing
        and age is not None
        and age <= SUBMISSION_VISIBILITY_GRACE_SECONDS
        and record.get("state") in {"submitting", "submitted", "started"}
    )
    scheduler_job = (
        same_id[0]
        if len(same_id) == 1
        else (same_token[0] if adoptable else None)
    )
    scheduler_state = (
        normalize_scheduler_state(scheduler_job.state)
        if scheduler_job is not None
        else None
    )
    return {
        "recorded": True,
        "recorded_job_id": job_id,
        "scheduler_job_id": (
            scheduler_job.job_id if scheduler_job is not None else None
        ),
        "attempt": record.get("attempt"),
        "job_token": record.get("job_token"),
        "sbatch_path": record.get("sbatch_path"),
        "dependency_job_id": record.get("dependency_job_id"),
        "live": bool(
            provenance is not None
            and scheduler_state in ACTIVE_SCHEDULER_STATES
        ),
        "scheduler_state": scheduler_state,
        "identity_mismatch": identity_mismatch,
        "adoptable": adoptable,
        "missing": missing,
        "missing_after_grace": bool(missing and not visibility_pending),
        "visibility_pending": visibility_pending,
        "terminal": bool(
            provenance is not None
            and scheduler_state in TERMINAL_SCHEDULER_STATES
        ),
        "provenance": provenance,
    }


def _finalizer_live_status(
    control: Mapping[str, Any],
    snapshot: SchedulerSnapshot,
    *,
    timestamp: float,
) -> dict[str, Any]:
    """Join the autonomous-finalizer ledger to exact scheduler identities."""

    raw = copy.deepcopy(control["finalization"])
    pending_payload = (
        _pending_finalization_request_payload(control)
        if raw["state"] == "idle"
        else None
    )
    pending_request = (
        None
        if pending_payload is None
        else {
            "validated": True,
            "intent_id": pending_payload["intent_id"],
            "requested_timestamp": pending_payload[
                "requested_timestamp"
            ],
            "semantic_evidence_sha256": pending_payload[
                "semantic_evidence"
            ]["sha256"],
            "request_payload_sha256": sha256_value(pending_payload),
        }
    )
    active = _finalizer_status_row(
        snapshot,
        raw.get("active_job"),
        timestamp=timestamp,
        field="active",
    )
    successor = _finalizer_status_row(
        snapshot,
        raw.get("successor_job"),
        timestamp=timestamp,
        field="successor",
    )
    namespace_error: str | None = None
    try:
        namespace_active = _finalizer_namespace_active_job_ids(snapshot)
    except SchedulerAmbiguity as exc:
        namespace_active = sorted(
            {
                job.job_id
                for job in snapshot.jobs
                if job.active
                and (
                    job.comment.startswith(FINALIZER_JOB_TOKEN_PREFIX + ";")
                    or job.job_name.startswith("asys-s5-final-")
                )
            }
        )
        namespace_error = str(exc)
    expected_ids = {
        str(
            row["scheduler_job_id"]
            if row["adoptable"]
            else row["recorded_job_id"]
        )
        for row in (active, successor)
        if isinstance(
            (
                row.get("scheduler_job_id")
                if row.get("adoptable")
                else row.get("recorded_job_id")
            ),
            str,
        )
        and str(
            row.get("scheduler_job_id")
            if row.get("adoptable")
            else row.get("recorded_job_id")
        ).isdigit()
    }
    unexpected = sorted(
        set(namespace_active) - expected_ids,
        key=int,
    )
    scheduler_complete = bool(
        snapshot.squeue_ok
        and snapshot.sacct_ok
        and not snapshot.errors
        and namespace_error is None
    )
    state = raw["state"]
    if state == "idle":
        chain_healthy = bool(
            scheduler_complete
            and pending_request is None
            and not active["recorded"]
            and not successor["recorded"]
            and not namespace_active
        )
    elif state in ACTIVE_FINALIZATION_STATES:
        chain_healthy = bool(
            scheduler_complete
            and active["live"]
            and successor["live"]
            and not active["identity_mismatch"]
            and not successor["identity_mismatch"]
            and successor["dependency_job_id"]
            == active["recorded_job_id"]
            and not unexpected
        )
    elif state == "complete":
        chain_healthy = bool(
            scheduler_complete
            and pending_request is None
            and isinstance(raw.get("completion_marker"), Mapping)
            and active["recorded"]
            and successor["recorded"]
            and not active["live"]
            and not successor["live"]
            and not active["identity_mismatch"]
            and not successor["identity_mismatch"]
            and raw["successor_job"].get("state")
            in {"terminal", "cancelled"}
            and isinstance(raw.get("successor_retirement"), Mapping)
            and raw["successor_retirement"].get("receipt_path") is not None
            and not namespace_active
        )
    else:
        chain_healthy = False
    raw.update(
        {
            "scheduler_complete": scheduler_complete,
            "pending_request": pending_request,
            "active": active,
            "successor": successor,
            "namespace_active_job_ids": namespace_active,
            "unexpected_active_job_ids": unexpected,
            "scheduler_error": namespace_error,
            "chain_healthy": chain_healthy,
        }
    )
    return raw


def _external_watchdog_mirror_root(state_dir: Path) -> Path:
    return state_dir / EXTERNAL_WATCHDOG_MIRROR_DIRNAME


@contextmanager
def external_watchdog_mirror_lock(state_dir: Path) -> Iterator[None]:
    """Serialize the cluster-side half of the external watchdog journal."""

    with _file_lock(
        state_dir / "locks" / "external-watchdog-mirror.lock"
    ):
        yield


@contextmanager
def external_watchdog_mirror_read_lock(state_dir: Path) -> Iterator[None]:
    """Take the journal lock without mutating its diagnostic owner payload."""

    path = state_dir / "locks" / "external-watchdog-mirror.lock"
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_CLOEXEC", 0))
    try:
        fcntl.flock(descriptor, fcntl.LOCK_SH)
        yield
    finally:
        try:
            fcntl.flock(descriptor, fcntl.LOCK_UN)
        finally:
            os.close(descriptor)


def _external_watchdog_tag_object(control: Mapping[str, Any]) -> str:
    immutable = control.get("immutable")
    if not isinstance(immutable, Mapping):
        raise ControlError("watchdog mirror lacks immutable release identity")
    try:
        capacity_authority = effective_protected_capacity_binding(
            control, verify_files=True
        )
        contract = _load_protected_capacity_contract(
            control,
            path=capacity_authority["path"],
            expected_marker_id=str(capacity_authority["marker_id"]),
            expected_sha256=str(capacity_authority["sha256"]),
        )
    except (
        KeyError,
        protected_capacity.ProtectedCapacityError,
    ) as exc:
        raise ControlError(
            "watchdog mirror cannot verify the release tag object"
        ) from exc
    if re.fullmatch(r"[0-9a-f]{40}", contract.release_tag_object) is None:
        raise ControlError("watchdog mirror release tag object is malformed")
    return contract.release_tag_object


def _external_watchdog_control_identity(
    control: Mapping[str, Any],
) -> dict[str, Any]:
    immutable = control.get("immutable")
    finalization = control.get("finalization")
    if not isinstance(immutable, Mapping) or not isinstance(
        finalization, Mapping
    ):
        raise ControlError("watchdog mirror control identity is incomplete")
    pending = finalization.get("pending_request")
    pending_intent_id = (
        pending.get("intent_id") if isinstance(pending, Mapping) else None
    )
    identity = {
        "release_id": immutable.get("release_id"),
        "release_tag": PRODUCTION_OPERATIONAL_TAG,
        "release_tag_object": _external_watchdog_tag_object(control),
        "git_commit": immutable.get("git_commit"),
        "control_sha256": control.get("immutable_sha256"),
        "desired_state": control.get("desired_state"),
        "rollout_generation": control.get("rollout_generation"),
        "finalization": {
            "state": finalization.get("state"),
            "intent_id": finalization.get("intent_id"),
            "pending_request_intent_id": pending_intent_id,
        },
    }
    _validate_external_watchdog_identity(
        identity, description="watchdog mirror current control"
    )
    return identity


def _validate_external_watchdog_identity(
    identity: Any, *, description: str
) -> None:
    expected_fields = {
        "release_id",
        "release_tag",
        "release_tag_object",
        "git_commit",
        "control_sha256",
        "desired_state",
        "rollout_generation",
        "finalization",
    }
    finalization_identity = (
        identity.get("finalization")
        if isinstance(identity, Mapping)
        else None
    )
    if (
        not isinstance(identity, Mapping)
        or set(identity) != expected_fields
        or identity.get("release_id") != PRODUCTION_RELEASE_ID
        or identity.get("release_tag") != PRODUCTION_OPERATIONAL_TAG
        or re.fullmatch(
            r"[0-9a-f]{40}", str(identity.get("release_tag_object", ""))
        )
        is None
        or re.fullmatch(r"[0-9a-f]{40}", str(identity.get("git_commit", "")))
        is None
        or _SHA256_RE.fullmatch(str(identity.get("control_sha256", "")))
        is None
        or identity.get("desired_state") not in {"paused", "resuming", "running"}
        or not isinstance(identity.get("rollout_generation"), int)
        or isinstance(identity.get("rollout_generation"), bool)
        or int(identity.get("rollout_generation", -1)) < 0
        or not isinstance(finalization_identity, Mapping)
        or set(finalization_identity)
        != {"state", "intent_id", "pending_request_intent_id"}
        or finalization_identity.get("state") not in FINALIZATION_STATES
        or any(
            value is not None and _SHA256_RE.fullmatch(str(value)) is None
            for value in (
                finalization_identity.get("intent_id"),
                finalization_identity.get("pending_request_intent_id"),
            )
        )
    ):
        raise ControlError(f"{description} identity is invalid")


def _watchdog_mirror_read(
    path: Path, *, description: str, read_only: bool
) -> tuple[dict[str, Any], bytes]:
    value, raw = _read_stable_json(
        path,
        description=description,
        require_read_only=read_only,
    )
    if raw != _watchdog_canonical_json(value):
        raise ControlError(f"{description} is not canonical JSON")
    return value, raw


def _watchdog_predecessor(
    record: Mapping[str, Any],
    *,
    id_field: str,
    path: Path,
) -> dict[str, Any]:
    return {
        "sequence": int(record["sequence"]),
        "record_id": str(record[id_field]),
        "sha256": sha256_file(path),
    }


def _watchdog_validate_predecessor(
    value: Any,
    *,
    previous: tuple[dict[str, Any], Path] | None,
    id_field: str,
    description: str,
) -> None:
    if previous is None:
        if value is not None:
            raise ControlError(
                f"{description} first record has a predecessor"
            )
        return
    prior, prior_path = previous
    expected = _watchdog_predecessor(
        prior, id_field=id_field, path=prior_path
    )
    if value != expected:
        raise ControlError(f"{description} predecessor chain is invalid")


def _watchdog_sequence_files(
    directory: Path, *, description: str
) -> list[Path]:
    if not directory.exists():
        return []
    if directory.is_symlink() or not directory.is_dir():
        raise ControlError(f"{description} directory is unsafe")
    paths: list[Path] = []
    pattern = re.compile(r"(?P<sequence>[0-9]{12})-(?P<id>[0-9a-f]{64})\.json\Z")
    for path in sorted(directory.iterdir(), key=lambda item: item.name):
        if path.name.startswith("."):
            raise ControlError(
                f"{description} has an incomplete or foreign hidden entry: {path}"
            )
        if pattern.fullmatch(path.name) is None:
            raise ControlError(f"{description} has a foreign entry: {path}")
        paths.append(path)
    return paths


def _recover_watchdog_publication_temps_locked(state_dir: Path) -> None:
    """Recover only exact immutable-publisher prelinks under the journal lock."""

    root = _external_watchdog_mirror_root(state_dir)
    immutable_directories = (
        "status_receipts",
        "action_intents",
        "action_receipts",
        "cycle_intents",
        "cycle_receipts",
    )
    pattern = re.compile(
        r"^\.(?P<destination>[0-9]{12}-[0-9a-f]{64}\.json)"
        r"\.publish\.(?P<payload>[0-9a-f]{64})"
        r"\.(?P<owner>[0-9a-f]{32})\.tmp\Z"
    )
    for name in immutable_directories:
        directory = root / name
        if not directory.exists():
            continue
        if directory.is_symlink() or not directory.is_dir():
            raise ControlError(
                f"watchdog journal recovery directory is unsafe: {directory}"
            )
        descriptor = os.open(
            directory,
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            for candidate in sorted(
                directory.iterdir(), key=lambda item: item.name
            ):
                if not candidate.name.startswith("."):
                    continue
                match = pattern.fullmatch(candidate.name)
                if match is None or candidate.is_symlink():
                    raise ControlError(
                        "watchdog journal has a foreign publication preimage: "
                        f"{candidate}"
                    )
                metadata = candidate.stat(follow_symlinks=False)
                if (
                    not stat.S_ISREG(metadata.st_mode)
                    or metadata.st_nlink not in {1, 2}
                ):
                    raise ControlError(
                        "watchdog publication preimage identity is unsafe: "
                        f"{candidate}"
                    )
                destination = directory / match.group("destination")
                if stat.S_IMODE(metadata.st_mode) & 0o222:
                    if metadata.st_nlink != 1:
                        raise ControlError(
                            "writable watchdog preimage has multiple links"
                        )
                    candidate.unlink()
                    os.fsync(descriptor)
                    continue
                raw = candidate.read_bytes()
                if hashlib.sha256(raw).hexdigest() != match.group("payload"):
                    raise ControlError(
                        "sealed watchdog publication preimage hash drifted"
                    )
                if destination.exists() or destination.is_symlink():
                    if (
                        destination.is_symlink()
                        or not destination.is_file()
                        or destination.read_bytes() != raw
                    ):
                        raise ControlError(
                            "watchdog publication preimage conflicts with "
                            f"{destination}"
                        )
                else:
                    if metadata.st_nlink != 1:
                        raise ControlError(
                            "watchdog publication preimage lost its destination"
                        )
                    os.link(candidate, destination, follow_symlinks=False)
                    os.fsync(descriptor)
                candidate.unlink()
                os.fsync(descriptor)
        finally:
            os.close(descriptor)

    if root.exists():
        for candidate in root.iterdir():
            if not candidate.name.startswith(".LATEST.json."):
                continue
            if (
                not candidate.name.endswith(".tmp")
                or candidate.is_symlink()
            ):
                raise ControlError(
                    f"watchdog pointer has a foreign temp entry: {candidate}"
                )
            metadata = candidate.stat(follow_symlinks=False)
            if not stat.S_ISREG(metadata.st_mode) or metadata.st_nlink != 1:
                raise ControlError(
                    f"watchdog pointer temp identity is unsafe: {candidate}"
                )
            candidate.unlink()
        directory_descriptor = os.open(
            root,
            os.O_RDONLY
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_CLOEXEC", 0),
        )
        try:
            os.fsync(directory_descriptor)
        finally:
            os.close(directory_descriptor)


def _load_watchdog_status_observations(
    state_dir: Path,
) -> list[tuple[dict[str, Any], Path]]:
    directory = _external_watchdog_mirror_root(state_dir) / "status_receipts"
    result: list[tuple[dict[str, Any], Path]] = []
    previous: tuple[dict[str, Any], Path] | None = None
    expected_fields = {
        "schema_version",
        "protocol",
        "sequence",
        "predecessor",
        "identity",
        "report_sha256",
        "report_captured_timestamp",
        "scheduler_sha256",
        "cluster_server_timestamp",
        "observation_id",
    }
    for expected_sequence, path in enumerate(
        _watchdog_sequence_files(
            directory, description="watchdog status journal"
        ),
        start=1,
    ):
        value, _raw = _watchdog_mirror_read(
            path,
            description="watchdog status receipt",
            read_only=True,
        )
        scheduler_timestamp = value.get("report_captured_timestamp")
        server_timestamp = value.get("cluster_server_timestamp")
        if (
            set(value) != expected_fields
            or value.get("schema_version") != 1
            or value.get("protocol") != EXTERNAL_WATCHDOG_STATUS_PROTOCOL
            or value.get("sequence") != expected_sequence
            or not isinstance(value.get("identity"), Mapping)
            or _SHA256_RE.fullmatch(str(value.get("report_sha256", "")))
            is None
            or _SHA256_RE.fullmatch(str(value.get("scheduler_sha256", "")))
            is None
            or not isinstance(scheduler_timestamp, (int, float))
            or isinstance(scheduler_timestamp, bool)
            or not math.isfinite(float(scheduler_timestamp))
            or not isinstance(server_timestamp, (int, float))
            or isinstance(server_timestamp, bool)
            or not math.isfinite(float(server_timestamp))
            or float(server_timestamp) < float(scheduler_timestamp)
            or value.get("observation_id")
            != _watchdog_self_hash(value, "observation_id")
            or path.name
            != (
                f"{expected_sequence:012d}-"
                f"{value.get('observation_id')}.json"
            )
        ):
            raise ControlError("watchdog status receipt is malformed")
        _validate_external_watchdog_identity(
            value["identity"], description="watchdog status receipt"
        )
        if previous is not None and (
            float(value["report_captured_timestamp"])
            <= float(previous[0]["report_captured_timestamp"])
            or float(value["cluster_server_timestamp"])
            <= float(previous[0]["cluster_server_timestamp"])
        ):
            raise ControlError(
                "watchdog status receipt timestamps are not monotonic"
            )
        _watchdog_validate_predecessor(
            value.get("predecessor"),
            previous=previous,
            id_field="observation_id",
            description="watchdog status journal",
        )
        result.append((value, path))
        previous = (value, path)
    return result


def record_external_watchdog_status_observation(
    state_dir: Path,
    *,
    report: Mapping[str, Any],
    now: float | None = None,
) -> dict[str, Any]:
    """Seal the exact report returned by the fixed external status selector."""

    timestamp = time.time() if now is None else float(now)
    if not math.isfinite(timestamp):
        raise ControlError("watchdog status server timestamp is invalid")
    scheduler = report.get("scheduler")
    captured = report.get("captured_timestamp")
    if (
        not isinstance(scheduler, Mapping)
        or scheduler.get("squeue_ok") is not True
        or scheduler.get("sacct_ok") is not True
        or scheduler.get("errors") not in ([], ())
        or not isinstance(captured, (int, float))
        or isinstance(captured, bool)
        or not math.isfinite(float(captured))
        or timestamp < float(captured)
    ):
        raise SchedulerAmbiguity(
            "watchdog status receipt requires complete current scheduler truth"
        )
    control = load_control(state_dir, verify_files=True)
    identity = _external_watchdog_control_identity(control)
    for field, expected in (
        ("release_id", identity["release_id"]),
        ("git_commit", identity["git_commit"]),
        ("immutable_sha256", identity["control_sha256"]),
        ("desired_state", identity["desired_state"]),
        ("rollout_generation", identity["rollout_generation"]),
    ):
        if report.get(field) != expected:
            raise ControlError(
                f"watchdog status report {field} differs from current control"
            )
    finalization = report.get("finalization")
    if (
        not isinstance(finalization, Mapping)
        or finalization.get("state")
        != identity["finalization"]["state"]
        or finalization.get("intent_id")
        != identity["finalization"]["intent_id"]
    ):
        raise ControlError(
            "watchdog status report finalization identity drifted"
        )
    with external_watchdog_mirror_lock(state_dir):
        _recover_watchdog_publication_temps_locked(state_dir)
        prior = _load_watchdog_status_observations(state_dir)
        sequence = len(prior) + 1
        record: dict[str, Any] = {
            "schema_version": 1,
            "protocol": EXTERNAL_WATCHDOG_STATUS_PROTOCOL,
            "sequence": sequence,
            "predecessor": (
                _watchdog_predecessor(
                    prior[-1][0],
                    id_field="observation_id",
                    path=prior[-1][1],
                )
                if prior
                else None
            ),
            "identity": identity,
            "report_sha256": hashlib.sha256(
                _watchdog_canonical_json(dict(report))
            ).hexdigest(),
            "report_captured_timestamp": float(captured),
            "scheduler_sha256": sha256_value(scheduler),
            "cluster_server_timestamp": timestamp,
        }
        record["observation_id"] = _watchdog_self_hash(
            record, "observation_id"
        )
        path = (
            _external_watchdog_mirror_root(state_dir)
            / "status_receipts"
            / f"{sequence:012d}-{record['observation_id']}.json"
        )
        _atomic_publish_readonly_json(path, record)
        return {
            "sequence": sequence,
            "observation_id": record["observation_id"],
            "path": str(path.resolve()),
            "sha256": sha256_file(path),
            "report_sha256": record["report_sha256"],
            "report_captured_timestamp": record[
                "report_captured_timestamp"
            ],
        }


def _load_watchdog_action_intents(
    state_dir: Path,
) -> list[tuple[dict[str, Any], Path]]:
    directory = _external_watchdog_mirror_root(state_dir) / "action_intents"
    result: list[tuple[dict[str, Any], Path]] = []
    expected_fields = {
        "schema_version",
        "protocol",
        "sequence",
        "action",
        "identity_before",
        "started_timestamp",
        "intent_id",
    }
    for expected_sequence, path in enumerate(
        _watchdog_sequence_files(
            directory, description="watchdog action-intent journal"
        ),
        start=1,
    ):
        value, _raw = _watchdog_mirror_read(
            path,
            description="watchdog action intent",
            read_only=True,
        )
        timestamp = value.get("started_timestamp")
        if (
            set(value) != expected_fields
            or value.get("schema_version") != 1
            or value.get("protocol")
            != EXTERNAL_WATCHDOG_ACTION_INTENT_PROTOCOL
            or value.get("sequence") != expected_sequence
            or value.get("action")
            not in {"repair-chain", "finalizer-reconcile"}
            or not isinstance(value.get("identity_before"), Mapping)
            or not isinstance(timestamp, (int, float))
            or isinstance(timestamp, bool)
            or not math.isfinite(float(timestamp))
            or value.get("intent_id")
            != _watchdog_self_hash(value, "intent_id")
            or path.name
            != f"{expected_sequence:012d}-{value.get('intent_id')}.json"
        ):
            raise ControlError("watchdog action intent is malformed")
        _validate_external_watchdog_identity(
            value["identity_before"],
            description="watchdog action intent",
        )
        result.append((value, path))
    return result


def _load_watchdog_action_receipts(
    state_dir: Path,
) -> list[tuple[dict[str, Any], Path]]:
    directory = _external_watchdog_mirror_root(state_dir) / "action_receipts"
    intents = _load_watchdog_action_intents(state_dir)
    result: list[tuple[dict[str, Any], Path]] = []
    previous: tuple[dict[str, Any], Path] | None = None
    expected_fields = {
        "schema_version",
        "protocol",
        "sequence",
        "predecessor",
        "intent",
        "action",
        "identity_before",
        "identity_after",
        "result_sha256",
        "outcome",
        "cluster_server_timestamp",
        "action_receipt_id",
    }
    for expected_sequence, path in enumerate(
        _watchdog_sequence_files(
            directory, description="watchdog action-receipt journal"
        ),
        start=1,
    ):
        value, _raw = _watchdog_mirror_read(
            path,
            description="watchdog action receipt",
            read_only=True,
        )
        timestamp = value.get("cluster_server_timestamp")
        intent_binding = value.get("intent")
        if (
            expected_sequence > len(intents)
            or set(value) != expected_fields
            or value.get("schema_version") != 1
            or value.get("protocol") != EXTERNAL_WATCHDOG_ACTION_PROTOCOL
            or value.get("sequence") != expected_sequence
            or value.get("action")
            not in {"repair-chain", "finalizer-reconcile"}
            or not isinstance(value.get("identity_before"), Mapping)
            or not isinstance(value.get("identity_after"), Mapping)
            or _SHA256_RE.fullmatch(str(value.get("result_sha256", "")))
            is None
            or value.get("outcome")
            not in {"completed", "recovered_interrupted"}
            or not isinstance(timestamp, (int, float))
            or isinstance(timestamp, bool)
            or not math.isfinite(float(timestamp))
            or not isinstance(intent_binding, Mapping)
            or set(intent_binding)
            != {"path", "sha256", "intent_id", "started_timestamp"}
            or value.get("action_receipt_id")
            != _watchdog_self_hash(value, "action_receipt_id")
            or path.name
            != (
                f"{expected_sequence:012d}-"
                f"{value.get('action_receipt_id')}.json"
            )
        ):
            raise ControlError("watchdog action receipt is malformed")
        _validate_external_watchdog_identity(
            value["identity_before"],
            description="watchdog action receipt before",
        )
        _validate_external_watchdog_identity(
            value["identity_after"],
            description="watchdog action receipt after",
        )
        intent, intent_path = intents[expected_sequence - 1]
        if (
            intent_binding
            != {
                "path": str(intent_path.resolve()),
                "sha256": sha256_file(intent_path),
                "intent_id": intent["intent_id"],
                "started_timestamp": intent["started_timestamp"],
            }
            or value["action"] != intent["action"]
            or value["identity_before"] != intent["identity_before"]
            or float(timestamp) < float(intent["started_timestamp"])
        ):
            raise ControlError(
                "watchdog action receipt does not bind its exact intent"
            )
        _watchdog_validate_predecessor(
            value.get("predecessor"),
            previous=previous,
            id_field="action_receipt_id",
            description="watchdog action journal",
        )
        if previous is not None and float(timestamp) <= float(
            previous[0]["cluster_server_timestamp"]
        ):
            raise ControlError(
                "watchdog action receipt timestamps are not monotonic"
            )
        result.append((value, path))
        previous = (value, path)
    return result


def begin_external_watchdog_action(
    state_dir: Path,
    *,
    action: str,
    now: float | None = None,
) -> dict[str, Any]:
    if action not in {"repair-chain", "finalizer-reconcile"}:
        raise ControlError("watchdog action is not authorized")
    timestamp = time.time() if now is None else float(now)
    control = load_control(state_dir, verify_files=True)
    identity = _external_watchdog_control_identity(control)
    with external_watchdog_mirror_lock(state_dir):
        _recover_watchdog_publication_temps_locked(state_dir)
        intents = _load_watchdog_action_intents(state_dir)
        receipts = _load_watchdog_action_receipts(state_dir)
        if len(intents) > len(receipts):
            pending = intents[-1][0]
            if len(intents) != len(receipts) + 1 or pending["action"] != action:
                raise ControlError(
                    "a different watchdog action intent remains incomplete"
                )
            return pending
        cycles = _load_watchdog_cycle_receipts(state_dir)
        consumed = (
            int(cycles[-1][0]["consumed_action_sequence"])
            if cycles
            else 0
        )
        if any(int(row["sequence"]) > consumed for row, _path in receipts):
            raise ControlError(
                "an unconsumed watchdog action receipt must be mirrored before "
                "another action can execute"
            )
        sequence = len(intents) + 1
        intent: dict[str, Any] = {
            "schema_version": 1,
            "protocol": EXTERNAL_WATCHDOG_ACTION_INTENT_PROTOCOL,
            "sequence": sequence,
            "action": action,
            "identity_before": identity,
            "started_timestamp": timestamp,
        }
        intent["intent_id"] = _watchdog_self_hash(intent, "intent_id")
        path = (
            _external_watchdog_mirror_root(state_dir)
            / "action_intents"
            / f"{sequence:012d}-{intent['intent_id']}.json"
        )
        _atomic_publish_readonly_json(path, intent)
        return intent


def complete_external_watchdog_action(
    state_dir: Path,
    *,
    intent: Mapping[str, Any],
    result: Mapping[str, Any],
    outcome: str = "completed",
    now: float | None = None,
) -> dict[str, Any]:
    timestamp = time.time() if now is None else float(now)
    if outcome not in {"completed", "recovered_interrupted"}:
        raise ControlError("watchdog action outcome is invalid")
    with external_watchdog_mirror_lock(state_dir):
        _recover_watchdog_publication_temps_locked(state_dir)
        intents = _load_watchdog_action_intents(state_dir)
        receipts = _load_watchdog_action_receipts(state_dir)
        sequence = int(intent.get("sequence", -1))
        if (
            sequence < 1
            or sequence > len(intents)
            or intents[sequence - 1][0] != dict(intent)
            or len(receipts) not in {sequence - 1, sequence}
        ):
            raise ControlError("watchdog action intent is not the journal tail")
        if len(receipts) == sequence:
            existing = receipts[-1][0]
            if existing["result_sha256"] != sha256_value(result):
                raise ControlError(
                    "watchdog action replay result differs from its receipt"
                )
            return {
                "action": existing["action"],
                "action_receipt_id": existing["action_receipt_id"],
                "path": str(receipts[-1][1].resolve()),
                "sha256": sha256_file(receipts[-1][1]),
                "outcome": existing["outcome"],
                "cluster_server_timestamp": existing[
                    "cluster_server_timestamp"
                ],
                "identity_before": existing["identity_before"],
                "identity_after": existing["identity_after"],
            }
        current = load_control(state_dir, verify_files=True)
        record: dict[str, Any] = {
            "schema_version": 1,
            "protocol": EXTERNAL_WATCHDOG_ACTION_PROTOCOL,
            "sequence": sequence,
            "predecessor": (
                _watchdog_predecessor(
                    receipts[-1][0],
                    id_field="action_receipt_id",
                    path=receipts[-1][1],
                )
                if receipts
                else None
            ),
            "intent": {
                "path": str(intents[sequence - 1][1].resolve()),
                "sha256": sha256_file(intents[sequence - 1][1]),
                "intent_id": intent["intent_id"],
                "started_timestamp": intent["started_timestamp"],
            },
            "action": intent["action"],
            "identity_before": intent["identity_before"],
            "identity_after": _external_watchdog_control_identity(current),
            "result_sha256": sha256_value(result),
            "outcome": outcome,
            "cluster_server_timestamp": timestamp,
        }
        record["action_receipt_id"] = _watchdog_self_hash(
            record, "action_receipt_id"
        )
        path = (
            _external_watchdog_mirror_root(state_dir)
            / "action_receipts"
            / f"{sequence:012d}-{record['action_receipt_id']}.json"
        )
        _atomic_publish_readonly_json(path, record)
        return {
            "action": record["action"],
            "action_receipt_id": record["action_receipt_id"],
            "path": str(path.resolve()),
            "sha256": sha256_file(path),
            "outcome": record["outcome"],
            "cluster_server_timestamp": record[
                "cluster_server_timestamp"
            ],
            "identity_before": record["identity_before"],
            "identity_after": record["identity_after"],
        }


def _recover_interrupted_watchdog_action_locked(
    state_dir: Path, *, timestamp: float
) -> dict[str, Any] | None:
    intents = _load_watchdog_action_intents(state_dir)
    receipts = _load_watchdog_action_receipts(state_dir)
    if len(intents) == len(receipts):
        return None
    if len(intents) != len(receipts) + 1:
        raise ControlError("watchdog action journal has multiple incomplete intents")
    intent = intents[-1][0]
    current = load_control(state_dir, verify_files=True)
    recovered_result = {
        "action": intent["action"],
        "recovered_after_interruption": True,
        "current_control_sha256": current["immutable_sha256"],
    }
    sequence = int(intent["sequence"])
    record: dict[str, Any] = {
        "schema_version": 1,
        "protocol": EXTERNAL_WATCHDOG_ACTION_PROTOCOL,
        "sequence": sequence,
        "predecessor": (
            _watchdog_predecessor(
                receipts[-1][0],
                id_field="action_receipt_id",
                path=receipts[-1][1],
            )
            if receipts
            else None
        ),
        "intent": {
            "path": str(intents[-1][1].resolve()),
            "sha256": sha256_file(intents[-1][1]),
            "intent_id": intent["intent_id"],
            "started_timestamp": intent["started_timestamp"],
        },
        "action": intent["action"],
        "identity_before": intent["identity_before"],
        "identity_after": _external_watchdog_control_identity(current),
        "result_sha256": sha256_value(recovered_result),
        "outcome": "recovered_interrupted",
        "cluster_server_timestamp": timestamp,
    }
    record["action_receipt_id"] = _watchdog_self_hash(
        record, "action_receipt_id"
    )
    path = (
        _external_watchdog_mirror_root(state_dir)
        / "action_receipts"
        / f"{sequence:012d}-{record['action_receipt_id']}.json"
    )
    _atomic_publish_readonly_json(path, record)
    return {
        "sequence": sequence,
        "action": record["action"],
        "action_receipt_id": record["action_receipt_id"],
        "path": str(path.resolve()),
        "sha256": sha256_file(path),
        "outcome": record["outcome"],
        "cluster_server_timestamp": record["cluster_server_timestamp"],
    }


def adopt_pending_external_watchdog_action(
    state_dir: Path,
    *,
    now: float | None = None,
) -> dict[str, Any] | None:
    """Return the exact unmirrored action, sealing an interrupted intent first."""

    timestamp = time.time() if now is None else float(now)
    with external_watchdog_mirror_lock(state_dir):
        _recover_watchdog_publication_temps_locked(state_dir)
        recovered = _recover_interrupted_watchdog_action_locked(
            state_dir, timestamp=timestamp
        )
        actions = _load_watchdog_action_receipts(state_dir)
        cycles = _load_watchdog_cycle_receipts(state_dir)
        consumed = (
            int(cycles[-1][0]["consumed_action_sequence"])
            if cycles
            else 0
        )
        pending = [
            (row, path)
            for row, path in actions
            if int(row["sequence"]) > consumed
        ]
        if not pending:
            return None
        if len(pending) != 1:
            raise ControlError(
                "multiple unconsumed watchdog actions are ambiguous"
            )
        row, path = pending[0]
        return {
            "sequence": row["sequence"],
            "action": row["action"],
            "action_receipt_id": row["action_receipt_id"],
            "path": str(path.resolve()),
            "sha256": sha256_file(path),
            "outcome": row["outcome"],
            "cluster_server_timestamp": row[
                "cluster_server_timestamp"
            ],
            "identity_before": row["identity_before"],
            "identity_after": row["identity_after"],
            "recovered_now": recovered is not None,
        }


def _load_watchdog_cycle_intents(
    state_dir: Path,
) -> list[tuple[dict[str, Any], Path]]:
    root = _external_watchdog_mirror_root(state_dir) / "cycle_intents"
    result: list[tuple[dict[str, Any], Path]] = []
    for expected_sequence, path in enumerate(
        _watchdog_sequence_files(
            root, description="watchdog cycle-intent journal"
        ),
        start=1,
    ):
        value, _raw = _watchdog_mirror_read(
            path,
            description="watchdog cycle intent",
            read_only=True,
        )
        expected_fields = {
            "schema_version",
            "protocol",
            "sequence",
            "predecessor",
            "identity",
            "status_observations",
            "consumed_status_sequence",
            "action_receipt",
            "consumed_action_sequence",
            "cluster_server_timestamp",
            "intent_id",
        }
        observations = value.get("status_observations")
        action_binding = value.get("action_receipt")
        predecessor = value.get("predecessor")
        server_timestamp = value.get("cluster_server_timestamp")
        if (
            set(value) != expected_fields
            or value.get("schema_version") != 1
            or value.get("protocol")
            != EXTERNAL_WATCHDOG_CYCLE_INTENT_PROTOCOL
            or value.get("sequence") != expected_sequence
            or value.get("intent_id")
            != _watchdog_self_hash(value, "intent_id")
            or path.name
            != f"{expected_sequence:012d}-{value.get('intent_id')}.json"
            or not isinstance(observations, list)
            or len(observations) != 2
            or not isinstance(value.get("consumed_status_sequence"), int)
            or isinstance(value.get("consumed_status_sequence"), bool)
            or not isinstance(value.get("consumed_action_sequence"), int)
            or isinstance(value.get("consumed_action_sequence"), bool)
            or int(value.get("consumed_action_sequence", -1)) < 0
            or (
                predecessor is not None
                and (
                    not isinstance(predecessor, Mapping)
                    or set(predecessor)
                    != {"sequence", "record_id", "sha256"}
                    or not isinstance(predecessor.get("sequence"), int)
                    or isinstance(predecessor.get("sequence"), bool)
                    or _SHA256_RE.fullmatch(
                        str(predecessor.get("record_id", ""))
                    )
                    is None
                    or _SHA256_RE.fullmatch(
                        str(predecessor.get("sha256", ""))
                    )
                    is None
                )
            )
            or (
                action_binding is not None
                and not isinstance(action_binding, Mapping)
            )
            or not isinstance(server_timestamp, (int, float))
            or isinstance(server_timestamp, bool)
            or not math.isfinite(float(server_timestamp))
        ):
            raise ControlError("watchdog cycle intent is malformed")
        _validate_external_watchdog_identity(
            value.get("identity"),
            description="watchdog cycle intent",
        )
        result.append((value, path))
    return result


def _validate_watchdog_cycle_semantics(
    value: Mapping[str, Any],
    *,
    statuses: Mapping[int, tuple[dict[str, Any], Path]],
    actions: Mapping[int, tuple[dict[str, Any], Path]],
    previous: tuple[dict[str, Any], Path] | None,
    description: str,
) -> None:
    """Re-prove the two-cut/action transaction from immutable source receipts."""

    _validate_external_watchdog_identity(
        value.get("identity"), description=description
    )
    observations = value.get("status_observations")
    if not isinstance(observations, list) or len(observations) != 2:
        raise ControlError(f"{description} does not bind exactly two status cuts")
    sequences = [
        binding.get("sequence")
        if isinstance(binding, Mapping)
        else None
        for binding in observations
    ]
    if (
        any(
            not isinstance(sequence, int) or isinstance(sequence, bool)
            for sequence in sequences
        )
        or int(sequences[0]) >= int(sequences[1])
        or int(sequences[0]) not in statuses
        or int(sequences[1]) not in statuses
    ):
        raise ControlError(
            f"{description} status cuts are repeated, reversed, or unavailable"
        )
    first = statuses[int(sequences[0])][0]
    second = statuses[int(sequences[1])][0]
    if (
        first["identity"] != second["identity"]
        or float(second["report_captured_timestamp"])
        - float(first["report_captured_timestamp"])
        < EXTERNAL_WATCHDOG_OBSERVATION_GAP_SECONDS
        or value.get("consumed_status_sequence") != second["sequence"]
    ):
        raise ControlError(
            f"{description} status identity, gap, or consumption is invalid"
        )
    prior_status = (
        int(previous[0]["consumed_status_sequence"])
        if previous is not None
        else 0
    )
    prior_action = (
        int(previous[0]["consumed_action_sequence"])
        if previous is not None
        else 0
    )
    if first["sequence"] <= prior_status or second["sequence"] <= prior_status:
        raise ControlError(f"{description} replays consumed status evidence")

    action_binding = value.get("action_receipt")
    consumed_action = value.get("consumed_action_sequence")
    action_timestamp: float | None = None
    if action_binding is None:
        if (
            consumed_action != prior_action
            or second["identity"] != value["identity"]
        ):
            raise ControlError(
                f"{description} advances action consumption or changes identity "
                "without a receipt"
            )
    else:
        action_sequence = (
            action_binding.get("sequence")
            if isinstance(action_binding, Mapping)
            else None
        )
        if (
            not isinstance(action_sequence, int)
            or isinstance(action_sequence, bool)
            or action_sequence != prior_action + 1
            or action_sequence not in actions
            or consumed_action != action_sequence
        ):
            raise ControlError(
                f"{description} action consumption is replayed or inconsistent"
            )
        action = actions[action_sequence][0]
        action_intent_timestamp = float(
            action["intent"]["started_timestamp"]
        )
        action_timestamp = float(action["cluster_server_timestamp"])
        recovered_interrupted = (
            action.get("outcome") == "recovered_interrupted"
        )
        identity_valid = (
            (
                recovered_interrupted
                and second["identity"] == action["identity_after"]
            )
            or (
                not recovered_interrupted
                and second["identity"] == action["identity_before"]
            )
        ) and action["identity_after"] == value["identity"]
        timing_valid = (
            (
                recovered_interrupted
                and action_timestamp
                >= float(second["cluster_server_timestamp"])
            )
            or (
                not recovered_interrupted
                and action_intent_timestamp
                >= float(second["cluster_server_timestamp"])
            )
        ) and action_timestamp >= action_intent_timestamp
        if not identity_valid or not timing_valid:
            raise ControlError(
                f"{description} action timing or control identity is invalid"
            )
    cycle_timestamp = value.get("cluster_server_timestamp")
    if (
        not isinstance(cycle_timestamp, (int, float))
        or isinstance(cycle_timestamp, bool)
        or not math.isfinite(float(cycle_timestamp))
        or float(cycle_timestamp)
        < float(second["cluster_server_timestamp"])
        or (
            action_timestamp is not None
            and float(cycle_timestamp) < action_timestamp
        )
        or (
            previous is not None
            and float(cycle_timestamp)
            <= float(previous[0]["cluster_server_timestamp"])
        )
    ):
        raise ControlError(
            f"{description} cluster timestamp is future-reversed or nonmonotonic"
        )
    _watchdog_validate_predecessor(
        value.get("predecessor"),
        previous=previous,
        id_field="receipt_id",
        description=description,
    )


def _load_watchdog_cycle_receipts(
    state_dir: Path,
) -> list[tuple[dict[str, Any], Path]]:
    directory = _external_watchdog_mirror_root(state_dir) / "cycle_receipts"
    intents = _load_watchdog_cycle_intents(state_dir)
    statuses = {
        row["sequence"]: (row, path)
        for row, path in _load_watchdog_status_observations(state_dir)
    }
    actions = {
        row["sequence"]: (row, path)
        for row, path in _load_watchdog_action_receipts(state_dir)
    }
    result: list[tuple[dict[str, Any], Path]] = []
    previous: tuple[dict[str, Any], Path] | None = None
    expected_fields = {
        "schema_version",
        "protocol",
        "sequence",
        "predecessor",
        "intent",
        "identity",
        "status_observations",
        "consumed_status_sequence",
        "action_receipt",
        "consumed_action_sequence",
        "cluster_server_timestamp",
        "receipt_id",
    }
    for expected_sequence, path in enumerate(
        _watchdog_sequence_files(
            directory, description="watchdog cycle-receipt journal"
        ),
        start=1,
    ):
        value, _raw = _watchdog_mirror_read(
            path,
            description="watchdog cycle receipt",
            read_only=True,
        )
        intent_binding = value.get("intent")
        observations = value.get("status_observations")
        if (
            expected_sequence > len(intents)
            or set(value) != expected_fields
            or value.get("schema_version") != 1
            or value.get("protocol") != EXTERNAL_WATCHDOG_CYCLE_PROTOCOL
            or value.get("sequence") != expected_sequence
            or not isinstance(intent_binding, Mapping)
            or set(intent_binding)
            != {"path", "sha256", "intent_id"}
            or not isinstance(observations, list)
            or len(observations) != 2
            or value.get("receipt_id")
            != _watchdog_self_hash(value, "receipt_id")
            or path.name
            != f"{expected_sequence:012d}-{value.get('receipt_id')}.json"
        ):
            raise ControlError("watchdog cycle receipt is malformed")
        intent, intent_path = intents[expected_sequence - 1]
        core_fields = {
            "sequence",
            "predecessor",
            "identity",
            "status_observations",
            "consumed_status_sequence",
            "action_receipt",
            "consumed_action_sequence",
            "cluster_server_timestamp",
        }
        if (
            intent_binding
            != {
                "path": str(intent_path.resolve()),
                "sha256": sha256_file(intent_path),
                "intent_id": intent["intent_id"],
            }
            or any(value[field] != intent[field] for field in core_fields)
        ):
            raise ControlError(
                "watchdog cycle receipt differs from its marker-first intent"
            )
        for binding in observations:
            if (
                not isinstance(binding, Mapping)
                or set(binding)
                != {
                    "sequence",
                    "path",
                    "sha256",
                    "observation_id",
                    "report_sha256",
                    "report_captured_timestamp",
                }
                or binding.get("sequence") not in statuses
            ):
                raise ControlError(
                    "watchdog cycle status binding is malformed"
                )
            status, status_path = statuses[int(binding["sequence"])]
            if binding != {
                "sequence": status["sequence"],
                "path": str(status_path.resolve()),
                "sha256": sha256_file(status_path),
                "observation_id": status["observation_id"],
                "report_sha256": status["report_sha256"],
                "report_captured_timestamp": status[
                    "report_captured_timestamp"
                ],
            }:
                raise ControlError(
                    "watchdog cycle status binding drifted"
                )
        action_binding = value.get("action_receipt")
        if action_binding is not None:
            if (
                not isinstance(action_binding, Mapping)
                or set(action_binding)
                != {
                    "sequence",
                    "path",
                    "sha256",
                    "action",
                    "action_receipt_id",
                    "cluster_server_timestamp",
                    "identity_before",
                    "identity_after",
                    "outcome",
                }
                or action_binding.get("sequence") not in actions
            ):
                raise ControlError(
                    "watchdog cycle action binding is malformed"
                )
            action, action_path = actions[int(action_binding["sequence"])]
            if action_binding != {
                "sequence": action["sequence"],
                "path": str(action_path.resolve()),
                "sha256": sha256_file(action_path),
                "action": action["action"],
                "action_receipt_id": action["action_receipt_id"],
                "cluster_server_timestamp": action[
                    "cluster_server_timestamp"
                ],
                "identity_before": action["identity_before"],
                "identity_after": action["identity_after"],
                "outcome": action["outcome"],
            }:
                raise ControlError(
                    "watchdog cycle action binding drifted"
                )
        _validate_watchdog_cycle_semantics(
            value,
            statuses=statuses,
            actions=actions,
            previous=previous,
            description="watchdog cycle journal",
        )
        result.append((value, path))
        previous = (value, path)
    return result


def _watchdog_status_binding(
    record: Mapping[str, Any], path: Path
) -> dict[str, Any]:
    return {
        "sequence": record["sequence"],
        "path": str(path.resolve()),
        "sha256": sha256_file(path),
        "observation_id": record["observation_id"],
        "report_sha256": record["report_sha256"],
        "report_captured_timestamp": record[
            "report_captured_timestamp"
        ],
    }


def _watchdog_action_binding(
    record: Mapping[str, Any], path: Path
) -> dict[str, Any]:
    return {
        "sequence": record["sequence"],
        "path": str(path.resolve()),
        "sha256": sha256_file(path),
        "action": record["action"],
        "action_receipt_id": record["action_receipt_id"],
        "cluster_server_timestamp": record["cluster_server_timestamp"],
        "identity_before": record["identity_before"],
        "identity_after": record["identity_after"],
        "outcome": record["outcome"],
    }


def _watchdog_latest_pointer_value(
    *, receipt: Mapping[str, Any], receipt_path: Path
) -> dict[str, Any]:
    pointer: dict[str, Any] = {
        "schema_version": 1,
        "protocol": EXTERNAL_WATCHDOG_LATEST_PROTOCOL,
        "sequence": receipt["sequence"],
        "receipt_path": str(receipt_path.resolve()),
        "receipt_sha256": sha256_file(receipt_path),
        "receipt_id": receipt["receipt_id"],
        "cluster_server_timestamp": receipt["cluster_server_timestamp"],
    }
    pointer["pointer_id"] = _watchdog_self_hash(pointer, "pointer_id")
    return pointer


def _publish_watchdog_latest_pointer(
    state_dir: Path,
    *,
    receipt: Mapping[str, Any],
    receipt_path: Path,
) -> dict[str, Any]:
    pointer = _watchdog_latest_pointer_value(
        receipt=receipt, receipt_path=receipt_path
    )
    _atomic_write_json(
        _external_watchdog_mirror_root(state_dir) / "LATEST.json",
        pointer,
    )
    return pointer


def _complete_watchdog_cycle_intent(
    state_dir: Path,
    *,
    intent: Mapping[str, Any],
    intent_path: Path,
) -> tuple[dict[str, Any], Path]:
    receipt: dict[str, Any] = {
        "schema_version": 1,
        "protocol": EXTERNAL_WATCHDOG_CYCLE_PROTOCOL,
        "sequence": intent["sequence"],
        "predecessor": intent["predecessor"],
        "intent": {
            "path": str(intent_path.resolve()),
            "sha256": sha256_file(intent_path),
            "intent_id": intent["intent_id"],
        },
        "identity": intent["identity"],
        "status_observations": intent["status_observations"],
        "consumed_status_sequence": intent["consumed_status_sequence"],
        "action_receipt": intent["action_receipt"],
        "consumed_action_sequence": intent["consumed_action_sequence"],
        "cluster_server_timestamp": intent["cluster_server_timestamp"],
    }
    receipt["receipt_id"] = _watchdog_self_hash(receipt, "receipt_id")
    path = (
        _external_watchdog_mirror_root(state_dir)
        / "cycle_receipts"
        / f"{int(receipt['sequence']):012d}-{receipt['receipt_id']}.json"
    )
    _atomic_publish_readonly_json(path, receipt)
    return receipt, path


def publish_external_watchdog_cycle(
    state_dir: Path,
    *,
    now: float | None = None,
) -> dict[str, Any]:
    """Consume two server-recorded status cuts and advance the cluster mirror."""

    timestamp = time.time() if now is None else float(now)
    if not math.isfinite(timestamp):
        raise ControlError("watchdog cycle server timestamp is invalid")
    with external_watchdog_mirror_lock(state_dir):
        _recover_watchdog_publication_temps_locked(state_dir)
        # A killed action wrapper leaves a marker-first intent.  Seal the attempt
        # before selecting a cycle so action history can never disappear.
        _recover_interrupted_watchdog_action_locked(
            state_dir, timestamp=timestamp
        )
        actions = _load_watchdog_action_receipts(state_dir)

        cycle_intents = _load_watchdog_cycle_intents(state_dir)
        cycles = _load_watchdog_cycle_receipts(state_dir)
        if len(cycle_intents) == len(cycles) + 1:
            _validate_watchdog_cycle_semantics(
                cycle_intents[-1][0],
                statuses={
                    row["sequence"]: (row, path)
                    for row, path in _load_watchdog_status_observations(
                        state_dir
                    )
                },
                actions={
                    row["sequence"]: (row, path)
                    for row, path in _load_watchdog_action_receipts(
                        state_dir
                    )
                },
                previous=cycles[-1] if cycles else None,
                description="watchdog recovered cycle intent",
            )
            receipt, receipt_path = _complete_watchdog_cycle_intent(
                state_dir,
                intent=cycle_intents[-1][0],
                intent_path=cycle_intents[-1][1],
            )
            pointer = _publish_watchdog_latest_pointer(
                state_dir, receipt=receipt, receipt_path=receipt_path
            )
            return {
                "published": True,
                "recovered": True,
                "receipt": receipt,
                "pointer": pointer,
            }
        if len(cycle_intents) != len(cycles):
            raise ControlError("watchdog cycle journal is inconsistent")
        if cycles:
            expected_pointer = _watchdog_latest_pointer_value(
                receipt=cycles[-1][0], receipt_path=cycles[-1][1]
            )
            pointer_path = (
                _external_watchdog_mirror_root(state_dir) / "LATEST.json"
            )
            pointer_current = False
            if os.path.lexists(pointer_path):
                try:
                    observed_pointer, _raw = _watchdog_mirror_read(
                        pointer_path,
                        description="watchdog mirror latest pointer",
                        read_only=False,
                    )
                    pointer_current = observed_pointer == expected_pointer
                except (OSError, ControlError):
                    pointer_current = False
            if not pointer_current:
                pointer = _publish_watchdog_latest_pointer(
                    state_dir,
                    receipt=cycles[-1][0],
                    receipt_path=cycles[-1][1],
                )
                return {
                    "published": True,
                    "recovered": True,
                    "receipt": cycles[-1][0],
                    "pointer": pointer,
                }

        prior_status_sequence = (
            int(cycles[-1][0]["consumed_status_sequence"])
            if cycles
            else 0
        )
        prior_action_sequence = (
            int(cycles[-1][0]["consumed_action_sequence"])
            if cycles
            else 0
        )
        statuses = [
            row
            for row in _load_watchdog_status_observations(state_dir)
            if int(row[0]["sequence"]) > prior_status_sequence
        ]
        pending_actions = [
            row
            for row in actions
            if int(row[0]["sequence"]) > prior_action_sequence
        ]
        selected_action: tuple[dict[str, Any], Path] | None = None
        if pending_actions:
            selected_action = pending_actions[0]
            before_action = [
                row
                for row in statuses
                if float(row[0]["cluster_server_timestamp"])
                <= float(selected_action[0]["cluster_server_timestamp"])
            ]
            if len(before_action) < 2:
                raise ControlError(
                    "watchdog action lacks two preceding unconsumed status cuts"
                )
            selected_statuses = before_action[-2:]
        else:
            if len(statuses) < 2:
                raise ControlError(
                    "watchdog observe requires two unconsumed status receipts"
                )
            selected_statuses = statuses[-2:]
        first, second = selected_statuses
        gap = float(second[0]["report_captured_timestamp"]) - float(
            first[0]["report_captured_timestamp"]
        )
        current = load_control(state_dir, verify_files=True)
        identity = _external_watchdog_control_identity(current)
        if (
            gap < EXTERNAL_WATCHDOG_OBSERVATION_GAP_SECONDS
            or first[0]["identity"] != second[0]["identity"]
            or (
                selected_action is None
                and second[0]["identity"] != identity
            )
        ):
            raise ControlError(
                "watchdog observe status cuts are too close or changed identity"
            )
        if selected_action is not None and (
            selected_action[0]["identity_after"] != identity
            or (
                (
                    selected_action[0]["outcome"]
                    == "recovered_interrupted"
                    and selected_action[0]["identity_after"]
                    != second[0]["identity"]
                )
                or (
                    selected_action[0]["outcome"] != "recovered_interrupted"
                    and selected_action[0]["identity_before"]
                    != second[0]["identity"]
                )
            )
            or float(selected_action[0]["cluster_server_timestamp"])
            < float(second[0]["report_captured_timestamp"])
        ):
            raise ControlError(
                "watchdog action is not after cut two or changed control identity"
            )
        sequence = len(cycles) + 1
        cycle_intent: dict[str, Any] = {
            "schema_version": 1,
            "protocol": EXTERNAL_WATCHDOG_CYCLE_INTENT_PROTOCOL,
            "sequence": sequence,
            "predecessor": (
                _watchdog_predecessor(
                    cycles[-1][0],
                    id_field="receipt_id",
                    path=cycles[-1][1],
                )
                if cycles
                else None
            ),
            "identity": identity,
            "status_observations": [
                _watchdog_status_binding(*first),
                _watchdog_status_binding(*second),
            ],
            "consumed_status_sequence": int(second[0]["sequence"]),
            "action_receipt": (
                _watchdog_action_binding(*selected_action)
                if selected_action is not None
                else None
            ),
            "consumed_action_sequence": (
                int(selected_action[0]["sequence"])
                if selected_action is not None
                else prior_action_sequence
            ),
            "cluster_server_timestamp": timestamp,
        }
        cycle_intent["intent_id"] = _watchdog_self_hash(
            cycle_intent, "intent_id"
        )
        _validate_watchdog_cycle_semantics(
            cycle_intent,
            statuses={
                row["sequence"]: (row, path)
                for row, path in _load_watchdog_status_observations(
                    state_dir
                )
            },
            actions={
                row["sequence"]: (row, path)
                for row, path in _load_watchdog_action_receipts(state_dir)
            },
            previous=cycles[-1] if cycles else None,
            description="watchdog cycle publication",
        )
        intent_path = (
            _external_watchdog_mirror_root(state_dir)
            / "cycle_intents"
            / f"{sequence:012d}-{cycle_intent['intent_id']}.json"
        )
        _atomic_publish_readonly_json(intent_path, cycle_intent)
        receipt, receipt_path = _complete_watchdog_cycle_intent(
            state_dir, intent=cycle_intent, intent_path=intent_path
        )
        pointer = _publish_watchdog_latest_pointer(
            state_dir, receipt=receipt, receipt_path=receipt_path
        )
        return {
            "published": True,
            "recovered": False,
            "receipt": receipt,
            "pointer": pointer,
        }


def _watchdog_mirror_required(control: Mapping[str, Any]) -> bool:
    readiness = control.get("readiness")
    gate = (
        readiness.get("external_watchdog")
        if isinstance(readiness, Mapping)
        else None
    )
    return bool(isinstance(gate, Mapping) and gate.get("passed") is True)


def external_watchdog_mirror_status(
    state_dir: Path,
    *,
    control: Mapping[str, Any] | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Validate the complete mirror chain and project its launch-health state."""

    timestamp = time.time() if now is None else float(now)
    current = dict(control) if control is not None else load_control(state_dir)
    required = _watchdog_mirror_required(current)
    base: dict[str, Any] = {
        "required": required,
        "healthy": not required,
        "status": "not_required",
        "receipt_id": None,
        "sequence": None,
        "age_seconds": None,
        "cluster_server_timestamp": None,
        "latest_pointer_path": str(
            (_external_watchdog_mirror_root(state_dir) / "LATEST.json").resolve()
        ),
        "error": None,
    }
    if not math.isfinite(timestamp):
        base.update(
            healthy=False if required else True,
            status="invalid" if required else "not_required_invalid",
            error="watchdog mirror validation time is non-finite",
        )
        return base
    pointer_path = _external_watchdog_mirror_root(state_dir) / "LATEST.json"
    if not os.path.lexists(pointer_path):
        if required:
            base.update(
                healthy=False,
                status="missing",
                error="cluster watchdog mirror LATEST.json is missing",
            )
        return base
    try:
        with external_watchdog_mirror_read_lock(state_dir):
            cycles = _load_watchdog_cycle_receipts(state_dir)
            intents = _load_watchdog_cycle_intents(state_dir)
            if len(intents) != len(cycles):
                raise ControlError(
                    "watchdog mirror has an incomplete marker-first cycle"
                )
            if not cycles:
                raise ControlError("watchdog mirror has no cycle receipts")
            pointer, _raw = _watchdog_mirror_read(
                pointer_path,
                description="watchdog mirror latest pointer",
                read_only=False,
            )
            expected_pointer_fields = {
                "schema_version",
                "protocol",
                "sequence",
                "receipt_path",
                "receipt_sha256",
                "receipt_id",
                "cluster_server_timestamp",
                "pointer_id",
            }
            latest, latest_path = cycles[-1]
            expected_pointer = _watchdog_latest_pointer_value(
                receipt=latest, receipt_path=latest_path
            )
            if set(pointer) != expected_pointer_fields or pointer != expected_pointer:
                raise ControlError(
                    "watchdog mirror pointer conflicts with the journal tail"
                )
            identity = _external_watchdog_control_identity(current)
            if latest["identity"] != identity:
                raise ControlError(
                    "watchdog mirror release/control/rollout/finalization identity drifted"
                )
            observed = float(latest["cluster_server_timestamp"])
            age = timestamp - observed
            if age < 0:
                raise ControlError(
                    "watchdog mirror cluster timestamp is in the future"
                )
            if age > EXTERNAL_WATCHDOG_MIRROR_STALE_SECONDS:
                base.update(
                    healthy=False,
                    status="stale",
                    receipt_id=latest["receipt_id"],
                    sequence=latest["sequence"],
                    age_seconds=age,
                    cluster_server_timestamp=observed,
                    error="cluster watchdog mirror is older than 600 seconds",
                )
                return base
            base.update(
                healthy=True,
                status="fresh",
                receipt_id=latest["receipt_id"],
                sequence=latest["sequence"],
                age_seconds=age,
                cluster_server_timestamp=observed,
                error=None,
            )
            return base
    except (OSError, ControlError, ImmutablePinError) as exc:
        base.update(
            healthy=False if required else True,
            status="invalid" if required else "not_required_invalid",
            error=str(exc),
        )
        return base


def require_fresh_external_watchdog_mirror(
    state_dir: Path,
    *,
    control: Mapping[str, Any],
    now: float,
) -> dict[str, Any]:
    status = external_watchdog_mirror_status(
        state_dir, control=control, now=now
    )
    if status.get("healthy") is not True or status.get("status") != "fresh":
        raise ReadinessError(
            "production resume requires a current cluster-mirrored external "
            f"watchdog heartbeat: {status.get('status')}: {status.get('error')}"
        )
    return status


def live_status(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    now: float | None = None,
) -> dict[str, Any]:
    """Return scheduler-authoritative live status without mutating cached state."""
    timestamp = snapshot.captured_at if now is None else float(now)
    control = load_control(state_dir)
    jobs_by_id = {job.job_id: job for job in snapshot.jobs}
    roles: dict[str, Any] = {}
    for role in ROLE_NAMES:
        state = control["controllers"][role]
        active = state.get("active") if isinstance(state.get("active"), dict) else {}
        successor = (
            state.get("successor") if isinstance(state.get("successor"), dict) else {}
        )
        active_id_job = jobs_by_id.get(str(active.get("job_id", "")))
        successor_id_job = jobs_by_id.get(str(successor.get("job_id", "")))
        active_job = _exact_live_controller_job(snapshot, active)
        successor_job = _exact_live_controller_job(snapshot, successor)
        age = controller_liveness_age(state, timestamp)
        roles[role] = {
            "recorded_active_job_id": active.get("job_id"),
            "live_active": active_job is not None,
            "active_identity_mismatch": bool(
                active_id_job is not None
                and active_id_job.active
                and active_job is None
            ),
            "scheduler_state": (
                active_id_job.state if active_id_job is not None else None
            ),
            "recorded_successor_job_id": successor.get("job_id"),
            "successor_live": successor_job is not None,
            "successor_identity_mismatch": bool(
                successor_id_job is not None
                and successor_id_job.active
                and successor_job is None
            ),
            "successor_scheduler_state": (
                successor_id_job.state
                if successor_id_job is not None
                else None
            ),
            "heartbeat": state.get("heartbeat"),
            "heartbeat_age_seconds": age,
            "heartbeat_stale": age is None or age > STALE_HEARTBEAT_SECONDS,
        }
    active_cell_jobs = [
        job for job in snapshot.jobs if job.active and _cell_job(job.job_name)
    ]
    ledger_path = state_dir / "ledger.json"
    cached: dict[str, Any] = {
        "available": False,
        "healthy": False,
        "status": "missing",
        "path": str(ledger_path),
        "trusted_live_state": False,
    }
    if os.path.lexists(ledger_path):
        try:
            raw, ledger = _production_dispatcher_ledger_preimage(
                state_dir,
                description="live-status dispatcher ledger",
            )
            updated_at = float(ledger["updated_at"])
            age = max(0.0, float(timestamp) - updated_at)
            stale = (
                updated_at > float(timestamp) + 1.0
                or age
                > protected_capacity.MAX_DISPATCHER_LEDGER_AGE_SECONDS
            )
            cached = {
                "available": True,
                "healthy": not stale,
                "status": "stale" if stale else "fresh",
                "path": str(ledger_path),
                "sha256": hashlib.sha256(raw).hexdigest(),
                "updated_at": updated_at,
                "age_seconds": age,
                "poll_number": ledger["poll_number"],
                "cached_job_records": len(ledger["jobs"]),
                "cached_cell_records": len(ledger["cells"]),
                "cached_state_only": True,
                "trusted_live_state": False,
            }
        except (OSError, SchedulerAmbiguity) as exc:
            cached = {
                "available": False,
                "healthy": False,
                "status": "invalid",
                "path": str(ledger_path),
                "error": str(exc),
                "trusted_live_state": False,
            }
    active_alerts = [
        alert for alert in control["alerts"] if alert.get("resolved_at") is None
    ]
    active_critical_keys = sorted(
        set(_active_critical_alerts(control))
        | set(_active_critical_alerts_from_journal(state_dir))
    )
    controller_identity_mismatch = any(
        role["active_identity_mismatch"]
        or role["successor_identity_mismatch"]
        for role in roles.values()
    )
    controllers_healthy = (
        (
            control["desired_state"] == "paused"
            or all(
                not role["heartbeat_stale"] and role["live_active"]
                for role in roles.values()
            )
        )
        and not controller_identity_mismatch
    )
    finalization_status = _finalizer_live_status(
        control, snapshot, timestamp=timestamp
    )
    watchdog_mirror = external_watchdog_mirror_status(
        state_dir, control=control, now=timestamp
    )
    healthy = (
        snapshot.squeue_ok
        and snapshot.sacct_ok
        and not snapshot.errors
        and controllers_healthy
        and not active_critical_keys
        and finalization_status["chain_healthy"]
        and (
            control["desired_state"] != "running"
            or cached["healthy"] is True
        )
        and (
            watchdog_mirror["required"] is not True
            or watchdog_mirror["healthy"] is True
        )
    )
    configured_ceiling = int(control["admission"]["current_ceiling"])
    stage_entries = [
        float(row["timestamp"])
        for row in control["admission_ramp"].get("promotions", [])
        if isinstance(row, dict)
        and row.get("to_ceiling") == configured_ceiling
        and isinstance(row.get("timestamp"), (int, float))
    ]
    if stage_entries:
        admission_stage_started_timestamp: float | None = max(stage_entries)
    else:
        resume = control.get("resume_intent")
        value = (
            resume.get("completed_timestamp")
            if isinstance(resume, dict)
            else None
        )
        admission_stage_started_timestamp = (
            float(value) if isinstance(value, (int, float)) else None
        )
    return {
        "schema_version": 1,
        "captured_at": utc_timestamp(timestamp),
        "captured_timestamp": timestamp,
        "release_id": control["immutable"]["release_id"],
        "git_commit": control["immutable"]["git_commit"],
        "immutable_sha256": control["immutable_sha256"],
        "desired_state": control["desired_state"],
        "drain_requested": control["drain_requested"],
        "rollout_generation": control["rollout_generation"],
        "admission": copy.deepcopy(control["admission"]),
        "admission_safety_hold": copy.deepcopy(
            control["admission_safety_hold"]
        ),
        "safety_hold_drain_intent": copy.deepcopy(
            control.get("safety_hold_drain_intent")
        ),
        "effective_admission_ceiling": (
            0
            if control["desired_state"] != "running"
            or control["admission_safety_hold"]["active"]
            or active_critical_keys
            or control["finalization"]["state"] != "idle"
            else int(control["admission"]["current_ceiling"])
        ),
        "admission_stage_started_timestamp": admission_stage_started_timestamp,
        "admission_ramp": copy.deepcopy(control["admission_ramp"]),
        "capacity": copy.deepcopy(control["capacity"]),
        "effective_capacity_authority": (
            effective_protected_capacity_binding(
                control, verify_files=True
            )
        ),
        "healthy": healthy,
        "scheduler": {
            "squeue_ok": snapshot.squeue_ok,
            "sacct_ok": snapshot.sacct_ok,
            "errors": list(snapshot.errors),
            "total_jobs": len(snapshot.jobs),
            # This is the only field named active_cell_tasks/jobs: it comes directly
            # from scheduler truth, never the potentially stale dispatcher ledger.
            "active_cell_tasks": len(active_cell_jobs),
            "active_cell_job_ids": [job.job_id for job in active_cell_jobs],
        },
        "controllers": roles,
        "monitoring": {
            "owner_role": control["monitoring"]["owner_role"],
            "cadences": {
                cadence: {
                    **copy.deepcopy(row),
                    "overdue": (
                        control["desired_state"] == "running"
                        and row["active_attempt"] is None
                        and float(row["next_due_timestamp"]) <= timestamp
                    ),
                }
                for cadence, row in control["monitoring"]["cadences"].items()
            },
        },
        "external_watchdog_mirror": watchdog_mirror,
        "finalization": finalization_status,
        "dispatcher_cache": cached,
        "readiness": copy.deepcopy(control["readiness"]),
        "open_throughput_epoch": (
            copy.deepcopy(control["throughput_epochs"][-1])
            if control["throughput_epochs"]
            and control["throughput_epochs"][-1].get("closed_at") is None
            else None
        ),
        "active_alerts": copy.deepcopy(active_alerts),
    }


def _role_has_live_chain(
    control: Mapping[str, Any], role: str, snapshot: SchedulerSnapshot
) -> bool:
    state = control["controllers"][role]
    for field in ("active", "successor", "submission_intent"):
        record = state.get(field)
        if isinstance(record, dict) and _exact_live_controller_job(
            snapshot, record
        ) is not None:
            return True
        if isinstance(record, dict) and record.get("state") == "submitting":
            matches = _find_intent_jobs(snapshot, str(record.get("job_token", "")))
            active = [job for job in matches if job.active]
            if len(active) == 1 and (
                not record.get("job_id")
                or active[0].job_id == str(record["job_id"])
            ):
                return True
    return False


def trigger_stale_takeover(
    state_dir: Path,
    *,
    role: str,
    snapshot: SchedulerSnapshot,
    cancel_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    stale_seconds: float = STALE_HEARTBEAT_SECONDS,
    now: float | None = None,
) -> dict[str, Any]:
    """Fence a >10-minute stale exact job and release or create its one successor."""
    _validate_role(role)
    timestamp = snapshot.captured_at if now is None else float(now)
    control = load_control(state_dir)
    if control["desired_state"] != "running":
        return {"role": role, "action": "disabled_while_paused"}
    state = control["controllers"][role]
    age = controller_liveness_age(state, timestamp)
    if age is not None and age <= stale_seconds:
        return {"role": role, "action": "heartbeat_fresh", "age_seconds": age}
    active = state.get("active")
    cancelled: str | None = None
    if isinstance(active, dict) and active.get("job_id"):
        active_id = str(active["job_id"])
        scheduler_job = next(
            (job for job in snapshot.jobs if job.job_id == active_id and job.active),
            None,
        )
        if scheduler_job is not None:
            if scheduler_job.token != active.get("job_token"):
                raise SchedulerAmbiguity(
                    f"refusing stale takeover of {active_id}: exact scheduler token mismatch"
                )
            invoke = cancel_runner or _run_subprocess
            proc = invoke(["scancel", active_id])
            if proc.returncode != 0:
                raise ControlError(
                    f"failed to fence stale exact controller {active_id}: "
                    f"{proc.stderr.strip()[:500]}"
                )
            cancelled = active_id
            with control_lock(state_dir):
                updated = load_control(state_dir)
                append_transition(
                    state_dir,
                    updated,
                    event="stale_controller_fenced",
                    details={"role": role, "job_id": active_id, "age_seconds": age},
                    now=timestamp,
                )
                _save_control(state_dir, updated, now=timestamp)

    # Exclude the just-fenced allocation from the scheduler view.  A recorded pending
    # successor is already the takeover and its afterany dependency will now release.
    remaining = SchedulerSnapshot(
        tuple(job for job in snapshot.jobs if job.job_id != cancelled),
        snapshot.captured_at,
        snapshot.squeue_ok,
        snapshot.sacct_ok,
        snapshot.errors,
    )
    refreshed = load_control(state_dir)
    successor = refreshed["controllers"][role].get("successor")
    if isinstance(successor, dict) and _exact_live_controller_job(
        remaining, successor
    ) is not None:
        return {
            "role": role,
            "action": "released_recorded_successor",
            "cancelled_job_id": cancelled,
            "successor_job_id": successor.get("job_id"),
        }
    result = submit_controller_intent(
        state_dir,
        role=role,
        target="active",
        dependency_job_id=None,
        scheduler=remaining,
        submit_runner=submit_runner,
        now=timestamp,
    )
    return {
        "role": role,
        "action": "submitted_takeover",
        "cancelled_job_id": cancelled,
        "successor_job_id": result["job_id"],
    }


def repair_chains(
    state_dir: Path,
    *,
    snapshot: SchedulerSnapshot,
    submit_runner: (
        Callable[[Sequence[str]], subprocess.CompletedProcess[str]] | None
    ) = None,
    only_roles: Sequence[str] = ROLE_NAMES,
    now: float | None = None,
) -> dict[str, Any]:
    """Idempotently ensure each requested role has one uniquely mapped live chain."""
    for role in only_roles:
        _validate_role(role)
    control = load_control(state_dir, verify_files=True)
    if control["desired_state"] != "running":
        return {"desired_state": "paused", "submitted": [], "existing": []}
    validate_readiness(control, state_dir=state_dir, verify_files=True)
    provisional = build_reconciliation_report(
        control, snapshot, all_jobs=True, no_admit=True
    )
    if provisional["errors"]:
        raise SchedulerAmbiguity(
            "repair-chain refused ambiguous scheduler state: "
            + "; ".join(provisional["errors"])
        )
    submitted: list[dict[str, Any]] = []
    existing: list[str] = []
    for role in only_roles:
        # Reload between roles because each submission commits a new durable identity.
        current = load_control(state_dir)
        if _role_has_live_chain(current, role, snapshot):
            existing.append(role)
            continue
        record = submit_controller_intent(
            state_dir,
            role=role,
            target="active",
            dependency_job_id=None,
            scheduler=snapshot,
            submit_runner=submit_runner,
            now=now,
        )
        submitted.append({"role": role, "job_id": record["job_id"]})
    return {"desired_state": "running", "submitted": submitted, "existing": existing}


def claim_controller(
    state_dir: Path,
    *,
    role: str,
    generation: int,
    intent_token: str,
    job_id: str,
    active_scheduler_job_ids: set[str],
    now: float | None = None,
) -> dict[str, Any]:
    """Fence a starting Slurm job to its exact durable generation and intent."""
    _validate_role(role)
    if not job_id.isdigit():
        raise ControllerFenced(f"invalid SLURM_JOB_ID {job_id!r}")
    timestamp = time.time() if now is None else float(now)
    expected_token = job_token(role, generation, intent_token)
    with control_lock(state_dir):
        control = load_control(state_dir)
        if control["desired_state"] not in {"resuming", "running"}:
            raise ControllerFenced(
                "desired_state=paused fences all starting controllers"
            )
        if control["desired_state"] == "resuming":
            resume_intent = control.get("resume_intent")
            if (
                not isinstance(resume_intent, dict)
                or resume_intent.get("state") != "submitting_controllers"
                or int(resume_intent.get("rollout_generation", -1))
                != int(control["rollout_generation"])
            ):
                raise ControllerFenced(
                    "controller is not part of the active resume transaction"
                )
        state = control["controllers"][role]
        claimed = _resolve_fenced_role_claim(
            state,
            role=role,
            expected_token=expected_token,
            generation=generation,
            intent_token=intent_token,
            job_id=job_id,
            active_scheduler_job_ids=active_scheduler_job_ids,
            context="production",
            now=timestamp,
        )
        state["active"] = claimed
        if isinstance(state.get("successor"), dict) and (
            state["successor"].get("intent_token") == intent_token
        ):
            state["successor"] = None
        state["heartbeat"] = {
            "job_id": job_id,
            "generation": generation,
            "intent_token": intent_token,
            "at": utc_timestamp(timestamp),
            "timestamp": timestamp,
            "host": socket.gethostname(),
            "pid": os.getpid(),
        }
        append_transition(
            state_dir,
            control,
            event="controller_claimed",
            details={"role": role, "generation": generation, "job_id": job_id},
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)
        return claimed


def heartbeat_controller(
    state_dir: Path,
    *,
    role: str,
    generation: int,
    intent_token: str,
    job_id: str,
    now: float | None = None,
) -> dict[str, Any]:
    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        state = control["controllers"][role]
        active = state.get("active")
        identity = (job_id, generation, intent_token)
        recorded = (
            (
                str(active.get("job_id", "")),
                int(active.get("generation", -1)),
                str(active.get("intent_token", "")),
            )
            if isinstance(active, dict)
            else None
        )
        if recorded != identity:
            raise ControllerFenced(
                f"heartbeat identity {identity!r} no longer owns {role}; recorded={recorded!r}"
            )
        heartbeat = {
            "job_id": job_id,
            "generation": generation,
            "intent_token": intent_token,
            "at": utc_timestamp(timestamp),
            "timestamp": timestamp,
            "host": socket.gethostname(),
            "pid": os.getpid(),
        }
        state["heartbeat"] = heartbeat
        _save_control(state_dir, control, now=timestamp)
        return heartbeat


def record_controller_exit(
    state_dir: Path,
    *,
    role: str,
    generation: int,
    intent_token: str,
    job_id: str,
    returncode: int,
    reason: str,
    now: float | None = None,
) -> None:
    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        state = control["controllers"][role]
        active = state.get("active")
        if isinstance(active, dict) and (
            str(active.get("job_id")) == job_id
            and int(active.get("generation", -1)) == generation
            and str(active.get("intent_token")) == intent_token
        ):
            state["active"] = None
        state["last_exit"] = {
            "job_id": job_id,
            "generation": generation,
            "intent_token": intent_token,
            "returncode": returncode,
            "reason": reason,
            "at": utc_timestamp(timestamp),
            "timestamp": timestamp,
        }
        append_transition(
            state_dir,
            control,
            event="controller_exited",
            details={
                "role": role,
                "generation": generation,
                "job_id": job_id,
                "returncode": returncode,
                "reason": reason,
            },
            now=timestamp,
        )
        _save_control(state_dir, control, now=timestamp)


def _ensure_own_successor(
    state_dir: Path,
    *,
    role: str,
    job_id: str,
    snapshot: SchedulerSnapshot,
) -> dict[str, Any] | None:
    control = load_control(state_dir)
    if control["desired_state"] != "running":
        return None
    successor = control["controllers"][role].get("successor")
    if isinstance(successor, dict) and successor.get("job_id"):
        if (
            _exact_live_own_successor_job(
                snapshot,
                successor=successor,
                parent_job_id=job_id,
            )
            is not None
        ):
            return successor
    return submit_controller_intent(
        state_dir,
        role=role,
        target="successor",
        dependency_job_id=job_id,
        scheduler=snapshot,
    )


def _exact_live_own_successor_job(
    snapshot: SchedulerSnapshot,
    *,
    successor: Mapping[str, Any],
    parent_job_id: str,
) -> SchedulerJob | None:
    """Bind one live successor to its exact immutable script and afterany parent."""

    job = _exact_live_controller_job(snapshot, successor)
    if job is None:
        return None
    if not _dependency_binds_exact_afterany(job.dependency, parent_job_id):
        raise SchedulerAmbiguity(
            f"controller successor {job.job_id} does not bind exact afterany parent "
            f"{parent_job_id}"
        )
    return job


def _signal_process_group(child: subprocess.Popen[Any], sig: signal.Signals) -> None:
    if child.poll() is not None:
        return
    try:
        os.killpg(child.pid, sig)
    except ProcessLookupError:
        return


@dataclass
class _ManagedMonitorProcess:
    cadence: str
    attempt_id: str
    process: subprocess.Popen[Any]
    output: TextIO
    started_timestamp: float
    timeout_seconds: float
    termination_started_timestamp: float | None = None


def _validate_monitor_cadence(cadence: str) -> None:
    if cadence not in MONITOR_CADENCE_SECONDS:
        raise ControlError(
            f"unknown monitor cadence {cadence!r}; expected "
            f"{tuple(MONITOR_CADENCE_SECONDS)}"
        )


def schema5_monitor_command(
    state_dir: Path,
    control: Mapping[str, Any],
    *,
    cadence: str,
) -> list[str]:
    """Build the exact frozen monitor argv used by the dispatcher supervisor."""

    _validate_monitor_cadence(cadence)
    immutable = control["immutable"]
    results_root = Path(str(immutable["results_root"])).expanduser().resolve()
    resolved_state_dir = state_dir.expanduser().resolve()
    expected_state_dir = results_root / ".dispatcher-schema5-v1"
    if resolved_state_dir != expected_state_dir:
        raise ImmutablePinError(
            "monitor state directory must be the pinned results-root control directory: "
            f"expected {expected_state_dir}, found {resolved_state_dir}"
        )
    release_worktree = Path(str(immutable["release_worktree"])).expanduser().resolve()
    python = (
        Path(str(immutable["harness_environment_prefix"])).expanduser().resolve()
        / "bin"
        / "python"
    )
    script = release_worktree / "scripts" / "schema5_monitor.py"
    config = release_worktree / "configs" / "schema5_monitoring.v1.json"
    for path, description in (
        (python, "immutable harness Python"),
        (script, "frozen schema-5 monitor"),
        (config, "frozen schema-5 monitoring contract"),
    ):
        if not path.is_file():
            raise ImmutablePinError(f"{description} is missing: {path}")
    command = [
        str(python),
        "-u",
        str(script),
        "--cadence",
        cadence,
        "--config",
        str(config),
        "--results-root",
        str(results_root),
        "--state-dir",
        str(resolved_state_dir),
        "--persist",
        "--send-email",
    ]
    if cadence == "health":
        command.append("--probe-endpoints")
    return command


def _next_aligned_deadline(
    *, scheduled_for: float, interval: float, now: float
) -> float:
    deadline = float(scheduled_for) + float(interval)
    if deadline <= now:
        skipped = int((now - deadline) // interval) + 1
        deadline += skipped * interval
    return deadline


def monitor_due_cadences(control: Mapping[str, Any], *, now: float) -> tuple[str, ...]:
    """Return due, non-overlapping cadences from durable control state."""

    if control.get("desired_state") != "running":
        return ()
    rows = control["monitoring"]["cadences"]
    return tuple(
        cadence
        for cadence in MONITOR_CADENCE_SECONDS
        if rows[cadence]["active_attempt"] is None
        and float(rows[cadence]["next_due_timestamp"]) <= now
    )


def begin_monitor_attempt(
    state_dir: Path,
    *,
    cadence: str,
    controller_generation: int,
    controller_intent_token: str,
    controller_job_id: str,
    now: float | None = None,
) -> dict[str, Any]:
    """Persist a cadence intent before starting its monitor subprocess."""

    _validate_monitor_cadence(cadence)
    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        if control["desired_state"] != "running":
            raise ControlError("cannot start a schema-5 monitor while paused")
        row = control["monitoring"]["cadences"][cadence]
        if row["active_attempt"] is not None:
            raise ControlError(
                f"monitor cadence {cadence!r} already has an active attempt"
            )
        if float(row["next_due_timestamp"]) > timestamp:
            raise ControlError(f"monitor cadence {cadence!r} is not due")
        scheduled_for = float(row["next_due_timestamp"])
        attempt_id = uuid.uuid4().hex
        log_path = (
            state_dir
            / "monitoring"
            / "controller_logs"
            / cadence
            / f"{int(timestamp)}.{attempt_id}.log"
        ).resolve()
        attempt = {
            "attempt_id": attempt_id,
            "cadence": cadence,
            "scheduled_for_at": utc_timestamp(scheduled_for),
            "scheduled_for_timestamp": scheduled_for,
            "started_at": utc_timestamp(timestamp),
            "started_timestamp": timestamp,
            "controller_generation": int(controller_generation),
            "controller_intent_token": str(controller_intent_token),
            "controller_job_id": str(controller_job_id),
            "log_path": str(log_path),
            "timeout_seconds": MONITOR_DEADLINE_SECONDS[cadence],
            "deadline_at": utc_timestamp(
                timestamp + MONITOR_DEADLINE_SECONDS[cadence]
            ),
            "deadline_timestamp": (
                timestamp + MONITOR_DEADLINE_SECONDS[cadence]
            ),
        }
        row["active_attempt"] = attempt
        row["last_attempt_at"] = utc_timestamp(timestamp)
        row["last_attempt_timestamp"] = timestamp
        deadline = _next_aligned_deadline(
            scheduled_for=scheduled_for,
            interval=float(row["interval_seconds"]),
            now=timestamp,
        )
        row["next_due_at"] = utc_timestamp(deadline)
        row["next_due_timestamp"] = deadline
        _save_control(state_dir, control, now=timestamp)
        return copy.deepcopy(attempt)


def complete_monitor_attempt(
    state_dir: Path,
    *,
    cadence: str,
    attempt_id: str,
    returncode: int | None,
    error: str | None = None,
    now: float | None = None,
) -> dict[str, Any]:
    """Fence and durably finish one monitor attempt.

    Exit code 2 is a successful scan with critical scientific findings; the monitor has
    already persisted and emailed those findings.  Only execution failures are retried
    early and raised as supervisor alerts.
    """

    _validate_monitor_cadence(cadence)
    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        row = control["monitoring"]["cadences"][cadence]
        active = row.get("active_attempt")
        if not isinstance(active, dict) or active.get("attempt_id") != attempt_id:
            raise ControllerFenced(
                f"monitor attempt {attempt_id!r} no longer owns cadence {cadence!r}"
            )
        successful = returncode in MONITOR_SUCCESS_RETURN_CODES and error is None
        row["active_attempt"] = None
        row["last_returncode"] = returncode
        if successful:
            row["last_success_at"] = utc_timestamp(timestamp)
            row["last_success_timestamp"] = timestamp
            row["last_error"] = None
            row["consecutive_failures"] = 0
        else:
            message = error or f"monitor exited with code {returncode}"
            row["last_failure_at"] = utc_timestamp(timestamp)
            row["last_failure_timestamp"] = timestamp
            row["last_error"] = message[:2000]
            row["consecutive_failures"] = int(row["consecutive_failures"]) + 1
            retry_at = timestamp + MONITOR_RETRY_SECONDS
            if retry_at < float(row["next_due_timestamp"]):
                row["next_due_at"] = utc_timestamp(retry_at)
                row["next_due_timestamp"] = retry_at
        if float(row["next_due_timestamp"]) <= timestamp:
            deadline = _next_aligned_deadline(
                scheduled_for=float(row["next_due_timestamp"]),
                interval=float(row["interval_seconds"]),
                now=timestamp,
            )
            row["next_due_at"] = utc_timestamp(deadline)
            row["next_due_timestamp"] = deadline
        _save_control(state_dir, control, now=timestamp)
        return copy.deepcopy(row)


def recover_abandoned_monitor_attempts(
    state_dir: Path,
    *,
    controller_generation: int,
    controller_intent_token: str,
    controller_job_id: str,
    now: float | None = None,
) -> list[dict[str, Any]]:
    """Clear monitor intents left by a terminated dispatcher controller."""

    timestamp = time.time() if now is None else float(now)
    recovered: list[dict[str, Any]] = []
    with control_lock(state_dir):
        control = load_control(state_dir)
        for cadence, row in control["monitoring"]["cadences"].items():
            active = row.get("active_attempt")
            if not isinstance(active, dict):
                continue
            recovered.append(copy.deepcopy(active))
            row["active_attempt"] = None
            row["last_failure_at"] = utc_timestamp(timestamp)
            row["last_failure_timestamp"] = timestamp
            row["last_error"] = (
                "abandoned monitor attempt recovered by dispatcher "
                f"generation={controller_generation} intent={controller_intent_token} "
                f"job={controller_job_id}"
            )
            row["consecutive_failures"] = int(row["consecutive_failures"]) + 1
            row["next_due_at"] = utc_timestamp(timestamp)
            row["next_due_timestamp"] = timestamp
        if recovered:
            _save_control(state_dir, control, now=timestamp)
    return recovered


def abandon_monitor_attempt(
    state_dir: Path,
    *,
    cadence: str,
    attempt_id: str,
    reason: str,
    now: float | None = None,
) -> None:
    """Clear an orderly controller-drain attempt without treating it as a failure."""

    timestamp = time.time() if now is None else float(now)
    with control_lock(state_dir):
        control = load_control(state_dir)
        row = control["monitoring"]["cadences"][cadence]
        active = row.get("active_attempt")
        if not isinstance(active, dict) or active.get("attempt_id") != attempt_id:
            return
        row["active_attempt"] = None
        row["last_error"] = reason[:2000]
        row["next_due_at"] = utc_timestamp(timestamp)
        row["next_due_timestamp"] = timestamp
        _save_control(state_dir, control, now=timestamp)


def _monitor_failure_alert(
    state_dir: Path, *, cadence: str, message: str, now: float
) -> None:
    """Best-effort deduplicated email path; never propagate into supervision."""

    dedupe_key = f"{MONITOR_FAILURE_ALERT_PREFIX}:{cadence}"
    try:
        active = any(
            alert.get("dedupe_key") == dedupe_key and alert.get("resolved_at") is None
            for alert in load_control(state_dir)["alerts"]
        )
        record_alert(
            state_dir,
            kind="monitor-execution-failure",
            severity="critical",
            message=message,
            dedupe_key=dedupe_key,
            send_email=not active,
            now=now,
        )
    except Exception as exc:
        print(
            f"[schema5-control] could not persist {cadence} monitor alert: {exc}",
            file=sys.stderr,
            flush=True,
        )


def _start_monitor_process(
    state_dir: Path,
    *,
    cadence: str,
    controller_generation: int,
    controller_intent_token: str,
    controller_job_id: str,
    now: float,
    popen_factory: Callable[..., subprocess.Popen[Any]] = subprocess.Popen,
) -> _ManagedMonitorProcess | None:
    attempt: dict[str, Any] | None = None
    output: TextIO | None = None
    try:
        attempt = begin_monitor_attempt(
            state_dir,
            cadence=cadence,
            controller_generation=controller_generation,
            controller_intent_token=controller_intent_token,
            controller_job_id=controller_job_id,
            now=now,
        )
        # Re-verify the frozen release and environment/model/fleet/run pins at every
        # monitor launch, not merely when this 12-hour controller generation began.
        control = load_control(state_dir, verify_files=True)
        command = schema5_monitor_command(state_dir, control, cadence=cadence)
        log_path = Path(str(attempt["log_path"]))
        log_path.parent.mkdir(parents=True, exist_ok=True)
        output = log_path.open("a", encoding="utf-8")
        environment = _sanitized_subprocess_environment()
        environment.update(production_environment(control))
        environment["ASYS_SCHEMA5_CONTROL"] = str(_state_path(state_dir).resolve())
        environment["PYTHONDONTWRITEBYTECODE"] = "1"
        process = popen_factory(
            command,
            env=environment,
            stdout=output,
            stderr=subprocess.STDOUT,
            start_new_session=True,
        )
        return _ManagedMonitorProcess(
            cadence=cadence,
            attempt_id=str(attempt["attempt_id"]),
            process=process,
            output=output,
            started_timestamp=float(attempt["started_timestamp"]),
            timeout_seconds=float(attempt["timeout_seconds"]),
        )
    except Exception as exc:
        if output is not None:
            output.close()
        message = f"could not start {cadence} monitor: {type(exc).__name__}: {exc}"
        if attempt is not None:
            try:
                complete_monitor_attempt(
                    state_dir,
                    cadence=cadence,
                    attempt_id=str(attempt["attempt_id"]),
                    returncode=None,
                    error=message,
                    now=now,
                )
            except Exception as completion_exc:
                message += f"; completion persistence failed: {completion_exc}"
        _monitor_failure_alert(state_dir, cadence=cadence, message=message, now=now)
        print(f"[schema5-control] {message}", file=sys.stderr, flush=True)
        return None


def _service_schema5_monitors(
    state_dir: Path,
    *,
    processes: MutableMapping[str, _ManagedMonitorProcess],
    controller_generation: int,
    controller_intent_token: str,
    controller_job_id: str,
    now: float,
    popen_factory: Callable[..., subprocess.Popen[Any]] = subprocess.Popen,
    alert_mail_runner: (
        Callable[[Sequence[str], str], subprocess.CompletedProcess[str]] | None
    ) = None,
) -> None:
    """Poll and launch monitors; all per-cadence errors are controller-safe."""

    # Email delivery is owned by the long-lived dispatcher supervisor, not by a
    # successful monitor subprocess.  This keeps persisted alert intents live when
    # every monitor repeatedly fails before it can publish a report.  The durable
    # in-flight token and retry timestamp fence concurrent monitor/controller calls.
    try:
        retry_pending_alert_emails(
            state_dir,
            mail_runner=alert_mail_runner,
            now=now,
        )
    except Exception as exc:
        print(
            f"[schema5-control] pending alert email retry failed safely: {exc}",
            file=sys.stderr,
            flush=True,
        )

    for cadence, managed in list(processes.items()):
        try:
            returncode = managed.process.poll()
            if returncode is None:
                elapsed = max(0.0, now - managed.started_timestamp)
                if elapsed >= managed.timeout_seconds:
                    if managed.termination_started_timestamp is None:
                        _signal_process_group(managed.process, signal.SIGTERM)
                        managed.termination_started_timestamp = now
                        managed.output.write(
                            "\n[schema5-control] monitor deadline exceeded; "
                            f"sent TERM after {elapsed:.1f}s\n"
                        )
                        managed.output.flush()
                    elif (
                        now - managed.termination_started_timestamp
                        >= MONITOR_TERMINATE_GRACE_SECONDS
                    ):
                        _signal_process_group(managed.process, signal.SIGKILL)
                        managed.output.write(
                            "[schema5-control] monitor ignored TERM; sent KILL\n"
                        )
                        managed.output.flush()
                continue
            managed.output.close()
            timed_out = managed.termination_started_timestamp is not None
            row = complete_monitor_attempt(
                state_dir,
                cadence=cadence,
                attempt_id=managed.attempt_id,
                returncode=int(returncode),
                error=(
                    f"{cadence} monitor exceeded its "
                    f"{managed.timeout_seconds:.0f}s execution deadline"
                    if timed_out
                    else None
                ),
                now=now,
            )
            processes.pop(cadence, None)
            if returncode in MONITOR_SUCCESS_RETURN_CODES and not timed_out:
                resolve_alert(
                    state_dir,
                    dedupe_key=f"{MONITOR_FAILURE_ALERT_PREFIX}:{cadence}",
                    now=now,
                )
            else:
                _monitor_failure_alert(
                    state_dir,
                    cadence=cadence,
                    message=(
                        f"{cadence} monitor exited with code {returncode}; "
                        f"timed_out={timed_out}; "
                        f"log={managed.output.name}; failures={row['consecutive_failures']}"
                    ),
                    now=now,
                )
        except Exception as exc:
            # One broken cadence must neither stop admission nor suppress the other
            # monitors.  Keep an unpolled process tracked; a completed but unrecordable
            # process is retried/recovered by the next controller.
            _monitor_failure_alert(
                state_dir,
                cadence=cadence,
                message=f"could not service {cadence} monitor: {type(exc).__name__}: {exc}",
                now=now,
            )
            print(
                f"[schema5-control] monitor service error ({cadence}): {exc}",
                file=sys.stderr,
                flush=True,
            )

    try:
        current = load_control(state_dir)
        due = monitor_due_cadences(current, now=now)
    except Exception as exc:
        _monitor_failure_alert(
            state_dir,
            cadence="health",
            message=f"could not load monitor cadence state: {type(exc).__name__}: {exc}",
            now=now,
        )
        return
    for cadence in due:
        if cadence in processes:
            continue
        # Daily already performs the complete semantic scan.  Keep those two heavy
        # scans serialized while allowing the lightweight five-minute health probe to
        # continue independently.
        if cadence in {"semantic", "daily"} and any(
            active in processes for active in ("semantic", "daily")
        ):
            continue
        managed = _start_monitor_process(
            state_dir,
            cadence=cadence,
            controller_generation=controller_generation,
            controller_intent_token=controller_intent_token,
            controller_job_id=controller_job_id,
            now=now,
            popen_factory=popen_factory,
        )
        if managed is not None:
            processes[cadence] = managed


def _stop_schema5_monitors(
    state_dir: Path,
    processes: MutableMapping[str, _ManagedMonitorProcess],
    *,
    reason: str,
) -> None:
    """Terminate controller-owned monitors and leave every cadence immediately due."""

    for cadence, managed in list(processes.items()):
        try:
            _signal_process_group(managed.process, signal.SIGTERM)
            try:
                managed.process.wait(timeout=5.0)
            except subprocess.TimeoutExpired:
                _signal_process_group(managed.process, signal.SIGKILL)
        except Exception as exc:
            print(
                f"[schema5-control] could not stop {cadence} monitor: {exc}",
                file=sys.stderr,
                flush=True,
            )
        finally:
            managed.output.close()
            try:
                abandon_monitor_attempt(
                    state_dir,
                    cadence=cadence,
                    attempt_id=managed.attempt_id,
                    reason=reason,
                )
            except Exception as exc:
                print(
                    f"[schema5-control] could not abandon {cadence} monitor: {exc}",
                    file=sys.stderr,
                    flush=True,
                )
            processes.pop(cadence, None)


def supervise(
    state_dir: Path,
    *,
    role: str,
    generation: int,
    intent_token: str,
    heartbeat_interval: float = HEARTBEAT_INTERVAL_SECONDS,
    stale_seconds: float = STALE_HEARTBEAT_SECONDS,
    drain_grace_seconds: float = 90.0,
) -> int:
    """Run one fenced controller process and continuously supervise its peer role."""
    _validate_role(role)
    if heartbeat_interval <= 0 or stale_seconds < heartbeat_interval:
        raise ControlError("invalid controller heartbeat/staleness intervals")
    job_id = os.environ.get("SLURM_JOB_ID", "")
    if not job_id:
        raise ControllerFenced("supervise must run inside a Slurm allocation")
    stop_requested = False

    def request_stop(_signum: int, _frame: Any) -> None:
        nonlocal stop_requested
        stop_requested = True

    previous_handlers = {
        sig: signal.signal(sig, request_stop) for sig in (signal.SIGTERM, signal.SIGINT)
    }
    child: subprocess.Popen[Any] | None = None
    runtime_refresh: _RuntimeLeaseRefreshTask | None = None
    snapshot_refresh: _SnapshotLeaseRefreshTask | None = None
    monitor_processes: dict[str, _ManagedMonitorProcess] = {}
    exit_reason = "supervisor_error"
    returncode = 1
    try:
        with role_singleton_lock(state_dir, role):
            initial_snapshot = query_scheduler(tolerate_errors=True)
            validate_live_controller_placement(
                job_id=job_id,
                role=role,
                generation=generation,
                intent_token=intent_token,
            )
            claim_controller(
                state_dir,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                active_scheduler_job_ids=initial_snapshot.active_job_ids | {job_id},
            )
            # A resume-submitted job may begin before its peer is visible.  Claim the
            # exact durable identity so no duplicate can take the role, but do not
            # start either managed plane until the atomic resume commit publishes
            # ``running``.  This is what makes unheld submission both restartable and
            # safe from one-controller admission.
            wait_heartbeat = 0.0
            while True:
                waiting_control = load_control(state_dir)
                if waiting_control["desired_state"] == "running":
                    break
                if stop_requested or waiting_control["desired_state"] == "paused":
                    returncode = 0
                    exit_reason = (
                        "desired_state_paused"
                        if waiting_control["desired_state"] == "paused"
                        else "signal"
                    )
                    return returncode
                wait_now = time.time()
                if wait_now - wait_heartbeat >= heartbeat_interval:
                    heartbeat_controller(
                        state_dir,
                        role=role,
                        generation=generation,
                        intent_token=intent_token,
                        job_id=job_id,
                        now=wait_now,
                    )
                    # Scheduler visibility may legitimately take longer than either
                    # seven-minute integrity lease.  Renew and verify both exact
                    # generation proofs on every waiting heartbeat; the snapshot scan
                    # runs in a daemon task while the waiter continues fenced
                    # heartbeats, so liveness does not weaken the drift boundary.
                    runtime_refresh = _start_runtime_lease_refresh(
                        state_dir, waiting_control
                    )
                    _await_runtime_lease_refresh_with_heartbeats(
                        runtime_refresh,
                        state_dir=state_dir,
                        role=role,
                        generation=generation,
                        intent_token=intent_token,
                        job_id=job_id,
                        heartbeat_interval=heartbeat_interval,
                    )
                    runtime_refresh = None
                    validate_runtime_integrity_attestation(
                        waiting_control, verify_metadata=True
                    )
                    snapshot_refresh = _start_snapshot_lease_refresh(
                        state_dir, waiting_control
                    )
                    _await_snapshot_lease_refresh_with_heartbeats(
                        snapshot_refresh,
                        state_dir=state_dir,
                        role=role,
                        generation=generation,
                        intent_token=intent_token,
                        job_id=job_id,
                        heartbeat_interval=heartbeat_interval,
                    )
                    snapshot_refresh = None
                    validate_snapshot_integrity_attestation(
                        waiting_control,
                        state_dir=state_dir,
                        verify_lease=True,
                    )
                    wait_heartbeat = time.time()
                time.sleep(min(1.0, heartbeat_interval))
            # A preemptible controller is safe only after its exact afterany successor
            # is durably accepted *and* visible with the frozen script, parent edge,
            # controller-only partition, and Requeue=0.  Never start the dispatcher or
            # fleet plane in the sbatch/visibility gap.  Heartbeats and integrity
            # leases continue while transient scheduler failures are retried.
            successor_wait_heartbeat = 0.0
            while True:
                waiting_control = load_control(state_dir)
                if stop_requested or waiting_control["desired_state"] == "paused":
                    returncode = 0
                    exit_reason = (
                        "desired_state_paused"
                        if waiting_control["desired_state"] == "paused"
                        else "signal"
                    )
                    return returncode
                successor_now = time.time()
                successor_snapshot = query_scheduler(
                    tolerate_errors=True,
                    now=successor_now,
                )
                verified_successor: dict[str, Any] | None = None
                try:
                    candidate = _ensure_own_successor(
                        state_dir,
                        role=role,
                        job_id=job_id,
                        snapshot=successor_snapshot,
                    )
                    if isinstance(candidate, dict):
                        successor_job = _exact_live_own_successor_job(
                            successor_snapshot,
                            successor=candidate,
                            parent_job_id=job_id,
                        )
                        if successor_job is not None:
                            validate_live_controller_placement(
                                job_id=str(candidate["job_id"]),
                                role=role,
                                generation=int(candidate["generation"]),
                                intent_token=str(candidate["intent_token"]),
                            )
                            verified_successor = candidate
                except (ControlError, OSError) as exc:
                    print(
                        f"[schema5-control] successor retry required for {role}: {exc}",
                        file=sys.stderr,
                        flush=True,
                    )
                if verified_successor is not None:
                    break
                if successor_now - successor_wait_heartbeat >= heartbeat_interval:
                    heartbeat_controller(
                        state_dir,
                        role=role,
                        generation=generation,
                        intent_token=intent_token,
                        job_id=job_id,
                        now=successor_now,
                    )
                    runtime_refresh = _start_runtime_lease_refresh(
                        state_dir, waiting_control
                    )
                    _await_runtime_lease_refresh_with_heartbeats(
                        runtime_refresh,
                        state_dir=state_dir,
                        role=role,
                        generation=generation,
                        intent_token=intent_token,
                        job_id=job_id,
                        heartbeat_interval=heartbeat_interval,
                    )
                    runtime_refresh = None
                    validate_runtime_integrity_attestation(
                        waiting_control,
                        verify_metadata=True,
                    )
                    snapshot_refresh = _start_snapshot_lease_refresh(
                        state_dir, waiting_control
                    )
                    _await_snapshot_lease_refresh_with_heartbeats(
                        snapshot_refresh,
                        state_dir=state_dir,
                        role=role,
                        generation=generation,
                        intent_token=intent_token,
                        job_id=job_id,
                        heartbeat_interval=heartbeat_interval,
                    )
                    snapshot_refresh = None
                    validate_snapshot_integrity_attestation(
                        waiting_control,
                        state_dir=state_dir,
                        verify_lease=True,
                    )
                    successor_wait_heartbeat = time.time()
                time.sleep(min(1.0, heartbeat_interval))

            control = load_control(state_dir, verify_files=True)
            # This is the last gate before either managed plane executes.  One
            # controller refreshes the centralized metadata lease when due; all other
            # starts validate that small, generation-bound lease in O(1).
            heartbeat_controller(
                state_dir,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                now=time.time(),
            )
            runtime_refresh = _start_runtime_lease_refresh(state_dir, control)
            _await_runtime_lease_refresh_with_heartbeats(
                runtime_refresh,
                state_dir=state_dir,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                heartbeat_interval=heartbeat_interval,
            )
            runtime_refresh = None
            validate_runtime_integrity_attestation(control, verify_metadata=True)
            snapshot_refresh = _start_snapshot_lease_refresh(state_dir, control)
            _await_snapshot_lease_refresh_with_heartbeats(
                snapshot_refresh,
                state_dir=state_dir,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                heartbeat_interval=heartbeat_interval,
            )
            snapshot_refresh = None
            validate_snapshot_integrity_attestation(
                control, state_dir=state_dir, verify_lease=True
            )
            command_field = (
                "dispatcher_command"
                if role == "dispatcher"
                else "fleet_supervisor_command"
            )
            command = (
                list(control["immutable"][command_field])
                if role == "dispatcher"
                else effective_fleet_supervisor_command(control)
            )
            environment = _sanitized_subprocess_environment()
            environment.update(production_environment(control))
            environment["ASYS_SCHEMA5_CONTROL"] = str(_state_path(state_dir).resolve())
            child = subprocess.Popen(command, env=environment, start_new_session=True)
            if role == MONITOR_OWNER_ROLE:
                try:
                    recovered = recover_abandoned_monitor_attempts(
                        state_dir,
                        controller_generation=generation,
                        controller_intent_token=intent_token,
                        controller_job_id=job_id,
                    )
                except Exception as exc:
                    recovered = []
                    _monitor_failure_alert(
                        state_dir,
                        cadence="health",
                        message=(
                            "could not reconcile restart-safe monitor intents: "
                            f"{type(exc).__name__}: {exc}"
                        ),
                        now=time.time(),
                    )
                    print(
                        f"[schema5-control] monitor recovery failed safely: {exc}",
                        file=sys.stderr,
                        flush=True,
                    )
                for attempt in recovered:
                    cadence = str(attempt.get("cadence", "health"))
                    _monitor_failure_alert(
                        state_dir,
                        cadence=cadence,
                        message=(
                            "dispatcher successor recovered an abandoned monitor attempt: "
                            f"attempt={attempt.get('attempt_id')} "
                            f"prior_job={attempt.get('controller_job_id')}"
                        ),
                        now=time.time(),
                    )
            last_heartbeat = 0.0
            last_peer_check = 0.0
            drain_started: float | None = None
            while True:
                now = time.time()
                control = load_control(state_dir)
                if runtime_refresh is not None and runtime_refresh.future.done():
                    # The completed renewal either publishes a new immutable lease or
                    # raises here.  On error the prior lease is never extended and its
                    # TTL remains the fail-closed boundary for every controller.
                    runtime_refresh.future.result()
                    runtime_refresh = None
                if snapshot_refresh is not None and snapshot_refresh.future.done():
                    # Surface drift/I/O failures promptly.  The previous lease remains
                    # immutable and expires naturally, so every admission path fails
                    # closed even if a successor also encounters the same outage.
                    snapshot_refresh.future.result()
                    snapshot_refresh = None
                desired_pause = control["desired_state"] == "paused"
                if stop_requested or desired_pause:
                    if drain_started is None:
                        drain_started = now
                        # Managed cell workers receive USR1 independently from Slurm.
                        # Controllers stop admission/supervision on TERM and exit only
                        # after their own cleanup handlers run.
                        _signal_process_group(child, signal.SIGTERM)
                    if child.poll() is not None:
                        returncode = int(child.returncode or 0)
                        exit_reason = (
                            "desired_state_paused" if desired_pause else "signal"
                        )
                        break
                    if now - drain_started >= drain_grace_seconds:
                        _signal_process_group(child, signal.SIGKILL)
                    time.sleep(min(1.0, heartbeat_interval))
                    continue

                polled = child.poll()
                if polled is not None:
                    returncode = int(polled)
                    exit_reason = "managed_process_exited"
                    break
                if now - last_heartbeat >= heartbeat_interval:
                    # Liveness is independent of filesystem latency: publish the exact
                    # fenced heartbeat before any validation or renewal work.  Snapshot
                    # renewal runs in at most one local daemon task; its cross-node lock
                    # and cache still allow only one double metadata scan fleet-wide.
                    heartbeat_now = time.time()
                    heartbeat_controller(
                        state_dir,
                        role=role,
                        generation=generation,
                        intent_token=intent_token,
                        job_id=job_id,
                        now=heartbeat_now,
                    )
                    last_heartbeat = heartbeat_now
                    # This validates only the compact generation lease.  It is
                    # intentionally performed after the fenced heartbeat and before
                    # launching renewal, so an expired proof stops the controller
                    # rather than being papered over by a late metadata scan.
                    validate_runtime_integrity_attestation(
                        control, verify_metadata=True
                    )
                    if runtime_refresh is None:
                        runtime_refresh = _start_runtime_lease_refresh(
                            state_dir, control
                        )
                    # While a slow renewal is in flight, expiry remains the strict
                    # safety bound.  This compact check never scans payload metadata.
                    validate_snapshot_integrity_attestation(
                        control, state_dir=state_dir, verify_lease=True
                    )
                    if snapshot_refresh is None:
                        snapshot_refresh = _start_snapshot_lease_refresh(
                            state_dir, control
                        )
                    scheduler_now = time.time()
                    snapshot = query_scheduler(
                        tolerate_errors=True, now=scheduler_now
                    )
                    try:
                        _ensure_own_successor(
                            state_dir, role=role, job_id=job_id, snapshot=snapshot
                        )
                    except (ControlError, OSError) as exc:
                        print(
                            f"[schema5-control] successor retry required for {role}: {exc}",
                            file=sys.stderr,
                            flush=True,
                        )
                if now - last_peer_check >= heartbeat_interval:
                    last_peer_check = now
                    peer = next(
                        candidate for candidate in ROLE_NAMES if candidate != role
                    )
                    peer_state = control["controllers"][peer]
                    age = controller_liveness_age(peer_state, now)
                    snapshot = query_scheduler(tolerate_errors=True, now=now)
                    has_chain = _role_has_live_chain(control, peer, snapshot)
                    stale = age is None or age > stale_seconds
                    if stale:
                        record_alert(
                            state_dir,
                            kind="stale_controller_heartbeat",
                            severity="critical",
                            message=(
                                f"{peer} has no live chain and heartbeat age is "
                                f"{age if age is not None else 'missing'} seconds; {role} "
                                "is attempting exact-token takeover"
                            ),
                            dedupe_key=f"stale-controller:{peer}",
                            send_email=True,
                            now=now,
                        )
                        if snapshot.squeue_ok and snapshot.sacct_ok:
                            try:
                                trigger_stale_takeover(
                                    state_dir,
                                    role=peer,
                                    snapshot=snapshot,
                                    stale_seconds=stale_seconds,
                                    now=now,
                                )
                            except ControlError as exc:
                                print(
                                    f"[schema5-control] peer repair failed closed: {exc}",
                                    file=sys.stderr,
                                    flush=True,
                                )
                    elif has_chain:
                        resolve_alert(
                            state_dir, dedupe_key=f"stale-controller:{peer}", now=now
                        )
                if role == MONITOR_OWNER_ROLE:
                    _service_schema5_monitors(
                        state_dir,
                        processes=monitor_processes,
                        controller_generation=generation,
                        controller_intent_token=intent_token,
                        controller_job_id=job_id,
                        now=now,
                    )
                time.sleep(min(1.0, heartbeat_interval))
    finally:
        for sig, handler in previous_handlers.items():
            signal.signal(sig, handler)
        if child is not None and child.poll() is None:
            _signal_process_group(child, signal.SIGTERM)
        if monitor_processes:
            _stop_schema5_monitors(
                state_dir,
                monitor_processes,
                reason=f"dispatcher supervisor exiting: {exit_reason}",
            )
        try:
            record_controller_exit(
                state_dir,
                role=role,
                generation=generation,
                intent_token=intent_token,
                job_id=job_id,
                returncode=returncode,
                reason=exit_reason,
            )
        except ControlError as exc:
            print(
                f"[schema5-control] could not record controller exit: {exc}",
                file=sys.stderr,
            )
    return returncode


def _load_json_object(path: Path, *, description: str) -> dict[str, Any]:
    def reject_duplicate_keys(pairs: Sequence[tuple[str, Any]]) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, item in pairs:
            if key in value:
                raise ValueError(f"duplicate JSON key {key!r}")
            value[key] = item
        return value

    def reject_nonfinite(value: str) -> Any:
        raise ValueError(f"non-finite JSON number {value!r}")

    try:
        value = json.loads(
            path.read_text(encoding="utf-8"),
            object_pairs_hook=reject_duplicate_keys,
            parse_constant=reject_nonfinite,
        )
    except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as exc:
        raise ControlError(f"cannot read {description} {path}: {exc}") from exc
    if not isinstance(value, dict):
        raise ControlError(f"{description} must be a JSON object: {path}")
    return value


def build_immutable_pins(
    *,
    state_dir: Path,
    release_bundle_root: Path,
    hf_home: Path,
) -> dict[str, Any]:
    """Derive the complete closed pin schema from published authority artifacts.

    The release freezer owns code, model, fleet, and environment identity.  The three
    cloned run roots own their manifest/lineage/policy/benchmark identity.  This builder
    joins those two sources without accepting any free-form command, run, weight, count,
    or hash override from the operator, then runs the same deep validator used by
    ``init`` before returning a byte-publishable object.
    """

    raw_state_dir = state_dir.expanduser()
    if raw_state_dir.is_symlink():
        raise ImmutablePinError(
            f"control state directory cannot be a symlink: {raw_state_dir}"
        )
    resolved_state_dir = raw_state_dir.resolve()
    if resolved_state_dir.name != CONTROL_STATE_DIRNAME:
        raise ImmutablePinError(
            f"control state directory must end in {CONTROL_STATE_DIRNAME!r}: "
            f"{resolved_state_dir}"
        )
    results_root = resolved_state_dir.parent
    if results_root.is_symlink() or not results_root.is_dir():
        raise ImmutablePinError(f"results root is missing or symlinked: {results_root}")

    raw_bundle = release_bundle_root.expanduser()
    if raw_bundle.is_symlink() or not raw_bundle.is_dir():
        raise ImmutablePinError(
            f"release bundle root is missing or symlinked: {raw_bundle}"
        )
    bundle = raw_bundle.resolve()
    marker_path = bundle / RELEASE_COMPLETE_FILENAME
    identity_path = bundle / RELEASE_IDENTITY_FILENAME
    for description, path in (
        ("release completion marker", marker_path),
        ("release identity", identity_path),
    ):
        if path.is_symlink() or not path.is_file():
            raise ImmutablePinError(f"{description} is missing or symlinked: {path}")
    marker = _load_json_object(marker_path, description="release completion marker")
    identity = _load_json_object(identity_path, description="release identity")
    fragment = identity.get("control_pin_fragment")
    if not isinstance(fragment, dict) or set(fragment) != _RELEASE_FRAGMENT_FIELDS:
        raise ImmutablePinError(
            "release identity does not contain the exact control pin fragment"
        )
    if (
        marker.get("complete") is not True
        or marker.get("release_id") != fragment.get("release_id")
        or marker.get("release_bundle_id") in {None, ""}
    ):
        raise ImmutablePinError("release marker and control pin fragment disagree")

    raw_hf_home = hf_home.expanduser()
    if raw_hf_home.is_symlink() or not raw_hf_home.is_dir():
        raise ImmutablePinError(
            f"Hugging Face home is missing or symlinked: {raw_hf_home}"
        )
    resolved_hf_home = raw_hf_home.resolve()
    protected_capacity_marker_path = protected_capacity.canonical_marker_path(
        results_root
    )
    try:
        protected_capacity_contract = protected_capacity.load_contract(
            protected_capacity_marker_path,
            expected_release_git_commit=str(fragment["git_commit"]),
            expected_release_tag_object=str(
                fragment["release_tag_object"]
            ),
            **_protected_capacity_source_expectations(fragment),
        )
    except protected_capacity.ProtectedCapacityError as exc:
        raise ImmutablePinError(
            f"protected scientific capacity is not ready: {exc}"
        ) from exc
    qualifying_client_placements = []
    for placement in protected_capacity_contract.client_placements:
        try:
            protected_capacity.authorize_client(
                protected_capacity_contract,
                partition=placement.partition,
                qos=placement.qos,
                required_slots=PRODUCTION_DESIGN_CELL_CAP,
                required_reserve_jobs=64,
            )
        except protected_capacity.ProtectedCapacityError:
            continue
        qualifying_client_placements.append(placement)
    if len(qualifying_client_placements) != 1:
        raise ImmutablePinError(
            "protected capacity must identify exactly one scientific client "
            "placement that authorizes 384 cells plus the 64-job reserve"
        )
    protected_client_placement = qualifying_client_placements[0]
    server_pool_root = results_root / "server_pools" / "schema5-v1"
    if server_pool_root.is_symlink() or not server_pool_root.is_dir():
        raise ImmutablePinError(
            f"canonical schema-5 server pool is missing or symlinked: {server_pool_root}"
        )
    try:
        stale_pool_entries = sorted(path.name for path in server_pool_root.iterdir())
    except OSError as exc:
        raise ImmutablePinError(
            f"cannot inspect canonical schema-5 server pool: {server_pool_root}: {exc}"
        ) from exc
    if stale_pool_entries:
        preview = ", ".join(stale_pool_entries[:8])
        if len(stale_pool_entries) > 8:
            preview += f", ... ({len(stale_pool_entries)} entries total)"
        raise ImmutablePinError(
            "canonical schema-5 server pool must be empty before v1.2 pin "
            f"publication; stale entries found in {server_pool_root}: {preview}"
        )

    runs: list[dict[str, Any]] = []
    for run_id, expected_cells in REQUIRED_RUNS.items():
        run_root = results_root / run_id
        if run_root.is_symlink() or not run_root.is_dir():
            raise ImmutablePinError(
                f"schema-5 run root is missing or symlinked: {run_root}"
            )
        paths = {
            "manifest": run_root / "cells.json",
            "lineage": run_root / "lineage.schema5-v1.json",
            "policy": run_root / "artifact_policy.schema5-v1.json",
            "benchmark_contract": run_root / "benchmark_contracts.v1.json",
        }
        for description, path in paths.items():
            if path.is_symlink() or not path.is_file():
                raise ImmutablePinError(
                    f"run {run_id} {description} is missing or symlinked: {path}"
                )
        hashes = {name: sha256_file(path) for name, path in paths.items()}
        try:
            manifest = json.loads(paths["manifest"].read_text(encoding="utf-8"))
        except (OSError, UnicodeError, json.JSONDecodeError) as exc:
            raise ImmutablePinError(
                f"cannot parse run manifest {paths['manifest']}: {exc}"
            ) from exc
        if not isinstance(manifest, list) or len(manifest) != expected_cells:
            raise ImmutablePinError(
                f"run {run_id} manifest must contain exactly {expected_cells} cells"
            )
        lineage = _load_json_object(paths["lineage"], description=f"{run_id} lineage")
        policy = _load_json_object(paths["policy"], description=f"{run_id} policy")
        target_artifacts = lineage.get("target_artifacts")
        target_manifest = (
            target_artifacts.get("cells.json")
            if isinstance(target_artifacts, dict)
            else None
        )
        target_benchmarks = (
            target_artifacts.get("benchmark_contracts.v1.json")
            if isinstance(target_artifacts, dict)
            else None
        )
        if (
            lineage.get("schema_version") != 1
            or lineage.get("clone_mode") != "byte_for_byte_scientific_contract"
            or lineage.get("target_run_id") != run_id
            or lineage.get("manifest_cell_count") != expected_cells
            or lineage.get("imported_result_rows") != 0
            or lineage.get("transformations") != []
            or not isinstance(target_artifacts, dict)
            or not isinstance(target_manifest, dict)
            or target_manifest.get("sha256") != hashes["manifest"]
            or not isinstance(target_benchmarks, dict)
            or target_benchmarks.get("sha256") != hashes["benchmark_contract"]
        ):
            raise ImmutablePinError(
                f"run {run_id} lineage does not bind its frozen clone"
            )
        policy_release = policy.get("release")
        policy_environment = policy.get("environment")
        if (
            policy.get("schema_version") != 1
            or policy.get("run_id") != run_id
            or policy.get("authoritative") is not True
            or policy.get("required_artifact_schema_version") != 5
            or policy.get("accepted_manifest_sha256") != hashes["manifest"]
            or policy.get("accepted_benchmark_contracts_sha256")
            != hashes["benchmark_contract"]
            or policy.get("accepted_model_contract_sha256")
            != fragment["model_contract_sha256"]
            or policy.get("legacy_result_import_allowed") is not False
            or not isinstance(policy_release, dict)
            or policy_release.get("release_id") != fragment["release_id"]
            or policy_release.get("git_commit") != fragment["git_commit"]
            or policy_release.get("source_tree_sha256")
            != fragment["source_tree_sha256"]
            or not isinstance(policy_environment, dict)
            or policy_environment.get("harness_sha256")
            != fragment["harness_environment_sha256"]
            or policy_environment.get("serving_sha256")
            != fragment["serving_environment_sha256"]
        ):
            raise ImmutablePinError(
                f"run {run_id} policy does not bind the frozen release"
            )
        runs.append(
            {
                "run_id": run_id,
                "run_root": str(run_root),
                "cell_count": expected_cells,
                "expected_qids": REQUIRED_RUN_QIDS[run_id],
                "weight": RUN_WEIGHT,
                "manifest_path": str(paths["manifest"]),
                "manifest_sha256": hashes["manifest"],
                "lineage_path": str(paths["lineage"]),
                "lineage_sha256": hashes["lineage"],
                "policy_path": str(paths["policy"]),
                "policy_sha256": hashes["policy"],
                "benchmark_contract_path": str(paths["benchmark_contract"]),
                "benchmark_contract_sha256": hashes["benchmark_contract"],
            }
        )

    pins: dict[str, Any] = {
        **copy.deepcopy(fragment),
        "release_bundle_root": str(bundle),
        "release_bundle_id": str(marker["release_bundle_id"]),
        "protected_capacity_marker_path": str(
            protected_capacity_contract.path
        ),
        "protected_capacity_marker_sha256": (
            protected_capacity_contract.sha256
        ),
        "protected_capacity_marker_id": protected_capacity_contract.marker_id,
        "protected_client_partition": protected_client_placement.partition,
        "protected_client_qos": protected_client_placement.qos,
        "protected_client_slots": int(
            protected_client_placement.capacity["slots"]
        ),
        "protected_client_cpus": int(
            protected_client_placement.capacity["cpus"]
        ),
        "protected_client_memory_mib": int(
            protected_client_placement.capacity["memory_mib"]
        ),
        "protected_client_reserve_jobs": int(
            protected_client_placement.capacity["reserve_jobs"]
        ),
        "protected_client_submit_headroom": int(
            protected_client_placement.capacity["submit_headroom"]
        ),
        "hf_home": str(resolved_hf_home),
        "results_root": str(results_root),
        "server_pool_root": str(server_pool_root),
        "dispatcher_command": [],
        "fleet_supervisor_command": [],
        "runs": runs,
    }
    pins["dispatcher_command"] = expected_dispatcher_command(pins)
    pins["fleet_supervisor_command"] = expected_fleet_supervisor_command(pins)
    validate_immutable_pins(pins, verify_files=True)
    return pins


def publish_immutable_pins(path: Path, pins: Mapping[str, Any]) -> dict[str, Any]:
    """Publish one deterministic, checksummed, read-only pins document."""

    validate_immutable_pins(pins, verify_files=True)
    raw_path = path.expanduser()
    if raw_path.is_symlink() or raw_path.is_dir():
        raise ImmutablePinError(
            f"pins output is symlinked or not a file target: {raw_path}"
        )
    target = raw_path.resolve()
    payload = json.dumps(dict(pins), indent=2, sort_keys=True, allow_nan=False) + "\n"
    if target.exists():
        if not target.is_file():
            raise ImmutablePinError(f"pins output is not a regular file: {target}")
        try:
            existing = target.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            raise ImmutablePinError(
                f"cannot read existing pins output {target}: {exc}"
            ) from exc
        if existing != payload:
            raise ImmutablePinError(
                f"refusing to replace non-identical immutable pins output: {target}"
            )
        if target.stat().st_nlink != 1 or target.stat().st_mode & 0o222:
            _atomic_publish_readonly_text(target, payload)
    else:
        _atomic_publish_readonly_text(target, payload)
    digest = sha256_file(target)
    checksum_path = target.with_name(target.name + ".sha256")
    checksum_payload = f"{digest}  {target.name}\n"
    if checksum_path.is_symlink() or checksum_path.is_dir():
        raise ImmutablePinError(f"pins checksum target is unsafe: {checksum_path}")
    if checksum_path.exists():
        if not checksum_path.is_file():
            raise ImmutablePinError(
                f"pins checksum target is not a regular file: {checksum_path}"
            )
        try:
            existing_checksum = checksum_path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            raise ImmutablePinError(
                f"cannot read existing pins checksum {checksum_path}: {exc}"
            ) from exc
        if existing_checksum != checksum_payload:
            raise ImmutablePinError(
                f"refusing to replace non-identical pins checksum: {checksum_path}"
            )
        if (
            checksum_path.stat().st_nlink != 1
            or checksum_path.stat().st_mode & 0o222
        ):
            _atomic_publish_readonly_text(checksum_path, checksum_payload)
    else:
        _atomic_publish_readonly_text(checksum_path, checksum_payload)
    return {
        "output": str(target),
        "sha256": digest,
        "checksum": str(checksum_path),
        "immutable_sha256": sha256_value(pins),
        "run_count": len(pins["runs"]),
        "cell_count": sum(int(run["cell_count"]) for run in pins["runs"]),
        "expected_qids": sum(int(run["expected_qids"]) for run in pins["runs"]),
    }


def _scheduler_for_cli(*, tolerate_errors: bool = False) -> SchedulerSnapshot:
    return query_scheduler(tolerate_errors=tolerate_errors)


def _watchdog_status_for_cli(
    state_dir: Path, *, snapshot: SchedulerSnapshot
) -> dict[str, Any]:
    drill = _load_external_watchdog_drill(state_dir)
    return (
        external_watchdog_drill_status(
            state_dir,
            snapshot=snapshot,
            record_observation=True,
        )
        if drill is not None
        and drill[1]["phase"] not in {"complete", "expired"}
        else live_status(state_dir, snapshot=snapshot)
    )


def _watchdog_repair_for_cli(
    state_dir: Path, *, snapshot: SchedulerSnapshot
) -> dict[str, Any]:
    drill = _load_external_watchdog_drill(state_dir)
    if (
        drill is not None
        and drill[1]["phase"] not in {"complete", "expired"}
    ):
        return repair_external_watchdog_drill(
            state_dir, snapshot=snapshot
        )
    return repair_chains(state_dir, snapshot=snapshot)


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--state-dir", type=Path, required=True)
    subparsers = parser.add_subparsers(dest="command", required=True)

    prepare = subparsers.add_parser(
        "prepare-pins",
        help="derive and publish the closed immutable pins consumed by init",
    )
    prepare.add_argument("--release-bundle-root", type=Path, required=True)
    prepare.add_argument("--hf-home", type=Path, required=True)
    prepare.add_argument("--output", type=Path, required=True)

    init = subparsers.add_parser("init", help="initialize an immutable paused control")
    init.add_argument("--pins-json", type=Path, required=True)
    init.add_argument("--alert-email", default="mabdel03@mit.edu")

    reconcile = subparsers.add_parser(
        "reconcile",
        help="join all scheduler truth with control state, without admission",
    )
    reconcile.add_argument("--all", action="store_true", required=True)
    reconcile.add_argument("--no-admit", action="store_true", required=True)

    subparsers.add_parser("resume", help="fail closed, then set desired_state=running")

    generation_catalog = subparsers.add_parser(
        "refresh-generation-catalog",
        help=(
            "seal and verify the exact endpoint-generation authority for the "
            "current or fenced next rollout"
        ),
    )
    generation_catalog.add_argument("--rollout-generation", type=int)

    pause = subparsers.add_parser("pause", help="pause admission and gracefully drain")
    pause.add_argument("--drain", action="store_true", required=True)

    status = subparsers.add_parser(
        "status", help="report scheduler-authoritative status"
    )
    status.add_argument("--live", action="store_true", required=True)

    repair = subparsers.add_parser(
        "repair-chain", help="idempotently recreate missing controller chains"
    )
    repair.add_argument("--dry-run", action="store_true")

    # These fixed, parameter-free commands are reachable only through the sealed SSH
    # forced-command selector.  Ordinary operator status remains strictly read-only.
    subparsers.add_parser("watchdog-status", help=argparse.SUPPRESS)
    subparsers.add_parser("watchdog-observe", help=argparse.SUPPRESS)
    subparsers.add_parser("watchdog-repair-chain", help=argparse.SUPPRESS)
    subparsers.add_parser(
        "watchdog-finalizer-reconcile", help=argparse.SUPPRESS
    )

    attest = subparsers.add_parser(
        "attest", help="attach checksummed readiness evidence"
    )
    attest.add_argument(
        "--gate",
        required=True,
        choices=(*REQUIRED_GATES[:-1], *PRODUCTION_AUTHORIZATION_GATES),
    )
    attest.add_argument("--evidence", type=Path)
    attest.add_argument("--sha256")
    attest.add_argument("--chain-manifest", type=Path)

    ceiling = subparsers.add_parser(
        "set-ceiling",
        help="hold or reduce staged admission (monitor evidence alone may raise it)",
    )
    ceiling.add_argument(
        "--value", type=int, required=True, choices=ADMISSION_RAMP_STAGES
    )

    acknowledge = subparsers.add_parser(
        "ack-hold",
        help="release a semantically-cleared scientific-integrity admission hold",
    )
    acknowledge.add_argument("--note", required=True)

    client_capacity = subparsers.add_parser(
        "attest-client-capacity",
        help=(
            "attach a sealed non-preemptible client placement/canary/readiness "
            "capacity generation"
        ),
    )
    client_capacity.add_argument("--evidence", type=Path, required=True)
    client_capacity.add_argument("--sha256", required=True)

    build_client_capacity = subparsers.add_parser(
        "build-client-capacity",
        help=(
            "capture and seal a candidate non-preemptible client placement; "
            "submit transactionally submits or adopts its exact canary"
        ),
    )
    build_client_capacity.add_argument(
        "action", choices=("dry-run", "prepare", "submit", "apply")
    )
    build_client_capacity.add_argument("--partition", required=True)
    build_client_capacity.add_argument(
        "--target-ceiling", type=int, required=True, choices=(192, 384)
    )

    capacity = subparsers.add_parser(
        "capacity-transition",
        help="retire and publish one checksummed fleet/capacity generation",
    )
    capacity.add_argument(
        "action",
        nargs="?",
        default="dry-run",
        choices=("status", "dry-run", "apply", "complete"),
    )
    capacity.add_argument("--fleet-contract", type=Path)
    capacity.add_argument("--fleet-contract-sha256")
    capacity.add_argument("--protected-capacity-marker", type=Path)
    capacity.add_argument("--protected-capacity-marker-sha256")
    capacity.add_argument("--protected-capacity-marker-id")
    capacity.add_argument("--static-feasibility-certificate", type=Path)
    capacity.add_argument("--static-feasibility-certificate-sha256")
    capacity.add_argument("--static-feasibility-certificate-id")

    finalize = subparsers.add_parser(
        "finalize",
        help="drain, validate, snapshot, and publish FINAL_COMPLETE marker-last",
    )
    finalize.add_argument("--output-root", type=Path)

    subparsers.add_parser(
        "finalizer-reconcile",
        help="idempotently restore the active autonomous finalizer successor chain",
    )

    finalizer_worker = subparsers.add_parser(
        "finalizer-worker", help=argparse.SUPPRESS
    )
    finalizer_worker.add_argument("--intent-id", required=True)
    finalizer_worker.add_argument("--attempt", type=int, required=True)

    poll = subparsers.add_parser(
        "record-poll", help="append one successful generation-scoped throughput sample"
    )
    poll.add_argument("--useful-qids", type=int, required=True)
    poll.add_argument("--fleet-generation", required=True)
    poll.add_argument("--strata-with-throughput", type=int)

    drill = subparsers.add_parser(
        "drill", help="run the paused, no-admission controller kill drill"
    )
    drill.add_argument("action", choices=("start", "status", "kill", "wait", "finish"))
    drill.add_argument("--role", choices=ROLE_NAMES)
    drill.add_argument("--live", action="store_true")
    drill.add_argument("--timeout", type=float, default=900.0)

    watchdog_drill = subparsers.add_parser(
        "watchdog-drill",
        help="manage the sealed paused external-watchdog cancellation drill",
    )
    watchdog_drill.add_argument(
        "action", choices=("arm", "cancel", "status", "finish")
    )
    watchdog_drill.add_argument("--deployment-evidence", type=Path)
    watchdog_drill.add_argument("--output", type=Path)
    watchdog_drill.add_argument(
        "--expires-seconds",
        type=float,
        default=EXTERNAL_WATCHDOG_DRILL_DEFAULT_EXPIRY_SECONDS,
    )

    worker = subparsers.add_parser("supervise", help=argparse.SUPPRESS)
    worker.add_argument("--role", required=True, choices=ROLE_NAMES)
    worker.add_argument("--generation", type=int, required=True)
    worker.add_argument("--intent-token", required=True)
    worker.add_argument(
        "--heartbeat-interval", type=float, default=HEARTBEAT_INTERVAL_SECONDS
    )
    worker.add_argument("--stale-seconds", type=float, default=STALE_HEARTBEAT_SECONDS)
    worker.add_argument("--drain-grace-seconds", type=float, default=90.0)
    drill_worker = subparsers.add_parser("supervise-drill", help=argparse.SUPPRESS)
    drill_worker.add_argument("--drill-id", required=True)
    drill_worker.add_argument("--role", required=True, choices=ROLE_NAMES)
    drill_worker.add_argument("--generation", type=int, required=True)
    drill_worker.add_argument("--intent-token", required=True)
    drill_worker.add_argument(
        "--heartbeat-interval", type=float, default=HEARTBEAT_INTERVAL_SECONDS
    )
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _build_parser().parse_args(argv)
    state_dir = args.state_dir.expanduser().resolve()
    try:
        if args.command == "prepare-pins":
            canonical_pool = state_dir.parent / "server_pools" / "schema5-v1"
            if canonical_pool.is_symlink():
                raise ImmutablePinError(
                    f"canonical schema-5 server pool cannot be a symlink: {canonical_pool}"
                )
            canonical_pool.mkdir(parents=True, exist_ok=True)
            pins = build_immutable_pins(
                state_dir=state_dir,
                release_bundle_root=args.release_bundle_root,
                hf_home=args.hf_home,
            )
            report = publish_immutable_pins(args.output, pins)
            print(json.dumps(report, indent=2, sort_keys=True))
            return 0
        if args.command == "init":
            pins = _load_json_object(
                args.pins_json.expanduser().resolve(), description="pins"
            )
            control = initialize_control(
                state_dir, pins=pins, alert_email=args.alert_email
            )
            print(
                json.dumps(
                    {"initialized": True, "control": control}, indent=2, sort_keys=True
                )
            )
            return 0
        if args.command == "reconcile":
            report = reconcile_control(
                state_dir,
                snapshot=_scheduler_for_cli(),
                all_jobs=args.all,
                no_admit=args.no_admit,
            )
            print(json.dumps(report, indent=2, sort_keys=True))
            return 0 if report["passed"] else 2
        if args.command == "resume":
            control = resume_control(state_dir)
            snapshot = _scheduler_for_cli()
            chains = repair_chains(state_dir, snapshot=snapshot)
            print(
                json.dumps(
                    {
                        "desired_state": control["desired_state"],
                        "rollout_generation": control["rollout_generation"],
                        "chains": chains,
                    },
                    indent=2,
                    sort_keys=True,
                )
            )
            return 0
        if args.command == "refresh-generation-catalog":
            catalog = refresh_trusted_generation_catalog(
                state_dir,
                target_rollout_generation=args.rollout_generation,
            )
            print(
                json.dumps(
                    {
                        "catalog_id": catalog.catalog_id,
                        "marker_path": str(catalog.marker_path),
                        "marker_sha256": catalog.marker_sha256,
                        "inventory_sha256": catalog.inventory_sha256,
                        "catalog_payload_sha256": catalog.catalog_sha256,
                        "allowed_generation_tuple_count": len(
                            catalog.allowed_generation_tuples
                        ),
                    },
                    indent=2,
                    sort_keys=True,
                )
            )
            return 0
        if args.command == "pause":
            control = pause_control(
                state_dir,
                drain=args.drain,
                scheduler_reader=lambda: _scheduler_for_cli(tolerate_errors=True),
            )
            print(
                json.dumps(
                    {
                        "desired_state": control["desired_state"],
                        "drain_requested": control["drain_requested"],
                    },
                    indent=2,
                    sort_keys=True,
                )
            )
            return 0
        if args.command == "watchdog-status":
            snapshot = _scheduler_for_cli(tolerate_errors=True)
            report = _watchdog_status_for_cli(
                state_dir, snapshot=snapshot
            )
            # The report bytes returned over SSH are exactly the bytes whose parsed
            # object is bound by this server-side observation receipt.
            record_external_watchdog_status_observation(
                state_dir, report=report
            )
            print(json.dumps(report, indent=2, sort_keys=True))
            return 0 if report["healthy"] else 1
        if args.command == "watchdog-observe":
            result = publish_external_watchdog_cycle(state_dir)
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0
        if args.command == "watchdog-repair-chain":
            pending = adopt_pending_external_watchdog_action(state_dir)
            if pending is not None:
                print(
                    json.dumps(
                        {
                            "requested_action": "repair-chain",
                            "executed": False,
                            "result": {
                                "deferred": True,
                                "reason": (
                                    "an exact prior action must be mirrored "
                                    "before another action"
                                ),
                            },
                            "watchdog_action_receipt": pending,
                        },
                        indent=2,
                        sort_keys=True,
                    )
                )
                return 0
            intent = begin_external_watchdog_action(
                state_dir, action="repair-chain"
            )
            result = _watchdog_repair_for_cli(
                state_dir, snapshot=_scheduler_for_cli()
            )
            receipt = complete_external_watchdog_action(
                state_dir, intent=intent, result=result
            )
            print(
                json.dumps(
                    {
                        "requested_action": "repair-chain",
                        "executed": True,
                        "result": result,
                        "watchdog_action_receipt": receipt,
                    },
                    indent=2,
                    sort_keys=True,
                )
            )
            return 0
        if args.command == "watchdog-finalizer-reconcile":
            pending = adopt_pending_external_watchdog_action(state_dir)
            if pending is not None:
                print(
                    json.dumps(
                        {
                            "requested_action": "finalizer-reconcile",
                            "executed": False,
                            "result": {
                                "deferred": True,
                                "reason": (
                                    "an exact prior action must be mirrored "
                                    "before another action"
                                ),
                            },
                            "watchdog_action_receipt": pending,
                        },
                        indent=2,
                        sort_keys=True,
                    )
                )
                return 0
            intent = begin_external_watchdog_action(
                state_dir, action="finalizer-reconcile"
            )
            drill = _load_external_watchdog_drill(state_dir)
            if (
                drill is not None
                and drill[1]["phase"] not in {"complete", "expired"}
            ):
                raise ControlError(
                    "finalizer reconciliation is fenced by the active "
                    "external-watchdog drill"
                )
            result = reconcile_autonomous_finalization(
                state_dir,
                snapshot=_scheduler_for_cli(tolerate_errors=False),
            )
            receipt = complete_external_watchdog_action(
                state_dir, intent=intent, result=result
            )
            print(
                json.dumps(
                    {
                        "requested_action": "finalizer-reconcile",
                        "executed": True,
                        "result": result,
                        "watchdog_action_receipt": receipt,
                    },
                    indent=2,
                    sort_keys=True,
                )
            )
            return 0
        if args.command == "status":
            snapshot = _scheduler_for_cli(tolerate_errors=True)
            drill = _load_external_watchdog_drill(state_dir)
            report = (
                external_watchdog_drill_status(
                    state_dir,
                    snapshot=snapshot,
                    record_observation=True,
                )
                if drill is not None
                and drill[1]["phase"] not in {"complete", "expired"}
                else live_status(state_dir, snapshot=snapshot)
            )
            print(json.dumps(report, indent=2, sort_keys=True))
            return 0 if report["healthy"] else 1
        if args.command == "repair-chain":
            snapshot = _scheduler_for_cli()
            drill = _load_external_watchdog_drill(state_dir)
            if (
                drill is not None
                and drill[1]["phase"] not in {"complete", "expired"}
            ):
                if args.dry_run:
                    result = {
                        "dry_run": True,
                        "desired_state": "paused",
                        "watchdog_drill": drill[1]["phase"],
                        "would_submit": list(ROLE_NAMES),
                        "intent_id": drill[0]["intent_id"],
                    }
                else:
                    result = repair_external_watchdog_drill(
                        state_dir, snapshot=snapshot
                    )
                print(json.dumps(result, indent=2, sort_keys=True))
                return 0
            control = load_control(state_dir, verify_files=True)
            provisional = build_reconciliation_report(
                control, snapshot, all_jobs=True, no_admit=True
            )
            if args.dry_run:
                result = {
                    "dry_run": True,
                    "would_submit": [
                        role
                        for role in ROLE_NAMES
                        if control["desired_state"] == "running"
                        and not _role_has_live_chain(control, role, snapshot)
                    ],
                    "reconciliation": provisional,
                }
            else:
                result = repair_chains(state_dir, snapshot=snapshot)
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0
        if args.command == "attest":
            control = attest_gate(
                state_dir,
                gate=args.gate,
                evidence_path=args.evidence,
                expected_sha256=args.sha256,
                chain_manifest=args.chain_manifest,
            )
            print(json.dumps(control["readiness"][args.gate], indent=2, sort_keys=True))
            return 0
        if args.command == "set-ceiling":
            control = set_admission_ceiling(state_dir, ceiling=args.value)
            print(json.dumps(control["admission"], indent=2, sort_keys=True))
            return 0
        if args.command == "ack-hold":
            control = acknowledge_admission_hold(state_dir, note=args.note)
            print(
                json.dumps(
                    control["admission_safety_hold"], indent=2, sort_keys=True
                )
            )
            return 0
        if args.command == "attest-client-capacity":
            control = attest_client_capacity_generation(
                state_dir,
                evidence_path=args.evidence,
                expected_sha256=args.sha256,
            )
            print(
                json.dumps(
                    {
                        "capacity_gate": control["admission_ramp"][
                            "capacity_gate"
                        ],
                        "authorization": control["admission_ramp"][
                            "client_capacity_authorizations"
                        ][-1],
                        "admission_safety_hold": control[
                            "admission_safety_hold"
                        ],
                    },
                    indent=2,
                    sort_keys=True,
                )
            )
            return 0
        if args.command == "build-client-capacity":
            result = build_client_capacity_generation(
                state_dir,
                action=args.action,
                partition=args.partition,
                target_ceiling=args.target_ceiling,
            )
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0
        if args.command == "capacity-transition":
            result = capacity_transition(
                state_dir,
                action=args.action,
                fleet_contract_path=args.fleet_contract,
                fleet_contract_sha256=args.fleet_contract_sha256,
                protected_capacity_marker_path=(
                    args.protected_capacity_marker
                ),
                protected_capacity_marker_sha256=(
                    args.protected_capacity_marker_sha256
                ),
                protected_capacity_marker_id=(
                    args.protected_capacity_marker_id
                ),
                static_feasibility_certificate_path=(
                    args.static_feasibility_certificate
                ),
                static_feasibility_certificate_sha256=(
                    args.static_feasibility_certificate_sha256
                ),
                static_feasibility_certificate_id=(
                    args.static_feasibility_certificate_id
                ),
                scheduler_reader=lambda: _scheduler_for_cli(
                    tolerate_errors=False
                ),
                resume_callback=(
                    (lambda path: resume_control(path))
                    if args.action == "complete"
                    else None
                ),
            )
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0
        if args.command == "finalize":
            result = finalize_sweep(
                state_dir,
                output_root=args.output_root,
                scheduler_reader=lambda: _scheduler_for_cli(
                    tolerate_errors=False
                ),
            )
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0
        if args.command == "finalizer-reconcile":
            drill = _load_external_watchdog_drill(state_dir)
            if (
                drill is not None
                and drill[1]["phase"] not in {"complete", "expired"}
            ):
                raise ControlError(
                    "finalizer reconciliation is fenced by the active "
                    "external-watchdog drill"
                )
            result = reconcile_autonomous_finalization(
                state_dir,
                snapshot=_scheduler_for_cli(tolerate_errors=False),
            )
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0
        if args.command == "finalizer-worker":
            return run_autonomous_finalizer_worker(
                state_dir,
                intent_id=args.intent_id,
                attempt=args.attempt,
            )
        if args.command == "record-poll":
            control = record_successful_poll(
                state_dir,
                useful_qids=args.useful_qids,
                fleet_generation=args.fleet_generation,
                strata_with_throughput=args.strata_with_throughput,
            )
            print(
                json.dumps(control["throughput_epochs"][-1], indent=2, sort_keys=True)
            )
            return 0
        if args.command == "drill":
            if args.action in {"kill", "wait"} and args.role is None:
                raise ControlError(f"drill {args.action} requires --role")
            if args.action == "status" and not args.live:
                raise ControlError("drill status requires --live")
            if args.action == "start":
                state = start_controller_drill(
                    state_dir, scheduler=_scheduler_for_cli()
                )
                result = {
                    "drill_id": state["drill_id"],
                    "phase": state["phase"],
                    "job_ids": {
                        role: state["roles"][role]["active"]["job_id"]
                        for role in ROLE_NAMES
                    },
                }
                print(json.dumps(result, indent=2, sort_keys=True))
                return 0
            if args.action == "status":
                result = controller_drill_status(
                    state_dir, snapshot=_scheduler_for_cli(tolerate_errors=True)
                )
                print(json.dumps(result, indent=2, sort_keys=True))
                return (
                    0
                    if result["healthy"]
                    and (result["ready_for_kill"] or result["completed"])
                    else 1
                )
            if args.action == "kill":
                result = kill_drill_controller(
                    state_dir, role=args.role, snapshot=_scheduler_for_cli()
                )
                print(json.dumps(result, indent=2, sort_keys=True))
                return 0
            if args.action == "wait":
                result = wait_for_drill_recovery(
                    state_dir, role=args.role, timeout_seconds=args.timeout
                )
                print(json.dumps(result, indent=2, sort_keys=True))
                return 0
            if args.action == "finish":
                result = finish_controller_drill(
                    state_dir, timeout_seconds=min(args.timeout, 900.0)
                )
                print(json.dumps(result, indent=2, sort_keys=True))
                return 0
            raise AssertionError(f"unhandled drill action {args.action}")
        if args.command == "watchdog-drill":
            snapshot = _scheduler_for_cli(tolerate_errors=False)
            if args.action == "arm":
                if args.deployment_evidence is None:
                    raise ControlError(
                        "watchdog-drill arm requires --deployment-evidence"
                    )
                result = arm_external_watchdog_drill(
                    state_dir,
                    snapshot=snapshot,
                    deployment_evidence_path=args.deployment_evidence,
                    expires_seconds=args.expires_seconds,
                )
            elif args.action == "cancel":
                result = cancel_external_watchdog_drill_namespace(
                    state_dir, snapshot=snapshot
                )
            elif args.action == "status":
                result = external_watchdog_drill_status(
                    state_dir,
                    snapshot=snapshot,
                    record_observation=False,
                )
            elif args.action == "finish":
                if args.output is None:
                    raise ControlError(
                        "watchdog-drill finish requires --output"
                    )
                result = complete_external_watchdog_drill(
                    state_dir,
                    snapshot=snapshot,
                    output_path=args.output,
                )
            else:  # pragma: no cover
                raise AssertionError(args.action)
            print(json.dumps(result, indent=2, sort_keys=True))
            return 0
        if args.command == "supervise":
            return supervise(
                state_dir,
                role=args.role,
                generation=args.generation,
                intent_token=args.intent_token,
                heartbeat_interval=args.heartbeat_interval,
                stale_seconds=args.stale_seconds,
                drain_grace_seconds=args.drain_grace_seconds,
            )
        if args.command == "supervise-drill":
            return supervise_drill(
                state_dir,
                drill_id=args.drill_id,
                role=args.role,
                generation=args.generation,
                intent_token=args.intent_token,
                heartbeat_interval=args.heartbeat_interval,
            )
        raise AssertionError(f"unhandled command {args.command}")
    except (ControlError, OSError) as exc:
        print(f"[schema5-control] ERROR: {exc}", file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())
